    dynamic_cells: set[CellKey]
    dynamic_ranges: tuple[ArrayFormulaRange, ...]
    unclassified_cells: set[CellKey]
    metadata_complete: bool
    metadata_coverage_signature: str | None
    warnings: tuple[str, ...]


