def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as file_handle:
        for block in iter(lambda: file_handle.read(1_048_576), b""):
            digest.update(block)
    return digest.hexdigest()


def _archive_preflight_error(detail: str) -> WorkbookLoadError:
    """Build a controlled error without echoing hostile ZIP metadata."""
    return WorkbookLoadError(
        "Workbook archive failed FormulaFence safety preflight: " f"{detail}"
    )


def _read_archive_segment(file_handle, offset: int, size: int) -> bytes:
    """Read one bounded ZIP region, rejecting truncation before any parser sees it."""
    file_handle.seek(offset)
    payload = file_handle.read(size)
    if len(payload) != size:
        raise _archive_preflight_error("archive metadata is truncated.")
    return payload


def _ooxml_archive_end_of_central_directory(
    tail: bytes,
    tail_offset: int,
) -> tuple[tuple[object, ...], int]:
    """Find one unambiguous ZIP end record in the bounded archive tail."""
    candidates: list[tuple[tuple[object, ...], int]] = []
    search_end = len(tail)
    while True:
        offset = tail.rfind(_ZIP_END_OF_CENTRAL_DIRECTORY_SIGNATURE, 0, search_end)
        if offset < 0:
            break
        if offset + _ZIP_END_OF_CENTRAL_DIRECTORY.size <= len(tail):
            record = _ZIP_END_OF_CENTRAL_DIRECTORY.unpack_from(tail, offset)
            comment_size = record[-1]
            if offset + _ZIP_END_OF_CENTRAL_DIRECTORY.size + comment_size == len(tail):
                candidates.append((record, tail_offset + offset))
        search_end = offset

    if not candidates:
        raise _archive_preflight_error("ZIP end-of-central-directory record is missing.")
    if len(candidates) > 1:
        raise _archive_preflight_error("ZIP end-of-central-directory record is ambiguous.")
    return candidates[0]


def _zip64_member_values(
    extra: bytes,
    *,
    uncompressed_size: int,
    compressed_size: int,
    local_header_offset: int,
    disk_start: int,
) -> tuple[int, int, int, int]:
    """Resolve ZIP64 central-directory values after validating extra-field framing."""
    zip64_payload: bytes | None = None
    cursor = 0
    while cursor < len(extra):
        if len(extra) - cursor < 4:
            raise _archive_preflight_error("ZIP member extra metadata is malformed.")
        field_id, field_size = struct.unpack_from("<HH", extra, cursor)
        cursor += 4
        if field_size > len(extra) - cursor:
            raise _archive_preflight_error("ZIP member extra metadata is malformed.")
        if field_id == 0x0001:
            if zip64_payload is not None:
                raise _archive_preflight_error("ZIP member ZIP64 metadata is ambiguous.")
            zip64_payload = extra[cursor : cursor + field_size]
        elif field_id == 0x7075:
            # ``zipfile`` can use this Info-ZIP field to replace the decoded
            # central-directory name after a caller has already indexed it.
            # OOXML part names must have one canonical spelling, so reject the
            # alias rather than letting downstream readers see a different key.
            raise _archive_preflight_error("ZIP Unicode-path aliases are unsupported.")
        cursor += field_size

    needs_zip64 = (
        uncompressed_size == _ZIP64_UINT32_SENTINEL
        or compressed_size == _ZIP64_UINT32_SENTINEL
        or local_header_offset == _ZIP64_UINT32_SENTINEL
        or disk_start == _ZIP64_UINT16_SENTINEL
    )
    if not needs_zip64:
        return (
            uncompressed_size,
            compressed_size,
            local_header_offset,
            disk_start,
        )
    if zip64_payload is None:
        raise _archive_preflight_error("ZIP64 member metadata is incomplete.")

    payload_cursor = 0

    def take_value(size: int) -> int:
        nonlocal payload_cursor
        if len(zip64_payload) - payload_cursor < size:
            raise _archive_preflight_error("ZIP64 member metadata is incomplete.")
        value = int.from_bytes(
            zip64_payload[payload_cursor : payload_cursor + size],
            "little",
        )
        payload_cursor += size
        return value

    if uncompressed_size == _ZIP64_UINT32_SENTINEL:
        uncompressed_size = take_value(8)
    if compressed_size == _ZIP64_UINT32_SENTINEL:
        compressed_size = take_value(8)
    if local_header_offset == _ZIP64_UINT32_SENTINEL:
        local_header_offset = take_value(8)
    if disk_start == _ZIP64_UINT16_SENTINEL:
        disk_start = take_value(4)
    return uncompressed_size, compressed_size, local_header_offset, disk_start


def _is_safe_ooxml_archive_member_name(member: str) -> bool:
    """Return whether a decoded ZIP member is one canonical relative OPC path."""
    if not member or member.startswith("/") or "\\" in member:
        return False
    if any(ord(character) < 32 or ord(character) == 127 for character in member):
        return False
    try:
        encoded_member = member.encode("utf-8")
    except UnicodeEncodeError:
        return False
    if len(encoded_member) > _OOXML_ARCHIVE_MAX_MEMBER_NAME_BYTES:
        return False

    is_directory = member.endswith("/")
    normalised = posixpath.normpath(member)
    expected = f"{normalised}/" if is_directory else normalised
    if member != expected or normalised in {"", ".", ".."}:
        return False
    components = normalised.split("/")
    return all(component not in {"", ".", ".."} for component in components)


def _ooxml_archive_directory_values(
    file_handle,
    source_size: int,
    end_record: tuple[object, ...],
    end_offset: int,
) -> tuple[int, int, int]:
    """Read bounded central-directory coordinates without constructing ``ZipFile``."""
    (
        _,
        disk_number,
        central_directory_disk,
        entries_on_disk,
        entry_count,
        central_directory_size,
        central_directory_offset,
        _,
    ) = end_record
    zip64_record_offset: int | None = None
    locator_offset = end_offset - _ZIP64_END_OF_CENTRAL_DIRECTORY_LOCATOR.size
    if locator_offset >= 0:
        locator = _read_archive_segment(
            file_handle,
            locator_offset,
            _ZIP64_END_OF_CENTRAL_DIRECTORY_LOCATOR.size,
        )
        (
            locator_signature,
            zip64_disk,
            declared_zip64_record_offset,
            zip64_disk_count,
        ) = _ZIP64_END_OF_CENTRAL_DIRECTORY_LOCATOR.unpack(locator)
        if locator_signature == _ZIP64_END_OF_CENTRAL_DIRECTORY_LOCATOR_SIGNATURE:
            if zip64_disk != 0 or zip64_disk_count != 1:
                raise _archive_preflight_error("multi-disk ZIP packages are unsupported.")
            zip64_record_offset = declared_zip64_record_offset
            if (
                zip64_record_offset + _ZIP64_END_OF_CENTRAL_DIRECTORY.size
                > locator_offset
            ):
                raise _archive_preflight_error("ZIP64 end metadata is malformed.")
            zip64_record = _read_archive_segment(
                file_handle,
                zip64_record_offset,
                _ZIP64_END_OF_CENTRAL_DIRECTORY.size,
            )
            (
                zip64_signature,
                zip64_record_size,
                _,
                _,
                disk_number,
                central_directory_disk,
                entries_on_disk,
                entry_count,
                central_directory_size,
                central_directory_offset,
            ) = _ZIP64_END_OF_CENTRAL_DIRECTORY.unpack(zip64_record)
            if zip64_signature != _ZIP64_END_OF_CENTRAL_DIRECTORY_SIGNATURE:
                raise _archive_preflight_error("ZIP64 end metadata is malformed.")
            if zip64_record_size < 44 or (
                zip64_record_offset + 12 + zip64_record_size > locator_offset
            ):
                raise _archive_preflight_error("ZIP64 end metadata is malformed.")
    if zip64_record_offset is None and (
        entries_on_disk == _ZIP64_UINT16_SENTINEL
        or entry_count == _ZIP64_UINT16_SENTINEL
        or central_directory_size == _ZIP64_UINT32_SENTINEL
        or central_directory_offset == _ZIP64_UINT32_SENTINEL
    ):
        raise _archive_preflight_error("ZIP64 end metadata is incomplete.")
    if disk_number != 0 or central_directory_disk != 0:
        raise _archive_preflight_error("multi-disk ZIP packages are unsupported.")
    if entries_on_disk != entry_count:
        raise _archive_preflight_error("ZIP entry counts are inconsistent.")
    if entry_count > _OOXML_ARCHIVE_MAX_ENTRY_COUNT:
        raise _archive_preflight_error(
            "entry count exceeds the supported safety limit."
        )
    if central_directory_size > _OOXML_ARCHIVE_MAX_CENTRAL_DIRECTORY_BYTES:
        raise _archive_preflight_error(
            "central-directory size exceeds the supported safety limit."
        )

    central_directory_end = (
        zip64_record_offset if zip64_record_offset is not None else end_offset
    )
    if (
        central_directory_offset + central_directory_size > central_directory_end
        or central_directory_end > source_size
    ):
        raise _archive_preflight_error("central-directory coordinates are invalid.")
    return entry_count, central_directory_size, central_directory_offset


def _ooxml_archive_members(
    central_directory: bytes,
    declared_entry_count: int,
) -> tuple[_OoxmlArchiveMember, ...]:
    """Validate central-directory records before a general ZIP reader allocates them."""
    cursor = 0
    entry_count = 0
    total_uncompressed_size = 0
    exact_names: set[str] = set()
    casefolded_names: set[str] = set()
    local_header_offsets: set[int] = set()
    members: list[_OoxmlArchiveMember] = []
    while cursor < len(central_directory):
        if len(central_directory) - cursor < _ZIP_CENTRAL_DIRECTORY_HEADER.size:
            raise _archive_preflight_error("central-directory metadata is truncated.")
        (
            signature,
            _,
            _,
            _,
            _,
            flag_bits,
            compression_method,
            _,
            _,
            _,
            compressed_size,
            uncompressed_size,
            filename_size,
            extra_size,
            comment_size,
            disk_start,
            _,
            external_attributes,
            local_header_offset,
        ) = _ZIP_CENTRAL_DIRECTORY_HEADER.unpack_from(central_directory, cursor)
        if signature != _ZIP_CENTRAL_DIRECTORY_HEADER_SIGNATURE:
            raise _archive_preflight_error("central-directory metadata is malformed.")
        record_size = (
            _ZIP_CENTRAL_DIRECTORY_HEADER.size
            + filename_size
            + extra_size
            + comment_size
        )
        if record_size > len(central_directory) - cursor:
            raise _archive_preflight_error("central-directory metadata is truncated.")
        entry_count += 1
        if entry_count > _OOXML_ARCHIVE_MAX_ENTRY_COUNT:
            raise _archive_preflight_error(
                "entry count exceeds the supported safety limit."
            )
        if filename_size > _OOXML_ARCHIVE_MAX_MEMBER_NAME_BYTES:
            raise _archive_preflight_error("a member name exceeds the supported safety limit.")
        filename_start = cursor + _ZIP_CENTRAL_DIRECTORY_HEADER.size
        filename_payload = central_directory[
            filename_start : filename_start + filename_size
        ]
        extra_start = filename_start + filename_size
        extra = central_directory[extra_start : extra_start + extra_size]
        try:
            member_name = filename_payload.decode(
                "utf-8" if flag_bits & 0x800 else "cp437"
            )
        except UnicodeDecodeError as error:
            raise _archive_preflight_error("a member name is not valid ZIP text.") from error
        if not _is_safe_ooxml_archive_member_name(member_name):
            raise _archive_preflight_error("a member path is unsafe or non-canonical.")
        if member_name in exact_names or member_name.casefold() in casefolded_names:
            raise _archive_preflight_error("member paths are ambiguous.")
        exact_names.add(member_name)
        casefolded_names.add(member_name.casefold())
        if flag_bits & 0x1:
            raise _archive_preflight_error("encrypted members are unsupported.")
        if compression_method not in _OOXML_ARCHIVE_ALLOWED_COMPRESSION_METHODS:
            raise _archive_preflight_error("a member uses an unsupported compression method.")

        (
            uncompressed_size,
            compressed_size,
            local_header_offset,
            disk_start,
        ) = _zip64_member_values(
            extra,
            uncompressed_size=uncompressed_size,
            compressed_size=compressed_size,
            local_header_offset=local_header_offset,
            disk_start=disk_start,
        )
        if disk_start != 0:
            raise _archive_preflight_error("multi-disk ZIP packages are unsupported.")
        member_mode = stat.S_IFMT(external_attributes >> 16)
        if stat.S_ISLNK(external_attributes >> 16):
            raise _archive_preflight_error("symbolic-link members are unsupported.")
        if member_mode not in {0, stat.S_IFREG, stat.S_IFDIR}:
            raise _archive_preflight_error("a member has an unsupported special file type.")
        if member_name.endswith("/") and (compressed_size or uncompressed_size):
            raise _archive_preflight_error("a directory member contains payload data.")
        if compression_method == ZIP_STORED and compressed_size != uncompressed_size:
            raise _archive_preflight_error("stored member sizes are inconsistent.")
        if uncompressed_size > _OOXML_ARCHIVE_MAX_MEMBER_UNCOMPRESSED_BYTES:
            raise _archive_preflight_error(
                "a member exceeds the supported uncompressed-size limit."
            )
        total_uncompressed_size += uncompressed_size
        if total_uncompressed_size > _OOXML_ARCHIVE_MAX_TOTAL_UNCOMPRESSED_BYTES:
            raise _archive_preflight_error(
                "aggregate uncompressed size exceeds the supported safety limit."
            )
        if uncompressed_size and (
            not compressed_size
            or uncompressed_size
            > compressed_size * _OOXML_ARCHIVE_MAX_COMPRESSION_RATIO
        ):
            raise _archive_preflight_error("a member exceeds the compression-ratio limit.")
        if local_header_offset in local_header_offsets:
            raise _archive_preflight_error("local member headers are ambiguous.")
        local_header_offsets.add(local_header_offset)
        members.append(
            _OoxmlArchiveMember(
                name=member_name,
                compressed_size=compressed_size,
                uncompressed_size=uncompressed_size,
                local_header_offset=local_header_offset,
                flag_bits=flag_bits,
                compression_method=compression_method,
            )
        )
        cursor += record_size

    if entry_count != declared_entry_count:
        raise _archive_preflight_error("central-directory entry counts are inconsistent.")
    if not members:
        raise _archive_preflight_error("the archive contains no workbook parts.")
    return tuple(members)


def _validate_ooxml_archive_local_headers(
    file_handle,
    central_directory_offset: int,
    members: tuple[_OoxmlArchiveMember, ...],
) -> None:
    """Ensure each bounded central record points to its own safe local header."""
    member_ends: list[tuple[int, int]] = []
    for member in members:
        if member.local_header_offset >= central_directory_offset:
            raise _archive_preflight_error("a local member header is outside package data.")
        local_header = _read_archive_segment(
            file_handle,
            member.local_header_offset,
            _ZIP_LOCAL_FILE_HEADER.size,
        )
        (
            signature,
            _,
            _,
            local_flag_bits,
            local_compression_method,
            _,
            _,
            _,
            _,
            _,
            filename_size,
            extra_size,
        ) = _ZIP_LOCAL_FILE_HEADER.unpack(local_header)
        if signature != _ZIP_LOCAL_FILE_HEADER_SIGNATURE:
            raise _archive_preflight_error("a local member header is malformed.")
        if (
            local_flag_bits != member.flag_bits
            or local_compression_method != member.compression_method
        ):
            raise _archive_preflight_error("local member metadata is inconsistent.")
        if filename_size > _OOXML_ARCHIVE_MAX_MEMBER_NAME_BYTES:
            raise _archive_preflight_error("a local member name exceeds the supported limit.")
        variable_start = member.local_header_offset + _ZIP_LOCAL_FILE_HEADER.size
        variable_size = filename_size + extra_size
        data_start = variable_start + variable_size
        data_end = data_start + member.compressed_size
        if data_end > central_directory_offset:
            raise _archive_preflight_error("a member payload overlaps package metadata.")
        local_filename_payload = _read_archive_segment(
            file_handle,
            variable_start,
            filename_size,
        )
        try:
            local_name = local_filename_payload.decode(
                "utf-8" if local_flag_bits & 0x800 else "cp437"
            )
        except UnicodeDecodeError as error:
            raise _archive_preflight_error("a local member name is not valid ZIP text.") from error
        if local_name != member.name:
            raise _archive_preflight_error("local and central member paths are inconsistent.")
        member_ends.append((member.local_header_offset, data_end))

    ordered_member_ends = sorted(member_ends)
    for (_, data_end), (next_offset, _) in zip(
        ordered_member_ends,
        ordered_member_ends[1:],
        strict=False,
    ):
        if data_end > next_offset:
            raise _archive_preflight_error("member payloads overlap.")


def _validate_ooxml_archive(path: Path) -> tuple[_OoxmlArchiveMember, ...]:
    """Fail closed on unsafe ZIP container structure before OOXML inspection."""
    try:
        with path.open("rb") as file_handle:
            source_size = os.fstat(file_handle.fileno()).st_size
            if source_size > _OOXML_ARCHIVE_MAX_SOURCE_BYTES:
                raise _archive_preflight_error(
                    "source size exceeds the supported safety limit."
                )
            if source_size < _ZIP_LOCAL_FILE_HEADER.size:
                raise _archive_preflight_error("archive is too small to be an OOXML package.")
            if (
                _read_archive_segment(file_handle, 0, 4)
                != _ZIP_LOCAL_FILE_HEADER_SIGNATURE
            ):
                raise _archive_preflight_error("archive does not begin with a ZIP member.")

            tail_size = min(
                source_size,
                _ZIP_MAX_COMMENT_BYTES + _ZIP_END_OF_CENTRAL_DIRECTORY.size,
            )
            tail_offset = source_size - tail_size
            end_record, end_offset = _ooxml_archive_end_of_central_directory(
                _read_archive_segment(file_handle, tail_offset, tail_size),
                tail_offset,
            )
            (
                declared_entry_count,
                central_directory_size,
                central_directory_offset,
            ) = _ooxml_archive_directory_values(
                file_handle,
                source_size,
                end_record,
                end_offset,
            )
            central_directory = _read_archive_segment(
                file_handle,
                central_directory_offset,
                central_directory_size,
            )
            members = _ooxml_archive_members(central_directory, declared_entry_count)
            _validate_ooxml_archive_local_headers(
                file_handle,
                central_directory_offset,
                members,
            )
    except WorkbookLoadError:
        raise
    except (OSError, UnicodeError, struct.error, ValueError) as error:
        raise _archive_preflight_error("ZIP metadata could not be read safely.") from error
    return members


def _reader_preflight_error(detail: str) -> WorkbookLoadError:
    """Return one stable, non-disclosing semantic-reader safety error."""
    return WorkbookLoadError(
        "Workbook semantic reader failed FormulaFence safety preflight: " f"{detail}"
    )


def _is_ooxml_xml_member(member: _OoxmlArchiveMember) -> bool:
    """Identify package parts that a reader can hand to an XML parser."""
    return member.name.casefold().endswith((".xml", ".rels"))


def _spreadsheetml_tags(*local_names: str) -> frozenset[str]:
    """Build tags for the transitional and Strict SpreadsheetML namespaces."""
    return frozenset(
        f"{{{namespace}}}{local_name}"
        for namespace in (_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS)
        for local_name in local_names
    )


class _OoxmlXmlCharacterDataLimitError(ValueError):
    """Signal a text node that would make the XML tree builder retain too much."""


class _BoundedOoxmlXmlTreeBuilder(_ElementTreeBuilder):
    """Stop one XML character-data node before the tree builder joins its chunks."""

    def __init__(
        self,
        maximum_character_data_characters: int | None = None,
    ) -> None:
        super().__init__()
        self._maximum_character_data_characters = (
            _OOXML_READER_MAX_XML_CHARACTER_DATA_CHARACTERS
            if maximum_character_data_characters is None
            else maximum_character_data_characters
        )
        self._current_character_data_characters = 0

    def start(self, tag, attributes):
        self._current_character_data_characters = 0
        return super().start(tag, attributes)

    def data(self, data):
        self._current_character_data_characters += len(data)
        if (
            self._current_character_data_characters
            > self._maximum_character_data_characters
        ):
            raise _OoxmlXmlCharacterDataLimitError
        return super().data(data)

    def end(self, tag):
        element = super().end(tag)
        self._current_character_data_characters = 0
        return element


def _ooxml_xml_parser_with_character_data_budget():
    """Build the defused parser with incremental character-data protection."""
    return ElementTree.XMLParser(
        target=_BoundedOoxmlXmlTreeBuilder(),
        forbid_dtd=True,
    )


def _iterparse_ooxml_xml_with_character_data_budget(xml_stream):
    """Iterate XML events without letting one text node grow unbounded."""
    return ElementTree.iterparse(
        xml_stream,
        events=("start", "end"),
        parser=_ooxml_xml_parser_with_character_data_budget(),
    )


def _iterparse_ooxml_reader_xml(xml_stream):
    """Yield reader XML events while turning a text overage into a stable error."""
    try:
        yield from _iterparse_ooxml_xml_with_character_data_budget(xml_stream)
    except _OoxmlXmlCharacterDataLimitError as error:
        raise _reader_preflight_error(
            "XML character data exceeds the semantic-reader safety limit."
        ) from error


def _xml_ascii_lexical_markup_budget_violation(
    xml_stream,
    initial: bytes,
    initial_offset: int,
    *,
    maximum_start_tag_bytes: int,
    maximum_markup_bytes: int,
) -> str | None:
    """Return an ASCII-compatible XML lexical allocation-boundary violation.

    Most OOXML uses UTF-8. Search its delimiter bytes in C and visit only the
    handful of punctuation marks that can change lexical state; a Python
    character-by-character pass would materially slow a large, ordinary
    worksheet before any reader starts.
    """
    state = "text"
    opening_offset = 0
    quote: int | None = None
    declaration_quote: int | None = None
    declaration_bracket_depth = 0
    bang_prefix = b""
    processing_question = False
    comment_tail = b""
    cdata_tail = b""
    data = initial
    data_offset = initial_offset

    while True:
        position = 0
        data_length = len(data)
        while position < data_length:
            if state == "text":
                match = _OOXML_READER_XML_TEXT_MARKER_PATTERN.search(data, position)
                if match is None:
                    position = data_length
                    break
                marker = match.start()
                opening_offset = data_offset + marker
                state = "opening" if data[marker] == ord("<") else "entity"
                position = marker + 1
                continue

            if state == "opening":
                marker = data[position]
                position += 1
                markup_byte_count = data_offset + position - opening_offset
                if marker == ord("?"):
                    if markup_byte_count > maximum_markup_bytes:
                        return "markup"
                    state = "processing-instruction"
                    processing_question = False
                elif marker == ord("!"):
                    if markup_byte_count > maximum_markup_bytes:
                        return "markup"
                    state = "bang"
                    bang_prefix = b""
                elif marker == ord("/"):
                    if markup_byte_count > maximum_markup_bytes:
                        return "markup"
                    state = "closing"
                else:
                    state = "start"
                    if markup_byte_count > maximum_start_tag_bytes:
                        return "start-tag"
                    if markup_byte_count > maximum_markup_bytes:
                        return "markup"
                continue

            if state == "start":
                maximum_token_bytes = min(
                    maximum_start_tag_bytes,
                    maximum_markup_bytes,
                )
                limit_violation = (
                    "start-tag"
                    if maximum_start_tag_bytes <= maximum_markup_bytes
                    else "markup"
                )
                allowed_end = min(
                    data_length,
                    opening_offset + maximum_token_bytes - data_offset,
                )
                if allowed_end <= position:
                    return limit_violation
                if quote is not None:
                    quote_marker = b'"' if quote == ord('"') else b"'"
                    marker = data.find(quote_marker, position, allowed_end)
                    if marker < 0:
                        if allowed_end < data_length:
                            return limit_violation
                        position = data_length
                        break
                    quote = None
                    position = marker + 1
                    continue
                match = _OOXML_READER_XML_START_TAG_DELIMITER_PATTERN.search(
                    data,
                    position,
                    allowed_end,
                )
                if match is None:
                    if allowed_end < data_length:
                        return limit_violation
                    position = data_length
                    break
                marker = match.start()
                character = data[marker]
                position = marker + 1
                if character == ord(">"):
                    state = "text"
                else:
                    quote = character
                continue

            if state == "closing":
                allowed_end = min(
                    data_length,
                    opening_offset + maximum_markup_bytes - data_offset,
                )
                if allowed_end <= position:
                    return "markup"
                marker = data.find(b">", position, allowed_end)
                if marker < 0:
                    if allowed_end < data_length:
                        return "markup"
                    position = data_length
                    break
                state = "text"
                position = marker + 1
                continue

            if state == "processing-instruction":
                if processing_question and data[position : position + 1] == b">":
                    if data_offset + position + 1 - opening_offset > maximum_markup_bytes:
                        return "markup"
                    processing_question = False
                    state = "text"
                    position += 1
                    continue
                processing_question = False
                allowed_end = min(
                    data_length,
                    opening_offset + maximum_markup_bytes - data_offset,
                )
                if allowed_end <= position:
                    return "markup"
                marker = data.find(b"?>", position, allowed_end)
                if marker < 0:
                    if allowed_end < data_length:
                        return "markup"
                    processing_question = data[position:].endswith(b"?")
                    position = data_length
                    break
                state = "text"
                position = marker + 2
                continue

            if state == "comment":
                if comment_tail == b"--" and data[position : position + 1] == b">":
                    if data_offset + position + 1 - opening_offset > maximum_markup_bytes:
                        return "markup"
                    comment_tail = b""
                    state = "text"
                    position += 1
                    continue
                if comment_tail.endswith(b"-") and data[
                    position : position + 2
                ] == b"->":
                    if data_offset + position + 2 - opening_offset > maximum_markup_bytes:
                        return "markup"
                    comment_tail = b""
                    state = "text"
                    position += 2
                    continue
                allowed_end = min(
                    data_length,
                    opening_offset + maximum_markup_bytes - data_offset,
                )
                if allowed_end <= position:
                    return "markup"
                marker = data.find(b"-->", position, allowed_end)
                if marker < 0:
                    if allowed_end < data_length:
                        return "markup"
                    comment_tail = (comment_tail + data[position:])[-2:]
                    position = data_length
                    break
                comment_tail = b""
                state = "text"
                position = marker + 3
                continue

            if state == "cdata":
                if cdata_tail == b"]]" and data[position : position + 1] == b">":
                    cdata_tail = b""
                    state = "text"
                    position += 1
                    continue
                if cdata_tail.endswith(b"]") and data[position : position + 2] == b"]>":
                    cdata_tail = b""
                    state = "text"
                    position += 2
                    continue
                marker = data.find(b"]]>", position)
                if marker < 0:
                    cdata_tail = (cdata_tail + data[position:])[-2:]
                    position = data_length
                    break
                cdata_tail = b""
                state = "text"
                position = marker + 3
                continue

            if state == "bang":
                bang_prefix += data[position : position + 1]
                position += 1
                if data_offset + position - opening_offset > maximum_markup_bytes:
                    return "markup"
                if bang_prefix == b"--":
                    state = "comment"
                    comment_tail = bang_prefix
                    continue
                if bang_prefix == b"[CDATA[":
                    state = "cdata"
                    cdata_tail = bang_prefix[-2:]
                    continue
                if b"--".startswith(bang_prefix) or b"[CDATA[".startswith(
                    bang_prefix
                ):
                    continue
                state = "declaration"
                declaration_quote = None
                declaration_bracket_depth = 0
                for character in bang_prefix:
                    if character in {ord('"'), ord("'")}:
                        declaration_quote = character
                    elif character == ord("["):
                        declaration_bracket_depth += 1
                    elif character == ord("]") and declaration_bracket_depth:
                        declaration_bracket_depth -= 1
                    elif character == ord(">") and not declaration_bracket_depth:
                        state = "text"
                        break
                continue

            if state == "entity":
                allowed_end = min(
                    data_length,
                    opening_offset + maximum_markup_bytes - data_offset,
                )
                if allowed_end <= position:
                    return "markup"
                marker = data.find(b";", position, allowed_end)
                if marker < 0:
                    if allowed_end < data_length:
                        return "markup"
                    position = data_length
                    break
                state = "text"
                position = marker + 1
                continue

            if declaration_quote is not None:
                quote_marker = b'"' if declaration_quote == ord('"') else b"'"
                allowed_end = min(
                    data_length,
                    opening_offset + maximum_markup_bytes - data_offset,
                )
                if allowed_end <= position:
                    return "markup"
                marker = data.find(quote_marker, position, allowed_end)
                if marker < 0:
                    if allowed_end < data_length:
                        return "markup"
                    position = data_length
                    break
                declaration_quote = None
                position = marker + 1
                continue
            match = _OOXML_READER_XML_DECLARATION_DELIMITER_PATTERN.search(
                data,
                position,
                min(
                    data_length,
                    opening_offset + maximum_markup_bytes - data_offset,
                ),
            )
            if match is None:
                if opening_offset + maximum_markup_bytes - data_offset < data_length:
                    return "markup"
                position = data_length
                break
            marker = match.start()
            character = data[marker]
            position = marker + 1
            if character in {ord('"'), ord("'")}:
                declaration_quote = character
            elif character == ord("["):
                declaration_bracket_depth += 1
            elif character == ord("]") and declaration_bracket_depth:
                declaration_bracket_depth -= 1
            elif character == ord(">") and not declaration_bracket_depth:
                state = "text"

        data_offset += data_length
        data = xml_stream.read(_OOXML_READER_XML_LEXICAL_CHUNK_BYTES)
        if not data:
            return None


def _xml_lexical_markup_budget_violation(
    xml_stream,
    *,
    maximum_start_tag_bytes: int | None = None,
    maximum_markup_bytes: int | None = None,
) -> str | None:
    """Return the XML parser-frontier lexical allocation-boundary violation.

    The scanner only needs XML punctuation, so it decodes fixed-width UTF-16
    and UTF-32 code units when an OOXML part uses either encoding. UTF-8 and
    ASCII-compatible encodings retain their byte-oriented punctuation. It
    bounds start tags plus other parser-token markup without treating CDATA as
    markup: its content is constrained by the incremental character-data target.
    """
    if maximum_start_tag_bytes is None:
        maximum_start_tag_bytes = _OOXML_READER_MAX_XML_START_TAG_BYTES
    if maximum_markup_bytes is None:
        maximum_markup_bytes = _OOXML_READER_MAX_XML_NON_CHARACTER_DATA_MARKUP_BYTES
    prefix = xml_stream.read(4)
    unit_width = 1
    byte_order = "big"
    prefix_skip = 0
    if prefix.startswith(b"\x00\x00\xfe\xff"):
        unit_width = 4
        prefix_skip = 4
    elif prefix.startswith(b"\xff\xfe\x00\x00"):
        unit_width = 4
        byte_order = "little"
        prefix_skip = 4
    elif prefix.startswith(b"\xfe\xff"):
        unit_width = 2
        prefix_skip = 2
    elif prefix.startswith(b"\xff\xfe"):
        unit_width = 2
        byte_order = "little"
        prefix_skip = 2
    elif len(prefix) == 4 and prefix[:3] == b"\x00\x00\x00":
        unit_width = 4
    elif len(prefix) == 4 and prefix[1:] == b"\x00\x00\x00":
        unit_width = 4
        byte_order = "little"
    elif len(prefix) == 4 and prefix[0] == 0 and prefix[2] == 0:
        unit_width = 2
    elif len(prefix) == 4 and prefix[1] == 0 and prefix[3] == 0:
        unit_width = 2
        byte_order = "little"
    elif prefix.startswith(b"\xef\xbb\xbf"):
        prefix_skip = 3

    if unit_width == 1:
        return _xml_ascii_lexical_markup_budget_violation(
            xml_stream,
            prefix[prefix_skip:],
            prefix_skip,
            maximum_start_tag_bytes=maximum_start_tag_bytes,
            maximum_markup_bytes=maximum_markup_bytes,
        )

    text_state = "text"
    state = text_state
    opening_byte_size = 0
    start_tag_byte_count = 0
    markup_byte_count = 0
    quote: int | None = None
    declaration_quote: int | None = None
    declaration_bracket_depth = 0
    bang_prefix: list[int] = []
    delimiter_tail: tuple[int, ...] = ()
    violation: str | None = None

    def consume_declaration_character(character: int) -> None:
        nonlocal declaration_bracket_depth, declaration_quote, state
        if declaration_quote is not None:
            if character == declaration_quote:
                declaration_quote = None
            return
        if character in {ord('"'), ord("'")}:
            declaration_quote = character
        elif character == ord("["):
            declaration_bracket_depth += 1
        elif character == ord("]") and declaration_bracket_depth:
            declaration_bracket_depth -= 1
        elif character == ord(">") and not declaration_bracket_depth:
            state = text_state

    def consume_character(character: int, byte_size: int) -> bool:
        nonlocal bang_prefix, declaration_bracket_depth, declaration_quote
        nonlocal delimiter_tail, markup_byte_count, opening_byte_size, quote
        nonlocal start_tag_byte_count, state, violation
        if state == text_state:
            markup_byte_count = 0
            if character == ord("<"):
                state = "opening"
                opening_byte_size = byte_size
                markup_byte_count = byte_size
            elif character == ord("&"):
                state = "entity"
                markup_byte_count = byte_size
            if markup_byte_count > maximum_markup_bytes:
                violation = "markup"
                return False
            return True

        if state == "cdata":
            delimiter_tail = (*delimiter_tail[-2:], character)
            if delimiter_tail == (ord("]"), ord("]"), ord(">")):
                state = text_state
            return True

        markup_byte_count += byte_size
        if (
            markup_byte_count > maximum_markup_bytes
            and state not in {"opening", "start"}
        ):
            violation = "markup"
            return False

        if state == "opening":
            if character == ord("?"):
                state = "processing-instruction"
                delimiter_tail = (character,)
            elif character == ord("!"):
                state = "bang"
                bang_prefix = []
            elif character == ord("/"):
                state = "closing"
            else:
                state = "start"
                quote = character if character in {ord('"'), ord("'")} else None
                start_tag_byte_count = opening_byte_size + byte_size
                if start_tag_byte_count > maximum_start_tag_bytes:
                    violation = "start-tag"
                    return False
                if markup_byte_count > maximum_markup_bytes:
                    violation = "markup"
                    return False
            return True

        if state == "start":
            start_tag_byte_count += byte_size
            if start_tag_byte_count > maximum_start_tag_bytes:
                violation = "start-tag"
                return False
            if markup_byte_count > maximum_markup_bytes:
                violation = "markup"
                return False
            if quote is not None:
                if character == quote:
                    quote = None
            elif character in {ord('"'), ord("'")}:
                quote = character
            elif character == ord(">"):
                state = text_state
            return True

        if state == "closing":
            if character == ord(">"):
                state = text_state
            return True

        if state == "processing-instruction":
            delimiter_tail = (*delimiter_tail[-1:], character)
            if delimiter_tail == (ord("?"), ord(">")):
                state = text_state
            return True

        if state == "comment":
            delimiter_tail = (*delimiter_tail[-2:], character)
            if delimiter_tail == (ord("-"), ord("-"), ord(">")):
                state = text_state
            return True

        if state == "declaration":
            consume_declaration_character(character)
            return True

        if state == "entity":
            if character == ord(";"):
                state = text_state
            return True

        # The only remaining state is the prefix after "<!". Classify the
        # two XML constructs that can contain element-looking text; any other
        # declaration is skipped through its balanced closing delimiter.
        bang_prefix.append(character)
        comment_prefix = (ord("-"), ord("-"))
        cdata_prefix = (
            ord("["),
            ord("C"),
            ord("D"),
            ord("A"),
            ord("T"),
            ord("A"),
            ord("["),
        )
        prefix = tuple(bang_prefix)
        if prefix == comment_prefix:
            state = "comment"
            delimiter_tail = prefix
            return True
        if prefix == cdata_prefix:
            state = "cdata"
            delimiter_tail = prefix[-2:]
            return True
        if comment_prefix[: len(prefix)] == prefix or cdata_prefix[: len(prefix)] == prefix:
            return True
        state = "declaration"
        declaration_quote = None
        declaration_bracket_depth = 0
        for declaration_character in bang_prefix:
            consume_declaration_character(declaration_character)
            if state == text_state:
                break
        return True

    pending = prefix[prefix_skip:]
    stream_exhausted = False
    while pending or not stream_exhausted:
        if not stream_exhausted:
            chunk = xml_stream.read(_OOXML_READER_XML_LEXICAL_CHUNK_BYTES)
            if chunk:
                pending += chunk
            else:
                stream_exhausted = True
        usable_size = len(pending) - (len(pending) % unit_width)
        for offset in range(0, usable_size, unit_width):
            unit = pending[offset : offset + unit_width]
            character = unit[0] if unit_width == 1 else int.from_bytes(unit, byte_order)
            if not consume_character(character, unit_width):
                return violation
        pending = pending[usable_size:]
    return None


def _xml_start_tags_within_budget(
    xml_stream,
    *,
    maximum_start_tag_bytes: int | None = None,
    maximum_markup_bytes: int | None = None,
) -> bool:
    """Return whether parser-frontier XML markup stays within its budgets.

    The historic name remains because callers use it as the pre-parser lexical
    gate. It now also protects ignored non-character-data tokens that can make
    the XML parser allocate before a stream event is available.
    """
    return (
        _xml_lexical_markup_budget_violation(
            xml_stream,
            maximum_start_tag_bytes=maximum_start_tag_bytes,
            maximum_markup_bytes=maximum_markup_bytes,
        )
        is None
    )


def _ooxml_xml_lexical_markup_budget_violation(
    archive: ZipFile,
    member: str,
    *,
    maximum_start_tag_bytes: int | None = None,
    maximum_markup_bytes: int | None = None,
) -> str | None:
    """Return an OOXML member's pre-parser lexical allocation-boundary violation."""
    with archive.open(member) as xml_stream:
        return _xml_lexical_markup_budget_violation(
            xml_stream,
            maximum_start_tag_bytes=maximum_start_tag_bytes,
            maximum_markup_bytes=maximum_markup_bytes,
        )


def _ooxml_xml_start_tags_within_budget(
    archive: ZipFile,
    member: str,
    *,
    maximum_start_tag_bytes: int | None = None,
) -> bool:
    """Check an OOXML part's lexical parser-allocation budgets without parsing."""
    return (
        _ooxml_xml_lexical_markup_budget_violation(
            archive,
            member,
            maximum_start_tag_bytes=maximum_start_tag_bytes,
        )
        is None
    )


def _stream_ooxml_reader_xml(
    archive: ZipFile,
    member: str,
    *,
    on_start: Callable[[ElementTree.Element], None] | None = None,
    on_start_with_tags: Callable[[ElementTree.Element, list[str]], None]
    | None = None,
    on_end: Callable[[ElementTree.Element, list[str]], None] | None = None,
) -> None:
    """Stream one reader-visible XML part under structural resource limits."""
    lexical_violation = _ooxml_xml_lexical_markup_budget_violation(archive, member)
    if lexical_violation == "start-tag":
        raise _reader_preflight_error(
            "XML start tag exceeds the semantic-reader safety limit."
        )
    if lexical_violation is not None:
        raise _reader_preflight_error(
            "XML non-character-data markup exceeds the semantic-reader safety limit."
        )
    depth = 0
    element_count = 0
    elements: list[ElementTree.Element] = []
    tags: list[str] = []
    with archive.open(member) as xml_stream:
        for event, element in _iterparse_ooxml_reader_xml(xml_stream):
            if event == "start":
                depth += 1
                if depth > _OOXML_READER_MAX_XML_NESTING_DEPTH:
                    raise _reader_preflight_error(
                        "XML nesting exceeds the semantic-reader safety limit."
                    )
                element_count += 1
                if element_count > _OOXML_READER_MAX_XML_ELEMENT_COUNT:
                    raise _reader_preflight_error(
                        "XML element count exceeds the semantic-reader safety limit."
                    )
                tags.append(element.tag)
                elements.append(element)
                if on_start is not None:
                    on_start(element)
                if on_start_with_tags is not None:
                    on_start_with_tags(element, tags)
                continue

            if on_end is not None:
                on_end(element, tags)
            parent = elements[-2] if len(elements) > 1 else None
            if parent is not None:
                parent.remove(element)
            element.clear()
            elements.pop()
            tags.pop()
            depth -= 1


def _ooxml_xml_structure_element_count_within_budget(
    archive: ZipFile,
    member: str,
    *,
    maximum_element_count: int,
    maximum_nesting_depth: int = _OOXML_READER_MAX_XML_NESTING_DEPTH,
) -> int | None:
    """Return a bounded XML count, or None for a structural/tag-budget overage."""
    if not _ooxml_xml_start_tags_within_budget(archive, member):
        return None
    depth = 0
    element_count = 0
    elements: list[ElementTree.Element] = []
    try:
        with archive.open(member) as xml_stream:
            for event, element in _iterparse_ooxml_xml_with_character_data_budget(
                xml_stream
            ):
                if event == "start":
                    depth += 1
                    element_count += 1
                    if (
                        depth > maximum_nesting_depth
                        or element_count > maximum_element_count
                    ):
                        return None
                    elements.append(element)
                    continue
                parent = elements[-2] if len(elements) > 1 else None
                if parent is not None:
                    parent.remove(element)
                element.clear()
                elements.pop()
                depth -= 1
    except _OoxmlXmlCharacterDataLimitError:
        return None
    return element_count


def _xml_payload_structure_element_count_within_budget(
    payload: bytes,
    *,
    maximum_element_count: int,
    maximum_nesting_depth: int = _OOXML_READER_MAX_XML_NESTING_DEPTH,
) -> int | None:
    """Return a bounded payload count, or None for a structural/tag-budget overage."""
    if not _xml_start_tags_within_budget(io.BytesIO(payload)):
        return None
    depth = 0
    element_count = 0
    elements: list[ElementTree.Element] = []
    try:
        with io.BytesIO(payload) as xml_stream:
            for event, element in _iterparse_ooxml_xml_with_character_data_budget(
                xml_stream
            ):
                if event == "start":
                    depth += 1
                    element_count += 1
                    if (
                        depth > maximum_nesting_depth
                        or element_count > maximum_element_count
                    ):
                        return None
                    elements.append(element)
                    continue
                parent = elements[-2] if len(elements) > 1 else None
                if parent is not None:
                    parent.remove(element)
                element.clear()
                elements.pop()
                depth -= 1
    except _OoxmlXmlCharacterDataLimitError:
        return None
    return element_count


def _ooxml_xml_structure_within_budget(
    archive: ZipFile,
    member: str,
    *,
    maximum_element_count: int,
    maximum_nesting_depth: int = _OOXML_READER_MAX_XML_NESTING_DEPTH,
) -> bool:
    """Stream one raw XML part without retaining an unbounded element tree."""
    return (
        _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=maximum_element_count,
            maximum_nesting_depth=maximum_nesting_depth,
        )
        is not None
    )


def _reader_shared_string_xml_paths(
    archive: ZipFile,
    *,
    manifest_targets: tuple[str, ...] = (),
) -> tuple[str, ...]:
    """Find every shared-string part selected by a reader without fixed paths.

    ``openpyxl`` follows the first shared-string manifest override, but the raw
    rich-text scanner follows one exact transitional workbook relationship (or
    its canonical fallback). A malformed package can make those two valid
    selection rules point at different members. Stream their union so neither
    reader reaches a compact, materializing shared-string tree first.
    """
    paths: list[str] = []
    if manifest_targets:
        # ``openpyxl`` reads the first matching manifest Override.
        paths.append(manifest_targets[0])
    relationships = _package_relationships(archive, "xl/workbook.xml")
    reader_relationship_targets = [
        relationship.target
        for relationship in relationships
        if (
            relationship.target is not None
            and relationship.relationship_type.rsplit("/", maxsplit=1)[-1].casefold()
            == "sharedstrings"
        )
    ]
    if not manifest_targets:
        if len(reader_relationship_targets) == 1:
            paths.append(reader_relationship_targets[0])
        elif (
            not reader_relationship_targets
            and "xl/sharedStrings.xml" in archive.namelist()
        ):
            paths.append("xl/sharedStrings.xml")

    raw_rich_text_targets = [
        relationship.target
        for relationship in relationships
        if (
            relationship.relationship_type == _OOXML_SHARED_STRINGS_RELATIONSHIP
            and relationship.target is not None
        )
    ]
    if len(raw_rich_text_targets) == 1:
        raw_rich_text_target = raw_rich_text_targets[0]
        if raw_rich_text_target in archive.namelist():
            paths.append(raw_rich_text_target)
    elif not raw_rich_text_targets and "xl/sharedStrings.xml" in archive.namelist():
        paths.append("xl/sharedStrings.xml")

    return tuple(dict.fromkeys(paths))


def _validate_ooxml_semantic_reader_resources(
    path: Path,
    members: tuple[_OoxmlArchiveMember, ...],
) -> None:
    """Bound XML and populated-cell resources before any semantic reader starts.

    The prior central-directory pass has already established that members have
    unique canonical names and coherent headers. This pass therefore only needs
    to inspect the workbook's sheet relationships, then stream each selected
    worksheet once while keeping no values, locations, or XML tree in memory.
    It therefore covers relationship-selected worksheet locations and
    shared-string paths rather than assuming a writer used one conventional
    member path, without turning an unrelated malformed extension part into a
    hard input failure. It also streams every relationship part under a small
    structural budget before raw metadata scanners can materialize an
    oversized catalog. Alongside cell counts, it bounds reader-materialized
    workbook catalogs, XML shape, the shared-string table, and
    Excel-compatible cell/formula scalar sizes.
    It protects FormulaFence's complete ``openpyxl`` reader and every
    subsequent raw OOXML scanner from a package that is valid ZIP but
    impractical to model safely in a CI worker.
    """
    member_by_name = {member.name: member for member in members}
    xml_members = tuple(member for member in members if _is_ooxml_xml_member(member))
    relationship_member_names = tuple(
        member.name
        for member in xml_members
        if member.name.casefold().endswith(".rels")
    )
    total_xml_bytes = 0
    for member in xml_members:
        if member.uncompressed_size > _OOXML_READER_MAX_XML_PART_BYTES:
            raise _reader_preflight_error(
                "an XML part exceeds the semantic-reader safety limit."
            )
        total_xml_bytes += member.uncompressed_size
        if total_xml_bytes > _OOXML_READER_MAX_TOTAL_XML_BYTES:
            raise _reader_preflight_error(
                "aggregate XML material exceeds the semantic-reader safety limit."
            )

    non_xml_reader_members: set[str] = set()

    def reader_member(member_name: str) -> _OoxmlArchiveMember:
        nonlocal total_xml_bytes
        member = member_by_name.get(member_name)
        if member is None:
            raise _reader_preflight_error(
                "a reader-visible XML part could not be located safely."
            )
        if (
            not _is_ooxml_xml_member(member)
            and member.name not in non_xml_reader_members
        ):
            if member.uncompressed_size > _OOXML_READER_MAX_XML_PART_BYTES:
                raise _reader_preflight_error(
                    "an XML part exceeds the semantic-reader safety limit."
                )
            total_xml_bytes += member.uncompressed_size
            if total_xml_bytes > _OOXML_READER_MAX_TOTAL_XML_BYTES:
                raise _reader_preflight_error(
                    "aggregate XML material exceeds the semantic-reader safety limit."
                )
            non_xml_reader_members.add(member.name)
        return member

    def validate_cell_text_length(length: int) -> None:
        if length > _OOXML_READER_MAX_CELL_TEXT_CHARACTERS:
            raise _reader_preflight_error(
                "cell text exceeds the semantic-reader safety limit."
            )

    def validate_formula_text_length(length: int) -> None:
        if length > _OOXML_READER_MAX_FORMULA_CHARACTERS:
            raise _reader_preflight_error(
                "formula text exceeds the semantic-reader safety limit."
            )

    inline_string_text_lengths: list[int] = []
    shared_string_text_lengths: list[int] = []
    manifest_shared_string_members: list[str] = []
    content_type_declaration_count = 0
    workbook_relationship_count = 0
    relationship_part_element_count = 0
    relationship_xml_element_count = 0
    workbook_sheet_count = 0
    workbook_defined_name_count = 0
    workbook_external_reference_count = 0
    workbook_pivot_cache_count = 0
    workbook_auxiliary_catalog_counts: dict[str, int] = {}
    workbook_opaque_root_xml_element_count = 0
    workbook_extension_list_xml_element_count = 0
    custom_sheet_view_count = 0
    custom_sheet_view_descendant_count = 0
    merged_cell_range_count = 0
    merged_cell_count = 0
    data_validation_count = 0
    data_validation_target_range_count = 0
    conditional_formatting_count = 0
    conditional_formatting_rule_count = 0
    conditional_formatting_target_range_count = 0
    scenario_container_count = 0
    scenario_count = 0
    scenario_input_cell_count = 0
    scenario_target_range_count = 0
    populated_cell_count = 0
    row_dimension_count = 0
    column_dimension_container_count = 0
    column_dimension_count = 0
    page_break_container_count = 0
    page_break_declaration_count = 0
    worksheet_opaque_root_part_xml_element_count = 0
    worksheet_opaque_root_xml_element_count = 0
    worksheet_extension_list_part_xml_element_count = 0
    worksheet_extension_list_xml_element_count = 0
    shared_string_count = 0
    shared_string_item_xml_element_counts: list[int] = []
    shared_string_item_is_complex: list[bool] = []
    complex_shared_string_xml_element_count = 0
    shared_string_opaque_part_xml_element_count = 0
    shared_string_opaque_xml_element_count = 0
    cell_tags = _spreadsheetml_tags("c")
    row_tags = _spreadsheetml_tags("row")
    column_tags = _spreadsheetml_tags("col")
    column_container_tags = _spreadsheetml_tags("cols")
    page_break_container_tags = _spreadsheetml_tags("rowBreaks", "colBreaks")
    custom_sheet_view_container_tags = _spreadsheetml_tags("customSheetViews")
    worksheet_tags = _spreadsheetml_tags("worksheet")
    formula_tags = _spreadsheetml_tags("f")
    inline_string_tags = _spreadsheetml_tags("is")
    shared_string_tags = _spreadsheetml_tags("si")
    shared_string_table_tags = _spreadsheetml_tags("sst")
    workbook_standard_root_tags = _spreadsheetml_tags(
        "fileVersion",
        "fileSharing",
        "workbookPr",
        "workbookProtection",
        "bookViews",
        "sheets",
        "functionGroups",
        "externalReferences",
        "definedNames",
        "calcPr",
        "oleSize",
        "customWorkbookViews",
        "pivotCaches",
        "smartTagPr",
        "smartTagTypes",
        "webPublishing",
        "fileRecoveryPr",
        "webPublishObjects",
        "extLst",
    )
    worksheet_extension_list_tags = _spreadsheetml_tags("extLst")
    worksheet_standard_root_tags = _spreadsheetml_tags(
        "sheetPr",
        "dimension",
        "sheetViews",
        "sheetFormatPr",
        "cols",
        "sheetData",
        "sheetCalcPr",
        "sheetProtection",
        "protectedRanges",
        "scenarios",
        "autoFilter",
        "sortState",
        "dataConsolidate",
        "customSheetViews",
        "mergeCells",
        "phoneticPr",
        "conditionalFormatting",
        "dataValidations",
        "hyperlinks",
        "printOptions",
        "pageMargins",
        "pageSetup",
        "headerFooter",
        "rowBreaks",
        "colBreaks",
        "customProperties",
        "cellWatches",
        "ignoredErrors",
        "smartTags",
        "drawing",
        "legacyDrawing",
        "legacyDrawingHF",
        "drawingHF",
        "picture",
        "oleObjects",
        "controls",
        "webPublishItems",
        "tableParts",
        "extLst",
    )
    text_tags = _spreadsheetml_tags("t")
    value_tags = _spreadsheetml_tags("v")
    data_validation_container_tags = _spreadsheetml_tags("dataValidations")
    conditional_formatting_tags = _spreadsheetml_tags("conditionalFormatting")
    scenario_container_tags = _spreadsheetml_tags("scenarios")

    def content_types_end(
        element: ElementTree.Element,
        _tags: list[str],
    ) -> None:
        nonlocal content_type_declaration_count
        local_name = element.tag.rsplit("}", maxsplit=1)[-1]
        if local_name in {"Default", "Override"}:
            content_type_declaration_count += 1
            if (
                content_type_declaration_count
                > _OOXML_READER_MAX_CONTENT_TYPE_DECLARATION_COUNT
            ):
                raise _reader_preflight_error(
                    "content-type declarations exceed the semantic-reader safety limit."
                )
        if (
            local_name == "Override"
            and element.get("ContentType", "").casefold()
            == _OOXML_SHARED_STRINGS_CONTENT_TYPE.casefold()
            and (part_name := element.get("PartName"))
            and not manifest_shared_string_members
        ):
            manifest_shared_string_members.append(part_name.lstrip("/"))

    def increment_auxiliary_catalog(
        catalog: str,
        *,
        limit: int,
        message: str,
    ) -> None:
        count = workbook_auxiliary_catalog_counts.get(catalog, 0) + 1
        workbook_auxiliary_catalog_counts[catalog] = count
        if count > limit:
            raise _reader_preflight_error(message)

    def workbook_opaque_root_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound one complete unknown direct workbook-root subtree.

        The published Workbook grammar names the ordinary package controls
        below. Keep those controls and their independently bounded catalogs
        outside this narrow counter, while treating compatibility and foreign
        root content as opaque material that neither reader needs to retain as
        ordinary workbook semantics.
        """
        nonlocal workbook_opaque_root_xml_element_count
        if (
            len(tags) < 2
            or _xml_local_name(tags[0]) != "workbook"
            or tags[1] in workbook_standard_root_tags
            or _xml_local_name(tags[1]) == "extLst"
        ):
            return
        workbook_opaque_root_xml_element_count += 1
        if (
            workbook_opaque_root_xml_element_count
            > _OOXML_READER_MAX_WORKBOOK_OPAQUE_ROOT_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "workbook opaque root XML structure exceeds the semantic-reader "
                "safety limit."
            )

    def workbook_extension_list_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound every extension subtree selected under a Workbook root.

        Extension lists are documented both as a direct Workbook child and on
        nested workbook controls such as workbook views. ``openpyxl`` dispatches
        those controls by local name, so an alternate-namespace ``extLst`` must
        receive the same limit. Count a subtree only once even if an extension
        payload contains another extension list: any matching ancestor makes
        the completed element part of this allocation boundary.
        """
        nonlocal workbook_extension_list_xml_element_count
        if (
            len(tags) < 2
            or _xml_local_name(tags[0]) != "workbook"
            or not any(_xml_local_name(tag) == "extLst" for tag in tags[1:])
        ):
            return
        workbook_extension_list_xml_element_count += 1
        if (
            workbook_extension_list_xml_element_count
            > _OOXML_READER_MAX_WORKBOOK_EXTENSION_LIST_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "workbook extension-list XML structure exceeds the semantic-reader "
                "safety limit."
            )

    def workbook_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal workbook_defined_name_count
        nonlocal workbook_external_reference_count
        nonlocal workbook_pivot_cache_count
        nonlocal workbook_sheet_count
        workbook_extension_list_end(element, tags)
        workbook_opaque_root_end(element, tags)
        # ``openpyxl``'s workbook package parser uses local XML names while
        # constructing these catalogs. A direct alternate-namespace
        # ``definedName`` is therefore still materialized, and nested-sequence
        # catalogs construct an object for every direct child. Count the same
        # direct catalog entries rather than allowing a namespace variation to
        # evade an allocation bound.
        is_direct_workbook_catalog_child = (
            len(tags) == 3 and _xml_local_name(tags[0]) == "workbook"
        )
        if not is_direct_workbook_catalog_child:
            return

        parent_name = _xml_local_name(tags[-2])
        element_name = _xml_local_name(element.tag)

        if parent_name == "definedNames" and element_name == "definedName":
            validate_formula_text_length(len(element.text or ""))
            workbook_defined_name_count += 1
            if (
                workbook_defined_name_count
                > _OOXML_READER_MAX_WORKBOOK_DEFINED_NAME_COUNT
            ):
                raise _reader_preflight_error(
                    "workbook defined-name declarations exceed the "
                    "semantic-reader safety limit."
                )
        elif parent_name == "sheets":
            workbook_sheet_count += 1
            if workbook_sheet_count > _OOXML_READER_MAX_WORKBOOK_SHEET_COUNT:
                raise _reader_preflight_error(
                    "workbook sheet declarations exceed the semantic-reader safety limit."
                )
        elif parent_name == "externalReferences":
            workbook_external_reference_count += 1
            if (
                workbook_external_reference_count
                > _OOXML_READER_MAX_WORKBOOK_EXTERNAL_REFERENCE_COUNT
            ):
                raise _reader_preflight_error(
                    "workbook external-reference declarations exceed the "
                    "semantic-reader safety limit."
                )
        elif parent_name == "pivotCaches":
            workbook_pivot_cache_count += 1
            if (
                workbook_pivot_cache_count
                > _OOXML_READER_MAX_WORKBOOK_PIVOT_CACHE_COUNT
            ):
                raise _reader_preflight_error(
                    "workbook pivot-cache declarations exceed the "
                    "semantic-reader safety limit."
                )
        elif parent_name == "bookViews":
            increment_auxiliary_catalog(
                "book-views",
                limit=_OOXML_READER_MAX_WORKBOOK_BOOK_VIEW_COUNT,
                message=(
                    "workbook book-view declarations exceed the semantic-reader "
                    "safety limit."
                ),
            )
        elif parent_name == "customWorkbookViews":
            increment_auxiliary_catalog(
                "custom-workbook-views",
                limit=_OOXML_READER_MAX_WORKBOOK_CUSTOM_VIEW_COUNT,
                message=(
                    "workbook custom-view declarations exceed the semantic-reader "
                    "safety limit."
                ),
            )
        elif parent_name == "functionGroups" and element_name == "functionGroup":
            increment_auxiliary_catalog(
                "function-groups",
                limit=_OOXML_READER_MAX_WORKBOOK_FUNCTION_GROUP_COUNT,
                message=(
                    "workbook function-group declarations exceed the semantic-reader "
                    "safety limit."
                ),
            )
        elif parent_name == "smartTagTypes" and element_name == "smartTagType":
            increment_auxiliary_catalog(
                "smart-tag-types",
                limit=_OOXML_READER_MAX_WORKBOOK_SMART_TAG_TYPE_COUNT,
                message=(
                    "workbook smart-tag type declarations exceed the semantic-reader "
                    "safety limit."
                ),
            )
        elif (
            parent_name == "webPublishObjects"
            and element_name == "webPublishObject"
        ):
            increment_auxiliary_catalog(
                "web-publish-objects",
                limit=_OOXML_READER_MAX_WORKBOOK_WEB_PUBLISH_OBJECT_COUNT,
                message=(
                    "workbook web-publish-object declarations exceed the "
                    "semantic-reader safety limit."
                ),
            )

    def workbook_relationships_end(
        element: ElementTree.Element,
        _tags: list[str],
    ) -> None:
        nonlocal workbook_relationship_count
        if element.tag.rsplit("}", maxsplit=1)[-1] != "Relationship":
            return
        workbook_relationship_count += 1
        if workbook_relationship_count > _OOXML_READER_MAX_WORKBOOK_RELATIONSHIP_COUNT:
            raise _reader_preflight_error(
                "workbook relationships exceed the semantic-reader safety limit."
            )

    def relationship_part_start(_element: ElementTree.Element) -> None:
        nonlocal relationship_part_element_count
        nonlocal relationship_xml_element_count
        relationship_part_element_count += 1
        if (
            relationship_part_element_count
            > _OOXML_READER_MAX_RELATIONSHIP_PART_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "relationship-part XML elements exceed the semantic-reader safety limit."
            )
        relationship_xml_element_count += 1
        if (
            relationship_xml_element_count
            > _OOXML_READER_MAX_RELATIONSHIP_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "aggregate relationship-part XML elements exceed the "
                "semantic-reader safety limit."
            )

    def worksheet_start(element: ElementTree.Element) -> None:
        if element.tag in inline_string_tags:
            inline_string_text_lengths.append(0)

    def custom_sheet_view_descendant_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound raw-scanned descendants beneath supported Custom View entries."""
        nonlocal custom_sheet_view_descendant_count

        # The Custom View scanner only enters a sheet-level container in a
        # supported SpreadsheetML namespace. It then handles every direct
        # ``customSheetView`` child, including an alternate-namespace child it
        # must hash as opaque evidence. Count each descendant—not the view
        # declaration itself, which has its own catalog budget—before either
        # the specialized or recursive generic scanner can build Python tuples.
        if (
            len(tags) < 4
            or tags[1] not in custom_sheet_view_container_tags
            or _xml_local_name(tags[2]) != "customSheetView"
        ):
            return
        custom_sheet_view_descendant_count += 1
        if (
            custom_sheet_view_descendant_count
            > _OOXML_READER_MAX_CUSTOM_SHEET_VIEW_DESCENDANT_COUNT
        ):
            raise _reader_preflight_error(
                "custom sheet-view descendants exceed the semantic-reader safety limit."
            )

    def sheet_catalog_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal custom_sheet_view_count
        custom_sheet_view_descendant_end(element, tags)
        custom_sheet_view_page_break_end(element, tags)
        # FormulaFence's legacy Custom View scanner examines every direct child
        # of a sheet-level ``customSheetViews`` container, including an unknown
        # namespace child it will retain as opaque evidence. Count that same
        # direct shape across all selected worksheet, chart-sheet, and dialog-
        # sheet parts before the raw scanner can build its per-view records.
        if len(tags) != 3 or _xml_local_name(tags[-2]) != "customSheetViews":
            return
        custom_sheet_view_count += 1
        if custom_sheet_view_count > _OOXML_READER_MAX_CUSTOM_SHEET_VIEW_COUNT:
            raise _reader_preflight_error(
                "custom sheet-view declarations exceed the semantic-reader safety limit."
            )

    def custom_sheet_view_page_break_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound direct page-break catalogs the raw Custom View scanner retains."""
        nonlocal page_break_container_count
        nonlocal page_break_declaration_count

        # The Custom View scanner accepts either SpreadsheetML namespace for a
        # direct ``customSheetViews`` container, then handles every direct
        # ``customSheetView`` child. A standard view parses its direct page
        # break containers structurally; an alternate-namespace view or nested
        # break container is retained through the generic opaque signature path.
        # Count both forms by local name so neither can make that raw scanner
        # allocate an unbounded record or subtree catalog.
        if (
            len(tags) == 4
            and tags[-3] in custom_sheet_view_container_tags
            and _xml_local_name(tags[-2]) == "customSheetView"
            and _xml_local_name(element.tag) in {"rowBreaks", "colBreaks"}
        ):
            page_break_container_count += 1
            if (
                page_break_container_count
                > _OOXML_READER_MAX_PAGE_BREAK_CONTAINER_COUNT
            ):
                raise _reader_preflight_error(
                    "page-break containers exceed the semantic-reader safety limit."
                )
            return

        if (
            len(tags) == 5
            and tags[-4] in custom_sheet_view_container_tags
            and _xml_local_name(tags[-3]) == "customSheetView"
            and _xml_local_name(tags[-2]) in {"rowBreaks", "colBreaks"}
        ):
            page_break_declaration_count += 1
            if (
                page_break_declaration_count
                > _OOXML_READER_MAX_PAGE_BREAK_DECLARATION_COUNT
            ):
                raise _reader_preflight_error(
                    "page-break declarations exceed the semantic-reader safety limit."
                )

    def merged_cell_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal merged_cell_count
        nonlocal merged_cell_range_count
        # ``MergeCells`` is a sequence parsed by local child name. The worksheet
        # reader then expands every coordinate in each parsed range into a
        # ``MergedCell`` object, so count the same direct declaration shape and
        # its geometric area before that allocation can start.
        if (
            len(tags) != 3
            or _xml_local_name(tags[-2]) != "mergeCells"
            or _xml_local_name(element.tag) != "mergeCell"
        ):
            return
        merged_cell_range_count += 1
        if merged_cell_range_count > _OOXML_READER_MAX_MERGED_CELL_RANGE_COUNT:
            raise _reader_preflight_error(
                "merged-cell declarations exceed the semantic-reader safety limit."
            )
        reference = element.get("ref")
        if (
            reference is None
            or len(reference) > _OOXML_READER_MAX_MERGED_CELL_REFERENCE_CHARACTERS
        ):
            raise _reader_preflight_error(
                "a merged-cell reference exceeds the semantic-reader safety limit."
            )
        try:
            if "!" in reference:
                _title, (min_column, min_row, max_column, max_row) = range_to_tuple(
                    reference
                )
            else:
                min_column, min_row, max_column, max_row = range_boundaries(reference)
        except ValueError as error:
            raise _reader_preflight_error(
                "a merged-cell reference could not be measured safely."
            ) from error
        if (
            not all(
                isinstance(value, int) and value >= 1
                for value in (min_column, min_row, max_column, max_row)
            )
            or min_column > max_column
            or min_row > max_row
        ):
            raise _reader_preflight_error(
                "a merged-cell reference could not be measured safely."
            )
        range_cell_count = (max_column - min_column + 1) * (max_row - min_row + 1)
        if range_cell_count > _OOXML_READER_MAX_MERGED_CELL_COUNT:
            raise _reader_preflight_error(
                "a merged-cell range exceeds the semantic-reader safety limit."
            )
        merged_cell_count += range_cell_count
        if merged_cell_count > _OOXML_READER_MAX_MERGED_CELL_COUNT:
            raise _reader_preflight_error(
                "merged-cell area exceeds the semantic-reader safety limit."
            )

    def multi_range_reference_count(
        reference: str | None,
        *,
        label: str,
    ) -> int:
        """Measure an ``openpyxl`` ``MultiCellRange`` input before expansion."""
        if reference is None:
            return 0
        if len(reference) > _OOXML_READER_MAX_MULTI_RANGE_REFERENCE_CHARACTERS:
            raise _reader_preflight_error(
                f"a {label} reference exceeds the semantic-reader safety limit."
            )
        count = len(reference.split())
        if count > _OOXML_READER_MAX_MULTI_RANGE_REFERENCE_COUNT:
            raise _reader_preflight_error(
                f"a {label} reference exceeds the semantic-reader safety limit."
            )
        return count

    def worksheet_reader_catalog_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal conditional_formatting_count
        nonlocal conditional_formatting_rule_count
        nonlocal conditional_formatting_target_range_count
        nonlocal data_validation_count
        nonlocal data_validation_target_range_count
        nonlocal scenario_container_count
        nonlocal scenario_count
        nonlocal scenario_input_cell_count
        nonlocal scenario_target_range_count
        element_name = _xml_local_name(element.tag)

        # ``DataValidationList`` constructs a ``DataValidation`` for every
        # direct local-named child; each ``sqref`` becomes a ``MultiCellRange``.
        if (
            len(tags) == 3
            and tags[-2] in data_validation_container_tags
            and element_name == "dataValidation"
        ):
            data_validation_count += 1
            if data_validation_count > _OOXML_READER_MAX_DATA_VALIDATION_COUNT:
                raise _reader_preflight_error(
                    "data-validation declarations exceed the semantic-reader safety "
                    "limit."
                )
            data_validation_target_range_count += multi_range_reference_count(
                element.get("sqref"),
                label="data-validation target",
            )
            if (
                data_validation_target_range_count
                > _OOXML_READER_MAX_DATA_VALIDATION_TARGET_RANGE_COUNT
            ):
                raise _reader_preflight_error(
                    "data-validation target ranges exceed the semantic-reader safety "
                    "limit."
                )
            return

        if (
            len(tags) == 4
            and tags[-3] in data_validation_container_tags
            and _xml_local_name(tags[-2]) == "dataValidation"
            and element_name in {"formula1", "formula2"}
        ):
            validate_formula_text_length(len(element.text or ""))
            return

        # A worksheet's direct conditional-formatting declarations each retain
        # one ``MultiCellRange`` and an unbounded local-name ``cfRule`` sequence
        # in the reader, while FormulaFence separately snapshots the rules.
        if len(tags) == 2 and element.tag in conditional_formatting_tags:
            conditional_formatting_count += 1
            if (
                conditional_formatting_count
                > _OOXML_READER_MAX_CONDITIONAL_FORMATTING_COUNT
            ):
                raise _reader_preflight_error(
                    "conditional-formatting declarations exceed the semantic-reader "
                    "safety limit."
                )
            conditional_formatting_target_range_count += multi_range_reference_count(
                element.get("sqref"),
                label="conditional-formatting target",
            )
            if (
                conditional_formatting_target_range_count
                > _OOXML_READER_MAX_CONDITIONAL_FORMATTING_TARGET_RANGE_COUNT
            ):
                raise _reader_preflight_error(
                    "conditional-formatting target ranges exceed the semantic-reader "
                    "safety limit."
                )
            return

        if (
            len(tags) == 3
            and tags[-2] in conditional_formatting_tags
            and element_name == "cfRule"
        ):
            conditional_formatting_rule_count += 1
            if (
                conditional_formatting_rule_count
                > _OOXML_READER_MAX_CONDITIONAL_FORMATTING_RULE_COUNT
            ):
                raise _reader_preflight_error(
                    "conditional-formatting rules exceed the semantic-reader safety "
                    "limit."
                )
            return

        if (
            len(tags) == 4
            and tags[-3] in conditional_formatting_tags
            and _xml_local_name(tags[-2]) == "cfRule"
            and element_name == "formula"
        ):
            validate_formula_text_length(len(element.text or ""))
            return

        # ``ScenarioList`` has the same ``MultiCellRange`` conversion and
        # materializes every direct scenario and input-cell child. FormulaFence's
        # raw Scenario Manager scanner retains the corresponding private records.
        if len(tags) == 2 and element.tag in scenario_container_tags:
            scenario_container_count += 1
            if scenario_container_count > _OOXML_READER_MAX_SCENARIO_CONTAINER_COUNT:
                raise _reader_preflight_error(
                    "Scenario Manager containers exceed the semantic-reader safety "
                    "limit."
                )
            scenario_target_range_count += multi_range_reference_count(
                element.get("sqref"),
                label="Scenario Manager target",
            )
            if (
                scenario_target_range_count
                > _OOXML_READER_MAX_SCENARIO_TARGET_RANGE_COUNT
            ):
                raise _reader_preflight_error(
                    "Scenario Manager target ranges exceed the semantic-reader safety "
                    "limit."
                )
            return

        if (
            len(tags) == 3
            and tags[-2] in scenario_container_tags
            and element_name == "scenario"
        ):
            scenario_count += 1
            if scenario_count > _OOXML_READER_MAX_SCENARIO_COUNT:
                raise _reader_preflight_error(
                    "Scenario Manager declarations exceed the semantic-reader safety "
                    "limit."
                )
            return

        if (
            len(tags) == 4
            and tags[-3] in scenario_container_tags
            and _xml_local_name(tags[-2]) == "scenario"
            and element_name == "inputCells"
        ):
            scenario_input_cell_count += 1
            if scenario_input_cell_count > _OOXML_READER_MAX_SCENARIO_INPUT_CELL_COUNT:
                raise _reader_preflight_error(
                    "Scenario Manager input cells exceed the semantic-reader safety "
                    "limit."
                )

    def worksheet_opaque_root_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound one complete unknown direct worksheet-root subtree.

        The published Worksheet child grammar deliberately leaves ordinary
        ``sheetData`` and supported controls outside this narrow counter. The
        counter instead follows an opaque root child through every descendant,
        including a foreign namespace child that the ordinary parser will not
        dispatch and raw readers do not need to retain as semantic evidence.
        """
        nonlocal worksheet_opaque_root_part_xml_element_count
        nonlocal worksheet_opaque_root_xml_element_count
        if (
            len(tags) < 2
            or tags[0] not in worksheet_tags
            or tags[1] in worksheet_standard_root_tags
        ):
            return
        worksheet_opaque_root_part_xml_element_count += 1
        if (
            worksheet_opaque_root_part_xml_element_count
            > _OOXML_READER_MAX_WORKSHEET_OPAQUE_ROOT_PART_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "worksheet opaque root XML structure exceeds the semantic-reader "
                "safety limit."
            )
        worksheet_opaque_root_xml_element_count += 1
        if (
            worksheet_opaque_root_xml_element_count
            > _OOXML_READER_MAX_WORKSHEET_OPAQUE_ROOT_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "aggregate worksheet opaque root XML elements exceed the "
                "semantic-reader safety limit."
            )

    def worksheet_extension_list_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound one element under a selected Worksheet extension list.

        A Worksheet ``extLst`` can appear beneath a named root child as well
        as directly below the worksheet root. Count an entire extension
        subtree only once even if it contains another extension list: any
        matching ancestor is sufficient to make the completed element part of
        this allocation boundary.
        """
        nonlocal worksheet_extension_list_part_xml_element_count
        nonlocal worksheet_extension_list_xml_element_count
        if (
            len(tags) < 2
            or tags[0] not in worksheet_tags
            or not any(tag in worksheet_extension_list_tags for tag in tags[1:])
        ):
            return
        worksheet_extension_list_part_xml_element_count += 1
        if (
            worksheet_extension_list_part_xml_element_count
            > _OOXML_READER_MAX_WORKSHEET_EXTENSION_LIST_PART_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "worksheet extension-list XML structure exceeds the "
                "semantic-reader safety limit."
            )
        worksheet_extension_list_xml_element_count += 1
        if (
            worksheet_extension_list_xml_element_count
            > _OOXML_READER_MAX_WORKSHEET_EXTENSION_LIST_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "aggregate worksheet extension-list XML elements exceed the "
                "semantic-reader safety limit."
            )

    def worksheet_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal populated_cell_count
        nonlocal row_dimension_count
        nonlocal column_dimension_container_count
        nonlocal column_dimension_count
        nonlocal page_break_container_count
        nonlocal page_break_declaration_count
        worksheet_extension_list_end(element, tags)
        worksheet_opaque_root_end(element, tags)
        sheet_catalog_end(element, tags)
        merged_cell_end(element, tags)
        worksheet_reader_catalog_end(element, tags)
        if (
            element.tag in page_break_container_tags
            and len(tags) == 2
            and tags[0] in worksheet_tags
        ):
            page_break_container_count += 1
            if (
                page_break_container_count
                > _OOXML_READER_MAX_PAGE_BREAK_CONTAINER_COUNT
            ):
                raise _reader_preflight_error(
                    "page-break containers exceed the semantic-reader safety limit."
                )
        elif (
            len(tags) == 3
            and tags[0] in worksheet_tags
            and tags[-2] in page_break_container_tags
        ):
            # ``RowBreak.from_tree`` dispatches direct ``brk`` children by
            # local name, and FormulaFence records unexpected direct children
            # as print coverage evidence. Count every child of an ordinary or
            # Strict break container so neither path can evade the bound.
            page_break_declaration_count += 1
            if (
                page_break_declaration_count
                > _OOXML_READER_MAX_PAGE_BREAK_DECLARATION_COUNT
            ):
                raise _reader_preflight_error(
                    "page-break declarations exceed the semantic-reader safety limit."
                )
        elif (
            element.tag in column_container_tags
            and len(tags) == 2
            and tags[0] in worksheet_tags
        ):
            column_dimension_container_count += 1
            if (
                column_dimension_container_count
                > _OOXML_READER_MAX_COLUMN_DIMENSION_CONTAINER_COUNT
            ):
                raise _reader_preflight_error(
                    "column-dimension containers exceed the semantic-reader safety limit."
                )
        elif element.tag in column_tags:
            column_dimension_count += 1
            if column_dimension_count > _OOXML_READER_MAX_COLUMN_DIMENSION_COUNT:
                raise _reader_preflight_error(
                    "column-dimension declarations exceed the semantic-reader safety limit."
                )
        elif element.tag in row_tags and any(
            not attribute.startswith("{") and attribute not in {"r", "spans"}
            for attribute in element.attrib
        ):
            row_dimension_count += 1
            if row_dimension_count > _OOXML_READER_MAX_ROW_DIMENSION_COUNT:
                raise _reader_preflight_error(
                    "row-dimension declarations exceed the semantic-reader safety limit."
                )
        elif element.tag in cell_tags:
            populated_cell_count += 1
            if populated_cell_count > _OOXML_READER_MAX_WORKSHEET_CELL_COUNT:
                raise _reader_preflight_error(
                    "populated worksheet cells exceed the semantic-reader safety limit."
                )
        elif element.tag in formula_tags:
            validate_formula_text_length(len(element.text or ""))
        elif (
            element.tag in value_tags
            and len(tags) > 1
            and tags[-2] in cell_tags
        ):
            validate_cell_text_length(len(element.text or ""))

        if element.tag in text_tags and inline_string_text_lengths:
            inline_string_text_lengths[-1] += len(element.text or "")
            validate_cell_text_length(inline_string_text_lengths[-1])
        if element.tag in inline_string_tags:
            inline_string_text_lengths.pop()

    def shared_string_start(element: ElementTree.Element) -> None:
        # A raw rich-text reader and ``openpyxl`` must retain an individual
        # shared-string item while interpreting its rich runs, phonetics, or
        # unsupported XML. Count the whole item, not the overall table: a
        # workbook can reasonably contain many simple ``si``/``t`` values, but
        # a compact, expansive item must never reach a materializing parser.
        for index in range(len(shared_string_item_xml_element_counts)):
            shared_string_item_xml_element_counts[index] += 1
            if (
                shared_string_item_xml_element_counts[index]
                > _OOXML_READER_MAX_SHARED_STRING_ITEM_XML_ELEMENT_COUNT
            ):
                raise _reader_preflight_error(
                    "shared-string item XML structure exceeds the semantic-reader "
                    "safety limit."
                )
            if element.tag not in text_tags:
                shared_string_item_is_complex[index] = True
        if element.tag in shared_string_tags:
            shared_string_text_lengths.append(0)
            shared_string_item_xml_element_counts.append(1)
            shared_string_item_is_complex.append(False)

    def shared_string_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal complex_shared_string_xml_element_count
        nonlocal shared_string_count
        nonlocal shared_string_opaque_part_xml_element_count
        nonlocal shared_string_opaque_xml_element_count
        # ``openpyxl`` clears recognized ``si`` items incrementally but leaves
        # each other direct ``sst`` child attached to the table root. The raw
        # rich-text scanner used to materialize that root too. Count the full
        # opaque root-child subtree before either path can retain a compact,
        # repetitive extension or foreign catalog. Rich ``si`` descendants are
        # covered separately by the item/complex-item limits below.
        if (
            len(tags) >= 2
            and tags[0] in shared_string_table_tags
            and tags[1] not in shared_string_tags
        ):
            shared_string_opaque_part_xml_element_count += 1
            if (
                shared_string_opaque_part_xml_element_count
                > _OOXML_READER_MAX_SHARED_STRING_OPAQUE_PART_XML_ELEMENT_COUNT
            ):
                raise _reader_preflight_error(
                    "shared-string opaque XML structure exceeds the semantic-reader "
                    "safety limit."
                )
            shared_string_opaque_xml_element_count += 1
            if (
                shared_string_opaque_xml_element_count
                > _OOXML_READER_MAX_SHARED_STRING_OPAQUE_XML_ELEMENT_COUNT
            ):
                raise _reader_preflight_error(
                    "aggregate shared-string opaque XML elements exceed the "
                    "semantic-reader safety limit."
                )
        if element.tag in text_tags and shared_string_text_lengths:
            shared_string_text_lengths[-1] += len(element.text or "")
            validate_cell_text_length(shared_string_text_lengths[-1])
        if element.tag in shared_string_tags:
            shared_string_text_lengths.pop()
            item_element_count = shared_string_item_xml_element_counts.pop()
            item_is_complex = shared_string_item_is_complex.pop()
            shared_string_count += 1
            if shared_string_count > _OOXML_READER_MAX_SHARED_STRING_COUNT:
                raise _reader_preflight_error(
                    "shared-string table entries exceed the semantic-reader safety limit."
                )
            if item_is_complex:
                complex_shared_string_xml_element_count += item_element_count
                if (
                    complex_shared_string_xml_element_count
                    > _OOXML_READER_MAX_COMPLEX_SHARED_STRING_XML_ELEMENT_COUNT
                ):
                    raise _reader_preflight_error(
                        "aggregate complex shared-string XML elements exceed the "
                        "semantic-reader safety limit."
                    )

    cell_style_count = 0
    stylesheet_container_count = 0
    stylesheet_catalog_counts: dict[str, int] = {}
    stylesheet_opaque_root_xml_element_count = 0
    stylesheet_extension_list_xml_element_count = 0
    stylesheet_opaque_catalog_xml_element_count = 0
    stylesheet_record_xml_element_count = 0
    stylesheet_active_record: ElementTree.Element | None = None
    stylesheet_active_record_xml_element_count = 0
    stylesheet_catalog_root_local_names = frozenset(
        {
            "numFmts",
            "fonts",
            "fills",
            "borders",
            "cellStyleXfs",
            "cellXfs",
            "cellStyles",
            "dxfs",
            "tableStyles",
            "colors",
        }
    )
    stylesheet_standard_root_tags = _spreadsheetml_tags(
        "numFmts",
        "fonts",
        "fills",
        "borders",
        "cellStyleXfs",
        "cellXfs",
        "cellStyles",
        "dxfs",
        "tableStyles",
        "colors",
        "extLst",
    )

    def increment_stylesheet_catalog(
        catalog: str,
        *,
        limit: int,
        message: str,
    ) -> None:
        count = stylesheet_catalog_counts.get(catalog, 0) + 1
        stylesheet_catalog_counts[catalog] = count
        if count > limit:
            raise _reader_preflight_error(message)

    def is_stylesheet_record_start(tags: list[str]) -> bool:
        """Return whether a direct catalog child becomes a style record.

        ``NestedSequence`` turns every direct child into its expected style
        object. Other stylesheet controls use a named descriptor and ignore
        foreign direct children, which receive the opaque-catalog boundary
        below instead.
        """
        if len(tags) < 3 or _xml_local_name(tags[0]) != "styleSheet":
            return False
        parent_name = _xml_local_name(tags[1])
        element_name = _xml_local_name(tags[2])
        if parent_name in {"fonts", "fills", "borders", "dxfs"}:
            return True
        if parent_name == "numFmts":
            return element_name == "numFmt"
        if parent_name in {"cellStyleXfs", "cellXfs"}:
            return element_name == "xf"
        if parent_name == "cellStyles":
            return element_name == "cellStyle"
        if parent_name == "tableStyles":
            return element_name == "tableStyle"
        if parent_name == "colors":
            return element_name in {"indexedColors", "mruColors"}
        return False

    def stylesheet_start(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Start a one-record structural budget before it can grow."""
        nonlocal stylesheet_active_record
        nonlocal stylesheet_active_record_xml_element_count
        if len(tags) != 3 or not is_stylesheet_record_start(tags):
            return
        stylesheet_active_record = element
        stylesheet_active_record_xml_element_count = 0

    def stylesheet_opaque_root_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound one complete unknown direct Stylesheet-root subtree.

        The published Stylesheet grammar names the catalog controls below.
        Their direct records retain the existing targeted limits; an opaque
        root subtree—or an entire part with a foreign root local name—is not
        ordinary style semantics and can be bounded before the complete reader
        tree is constructed.
        """
        nonlocal stylesheet_opaque_root_xml_element_count
        if len(tags) < 2:
            return
        if _xml_local_name(tags[0]) == "styleSheet":
            if (
                tags[1] in stylesheet_standard_root_tags
                or _xml_local_name(tags[1]) == "extLst"
            ):
                return
        stylesheet_opaque_root_xml_element_count += 1
        if (
            stylesheet_opaque_root_xml_element_count
            > _OOXML_READER_MAX_STYLESHEET_OPAQUE_ROOT_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "stylesheet opaque root XML structure exceeds the semantic-reader "
                "safety limit."
            )

    def stylesheet_extension_list_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound every extension subtree selected under a Stylesheet root.

        A stylesheet extension list is documented at the root, while style
        records can carry nested extension lists. The reader dispatches those
        controls by local name, so namespace variations receive the same
        boundary. Count a nested extension tree only once even when it itself
        contains another extension list.
        """
        nonlocal stylesheet_extension_list_xml_element_count
        if (
            len(tags) < 2
            or _xml_local_name(tags[0]) != "styleSheet"
            or not any(_xml_local_name(tag) == "extLst" for tag in tags[1:])
        ):
            return
        stylesheet_extension_list_xml_element_count += 1
        if (
            stylesheet_extension_list_xml_element_count
            > _OOXML_READER_MAX_STYLESHEET_EXTENSION_LIST_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "stylesheet extension-list XML structure exceeds the semantic-reader "
                "safety limit."
            )

    def stylesheet_opaque_catalog_end(
        _element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound an ignored direct child beneath a named style catalog."""
        nonlocal stylesheet_opaque_catalog_xml_element_count
        if (
            len(tags) < 3
            or _xml_local_name(tags[0]) != "styleSheet"
            or _xml_local_name(tags[1]) not in stylesheet_catalog_root_local_names
            or is_stylesheet_record_start(tags)
            or any(_xml_local_name(tag) == "extLst" for tag in tags[2:])
        ):
            return
        stylesheet_opaque_catalog_xml_element_count += 1
        if (
            stylesheet_opaque_catalog_xml_element_count
            > _OOXML_READER_MAX_STYLESHEET_OPAQUE_CATALOG_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "stylesheet opaque catalog XML structure exceeds the "
                "semantic-reader safety limit."
            )

    def stylesheet_record_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        """Bound retained non-extension structure inside one style record."""
        nonlocal stylesheet_active_record
        nonlocal stylesheet_active_record_xml_element_count
        nonlocal stylesheet_record_xml_element_count
        if stylesheet_active_record is None:
            return
        if element is stylesheet_active_record:
            stylesheet_active_record = None
            return
        if any(_xml_local_name(tag) == "extLst" for tag in tags[3:]):
            return
        stylesheet_active_record_xml_element_count += 1
        if (
            stylesheet_active_record_xml_element_count
            > _OOXML_READER_MAX_STYLESHEET_RECORD_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "stylesheet record XML structure exceeds the semantic-reader "
                "safety limit."
            )
        stylesheet_record_xml_element_count += 1
        if (
            stylesheet_record_xml_element_count
            > _OOXML_READER_MAX_STYLESHEET_AGGREGATE_RECORD_XML_ELEMENT_COUNT
        ):
            raise _reader_preflight_error(
                "aggregate stylesheet record XML structure exceeds the "
                "semantic-reader safety limit."
            )

    def stylesheet_end(
        element: ElementTree.Element,
        tags: list[str],
    ) -> None:
        nonlocal cell_style_count, stylesheet_container_count
        stylesheet_extension_list_end(element, tags)
        stylesheet_opaque_root_end(element, tags)
        stylesheet_opaque_catalog_end(element, tags)
        stylesheet_record_end(element, tags)
        element_name = _xml_local_name(element.tag)

        # ``Stylesheet.from_tree`` recognizes direct child containers by local
        # name. Repeated containers are individually materialized before later
        # declarations overwrite the stored attribute, so cap those too rather
        # than only counting records inside the last conventional container.
        if len(tags) == 2 and element_name in {
            "numFmts",
            "fonts",
            "fills",
            "borders",
            "cellStyleXfs",
            "cellXfs",
            "cellStyles",
            "dxfs",
            "tableStyles",
            "colors",
            "extLst",
        }:
            stylesheet_container_count += 1
            if (
                stylesheet_container_count
                > _OOXML_READER_MAX_STYLESHEET_CONTAINER_COUNT
            ):
                raise _reader_preflight_error(
                    "stylesheet containers exceed the semantic-reader safety limit."
                )
            return

        if len(tags) == 3:
            parent_name = _xml_local_name(tags[-2])
            # ``NestedSequence.from_tree`` constructs its expected object for
            # every direct child, regardless of that child's namespace or local
            # name. Count all direct records in those containers to follow the
            # same allocation behavior.
            if parent_name == "fonts":
                increment_stylesheet_catalog(
                    "fonts",
                    limit=_OOXML_READER_MAX_FONT_COUNT,
                    message="font records exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "fills":
                increment_stylesheet_catalog(
                    "fills",
                    limit=_OOXML_READER_MAX_FILL_COUNT,
                    message="fill records exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "borders":
                increment_stylesheet_catalog(
                    "borders",
                    limit=_OOXML_READER_MAX_BORDER_COUNT,
                    message="border records exceed the semantic-reader safety limit.",
                )
                return

            if parent_name == "numFmts" and element_name == "numFmt":
                increment_stylesheet_catalog(
                    "number-formats",
                    limit=_OOXML_READER_MAX_NUMBER_FORMAT_COUNT,
                    message="number-format records exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "cellStyleXfs" and element_name == "xf":
                increment_stylesheet_catalog(
                    "base-cell-styles",
                    limit=_OOXML_READER_MAX_BASE_CELL_STYLE_COUNT,
                    message="base cell styles exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "cellXfs" and element_name == "xf":
                # ``CellStyleList`` also dispatches direct ``xf`` children by
                # local name, so an alternate-namespace container cannot evade
                # the established effective-cell-style ceiling.
                cell_style_count += 1
                if cell_style_count > _OOXML_READER_MAX_CELL_STYLE_COUNT:
                    raise _reader_preflight_error(
                        "cell styles exceed the semantic-reader safety limit."
                    )
                return
            if parent_name == "cellStyles" and element_name == "cellStyle":
                increment_stylesheet_catalog(
                    "named-cell-styles",
                    limit=_OOXML_READER_MAX_NAMED_CELL_STYLE_COUNT,
                    message="named cell styles exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "dxfs":
                increment_stylesheet_catalog(
                    "differential-styles",
                    limit=_OOXML_READER_MAX_DIFFERENTIAL_STYLE_COUNT,
                    message="differential styles exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "tableStyles" and element_name == "tableStyle":
                increment_stylesheet_catalog(
                    "table-styles",
                    limit=_OOXML_READER_MAX_TABLE_STYLE_COUNT,
                    message="table styles exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "extLst" and element_name == "ext":
                increment_stylesheet_catalog(
                    "style-extensions",
                    limit=_OOXML_READER_MAX_STYLE_EXTENSION_COUNT,
                    message="stylesheet extension records exceed the semantic-reader safety limit.",
                )
                return

        if len(tags) == 4:
            grandparent_name = _xml_local_name(tags[-3])
            parent_name = _xml_local_name(tags[-2])
            if grandparent_name == "fills" and parent_name == "fill":
                # ``Fill.from_tree`` first builds a list of every direct child
                # before selecting its pattern or gradient representation.
                increment_stylesheet_catalog(
                    "fill-children",
                    limit=_OOXML_READER_MAX_FILL_CHILD_COUNT,
                    message="fill child records exceed the semantic-reader safety limit.",
                )
                return
            if parent_name in {"indexedColors", "mruColors"}:
                increment_stylesheet_catalog(
                    "style-colors",
                    limit=_OOXML_READER_MAX_STYLE_COLOR_COUNT,
                    message="stylesheet colour records exceed the semantic-reader safety limit.",
                )
                return
            if parent_name == "tableStyle" and element_name == "tableStyleElement":
                increment_stylesheet_catalog(
                    "table-style-elements",
                    limit=_OOXML_READER_MAX_TABLE_STYLE_ELEMENT_COUNT,
                    message="table-style elements exceed the semantic-reader safety limit.",
                )
                return

        if (
            len(tags) == 5
            and _xml_local_name(tags[-4]) == "fills"
            and _xml_local_name(tags[-3]) == "fill"
            and _xml_local_name(tags[-2]) == "gradientFill"
            and element_name == "stop"
        ):
            increment_stylesheet_catalog(
                "gradient-fill-stops",
                limit=_OOXML_READER_MAX_GRADIENT_FILL_STOP_COUNT,
                message="gradient-fill stops exceed the semantic-reader safety limit.",
            )

    try:
        with ZipFile(path) as archive:
            for relationship_member_name in sorted(relationship_member_names):
                relationship_part_element_count = 0
                try:
                    _stream_ooxml_reader_xml(
                        archive,
                        relationship_member_name,
                        on_start=relationship_part_start,
                    )
                except ElementTree.ParseError:
                    # Individual metadata scanners preserve their established
                    # coverage warning for malformed optional relationship
                    # parts. The stream above still enforces structural limits
                    # before a malformed part can become expensive to parse.
                    continue
            bootstrap_members = (
                "[Content_Types].xml",
                "xl/workbook.xml",
                _relationship_part_path("xl/workbook.xml"),
            )
            for member_name in bootstrap_members:
                if member_name not in member_by_name:
                    continue
                reader_member(member_name)
                _stream_ooxml_reader_xml(
                    archive,
                    member_name,
                    on_end=(
                        content_types_end
                        if member_name == "[Content_Types].xml"
                        else workbook_end
                        if member_name == "xl/workbook.xml"
                        else workbook_relationships_end
                    ),
                )

            worksheet_members = tuple(dict.fromkeys(_worksheet_display_xml_paths(archive)))
            sheet_parts = tuple(_sheet_xml_parts(archive).values())
            reader_sheet_members = list(worksheet_members)
            non_grid_sheet_members: list[str] = []
            for member_name, sheet_kind in sheet_parts:
                if member_name not in reader_sheet_members:
                    reader_sheet_members.append(member_name)
                if (
                    sheet_kind in {"chartsheet", "dialogsheet"}
                    and member_name not in non_grid_sheet_members
                ):
                    non_grid_sheet_members.append(member_name)

            non_grid_sheet_xml_element_count = 0
            for non_grid_sheet_member in non_grid_sheet_members:
                reader_member(non_grid_sheet_member)
                try:
                    element_count = _ooxml_xml_structure_element_count_within_budget(
                        archive,
                        non_grid_sheet_member,
                        maximum_element_count=(
                            _OOXML_READER_MAX_NON_GRID_SHEET_PART_XML_ELEMENT_COUNT
                        ),
                    )
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
                    # Existing non-grid-sheet readers preserve their normal coverage
                    # warning or parser diagnostic for malformed sheet XML. A valid
                    # oversized tree, however, must stop before either parser
                    # materializes it.
                    continue
                if element_count is None:
                    raise _reader_preflight_error(
                        "non-grid sheet XML structure exceeds the semantic-reader safety "
                        "limit."
                    )
                non_grid_sheet_xml_element_count += element_count
                if (
                    non_grid_sheet_xml_element_count
                    > _OOXML_READER_MAX_NON_GRID_SHEET_XML_ELEMENT_COUNT
                ):
                    raise _reader_preflight_error(
                        "aggregate non-grid sheet XML elements exceed the semantic-reader "
                        "safety limit."
                    )

            # Multiple metadata boundaries inspect a worksheet's DrawingML
            # target before ``openpyxl`` starts.  Do not rely on the later
            # chart boundary's local XML budget: shape, image, and in-content
            # Office Web Add-in readers can each otherwise materialize the
            # same compact, expansive tree first.  Follow the same direct
            # relationship semantics as those readers, but stream the target
            # without retaining its XML tree.  A missing, malformed, or
            # non-XML optional target remains a scanner coverage condition;
            # only a successfully streamed XML structure that exceeds this
            # shared reader budget is an unsafe workbook input.
            drawing_relationship_types = frozenset(
                {
                    _WORKSHEET_DRAWING_RELATIONSHIP.casefold(),
                    _WORKSHEET_STRICT_DRAWING_RELATIONSHIP.casefold(),
                }
            )
            package_relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
            worksheet_drawing_members: set[str] = set()
            # The Table Style scanner inventories canonical ``xl/tables``
            # parts even when they are orphaned, while other raw readers and
            # ``openpyxl`` follow a worksheet table relationship to a target
            # at any safe package path. Cover both routes before either can
            # materialize a repetitive definition tree.
            table_definition_members = {
                member.name
                for member in xml_members
                if _XML_MAPPING_TABLE_PART_PATTERN.fullmatch(member.name)
            }
            for worksheet_member in worksheet_members:
                relationship_member_name = _relationship_part_path(worksheet_member)
                if relationship_member_name not in member_by_name:
                    continue

                def worksheet_related_part_end(
                    element: ElementTree.Element,
                    tags: list[str],
                    *,
                    source_member: str = worksheet_member,
                ) -> None:
                    if (
                        len(tags) != 2
                        or element.tag != package_relationship_tag
                        or element.get("TargetMode", "Internal").casefold()
                        != "internal"
                    ):
                        return
                    raw_target = element.get("Target")
                    if raw_target is None:
                        return
                    target = _normalise_part_target(source_member, raw_target)
                    if target is None or target not in member_by_name:
                        return
                    relationship_type = element.get("Type", "").casefold()
                    if relationship_type in drawing_relationship_types:
                        worksheet_drawing_members.add(target)
                    if relationship_type.rsplit("/", maxsplit=1)[-1] == "table":
                        table_definition_members.add(target)

                try:
                    _stream_ooxml_reader_xml(
                        archive,
                        relationship_member_name,
                        on_end=worksheet_related_part_end,
                    )
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
                    # Raw metadata boundaries retain their established warning
                    # and opaque-coverage behavior for malformed optional
                    # relationship parts.  The all-relationship structural
                    # stream above has already bounded their parser work.
                    continue

            worksheet_drawing_xml_element_count = 0
            for drawing_member in sorted(worksheet_drawing_members, key=str.casefold):
                member = member_by_name[drawing_member]
                if not _is_ooxml_xml_member(member):
                    continue
                try:
                    element_count = _ooxml_xml_structure_element_count_within_budget(
                        archive,
                        drawing_member,
                        maximum_element_count=(
                            _OOXML_READER_MAX_WORKSHEET_DRAWING_PART_XML_ELEMENT_COUNT
                        ),
                    )
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
                    # Preserve the raw boundaries' normal coverage warning for
                    # malformed optional DrawingML while ensuring a valid,
                    # expansive target never reaches any materializing reader.
                    continue
                if element_count is None:
                    raise _reader_preflight_error(
                        "worksheet DrawingML XML structure exceeds the "
                        "semantic-reader safety limit."
                    )
                worksheet_drawing_xml_element_count += element_count
                if (
                    worksheet_drawing_xml_element_count
                    > _OOXML_READER_MAX_WORKSHEET_DRAWING_XML_ELEMENT_COUNT
                ):
                    raise _reader_preflight_error(
                        "aggregate worksheet DrawingML XML elements exceed the "
                        "semantic-reader safety limit."
                    )

            table_definition_xml_element_count = 0
            for table_member in sorted(table_definition_members, key=str.casefold):
                if table_member not in member_by_name:
                    continue
                reader_member(table_member)
                try:
                    element_count = _ooxml_xml_structure_element_count_within_budget(
                        archive,
                        table_member,
                        maximum_element_count=(
                            _OOXML_READER_MAX_TABLE_DEFINITION_PART_XML_ELEMENT_COUNT
                        ),
                    )
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
                    # Preserve the existing metadata readers' coverage warning
                    # or ordinary parser diagnostic for malformed optional
                    # table parts. Only a successfully streamed overage must
                    # stop the readers before an XML tree is allocated.
                    continue
                if element_count is None:
                    raise _reader_preflight_error(
                        "table-definition XML structure exceeds the "
                        "semantic-reader safety limit."
                    )
                table_definition_xml_element_count += element_count
                if (
                    table_definition_xml_element_count
                    > _OOXML_READER_MAX_TABLE_DEFINITION_XML_ELEMENT_COUNT
                ):
                    raise _reader_preflight_error(
                        "aggregate table-definition XML elements exceed the "
                        "semantic-reader safety limit."
                    )

            shared_string_members = _reader_shared_string_xml_paths(
                archive,
                manifest_targets=tuple(manifest_shared_string_members),
            )

            if "xl/styles.xml" in member_by_name:
                reader_member("xl/styles.xml")
                _stream_ooxml_reader_xml(
                    archive,
                    "xl/styles.xml",
                    on_start_with_tags=stylesheet_start,
                    on_end=stylesheet_end,
                )
            for member_name in shared_string_members:
                reader_member(member_name)
                shared_string_opaque_part_xml_element_count = 0
                _stream_ooxml_reader_xml(
                    archive,
                    member_name,
                    on_start=shared_string_start,
                    on_end=shared_string_end,
                )
            for member_name in reader_sheet_members:
                reader_member(member_name)
                if member_name in worksheet_members:
                    worksheet_opaque_root_part_xml_element_count = 0
                    worksheet_extension_list_part_xml_element_count = 0
                _stream_ooxml_reader_xml(
                    archive,
                    member_name,
                    on_start=(worksheet_start if member_name in worksheet_members else None),
                    on_end=(
                        worksheet_end
                        if member_name in worksheet_members
                        else sheet_catalog_end
                    ),
                )
    except WorkbookLoadError:
        raise
    except _OoxmlXmlCharacterDataLimitError as error:
        raise _reader_preflight_error(
            "XML character data exceeds the semantic-reader safety limit."
        ) from error
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        raise _reader_preflight_error(
            "workbook sheet metadata could not be scanned safely."
        ) from error


def _vba_hash(path: Path) -> str | None:
    """Hash the macro payload without loading or executing it."""
    try:
        with ZipFile(path) as archive:
            try:
                digest = hashlib.sha256()
                with archive.open("xl/vbaProject.bin") as payload:
                    for block in iter(lambda: payload.read(1_048_576), b""):
                        digest.update(block)
            except KeyError:
                return None
    except BadZipFile as error:
        raise WorkbookLoadError(f"{path} is not a valid Office Open XML workbook") from error
    return digest.hexdigest()


def _xml_root(archive: ZipFile, member: str) -> ElementTree.Element:
    """Read one OOXML part without accepting document type declarations."""
    return _xml_root_from_payload(archive.read(member))


def _xml_root_from_payload(payload: bytes) -> ElementTree.Element:
    """Parse untrusted XML payload without accepting document type declarations."""
    lexical_violation = _xml_lexical_markup_budget_violation(io.BytesIO(payload))
    if lexical_violation == "start-tag":
        raise ValueError("OOXML metadata XML start tag exceeds the safety limit")
    if lexical_violation is not None:
        raise ValueError(
            "OOXML metadata XML non-character-data markup exceeds the safety limit"
        )
    parser = _ooxml_xml_parser_with_character_data_budget()
    try:
        for offset in range(0, len(payload), _OOXML_READER_XML_LEXICAL_CHUNK_BYTES):
            parser.feed(payload[offset : offset + _OOXML_READER_XML_LEXICAL_CHUNK_BYTES])
        return parser.close()
    except _OoxmlXmlCharacterDataLimitError as error:
        raise ValueError(
            "OOXML metadata XML character data exceeds the safety limit"
        ) from error


def _normalise_package_target(target: str) -> str | None:
    """Turn a workbook relationship target into a safe ZIP member name."""
    return _normalise_part_target("xl/workbook.xml", target)


def _normalise_part_target(source_member: str, target: str) -> str | None:
    """Resolve one internal OOXML relationship target inside the ZIP package."""
    candidate = (
        target.lstrip("/")
        if target.startswith("/")
        else posixpath.join(posixpath.dirname(source_member), target)
    )
    normalised = posixpath.normpath(candidate)
    if normalised == ".." or normalised.startswith("../"):
        return None
    return normalised


def _relationship_part_path(source_member: str) -> str:
    """Return the OPC relationship-part member for one package part."""
    return posixpath.join(
        posixpath.dirname(source_member),
        "_rels",
        f"{posixpath.basename(source_member)}.rels",
    )


def _package_relationships(
    archive: ZipFile,
    source_member: str,
) -> tuple[_PackageRelationship, ...]:
    """Read package relationships without following external targets."""
    relationships = _xml_root(archive, _relationship_part_path(source_member))
    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    parsed: list[_PackageRelationship] = []
    for relationship in relationships.findall(relationship_tag):
        target_mode = relationship.get("TargetMode", "Internal")
        target = relationship.get("Target")
        parsed.append(
            _PackageRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=(
                    _normalise_part_target(source_member, target)
                    if target is not None and target_mode.casefold() == "internal"
                    else None
                ),
                target_mode=target_mode,
                raw_target=target,
            )
        )
    return tuple(parsed)


def _xlm_macro_sheet_target_members(archive: ZipFile) -> frozenset[str]:
    """Return safe workbook targets declared as raw XLM macro sheets.

    A malformed package can point an ordinary worksheet relationship at the
    same target. Secondary worksheet metadata readers must still leave that
    executable XML to the dedicated bounded XLM scanner.
    """
    return frozenset(
        relationship.target
        for relationship in _package_relationships(archive, "xl/workbook.xml")
        if (
            relationship.target is not None
            and relationship.relationship_type in _XLM_MACRO_SHEET_RELATIONSHIPS
        )
    )


def _sheet_xml_parts(archive: ZipFile) -> dict[str, tuple[str, str]]:
    """Map workbook sheet titles to safe OOXML parts and their sheet kind."""
    workbook = _xml_root(archive, "xl/workbook.xml")
    xlm_macro_targets = _xlm_macro_sheet_target_members(archive)
    relationship_targets: dict[str, tuple[str, str]] = {}
    for relationship in _package_relationships(archive, "xl/workbook.xml"):
        sheet_type = relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
        if (
            sheet_type not in {"worksheet", "chartsheet", "dialogsheet"}
            or not relationship.relationship_id
            or relationship.target is None
            or relationship.target in xlm_macro_targets
        ):
            continue
        relationship_targets[relationship.relationship_id] = (
            relationship.target,
            sheet_type,
        )

    sheet_parts: dict[str, tuple[str, str]] = {}
    sheet_tag = f"{{{_SPREADSHEETML_NS}}}sheet"
    relationship_id_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    for sheet in workbook.iter(sheet_tag):
        title = sheet.get("name")
        relationship_id = sheet.get(relationship_id_attribute)
        if not title or not relationship_id:
            continue
        if part := relationship_targets.get(relationship_id):
            sheet_parts[title] = part
    return sheet_parts


def _workbook_tab_order_metadata(path: Path) -> _WorkbookTabOrderMetadata:
    """Read all workbook tab declarations in order without exposing their titles.

    ``openpyxl`` deliberately focuses on worksheet cells and can omit or reject
    workbook tab types such as macro and dialog sheets. Excel documents that
    SHEET and SHEETS include those tab types, so compare the raw OOXML ``sheets``
    catalog instead. Visibility is intentionally excluded: both functions count
    visible, hidden, and very-hidden tabs alike.
    """
    try:
        with ZipFile(path) as archive:
            workbook = _xml_root(archive, "xl/workbook.xml")
            relationship_kinds = {
                relationship.relationship_id: relationship.relationship_type.rsplit(
                    "/", maxsplit=1
                )[-1]
                for relationship in _package_relationships(archive, "xl/workbook.xml")
                if relationship.relationship_id and relationship.relationship_type
            }
    except (BadZipFile, ElementTree.ParseError, KeyError, OSError, ValueError) as error:
        return _WorkbookTabOrderMetadata(
            tab_order=(),
            complete=False,
            worksheet_tab_order=(),
            worksheet_tab_order_complete=False,
            warnings=(
                "FormulaFence could not inspect the raw OOXML workbook tab catalog "
                f"({type(error).__name__}); SHEET and SHEETS workbook-structure "
                "coverage has a gap.",
            ),
        )

    if (
        _xml_local_name(workbook.tag) != "workbook"
        or _xml_namespace(workbook.tag)
        not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
    ):
        return _WorkbookTabOrderMetadata(
            tab_order=(),
            complete=False,
            worksheet_tab_order=(),
            worksheet_tab_order_complete=False,
            warnings=(
                "FormulaFence found an unexpected raw OOXML workbook root; SHEET and "
                "SHEETS workbook-structure coverage has a gap.",
            ),
        )

    sheets = next(
        (
            child
            for child in workbook
            if (
                _xml_local_name(child.tag) == "sheets"
                and _xml_namespace(child.tag)
                in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
            )
        ),
        None,
    )
    if sheets is None:
        return _WorkbookTabOrderMetadata(
            tab_order=(),
            complete=False,
            worksheet_tab_order=(),
            worksheet_tab_order_complete=False,
            warnings=(
                "FormulaFence found no raw OOXML workbook tab catalog; SHEET and SHEETS "
                "workbook-structure coverage has a gap.",
            ),
        )

    tab_order: list[str] = []
    warnings: set[str] = set()
    seen_titles: set[str] = set()
    complete = True
    worksheet_tab_order: list[str] = []
    worksheet_tab_order_complete = True
    known_non_worksheet_kinds = {
        "chartsheet",
        "dialogsheet",
        "xlIntlMacrosheet",
        "xlMacrosheet",
    }
    for sheet in sheets:
        if (
            _xml_local_name(sheet.tag) != "sheet"
            or _xml_namespace(sheet.tag)
            not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
        ):
            complete = False
            worksheet_tab_order_complete = False
            warnings.add(
                "FormulaFence found an unexpected raw OOXML workbook tab declaration; "
                "SHEET and SHEETS workbook-structure coverage has a gap."
            )
            continue
        title = sheet.get("name")
        if not title:
            complete = False
            worksheet_tab_order_complete = False
            warnings.add(
                "FormulaFence found a raw OOXML workbook tab without a name; SHEET and "
                "SHEETS workbook-structure coverage has a gap."
            )
            continue
        title_key = title.casefold()
        if title_key in seen_titles:
            complete = False
            worksheet_tab_order_complete = False
            warnings.add(
                "FormulaFence found duplicate raw OOXML workbook tab names; SHEET and "
                "SHEETS workbook-structure coverage has a gap."
            )
            continue
        seen_titles.add(title_key)
        tab_order.append(title)
        relationship_id = sheet.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id")
        if relationship_id is None:
            relationship_id = sheet.get(f"{{{_STRICT_DOCUMENT_RELATIONSHIP_NS}}}id")
        relationship_kind = (
            relationship_kinds.get(relationship_id) if relationship_id else None
        )
        if relationship_kind == "worksheet":
            worksheet_tab_order.append(title)
        elif relationship_kind not in known_non_worksheet_kinds:
            worksheet_tab_order_complete = False
            warnings.add(
                "FormulaFence could not classify a raw OOXML workbook tab as an ordinary "
                "worksheet or a supported non-worksheet tab; external 3-D portfolio "
                "coverage has a gap."
            )

    if not tab_order:
        complete = False
        worksheet_tab_order_complete = False
        warnings.add(
            "FormulaFence found an empty raw OOXML workbook tab catalog; SHEET and SHEETS "
            "workbook-structure coverage has a gap."
        )
    return _WorkbookTabOrderMetadata(
        tab_order=tuple(tab_order),
        complete=complete,
        worksheet_tab_order=tuple(worksheet_tab_order),
        worksheet_tab_order_complete=worksheet_tab_order_complete,
        warnings=tuple(sorted(warnings)),
    )


def _worksheet_xml_paths(archive: ZipFile) -> dict[str, str]:
    """Map standard worksheet titles to their OOXML worksheet parts."""
    return {
        title: member
        for title, (member, sheet_type) in _sheet_xml_parts(archive).items()
        if sheet_type == "worksheet"
    }


def _worksheet_display_xml_paths(archive: ZipFile) -> tuple[str, ...]:
    """Return worksheet parts in workbook order for both SpreadsheetML variants.

    Most worksheet readers only understand transitional SpreadsheetML, but the
    display boundary is raw OOXML and can safely inspect the equivalent strict
    declarations too. This stays deliberately separate from
    :func:`_worksheet_xml_paths` so it does not broaden the behavior of the
    workbook/cell reader or unrelated raw-control boundaries.
    """
    workbook = _xml_root(archive, "xl/workbook.xml")
    xlm_macro_targets = _xlm_macro_sheet_target_members(archive)
    relationship_targets = {
        relationship.relationship_id: relationship.target
        for relationship in _package_relationships(archive, "xl/workbook.xml")
        if (
            relationship.relationship_id
            and relationship.target is not None
            and relationship.target not in xlm_macro_targets
            and relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
            == "worksheet"
        )
    }
    members: list[str] = []
    for sheet in workbook.iter():
        if (
            _xml_local_name(sheet.tag) != "sheet"
            or _xml_namespace(sheet.tag)
            not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
        ):
            continue
        relationship_id = sheet.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id")
        if relationship_id is None:
            relationship_id = sheet.get(f"{{{_STRICT_DOCUMENT_RELATIONSHIP_NS}}}id")
        if relationship_id and (member := relationship_targets.get(relationship_id)):
            members.append(member)
    return tuple(members)


def _visual_worksheet_xml_paths(archive: ZipFile) -> dict[str, str]:
    """Map worksheet titles to raw transitional or strict worksheet parts.

    Visual-control boundaries inspect strict worksheet records too, even where
    the ordinary cell reader deliberately limits itself to transitional
    SpreadsheetML.
    """
    workbook = _xml_root(archive, "xl/workbook.xml")
    xlm_macro_targets = _xlm_macro_sheet_target_members(archive)
    relationship_targets = {
        relationship.relationship_id: relationship.target
        for relationship in _package_relationships(archive, "xl/workbook.xml")
        if (
            relationship.relationship_id
            and relationship.target is not None
            and relationship.target not in xlm_macro_targets
            and relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
            == "worksheet"
        )
    }
    members: dict[str, str] = {}
    for sheet in workbook.iter():
        if (
            _xml_local_name(sheet.tag) != "sheet"
            or _xml_namespace(sheet.tag)
            not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
        ):
            continue
        title = sheet.get("name")
        relationship_id = sheet.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id")
        if relationship_id is None:
            relationship_id = sheet.get(f"{{{_STRICT_DOCUMENT_RELATIONSHIP_NS}}}id")
        if title and relationship_id and (
            member := relationship_targets.get(relationship_id)
        ):
            members[title] = member
    return members


def _xml_local_name(tag: str) -> str:
    """Return an XML local name without discarding a namespace elsewhere."""
    return tag.rsplit("}", maxsplit=1)[-1]


def _xml_namespace(tag: str) -> str | None:
    """Return an XML namespace, if ``tag`` is namespace-qualified."""
    if not tag.startswith("{"):
        return None
    return tag[1:].split("}", maxsplit=1)[0]


def _xml_display_name(tag: str) -> str:
    """Render a qualified XML name deterministically for local review evidence."""
    if not tag.startswith("{"):
        return tag
    namespace, local_name = tag[1:].split("}", maxsplit=1)
    if prefix := _XML_NAMESPACE_PREFIXES.get(namespace):
        return f"{prefix}{local_name}"
    if namespace == _SPREADSHEETML_NS:
        return local_name
    return f"{{{namespace}}}{local_name}"


def _normalise_guid(value: str) -> str:
    """Remove writer-specific GUID noise while retaining extension structure."""
    return _GUID_PATTERN.sub("{GUID}", value)


def _normalise_conditional_formula(value: str) -> str:
    """Accept the optional leading-equals spelling used by workbook writers."""
    return value[1:] if value.startswith("=") else value


def _is_conditional_guid_link(
    element: ElementTree.Element,
    attribute: str | None = None,
) -> bool:
    """Return whether an x14 GUID only links a base rule to its extension.

    An ``ext`` element's ``uri`` is a semantic extension-type identifier and
    must never be normalised away. The known ``x14:id`` / ``x14:cfRule@id``
    pair, by contrast, is writer-generated linkage between equivalent base and
    extension rule records.
    """
    if _xml_namespace(element.tag) != _OFFICE_2010_SPREADSHEET_NS:
        return False
    local_name = _xml_local_name(element.tag)
    if attribute is None:
        return local_name == "id"
    return local_name == "cfRule" and _xml_local_name(attribute) == "id"


def _xml_fragment(
    element: ElementTree.Element,
    *,
    normalise_guids: bool = False,
    normalise_formulas: bool = False,
    omit_pivot_cache_extension_ids: bool = False,
) -> XmlFragmentSnapshot:
    """Capture an XML subtree with deterministic names and attribute ordering."""
    local_name = _xml_local_name(element.tag)
    formula_value = normalise_formulas and local_name in {"f", "formula"}
    value_object = normalise_formulas and local_name == "cfvo" and element.get("type") == "formula"

    def normalise_value(
        value: str,
        *,
        formula: bool = False,
        guid_link: bool = False,
    ) -> str:
        if formula:
            value = _normalise_conditional_formula(value)
        return _normalise_guid(value) if normalise_guids and guid_link else value

    attributes = tuple(
        sorted(
            (
                _xml_display_name(attribute),
                normalise_value(
                    value,
                    formula=value_object and _xml_local_name(attribute) == "val",
                    guid_link=_is_conditional_guid_link(element, attribute),
                ),
            )
            for attribute, value in element.attrib.items()
            if not (
                omit_pivot_cache_extension_ids
                and _xml_namespace(element.tag) == _OFFICE_2010_SPREADSHEET_NS
                and local_name == "pivotCacheDefinition"
                and _xml_local_name(attribute) == "pivotCacheId"
            )
        )
    )
    children = tuple(
        _xml_fragment(
            child,
            normalise_guids=normalise_guids,
            normalise_formulas=normalise_formulas,
            omit_pivot_cache_extension_ids=omit_pivot_cache_extension_ids,
        )
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    if text is not None:
        text = normalise_value(
            text,
            formula=formula_value,
            guid_link=_is_conditional_guid_link(element),
        )
    return XmlFragmentSnapshot(
        tag=_xml_display_name(element.tag),
        attributes=attributes,
        text=text,
        children=children,
    )


def _conditional_ranges(value: str | None) -> tuple[str, ...]:
    """Return an order-independent, compact inventory of an ``sqref`` value."""
    return tuple(sorted({part for part in (value or "").split() if part}, key=str.casefold))


def _conditional_bool(
    value: str | None,
    default: bool,
    attribute: str,
    warnings: set[str],
) -> bool:
    """Read one OOXML boolean and preserve the schema default when omitted."""
    if value is None:
        return default
    lowered = value.casefold()
    if lowered in {"1", "true"}:
        return True
    if lowered in {"0", "false"}:
        return False
    warnings.add(
        "FormulaFence could not interpret a conditional-formatting "
        f"{attribute} boolean; the schema default was used."
    )
    return default


def _conditional_int(
    element: ElementTree.Element,
    attribute: str,
    warnings: set[str],
) -> int | None:
    """Read an optional integer attribute without making malformed XML look safe."""
    value = element.get(attribute)
    if value is None:
        return None
    try:
        return int(value)
    except ValueError:
        warnings.add(
            "FormulaFence could not interpret a conditional-formatting "
            f"{attribute} integer; the affected rule has a coverage gap."
        )
        return None


def _differential_style_fragments(archive: ZipFile) -> tuple[XmlFragmentSnapshot, ...]:
    """Resolve conditional-format ``dxfId`` values without trusting their order."""
    try:
        styles = _xml_root(archive, "xl/styles.xml")
    except KeyError:
        return ()
    dxfs = styles.find(f"{{{_SPREADSHEETML_NS}}}dxfs")
    if dxfs is None:
        return ()
    return tuple(
        _xml_fragment(dxf, normalise_formulas=True)
        for dxf in dxfs.findall(f"{{{_SPREADSHEETML_NS}}}dxf")
    )


def _conditional_rule_snapshot(
    sheet: str,
    ranges: tuple[str, ...],
    rule: ElementTree.Element,
    differential_styles: tuple[XmlFragmentSnapshot, ...],
    warnings: set[str],
) -> ConditionalFormattingSnapshot:
    """Read one base OOXML ``cfRule`` without calculating its formula."""
    raw_priority = _conditional_int(rule, "priority", warnings)
    if raw_priority is None or raw_priority <= 0:
        warnings.add(
            "FormulaFence could not read a valid conditional-formatting priority; "
            "the affected rule has a coverage gap."
        )
        raw_priority = 0

    rule_type = rule.get("type") or "unknown"
    if rule_type == "unknown":
        warnings.add(
            "FormulaFence found a conditional-formatting rule without a type; "
            "the affected rule has a coverage gap."
        )
    formula_tag = f"{{{_SPREADSHEETML_NS}}}formula"
    formulas = tuple(
        _normalise_conditional_formula(formula.text or "")
        for formula in rule.findall(formula_tag)
    )
    differential_style: XmlFragmentSnapshot | None = None
    dxf_id = rule.get("dxfId")
    if dxf_id is not None:
        parsed_dxf_id = _conditional_int(rule, "dxfId", warnings)
        if parsed_dxf_id is None or not 0 <= parsed_dxf_id < len(differential_styles):
            warnings.add(
                "FormulaFence could not resolve a conditional-formatting differential "
                "style; the affected rule has a coverage gap."
            )
            differential_style = XmlFragmentSnapshot(
                "unresolved-dxf", (("id", dxf_id),)
            )
        else:
            differential_style = differential_styles[parsed_dxf_id]

    def component(name: str) -> XmlFragmentSnapshot | None:
        found = rule.find(f"{{{_SPREADSHEETML_NS}}}{name}")
        return (
            _xml_fragment(found, normalise_formulas=True)
            if found is not None
            else None
        )

    extension_list = rule.find(f"{{{_SPREADSHEETML_NS}}}extLst")
    extensions = (
        tuple(
            _xml_fragment(
                extension,
                normalise_guids=True,
                normalise_formulas=True,
            )
            for extension in extension_list
        )
        if extension_list is not None
        else ()
    )
    known_attributes = {
        "type",
        "priority",
        "dxfId",
        "stopIfTrue",
        "aboveAverage",
        "percent",
        "bottom",
        "operator",
        "text",
        "timePeriod",
        "rank",
        "stdDev",
        "equalAverage",
    }
    unmodelled_attributes = tuple(
        sorted(
            (
                _xml_display_name(attribute),
                value,
            )
            for attribute, value in rule.attrib.items()
            if _xml_local_name(attribute) not in known_attributes
        )
    )
    if unmodelled_attributes:
        warnings.add(
            "FormulaFence found unmodelled conditional-formatting rule attributes; "
            "their raw structure is retained for review."
        )
        extensions += (
            XmlFragmentSnapshot("unmodelled-cf-rule-attributes", unmodelled_attributes),
        )
    known_children = {"formula", "colorScale", "dataBar", "iconSet", "extLst"}
    unmodelled_children = tuple(
        _xml_fragment(child, normalise_guids=True, normalise_formulas=True)
        for child in rule
        if _xml_local_name(child.tag) not in known_children
    )
    if unmodelled_children:
        warnings.add(
            "FormulaFence found unmodelled conditional-formatting rule children; "
            "their raw structure is retained for review."
        )
        extensions += unmodelled_children

    return ConditionalFormattingSnapshot(
        sheet=sheet,
        ranges=ranges,
        priority=raw_priority,
        rule_type=rule_type,
        operator=rule.get("operator"),
        formulas=formulas,
        stop_if_true=_conditional_bool(rule.get("stopIfTrue"), False, "stopIfTrue", warnings),
        above_average=_conditional_bool(
            rule.get("aboveAverage"), True, "aboveAverage", warnings
        ),
        percent=_conditional_bool(rule.get("percent"), False, "percent", warnings),
        bottom=_conditional_bool(rule.get("bottom"), False, "bottom", warnings),
        rank=_conditional_int(rule, "rank", warnings),
        std_dev=_conditional_int(rule, "stdDev", warnings),
        equal_average=_conditional_bool(
            rule.get("equalAverage"), False, "equalAverage", warnings
        ),
        text=rule.get("text"),
        time_period=rule.get("timePeriod"),
        differential_style=differential_style,
        color_scale=component("colorScale"),
        data_bar=component("dataBar"),
        icon_set=component("iconSet"),
        extensions=extensions,
    )


def _worksheet_conditional_formatting_extensions(
    sheet: str,
    worksheet: ElementTree.Element,
) -> tuple[ConditionalFormattingExtensionSnapshot, ...]:
    """Keep worksheet-level x14 conditional-formatting extensions inspectable."""
    extension_snapshots: list[ConditionalFormattingExtensionSnapshot] = []
    extension_list_tag = f"{{{_SPREADSHEETML_NS}}}extLst"
    for extension_list in worksheet.findall(extension_list_tag):
        for extension in extension_list:
            if not any(
                _xml_local_name(element.tag)
                in {"conditionalFormattings", "conditionalFormatting", "cfRule"}
                for element in extension.iter()
            ):
                continue
            extension_snapshots.append(
                ConditionalFormattingExtensionSnapshot(
                    sheet=sheet,
                    fragment=_xml_fragment(
                        extension,
                        normalise_guids=True,
                        normalise_formulas=True,
                    ),
                )
            )
    return tuple(
        sorted(extension_snapshots, key=ConditionalFormattingExtensionSnapshot.sort_key)
    )


def _conditional_formatting_metadata(path: Path) -> _ConditionalFormattingMetadata:
    """Read conditional formatting from OOXML before a library can discard extensions."""
    rules_by_sheet: dict[str, list[tuple[int, int, ConditionalFormattingSnapshot]]] = (
        defaultdict(list)
    )
    extensions: list[ConditionalFormattingExtensionSnapshot] = []
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            differential_styles = _differential_style_fragments(archive)
            conditional_formatting_tag = f"{{{_SPREADSHEETML_NS}}}conditionalFormatting"
            rule_tag = f"{{{_SPREADSHEETML_NS}}}cfRule"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                source_order = 0
                for conditional_formatting in worksheet.findall(conditional_formatting_tag):
                    ranges = _conditional_ranges(conditional_formatting.get("sqref"))
                    if not ranges:
                        warnings.add(
                            "FormulaFence found conditional formatting without target ranges; "
                            "the affected control has a coverage gap."
                        )
                        continue
                    for rule in conditional_formatting.findall(rule_tag):
                        snapshot = _conditional_rule_snapshot(
                            sheet,
                            ranges,
                            rule,
                            differential_styles,
                            warnings,
                        )
                        rules_by_sheet[sheet].append(
                            (snapshot.priority, source_order, snapshot)
                        )
                        source_order += 1
                extensions.extend(
                    _worksheet_conditional_formatting_extensions(sheet, worksheet)
                )
    except (BadZipFile, ElementTree.ParseError, KeyError, OSError, ValueError) as error:
        return _ConditionalFormattingMetadata(
            rules=(),
            extensions=(),
            warnings=(
                "FormulaFence could not inspect conditional-formatting OOXML "
                f"({type(error).__name__}); conditional-formatting controls were not compared.",
            ),
        )

    rules: list[ConditionalFormattingSnapshot] = []
    for _sheet, entries in rules_by_sheet.items():
        priorities = [priority for priority, _, _ in entries]
        if len(set(priorities)) != len(priorities):
            warnings.add(
                "FormulaFence found duplicate conditional-formatting priorities on a "
                "worksheet; the affected controls have a coverage gap."
            )
        for normalized_priority, (_, _, snapshot) in enumerate(
            sorted(entries, key=lambda item: item[:2]),
            start=1,
        ):
            rules.append(replace(snapshot, priority=normalized_priority))
    return _ConditionalFormattingMetadata(
        rules=tuple(sorted(rules, key=ConditionalFormattingSnapshot.sort_key)),
        extensions=tuple(
            sorted(extensions, key=ConditionalFormattingExtensionSnapshot.sort_key)
        ),
        warnings=tuple(sorted(warnings)),
    )


def _protection_bool(
    value: str | None,
    default: bool,
    attribute: str,
    warnings: set[str],
) -> bool:
    """Read a protection boolean while retaining its schema default."""
    if value is None:
        return default
    lowered = value.casefold()
    if lowered in {"1", "true", "on"}:
        return True
    if lowered in {"0", "false", "off"}:
        return False
    warnings.add(
        "FormulaFence could not interpret a protection "
        f"{attribute} boolean; the schema default was used."
    )
    return default


def _protection_int(
    element: ElementTree.Element,
    attribute: str,
    warnings: set[str],
    *,
    context: str,
) -> int | None:
    """Read an optional non-negative protection integer conservatively."""
    value = element.get(attribute)
    if value is None:
        return None
    try:
        parsed = int(value)
    except ValueError:
        warnings.add(
            "FormulaFence could not interpret a "
            f"{context} {attribute} integer; the affected protection has a coverage gap."
        )
        return None
    if parsed < 0:
        warnings.add(
            "FormulaFence found a negative "
            f"{context} {attribute} integer; the affected protection has a coverage gap."
        )
        return None
    return parsed


def _private_protection_signature(
    entries: tuple[tuple[str, str], ...],
) -> str | None:
    """Hash sensitive comparison material without retaining it in output models."""
    if not entries:
        return None
    digest = hashlib.sha256()
    for name, value in entries:
        digest.update(name.encode("utf-8"))
        digest.update(b"\0")
        digest.update(value.encode("utf-8"))
        digest.update(b"\0")
    return digest.hexdigest()


def _merge_opaque_protection_metadata(
    *metadata: ProtectionOpaqueMetadataSnapshot,
) -> ProtectionOpaqueMetadataSnapshot:
    """Combine opaque fragments while leaving their contents private."""
    present = tuple(
        item for item in metadata if item.count and item.signature is not None
    )
    if not present:
        return ProtectionOpaqueMetadataSnapshot()
    return ProtectionOpaqueMetadataSnapshot(
        count=sum(item.count for item in present),
        signature=_private_protection_signature(
            tuple(
                (str(index), item.signature or "")
                for index, item in enumerate(present, start=1)
            )
        ),
    )


def _opaque_protection_metadata(
    element: ElementTree.Element,
    *,
    known_attributes: set[str],
    known_children: set[str] = frozenset(),
) -> ProtectionOpaqueMetadataSnapshot:
    """Fingerprint unmodelled protection XML without exposing its contents."""
    entries: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if _xml_local_name(attribute) not in known_attributes:
            entries.append((f"attribute:{_xml_display_name(attribute)}", value))
    for child in element:
        if _xml_local_name(child.tag) in known_children:
            continue
        entries.append(
            (
                f"child:{_xml_display_name(child.tag)}",
                repr(_xml_fragment(child).sort_key()),
            )
        )
    entries.sort()
    return ProtectionOpaqueMetadataSnapshot(
        count=len(entries),
        signature=_private_protection_signature(tuple(entries)),
    )


def _protection_credential_snapshot(
    element: ElementTree.Element,
    *,
    legacy_attribute: str,
    algorithm_attribute: str,
    hash_attribute: str,
    salt_attribute: str,
    spin_count_attribute: str,
    context: str,
    warnings: set[str],
) -> ProtectionCredentialSnapshot:
    """Record safe verifier metadata while hashing the actual verifier values."""
    attribute_names = (
        legacy_attribute,
        algorithm_attribute,
        hash_attribute,
        salt_attribute,
        spin_count_attribute,
    )
    signature_entries = tuple(
        (attribute, value)
        for attribute in attribute_names
        if (value := element.get(attribute)) is not None
    )
    modern_attributes = (
        algorithm_attribute,
        hash_attribute,
        salt_attribute,
        spin_count_attribute,
    )
    has_modern_verifier = any(element.get(attribute) is not None for attribute in modern_attributes)
    if has_modern_verifier and not (
        element.get(hash_attribute) is not None and element.get(salt_attribute) is not None
    ):
        warnings.add(
            "FormulaFence found incomplete modern "
            f"{context} verifier metadata; its presence is compared but has a coverage gap."
        )
    return ProtectionCredentialSnapshot(
        has_legacy_verifier=element.get(legacy_attribute) is not None,
        has_modern_verifier=has_modern_verifier,
        algorithm=element.get(algorithm_attribute),
        spin_count=_protection_int(
            element,
            spin_count_attribute,
            warnings,
            context=context,
        ),
        signature=_private_protection_signature(signature_entries),
    )


def _workbook_protection_snapshot(
    workbook: ElementTree.Element,
    warnings: set[str],
) -> WorkbookProtectionSnapshot | None:
    """Read workbook protection without passing verifier material to openpyxl."""
    element = workbook.find(f"{{{_SPREADSHEETML_NS}}}workbookProtection")
    if element is None:
        return None
    workbook_credential = _protection_credential_snapshot(
        element,
        legacy_attribute="workbookPassword",
        algorithm_attribute="workbookAlgorithmName",
        hash_attribute="workbookHashValue",
        salt_attribute="workbookSaltValue",
        spin_count_attribute="workbookSpinCount",
        context="workbook-protection",
        warnings=warnings,
    )
    revisions_credential = _protection_credential_snapshot(
        element,
        legacy_attribute="revisionsPassword",
        algorithm_attribute="revisionsAlgorithmName",
        hash_attribute="revisionsHashValue",
        salt_attribute="revisionsSaltValue",
        spin_count_attribute="revisionsSpinCount",
        context="revision-protection",
        warnings=warnings,
    )
    return WorkbookProtectionSnapshot(
        lock_structure=_protection_bool(
            element.get("lockStructure"), False, "lockStructure", warnings
        ),
        lock_windows=_protection_bool(
            element.get("lockWindows"), False, "lockWindows", warnings
        ),
        lock_revision=_protection_bool(
            element.get("lockRevision"), False, "lockRevision", warnings
        ),
        workbook_credential=workbook_credential,
        revisions_credential=revisions_credential,
        opaque_metadata=_opaque_protection_metadata(
            element,
            known_attributes={
                "lockStructure",
                "lockWindows",
                "lockRevision",
                "workbookPassword",
                "workbookAlgorithmName",
                "workbookHashValue",
                "workbookSaltValue",
                "workbookSpinCount",
                "revisionsPassword",
                "revisionsAlgorithmName",
                "revisionsHashValue",
                "revisionsSaltValue",
                "revisionsSpinCount",
            },
        ),
    )


def _sheet_protection_snapshot(
    sheet: str,
    sheet_type: str,
    root: ElementTree.Element,
    warnings: set[str],
) -> SheetProtectionSnapshot | None:
    """Read one sheet-protection declaration with effective action defaults."""
    element = root.find(f"{{{_SPREADSHEETML_NS}}}sheetProtection")
    if element is None:
        return None
    actions = (
        _CHART_SHEET_PROTECTION_ACTIONS
        if sheet_type == "chartsheet"
        else _SHEET_PROTECTION_ACTIONS
    )
    enabled = (
        any(
            _protection_bool(element.get(attribute), default, attribute, warnings)
            for attribute, _name, default in actions
        )
        if sheet_type == "chartsheet"
        else _protection_bool(element.get("sheet"), False, "sheet", warnings)
    )
    locked_actions = (
        tuple(
            name
            for attribute, name, default in actions
            if _protection_bool(element.get(attribute), default, attribute, warnings)
        )
        if enabled
        else ()
    )
    credential = _protection_credential_snapshot(
        element,
        legacy_attribute="password",
        algorithm_attribute="algorithmName",
        hash_attribute="hashValue",
        salt_attribute="saltValue",
        spin_count_attribute="spinCount",
        context="sheet-protection",
        warnings=warnings,
    )
    known_attributes = {
        *(attribute for attribute, _name, _default in actions),
        "password",
        "algorithmName",
        "hashValue",
        "saltValue",
        "spinCount",
    }
    if sheet_type == "chartsheet":
        known_attributes.add("content")
    else:
        known_attributes.add("sheet")
    return SheetProtectionSnapshot(
        sheet=sheet,
        sheet_type=sheet_type,
        enabled=enabled,
        locked_actions=locked_actions,
        credential=credential,
        opaque_metadata=_opaque_protection_metadata(
            element,
            known_attributes=known_attributes,
        ),
    )


def _protected_range_snapshots(
    sheet: str,
    root: ElementTree.Element,
    warnings: set[str],
) -> tuple[tuple[ProtectedRangeSnapshot, ...], ProtectionOpaqueMetadataSnapshot]:
    """Read protected ranges while redacting names and security descriptors."""
    container = root.find(f"{{{_SPREADSHEETML_NS}}}protectedRanges")
    if container is None:
        return (), ProtectionOpaqueMetadataSnapshot()
    snapshots: list[ProtectedRangeSnapshot] = []
    range_tag = f"{{{_SPREADSHEETML_NS}}}protectedRange"
    for protected_range in container.findall(range_tag):
        ranges = _conditional_ranges(protected_range.get("sqref"))
        if not ranges:
            warnings.add(
                "FormulaFence found a protected range without target references; "
                "the affected permission has a coverage gap."
            )
        name = protected_range.get("name")
        if name is None:
            warnings.add(
                "FormulaFence found a protected range without its required name; "
                "the affected permission has a coverage gap."
            )
        security_descriptor = protected_range.get("securityDescriptor")
        credential = _protection_credential_snapshot(
            protected_range,
            legacy_attribute="password",
            algorithm_attribute="algorithmName",
            hash_attribute="hashValue",
            salt_attribute="saltValue",
            spin_count_attribute="spinCount",
            context="protected-range",
            warnings=warnings,
        )
        snapshots.append(
            ProtectedRangeSnapshot(
                sheet=sheet,
                ranges=ranges,
                has_name=name is not None,
                name_signature=_private_protection_signature(
                    (("name", name),) if name is not None else ()
                ),
                credential=credential,
                has_security_descriptor=security_descriptor is not None,
                security_descriptor_signature=_private_protection_signature(
                    (("securityDescriptor", security_descriptor),)
                    if security_descriptor is not None
                    else ()
                ),
                opaque_metadata=_opaque_protection_metadata(
                    protected_range,
                    known_attributes={
                        "name",
                        "sqref",
                        "password",
                        "algorithmName",
                        "hashValue",
                        "saltValue",
                        "spinCount",
                        "securityDescriptor",
                    },
                ),
            )
        )
    return (
        tuple(sorted(snapshots, key=ProtectedRangeSnapshot.sort_key)),
        _opaque_protection_metadata(
            container,
            known_attributes=set(),
            known_children={"protectedRange"},
        ),
    )


def _style_index(
    element: ElementTree.Element,
    attribute: str,
    warnings: set[str],
    *,
    context: str,
) -> int | None:
    """Read a zero-based style index without silently accepting malformed XML."""
    value = element.get(attribute)
    if value is None:
        return None
    try:
        parsed = int(value)
    except ValueError:
        warnings.add(
            "FormulaFence could not interpret a "
            f"{context} style index; the affected cell-protection assignment has a coverage gap."
        )
        return None
    if parsed < 0:
        warnings.add(
            "FormulaFence found a negative "
            f"{context} style index; the affected cell-protection assignment has a coverage gap."
        )
        return None
    return parsed


def _xf_protection(
    xf: ElementTree.Element,
    inherited: _StyleProtection,
    warnings: set[str],
    *,
    context: str,
) -> _StyleProtection:
    """Resolve the protection part of one XF without inspecting formatting data."""
    protection = xf.find(f"{{{_SPREADSHEETML_NS}}}protection")
    if protection is None:
        return inherited
    if (
        any(
            _xml_local_name(attribute) not in {"locked", "hidden"}
            for attribute in protection.attrib
        )
        or list(protection)
    ):
        warnings.add(
            "FormulaFence found unmodelled cell-protection style metadata; "
            "the affected assignment has a coverage gap."
        )
    applies = _protection_bool(
        xf.get("applyProtection"),
        True,
        "applyProtection",
        warnings,
    )
    if not applies:
        return inherited
    return _StyleProtection(
        locked=_protection_bool(
            protection.get("locked"), True, f"{context} locked", warnings
        ),
        hidden=_protection_bool(
            protection.get("hidden"), False, f"{context} hidden", warnings
        ),
        explicit=True,
    )


def _styles_with_protection(
    archive: ZipFile,
    warnings: set[str],
) -> tuple[_StyleProtection, tuple[_StyleProtection, ...]]:
    """Return the base default and effective cell-XF protection table."""
    default = _StyleProtection(locked=True, hidden=False)
    try:
        styles = _xml_root(archive, "xl/styles.xml")
    except KeyError:
        return default, (default,)
    style_xfs = styles.find(f"{{{_SPREADSHEETML_NS}}}cellStyleXfs")
    base_styles: list[_StyleProtection] = []
    if style_xfs is not None:
        for xf in style_xfs.findall(f"{{{_SPREADSHEETML_NS}}}xf"):
            base_styles.append(
                _xf_protection(xf, default, warnings, context="base-cell-style")
            )
    if not base_styles:
        base_styles.append(default)

    cell_xfs = styles.find(f"{{{_SPREADSHEETML_NS}}}cellXfs")
    effective_styles: list[_StyleProtection] = []
    if cell_xfs is not None:
        for xf in cell_xfs.findall(f"{{{_SPREADSHEETML_NS}}}xf"):
            xf_id = _style_index(xf, "xfId", warnings, context="cell-XF")
            inherited = default
            if xf_id is not None:
                if xf_id >= len(base_styles):
                    warnings.add(
                        "FormulaFence found a cell-XF with an unknown base style; "
                        "the affected cell-protection assignment has a coverage gap."
                    )
                else:
                    inherited = base_styles[xf_id]
            effective_styles.append(
                _xf_protection(xf, inherited, warnings, context="cell-style")
            )
    if not effective_styles:
        effective_styles.append(default)
    return effective_styles[0], tuple(effective_styles)


def _style_is_protection_relevant(
    style: _StyleProtection,
    default: _StyleProtection,
) -> bool:
    """Return whether a styled record can alter visible protection behavior."""
    return style.explicit or (style.locked, style.hidden) != (default.locked, default.hidden)


def _style_for_assignment(
    element: ElementTree.Element,
    attribute: str,
    styles: tuple[_StyleProtection, ...],
    warnings: set[str],
    *,
    context: str,
) -> _StyleProtection | None:
    """Resolve a direct style reference, returning ``None`` when absent/invalid."""
    style_index = _style_index(element, attribute, warnings, context=context)
    if style_index is None:
        return None
    if style_index >= len(styles):
        warnings.add(
            "FormulaFence found a "
            f"{context} style index outside the workbook style table; "
            "the affected cell-protection assignment has a coverage gap."
        )
        return None
    return styles[style_index]


def _column_span(
    element: ElementTree.Element,
    warnings: set[str],
) -> tuple[int, int, str] | None:
    """Return a compact column span from a raw ``col`` record."""
    start = _protection_int(element, "min", warnings, context="column-protection")
    end = _protection_int(element, "max", warnings, context="column-protection")
    if start is None or end is None or start < 1 or end < start or end > 16_384:
        warnings.add(
            "FormulaFence could not interpret a column-protection span; "
            "the affected assignment has a coverage gap."
        )
        return None
    try:
        start_column = get_column_letter(start)
        end_column = get_column_letter(end)
    except ValueError:
        warnings.add(
            "FormulaFence found a column-protection span outside Excel's column range; "
            "the affected assignment has a coverage gap."
        )
        return None
    return start, end, f"{start_column}:{end_column}"


def _cell_protection_assignments(
    archive: ZipFile,
    sheet_parts: Mapping[str, tuple[str, str]],
    sheet_protections: tuple[SheetProtectionSnapshot, ...],
    warnings: set[str],
) -> tuple[
    CellProtectionDefaultSnapshot | None,
    tuple[CellProtectionAssignmentSnapshot, ...],
]:
    """Read sparse direct cell/row/column protection assignments from OOXML.

    The inventory deliberately retains raw assignment scopes instead of
    expanding rows, columns, or styled rectangles into cells. It records only
    normal protected sheets, because locked/hidden cell styles are inactive on
    an unprotected sheet.
    """
    protected_sheets = {
        protection.sheet
        for protection in sheet_protections
        if protection.enabled and protection.sheet_type in {"worksheet", "dialogsheet"}
    }
    if not protected_sheets:
        return None, ()
    default, styles = _styles_with_protection(archive, warnings)
    assignments: set[CellProtectionAssignmentSnapshot] = set()
    row_tag = f"{{{_SPREADSHEETML_NS}}}row"
    cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
    column_tag = f"{{{_SPREADSHEETML_NS}}}col"
    for sheet in sorted(protected_sheets, key=str.casefold):
        part = sheet_parts.get(sheet)
        if part is None:
            warnings.add(
                "FormulaFence could not locate OOXML for a protected worksheet; "
                "cell-protection assignments have a coverage gap."
            )
            continue
        member, _sheet_type = part
        worksheet = _xml_root(archive, member)
        raw_rows: list[tuple[int, _StyleProtection]] = []
        raw_columns: list[tuple[int, int, str, _StyleProtection]] = []
        for row in worksheet.iter(row_tag):
            style = _style_for_assignment(
                row, "s", styles, warnings, context="row-protection"
            )
            if style is None:
                continue
            row_number = _protection_int(row, "r", warnings, context="row-protection")
            if row_number is None or row_number < 1:
                warnings.add(
                    "FormulaFence could not interpret a row-protection target; "
                    "the affected assignment has a coverage gap."
                )
                continue
            raw_rows.append((row_number, style))
        for column in worksheet.iter(column_tag):
            style = _style_for_assignment(
                column, "style", styles, warnings, context="column-protection"
            )
            if style is None or (span := _column_span(column, warnings)) is None:
                continue
            start_column, end_column, target = span
            raw_columns.append((start_column, end_column, target, style))

        relevant_rows = {
            row_number
            for row_number, style in raw_rows
            if _style_is_protection_relevant(style, default)
        }
        relevant_columns = [
            column_target
            for _start_column, _end_column, column_target, style in raw_columns
            if _style_is_protection_relevant(style, default)
        ]
        for row_number, style in raw_rows:
            if not _style_is_protection_relevant(style, default) and not relevant_columns:
                continue
            assignments.add(
                CellProtectionAssignmentSnapshot(
                    sheet=sheet,
                    scope="row",
                    target=str(row_number),
                    locked=style.locked,
                    hidden=style.hidden,
                )
            )
        for _start_column, _end_column, target, style in raw_columns:
            if not _style_is_protection_relevant(style, default) and not relevant_rows:
                continue
            assignments.add(
                CellProtectionAssignmentSnapshot(
                    sheet=sheet,
                    scope="column",
                    target=target,
                    locked=style.locked,
                    hidden=style.hidden,
                )
            )

        for cell in worksheet.iter(cell_tag):
            style = _style_for_assignment(
                cell, "s", styles, warnings, context="cell-protection"
            )
            if style is None:
                continue
            coordinate = cell.get("r")
            if not coordinate:
                warnings.add(
                    "FormulaFence found a styled cell without a coordinate; "
                    "the affected cell-protection assignment has a coverage gap."
                )
                continue
            match = re.fullmatch(r"([A-Za-z]+)([1-9][0-9]*)", coordinate)
            if match is None:
                warnings.add(
                    "FormulaFence could not interpret a styled cell coordinate; "
                    "the affected cell-protection assignment has a coverage gap."
                )
                continue
            column_letters, raw_row_number = match.groups()
            row_number = int(raw_row_number)
            try:
                column_number = column_index_from_string(column_letters)
            except ValueError:
                warnings.add(
                    "FormulaFence could not interpret a styled cell column; "
                    "the affected cell-protection assignment has a coverage gap."
                )
                continue
            intersects_relevant_column = any(
                start_column <= column_number <= end_column
                for start_column, end_column, _target, style in raw_columns
                if _style_is_protection_relevant(style, default)
            )
            if not (
                _style_is_protection_relevant(style, default)
                or row_number in relevant_rows
                or intersects_relevant_column
            ):
                continue
            assignments.add(
                CellProtectionAssignmentSnapshot(
                    sheet=sheet,
                    scope="cell",
                    target=coordinate.upper(),
                    locked=style.locked,
                    hidden=style.hidden,
                )
            )
    return (
        CellProtectionDefaultSnapshot(locked=default.locked, hidden=default.hidden),
        tuple(sorted(assignments, key=CellProtectionAssignmentSnapshot.sort_key)),
    )


def _protection_metadata(path: Path) -> _ProtectionMetadata:
    """Read protection controls directly from OOXML before a library drops data."""
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            workbook = _xml_root(archive, "xl/workbook.xml")
            sheet_parts = _sheet_xml_parts(archive)
            workbook_protection = _workbook_protection_snapshot(workbook, warnings)
            sheet_protections: dict[str, SheetProtectionSnapshot] = {}
            protected_ranges: list[ProtectedRangeSnapshot] = []
            for sheet, (member, sheet_type) in sheet_parts.items():
                root = _xml_root(archive, member)
                sheet_protection = _sheet_protection_snapshot(
                    sheet, sheet_type, root, warnings
                )
                ranges: tuple[ProtectedRangeSnapshot, ...] = ()
                range_container_opaque = ProtectionOpaqueMetadataSnapshot()
                if sheet_type != "chartsheet":
                    ranges, range_container_opaque = _protected_range_snapshots(
                        sheet, root, warnings
                    )
                    protected_ranges.extend(ranges)
                if sheet_protection is not None:
                    sheet_protections[sheet] = replace(
                        sheet_protection,
                        opaque_metadata=_merge_opaque_protection_metadata(
                            sheet_protection.opaque_metadata,
                            range_container_opaque,
                        ),
                    )
                elif range_container_opaque.present:
                    sheet_protections[sheet] = SheetProtectionSnapshot(
                        sheet=sheet,
                        sheet_type=sheet_type,
                        enabled=False,
                        locked_actions=(),
                        opaque_metadata=range_container_opaque,
                    )
            sorted_sheet_protections = tuple(
                sorted(sheet_protections.values(), key=SheetProtectionSnapshot.sort_key)
            )
            cell_default, cell_assignments = _cell_protection_assignments(
                archive,
                sheet_parts,
                sorted_sheet_protections,
                warnings,
            )
    except (BadZipFile, ElementTree.ParseError, KeyError, OSError, ValueError) as error:
        return _ProtectionMetadata(
            workbook_protection=None,
            sheet_protections=(),
            protected_ranges=(),
            cell_protection_default=None,
            cell_protection_assignments=(),
            warnings=(
                "FormulaFence could not inspect protection OOXML "
                f"({type(error).__name__}); protection controls were not compared.",
            ),
        )
    return _ProtectionMetadata(
        workbook_protection=workbook_protection,
        sheet_protections=sorted_sheet_protections,
        protected_ranges=tuple(
            sorted(protected_ranges, key=ProtectedRangeSnapshot.sort_key)
        ),
        cell_protection_default=cell_default,
        cell_protection_assignments=cell_assignments,
        warnings=tuple(sorted(warnings)),
    )


def _external_data_bool(
    value: str | None,
    default: bool,
    attribute: str,
    warnings: set[str],
    *,
    context: str,
) -> bool:
    """Read an OOXML external-data boolean while retaining its default."""
    if value is None:
        return default
    lowered = value.casefold()
    if lowered in {"1", "true", "on"}:
        return True
    if lowered in {"0", "false", "off"}:
        return False
    warnings.add(
        "FormulaFence could not interpret an external-data "
        f"{context} {attribute} boolean; the schema default was used."
    )
    return default


def _external_data_unsigned_int(
    element: ElementTree.Element,
    attribute: str,
    default: int | None,
    warnings: set[str],
    *,
    context: str,
    maximum: int = 4_294_967_295,
) -> int | None:
    """Read a non-negative OOXML integer without accepting malformed values."""
    value = element.get(attribute)
    if value is None:
        return default
    try:
        parsed = int(value)
    except ValueError:
        warnings.add(
            "FormulaFence could not interpret an external-data "
            f"{context} {attribute} integer; the affected control has a coverage gap."
        )
        return default
    if not 0 <= parsed <= maximum:
        warnings.add(
            "FormulaFence found an out-of-range external-data "
            f"{context} {attribute} integer; the affected control has a coverage gap."
        )
        return default
    return parsed


def _external_data_enum(
    value: str | None,
    default: str,
    values: Mapping[str, str],
    warnings: set[str],
    *,
    context: str,
    attribute: str,
) -> str:
    """Normalize a safe OOXML enumeration without exposing invalid values."""
    if value is None:
        return default
    if normalised := values.get(value):
        return normalised
    warnings.add(
        "FormulaFence found an unrecognized external-data "
        f"{context} {attribute} value; the affected control has a coverage gap."
    )
    return "unrecognized"


def _private_external_data_signature(
    entries: tuple[tuple[str, str], ...],
) -> str | None:
    """Hash source or identity material without retaining it in output models."""
    if not entries:
        return None
    digest = hashlib.sha256()
    for name, value in entries:
        digest.update(name.encode("utf-8"))
        digest.update(b"\0")
        digest.update(value.encode("utf-8"))
        digest.update(b"\0")
    return digest.hexdigest()


def _external_data_opaque_metadata(
    element: ElementTree.Element,
    *,
    known_attributes: frozenset[str],
    known_children: frozenset[str] = frozenset(),
    omit_pivot_cache_extension_ids: bool = False,
) -> ExternalDataOpaqueMetadataSnapshot:
    """Fingerprint unknown external-data XML without serializing its contents."""
    entries: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if _xml_local_name(attribute) not in known_attributes:
            entries.append((f"attribute:{_xml_display_name(attribute)}", value))
    for child in element:
        if _xml_local_name(child.tag) in known_children:
            continue
        entries.append(
            (
                f"child:{_xml_display_name(child.tag)}",
                repr(
                    _xml_fragment(
                        child,
                        omit_pivot_cache_extension_ids=omit_pivot_cache_extension_ids,
                    ).sort_key()
                ),
            )
        )
    entries.sort()
    return ExternalDataOpaqueMetadataSnapshot(
        count=len(entries),
        signature=_private_external_data_signature(tuple(entries)),
    )


def _private_payload_signature(payload: bytes) -> str:
    """Hash opaque bytes without retaining them in any reviewable model."""
    return hashlib.sha256(payload).hexdigest()


def _private_archive_member_payload_signature(
    archive: ZipFile,
    info: ZipInfo,
) -> str | None:
    """Hash one bounded archive member without materializing its payload."""
    digest = hashlib.sha256()
    try:
        with archive.open(info) as payload:
            for block in iter(lambda: payload.read(1_048_576), b""):
                digest.update(block)
    except (BadZipFile, OSError, RuntimeError, ValueError):
        return None
    return digest.hexdigest()


def _is_opc_relationship_member(member: str) -> bool:
    """Return whether one ZIP member has an OPC relationship-part location."""
    return member == "_rels/.rels" or (
        member.endswith(".rels") and "/_rels/" in member
    )


def _opc_relationship_source_member(member: str) -> str | None:
    """Return the private source part for one canonical OPC relationship part."""
    if member == "_rels/.rels":
        return "@package"
    if member.startswith("/") or "\\" in member:
        return None
    directory, separator, filename = member.partition("/_rels/")
    if (
        not separator
        or not directory
        or "/" in filename
        or not filename.endswith(".rels")
    ):
        return None
    source_name = filename.removesuffix(".rels")
    if not source_name:
        return None
    source_member = f"{directory}/{source_name}"
    if any(
        not segment or segment in {".", ".."}
        for segment in source_member.split("/")
    ):
        return None
    return source_member


def _external_relationship_xml_payload(
    archive: ZipFile,
    info: ZipInfo,
    warnings: set[str],
    budget: _ExternalRelationshipBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded raw OPC relationship XML part."""
    metadata = repr((info.filename, info.file_size, info.compress_size, info.CRC))
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded package-wide external-relationship XML "
            "part count; affected external relationships were not compared."
        )
        return None, _private_external_data_signature(
            (("external-relationship-part-count-budget-exhausted", metadata),)
        )
    budget.remaining_parts -= 1
    if info.file_size > _EXTERNAL_RELATIONSHIP_MAX_XML_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized package relationship XML "
            "part; affected external relationships were not compared."
        )
        return None, _private_external_data_signature(
            (("oversized-external-relationship-part", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded package-wide external-relationship XML "
            "read budget; affected external relationships were not compared."
        )
        return None, _private_external_data_signature(
            (("external-relationship-read-budget-exhausted", metadata),)
        )
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(info), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a package relationship XML part while "
            f"inspecting external relationships ({type(error).__name__}); affected "
            "relationships were not compared."
        )
        return None, _private_external_data_signature(
            (("unreadable-external-relationship-part", metadata),)
        )


def _external_relationship_kind(relationship_type: str) -> str:
    """Classify a relationship type without retaining its private URI publicly."""
    normalized = relationship_type.casefold()
    if normalized.endswith("/hyperlink"):
        return "hyperlink"
    if normalized.endswith("/image"):
        return "image"
    return "other"


def _external_relationship_metadata(path: Path) -> _ExternalRelationshipMetadata:
    """Inventory every bounded OPC relationship whose target is external.

    This deliberately starts at relationship parts instead of feature-specific
    workbook XML. OPC allows any package or part source to target an external
    URI, including a source that FormulaFence does not otherwise model.
    """
    warnings: set[str] = set()
    signature_entries: list[tuple[str, str]] = []
    external_relationship_part_members: set[str] = set()
    external_relationship_sources: set[str] = set()
    external_relationship_count = 0
    external_hyperlink_relationship_count = 0
    external_image_relationship_count = 0
    external_other_relationship_count = 0
    unrecognized_relationship_count = 0
    try:
        with ZipFile(path) as archive:
            relationship_infos = sorted(
                (
                    info
                    for info in archive.infolist()
                    if not info.is_dir() and _is_opc_relationship_member(info.filename)
                ),
                key=lambda info: (
                    info.filename.casefold(),
                    info.filename,
                    info.CRC,
                    info.file_size,
                    info.compress_size,
                    info.header_offset,
                ),
            )
            archive_members = {info.filename for info in archive.infolist()}
            relationship_part_counts = Counter(
                info.filename for info in relationship_infos
            )
            budget = _ExternalRelationshipBudget()
            relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
            relationships_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationships"

            for info in relationship_infos:
                source_member = _opc_relationship_source_member(info.filename)
                if source_member is None:
                    warnings.add(
                        "FormulaFence found a relationship-like package member outside "
                        "the OPC relationship-part layout; affected external "
                        "relationships have a coverage gap."
                    )
                    unrecognized_relationship_count += 1
                    signature_entries.append(
                        (
                            "invalid-external-relationship-member",
                            repr(
                                (
                                    info.filename,
                                    info.file_size,
                                    info.compress_size,
                                    info.CRC,
                                )
                            ),
                        )
                    )
                    continue

                part_is_unrecognized = False
                if relationship_part_counts[info.filename] > 1:
                    warnings.add(
                        "FormulaFence found duplicate OPC relationship parts; affected "
                        "external relationships have a coverage gap."
                    )
                    unrecognized_relationship_count += 1
                    part_is_unrecognized = True
                    signature_entries.append(
                        (
                            "duplicate-external-relationship-part",
                            repr(
                                (
                                    source_member,
                                    relationship_part_counts[info.filename],
                                    info.file_size,
                                    info.compress_size,
                                    info.CRC,
                                )
                            ),
                        )
                    )
                if (
                    source_member != "@package"
                    and (
                        source_member not in archive_members
                        or source_member.endswith(".rels")
                    )
                ):
                    warnings.add(
                        "FormulaFence found an orphaned or invalid OPC relationship "
                        "source; affected external relationships have a coverage gap."
                    )
                    unrecognized_relationship_count += 1
                    part_is_unrecognized = True
                    signature_entries.append(
                        (
                            "orphaned-external-relationship-source",
                            source_member,
                        )
                    )

                payload, fallback_signature = _external_relationship_xml_payload(
                    archive,
                    info,
                    warnings,
                    budget,
                )
                if payload is None:
                    unrecognized_relationship_count += 1
                    signature_entries.append(
                        (
                            "uninspected-external-relationship-part",
                            repr((source_member, fallback_signature or "")),
                        )
                    )
                    continue
                try:
                    root = _xml_root_from_payload(payload)
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                    warnings.add(
                        "FormulaFence could not parse a package relationship XML part "
                        f"while inspecting external relationships ({type(error).__name__}); "
                        "affected relationships were not compared."
                    )
                    unrecognized_relationship_count += 1
                    signature_entries.append(
                        (
                            "malformed-external-relationship-part",
                            repr((source_member, _private_payload_signature(payload))),
                        )
                    )
                    continue
                if root.tag != relationships_tag:
                    warnings.add(
                        "FormulaFence found an unexpected OPC relationship root; affected "
                        "external relationships have a coverage gap."
                    )
                    unrecognized_relationship_count += 1
                    signature_entries.append(
                        (
                            "unexpected-external-relationship-root",
                            repr((source_member, _private_payload_signature(payload))),
                        )
                    )
                    continue

                if root.attrib or (root.text and root.text.strip()):
                    warnings.add(
                        "FormulaFence found unsupported OPC relationship-root metadata; "
                        "affected external relationships have a coverage gap."
                    )
                    unrecognized_relationship_count += 1
                    part_is_unrecognized = True
                    signature_entries.append(
                        (
                            "unrecognized-external-relationship-root-metadata",
                            repr(
                                (
                                    source_member,
                                    tuple(sorted(root.attrib.items())),
                                    root.text.strip() if root.text and root.text.strip() else "",
                                )
                            ),
                        )
                    )

                relationship_ids: Counter[str] = Counter()
                for child in root:
                    if child.tag != relationship_tag:
                        warnings.add(
                            "FormulaFence found unsupported OPC relationship XML; "
                            "affected external relationships have a coverage gap."
                        )
                        unrecognized_relationship_count += 1
                        part_is_unrecognized = True
                        signature_entries.append(
                            (
                                "unrecognized-external-relationship-child",
                                repr(
                                    (
                                        source_member,
                                        _private_payload_signature(
                                            ElementTree.tostring(child, encoding="utf-8")
                                        ),
                                    )
                                ),
                            )
                        )
                        continue

                    relationship_id = child.get("Id")
                    if relationship_id:
                        relationship_ids[relationship_id] += 1
                    relationship_type = child.get("Type", "")
                    target = child.get("Target")
                    target_mode = child.get("TargetMode", "Internal")
                    normalized_target_mode = target_mode.casefold()
                    unknown_attributes = tuple(
                        sorted(
                            (attribute, value)
                            for attribute, value in child.attrib.items()
                            if attribute not in _EXTERNAL_RELATIONSHIP_KNOWN_ATTRIBUTES
                        )
                    )
                    malformed_reasons: list[str] = []
                    if not relationship_id:
                        malformed_reasons.append("missing-id")
                    if not relationship_type:
                        malformed_reasons.append("missing-type")
                    if not target:
                        malformed_reasons.append("missing-target")
                    if normalized_target_mode not in {"internal", "external"}:
                        malformed_reasons.append("invalid-target-mode")
                    if unknown_attributes:
                        malformed_reasons.append("unknown-attributes")
                    if child.text and child.text.strip():
                        malformed_reasons.append("text-content")
                    if list(child):
                        malformed_reasons.append("child-content")

                    if normalized_target_mode == "external":
                        external_relationship_count += 1
                        external_relationship_part_members.add(info.filename)
                        external_relationship_sources.add(source_member)
                        kind = _external_relationship_kind(relationship_type)
                        if kind == "hyperlink":
                            external_hyperlink_relationship_count += 1
                        elif kind == "image":
                            external_image_relationship_count += 1
                        else:
                            external_other_relationship_count += 1
                        signature_entries.append(
                            (
                                "external-relationship",
                                repr(
                                    (
                                        source_member,
                                        relationship_type,
                                        normalized_target_mode,
                                        target or "",
                                        unknown_attributes,
                                    )
                                ),
                            )
                        )

                    if malformed_reasons:
                        warnings.add(
                            "FormulaFence found malformed or unsupported OPC relationship "
                            "metadata; affected external relationships have a coverage gap."
                        )
                        unrecognized_relationship_count += 1
                        part_is_unrecognized = True
                        signature_entries.append(
                            (
                                "malformed-external-relationship",
                                repr(
                                    (
                                        source_member,
                                        relationship_type,
                                        normalized_target_mode,
                                        target or "",
                                        unknown_attributes,
                                        tuple(sorted(malformed_reasons)),
                                    )
                                ),
                            )
                        )

                duplicate_id_count = sum(
                    count
                    for count in relationship_ids.values()
                    if count > 1
                )
                if duplicate_id_count:
                    warnings.add(
                        "FormulaFence found duplicate OPC relationship IDs; affected "
                        "external relationships have a coverage gap."
                    )
                    unrecognized_relationship_count += duplicate_id_count
                    part_is_unrecognized = True
                    signature_entries.append(
                        (
                            "duplicate-external-relationship-identifiers",
                            repr((source_member, duplicate_id_count)),
                        )
                    )

                if part_is_unrecognized and info.filename not in external_relationship_part_members:
                    # Keep the part itself private but ensure that a malformed part
                    # which contains no recognizable external edge remains diff-visible.
                    signature_entries.append(
                        ("unrecognized-external-relationship-part", source_member)
                    )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _ExternalRelationshipMetadata(
            ExternalRelationshipSnapshot(
                unrecognized_relationship_count=1,
                relationship_signature=_private_external_data_signature(
                    (("external-relationship-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect package-wide external relationships "
                f"({type(error).__name__}); affected relationships were not compared.",
            ),
        )

    return _ExternalRelationshipMetadata(
        ExternalRelationshipSnapshot(
            external_relationship_part_count=len(external_relationship_part_members),
            external_relationship_source_count=len(external_relationship_sources),
            external_relationship_count=external_relationship_count,
            external_hyperlink_relationship_count=(
                external_hyperlink_relationship_count
            ),
            external_image_relationship_count=external_image_relationship_count,
            external_other_relationship_count=external_other_relationship_count,
            unrecognized_relationship_count=unrecognized_relationship_count,
            relationship_signature=_private_external_data_signature(
                tuple(sorted(signature_entries))
            ),
        ),
        tuple(sorted(warnings)),
    )


def _power_query_opaque_metadata(
    entries: list[tuple[str, str]],
) -> ExternalDataOpaqueMetadataSnapshot:
    """Aggregate private Data Mashup evidence without serializing its material."""
    entries.sort()
    return ExternalDataOpaqueMetadataSnapshot(
        count=len(entries),
        signature=_private_external_data_signature(tuple(entries)),
    )


def _power_query_xml_structure_budget_fallback_signature(
    payload: bytes,
    member: str,
    warnings: set[str],
    budget: _PowerQueryXmlBudget,
    *,
    kind: str,
) -> str | None:
    """Stream decoded Power Query XML before private tree parsing."""
    try:
        element_count = _xml_payload_structure_element_count_within_budget(
            payload,
            maximum_element_count=min(
                _POWER_QUERY_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed input.
        # Only a successfully streamed overage can bypass its parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        f"FormulaFence did not fully read a Power Query {kind} XML payload whose XML "
        "structure exceeds the safety budget; affected query controls have a "
        "coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", kind),
            ("member", member),
            ("size", str(len(payload))),
            ("payload", _private_payload_signature(payload)),
        )
    )


def _power_query_boolean(
    value: str | None,
    default: bool,
    element_name: str,
    warnings: set[str],
) -> bool:
    """Read a Data Mashup boolean while retaining the documented default."""
    if value is None:
        return default
    lowered = value.strip().casefold()
    if lowered in {"1", "true"}:
        return True
    if lowered in {"0", "false"}:
        return False
    warnings.add(
        "FormulaFence could not interpret a Power Query "
        f"{element_name} boolean; the documented default was used."
    )
    return default


def _power_query_fields(
    payload: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
) -> tuple[int, tuple[bytes, bytes, bytes, bytes]] | None:
    """Read the versioned, length-prefixed Data Mashup binary stream safely."""
    if len(payload) < 4:
        warnings.add(
            "FormulaFence found a truncated Power Query Data Mashup stream; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append((f"{member}:truncated", _private_payload_signature(payload)))
        return None
    version = struct.unpack_from("<I", payload, 0)[0]
    if version != 0:
        warnings.add(
            "FormulaFence found an unrecognized Power Query Data Mashup stream version; "
            "the affected query controls have a coverage gap."
        )
    cursor = 4
    fields: list[bytes] = []
    for field_name in ("package parts", "permissions", "metadata", "permission bindings"):
        if cursor + 4 > len(payload):
            warnings.add(
                "FormulaFence found a truncated Power Query Data Mashup "
                f"{field_name} length; the affected query controls have a coverage gap."
            )
            opaque_entries.append(
                (f"{member}:truncated-{field_name}", _private_payload_signature(payload))
            )
            return None
        length = struct.unpack_from("<I", payload, cursor)[0]
        cursor += 4
        if length > len(payload) - cursor:
            warnings.add(
                "FormulaFence found an out-of-range Power Query Data Mashup "
                f"{field_name} length; the affected query controls have a coverage gap."
            )
            opaque_entries.append(
                (f"{member}:out-of-range-{field_name}", _private_payload_signature(payload))
            )
            return None
        fields.append(payload[cursor : cursor + length])
        cursor += length
    if cursor != len(payload):
        warnings.add(
            "FormulaFence found trailing bytes in a Power Query Data Mashup stream; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:trailing-bytes", _private_payload_signature(payload[cursor:]))
        )
    return version, (fields[0], fields[1], fields[2], fields[3])


def _power_query_package_inventory(
    package_parts: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    budget: _PowerQueryPackageBudget,
) -> tuple[int, int, int, str | None, str | None]:
    """Fingerprint logical query-package parts without exposing any part contents."""
    entry_count, preflight_reason = _power_query_nested_zip_entry_count(
        package_parts,
        maximum_parts=budget.remaining_parts,
    )
    if entry_count is None:
        if preflight_reason == "malformed-zip-metadata":
            return _power_query_package_unreadable_fallback(
                package_parts,
                member,
                warnings,
                opaque_entries,
                reason="ZIP metadata",
            )
        return _power_query_package_resource_budget_fallback(
            package_parts,
            member,
            warnings,
            opaque_entries,
            reason=preflight_reason or "zip-metadata",
        )
    # The raw catalog already passed the shared part boundary. Reserve it
    # before constructing ``ZipInfo`` objects, including if a later declared
    # member resource check rejects this logical package.
    budget.remaining_parts -= entry_count
    try:
        with ZipFile(io.BytesIO(package_parts)) as package:
            entries = package.infolist()
            if len(entries) != entry_count:
                return _power_query_package_unreadable_fallback(
                    package_parts,
                    member,
                    warnings,
                    opaque_entries,
                    reason="ZIP entry count",
                )
            total_uncompressed_bytes = 0
            for entry in entries:
                if entry.flag_bits & 0x1:
                    return _power_query_package_resource_budget_fallback(
                        package_parts,
                        member,
                        warnings,
                        opaque_entries,
                        reason="encrypted-member",
                    )
                if entry.compress_type not in {ZIP_STORED, ZIP_DEFLATED}:
                    return _power_query_package_resource_budget_fallback(
                        package_parts,
                        member,
                        warnings,
                        opaque_entries,
                        reason="compression-method",
                    )
                if entry.file_size > _POWER_QUERY_PACKAGE_MAX_MEMBER_BYTES:
                    return _power_query_package_resource_budget_fallback(
                        package_parts,
                        member,
                        warnings,
                        opaque_entries,
                        reason="member-size",
                    )
                total_uncompressed_bytes += entry.file_size
                if total_uncompressed_bytes > budget.remaining_uncompressed_bytes:
                    return _power_query_package_resource_budget_fallback(
                        package_parts,
                        member,
                        warnings,
                        opaque_entries,
                        reason="aggregate-size",
                    )
                if entry.file_size and (
                    not entry.compress_size
                    or entry.file_size
                    > entry.compress_size * _POWER_QUERY_PACKAGE_MAX_COMPRESSION_RATIO
                ):
                    return _power_query_package_resource_budget_fallback(
                        package_parts,
                        member,
                        warnings,
                        opaque_entries,
                        reason="compression-ratio",
                    )
            budget.remaining_uncompressed_bytes -= total_uncompressed_bytes
            formula_entries = [
                entry for entry in entries if entry.filename == _POWER_QUERY_FORMULA_MEMBER
            ]
            if len(formula_entries) > 1:
                warnings.add(
                    "FormulaFence found multiple Power Query Section1.m formula parts; "
                    "the affected query controls have a coverage gap."
                )
            formula_material: list[tuple[str, str]] = []
            configuration_material: list[tuple[str, str]] = []
            for entry in entries:
                label = f"{member}:{entry.filename}"
                signature = _private_payload_signature(package.read(entry))
                if entry.filename == _POWER_QUERY_FORMULA_MEMBER:
                    formula_material.append((label, signature or ""))
                else:
                    configuration_material.append((label, signature or ""))
            embedded_content_count = sum(
                entry.filename.startswith("Content/") for entry in entries
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _power_query_package_unreadable_fallback(
            package_parts,
            member,
            warnings,
            opaque_entries,
            reason=type(error).__name__,
        )
    return (
        len(entries),
        len(formula_entries),
        embedded_content_count,
        _private_external_data_signature(tuple(sorted(formula_material))),
        _private_external_data_signature(tuple(sorted(configuration_material))),
    )


def _power_query_nested_zip_entry_count(
    payload: bytes,
    *,
    maximum_parts: int,
) -> tuple[int | None, str | None]:
    """Count a nested ZIP before ``ZipFile`` can allocate its entry catalog."""
    if len(payload) > _POWER_QUERY_PACKAGE_MAX_SOURCE_BYTES:
        return None, "source-size"
    if len(payload) < _ZIP_END_OF_CENTRAL_DIRECTORY.size:
        return None, "malformed-zip-metadata"
    try:
        source_size = len(payload)
        tail_size = min(
            source_size,
            _ZIP_MAX_COMMENT_BYTES + _ZIP_END_OF_CENTRAL_DIRECTORY.size,
        )
        end_record, end_offset = _ooxml_archive_end_of_central_directory(
            payload[source_size - tail_size :],
            source_size - tail_size,
        )
        (
            _,
            disk_number,
            central_directory_disk,
            entries_on_disk,
            declared_entry_count,
            central_directory_size,
            central_directory_offset,
            _,
        ) = end_record
        if (
            entries_on_disk == _ZIP64_UINT16_SENTINEL
            or declared_entry_count == _ZIP64_UINT16_SENTINEL
            or central_directory_size == _ZIP64_UINT32_SENTINEL
            or central_directory_offset == _ZIP64_UINT32_SENTINEL
        ):
            return None, "zip64-directory"
        if (
            disk_number != 0
            or central_directory_disk != 0
            or entries_on_disk != declared_entry_count
        ):
            return None, "malformed-zip-metadata"
        if declared_entry_count > maximum_parts:
            return None, "part-count"
        if (
            end_offset > source_size
            or central_directory_offset > source_size
            or central_directory_size > source_size - central_directory_offset
            or central_directory_offset + central_directory_size > end_offset
        ):
            return None, "malformed-zip-metadata"
        central_directory = memoryview(payload)[
            central_directory_offset : central_directory_offset + central_directory_size
        ]
        cursor = 0
        entry_count = 0
        while cursor < len(central_directory):
            if len(central_directory) - cursor < _ZIP_CENTRAL_DIRECTORY_HEADER.size:
                return None, "malformed-zip-metadata"
            (
                signature,
                _,
                _,
                _,
                _,
                _,
                _,
                _,
                _,
                _,
                compressed_size,
                uncompressed_size,
                filename_size,
                extra_size,
                comment_size,
                disk_start,
                _,
                _,
                local_header_offset,
            ) = _ZIP_CENTRAL_DIRECTORY_HEADER.unpack_from(central_directory, cursor)
            if signature != _ZIP_CENTRAL_DIRECTORY_HEADER_SIGNATURE:
                return None, "malformed-zip-metadata"
            record_size = (
                _ZIP_CENTRAL_DIRECTORY_HEADER.size
                + filename_size
                + extra_size
                + comment_size
            )
            if record_size > len(central_directory) - cursor:
                return None, "malformed-zip-metadata"
            entry_count += 1
            if entry_count > maximum_parts:
                return None, "part-count"
            if filename_size > _POWER_QUERY_PACKAGE_MAX_MEMBER_NAME_BYTES:
                return None, "member-name"
            filename_start = cursor + _ZIP_CENTRAL_DIRECTORY_HEADER.size
            extra_start = filename_start + filename_size
            filename_payload = central_directory[filename_start:extra_start]
            if 0 in filename_payload or ord("\\") in filename_payload:
                # ``ZipInfo`` truncates at NUL and normalizes path separators
                # on Windows. Keep nested-package labels platform-independent
                # and prevent post-preflight filename aliases.
                return None, "member-name-alias"
            extra_cursor = 0
            extra = central_directory[extra_start : extra_start + extra_size]
            while extra_cursor < len(extra):
                if len(extra) - extra_cursor < 4:
                    return None, "malformed-zip-metadata"
                field_id, field_size = struct.unpack_from("<HH", extra, extra_cursor)
                extra_cursor += 4
                if field_size > len(extra) - extra_cursor:
                    return None, "malformed-zip-metadata"
                if field_id == 0x7075:
                    # ``ZipInfo._decodeExtra`` can replace the short central
                    # directory name with this alias after preflight.  Reject
                    # it so the member-name allocation bound stays meaningful.
                    return None, "unicode-path-alias"
                extra_cursor += field_size
            if (
                compressed_size == _ZIP64_UINT32_SENTINEL
                or uncompressed_size == _ZIP64_UINT32_SENTINEL
                or local_header_offset == _ZIP64_UINT32_SENTINEL
                or disk_start == _ZIP64_UINT16_SENTINEL
            ):
                return None, "zip64-member"
            if disk_start != 0:
                return None, "malformed-zip-metadata"
            cursor += record_size
        if entry_count != declared_entry_count:
            return None, "malformed-zip-metadata"
    except (WorkbookLoadError, struct.error, ValueError):
        return None, "malformed-zip-metadata"
    return entry_count, None


def _power_query_package_unreadable_fallback(
    package_parts: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    *,
    reason: str,
) -> tuple[int, int, int, str | None, str | None]:
    """Retain coverage evidence for a malformed nested logical package."""
    warnings.add(
        "FormulaFence could not inspect a Power Query package-part stream "
        f"({reason}); the affected query controls have a coverage gap."
    )
    opaque_entries.append((f"{member}:package-parts", _private_payload_signature(package_parts)))
    return 0, 0, 0, None, None


def _power_query_package_resource_budget_fallback(
    package_parts: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    *,
    reason: str,
) -> tuple[int, int, int, str | None, str | None]:
    """Retain private evidence when nested ZIP resources cannot be read safely."""
    warnings.add(
        "FormulaFence did not fully read a Power Query package-part stream whose ZIP "
        "resources exceed the safety budget; affected query controls have a coverage gap."
    )
    signature = _private_external_data_signature(
        (
            ("zip-resource-budget-exhausted", reason),
            ("source-size", str(len(package_parts))),
            ("payload", _private_payload_signature(package_parts)),
        )
    )
    opaque_entries.append((f"{member}:package-resource-budget", signature or ""))
    return 0, 0, 0, None, None


def _power_query_metadata_content_count(
    payload: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    package_budget: _PowerQueryPackageBudget,
) -> int:
    """Count metadata-side embedded parts without reading their sensitive contents."""
    if not payload:
        return 0
    entry_count, preflight_reason = _power_query_nested_zip_entry_count(
        payload,
        maximum_parts=package_budget.remaining_parts,
    )
    if entry_count is None:
        if preflight_reason == "malformed-zip-metadata":
            warnings.add(
                "FormulaFence could not inspect Power Query metadata embedded content "
                "(ZIP metadata); the affected query controls have a coverage gap."
            )
            opaque_entries.append(
                (f"{member}:metadata-content", _private_payload_signature(payload))
            )
            return 0
        warnings.add(
            "FormulaFence did not fully inspect a Power Query metadata embedded-content "
            "ZIP stream whose resources exceed the safety budget; affected query controls "
            "have a coverage gap."
        )
        signature = _private_external_data_signature(
            (
                ("zip-resource-budget-exhausted", preflight_reason or "zip-metadata"),
                ("source-size", str(len(payload))),
                ("payload", _private_payload_signature(payload)),
            )
        )
        opaque_entries.append(
            (f"{member}:metadata-content-resource-budget", signature or "")
        )
        return 0
    package_budget.remaining_parts -= entry_count
    return entry_count


def _power_query_metadata_inventory(
    payload: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    budget: _PowerQueryXmlBudget,
    package_budget: _PowerQueryPackageBudget,
) -> tuple[int, int, int, str | None, str | None]:
    """Read stable query metadata while intentionally ignoring refresh-result noise."""
    if not payload:
        return 0, 0, 0, None, None
    if len(payload) < 8:
        warnings.add(
            "FormulaFence found a truncated Power Query metadata stream; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append((f"{member}:truncated-metadata", _private_payload_signature(payload)))
        return 0, 0, 0, None, None

    version, xml_length = struct.unpack_from("<II", payload, 0)
    if version != 0:
        warnings.add(
            "FormulaFence found an unrecognized Power Query metadata version; "
            "the affected query controls have a coverage gap."
        )
    cursor = 8
    if xml_length > len(payload) - cursor:
        warnings.add(
            "FormulaFence found an out-of-range Power Query metadata XML length; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-xml-length", _private_payload_signature(payload))
        )
        return 0, 0, 0, None, None
    metadata_xml = payload[cursor : cursor + xml_length]
    cursor += xml_length
    if cursor + 4 > len(payload):
        warnings.add(
            "FormulaFence found a truncated Power Query metadata content length; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-content-length", _private_payload_signature(payload))
        )
        return 0, 0, 0, None, None
    content_length = struct.unpack_from("<I", payload, cursor)[0]
    cursor += 4
    if content_length > len(payload) - cursor:
        warnings.add(
            "FormulaFence found an out-of-range Power Query metadata content length; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-content-length", _private_payload_signature(payload))
        )
        return 0, 0, 0, None, None
    embedded_content = payload[cursor : cursor + content_length]
    cursor += content_length
    if cursor != len(payload):
        warnings.add(
            "FormulaFence found trailing Power Query metadata bytes; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-trailing-bytes", _private_payload_signature(payload[cursor:]))
        )

    embedded_content_count = _power_query_metadata_content_count(
        embedded_content,
        member,
        warnings,
        opaque_entries,
        package_budget,
    )
    structure_fallback_signature = (
        _power_query_xml_structure_budget_fallback_signature(
            metadata_xml,
            member,
            warnings,
            budget,
            kind="metadata",
        )
    )
    if structure_fallback_signature is not None:
        opaque_entries.append(
            (
                f"{member}:metadata-xml-structure-budget-exhausted",
                structure_fallback_signature,
            )
        )
        return 0, 0, embedded_content_count, None, None
    try:
        root = _xml_root_from_payload(metadata_xml)
    except (ElementTree.ParseError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect Power Query metadata XML "
            f"({type(error).__name__}); the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-xml", _private_payload_signature(metadata_xml))
        )
        return 0, 0, embedded_content_count, None, None
    if (
        _xml_local_name(root.tag) != "LocalPackageMetadataFile"
        or _xml_namespace(root.tag) not in {None, _DATA_MASHUP_NS}
    ):
        warnings.add(
            "FormulaFence found Power Query metadata with an unexpected root; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-root", _private_payload_signature(metadata_xml))
        )
        return 0, 0, embedded_content_count, None, None

    def named_children(element: ElementTree.Element, name: str) -> list[ElementTree.Element]:
        return [
            child
            for child in element
            if _xml_local_name(child.tag) == name
            and _xml_namespace(child.tag) in {None, _DATA_MASHUP_NS}
        ]

    def named_child(element: ElementTree.Element, name: str) -> ElementTree.Element | None:
        children = named_children(element, name)
        return children[0] if children else None

    items_containers = named_children(root, "Items")
    if len(items_containers) != 1:
        warnings.add(
            "FormulaFence found an unexpected Power Query metadata Items container; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (f"{member}:metadata-items", _private_payload_signature(metadata_xml))
        )
        return 1, 0, embedded_content_count, None, None
    unknown_root_children = [
        child
        for child in root
        if _xml_local_name(child.tag) != "Items"
    ]
    for child in unknown_root_children:
        opaque_entries.append(
            (
                f"{member}:metadata-root-child",
                _private_payload_signature(ElementTree.tostring(child, encoding="utf-8")),
            )
        )

    identity_entries: list[tuple[str, str]] = [("metadata-version", str(version))]
    control_entries: list[tuple[str, str]] = []
    item_count = 0
    for item_index, item in enumerate(named_children(items_containers[0], "Item")):
        item_count += 1
        item_location = named_child(item, "ItemLocation")
        stable_entries = named_child(item, "StableEntries")
        if item_location is None or stable_entries is None:
            warnings.add(
                "FormulaFence found incomplete Power Query query metadata; "
                "the affected query controls have a coverage gap."
            )
            opaque_entries.append(
                (
                    f"{member}:metadata-item:{item_index}",
                    _private_payload_signature(ElementTree.tostring(item, encoding="utf-8")),
                )
            )
            continue
        item_type_element = named_child(item_location, "ItemType")
        item_path_element = named_child(item_location, "ItemPath")
        if item_type_element is None or item_path_element is None:
            warnings.add(
                "FormulaFence found Power Query metadata without an item location; "
                "the affected query controls have a coverage gap."
            )
            opaque_entries.append(
                (
                    f"{member}:metadata-location:{item_index}",
                    _private_payload_signature(
                        ElementTree.tostring(item_location, encoding="utf-8")
                    ),
                )
            )
            continue
        item_type = item_type_element.text or ""
        item_path = item_path_element.text or ""
        if not item_type:
            warnings.add(
                "FormulaFence found Power Query metadata without an item type; "
                "the affected query controls have a coverage gap."
            )
            opaque_entries.append(
                (
                    f"{member}:metadata-item-type:{item_index}",
                    _private_payload_signature(
                        ElementTree.tostring(item_location, encoding="utf-8")
                    ),
                )
            )
            continue
        item_key = f"{item_type}\0{item_path}"
        identity_entries.append((f"item:{item_index}", item_key))
        unknown_item_children = [
            child
            for child in item
            if _xml_local_name(child.tag) not in {"ItemLocation", "StableEntries"}
        ]
        for child in unknown_item_children:
            opaque_entries.append(
                (
                    f"{member}:metadata-item-child:{item_index}",
                    _private_payload_signature(ElementTree.tostring(child, encoding="utf-8")),
                )
            )
        for entry_index, entry in enumerate(named_children(stable_entries, "Entry")):
            entry_type = entry.get("Type")
            value = entry.get("Value")
            if entry_type is None or value is None:
                warnings.add(
                    "FormulaFence found incomplete Power Query metadata entry; "
                    "the affected query controls have a coverage gap."
                )
                opaque_entries.append(
                    (
                        f"{member}:metadata-entry:{item_index}:{entry_index}",
                        _private_payload_signature(ElementTree.tostring(entry, encoding="utf-8")),
                    )
                )
                continue
            if entry_type in _POWER_QUERY_STABLE_METADATA_TYPES:
                control_entries.append(
                    (f"{item_key}\0{entry_type}", value)
                )
            elif entry_type not in _POWER_QUERY_VOLATILE_METADATA_TYPES:
                opaque_entries.append(
                    (
                        f"{member}:unknown-metadata-entry:{item_index}:{entry_index}",
                        _private_external_data_signature(
                            (("item", item_key), ("type", entry_type), ("value", value))
                        )
                        or "",
                    )
                )
        unknown_stable_children = [
            child
            for child in stable_entries
            if _xml_local_name(child.tag) != "Entry"
        ]
        for child in unknown_stable_children:
            opaque_entries.append(
                (
                    f"{member}:metadata-stable-child:{item_index}",
                    _private_payload_signature(ElementTree.tostring(child, encoding="utf-8")),
                )
            )
    return (
        1,
        item_count,
        embedded_content_count,
        _private_external_data_signature(tuple(sorted(identity_entries))),
        _private_external_data_signature(tuple(sorted(control_entries))),
    )


def _power_query_permission_inventory(
    payload: bytes,
    member: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    budget: _PowerQueryXmlBudget,
) -> tuple[int, int, int, int, int, str | None]:
    """Read safe formula-firewall controls without retaining user-bound payloads."""
    if not payload:
        return 0, 0, 0, 0, 0, None
    structure_fallback_signature = (
        _power_query_xml_structure_budget_fallback_signature(
            payload,
            member,
            warnings,
            budget,
            kind="permissions",
        )
    )
    if structure_fallback_signature is not None:
        opaque_entries.append(
            (
                f"{member}:permissions-xml-structure-budget-exhausted",
                structure_fallback_signature,
            )
        )
        return 1, 0, 0, 0, 0, None
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect Power Query permissions "
            f"({type(error).__name__}); the affected query controls have a coverage gap."
        )
        opaque_entries.append((f"{member}:permissions", _private_payload_signature(payload)))
        return 1, 0, 0, 0, 0, None
    if _xml_local_name(root.tag) != "PermissionList":
        warnings.add(
            "FormulaFence found Power Query permissions with an unexpected root; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append((f"{member}:permissions-root", _private_payload_signature(payload)))
        return 1, 0, 0, 0, 0, None

    children = {_xml_local_name(child.tag): child for child in root}
    firewall_enabled = _power_query_boolean(
        children.get("FirewallEnabled").text
        if children.get("FirewallEnabled") is not None
        else None,
        True,
        "FirewallEnabled",
        warnings,
    )
    future_packages_allowed = _power_query_boolean(
        children.get("CanEvaluateFuturePackages").text
        if children.get("CanEvaluateFuturePackages") is not None
        else None,
        False,
        "CanEvaluateFuturePackages",
        warnings,
    )
    workbook_group_type = children.get("WorkbookGroupType")
    xsi_nil = "{http://www.w3.org/2001/XMLSchema-instance}nil"
    has_workbook_group_type = bool(
        workbook_group_type is not None
        and workbook_group_type.get(xsi_nil, "").casefold() not in {"1", "true"}
        and (workbook_group_type.text or "").strip()
    )
    signature_entries: list[tuple[str, str]] = [
        ("firewall", str(firewall_enabled)),
        ("future-packages", str(future_packages_allowed)),
    ]
    if has_workbook_group_type and workbook_group_type is not None:
        signature_entries.append(("workbook-group-type", workbook_group_type.text or ""))
    for child in root:
        if _xml_local_name(child.tag) not in {
            "CanEvaluateFuturePackages",
            "FirewallEnabled",
            "WorkbookGroupType",
        }:
            opaque_entries.append(
                (
                    f"{member}:permissions-child",
                    _private_payload_signature(ElementTree.tostring(child, encoding="utf-8")),
                )
            )
    for attribute, value in root.attrib.items():
        opaque_entries.append(
            (
                f"{member}:permissions-attribute:{_xml_display_name(attribute)}",
                value,
            )
        )
    return (
        1,
        1,
        int(firewall_enabled),
        int(future_packages_allowed),
        int(has_workbook_group_type),
        _private_external_data_signature(tuple(sorted(signature_entries))),
    )


def _power_query_mashup_inspection(
    root: ElementTree.Element,
    member: str,
    warnings: set[str],
    xml_budget: _PowerQueryXmlBudget,
    package_budget: _PowerQueryPackageBudget,
) -> _PowerQueryMashupInspection:
    """Inspect one Data Mashup part while keeping formulas and sources private."""
    opaque_entries: list[tuple[str, str]] = []
    permission_opaque_entries: list[tuple[str, str]] = []
    for attribute, value in root.attrib.items():
        if _xml_local_name(attribute) != "sqmid":
            opaque_entries.append(
                (f"{member}:attribute:{_xml_display_name(attribute)}", value)
            )
    if tuple(root):
        warnings.add(
            "FormulaFence found child XML inside a Power Query Data Mashup root; "
            "the affected query controls have a coverage gap."
        )
        for child in root:
            opaque_entries.append(
                (
                    f"{member}:root-child",
                    _private_payload_signature(ElementTree.tostring(child, encoding="utf-8")),
                )
            )
    encoded_payload = "".join((root.text or "").split())
    if not encoded_payload:
        warnings.add(
            "FormulaFence found an empty Power Query Data Mashup payload; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append((f"{member}:empty-payload", ""))
        return _PowerQueryMashupInspection(opaque_entries=tuple(opaque_entries))
    try:
        payload = base64.b64decode(encoded_payload.encode("ascii"), validate=True)
    except (UnicodeEncodeError, binascii.Error, ValueError):
        warnings.add(
            "FormulaFence could not decode a Power Query Data Mashup payload; "
            "the affected query controls have a coverage gap."
        )
        opaque_entries.append(
            (
                f"{member}:invalid-base64",
                _private_external_data_signature((("payload", encoded_payload),)) or "",
            )
        )
        return _PowerQueryMashupInspection(opaque_entries=tuple(opaque_entries))

    fields = _power_query_fields(payload, member, warnings, opaque_entries)
    if fields is None:
        return _PowerQueryMashupInspection(opaque_entries=tuple(opaque_entries))
    version, (package_parts, permissions, metadata, permission_bindings) = fields
    (
        package_part_count,
        formula_document_count,
        package_embedded_content_count,
        formula_signature,
        package_configuration_signature,
    ) = _power_query_package_inventory(
        package_parts,
        member,
        warnings,
        opaque_entries,
        package_budget,
    )
    (
        metadata_document_count,
        metadata_item_count,
        metadata_embedded_content_count,
        metadata_identity_signature,
        metadata_control_signature,
    ) = _power_query_metadata_inventory(
        metadata,
        member,
        warnings,
        opaque_entries,
        xml_budget,
        package_budget,
    )
    (
        permission_payload_count,
        permission_parsed_count,
        firewall_enabled_count,
        future_packages_allowed_count,
        workbook_group_type_count,
        permission_signature,
    ) = _power_query_permission_inventory(
        permissions,
        member,
        warnings,
        permission_opaque_entries,
        xml_budget,
    )
    package_signature_entries = [("stream-version", str(version))]
    if package_configuration_signature is not None:
        package_signature_entries.append(("logical-package", package_configuration_signature))
    return _PowerQueryMashupInspection(
        parsed=True,
        formula_document_count=formula_document_count,
        package_part_count=package_part_count,
        embedded_content_part_count=(
            package_embedded_content_count + metadata_embedded_content_count
        ),
        metadata_document_count=metadata_document_count,
        metadata_item_count=metadata_item_count,
        permission_payload_count=permission_payload_count,
        permission_parsed_count=permission_parsed_count,
        firewall_enabled_count=firewall_enabled_count,
        future_packages_allowed_count=future_packages_allowed_count,
        workbook_group_type_count=workbook_group_type_count,
        permission_binding_present=bool(permission_bindings),
        formula_signature=formula_signature,
        package_configuration_signature=_private_external_data_signature(
            tuple(package_signature_entries)
        ),
        metadata_identity_signature=metadata_identity_signature,
        metadata_control_signature=metadata_control_signature,
        permission_signature=permission_signature,
        opaque_entries=tuple(opaque_entries),
        permission_opaque_entries=tuple(permission_opaque_entries),
    )


def _power_query_snapshot(
    archive: ZipFile,
    warnings: set[str],
    power_query_item_members: tuple[str, ...],
) -> PowerQuerySnapshot:
    """Inventory Data Mashup parts identified by the custom-state structural pass."""
    inspections: list[tuple[str, _PowerQueryMashupInspection]] = []
    xml_budget = _PowerQueryXmlBudget()
    package_budget = _PowerQueryPackageBudget()
    for member in sorted(set(power_query_item_members), key=str.casefold):
        try:
            root = _xml_root(archive, member)
        except (KeyError, ElementTree.ParseError, ValueError) as error:
            warnings.add(
                "FormulaFence could not inspect a custom XML part while looking for "
                f"Power Query definitions ({type(error).__name__}); coverage may be incomplete."
            )
            continue
        if (
            _xml_local_name(root.tag) != "DataMashup"
            or _xml_namespace(root.tag) != _DATA_MASHUP_NS
        ):
            continue
        inspections.append(
            (
                member,
                _power_query_mashup_inspection(
                    root,
                    member,
                    warnings,
                    xml_budget,
                    package_budget,
                ),
            )
        )
    if not inspections:
        return PowerQuerySnapshot()

    opaque_entries = [
        entry
        for _, inspection in inspections
        for entry in inspection.opaque_entries
    ]
    permission_opaque_entries = [
        entry
        for _, inspection in inspections
        for entry in inspection.permission_opaque_entries
    ]

    def aggregate_signature(attribute: str) -> str | None:
        material = [
            (member, value)
            for member, inspection in inspections
            if (value := getattr(inspection, attribute)) is not None
        ]
        return _private_external_data_signature(tuple(material))

    permission_controls = PowerQueryPermissionControlsSnapshot(
        payload_count=sum(inspection.permission_payload_count for _, inspection in inspections),
        parsed_count=sum(inspection.permission_parsed_count for _, inspection in inspections),
        firewall_enabled_count=sum(
            inspection.firewall_enabled_count for _, inspection in inspections
        ),
        future_packages_allowed_count=sum(
            inspection.future_packages_allowed_count for _, inspection in inspections
        ),
        workbook_group_type_count=sum(
            inspection.workbook_group_type_count for _, inspection in inspections
        ),
        opaque_metadata=_power_query_opaque_metadata(permission_opaque_entries),
        signature=aggregate_signature("permission_signature"),
    )
    return PowerQuerySnapshot(
        mashup_count=len(inspections),
        parsed_mashup_count=sum(inspection.parsed for _, inspection in inspections),
        formula_document_count=sum(
            inspection.formula_document_count for _, inspection in inspections
        ),
        package_part_count=sum(inspection.package_part_count for _, inspection in inspections),
        embedded_content_part_count=sum(
            inspection.embedded_content_part_count for _, inspection in inspections
        ),
        metadata_document_count=sum(
            inspection.metadata_document_count for _, inspection in inspections
        ),
        metadata_item_count=sum(inspection.metadata_item_count for _, inspection in inspections),
        permission_controls=permission_controls,
        permission_binding_count=sum(
            inspection.permission_binding_present for _, inspection in inspections
        ),
        formula_signature=aggregate_signature("formula_signature"),
        package_configuration_signature=aggregate_signature("package_configuration_signature"),
        metadata_identity_signature=aggregate_signature("metadata_identity_signature"),
        metadata_control_signature=aggregate_signature("metadata_control_signature"),
        opaque_metadata=_power_query_opaque_metadata(opaque_entries),
    )


def _external_link_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info: ZipInfo,
    budget: _ExternalLinkXmlBudget,
) -> str | None:
    """Stream external-link XML before its private tree is materialized."""
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if budget.remaining_xml_elements <= 0:
        return _private_external_data_signature(
            (("external-link-xml-structure-budget-exhausted", metadata),)
        )
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _EXTERNAL_LINK_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable XML. Only a successfully streamed overage can skip that
        # materializing parser safely.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    # An overage can contain an unbounded number of unseen descendants. Stop
    # spending the aggregate structural budget after its first failed part.
    budget.remaining_xml_elements = 0
    signature_entries = [("xml-structure-budget-exhausted", metadata)]
    if (
        payload_signature := _private_archive_member_payload_signature(archive, info)
    ) is not None:
        signature_entries.append(("payload", payload_signature))
    return _private_external_data_signature(tuple(signature_entries))


def _external_link_part_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _ExternalLinkXmlBudget,
    *,
    context: str,
) -> tuple[ElementTree.Element | None, str | None]:
    """Read one bounded, cached external-link XML root privately."""
    if member in budget.roots:
        return budget.roots[member]

    def retain(
        root: ElementTree.Element | None,
        fallback_signature: str | None,
    ) -> tuple[ElementTree.Element | None, str | None]:
        result = (root, fallback_signature)
        budget.roots[member] = result
        return result

    if budget.remaining_parts <= 0:
        try:
            info = archive.getinfo(member)
            metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        except KeyError:
            metadata = repr((member, "missing"))
        warnings.add(
            "FormulaFence reached its bounded external-link XML part count; "
            "affected external-link controls were not compared."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("external-link-xml-part-count-budget-exhausted", metadata),)
            )
        )
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate an external-link package part; "
            "the affected external-link controls were not compared."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("missing-external-link-xml-member", member),)
            ),
        )
    budget.remaining_parts -= 1
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _EXTERNAL_LINK_MAX_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized external-link XML part; "
            "the affected external-link controls have a coverage gap."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("oversized-external-link-xml-part", metadata),)
            ),
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded external-link XML read budget; "
            "affected external-link controls were not compared."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("external-link-xml-read-budget-exhausted", metadata),)
            ),
        )
    # A structural preflight must count against the same aggregate byte budget:
    # it reads the whole member even if parsing is then deliberately skipped.
    budget.remaining_bytes -= info.file_size
    structure_fallback_signature = (
        _external_link_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        warnings.add(
            "FormulaFence did not fully read an external-link XML part whose XML "
            "structure exceeds the safety budget; affected external-link controls "
            "have a coverage gap."
        )
        return retain(None, structure_fallback_signature)
    return retain(
        _external_data_part_root(archive, member, warnings, context=context),
        None,
    )


def _external_link_opaque_entries(
    element: ElementTree.Element,
    *,
    context: str,
    known_attributes: frozenset[str] = frozenset(),
    known_children: frozenset[str] = frozenset(),
    known_namespaces: frozenset[str] = frozenset({_SPREADSHEETML_NS}),
) -> list[tuple[str, str]]:
    """Privately retain unsupported external-link XML without serializing it."""
    entries: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute == f"{{{_MARKUP_COMPATIBILITY_NS}}}Ignorable":
            continue
        if _xml_local_name(attribute) in known_attributes:
            continue
        entries.append(
            (
                f"{context}:attribute:{_xml_display_name(attribute)}",
                value,
            )
        )
    for child in element:
        if (
            _xml_local_name(child.tag) in known_children
            and _xml_namespace(child.tag) in known_namespaces
        ):
            continue
        entries.append(
            (
                f"{context}:child:{_xml_display_name(child.tag)}",
                repr(_xml_fragment(child).sort_key()),
            )
        )
    return entries


def _external_link_relationship_signature(
    archive: ZipFile,
    member: str,
    relationship_id: str | None,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    budget: _ExternalLinkXmlBudget,
) -> str | None:
    """Fingerprint one link's package target without retaining its location."""
    if not relationship_id:
        warnings.add(
            "FormulaFence found an external-link definition without its required "
            "relationship id; the affected external-link control has a coverage gap."
        )
        return None
    relationships, fallback_signature = _external_link_part_root(
        archive,
        _relationship_part_path(member),
        warnings,
        budget,
        context="external-link relationship",
    )
    if relationships is None:
        if fallback_signature is not None:
            opaque_entries.append(
                ("bounded-external-link-relationship-xml", fallback_signature)
            )
        return None
    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    matches = [
        relationship
        for relationship in relationships.findall(relationship_tag)
        if relationship.get("Id") == relationship_id
    ]
    if not matches:
        warnings.add(
            "FormulaFence could not locate an external-link target relationship; "
            "the affected external-link control has a coverage gap."
        )
        return None
    if len(matches) > 1:
        warnings.add(
            "FormulaFence found repeated external-link target relationships; "
            "the affected external-link control has a coverage gap."
        )
    material: list[tuple[str, str]] = []
    for relationship in matches:
        target = relationship.get("Target")
        if target is None:
            warnings.add(
                "FormulaFence found an external-link target relationship without a target; "
                "the affected external-link control has a coverage gap."
            )
            target = ""
        material.extend(
            [
                ("type", relationship.get("Type", "")),
                ("target_mode", relationship.get("TargetMode", "Internal").casefold()),
                ("target", target),
            ]
        )
        opaque_entries.extend(
            _external_link_opaque_entries(
                relationship,
                context="relationship",
                known_attributes=frozenset({"Id", "Type", "Target", "TargetMode"}),
                known_children=frozenset(),
                known_namespaces=frozenset(),
            )
        )
    material.sort()
    return _private_external_data_signature(tuple(material))


def _external_link_item_flags(
    item: ElementTree.Element,
    warnings: set[str],
    *,
    context: str,
) -> tuple[bool, bool, bool]:
    """Read safe DDE/OLE item behavior flags with their schema defaults."""
    return (
        _external_data_bool(
            item.get("advise"), False, "advise", warnings, context=context
        ),
        _external_data_bool(item.get("ole"), False, "ole", warnings, context=context),
        _external_data_bool(
            item.get("preferPic"), False, "preferPic", warnings, context=context
        ),
    )


def _external_link_optional_child(
    element: ElementTree.Element,
    name: str,
    warnings: set[str],
    opaque_entries: list[tuple[str, str]],
    *,
    context: str,
) -> ElementTree.Element | None:
    """Return one schema-singleton child while retaining repeated XML privately."""
    matches = [
        child
        for child in element
        if _xml_namespace(child.tag) == _SPREADSHEETML_NS
        and _xml_local_name(child.tag) == name
    ]
    if len(matches) > 1:
        warnings.add(
            "FormulaFence found repeated "
            f"{name} containers in an external-link {context}; "
            "the affected controls have a coverage gap."
        )
        opaque_entries.extend(
            (
                f"{context}:repeated-{name}:{index}",
                repr(_xml_fragment(child).sort_key()),
            )
            for index, child in enumerate(matches[1:], start=1)
        )
    return matches[0] if matches else None


def _external_link_part_inspection(
    archive: ZipFile,
    member: str,
    root: ElementTree.Element,
    warnings: set[str],
    budget: _ExternalLinkXmlBudget,
) -> _ExternalLinkPartInspection:
    """Read one external-link definition while keeping all endpoint material private."""
    opaque_entries = _external_link_opaque_entries(
        root,
        context="external-link",
        known_children=frozenset({"externalBook", "ddeLink", "oleLink"}),
    )
    recognised_children = [
        child
        for child in root
        if _xml_namespace(child.tag) == _SPREADSHEETML_NS
        and _xml_local_name(child.tag) in {"externalBook", "ddeLink", "oleLink"}
    ]
    if len(recognised_children) != 1:
        warnings.add(
            "FormulaFence found an external-link part without exactly one supported link "
            "definition; the affected external-link controls have a coverage gap."
        )
        opaque_entries.append(
            ("external-link:ambiguous-definition", repr(_xml_fragment(root).sort_key()))
        )
        return _ExternalLinkPartInspection(
            member=member,
            opaque_entries=tuple(opaque_entries),
        )

    element = recognised_children[0]
    kind = _xml_local_name(element.tag)
    source_entries: list[tuple[str, str]] = [("kind", kind)]
    definition_entries: list[tuple[str, str]] = []
    cached_entries: list[tuple[str, str]] = []
    standard = _SPREADSHEETML_NS
    relationship_id_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"

    if kind == "externalBook":
        relationship_signature = _external_link_relationship_signature(
            archive,
            member,
            element.get(relationship_id_attribute),
            warnings,
            opaque_entries,
            budget,
        )
        if relationship_signature is not None:
            source_entries.append(("target", relationship_signature))
        opaque_entries.extend(
            _external_link_opaque_entries(
                element,
                context="external-workbook",
                known_attributes=frozenset({"id"}),
                known_children=frozenset({"sheetNames", "definedNames", "sheetDataSet"}),
            )
        )
        sheet_names = _external_link_optional_child(
            element,
            "sheetNames",
            warnings,
            opaque_entries,
            context="external-workbook definition",
        )
        sheet_name_count = 0
        if sheet_names is not None:
            opaque_entries.extend(
                _external_link_opaque_entries(
                    sheet_names,
                    context="external-workbook-sheet-names",
                    known_children=frozenset({"sheetName"}),
                )
            )
            for index, sheet_name in enumerate(
                sheet_names.findall(f"{{{standard}}}sheetName")
            ):
                value = sheet_name.get("val")
                if value is None:
                    warnings.add(
                        "FormulaFence found an external-workbook sheet name without a value; "
                        "the affected external-link control has a coverage gap."
                    )
                    value = ""
                definition_entries.append((f"sheet-name:{index}", value))
                opaque_entries.extend(
                    _external_link_opaque_entries(
                        sheet_name,
                        context="external-workbook-sheet-name",
                        known_attributes=frozenset({"val"}),
                    )
                )
                sheet_name_count += 1
        defined_names = _external_link_optional_child(
            element,
            "definedNames",
            warnings,
            opaque_entries,
            context="external-workbook definition",
        )
        defined_name_count = 0
        if defined_names is not None:
            opaque_entries.extend(
                _external_link_opaque_entries(
                    defined_names,
                    context="external-workbook-defined-names",
                    known_children=frozenset({"definedName"}),
                )
            )
            for index, defined_name in enumerate(
                defined_names.findall(f"{{{standard}}}definedName")
            ):
                if defined_name.get("name") is None:
                    warnings.add(
                        "FormulaFence found an external defined name without a name; "
                        "the affected external-link control has a coverage gap."
                    )
                definition_entries.append(
                    (
                        f"defined-name:{index}",
                        repr(_xml_fragment(defined_name).sort_key()),
                    )
                )
                opaque_entries.extend(
                    _external_link_opaque_entries(
                        defined_name,
                        context="external-workbook-defined-name",
                        known_attributes=frozenset({"name", "refersTo", "sheetId"}),
                    )
                )
                defined_name_count += 1
        sheet_data_set = _external_link_optional_child(
            element,
            "sheetDataSet",
            warnings,
            opaque_entries,
            context="external-workbook definition",
        )
        cached_sheet_count = 0
        cached_cell_count = 0
        cached_refresh_error_count = 0
        if sheet_data_set is not None:
            opaque_entries.extend(
                _external_link_opaque_entries(
                    sheet_data_set,
                    context="external-workbook-cache",
                    known_children=frozenset({"sheetData"}),
                )
            )
            for index, sheet_data in enumerate(
                sheet_data_set.findall(f"{{{standard}}}sheetData")
            ):
                if sheet_data.get("sheetId") is None:
                    warnings.add(
                        "FormulaFence found cached external-workbook data without a sheet id; "
                        "the affected external-link control has a coverage gap."
                    )
                refresh_error = _external_data_bool(
                    sheet_data.get("refreshError"),
                    False,
                    "refreshError",
                    warnings,
                    context="external-workbook cache",
                )
                cached_refresh_error_count += int(refresh_error)
                cells = tuple(sheet_data.iter(f"{{{standard}}}cell"))
                cached_cell_count += len(cells)
                cached_entries.append(
                    (f"external-workbook-cache:{index}", repr(_xml_fragment(sheet_data).sort_key()))
                )
                opaque_entries.extend(
                    _external_link_opaque_entries(
                        sheet_data,
                        context="external-workbook-cache-sheet",
                        known_attributes=frozenset({"sheetId", "refreshError"}),
                        known_children=frozenset({"row"}),
                    )
                )
                cached_sheet_count += 1
        return _ExternalLinkPartInspection(
            member=member,
            kind="external_workbook",
            external_workbook_sheet_count=sheet_name_count,
            external_defined_name_count=defined_name_count,
            external_workbook_cached_sheet_count=cached_sheet_count,
            external_workbook_cached_cell_count=cached_cell_count,
            external_workbook_cached_refresh_error_count=cached_refresh_error_count,
            source_signature=_private_external_data_signature(tuple(sorted(source_entries))),
            definition_signature=_private_external_data_signature(
                tuple(sorted(definition_entries))
            ),
            cached_material_signature=_private_external_data_signature(
                tuple(sorted(cached_entries))
            ),
            opaque_entries=tuple(opaque_entries),
        )

    if kind == "ddeLink":
        service = element.get("ddeService")
        topic = element.get("ddeTopic")
        if service is None or topic is None:
            warnings.add(
                "FormulaFence found a DDE link without its required service or topic; "
                "the affected external-link control has a coverage gap."
            )
        source_entries.extend(
            [("service", service or ""), ("topic", topic or "")]
        )
        opaque_entries.extend(
            _external_link_opaque_entries(
                element,
                context="dde-link",
                known_attributes=frozenset({"ddeService", "ddeTopic"}),
                known_children=frozenset({"ddeItems"}),
            )
        )
        items = _external_link_optional_child(
            element,
            "ddeItems",
            warnings,
            opaque_entries,
            context="DDE definition",
        )
        item_count = advise_count = ole_count = prefer_picture_count = cached_value_count = 0
        if items is not None:
            opaque_entries.extend(
                _external_link_opaque_entries(
                    items,
                    context="dde-items",
                    known_children=frozenset({"ddeItem"}),
                )
            )
            for index, item in enumerate(items.findall(f"{{{standard}}}ddeItem")):
                advise, ole, prefer_picture = _external_link_item_flags(
                    item, warnings, context="DDE item"
                )
                advise_count += int(advise)
                ole_count += int(ole)
                prefer_picture_count += int(prefer_picture)
                definition_entries.append((f"dde-item:{index}", item.get("name", "0")))
                values = _external_link_optional_child(
                    item,
                    "values",
                    warnings,
                    opaque_entries,
                    context="DDE item",
                )
                if values is not None:
                    cached_value_count += len(values.findall(f"{{{standard}}}value"))
                    cached_entries.append(
                        (f"dde-values:{index}", repr(_xml_fragment(values).sort_key()))
                    )
                opaque_entries.extend(
                    _external_link_opaque_entries(
                        item,
                        context="dde-item",
                        known_attributes=frozenset({"name", "ole", "advise", "preferPic"}),
                        known_children=frozenset({"values"}),
                    )
                )
                item_count += 1
        return _ExternalLinkPartInspection(
            member=member,
            kind="dde",
            dde_item_count=item_count,
            dde_advise_item_count=advise_count,
            dde_ole_item_count=ole_count,
            dde_prefer_picture_item_count=prefer_picture_count,
            dde_cached_value_count=cached_value_count,
            source_signature=_private_external_data_signature(tuple(sorted(source_entries))),
            definition_signature=_private_external_data_signature(
                tuple(sorted(definition_entries))
            ),
            cached_material_signature=_private_external_data_signature(
                tuple(sorted(cached_entries))
            ),
            opaque_entries=tuple(opaque_entries),
        )

    relationship_signature = _external_link_relationship_signature(
        archive,
        member,
        element.get(relationship_id_attribute),
        warnings,
        opaque_entries,
        budget,
    )
    if relationship_signature is not None:
        source_entries.append(("target", relationship_signature))
    program_id = element.get("progId")
    if program_id is None:
        warnings.add(
            "FormulaFence found an OLE link without its required program id; "
            "the affected external-link control has a coverage gap."
        )
    source_entries.append(("program-id", program_id or ""))
    opaque_entries.extend(
        _external_link_opaque_entries(
            element,
            context="ole-link",
            known_attributes=frozenset({"id", "progId"}),
            known_children=frozenset({"oleItems"}),
        )
    )
    items = _external_link_optional_child(
        element,
        "oleItems",
        warnings,
        opaque_entries,
        context="OLE definition",
    )
    item_count = advise_count = icon_count = prefer_picture_count = 0
    if items is not None:
        opaque_entries.extend(
            _external_link_opaque_entries(
                items,
                context="ole-items",
                known_children=frozenset({"oleItem"}),
            )
        )
        for index, item in enumerate(items.findall(f"{{{standard}}}oleItem")):
            advise, _ole, prefer_picture = _external_link_item_flags(
                item, warnings, context="OLE item"
            )
            icon = _external_data_bool(
                item.get("icon"), False, "icon", warnings, context="OLE item"
            )
            advise_count += int(advise)
            icon_count += int(icon)
            prefer_picture_count += int(prefer_picture)
            definition_entries.append((f"ole-item:{index}", item.get("name", "")))
            opaque_entries.extend(
                _external_link_opaque_entries(
                    item,
                    context="ole-item",
                    known_attributes=frozenset({"name", "icon", "advise", "preferPic"}),
                )
            )
            item_count += 1
    return _ExternalLinkPartInspection(
        member=member,
        kind="ole",
        ole_item_count=item_count,
        ole_advise_item_count=advise_count,
        ole_icon_item_count=icon_count,
        ole_prefer_picture_item_count=prefer_picture_count,
        source_signature=_private_external_data_signature(tuple(sorted(source_entries))),
        definition_signature=_private_external_data_signature(tuple(sorted(definition_entries))),
        cached_material_signature=_private_external_data_signature(tuple(sorted(cached_entries))),
        opaque_entries=tuple(opaque_entries),
    )


def _external_link_packages_snapshot(
    archive: ZipFile,
    workbook: ElementTree.Element,
    relationships: tuple[_PackageRelationship, ...],
    warnings: set[str],
    budget: _ExternalLinkXmlBudget,
) -> ExternalLinkPackageSnapshot:
    """Inventory externalLink OOXML parts without following their endpoints."""
    external_relationships = [
        relationship
        for relationship in relationships
        if relationship.relationship_type.rsplit("/", maxsplit=1)[-1] == "externalLink"
    ]
    relationships_by_id = {
        relationship.relationship_id: relationship
        for relationship in external_relationships
        if relationship.relationship_id
    }
    external_references = workbook.find(f"{{{_SPREADSHEETML_NS}}}externalReferences")
    reference_ids: list[str] = []
    declaration_opaque_entries: list[tuple[str, str]] = []
    if external_references is not None:
        declaration_opaque_entries.extend(
            _external_link_opaque_entries(
                external_references,
                context="external-link-declarations",
                known_children=frozenset({"externalReference"}),
            )
        )
        identifier_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
        for reference in external_references.findall(
            f"{{{_SPREADSHEETML_NS}}}externalReference"
        ):
            declaration_opaque_entries.extend(
                _external_link_opaque_entries(
                    reference,
                    context="external-link-declaration",
                    known_attributes=frozenset({"id"}),
                )
            )
            if (relationship_id := reference.get(identifier_attribute)) is None:
                warnings.add(
                    "FormulaFence found an external-link declaration without a relationship id; "
                    "the affected external-link controls have a coverage gap."
                )
                continue
            reference_ids.append(relationship_id)
            if relationship_id not in relationships_by_id:
                warnings.add(
                    "FormulaFence could not locate an external-link declaration relationship; "
                    "the affected external-link controls were not compared."
                )
    if len(reference_ids) != len(set(reference_ids)):
        warnings.add(
            "FormulaFence found repeated external-link declaration relationships; "
            "the affected external-link controls have a coverage gap."
        )
    relationship_ids = [
        relationship.relationship_id
        for relationship in external_relationships
        if relationship.relationship_id is not None
    ]
    if len(relationship_ids) != len(set(relationship_ids)):
        warnings.add(
            "FormulaFence found duplicate external-link package relationship ids; "
            "the affected external-link controls have a coverage gap."
        )
    declaration_entries: list[tuple[str, str]] = []
    for index, relationship_id in enumerate(reference_ids):
        relationship = relationships_by_id.get(relationship_id)
        if relationship is None:
            declaration_entries.append((f"external-reference:{index}", "missing"))
            continue
        declaration_entries.append(
            (
                f"external-reference:{index}",
                repr(
                    (
                        relationship.relationship_type,
                        relationship.target_mode,
                        relationship.target,
                    )
                ),
            )
        )
    referenced_relationship_ids = set(reference_ids)
    unreferenced_relationships = sorted(
        (
            (
                relationship.relationship_type,
                relationship.target_mode,
                relationship.target,
            )
            for relationship in external_relationships
            if relationship.relationship_id not in referenced_relationship_ids
        ),
        key=repr,
    )
    for index, relationship in enumerate(unreferenced_relationships):
        declaration_entries.append(
            (f"unreferenced-workbook-relationship:{index}", repr(relationship))
        )
    declaration_signature = _private_external_data_signature(
        tuple(declaration_entries)
    )

    members: set[str] = set()
    declared_targets: list[str] = []
    for relationship in external_relationships:
        if relationship.target is None:
            warnings.add(
                "FormulaFence found an external-link declaration without a safe internal part "
                "target; the affected external-link controls were not compared."
            )
            continue
        members.add(relationship.target)
        declared_targets.append(relationship.target)
        if relationship.relationship_id not in reference_ids:
            warnings.add(
                "FormulaFence found an external-link package relationship not declared by the "
                "workbook; the affected external-link controls have a coverage gap."
            )
    if len(declared_targets) != len(set(declared_targets)):
        warnings.add(
            "FormulaFence found multiple external-link relationships targeting one package "
            "part; the affected external-link controls have a coverage gap."
        )
    discovered_members = {
        member for member in archive.namelist() if _EXTERNAL_LINK_PART_PATTERN.fullmatch(member)
    }
    for _member in discovered_members - members:
        warnings.add(
            "FormulaFence found an external-link package part not declared by the workbook; "
            "the affected external-link controls have a coverage gap."
        )
    members.update(discovered_members)

    inspections: list[_ExternalLinkPartInspection] = []
    for member in sorted(members, key=str.casefold):
        root, fallback_signature = _external_link_part_root(
            archive,
            member,
            warnings,
            budget,
            context="external-link package",
        )
        if root is None:
            if fallback_signature is not None:
                inspections.append(
                    _ExternalLinkPartInspection(
                        member=member,
                        opaque_entries=(
                            ("bounded-external-link-xml", fallback_signature),
                        ),
                    )
                )
            continue
        if (
            _xml_local_name(root.tag) != "externalLink"
            or _xml_namespace(root.tag) != _SPREADSHEETML_NS
        ):
            warnings.add(
                "FormulaFence found an external-link package part with an unexpected root; "
                "the affected external-link controls were not compared."
            )
            continue
        inspections.append(
            _external_link_part_inspection(archive, member, root, warnings, budget)
        )
    if not members:
        return ExternalLinkPackageSnapshot()
    inspected_members = {inspection.member for inspection in inspections}
    uninspected_member_count = len(members - inspected_members)

    def aggregate_signature(attribute: str) -> str | None:
        material = sorted(
            (inspection.member, value)
            for inspection in inspections
            if (value := getattr(inspection, attribute)) is not None
        )
        return _private_external_data_signature(tuple(material))

    opaque_entries = [
        (f"workbook:{entry[0]}", entry[1])
        for entry in declaration_opaque_entries
    ] + [
        (f"{inspection.member}:{entry[0]}", entry[1])
        for inspection in inspections
        for entry in inspection.opaque_entries
    ]
    opaque_entries.sort()
    part_source_signature = aggregate_signature("source_signature")
    source_signature = _private_external_data_signature(
        tuple(
            entry
            for entry in (
                ("declarations", declaration_signature),
                ("parts", part_source_signature),
            )
            if entry[1] is not None
        )
    )
    return ExternalLinkPackageSnapshot(
        external_link_count=len(members),
        external_workbook_count=sum(
            inspection.kind == "external_workbook" for inspection in inspections
        ),
        dde_link_count=sum(inspection.kind == "dde" for inspection in inspections),
        ole_link_count=sum(inspection.kind == "ole" for inspection in inspections),
        unrecognized_link_count=sum(
            inspection.kind == "unrecognized" for inspection in inspections
        )
        + uninspected_member_count,
        external_workbook_sheet_count=sum(
            inspection.external_workbook_sheet_count for inspection in inspections
        ),
        external_defined_name_count=sum(
            inspection.external_defined_name_count for inspection in inspections
        ),
        external_workbook_cached_sheet_count=sum(
            inspection.external_workbook_cached_sheet_count for inspection in inspections
        ),
        external_workbook_cached_cell_count=sum(
            inspection.external_workbook_cached_cell_count for inspection in inspections
        ),
        external_workbook_cached_refresh_error_count=sum(
            inspection.external_workbook_cached_refresh_error_count
            for inspection in inspections
        ),
        dde_item_count=sum(inspection.dde_item_count for inspection in inspections),
        dde_advise_item_count=sum(
            inspection.dde_advise_item_count for inspection in inspections
        ),
        dde_ole_item_count=sum(
            inspection.dde_ole_item_count for inspection in inspections
        ),
        dde_prefer_picture_item_count=sum(
            inspection.dde_prefer_picture_item_count for inspection in inspections
        ),
        dde_cached_value_count=sum(
            inspection.dde_cached_value_count for inspection in inspections
        ),
        ole_item_count=sum(inspection.ole_item_count for inspection in inspections),
        ole_advise_item_count=sum(
            inspection.ole_advise_item_count for inspection in inspections
        ),
        ole_icon_item_count=sum(
            inspection.ole_icon_item_count for inspection in inspections
        ),
        ole_prefer_picture_item_count=sum(
            inspection.ole_prefer_picture_item_count for inspection in inspections
        ),
        source_signature=source_signature,
        definition_signature=aggregate_signature("definition_signature"),
        cached_material_signature=aggregate_signature("cached_material_signature"),
        opaque_metadata=ExternalDataOpaqueMetadataSnapshot(
            count=len(opaque_entries),
            signature=_private_external_data_signature(tuple(opaque_entries)),
        ),
    )


def _external_link_external_workbook_target(
    archive: ZipFile,
    member: str,
    relationship_id: str | None,
    warnings: set[str],
    budget: _ExternalLinkXmlBudget,
) -> str | None:
    """Return one private external-workbook target from a valid link part.

    This is intentionally stricter than the aggregate external-link inventory:
    a package-mediated portfolio edge must come from one unambiguous
    ``externalLinkPath`` relationship, not from a cache, an arbitrary target,
    or a relationship that merely happens to have a similar identifier.
    """
    if not relationship_id:
        warnings.add(
            "FormulaFence found a package-indexed external reference without an "
            "external-book relationship id; the affected package-mediated reference "
            "was not resolved."
        )
        return None
    relationships, _fallback_signature = _external_link_part_root(
        archive,
        _relationship_part_path(member),
        warnings,
        budget,
        context="package-indexed external-reference relationship",
    )
    if relationships is None:
        return None
    if (
        _xml_namespace(relationships.tag) != _PACKAGE_RELATIONSHIP_NS
        or _xml_local_name(relationships.tag) != "Relationships"
    ):
        warnings.add(
            "FormulaFence found a package-indexed external-reference relationship part "
            "with an unexpected root; the affected package-mediated reference was not "
            "resolved."
        )
        return None
    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    matches = [
        relationship
        for relationship in relationships.findall(relationship_tag)
        if relationship.get("Id") == relationship_id
    ]
    if len(matches) != 1:
        warnings.add(
            "FormulaFence could not uniquely locate a package-indexed external-reference "
            "target relationship; the affected package-mediated reference was not "
            "resolved."
        )
        return None
    relationship = matches[0]
    if (
        relationship.get("Type") != _EXTERNAL_LINK_PATH_RELATIONSHIP_TYPE
        or relationship.get("TargetMode", "Internal").casefold() != "external"
    ):
        warnings.add(
            "FormulaFence found a package-indexed external-reference target that is not "
            "an external workbook path relationship; the affected package-mediated "
            "reference was not resolved."
        )
        return None
    target = relationship.get("Target")
    if not target:
        warnings.add(
            "FormulaFence found a package-indexed external-reference target relationship "
            "without a target; the affected package-mediated reference was not resolved."
        )
        return None
    return target


def _indexed_external_workbook_paths(
    archive: ZipFile,
    workbook: ElementTree.Element,
    relationships: tuple[_PackageRelationship, ...],
    warnings: set[str],
    budget: _ExternalLinkXmlBudget,
) -> tuple[tuple[int, str], ...]:
    """Map declared external-reference positions to private workbook targets.

    Excel's ``[N]!Name`` and ``[N]Sheet!A1`` syntax use the one-based document
    order of ``externalReference`` declarations, rather than a relationship
    filename or arbitrary relationship order.  The map is intentionally private
    and is consumed only while building the candidate-only portfolio graph.
    """
    containers = [
        child
        for child in workbook
        if _xml_namespace(child.tag) == _SPREADSHEETML_NS
        and _xml_local_name(child.tag) == "externalReferences"
    ]
    if not containers:
        return ()
    if len(containers) != 1:
        warnings.add(
            "FormulaFence found repeated external-link declaration containers; "
            "package-mediated external references were not resolved."
        )
        return ()
    identifier_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    references = list(
        containers[0].findall(f"{{{_SPREADSHEETML_NS}}}externalReference")
    )
    reference_ids = [reference.get(identifier_attribute) for reference in references]
    if any(relationship_id is None for relationship_id in reference_ids):
        warnings.add(
            "FormulaFence found a package-indexed external-reference declaration "
            "without a relationship id; package-mediated external references were not "
            "resolved."
        )
        return ()
    if len(reference_ids) != len(set(reference_ids)):
        warnings.add(
            "FormulaFence found repeated package-indexed external-reference "
            "declarations; package-mediated external references were not resolved."
        )
        return ()
    relationships_by_id: defaultdict[str, list[_PackageRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
    # A declaration index must identify one physical external-link package
    # part.  Rebinding two workbook relationships to the same part leaves the
    # package graph ambiguous, even if both relationship ids are individually
    # well-formed.  Do not let that malformed indirection create an impact
    # edge.
    external_link_member_counts = Counter(
        relationship.target
        for relationship in relationships
        if relationship.relationship_type == _EXTERNAL_LINK_RELATIONSHIP_TYPE
        and relationship.target_mode.casefold() == "internal"
        and relationship.target is not None
    )

    resolved: list[tuple[int, str]] = []
    for index, relationship_id in enumerate(reference_ids, start=1):
        matches = relationships_by_id[relationship_id]
        if (
            len(matches) != 1
            or matches[0].relationship_type != _EXTERNAL_LINK_RELATIONSHIP_TYPE
            or matches[0].target_mode.casefold() != "internal"
            or matches[0].target is None
            or external_link_member_counts[matches[0].target] != 1
        ):
            warnings.add(
                "FormulaFence could not uniquely validate a package-indexed external-"
                "reference declaration or package part; the affected package-mediated "
                "reference was not resolved."
            )
            continue
        member = matches[0].target
        root, _fallback_signature = _external_link_part_root(
            archive,
            member,
            warnings,
            budget,
            context="package-indexed external-reference package",
        )
        if root is None:
            continue
        if (
            _xml_namespace(root.tag) != _SPREADSHEETML_NS
            or _xml_local_name(root.tag) != "externalLink"
        ):
            warnings.add(
                "FormulaFence found a package-indexed external-reference package with "
                "an unexpected root; the affected package-mediated reference was not "
                "resolved."
            )
            continue
        external_books = [
            child
            for child in root
            if _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) == "externalBook"
        ]
        conflicting_links = [
            child
            for child in root
            if _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) in {"ddeLink", "oleLink"}
        ]
        if len(external_books) != 1 or conflicting_links:
            warnings.add(
                "FormulaFence found a package-indexed external-reference package without "
                "exactly one external workbook; the affected package-mediated reference "
                "was not resolved."
            )
            continue
        target = _external_link_external_workbook_target(
            archive,
            member,
            external_books[0].get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"),
            warnings,
            budget,
        )
        if target is not None:
            resolved.append((index, target))
    return tuple(resolved)


def _external_data_workbook_settings(
    workbook: ElementTree.Element,
    warnings: set[str],
) -> ExternalDataRefreshSettingsSnapshot:
    """Read workbook-wide refresh controls directly from ``workbookPr``."""
    properties = workbook.find(f"{{{_SPREADSHEETML_NS}}}workbookPr")
    if properties is None:
        return ExternalDataRefreshSettingsSnapshot()
    return ExternalDataRefreshSettingsSnapshot(
        update_links=_external_data_enum(
            properties.get("updateLinks"),
            "user_set",
            {"userSet": "user_set", "never": "never", "always": "always"},
            warnings,
            context="workbook properties",
            attribute="updateLinks",
        ),
        allow_refresh_query=_external_data_bool(
            properties.get("allowRefreshQuery"),
            False,
            "allowRefreshQuery",
            warnings,
            context="workbook properties",
        ),
        refresh_all_connections=_external_data_bool(
            properties.get("refreshAllConnections"),
            False,
            "refreshAllConnections",
            warnings,
            context="workbook properties",
        ),
        save_external_link_values=_external_data_bool(
            properties.get("saveExternalLinkValues"),
            True,
            "saveExternalLinkValues",
            warnings,
            context="workbook properties",
        ),
    )


def _connection_source_type(
    element: ElementTree.Element,
    warnings: set[str],
) -> str:
    """Return the safe source-type label for one connection."""
    raw_value = element.get("type")
    if raw_value is None:
        return "unspecified"
    source_type = _external_data_unsigned_int(
        element,
        "type",
        None,
        warnings,
        context="connection",
    )
    if source_type is None:
        return "unrecognized"
    if normalised := _EXTERNAL_CONNECTION_TYPES.get(source_type):
        return normalised
    warnings.add(
        "FormulaFence found an unrecognized external-data connection type; "
        "the affected source has a coverage gap."
    )
    return "unrecognized"


def _connection_reconnection_method(
    element: ElementTree.Element,
    warnings: set[str],
) -> str:
    """Normalize a connection-file reload policy without exposing raw values."""
    raw_value = element.get("reconnectionMethod")
    if raw_value is None:
        return "as_required"
    method = _external_data_unsigned_int(
        element,
        "reconnectionMethod",
        None,
        warnings,
        context="connection",
    )
    if method is None:
        return "unrecognized"
    if normalised := _EXTERNAL_RECONNECTION_METHODS.get(method):
        return normalised
    warnings.add(
        "FormulaFence found an unrecognized external-data connection "
        "reconnection method; the affected control has a coverage gap."
    )
    return "unrecognized"


def _connection_identity_signature(element: ElementTree.Element) -> str | None:
    """Privately retain connection name and description changes."""
    return _private_external_data_signature(
        tuple(
            (attribute, value)
            for attribute in ("name", "description")
            if (value := element.get(attribute)) is not None
        )
    )


def _connection_source_configuration_signature(
    element: ElementTree.Element,
) -> str | None:
    """Privately retain source paths, credentials, and query configuration."""
    entries: list[tuple[str, str]] = [
        (attribute, value)
        for attribute in ("sourceFile", "odcFile", "singleSignOnId")
        if (value := element.get(attribute)) is not None
    ]
    for index, child in enumerate(element):
        if _xml_local_name(child.tag) not in {
            "dbPr",
            "olapPr",
            "webPr",
            "textPr",
            "parameters",
        }:
            continue
        entries.append(
            (
                f"child:{index}:{_xml_display_name(child.tag)}",
                repr(_xml_fragment(child).sort_key()),
            )
        )
    return _private_external_data_signature(tuple(entries))


def _connection_snapshot(
    element: ElementTree.Element,
    warnings: set[str],
) -> ExternalDataConnectionSnapshot:
    """Read one connection while keeping all source material private."""
    deleted = _external_data_bool(
        element.get("deleted"),
        False,
        "deleted",
        warnings,
        context="connection",
    )
    if element.get("id") is None and not deleted:
        warnings.add(
            "FormulaFence found an external-data connection without its required id; "
            "the affected connection has a coverage gap."
        )
    connection_id = _external_data_unsigned_int(
        element,
        "id",
        None,
        warnings,
        context="connection",
    )
    interval = _external_data_unsigned_int(
        element,
        "interval",
        0,
        warnings,
        context="connection",
    )
    parameter_elements = [
        child for child in element if _xml_local_name(child.tag) == "parameters"
    ]
    if len(parameter_elements) > 1:
        warnings.add(
            "FormulaFence found multiple external-data parameter containers; "
            "the affected connection has a coverage gap."
        )
    parameter_count = 0
    parameters_refresh_on_change = 0
    parameter_tag = f"{{{_SPREADSHEETML_NS}}}parameter"
    for parameters in parameter_elements:
        for parameter in parameters.findall(parameter_tag):
            parameter_count += 1
            if _external_data_bool(
                parameter.get("refreshOnChange"),
                False,
                "refreshOnChange",
                warnings,
                context="connection parameter",
            ):
                parameters_refresh_on_change += 1
    source_components: list[str] = []
    for element_name, component in (
        ("dbPr", "database"),
        ("olapPr", "olap"),
        ("webPr", "web_query"),
        ("textPr", "text_import"),
        ("parameters", "parameters"),
    ):
        count = sum(_xml_local_name(child.tag) == element_name for child in element)
        if count:
            source_components.append(component)
        if count > 1:
            warnings.add(
                "FormulaFence found repeated external-data connection source metadata; "
                "the affected connection has a coverage gap."
            )
    return ExternalDataConnectionSnapshot(
        connection_id=connection_id,
        source_type=_connection_source_type(element, warnings),
        deleted=deleted,
        refresh_on_load=_external_data_bool(
            element.get("refreshOnLoad"),
            False,
            "refreshOnLoad",
            warnings,
            context="connection",
        ),
        refresh_interval_minutes=interval if interval else None,
        background=_external_data_bool(
            element.get("background"),
            False,
            "background",
            warnings,
            context="connection",
        ),
        keep_alive=_external_data_bool(
            element.get("keepAlive"),
            False,
            "keepAlive",
            warnings,
            context="connection",
        ),
        save_data=_external_data_bool(
            element.get("saveData"),
            False,
            "saveData",
            warnings,
            context="connection",
        ),
        save_password=_external_data_bool(
            element.get("savePassword"),
            False,
            "savePassword",
            warnings,
            context="connection",
        ),
        has_source_file=element.get("sourceFile") is not None,
        has_connection_file=element.get("odcFile") is not None,
        only_use_connection_file=_external_data_bool(
            element.get("onlyUseConnectionFile"),
            False,
            "onlyUseConnectionFile",
            warnings,
            context="connection",
        ),
        reconnection_method=_connection_reconnection_method(element, warnings),
        credential_method=_external_data_enum(
            element.get("credentials"),
            "integrated",
            _EXTERNAL_CREDENTIAL_METHODS,
            warnings,
            context="connection",
            attribute="credentials",
        ),
        minimum_refreshable_version=(
            _external_data_unsigned_int(
                element,
                "minRefreshableVersion",
                0,
                warnings,
                context="connection",
                maximum=255,
            )
            or 0
        ),
        has_single_sign_on_id=element.get("singleSignOnId") is not None,
        awaiting_initial_refresh=_external_data_bool(
            element.get("new"),
            False,
            "new",
            warnings,
            context="connection",
        ),
        has_name=element.get("name") is not None,
        has_description=element.get("description") is not None,
        source_components=tuple(source_components),
        parameter_count=parameter_count,
        parameters_refresh_on_change=parameters_refresh_on_change,
        identity_signature=_connection_identity_signature(element),
        source_configuration_signature=_connection_source_configuration_signature(element),
        opaque_metadata=_external_data_opaque_metadata(
            element,
            known_attributes=frozenset(
                {
                    "id",
                    "sourceFile",
                    "odcFile",
                    "keepAlive",
                    "interval",
                    "name",
                    "description",
                    "type",
                    "reconnectionMethod",
                    "refreshedVersion",
                    "minRefreshableVersion",
                    "savePassword",
                    "new",
                    "deleted",
                    "onlyUseConnectionFile",
                    "background",
                    "refreshOnLoad",
                    "saveData",
                    "credentials",
                    "singleSignOnId",
                }
            ),
            known_children=frozenset(
                {"dbPr", "olapPr", "webPr", "textPr", "parameters"}
            ),
        ),
    )


def _external_data_part_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    *,
    context: str,
) -> ElementTree.Element | None:
    """Read one external-data part without allowing a bad sibling to hide all controls."""
    try:
        return _xml_root(archive, member)
    except (KeyError, ElementTree.ParseError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} OOXML ({type(error).__name__}); the affected controls were not compared."
        )
        return None


def _external_data_connection_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info: ZipInfo,
    budget: _ExternalDataConnectionXmlBudget,
) -> str | None:
    """Stream a Connection XML part before the private tree is materialized."""
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if budget.remaining_xml_elements <= 0:
        return _private_external_data_signature(
            (("connection-xml-structure-budget-exhausted", metadata),)
        )
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _EXTERNAL_DATA_CONNECTION_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Keep the existing full-parser coverage diagnostic for malformed or
        # unreadable XML. Only a successfully streamed overage can skip that
        # materializing parser safely.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    # An overage can contain an unbounded number of unseen descendants. Stop
    # spending the aggregate structural budget after its first failed part.
    budget.remaining_xml_elements = 0
    signature_entries = [
        (
            "xml-structure-budget-exhausted",
            metadata,
        )
    ]
    if (payload_signature := _private_archive_member_payload_signature(archive, info)) is not None:
        signature_entries.append(("payload", payload_signature))
    return _private_external_data_signature(tuple(signature_entries))


def _external_data_connection_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _ExternalDataConnectionXmlBudget,
) -> tuple[ElementTree.Element | None, str | None]:
    """Read one bounded external-data Connection XML root privately."""
    if budget.remaining_parts <= 0:
        try:
            info = archive.getinfo(member)
            metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        except KeyError:
            metadata = repr((member, "missing"))
        warnings.add(
            "FormulaFence reached its bounded external-data Connections XML part "
            "count; affected connection controls were not compared."
        )
        return None, _private_external_data_signature(
            (("connection-xml-part-count-budget-exhausted", metadata),)
        )
    try:
        info = archive.getinfo(member)
    except KeyError:
        return (
            _external_data_part_root(
                archive,
                member,
                warnings,
                context="Connections",
            ),
            None,
        )
    budget.remaining_parts -= 1
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _EXTERNAL_DATA_CONNECTION_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized external-data Connections "
            "XML part; affected connection controls have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("oversized-connection-xml-part", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded external-data Connections XML read "
            "budget; affected connection controls were not compared."
        )
        return None, _private_external_data_signature(
            (("connection-xml-read-budget-exhausted", metadata),)
        )
    # A structural preflight must count against the same aggregate byte budget:
    # it reads the whole member even if parsing is then deliberately skipped.
    budget.remaining_bytes -= info.file_size
    structure_fallback_signature = (
        _external_data_connection_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        warnings.add(
            "FormulaFence did not fully read an external-data Connections XML part "
            "whose XML structure exceeds the safety budget; affected connection "
            "controls have a coverage gap."
        )
        return None, structure_fallback_signature
    return (
        _external_data_part_root(
            archive,
            member,
            warnings,
            context="Connections",
        ),
        None,
    )


def _query_table_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info: ZipInfo,
    budget: _QueryTableXmlBudget,
) -> str | None:
    """Stream a query-table XML part before its private tree is materialized."""
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if budget.remaining_xml_elements <= 0:
        return _private_external_data_signature(
            (("query-table-xml-structure-budget-exhausted", metadata),)
        )
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _QUERY_TABLE_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the existing full-parser diagnostic for malformed or
        # unreadable XML. Only a successfully streamed overage can bypass that
        # materializing parser safely.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    # An overage can contain an unbounded number of unseen descendants. Stop
    # spending the aggregate structural budget after its first failed part.
    budget.remaining_xml_elements = 0
    signature_entries = [("xml-structure-budget-exhausted", metadata)]
    if (
        payload_signature := _private_archive_member_payload_signature(archive, info)
    ) is not None:
        signature_entries.append(("payload", payload_signature))
    return _private_external_data_signature(tuple(signature_entries))


def _query_table_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _QueryTableXmlBudget,
    *,
    context: str,
) -> tuple[ElementTree.Element | None, str | None]:
    """Read one bounded, cached query-table XML root privately."""
    if member in budget.roots:
        return budget.roots[member]

    def retain(
        root: ElementTree.Element | None,
        fallback_signature: str | None,
    ) -> tuple[ElementTree.Element | None, str | None]:
        result = (root, fallback_signature)
        budget.roots[member] = result
        return result

    if budget.remaining_parts <= 0:
        try:
            info = archive.getinfo(member)
            metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        except KeyError:
            metadata = repr((member, "missing"))
        warnings.add(
            "FormulaFence reached its bounded query-table XML part count; "
            "affected query-table controls were not compared."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("query-table-xml-part-count-budget-exhausted", metadata),)
            ),
        )
    try:
        info = archive.getinfo(member)
    except KeyError:
        return retain(
            _external_data_part_root(archive, member, warnings, context=context),
            None,
        )
    budget.remaining_parts -= 1
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _QUERY_TABLE_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized query-table XML part; "
            "the affected query-table controls have a coverage gap."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("oversized-query-table-xml-part", metadata),)
            ),
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded query-table XML read budget; "
            "affected query-table controls were not compared."
        )
        return retain(
            None,
            _private_external_data_signature(
                (("query-table-xml-read-budget-exhausted", metadata),)
            ),
        )
    # Structural preflight reads the whole member even if parsing is then
    # deliberately skipped, so it consumes the shared byte budget first.
    budget.remaining_bytes -= info.file_size
    structure_fallback_signature = _query_table_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        budget,
    )
    if structure_fallback_signature is not None:
        warnings.add(
            "FormulaFence did not fully read a query-table XML part whose XML "
            "structure exceeds the safety budget; affected query-table controls "
            "have a coverage gap."
        )
        return retain(None, structure_fallback_signature)
    return retain(
        _external_data_part_root(archive, member, warnings, context=context),
        None,
    )


def _external_data_part_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_PackageRelationship, ...]:
    """Read relationships for one external-data owner part safely."""
    try:
        return _package_relationships(archive, source_member)
    except (KeyError, ElementTree.ParseError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships ({type(error).__name__}); "
            "the affected controls were not compared."
        )
        return ()


def _connection_snapshots(
    archive: ZipFile,
    relationships: tuple[_PackageRelationship, ...],
    warnings: set[str],
    budget: _ExternalDataConnectionXmlBudget,
) -> tuple[ExternalDataConnectionSnapshot, ...]:
    """Read every workbook-connected ``connections`` part safely."""
    connection_parts = [
        relationship
        for relationship in relationships
        if relationship.relationship_type.rsplit("/", maxsplit=1)[-1] == "connections"
    ]
    if len(connection_parts) > 1:
        warnings.add(
            "FormulaFence found multiple external-data Connections parts; "
            "the workbook has a coverage gap."
        )
    snapshots: list[ExternalDataConnectionSnapshot] = []
    connection_tag = f"{{{_SPREADSHEETML_NS}}}connection"
    for relationship in connection_parts:
        if relationship.target is None:
            warnings.add(
                "FormulaFence found a Connections relationship without a safe internal target; "
                "the affected controls were not compared."
            )
            continue
        root, fallback_signature = _external_data_connection_bounded_root(
            archive,
            relationship.target,
            warnings,
            budget,
        )
        if root is None:
            if fallback_signature is not None:
                snapshots.append(
                    ExternalDataConnectionSnapshot(
                        connection_id=None,
                        source_type="unrecognized",
                        opaque_metadata=ExternalDataOpaqueMetadataSnapshot(
                            count=1,
                            signature=fallback_signature,
                        ),
                    )
                )
            continue
        if (
            _xml_local_name(root.tag) != "connections"
            or _xml_namespace(root.tag) != _SPREADSHEETML_NS
        ):
            warnings.add(
                "FormulaFence found a workbook Connections part with an unexpected root; "
                "the affected controls were not compared."
            )
            continue
        if root.attrib or any(
            _xml_local_name(child.tag) != "connection" for child in root
        ):
            warnings.add(
                "FormulaFence found unmodelled Connections-container metadata; "
                "the affected controls have a coverage gap."
            )
        snapshots.extend(
            _connection_snapshot(connection, warnings)
            for connection in root.findall(connection_tag)
        )
    identifiers = [
        snapshot.connection_id
        for snapshot in snapshots
        if snapshot.connection_id is not None
    ]
    if len(identifiers) != len(set(identifiers)):
        warnings.add(
            "FormulaFence found duplicate external-data connection ids; "
            "the affected controls have a coverage gap."
        )
    return tuple(sorted(snapshots, key=ExternalDataConnectionSnapshot.sort_key))


def _query_table_snapshot(
    sheet: str,
    element: ElementTree.Element,
    warnings: set[str],
) -> QueryTableRefreshSnapshot:
    """Read query-table refresh behavior without names or result metadata."""
    if element.get("connectionId") is None:
        warnings.add(
            "FormulaFence found a query table without its required connection id; "
            "the affected control has a coverage gap."
        )
    connection_id = _external_data_unsigned_int(
        element,
        "connectionId",
        None,
        warnings,
        context="query table",
    )
    return QueryTableRefreshSnapshot(
        sheet=sheet,
        connection_id=connection_id,
        refresh_on_load=_external_data_bool(
            element.get("refreshOnLoad"),
            False,
            "refreshOnLoad",
            warnings,
            context="query table",
        ),
        background_refresh=_external_data_bool(
            element.get("backgroundRefresh"),
            True,
            "backgroundRefresh",
            warnings,
            context="query table",
        ),
        refresh_disabled=_external_data_bool(
            element.get("disableRefresh"),
            False,
            "disableRefresh",
            warnings,
            context="query table",
        ),
        remove_data_on_save=_external_data_bool(
            element.get("removeDataOnSave"),
            False,
            "removeDataOnSave",
            warnings,
            context="query table",
        ),
        fill_formulas=_external_data_bool(
            element.get("fillFormulas"),
            False,
            "fillFormulas",
            warnings,
            context="query table",
        ),
        connection_edit_disabled=_external_data_bool(
            element.get("disableEdit"),
            False,
            "disableEdit",
            warnings,
            context="query table",
        ),
        growth_behavior=_external_data_enum(
            element.get("growShrinkType"),
            "insert_delete",
            _QUERY_TABLE_GROWTH_BEHAVIORS,
            warnings,
            context="query table",
            attribute="growShrinkType",
        ),
        has_name=element.get("name") is not None,
        has_refresh_metadata=any(
            _xml_local_name(child.tag) == "queryTableRefresh" for child in element
        ),
        identity_signature=_private_external_data_signature(
            (("name", element.get("name")),)
            if element.get("name") is not None
            else ()
        ),
        opaque_metadata=_external_data_opaque_metadata(
            element,
            known_attributes=frozenset(
                {
                    "name",
                    "headers",
                    "rowNumbers",
                    "disableRefresh",
                    "backgroundRefresh",
                    "firstBackgroundRefresh",
                    "refreshOnLoad",
                    "growShrinkType",
                    "fillFormulas",
                    "removeDataOnSave",
                    "disableEdit",
                    "preserveFormatting",
                    "adjustColumnWidth",
                    "intermediate",
                    "connectionId",
                    "autoFormatId",
                    "applyNumberFormats",
                    "applyBorderFormats",
                    "applyFontFormats",
                    "applyPatternFormats",
                    "applyAlignmentFormats",
                    "applyWidthHeightFormats",
                }
            ),
            known_children=frozenset({"queryTableRefresh"}),
        ),
    )


def _query_table_refresh_snapshots(
    archive: ZipFile,
    sheet_parts: Mapping[str, tuple[str, str]],
    warnings: set[str],
    budget: _QueryTableXmlBudget,
) -> tuple[QueryTableRefreshSnapshot, ...]:
    """Read query tables linked directly from worksheets or through Excel tables."""
    snapshots: list[QueryTableRefreshSnapshot] = []
    seen_parts: set[tuple[str, str]] = set()

    def append_query_table(sheet: str, target: str | None, *, context: str) -> None:
        if target is None:
            warnings.add(
                "FormulaFence found a query-table relationship without a safe internal target; "
                "the affected controls were not compared."
            )
            return
        part_key = (sheet, target)
        if part_key in seen_parts:
            return
        seen_parts.add(part_key)
        if target in budget.templates:
            snapshots.append(replace(budget.templates[target], sheet=sheet))
            return
        root, fallback_signature = _query_table_bounded_root(
            archive,
            target,
            warnings,
            budget,
            context=context,
        )
        if root is None:
            if fallback_signature is not None:
                snapshots.append(
                    QueryTableRefreshSnapshot(
                        sheet=sheet,
                        connection_id=None,
                        opaque_metadata=ExternalDataOpaqueMetadataSnapshot(
                            count=1,
                            signature=fallback_signature,
                        ),
                    )
                )
            return
        if (
            _xml_local_name(root.tag) != "queryTable"
            or _xml_namespace(root.tag) != _SPREADSHEETML_NS
        ):
            warnings.add(
                "FormulaFence found a query-table part with an unexpected root; "
                "the affected controls were not compared."
            )
            return
        snapshot = _query_table_snapshot(sheet, root, warnings)
        budget.templates[target] = snapshot
        snapshots.append(snapshot)

    for sheet, (sheet_member, sheet_type) in sheet_parts.items():
        if sheet_type != "worksheet":
            continue
        relationships_member = _relationship_part_path(sheet_member)
        if relationships_member not in archive.namelist():
            continue
        relationships = _external_data_part_relationships(
            archive,
            sheet_member,
            warnings,
            context="worksheet query-table",
        )
        for relationship in relationships:
            relationship_kind = relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
            if relationship_kind == "queryTable":
                append_query_table(
                    sheet,
                    relationship.target,
                    context="worksheet query-table",
                )
                continue
            if relationship_kind != "table":
                continue
            if relationship.target is None:
                warnings.add(
                    "FormulaFence found a worksheet table relationship without a safe internal "
                    "target; linked query-table controls were not compared."
                )
                continue
            table_root = _external_data_part_root(
                archive,
                relationship.target,
                warnings,
                context="worksheet table",
            )
            if table_root is None:
                continue
            if (
                _xml_local_name(table_root.tag) != "table"
                or _xml_namespace(table_root.tag) != _SPREADSHEETML_NS
            ):
                warnings.add(
                    "FormulaFence found a worksheet table part with an unexpected root; "
                    "linked query-table controls were not compared."
                )
                continue
            table_relationships_member = _relationship_part_path(relationship.target)
            if table_relationships_member not in archive.namelist():
                continue
            table_relationships = _external_data_part_relationships(
                archive,
                relationship.target,
                warnings,
                context="worksheet table query-table",
            )
            for table_relationship in table_relationships:
                if table_relationship.relationship_type.rsplit("/", maxsplit=1)[-1] != "queryTable":
                    continue
                append_query_table(
                    sheet,
                    table_relationship.target,
                    context="table query-table",
                )
    return tuple(sorted(snapshots, key=QueryTableRefreshSnapshot.sort_key))


def _pivot_cache_source_type(
    cache_source: ElementTree.Element,
    warnings: set[str],
) -> str:
    """Normalize a pivot cache source type without exposing source values."""
    source_type = cache_source.get("type")
    if source_type is None:
        warnings.add(
            "FormulaFence found a pivot cache source without its required type; "
            "the affected control has a coverage gap."
        )
        return "unrecognized"
    return _external_data_enum(
        source_type,
        "unrecognized",
        _PIVOT_CACHE_SOURCE_TYPES,
        warnings,
        context="pivot cache source",
        attribute="type",
    )


def _pivot_cache_snapshot(
    cache_id: int | None,
    element: ElementTree.Element,
    warnings: set[str],
) -> PivotCacheRefreshSnapshot:
    """Read one pivot-cache source and refresh setting set safely."""
    cache_source = element.find(f"{{{_SPREADSHEETML_NS}}}cacheSource")
    if cache_source is None:
        warnings.add(
            "FormulaFence found a pivot cache without a source definition; "
            "the affected control has a coverage gap."
        )
        source_type = "unrecognized"
        connection_id = None
        source_configuration_signature = None
    else:
        source_type = _pivot_cache_source_type(cache_source, warnings)
        if source_type == "external" and cache_source.get("connectionId") is None:
            warnings.add(
                "FormulaFence found an external pivot cache without a connection id; "
                "the affected control has a coverage gap."
            )
        connection_id = _external_data_unsigned_int(
            cache_source,
            "connectionId",
            None,
            warnings,
            context="pivot cache source",
        )
        source_configuration_signature = _private_external_data_signature(
            (("cacheSource", repr(_xml_fragment(cache_source).sort_key())),)
        )
    return PivotCacheRefreshSnapshot(
        cache_id=cache_id,
        source_type=source_type,
        connection_id=connection_id,
        refresh_on_load=_external_data_bool(
            element.get("refreshOnLoad"),
            False,
            "refreshOnLoad",
            warnings,
            context="pivot cache",
        ),
        background_query=_external_data_bool(
            element.get("backgroundQuery"),
            False,
            "backgroundQuery",
            warnings,
            context="pivot cache",
        ),
        refresh_enabled=_external_data_bool(
            element.get("enableRefresh"),
            True,
            "enableRefresh",
            warnings,
            context="pivot cache",
        ),
        save_data=_external_data_bool(
            element.get("saveData"),
            True,
            "saveData",
            warnings,
            context="pivot cache",
        ),
        upgrade_on_refresh=_external_data_bool(
            element.get("upgradeOnRefresh"),
            False,
            "upgradeOnRefresh",
            warnings,
            context="pivot cache",
        ),
        source_configuration_signature=source_configuration_signature,
        opaque_metadata=_external_data_opaque_metadata(
            element,
            known_attributes=frozenset(
                {
                    "invalid",
                    "saveData",
                    "refreshOnLoad",
                    "optimizeMemory",
                    "enableRefresh",
                    "refreshedBy",
                    "refreshedDate",
                    "backgroundQuery",
                    "missingItemsLimit",
                    "createdVersion",
                    "refreshedVersion",
                    "minRefreshableVersion",
                    "recordCount",
                    "upgradeOnRefresh",
                    "tupleCache",
                    "supportSubquery",
                    "supportAdvancedDrill",
                    "id",
                }
            ),
            known_children=frozenset(
                {
                    "cacheSource",
                    "cacheFields",
                    "cacheHierarchies",
                    "kpis",
                    "tupleCache",
                    "calculatedItems",
                    "calculatedMembers",
                    "dimensions",
                    "measureGroups",
                    "maps",
                }
            ),
            omit_pivot_cache_extension_ids=True,
        ),
    )


def _pivot_cache_refresh_snapshots(
    archive: ZipFile,
    workbook: ElementTree.Element,
    relationships: tuple[_PackageRelationship, ...],
    warnings: set[str],
) -> tuple[PivotCacheRefreshSnapshot, ...]:
    """Read pivot-cache refresh controls linked from the workbook."""
    relationship_targets = {
        relationship.relationship_id: relationship.target
        for relationship in relationships
        if relationship.relationship_id
        and relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
        == "pivotCacheDefinition"
    }
    cache_container = workbook.find(f"{{{_SPREADSHEETML_NS}}}pivotCaches")
    if cache_container is None:
        return ()
    cache_tag = f"{{{_SPREADSHEETML_NS}}}pivotCache"
    relationship_id_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    snapshots: list[PivotCacheRefreshSnapshot] = []
    xml_budget = _PivotXmlBudget()
    for cache in cache_container.findall(cache_tag):
        if cache.get("cacheId") is None:
            warnings.add(
                "FormulaFence found a pivot-cache declaration without its required cache id; "
                "the affected control has a coverage gap."
            )
        cache_id = _external_data_unsigned_int(
            cache,
            "cacheId",
            None,
            warnings,
            context="pivot-cache declaration",
        )
        relationship_id = cache.get(relationship_id_attribute)
        if not relationship_id or relationship_id not in relationship_targets:
            warnings.add(
                "FormulaFence could not locate a pivot-cache definition relationship; "
                "the affected controls were not compared."
            )
            continue
        target = relationship_targets[relationship_id]
        if target is None:
            warnings.add(
                "FormulaFence found a pivot-cache definition without a safe internal target; "
                "the affected controls were not compared."
            )
            continue
        payload, _fallback_signature = _pivot_xml_payload(
            archive,
            target,
            warnings,
            xml_budget,
        )
        if payload is None:
            continue
        try:
            root = _xml_root_from_payload(payload)
        except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not inspect pivot-cache definition OOXML "
                f"({type(error).__name__}); the affected controls were not compared."
            )
            continue
        if (
            _xml_local_name(root.tag) != "pivotCacheDefinition"
            or _xml_namespace(root.tag) != _SPREADSHEETML_NS
        ):
            warnings.add(
                "FormulaFence found a pivot-cache definition with an unexpected root; "
                "the affected controls were not compared."
            )
            continue
        snapshots.append(_pivot_cache_snapshot(cache_id, root, warnings))
    identifiers = [snapshot.cache_id for snapshot in snapshots if snapshot.cache_id is not None]
    if len(identifiers) != len(set(identifiers)):
        warnings.add(
            "FormulaFence found duplicate pivot-cache ids; "
            "the affected controls have a coverage gap."
        )
    return tuple(sorted(snapshots, key=PivotCacheRefreshSnapshot.sort_key))


def _external_data_metadata(
    path: Path,
    *,
    power_query_item_members: tuple[str, ...],
) -> _ExternalDataMetadata:
    """Read external-data refresh controls before the workbook reader drops them."""
    warnings: set[str] = set()
    default_settings = ExternalDataRefreshSettingsSnapshot()
    default_external_link_packages = ExternalLinkPackageSnapshot()
    default_power_query = PowerQuerySnapshot()
    try:
        with ZipFile(path) as archive:
            workbook = _external_data_part_root(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
            )
            if workbook is None:
                return _ExternalDataMetadata(
                    refresh_settings=default_settings,
                    connections=(),
                    query_tables=(),
                    pivot_caches=(),
                    external_link_packages=default_external_link_packages,
                    indexed_external_workbook_paths=(),
                    power_query=default_power_query,
                    warnings=tuple(sorted(warnings)),
                )
            refresh_settings = _external_data_workbook_settings(workbook, warnings)
            workbook_relationships = _external_data_part_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
            )
            connections = _connection_snapshots(
                archive,
                workbook_relationships,
                warnings,
                _ExternalDataConnectionXmlBudget(),
            )
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (KeyError, ElementTree.ParseError, ValueError) as error:
                warnings.add(
                    "FormulaFence could not map worksheet OOXML for query-table inspection "
                    f"({type(error).__name__}); query-table controls were not compared."
                )
                sheet_parts = {}
            query_table_xml_budget = _QueryTableXmlBudget()
            query_tables = _query_table_refresh_snapshots(
                archive,
                sheet_parts,
                warnings,
                query_table_xml_budget,
            )
            pivot_caches = _pivot_cache_refresh_snapshots(
                archive,
                workbook,
                workbook_relationships,
                warnings,
            )
            external_link_xml_budget = _ExternalLinkXmlBudget()
            external_link_packages = _external_link_packages_snapshot(
                archive,
                workbook,
                workbook_relationships,
                warnings,
                external_link_xml_budget,
            )
            indexed_external_workbook_paths = _indexed_external_workbook_paths(
                archive,
                workbook,
                workbook_relationships,
                warnings,
                external_link_xml_budget,
            )
            power_query = _power_query_snapshot(
                archive,
                warnings,
                power_query_item_members,
            )
    except (BadZipFile, OSError, ValueError) as error:
        return _ExternalDataMetadata(
            refresh_settings=default_settings,
            connections=(),
            query_tables=(),
            pivot_caches=(),
            external_link_packages=default_external_link_packages,
            indexed_external_workbook_paths=(),
            power_query=default_power_query,
            warnings=(
                "FormulaFence could not inspect external-data OOXML "
                f"({type(error).__name__}); external-data controls were not compared.",
            ),
        )
    return _ExternalDataMetadata(
        refresh_settings=refresh_settings,
        connections=connections,
        query_tables=query_tables,
        pivot_caches=pivot_caches,
        external_link_packages=external_link_packages,
        indexed_external_workbook_paths=indexed_external_workbook_paths,
        power_query=power_query,
        warnings=tuple(sorted(warnings)),
    )


def _normalise_content_type_part_name(part_name: str) -> str | None:
    """Turn an OPC content-type part name into a safe ZIP member name."""
    normalised = posixpath.normpath(part_name.lstrip("/"))
    if normalised in {"", ".", ".."} or normalised.startswith("../"):
        return None
    return normalised


def _xlm_macro_content_type_parts(
    archive: ZipFile,
    warnings: set[str],
) -> dict[str, set[str]]:
    """Find XLM macro-sheet parts declared through OPC content types."""
    try:
        root = _xml_root(archive, "[Content_Types].xml")
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect XLM macro-sheet content types "
            f"({type(error).__name__}); affected macro-sheet controls may be incomplete."
        )
        return {}
    if (
        _xml_local_name(root.tag) != "Types"
        or _xml_namespace(root.tag) != _CONTENT_TYPES_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected OPC content-types root while inspecting "
            "XLM macro sheets; affected macro-sheet controls may be incomplete."
        )
        return {}

    parts: dict[str, set[str]] = defaultdict(set)
    override_tag = f"{{{_CONTENT_TYPES_NS}}}Override"
    for override in root.findall(override_tag):
        kind = _XLM_MACRO_SHEET_CONTENT_TYPES.get(override.get("ContentType", ""))
        if kind is None:
            continue
        part_name = override.get("PartName")
        member = _normalise_content_type_part_name(part_name) if part_name else None
        if member is None:
            warnings.add(
                "FormulaFence found an XLM macro-sheet content type without a safe part "
                "name; the affected macro-sheet controls were not compared."
            )
            continue
        parts[member].add(kind)
    return dict(parts)


def _xlm_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
    missing_is_warning: bool = False,
) -> tuple[_XlmRawRelationship, ...]:
    """Read private relationship endpoints without following any target."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        if missing_is_warning:
            warnings.add(
                "FormulaFence could not locate "
                f"{context} relationships while inspecting XLM macro sheets; "
                "affected macro-sheet controls may be incomplete."
            )
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for XLM macro sheets ({type(error).__name__}); "
            "affected macro-sheet controls were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting XLM macro sheets; "
            "affected macro-sheet controls were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_XlmRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _XlmRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting XLM macro "
            "sheets; affected macro-sheet controls may be incomplete."
        )
    return tuple(relationships)


def _xlm_relationship_signature(
    relationships: tuple[_XlmRawRelationship, ...],
) -> str | None:
    """Fingerprint relationship semantics while ignoring arbitrary identifiers."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _xlm_related_part_payloads(
    archive: ZipFile,
    relationships: tuple[_XlmRawRelationship, ...],
    warnings: set[str],
    budget: _XlmRelatedPartBudget,
) -> _XlmRelatedPartPayloadInspection:
    """Fingerprint direct internal XLM relationship targets without parsing them.

    Macro-sheet XML can point to OLE objects, embedded packages, drawings, and
    other package parts. Hash their bytes only after resolving a safe internal
    target; never follow an external target or parse an embedded payload.
    """
    members: set[str] = set()
    unresolved_entries: list[tuple[str, str]] = []
    for relationship in relationships:
        if relationship.target_mode.casefold() != "internal":
            continue
        if relationship.safe_target is None:
            warnings.add(
                "FormulaFence found an XLM macro-sheet internal relationship without "
                "a safe related-part target; the affected controls have a coverage gap."
            )
            unresolved_entries.append(
                (
                    "unsafe-target",
                    repr((relationship.relationship_type, relationship.target)),
                )
            )
            continue
        members.add(relationship.safe_target)

    entries = list(unresolved_entries)
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts == 0:
            warnings.add(
                "FormulaFence reached its bounded XLM macro-sheet related-part count "
                "budget; the affected controls have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate an XLM macro-sheet internal related "
                "part; the affected controls were not compared."
            )
            entries.append(("missing-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _XLM_RELATED_PART_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized XLM macro-sheet related "
                "part; the affected controls have a coverage gap."
            )
            entries.append(("oversized-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded XLM macro-sheet related-part read "
                "budget; the affected controls have a coverage gap."
            )
            entries.append(("read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as related_part:
                while chunk := related_part.read(_XLM_RELATED_PART_HASH_CHUNK_BYTES):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("related part exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("related part did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint an XLM macro-sheet internal related "
                f"part ({type(error).__name__}); the affected controls were not compared."
            )
            entries.append(("unreadable-part", metadata))
            uninspected_part_count += 1
            continue
        entries.append(("payload", repr((member, digest.hexdigest()))))
        fingerprinted_part_count += 1

    entries.sort()
    return _XlmRelatedPartPayloadInspection(
        internal_part_count=len(members) + len(unresolved_entries),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_signature=_private_external_data_signature(tuple(entries)),
    )


def _xlm_macro_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
) -> tuple[object, ...]:
    """Canonicalize macro XML while resolving relationship ids privately.

    Relationship identifiers are writer-chosen.  Replacing each ``r:id`` with
    its relationship semantic tuple makes an identifier-only rewrite compare
    equal, but retains the target/type change that would alter macro behavior.
    """
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute == relationship_attribute:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
        else:
            attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _xlm_macro_fragment(child, relationship_semantics) for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _xlm_macro_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info: ZipInfo,
    budget: _XlmMacroXmlBudget,
) -> str | None:
    """Stream an XLM macro-sheet part before its private tree is materialized."""
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if budget.remaining_xml_elements <= 0:
        return _private_external_data_signature(
            (("xlm-macro-sheet-xml-structure-budget-exhausted", metadata),)
        )
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _XLM_MACRO_SHEET_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the existing full-parser diagnostic for malformed or
        # unreadable XML. Only a successfully streamed overage can bypass that
        # materializing parser safely.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    # An overage can contain an unbounded number of unseen descendants. Stop
    # spending the aggregate structural budget after its first failed part.
    budget.remaining_xml_elements = 0
    signature_entries = [("xml-structure-budget-exhausted", metadata)]
    if (
        payload_signature := _private_archive_member_payload_signature(archive, info)
    ) is not None:
        signature_entries.append(("payload", payload_signature))
    return _private_external_data_signature(tuple(signature_entries))


def _xlm_macro_formula_cell_count(root: ElementTree.Element) -> int:
    """Count macro-sheet cells with a formula without evaluating the formula."""
    return sum(
        any(_xml_local_name(child.tag) == "f" for child in cell)
        for cell in root.iter()
        if _xml_local_name(cell.tag) == "c"
    )


def _xlm_macro_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _XlmMacroXmlBudget,
    related_part_budget: _XlmRelatedPartBudget,
) -> _XlmMacroSheetInspection:
    """Fingerprint one XLM macro-sheet part and its relationships privately."""
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate an XLM macro-sheet package part; "
            "the affected macro-sheet controls were not compared."
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=_private_external_data_signature(
                (("missing-member", member),)
            ),
        )
    if xml_budget.remaining_parts <= 0:
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        warnings.add(
            "FormulaFence reached its bounded XLM macro-sheet XML part count; "
            "affected macro-sheet controls were not compared."
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=_private_external_data_signature(
                (("xlm-macro-sheet-xml-part-count-budget-exhausted", metadata),)
            ),
        )
    xml_budget.remaining_parts -= 1
    if info.file_size > _XLM_MACRO_SHEET_MAX_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized XLM macro-sheet part; "
            "the affected macro-sheet controls have a coverage gap."
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=_private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    if info.file_size > xml_budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded XLM macro-sheet XML read budget; "
            "affected macro-sheet controls were not compared."
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=_private_external_data_signature(
                (
                    (
                        "xlm-macro-sheet-xml-read-budget-exhausted",
                        repr((member, info.file_size, info.compress_size, info.CRC)),
                    ),
                )
            ),
        )
    # Structural preflight reads the whole member even if parsing is then
    # deliberately skipped, so it consumes the shared byte budget first.
    xml_budget.remaining_bytes -= info.file_size
    structure_fallback_signature = _xlm_macro_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        xml_budget,
    )
    if structure_fallback_signature is not None:
        warnings.add(
            "FormulaFence did not fully read an XLM macro-sheet XML part whose XML "
            "structure exceeds the safety budget; affected macro-sheet controls "
            "have a coverage gap."
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=structure_fallback_signature,
        )
    payload: bytes | None = None
    try:
        payload = archive.read(member)
        root = _xml_root_from_payload(payload)
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect an XLM macro-sheet XML part "
            f"({type(error).__name__}); the affected macro-sheet controls were not compared."
        )
        signature = (
            _private_payload_signature(payload)
            if payload is not None
            else _private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            )
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=signature,
        )
    if (
        _xml_local_name(root.tag) != "macrosheet"
        or _xml_namespace(root.tag) != _EXCEL_2006_MAIN_NS
    ):
        warnings.add(
            "FormulaFence found an XLM macro-sheet part with an unexpected root; "
            "the affected macro-sheet controls were not compared."
        )
        return _XlmMacroSheetInspection(
            member=member,
            program_signature=_private_payload_signature(payload),
        )

    relationships = _xlm_raw_relationships(
        archive,
        member,
        warnings,
        context="XLM macro-sheet",
    )
    relationships_by_id: dict[str, list[_XlmRawRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
    relationship_semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        semantics = sorted(match.semantic_key() for match in matches)
        if len(semantics) > 1:
            warnings.add(
                "FormulaFence found duplicate XLM macro-sheet relationship ids; "
                "the affected macro-sheet controls have a coverage gap."
            )
        relationship_semantics[relationship_id] = semantics[0]

    referenced_relationship_ids = {
        value
        for element in root.iter()
        if (value := element.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id")) is not None
    }
    if referenced_relationship_ids - set(relationship_semantics):
        warnings.add(
            "FormulaFence found an XLM macro-sheet relationship reference without a "
            "matching relationship; the affected macro-sheet controls have a coverage gap."
        )
    relationship_kinds = [
        relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
        for relationship in relationships
    ]
    related_part_payloads = _xlm_related_part_payloads(
        archive,
        relationships,
        warnings,
        related_part_budget,
    )
    formula_cell_count = _xlm_macro_formula_cell_count(root)
    try:
        program_signature = _private_external_data_signature(
            (("macro-sheet", repr(_xlm_macro_fragment(root, relationship_semantics))),)
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested XLM macro-sheet "
            "part; the affected macro-sheet controls were not compared."
        )
        return _XlmMacroSheetInspection(
            member=member,
            formula_cell_count=formula_cell_count,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            internal_related_part_count=related_part_payloads.internal_part_count,
            fingerprinted_related_part_count=(
                related_part_payloads.fingerprinted_part_count
            ),
            uninspected_related_part_count=related_part_payloads.uninspected_part_count,
            embedded_object_relationship_count=relationship_kinds.count("oleObject"),
            embedded_package_relationship_count=relationship_kinds.count("package"),
            program_signature=_private_payload_signature(payload),
            relationship_signature=_xlm_relationship_signature(relationships),
            related_part_payload_signature=related_part_payloads.payload_signature,
        )
    return _XlmMacroSheetInspection(
        member=member,
        formula_cell_count=formula_cell_count,
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        internal_related_part_count=related_part_payloads.internal_part_count,
        fingerprinted_related_part_count=related_part_payloads.fingerprinted_part_count,
        uninspected_related_part_count=related_part_payloads.uninspected_part_count,
        embedded_object_relationship_count=relationship_kinds.count("oleObject"),
        embedded_package_relationship_count=relationship_kinds.count("package"),
        inspected=True,
        program_signature=program_signature,
        relationship_signature=_xlm_relationship_signature(relationships),
        related_part_payload_signature=related_part_payloads.payload_signature,
    )


def _xlm_macro_metadata(path: Path) -> _XlmMacroMetadata:
    """Inspect XLM macro sheets before a workbook library can omit their code."""
    warnings: set[str] = set()
    default = XlmMacroSheetSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                workbook = _xml_root(archive, "xl/workbook.xml")
            except (KeyError, ElementTree.ParseError, ValueError) as error:
                warnings.add(
                    "FormulaFence could not inspect workbook OOXML for XLM macro sheets "
                    f"({type(error).__name__}); affected macro-sheet controls were not compared."
                )
                return _XlmMacroMetadata(default, tuple(sorted(warnings)))
            if (
                _xml_local_name(workbook.tag) != "workbook"
                or _xml_namespace(workbook.tag) != _SPREADSHEETML_NS
            ):
                warnings.add(
                    "FormulaFence found an unexpected workbook root while inspecting XLM "
                    "macro sheets; affected macro-sheet controls were not compared."
                )
                return _XlmMacroMetadata(default, tuple(sorted(warnings)))

            workbook_relationships = _xlm_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
                missing_is_warning=True,
            )
            macro_relationships = tuple(
                relationship
                for relationship in workbook_relationships
                if relationship.relationship_type in _XLM_MACRO_SHEET_RELATIONSHIPS
            )
            workbook_relationships_by_id: dict[
                str, list[_XlmRawRelationship]
            ] = defaultdict(list)
            for relationship in workbook_relationships:
                if relationship.relationship_id:
                    workbook_relationships_by_id[relationship.relationship_id].append(
                        relationship
                    )
            workbook_relationship_semantics = {
                relationship_id: sorted(
                    relationship.semantic_key() for relationship in matches
                )[0]
                for relationship_id, matches in workbook_relationships_by_id.items()
            }
            content_type_parts = _xlm_macro_content_type_parts(archive, warnings)
            discovered_members = {
                entry.filename
                for entry in archive.infolist()
                if _XLM_MACRO_SHEET_PART_PATTERN.fullmatch(entry.filename)
            }

            candidate_kinds: dict[str, set[str]] = defaultdict(set)
            declaration_entries: list[tuple[str, str]] = []
            declared_targets: set[str] = set()
            relationships_by_id: dict[str, list[_XlmRawRelationship]] = defaultdict(list)
            for relationship in macro_relationships:
                kind = _XLM_MACRO_SHEET_RELATIONSHIPS[relationship.relationship_type]
                declaration_entries.append(
                    ("workbook-relationship", repr((kind, relationship.semantic_key())))
                )
                if relationship.relationship_id:
                    relationships_by_id[relationship.relationship_id].append(relationship)
                else:
                    warnings.add(
                        "FormulaFence found an XLM macro-sheet workbook relationship without "
                        "an id; the affected macro-sheet controls have a coverage gap."
                    )
                if relationship.safe_target is None:
                    warnings.add(
                        "FormulaFence found an XLM macro-sheet relationship without a safe "
                        "internal part target; the affected macro-sheet controls were not compared."
                    )
                    continue
                candidate_kinds[relationship.safe_target].add(kind)
                declared_targets.add(relationship.safe_target)

            duplicate_relationship_ids = {
                relationship_id
                for relationship_id, matches in relationships_by_id.items()
                if len(matches) > 1
            }
            if duplicate_relationship_ids:
                warnings.add(
                    "FormulaFence found duplicate XLM macro-sheet workbook relationship ids; "
                    "the affected macro-sheet controls have a coverage gap."
                )

            for member, kinds in content_type_parts.items():
                candidate_kinds[member].update(kinds)
                declaration_entries.append(
                    ("content-type", repr((member, tuple(sorted(kinds)))))
                )
                if member not in declared_targets:
                    warnings.add(
                        "FormulaFence found an XLM macro-sheet content-type part not declared "
                        "by the workbook; the affected macro-sheet controls have a coverage gap."
                    )
            for member in discovered_members:
                candidate_kinds.setdefault(member, set())
                if member not in declared_targets:
                    warnings.add(
                        "FormulaFence found an XLM macro-sheet package part not declared by "
                        "the workbook; the affected macro-sheet controls have a coverage gap."
                    )

            binding_entries: list[tuple[str, str]] = []
            bound_relationship_ids: set[str] = set()
            binding_occurrences: dict[str, int] = defaultdict(int)
            hidden_macro_sheet_count = 0
            very_hidden_macro_sheet_count = 0
            sheets = workbook.find(f"{{{_SPREADSHEETML_NS}}}sheets")
            relationship_id_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
            if sheets is not None:
                for index, sheet in enumerate(sheets.findall(f"{{{_SPREADSHEETML_NS}}}sheet")):
                    relationship_id = sheet.get(relationship_id_attribute)
                    matches = relationships_by_id.get(relationship_id or "", [])
                    if not matches:
                        continue
                    if len(matches) != 1:
                        warnings.add(
                            "FormulaFence found a workbook sheet bound to repeated XLM macro-sheet "
                            "relationships; the affected macro-sheet controls have a coverage gap."
                        )
                    relationship = matches[0]
                    state = sheet.get("state", "visible")
                    if state not in {"visible", "hidden", "veryHidden"}:
                        warnings.add(
                            "FormulaFence found an unrecognized XLM macro-sheet visibility state; "
                            "the affected macro-sheet controls have a coverage gap."
                        )
                    hidden_macro_sheet_count += int(state == "hidden")
                    very_hidden_macro_sheet_count += int(state == "veryHidden")
                    if sheet.get("name") is None:
                        warnings.add(
                            "FormulaFence found an XLM macro-sheet workbook declaration without "
                            "a name; the affected macro-sheet controls have a coverage gap."
                        )
                    binding_entries.append(
                        (
                            f"sheet-binding:{index}",
                            repr(
                                _xlm_macro_fragment(
                                    sheet, workbook_relationship_semantics
                                )
                            ),
                        )
                    )
                    if relationship_id:
                        bound_relationship_ids.add(relationship_id)
                        binding_occurrences[relationship_id] += 1
            if any(count > 1 for count in binding_occurrences.values()):
                warnings.add(
                    "FormulaFence found multiple workbook sheets bound to one XLM macro-sheet "
                    "relationship; the affected macro-sheet controls have a coverage gap."
                )
            for relationship in macro_relationships:
                if (
                    relationship.relationship_id is None
                    or relationship.relationship_id not in bound_relationship_ids
                ):
                    warnings.add(
                        "FormulaFence found an XLM macro-sheet relationship not bound to a "
                        "workbook sheet; the affected macro-sheet controls have a coverage gap."
                    )
                    binding_entries.append(
                        (
                            "unbound-workbook-relationship",
                            repr(relationship.semantic_key()),
                        )
                    )

            inspections: list[_XlmMacroSheetInspection] = []
            unrecognized_macro_sheet_members: set[str] = set()
            international_macro_sheet_count = 0
            macro_sheet_xml_budget = _XlmMacroXmlBudget()
            related_part_budget = _XlmRelatedPartBudget()
            for member in sorted(candidate_kinds, key=str.casefold):
                kinds = candidate_kinds[member]
                if len(kinds) != 1:
                    warnings.add(
                        "FormulaFence could not identify one XLM macro-sheet part's declared "
                        "kind; the affected macro-sheet controls have a coverage gap."
                    )
                    unrecognized_macro_sheet_members.add(member)
                elif "international" in kinds:
                    international_macro_sheet_count += 1
                inspection = _xlm_macro_part_inspection(
                    archive,
                    member,
                    warnings,
                    macro_sheet_xml_budget,
                    related_part_budget,
                )
                inspections.append(inspection)
                if not inspection.inspected:
                    unrecognized_macro_sheet_members.add(member)

            def aggregate_signature(attribute: str) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            declaration_entries.extend(binding_entries)
            declaration_entries.sort()
            snapshot = XlmMacroSheetSnapshot(
                declared_macro_sheet_count=len(macro_relationships),
                macro_sheet_count=len(candidate_kinds),
                international_macro_sheet_count=international_macro_sheet_count,
                unrecognized_macro_sheet_count=len(unrecognized_macro_sheet_members),
                hidden_macro_sheet_count=hidden_macro_sheet_count,
                very_hidden_macro_sheet_count=very_hidden_macro_sheet_count,
                formula_cell_count=sum(
                    inspection.formula_cell_count for inspection in inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in inspections
                ),
                internal_related_part_count=sum(
                    inspection.internal_related_part_count for inspection in inspections
                ),
                fingerprinted_related_part_count=sum(
                    inspection.fingerprinted_related_part_count
                    for inspection in inspections
                ),
                uninspected_related_part_count=sum(
                    inspection.uninspected_related_part_count for inspection in inspections
                ),
                embedded_object_relationship_count=sum(
                    inspection.embedded_object_relationship_count
                    for inspection in inspections
                ),
                embedded_package_relationship_count=sum(
                    inspection.embedded_package_relationship_count
                    for inspection in inspections
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                program_signature=aggregate_signature("program_signature"),
                relationship_signature=aggregate_signature("relationship_signature"),
                related_part_payload_signature=aggregate_signature(
                    "related_part_payload_signature"
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _XlmMacroMetadata(
            default,
            (
                "FormulaFence could not inspect XLM macro-sheet OOXML "
                f"({type(error).__name__}); affected macro-sheet controls were not compared.",
            ),
        )
    return _XlmMacroMetadata(snapshot, tuple(sorted(warnings)))


def _xlm_automatic_macro_binding_kind(value: str | None) -> str | None:
    """Return the documented automatic-macro event for one workbook name."""
    if value is None:
        return None
    normalized = value.strip().casefold()
    if normalized.startswith("_xlnm."):
        normalized = normalized.removeprefix("_xlnm.")
    return _XLM_AUTOMATIC_MACRO_BINDING_NAMES.get(normalized)


def _xlm_automatic_macro_binding_metadata(
    path: Path,
) -> _XlmAutomaticMacroBindingMetadata:
    """Inspect static workbook-name dispatch to declared XLM macro sheets.

    Excel's legacy automatic macro names are workbook-scoped defined names. We
    intentionally recognize only the four documented names and only when a
    direct internal single-cell A1 reference names a workbook sheet declared
    through a raw XLM macro-sheet relationship. This records a routing surface
    without evaluating a name, parsing a macro command, or inferring whether
    Excel will execute it under the current security configuration.
    """
    warnings: set[str] = set()
    default = XlmAutomaticMacroBindingSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                workbook = _xml_root(archive, "xl/workbook.xml")
            except (KeyError, ElementTree.ParseError, ValueError) as error:
                warnings.add(
                    "FormulaFence could not inspect workbook OOXML for XLM automatic "
                    f"macro bindings ({type(error).__name__}); affected bindings were not "
                    "compared."
                )
                return _XlmAutomaticMacroBindingMetadata(
                    default, tuple(sorted(warnings))
                )
            if (
                _xml_local_name(workbook.tag) != "workbook"
                or _xml_namespace(workbook.tag) != _SPREADSHEETML_NS
            ):
                warnings.add(
                    "FormulaFence found an unexpected workbook root while inspecting XLM "
                    "automatic macro bindings; affected bindings were not compared."
                )
                return _XlmAutomaticMacroBindingMetadata(
                    default, tuple(sorted(warnings))
                )

            workbook_relationships = _xlm_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
                missing_is_warning=True,
            )
            workbook_relationships_by_id: dict[str, list[_XlmRawRelationship]] = (
                defaultdict(list)
            )
            macro_relationships_by_id: dict[str, list[_XlmRawRelationship]] = (
                defaultdict(list)
            )
            for relationship in workbook_relationships:
                if relationship.relationship_id is not None:
                    workbook_relationships_by_id[relationship.relationship_id].append(
                        relationship
                    )
                if relationship.relationship_type not in _XLM_MACRO_SHEET_RELATIONSHIPS:
                    continue
                if (
                    relationship.relationship_id is None
                    or relationship.safe_target is None
                ):
                    warnings.add(
                        "FormulaFence could not establish an XLM macro-sheet workbook "
                        "binding while inspecting automatic macro names; affected bindings "
                        "were not compared."
                    )
                    continue
                macro_relationships_by_id[relationship.relationship_id].append(
                    relationship
                )

            duplicate_relationship_ids = {
                relationship_id
                for relationship_id, relationships in workbook_relationships_by_id.items()
                if len(relationships) != 1
                and any(
                    relationship.relationship_type in _XLM_MACRO_SHEET_RELATIONSHIPS
                    for relationship in relationships
                )
            }
            if duplicate_relationship_ids:
                warnings.add(
                    "FormulaFence found duplicate XLM macro-sheet workbook relationship ids "
                    "while inspecting automatic macro bindings; affected bindings were not "
                    "compared."
                )

            macro_sheet_names: set[str] = set()
            sheets = workbook.find(f"{{{_SPREADSHEETML_NS}}}sheets")
            relationship_id_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
            if sheets is None:
                if macro_relationships_by_id:
                    warnings.add(
                        "FormulaFence could not locate workbook sheet declarations while "
                        "inspecting XLM automatic macro bindings; affected bindings were not "
                        "compared."
                    )
            else:
                for sheet in sheets.findall(f"{{{_SPREADSHEETML_NS}}}sheet"):
                    relationship_id = sheet.get(relationship_id_attribute)
                    matches = workbook_relationships_by_id.get(relationship_id or "", ())
                    if not matches:
                        continue
                    if len(matches) != 1:
                        continue
                    relationship = matches[0]
                    if (
                        relationship.relationship_type
                        not in _XLM_MACRO_SHEET_RELATIONSHIPS
                        or relationship.safe_target is None
                    ):
                        continue
                    name = sheet.get("name")
                    if name is None:
                        warnings.add(
                            "FormulaFence found an unnamed XLM macro-sheet workbook "
                            "declaration while inspecting automatic macro bindings; affected "
                            "bindings were not compared."
                        )
                        continue
                    macro_sheet_names.add(name.casefold())

            binding_entries: list[tuple[str, str]] = []
            defined_names = workbook.find(f"{{{_SPREADSHEETML_NS}}}definedNames")
            if defined_names is not None:
                definition_tag = f"{{{_SPREADSHEETML_NS}}}definedName"
                for definition in defined_names.findall(definition_tag):
                    # Excel attaches automatic macros to the workbook. A local
                    # defined name with the same spelling is not such a binding.
                    if definition.get("localSheetId") is not None:
                        continue
                    event = _xlm_automatic_macro_binding_kind(definition.get("name"))
                    if event is None:
                        continue
                    formula = (definition.text or "").strip()
                    candidate = formula[1:].strip() if formula.startswith("=") else formula
                    reference = parse_reference_token(candidate)
                    if (
                        reference is None
                        or reference.is_external
                        or reference.sheet is None
                        or reference.min_column is None
                        or reference.min_row is None
                        or reference.max_column is None
                        or reference.max_row is None
                        or reference.min_column != reference.max_column
                        or reference.min_row != reference.max_row
                        or reference.sheet.casefold() not in macro_sheet_names
                    ):
                        continue
                    binding_entries.append((event, candidate))

            counts: Counter[str] = Counter(event for event, _ in binding_entries)
            snapshot = XlmAutomaticMacroBindingSnapshot(
                automatic_macro_binding_count=len(binding_entries),
                auto_open_binding_count=counts["auto_open"],
                auto_close_binding_count=counts["auto_close"],
                auto_activate_binding_count=counts["auto_activate"],
                auto_deactivate_binding_count=counts["auto_deactivate"],
                binding_signature=_private_external_data_signature(
                    tuple(
                        (f"binding:{index}", repr(entry))
                        for index, entry in enumerate(sorted(binding_entries))
                    )
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _XlmAutomaticMacroBindingMetadata(
            default,
            (
                "FormulaFence could not inspect XLM automatic macro binding OOXML "
                f"({type(error).__name__}); affected bindings were not compared.",
            ),
        )
    return _XlmAutomaticMacroBindingMetadata(snapshot, tuple(sorted(warnings)))


def _ribbon_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
    missing_is_warning: bool = False,
) -> tuple[_RibbonRawRelationship, ...]:
    """Read RibbonX relationships without following any package target."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        if missing_is_warning:
            warnings.add(
                "FormulaFence could not locate "
                f"{context} relationships while inspecting RibbonX customization; "
                "affected controls may be incomplete."
            )
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for RibbonX customization ({type(error).__name__}); "
            "affected controls were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting RibbonX customization; "
            "affected controls were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_RibbonRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _RibbonRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting RibbonX "
            "customization; affected controls may be incomplete."
        )
    return tuple(relationships)


def _ribbon_relationship_signature(
    relationships: tuple[_RibbonRawRelationship, ...],
) -> str | None:
    """Fingerprint RibbonX relationship semantics without identifier churn."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _ribbon_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
) -> tuple[object, ...]:
    """Canonicalize RibbonX XML while resolving private relationship identifiers.

    A custom UI part can point to embedded images using a writer-chosen
    relationship id. Resolving an ``r:id`` or an ``image`` value only when it
    matches a known relationship keeps ID-only package rewrites out of diffs,
    without hiding a changed relationship endpoint.
    """
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        is_relationship_reference = attribute == relationship_attribute or (
            _xml_local_name(attribute) == "image" and value in relationship_semantics
        )
        if is_relationship_reference:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
        else:
            attributes.append((_xml_display_name(attribute), value))
    children = tuple(_ribbon_fragment(child, relationship_semantics) for child in element)
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _ribbon_control_counts(root: ElementTree.Element) -> tuple[int, int, int]:
    """Count RibbonX controls and callback attributes without retaining names."""
    control_count = 0
    callback_attribute_count = 0
    action_callback_count = 0
    control_id_attributes = {"id", "idMso", "idQ"}
    for element in root.iter():
        if element is not root and any(
            _xml_local_name(attribute) in control_id_attributes
            for attribute in element.attrib
        ):
            control_count += 1
        for attribute in element.attrib:
            name = _xml_local_name(attribute)
            if name.startswith(("on", "get")) or name == "loadImage":
                callback_attribute_count += 1
            if name == "onAction":
                action_callback_count += 1
    return control_count, callback_attribute_count, action_callback_count


def _ribbon_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _RibbonCustomizationBudget,
) -> _RibbonPartInspection:
    """Fingerprint one bounded RibbonX part and its image relationships privately."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded RibbonX customization part count budget; "
            "the affected controls have a coverage gap."
        )
        return _RibbonPartInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (("part-count-budget-exhausted", member),)
            ),
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a RibbonX customization package part; "
            "the affected controls were not compared."
        )
        return _RibbonPartInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (("missing-member", member),)
            ),
        )
    if info.file_size > _RIBBON_CUSTOM_UI_MAX_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized RibbonX customization part; "
            "the affected controls have a coverage gap."
        )
        return _RibbonPartInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded RibbonX customization part read budget; "
            "the affected controls have a coverage gap."
        )
        return _RibbonPartInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("read-budget-exhausted", member),
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    try:
        within_structure_budget = _ooxml_xml_structure_within_budget(
            archive,
            member,
            maximum_element_count=_RIBBON_CUSTOM_UI_MAX_XML_ELEMENT_COUNT,
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        within_structure_budget = True
    if not within_structure_budget:
        warnings.add(
            "FormulaFence did not fully read a RibbonX customization XML part whose "
            "structure exceeds the safety budget; the affected controls have a "
            "coverage gap."
        )
        return _RibbonPartInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("xml-structure-budget-exhausted", member),
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    budget.remaining_bytes -= info.file_size
    payload: bytes | None = None
    try:
        payload = archive.read(member)
        root = _xml_root_from_payload(payload)
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a RibbonX customization XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        signature = (
            _private_payload_signature(payload)
            if payload is not None
            else _private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            )
        )
        return _RibbonPartInspection(member=member, definition_signature=signature)

    namespace = _xml_namespace(root.tag)
    if (
        _xml_local_name(root.tag) != "customUI"
        or namespace not in _RIBBON_CUSTOM_UI_NAMESPACES
    ):
        warnings.add(
            "FormulaFence found a RibbonX customization part with an unexpected root; "
            "the affected controls were not compared."
        )
        return _RibbonPartInspection(
            member=member,
            definition_signature=_private_payload_signature(payload),
        )

    relationships = _ribbon_raw_relationships(
        archive,
        member,
        warnings,
        context="RibbonX customization",
    )
    relationships_by_id: dict[str, list[_RibbonRawRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found a RibbonX customization relationship without an id; "
                "the affected controls have a coverage gap."
            )
    relationship_semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        semantics = sorted(match.semantic_key() for match in matches)
        if len(semantics) > 1:
            warnings.add(
                "FormulaFence found duplicate RibbonX customization relationship ids; "
                "the affected controls have a coverage gap."
            )
        relationship_semantics[relationship_id] = semantics[0]

    referenced_relationship_ids = {
        value
        for element in root.iter()
        if (value := element.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id")) is not None
    }
    if referenced_relationship_ids - set(relationship_semantics):
        warnings.add(
            "FormulaFence found a RibbonX customization relationship reference without a "
            "matching relationship; the affected controls have a coverage gap."
        )
    control_count, callback_attribute_count, action_callback_count = _ribbon_control_counts(
        root
    )
    try:
        definition_signature = _private_external_data_signature(
            (("ribbon", repr(_ribbon_fragment(root, relationship_semantics))),)
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested RibbonX "
            "customization part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
    else:
        inspected = True
    return _RibbonPartInspection(
        member=member,
        office_2010=_RIBBON_CUSTOM_UI_NAMESPACES[namespace] == "2010",
        control_count=control_count,
        callback_attribute_count=callback_attribute_count,
        action_callback_count=action_callback_count,
        image_relationship_count=sum(
            relationship.relationship_type.rsplit("/", maxsplit=1)[-1].casefold()
            == "image"
            for relationship in relationships
        ),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_ribbon_relationship_signature(relationships),
    )


def _ribbon_customization_metadata(path: Path) -> _RibbonCustomizationMetadata:
    """Inspect Office RibbonX callbacks before the workbook reader omits the parts."""
    warnings: set[str] = set()
    default = RibbonCustomizationSnapshot()
    try:
        with ZipFile(path) as archive:
            package_relationships = _ribbon_raw_relationships(
                archive,
                "",
                warnings,
                context="package",
                missing_is_warning=True,
            )
            ribbon_relationships = tuple(
                relationship
                for relationship in package_relationships
                if relationship.relationship_type in _RIBBON_CUSTOM_UI_RELATIONSHIPS
            )
            candidate_kinds: dict[str, set[str]] = defaultdict(set)
            declaration_entries: list[tuple[str, str]] = []
            declared_targets: set[str] = set()
            unresolved_declaration_count = 0
            relationships_by_id: dict[str, list[_RibbonRawRelationship]] = defaultdict(list)
            for relationship in ribbon_relationships:
                kind = _RIBBON_CUSTOM_UI_RELATIONSHIPS[relationship.relationship_type]
                declaration_entries.append(
                    ("package-relationship", repr((kind, relationship.semantic_key())))
                )
                if relationship.relationship_id:
                    relationships_by_id[relationship.relationship_id].append(relationship)
                else:
                    warnings.add(
                        "FormulaFence found a RibbonX package relationship without an id; "
                        "the affected controls have a coverage gap."
                    )
                if relationship.safe_target is None:
                    warnings.add(
                        "FormulaFence found a RibbonX package relationship without a safe "
                        "internal customization target; the affected controls were not compared."
                    )
                    unresolved_declaration_count += 1
                    continue
                candidate_kinds[relationship.safe_target].add(kind)
                declared_targets.add(relationship.safe_target)

            if any(len(matches) > 1 for matches in relationships_by_id.values()):
                warnings.add(
                    "FormulaFence found duplicate RibbonX package relationship ids; "
                    "the affected controls have a coverage gap."
                )

            declared_version_counts: dict[str, int] = defaultdict(int)
            for relationship in ribbon_relationships:
                declared_version_counts[
                    _RIBBON_CUSTOM_UI_RELATIONSHIPS[relationship.relationship_type]
                ] += 1
            if any(count > 1 for count in declared_version_counts.values()):
                warnings.add(
                    "FormulaFence found repeated RibbonX package declarations for one "
                    "customization version; the affected controls have a coverage gap."
                )

            discovered_members = {
                entry.filename
                for entry in archive.infolist()
                if _RIBBON_CUSTOM_UI_PART_PATTERN.fullmatch(entry.filename)
            }
            for member in discovered_members:
                candidate_kinds.setdefault(member, set())
                if member not in declared_targets:
                    warnings.add(
                        "FormulaFence found a RibbonX customization package part not declared "
                        "by the package; the affected controls have a coverage gap."
                    )

            inspections: list[_RibbonPartInspection] = []
            unrecognized_members: set[str] = set()
            customization_budget = _RibbonCustomizationBudget()
            for member in sorted(candidate_kinds, key=str.casefold):
                kinds = candidate_kinds[member]
                declaration_entries.append(
                    ("package-part", repr((member, tuple(sorted(kinds)))))
                )
                if len(kinds) != 1:
                    warnings.add(
                        "FormulaFence could not identify one RibbonX customization part's "
                        "declared version; the affected controls have a coverage gap."
                    )
                    unrecognized_members.add(member)
                inspection = _ribbon_part_inspection(
                    archive,
                    member,
                    warnings,
                    customization_budget,
                )
                inspections.append(inspection)
                if not inspection.inspected:
                    unrecognized_members.add(member)
                    continue
                declared_kind = next(iter(kinds), None)
                inspected_kind = "2010" if inspection.office_2010 else "2007"
                if declared_kind is not None and declared_kind != inspected_kind:
                    warnings.add(
                        "FormulaFence found a RibbonX customization declaration whose version "
                        "does not match its XML root; the affected controls have a coverage gap."
                    )
                    unrecognized_members.add(member)

            def aggregate_signature(attribute: str) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            declaration_entries.sort()
            snapshot = RibbonCustomizationSnapshot(
                declared_ribbon_part_count=len(ribbon_relationships),
                ribbon_part_count=len(candidate_kinds),
                office_2010_ribbon_part_count=sum(
                    inspection.office_2010 for inspection in inspections
                ),
                unrecognized_ribbon_part_count=(
                    len(unrecognized_members) + unresolved_declaration_count
                ),
                control_count=sum(inspection.control_count for inspection in inspections),
                callback_attribute_count=sum(
                    inspection.callback_attribute_count for inspection in inspections
                ),
                action_callback_count=sum(
                    inspection.action_callback_count for inspection in inspections
                ),
                image_relationship_count=sum(
                    inspection.image_relationship_count for inspection in inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in inspections
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                definition_signature=aggregate_signature("definition_signature"),
                relationship_signature=aggregate_signature("relationship_signature"),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _RibbonCustomizationMetadata(
            default,
            (
                "FormulaFence could not inspect RibbonX customization OOXML "
                f"({type(error).__name__}); affected controls were not compared.",
            ),
        )
    return _RibbonCustomizationMetadata(snapshot, tuple(sorted(warnings)))


def _office_web_addin_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
    missing_is_warning: bool = False,
) -> tuple[_OfficeWebAddinRawRelationship, ...]:
    """Read task-pane relationships without opening any package target."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        if missing_is_warning:
            warnings.add(
                "FormulaFence could not locate "
                f"{context} relationships while inspecting Office Web Add-ins; "
                "affected controls may be incomplete."
            )
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for Office Web Add-ins ({type(error).__name__}); "
            "affected controls were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting Office Web Add-ins; "
            "affected controls were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_OfficeWebAddinRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _OfficeWebAddinRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting Office Web "
            "Add-ins; affected controls may be incomplete."
        )
    return tuple(relationships)


def _office_web_addin_relationship_signature(
    relationships: tuple[_OfficeWebAddinRawRelationship, ...],
) -> str | None:
    """Fingerprint relationship semantics without writer-chosen identifiers."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _office_web_addin_relationship_semantics(
    relationships: tuple[_OfficeWebAddinRawRelationship, ...],
    warnings: set[str],
    *,
    context: str,
) -> dict[str, tuple[str, str, str]]:
    """Map relationship IDs to stable private semantics for XML canonicalization."""
    relationships_by_id: dict[str, list[_OfficeWebAddinRawRelationship]] = defaultdict(
        list
    )
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found an Office Web Add-in "
                f"{context} relationship without an id; affected controls have a coverage gap."
            )

    semantics_by_id: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        semantics = sorted(match.semantic_key() for match in matches)
        if len(matches) > 1:
            warnings.add(
                "FormulaFence found duplicate Office Web Add-in "
                f"{context} relationship ids; affected controls have a coverage gap."
            )
        semantics_by_id[relationship_id] = semantics[0]
    return semantics_by_id


def _office_web_addin_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
) -> tuple[object, ...]:
    """Canonicalize Web Add-in XML while resolving relationship-ID churn privately."""
    relationship_attributes = {
        f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id",
        f"{{{_DOCUMENT_RELATIONSHIP_NS}}}embed",
        f"{{{_DOCUMENT_RELATIONSHIP_NS}}}link",
    }
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute in relationship_attributes:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
        else:
            attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _office_web_addin_fragment(child, relationship_semantics) for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _office_web_addin_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _OfficeWebAddinBudget,
) -> str | None:
    """Stream a Web Add-in part before its recursive private fragment is built."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _WEB_EXTENSION_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read an Office Web Add-in package part whose XML "
        "structure exceeds the safety budget; the affected controls have a coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _office_web_addin_boolean(
    value: str | None,
    default: bool,
    warnings: set[str],
    *,
    context: str,
    attribute: str,
) -> bool:
    """Parse an OOXML boolean while preserving malformed material privately."""
    if value is None:
        return default
    normalized = value.strip().casefold()
    if normalized in {"1", "true"}:
        return True
    if normalized in {"0", "false"}:
        return False
    warnings.add(
        "FormulaFence found an unrecognized Office Web Add-in "
        f"{context} {attribute} value; affected controls have a coverage gap."
    )
    return default


def _office_web_addin_taskpane_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _OfficeWebAddinBudget,
) -> _OfficeWebAddinTaskpaneInspection:
    """Fingerprint one bounded task-pane part and its extension bindings privately."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded Office Web Add-in part count budget; "
            "the affected controls have a coverage gap."
        )
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (("part-count-budget-exhausted", member),)
            ),
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate an Office Web Add-in task-pane package part; "
            "the affected controls were not compared."
        )
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (("missing-member", member),)
            ),
        )
    if info.file_size > _WEB_EXTENSION_MAX_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized Office Web Add-in package part; "
            "the affected controls have a coverage gap."
        )
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded Office Web Add-in part read budget; "
            "the affected controls have a coverage gap."
        )
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("read-budget-exhausted", member),
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    structure_fallback_signature = _office_web_addin_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        warnings,
        budget,
    )
    if structure_fallback_signature is not None:
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=structure_fallback_signature,
        )
    budget.remaining_bytes -= info.file_size
    payload: bytes | None = None
    try:
        payload = archive.read(member)
        root = _xml_root_from_payload(payload)
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect an Office Web Add-in task-pane XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        signature = (
            _private_payload_signature(payload)
            if payload is not None
            else _private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            )
        )
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=signature,
        )

    if (
        _xml_local_name(root.tag) != "taskpanes"
        or _xml_namespace(root.tag) != _WEB_EXTENSION_TASKPANES_NS
    ):
        warnings.add(
            "FormulaFence found an Office Web Add-in task-pane part with an unexpected "
            "root; the affected controls were not compared."
        )
        return _OfficeWebAddinTaskpaneInspection(
            member=member,
            definition_signature=_private_payload_signature(payload),
        )

    relationships = _office_web_addin_raw_relationships(
        archive,
        member,
        warnings,
        context="task-pane",
    )
    relationship_semantics = _office_web_addin_relationship_semantics(
        relationships,
        warnings,
        context="task-pane",
    )
    taskpane_tag = f"{{{_WEB_EXTENSION_TASKPANES_NS}}}taskpane"
    web_extension_ref_tags = {
        f"{{{_WEB_EXTENSION_TASKPANES_NS}}}webextensionref",
        f"{{{_WEB_EXTENSION_TASKPANES_NS}}}webextension",
    }
    relationship_id_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    taskpanes = root.findall(taskpane_tag)
    if len(taskpanes) != len(root):
        warnings.add(
            "FormulaFence found unmodelled XML in an Office Web Add-in task-pane part; "
            "affected controls may be incomplete."
        )

    declared_web_extension_members: set[str] = set()
    referenced_relationship_ids: set[str] = set()
    unresolved_binding_count = 0
    visible_taskpane_count = 0
    locked_taskpane_count = 0
    web_extension_reference_count = 0
    for taskpane in taskpanes:
        visible_taskpane_count += _office_web_addin_boolean(
            taskpane.get("visibility"),
            False,
            warnings,
            context="task-pane",
            attribute="visibility",
        )
        locked_taskpane_count += _office_web_addin_boolean(
            taskpane.get("locked"),
            False,
            warnings,
            context="task-pane",
            attribute="locked",
        )
        references = [
            child for child in taskpane if child.tag in web_extension_ref_tags
        ]
        web_extension_reference_count += len(references)
        if not references:
            warnings.add(
                "FormulaFence found an Office Web Add-in task-pane without a web-extension "
                "reference; affected controls have a coverage gap."
            )
            unresolved_binding_count += 1
        for reference in references:
            relationship_id = reference.get(relationship_id_attribute)
            if not relationship_id:
                warnings.add(
                    "FormulaFence found an Office Web Add-in task-pane reference without a "
                    "relationship id; affected controls have a coverage gap."
                )
                unresolved_binding_count += 1
                continue
            referenced_relationship_ids.add(relationship_id)
            semantic = relationship_semantics.get(relationship_id)
            if semantic is None:
                warnings.add(
                    "FormulaFence found an Office Web Add-in task-pane reference without a "
                    "matching relationship; affected controls have a coverage gap."
                )
                unresolved_binding_count += 1
                continue
            if semantic[0] != _WEB_EXTENSION_RELATIONSHIP:
                warnings.add(
                    "FormulaFence found an Office Web Add-in task-pane reference with an "
                    "unexpected relationship type; affected controls have a coverage gap."
                )
                unresolved_binding_count += 1
                continue
            relationship = next(
                (
                    candidate
                    for candidate in relationships
                    if candidate.relationship_id == relationship_id
                    and candidate.semantic_key() == semantic
                ),
                None,
            )
            if relationship is None or relationship.safe_target is None:
                warnings.add(
                    "FormulaFence found an Office Web Add-in task-pane reference without a "
                    "safe internal extension target; affected controls were not compared."
                )
                unresolved_binding_count += 1
                continue
            declared_web_extension_members.add(relationship.safe_target)

    for relationship in relationships:
        if relationship.relationship_type != _WEB_EXTENSION_RELATIONSHIP:
            continue
        if relationship.safe_target is None:
            warnings.add(
                "FormulaFence found an Office Web Add-in extension relationship without a "
                "safe internal target; affected controls were not compared."
            )
            unresolved_binding_count += 1
            continue
        declared_web_extension_members.add(relationship.safe_target)
        if (
            relationship.relationship_id is None
            or relationship.relationship_id not in referenced_relationship_ids
        ):
            warnings.add(
                "FormulaFence found an Office Web Add-in extension relationship not bound "
                "by a task pane; affected controls have a coverage gap."
            )
            unresolved_binding_count += 1

    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    "taskpanes",
                    repr(_office_web_addin_fragment(root, relationship_semantics)),
                ),
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested Office Web Add-in "
            "task-pane part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
    else:
        inspected = True
    return _OfficeWebAddinTaskpaneInspection(
        member=member,
        taskpane_count=len(taskpanes),
        visible_taskpane_count=visible_taskpane_count,
        locked_taskpane_count=locked_taskpane_count,
        web_extension_reference_count=web_extension_reference_count,
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        declared_web_extension_members=tuple(
            sorted(declared_web_extension_members, key=str.casefold)
        ),
        unresolved_binding_count=unresolved_binding_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_office_web_addin_relationship_signature(relationships),
    )


def _office_web_addin_extension_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _OfficeWebAddinBudget,
) -> _OfficeWebAddinExtensionInspection:
    """Fingerprint one bounded Office Web Add-in definition part privately."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded Office Web Add-in part count budget; "
            "the affected controls have a coverage gap."
        )
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (("part-count-budget-exhausted", member),)
            ),
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate an Office Web Add-in definition package part; "
            "the affected controls were not compared."
        )
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (("missing-member", member),)
            ),
        )
    if info.file_size > _WEB_EXTENSION_MAX_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized Office Web Add-in package part; "
            "the affected controls have a coverage gap."
        )
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded Office Web Add-in part read budget; "
            "the affected controls have a coverage gap."
        )
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=_private_external_data_signature(
                (
                    ("read-budget-exhausted", member),
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            ),
        )
    structure_fallback_signature = _office_web_addin_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        warnings,
        budget,
    )
    if structure_fallback_signature is not None:
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=structure_fallback_signature,
        )
    budget.remaining_bytes -= info.file_size
    payload: bytes | None = None
    try:
        payload = archive.read(member)
        root = _xml_root_from_payload(payload)
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect an Office Web Add-in definition XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        signature = (
            _private_payload_signature(payload)
            if payload is not None
            else _private_external_data_signature(
                (
                    ("size", str(info.file_size)),
                    ("compressed-size", str(info.compress_size)),
                    ("crc", str(info.CRC)),
                )
            )
        )
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=signature,
        )

    if (
        _xml_local_name(root.tag) != "webextension"
        or _xml_namespace(root.tag) != _WEB_EXTENSION_NS
    ):
        warnings.add(
            "FormulaFence found an Office Web Add-in definition part with an unexpected "
            "root; the affected controls were not compared."
        )
        return _OfficeWebAddinExtensionInspection(
            member=member,
            definition_signature=_private_payload_signature(payload),
        )

    relationships = _office_web_addin_raw_relationships(
        archive,
        member,
        warnings,
        context="definition",
    )
    relationship_semantics = _office_web_addin_relationship_semantics(
        relationships,
        warnings,
        context="definition",
    )
    property_tag = f"{{{_WEB_EXTENSION_NS}}}property"
    reference_tag = f"{{{_WEB_EXTENSION_NS}}}reference"
    alternate_references_tag = f"{{{_WEB_EXTENSION_NS}}}alternateReferences"
    alternate_reference_tags = {
        reference_tag,
        f"{{{_WEB_EXTENSION_NS}}}alternateReference",
    }
    binding_tag = f"{{{_WEB_EXTENSION_NS}}}binding"
    snapshot_tag = f"{{{_WEB_EXTENSION_NS}}}snapshot"
    embedded_relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}embed"

    auto_show_taskpane_count = 0
    for property_element in root.iter(property_tag):
        if property_element.get("name") != "Office.AutoShowTaskpaneWithDocument":
            continue
        auto_show_taskpane_count += _office_web_addin_boolean(
            property_element.get("value"),
            False,
            warnings,
            context="definition property",
            attribute="value",
        )
    snapshot_reference_count = 0
    unresolved_snapshot_reference_count = 0
    for snapshot in root.iter(snapshot_tag):
        relationship_id = snapshot.get(embedded_relationship_attribute)
        if relationship_id is None:
            continue
        snapshot_reference_count += 1
        if relationship_id not in relationship_semantics:
            warnings.add(
                "FormulaFence found an Office Web Add-in snapshot reference without a "
                "matching relationship; affected controls have a coverage gap."
            )
            unresolved_snapshot_reference_count += 1

    binding_apprefs: list[str] = []
    unresolved_binding_count = 0
    for binding in root.iter(binding_tag):
        appref = binding.get("appref")
        if appref is None or not appref.strip():
            warnings.add(
                "FormulaFence found an Office Web Add-in definition binding without an "
                "appref; affected worksheet bindings have a coverage gap."
            )
            unresolved_binding_count += 1
            continue
        binding_apprefs.append(appref)

    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    "webextension",
                    repr(_office_web_addin_fragment(root, relationship_semantics)),
                ),
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested Office Web Add-in "
            "definition part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
    else:
        inspected = True
    return _OfficeWebAddinExtensionInspection(
        member=member,
        auto_show_taskpane_count=auto_show_taskpane_count,
        store_reference_count=len(root.findall(reference_tag)),
        alternate_reference_count=sum(
            1
            for container in root.iter(alternate_references_tag)
            for child in container
            if child.tag in alternate_reference_tags
        ),
        binding_count=len(binding_apprefs) + unresolved_binding_count,
        snapshot_reference_count=snapshot_reference_count,
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        unresolved_snapshot_reference_count=unresolved_snapshot_reference_count,
        binding_apprefs=tuple(sorted(binding_apprefs)),
        unresolved_binding_count=unresolved_binding_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_office_web_addin_relationship_signature(relationships),
    )


def _office_web_addin_bounded_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetWebExtensionBudget | _InContentWebExtensionBudget,
    *,
    maximum_part_bytes: int,
    context: str,
) -> tuple[bytes | None, str | None]:
    """Read a related Office Web Add-in XML part under fixed scan budgets."""
    if budget.remaining_parts <= 0:
        warnings.add(
            "FormulaFence reached its bounded Office Web Add-in XML part count budget; "
            f"affected {context} controls have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("office-web-addin-part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate an Office Web Add-in "
            f"{context} XML part; affected controls were not compared."
        )
        return None, _private_external_data_signature(
            (("missing-office-web-addin-member", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > maximum_part_bytes:
        warnings.add(
            "FormulaFence did not fully read an oversized Office Web Add-in "
            f"{context} XML part; affected controls have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("oversized-office-web-addin-member", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded Office Web Add-in XML read budget; "
            f"affected {context} controls have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("office-web-addin-read-budget-exhausted", metadata),)
        )
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read an Office Web Add-in "
            f"{context} XML part ({type(error).__name__}); affected controls were not "
            "compared."
        )
        return None, _private_external_data_signature(
            (("unreadable-office-web-addin-member", metadata),)
        )


def _worksheet_web_extension_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetWebExtensionBudget,
) -> _WorksheetWebExtensionInspection:
    """Inspect one worksheet's x15 Office Web Add-in bindings privately."""
    payload, fallback_signature = _office_web_addin_bounded_xml_payload(
        archive,
        member,
        warnings,
        budget,
        maximum_part_bytes=_WORKSHEET_WEB_EXTENSION_MAX_XML_BYTES,
        context="worksheet binding",
    )
    if payload is None:
        return _WorksheetWebExtensionInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        worksheet = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect worksheet XML for Office Web Add-in "
            f"bindings ({type(error).__name__}); affected controls were not compared."
        )
        return _WorksheetWebExtensionInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    worksheet_namespace = _xml_namespace(worksheet.tag)
    if (
        worksheet_namespace not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
        or _xml_local_name(worksheet.tag) != "worksheet"
    ):
        warnings.add(
            "FormulaFence found a worksheet part with an unexpected root while "
            "inspecting Office Web Add-in bindings; affected controls were not compared."
        )
        return _WorksheetWebExtensionInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    extension_list_tag = f"{{{worksheet_namespace}}}extLst"
    extension_tag = f"{{{worksheet_namespace}}}ext"
    container_tag = f"{{{_OFFICE_2013_SPREADSHEET_NS}}}webExtensions"
    binding_tag = f"{{{_OFFICE_2013_SPREADSHEET_NS}}}webExtension"
    formula_tag = f"{{{_EXCEL_2006_MAIN_NS}}}f"
    issues: list[tuple[str, str]] = []
    accepted_containers: list[ElementTree.Element] = []
    accepted_container_ids: set[int] = set()
    extension_lists = [child for child in worksheet if child.tag == extension_list_tag]
    if len(extension_lists) > 1:
        issues.append(("multiple-worksheet-extension-lists", str(len(extension_lists))))
    for extension_list_index, extension_list in enumerate(extension_lists):
        if extension_list.attrib or (
            extension_list.text is not None and extension_list.text.strip()
        ):
            issues.append(
                (
                    "malformed-worksheet-extension-list",
                    repr((member, extension_list_index)),
                )
            )
        for extension_index, extension in enumerate(extension_list):
            if (
                extension.tag != extension_tag
                or extension.get("uri", "").casefold()
                != _WORKSHEET_WEB_EXTENSION_EXTENSION_URI.casefold()
            ):
                continue
            context = (member, extension_list_index, extension_index)
            if set(extension.attrib) != {"uri"} or (
                extension.text is not None and extension.text.strip()
            ):
                issues.append(("malformed-worksheet-web-extension", repr(context)))
            containers = [child for child in extension if child.tag == container_tag]
            if len(containers) != 1:
                issues.append(
                    (
                        "invalid-worksheet-web-extension-container-count",
                        repr((context, len(containers))),
                    )
                )
            for child_index, child in enumerate(extension):
                if child.tag != container_tag:
                    issues.append(
                        (
                            "unexpected-worksheet-web-extension-child",
                            repr((context, child_index, _xml_display_name(child.tag))),
                        )
                    )
            accepted_containers.extend(containers)
            accepted_container_ids.update(id(container) for container in containers)

    for container in worksheet.iter(container_tag):
        if id(container) not in accepted_container_ids:
            issues.append(
                (
                    "out-of-container-worksheet-web-extensions",
                    _private_payload_signature(
                        ElementTree.tostring(container, encoding="utf-8")
                    ),
                )
            )

    if not accepted_containers and not issues:
        return _WorksheetWebExtensionInspection(member=member)

    binding_count = 0
    apprefs: list[str] = []
    definition_entries: list[tuple[str, str]] = []
    for container_index, container in enumerate(accepted_containers):
        container_context = (member, container_index)
        if container.attrib or (
            container.text is not None and container.text.strip()
        ):
            issues.append(
                (
                    "malformed-worksheet-web-extensions-container",
                    repr(container_context),
                )
            )
        bindings: list[ElementTree.Element] = []
        for child_index, child in enumerate(container):
            if child.tag != binding_tag:
                issues.append(
                    (
                        "unexpected-worksheet-web-extensions-binding-child",
                        repr((container_context, child_index, _xml_display_name(child.tag))),
                    )
                )
                continue
            bindings.append(child)
        if not bindings:
            issues.append(("empty-worksheet-web-extensions", repr(container_context)))
        for binding_index, binding in enumerate(bindings):
            binding_count += 1
            binding_context = (*container_context, binding_index)
            appref = binding.get("appRef")
            if appref is None or not appref.strip():
                issues.append(("missing-worksheet-web-extension-appref", repr(binding_context)))
            else:
                apprefs.append(appref)
            if set(binding.attrib) != {"appRef"}:
                issues.append(
                    (
                        "malformed-worksheet-web-extension-binding-attributes",
                        repr(binding_context),
                    )
                )
            formulas = [child for child in binding if child.tag == formula_tag]
            if len(formulas) != 1:
                issues.append(
                    (
                        "invalid-worksheet-web-extension-formula-count",
                        repr((binding_context, len(formulas))),
                    )
                )
            for child_index, child in enumerate(binding):
                if child.tag != formula_tag:
                    issues.append(
                        (
                            "unexpected-worksheet-web-extension-binding-child",
                            repr((binding_context, child_index, _xml_display_name(child.tag))),
                        )
                    )
            for formula in formulas:
                if formula.attrib or list(formula) or not (formula.text or "").strip():
                    issues.append(
                        (
                            "malformed-worksheet-web-extension-formula",
                            repr(binding_context),
                        )
                    )
        try:
            fragment = _office_web_addin_fragment(container, {})
        except RecursionError:
            issues.append(
                (
                    "nested-worksheet-web-extensions-container",
                    repr(container_context),
                )
            )
            fragment = _private_payload_signature(
                ElementTree.tostring(container, encoding="utf-8")
            )
        definition_entries.append(
            ("worksheet-web-extensions", repr((member, fragment)))
        )

    definition_entries.extend(issues)
    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported worksheet Office Web Add-in "
            "metadata; affected controls have a coverage gap."
        )
    return _WorksheetWebExtensionInspection(
        member=member,
        binding_count=binding_count,
        binding_apprefs=tuple(sorted(apprefs)),
        unrecognized_count=len(issues),
        definition_signature=_private_external_data_signature(
            tuple(sorted(definition_entries))
        ),
    )


def _office_web_addin_in_content_graphic_data(
    frame: ElementTree.Element,
) -> ElementTree.Element | None:
    """Return one Office Web Add-in graphicData container, if structurally clear."""
    if (
        _xml_namespace(frame.tag)
        not in {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
        or _xml_local_name(frame.tag) != "graphicFrame"
    ):
        return None
    graphics = [
        child
        for child in frame
        if (
            _xml_namespace(child.tag) in {_DRAWINGML_MAIN_NS, _DRAWINGML_STRICT_MAIN_NS}
            and _xml_local_name(child.tag) == "graphic"
        )
    ]
    if len(graphics) != 1:
        return None
    graphic_data = [
        child
        for child in graphics[0]
        if (
            _xml_namespace(child.tag) in {_DRAWINGML_MAIN_NS, _DRAWINGML_STRICT_MAIN_NS}
            and _xml_local_name(child.tag) == "graphicData"
        )
    ]
    if len(graphic_data) != 1 or graphic_data[0].get("uri") != _WEB_EXTENSION_NS:
        return None
    return graphic_data[0]


def _office_web_addin_in_content_frames(
    root: ElementTree.Element,
) -> tuple[tuple[ElementTree.Element | None, ElementTree.Element], ...]:
    """Return active DrawingML frames that host Office Web Add-ins.

    Fallback branches are deliberately skipped: they are image-only previews for
    clients that cannot load the active Office Web Add-in branch and are handled
    by the native worksheet-image scanner.
    """
    frames: list[tuple[ElementTree.Element | None, ElementTree.Element]] = []
    anchor_names = {"twoCellAnchor", "oneCellAnchor", "absoluteAnchor"}

    def visit(
        element: ElementTree.Element,
        anchor: ElementTree.Element | None,
    ) -> None:
        if (
            _xml_namespace(element.tag)
            in {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
            and _xml_local_name(element.tag) in anchor_names
        ):
            anchor = element
        if (
            _xml_namespace(element.tag) == _MARKUP_COMPATIBILITY_NS
            and _xml_local_name(element.tag) == "AlternateContent"
        ):
            for child in element:
                if (
                    _xml_namespace(child.tag) == _MARKUP_COMPATIBILITY_NS
                    and _xml_local_name(child.tag) == "Fallback"
                ):
                    continue
                visit(child, anchor)
            return
        if _office_web_addin_in_content_graphic_data(element) is not None:
            frames.append((anchor, element))
            return
        for child in element:
            visit(child, anchor)

    visit(root, None)
    return tuple(frames)


def _office_web_addin_in_content_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
) -> tuple[object, ...]:
    """Canonicalize private in-content frame XML without object-ID churn."""
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if (
            _xml_namespace(element.tag)
            in {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
            and _xml_local_name(element.tag) == "cNvPr"
            and _xml_local_name(attribute) == "id"
        ):
            continue
        if attribute in {
            f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id",
            f"{{{_STRICT_DOCUMENT_RELATIONSHIP_NS}}}id",
        }:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _office_web_addin_in_content_fragment(child, relationship_semantics)
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _office_web_addin_in_content_anchor_material(
    anchor: ElementTree.Element | None,
) -> tuple[object, ...]:
    """Retain a frame's private placement without serialising fallback previews."""
    if anchor is None:
        return ("unanchored",)
    return (
        _xml_display_name(anchor.tag),
        tuple(
            sorted(
                (_xml_display_name(attribute), value)
                for attribute, value in anchor.attrib.items()
            )
        ),
        tuple(
            _office_web_addin_in_content_fragment(child, {})
            for child in anchor
            if (
                _xml_namespace(child.tag)
                in {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
                and _xml_local_name(child.tag) in {"from", "to", "pos", "ext"}
            )
        ),
    )


def _office_web_addin_in_content_drawing_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _InContentWebExtensionBudget,
) -> _InContentWebExtensionDrawingInspection:
    """Follow bounded DrawingML Office Web Add-in frame relationships."""
    payload, fallback_signature = _office_web_addin_bounded_xml_payload(
        archive,
        member,
        warnings,
        budget,
        maximum_part_bytes=_IN_CONTENT_WEB_EXTENSION_MAX_XML_BYTES,
        context="in-content DrawingML",
    )
    if payload is None:
        return _InContentWebExtensionDrawingInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect Office Web Add-in in-content DrawingML "
            f"({type(error).__name__}); affected controls were not compared."
        )
        return _InContentWebExtensionDrawingInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(root.tag)
        not in {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
        or _xml_local_name(root.tag) != "wsDr"
    ):
        warnings.add(
            "FormulaFence found an Office Web Add-in in-content DrawingML part with an "
            "unexpected root; affected controls were not compared."
        )
        return _InContentWebExtensionDrawingInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    frames = _office_web_addin_in_content_frames(root)
    if not frames:
        return _InContentWebExtensionDrawingInspection(member=member)
    relationships = _office_web_addin_raw_relationships(
        archive,
        member,
        warnings,
        context="in-content DrawingML",
    )
    relationship_semantics = _office_web_addin_relationship_semantics(
        relationships,
        warnings,
        context="in-content DrawingML",
    )
    relationships_by_id: dict[str, list[_OfficeWebAddinRawRelationship]] = defaultdict(
        list
    )
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)

    declared_members: set[str] = set()
    selected_relationships: list[_OfficeWebAddinRawRelationship] = []
    issues: list[tuple[str, str]] = []
    unresolved_binding_count = 0
    definition_entries: list[tuple[str, str]] = []
    reference_count = 0
    for frame_index, (anchor, frame) in enumerate(frames):
        graphic_data = _office_web_addin_in_content_graphic_data(frame)
        assert graphic_data is not None
        context = (member, frame_index)
        if set(graphic_data.attrib) != {"uri"} or (
            graphic_data.text is not None and graphic_data.text.strip()
        ):
            issues.append(("malformed-in-content-web-extension-graphic-data", repr(context)))
        references = [
            element
            for element in graphic_data
            if (
                _xml_namespace(element.tag) == _WEB_EXTENSION_NS
                and _xml_local_name(element.tag) == "webextensionref"
            )
        ]
        for child_index, child in enumerate(graphic_data):
            if child in references:
                continue
            issues.append(
                (
                    "unexpected-in-content-web-extension-graphic-data-child",
                    repr((context, child_index, _xml_display_name(child.tag))),
                )
            )
        if len(references) != 1:
            issues.append(("invalid-in-content-web-extension-reference-count", repr(context)))
        for reference_index, reference in enumerate(references):
            reference_count += 1
            reference_context = (*context, reference_index)
            permitted_relationship_attributes = {
                f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id",
                f"{{{_STRICT_DOCUMENT_RELATIONSHIP_NS}}}id",
            }
            if (
                len(reference.attrib) != 1
                or next(iter(reference.attrib), None)
                not in permitted_relationship_attributes
                or list(reference)
                or (reference.text is not None and reference.text.strip())
            ):
                issues.append(
                    (
                        "malformed-in-content-web-extension-reference",
                        repr(reference_context),
                    )
                )
                unresolved_binding_count += 1
            relationship_ids = [
                value
                for attribute, value in reference.attrib.items()
                if (
                    attribute in permitted_relationship_attributes
                    and value
                )
            ]
            if len(relationship_ids) != 1:
                issues.append(
                    (
                        "invalid-in-content-web-extension-relationship-id",
                        repr(reference_context),
                    )
                )
                unresolved_binding_count += 1
                continue
            relationship_id = relationship_ids[0]
            matches = relationships_by_id.get(relationship_id, [])
            if len(matches) != 1:
                issues.append(
                    (
                        "invalid-in-content-web-extension-relationship-binding",
                        repr(reference_context),
                    )
                )
                unresolved_binding_count += 1
                continue
            relationship = matches[0]
            selected_relationships.append(relationship)
            if (
                relationship.relationship_type != _WEB_EXTENSION_RELATIONSHIP
                or relationship.target_mode.casefold() != "internal"
                or relationship.safe_target is None
            ):
                issues.append(
                    (
                        "unsafe-in-content-web-extension-target",
                        repr((reference_context, relationship.semantic_key())),
                    )
                )
                unresolved_binding_count += 1
                continue
            declared_members.add(relationship.safe_target)
        try:
            frame_fragment = _office_web_addin_in_content_fragment(
                frame,
                relationship_semantics,
            )
        except RecursionError:
            issues.append(("nested-in-content-web-extension-frame", repr(context)))
            frame_fragment = _private_payload_signature(
                ElementTree.tostring(frame, encoding="utf-8")
            )
        definition_entries.append(
            (
                "in-content-web-extension-frame",
                repr(
                    (
                        member,
                        _office_web_addin_in_content_anchor_material(anchor),
                        frame_fragment,
                    )
                ),
            )
        )

    definition_entries.extend(issues)
    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported Office Web Add-in "
            "in-content DrawingML metadata; affected controls have a coverage gap."
        )
    return _InContentWebExtensionDrawingInspection(
        member=member,
        reference_count=reference_count,
        declared_web_extension_members=tuple(sorted(declared_members, key=str.casefold)),
        unresolved_binding_count=unresolved_binding_count,
        unrecognized_count=len(issues),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        definition_signature=_private_external_data_signature(
            tuple(sorted(definition_entries))
        ),
        relationship_signature=_office_web_addin_relationship_signature(
            tuple(selected_relationships)
        ),
    )


def _office_web_addin_metadata(path: Path) -> _OfficeWebAddinMetadata:
    """Inspect task-pane Office Web Add-ins before the workbook reader omits them."""
    warnings: set[str] = set()
    default = OfficeWebAddinSnapshot()
    try:
        with ZipFile(path) as archive:
            budget = _OfficeWebAddinBudget()
            workbook_relationships = _office_web_addin_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
                missing_is_warning=True,
            )
            taskpane_relationships = tuple(
                relationship
                for relationship in workbook_relationships
                if relationship.relationship_type == _WEB_EXTENSION_TASKPANES_RELATIONSHIP
            )
            candidate_taskpane_members: dict[str, set[str]] = defaultdict(set)
            declaration_entries: list[tuple[str, str]] = []
            declared_taskpane_members: set[str] = set()
            unresolved_declaration_count = 0
            relationship_ids: set[str] = set()
            for relationship in taskpane_relationships:
                declaration_entries.append(
                    ("workbook-relationship", repr(relationship.semantic_key()))
                )
                if relationship.relationship_id is None:
                    warnings.add(
                        "FormulaFence found an Office Web Add-in workbook relationship without "
                        "an id; affected controls have a coverage gap."
                    )
                elif relationship.relationship_id in relationship_ids:
                    warnings.add(
                        "FormulaFence found duplicate Office Web Add-in workbook relationship "
                        "ids; affected controls have a coverage gap."
                    )
                relationship_ids.add(relationship.relationship_id or "")
                if relationship.safe_target is None:
                    warnings.add(
                        "FormulaFence found an Office Web Add-in workbook relationship without "
                        "a safe internal task-pane target; affected controls were not compared."
                    )
                    unresolved_declaration_count += 1
                    continue
                candidate_taskpane_members[relationship.safe_target].add("workbook")
                declared_taskpane_members.add(relationship.safe_target)

            discovered_taskpane_members = {
                entry.filename
                for entry in archive.infolist()
                if _WEB_EXTENSION_TASKPANES_PART_PATTERN.fullmatch(entry.filename)
            }
            for member in discovered_taskpane_members:
                candidate_taskpane_members.setdefault(member, set())
                if member not in declared_taskpane_members:
                    warnings.add(
                        "FormulaFence found an Office Web Add-in task-pane package part not "
                        "declared by the workbook; affected controls have a coverage gap."
                    )

            taskpane_inspections: list[_OfficeWebAddinTaskpaneInspection] = []
            unrecognized_members: set[str] = set()
            unresolved_binding_count = unresolved_declaration_count
            candidate_web_extension_members: dict[str, set[str]] = defaultdict(set)
            for member in sorted(candidate_taskpane_members, key=str.casefold):
                sources = candidate_taskpane_members[member]
                declaration_entries.append(
                    ("taskpane-part", repr((member, tuple(sorted(sources)))))
                )
                if not sources:
                    unrecognized_members.add(member)
                inspection = _office_web_addin_taskpane_inspection(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                taskpane_inspections.append(inspection)
                if not inspection.inspected:
                    unrecognized_members.add(member)
                    continue
                unresolved_binding_count += inspection.unresolved_binding_count
                for web_extension_member in inspection.declared_web_extension_members:
                    candidate_web_extension_members[web_extension_member].add(
                        f"taskpane:{member}"
                    )

            try:
                worksheet_members = _worksheet_display_xml_paths(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                warnings.add(
                    "FormulaFence could not inspect worksheet OOXML declarations for "
                    f"Office Web Add-ins ({type(error).__name__}); affected controls were "
                    "not compared."
                )
                worksheet_members = ()
                unresolved_binding_count += 1

            drawing_sources: dict[str, set[str]] = defaultdict(set)
            drawing_relationship_types = {
                _WORKSHEET_DRAWING_RELATIONSHIP.casefold(),
                _WORKSHEET_STRICT_DRAWING_RELATIONSHIP.casefold(),
            }
            for worksheet_member in worksheet_members:
                relationships = _office_web_addin_raw_relationships(
                    archive,
                    worksheet_member,
                    warnings,
                    context="worksheet",
                )
                for relationship in relationships:
                    if (
                        relationship.relationship_type.casefold()
                        not in drawing_relationship_types
                        or relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        continue
                    drawing_sources[relationship.safe_target].add(worksheet_member)

            in_content_inspections: list[_InContentWebExtensionDrawingInspection] = []
            in_content_declaration_entries: list[tuple[str, str]] = []
            in_content_budget = _InContentWebExtensionBudget()
            for drawing_member in sorted(drawing_sources, key=str.casefold):
                sources = tuple(sorted(drawing_sources[drawing_member], key=str.casefold))
                inspection = _office_web_addin_in_content_drawing_inspection(
                    archive,
                    drawing_member,
                    warnings,
                    in_content_budget,
                )
                in_content_inspections.append(inspection)
                if inspection.present:
                    in_content_declaration_entries.append(
                        (
                            "in-content-drawing-part",
                            repr((drawing_member, sources)),
                        )
                    )
                unresolved_binding_count += max(
                    inspection.unresolved_binding_count,
                    inspection.unrecognized_count,
                )
                for web_extension_member in inspection.declared_web_extension_members:
                    candidate_web_extension_members[web_extension_member].add(
                        f"drawing:{drawing_member}"
                    )

            discovered_web_extension_members = {
                entry.filename
                for entry in archive.infolist()
                if _WEB_EXTENSION_PART_PATTERN.fullmatch(entry.filename)
            }
            for member in discovered_web_extension_members:
                candidate_web_extension_members.setdefault(member, set())
                if not candidate_web_extension_members[member]:
                    warnings.add(
                        "FormulaFence found an Office Web Add-in definition package part not "
                        "declared by a task pane or in-content frame; affected controls have "
                        "a coverage gap."
                    )
                    unrecognized_members.add(member)

            extension_inspections: list[_OfficeWebAddinExtensionInspection] = []
            for member in sorted(candidate_web_extension_members, key=str.casefold):
                sources = candidate_web_extension_members[member]
                taskpane_sources = tuple(
                    sorted(
                        source
                        for source in sources
                        if source.startswith("taskpane:")
                    )
                )
                if taskpane_sources:
                    declaration_entries.append(
                        (
                            "web-extension-taskpane-part",
                            repr((member, taskpane_sources)),
                        )
                    )
                inspection = _office_web_addin_extension_inspection(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                extension_inspections.append(inspection)
                if not inspection.inspected:
                    unrecognized_members.add(member)
                    continue
                unresolved_binding_count += (
                    inspection.unresolved_snapshot_reference_count
                    + inspection.unresolved_binding_count
                )

            worksheet_inspections: list[_WorksheetWebExtensionInspection] = []
            worksheet_budget = _WorksheetWebExtensionBudget()
            for worksheet_member in sorted(set(worksheet_members), key=str.casefold):
                worksheet_inspections.append(
                    _worksheet_web_extension_inspection(
                        archive,
                        worksheet_member,
                        warnings,
                        worksheet_budget,
                    )
                )

            appref_sources: dict[str, list[str]] = defaultdict(list)
            for inspection in extension_inspections:
                if not inspection.inspected:
                    continue
                for appref in inspection.binding_apprefs:
                    appref_sources[appref].append(inspection.member)
            for sources in appref_sources.values():
                if len(sources) <= 1:
                    continue
                warnings.add(
                    "FormulaFence found one Office Web Add-in binding appref in multiple "
                    "definition parts; affected worksheet bindings have a coverage gap."
                )
                unresolved_binding_count += 1
            for inspection in worksheet_inspections:
                unresolved_binding_count += inspection.unrecognized_count
                for appref in inspection.binding_apprefs:
                    if len(appref_sources.get(appref, [])) == 1:
                        continue
                    warnings.add(
                        "FormulaFence found a worksheet Office Web Add-in binding without "
                        "one matching definition binding; affected controls have a coverage "
                        "gap."
                    )
                    unresolved_binding_count += 1

            def aggregate_signature(
                inspections: list[object], attribute: str
            ) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            declaration_entries.sort()
            all_inspections: list[object] = [
                *taskpane_inspections,
                *extension_inspections,
                *in_content_inspections,
            ]
            in_content_members = {
                member
                for member, sources in candidate_web_extension_members.items()
                if any(source.startswith("drawing:") for source in sources)
            }
            present_worksheet_inspections = [
                inspection for inspection in worksheet_inspections if inspection.present
            ]
            present_in_content_inspections = [
                inspection for inspection in in_content_inspections if inspection.present
            ]
            snapshot = OfficeWebAddinSnapshot(
                declared_taskpane_part_count=len(taskpane_relationships),
                taskpane_part_count=len(candidate_taskpane_members),
                web_extension_part_count=len(candidate_web_extension_members),
                unrecognized_part_count=(
                    len(unrecognized_members) + unresolved_binding_count
                ),
                taskpane_count=sum(
                    inspection.taskpane_count for inspection in taskpane_inspections
                ),
                visible_taskpane_count=sum(
                    inspection.visible_taskpane_count for inspection in taskpane_inspections
                ),
                locked_taskpane_count=sum(
                    inspection.locked_taskpane_count for inspection in taskpane_inspections
                ),
                web_extension_reference_count=sum(
                    inspection.web_extension_reference_count
                    for inspection in taskpane_inspections
                ),
                auto_show_taskpane_count=sum(
                    inspection.auto_show_taskpane_count
                    for inspection in extension_inspections
                ),
                store_reference_count=sum(
                    inspection.store_reference_count for inspection in extension_inspections
                ),
                alternate_reference_count=sum(
                    inspection.alternate_reference_count
                    for inspection in extension_inspections
                ),
                binding_count=sum(
                    inspection.binding_count for inspection in extension_inspections
                ),
                snapshot_reference_count=sum(
                    inspection.snapshot_reference_count
                    for inspection in extension_inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in all_inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in all_inspections
                ),
                worksheet_binding_sheet_count=len(present_worksheet_inspections),
                worksheet_binding_count=sum(
                    inspection.binding_count for inspection in worksheet_inspections
                ),
                in_content_drawing_part_count=len(present_in_content_inspections),
                in_content_web_extension_reference_count=sum(
                    inspection.reference_count for inspection in in_content_inspections
                ),
                in_content_web_extension_part_count=len(in_content_members),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                taskpane_signature=aggregate_signature(
                    taskpane_inspections, "definition_signature"
                ),
                web_extension_signature=aggregate_signature(
                    extension_inspections, "definition_signature"
                ),
                relationship_signature=aggregate_signature(
                    all_inspections, "relationship_signature"
                ),
                worksheet_binding_signature=aggregate_signature(
                    worksheet_inspections, "definition_signature"
                ),
                in_content_signature=_private_external_data_signature(
                    tuple(
                        sorted(
                            [
                                *in_content_declaration_entries,
                                *[
                                    ("in-content-frame", repr((inspection.member, value)))
                                    for inspection in in_content_inspections
                                    if (value := inspection.definition_signature)
                                    is not None
                                ],
                            ]
                        )
                    )
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _OfficeWebAddinMetadata(
            default,
            (
                "FormulaFence could not inspect Office Web Add-in OOXML "
                f"({type(error).__name__}); affected controls were not compared.",
            ),
        )
    return _OfficeWebAddinMetadata(snapshot, tuple(sorted(warnings)))


def _chart_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_ChartRawRelationship, ...]:
    """Read chart-package relationships without opening their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for chart inspection "
            f"({type(error).__name__}); affected charts were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting charts; affected charts "
            "were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_ChartRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _ChartRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting charts; "
            "affected charts may be incomplete."
        )
    return tuple(relationships)


def _chart_relationship_signature(
    relationships: tuple[_ChartRawRelationship, ...],
) -> str | None:
    """Fingerprint chart relationship semantics without identifier churn."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _chart_relationship_semantics(
    relationships: tuple[_ChartRawRelationship, ...],
    warnings: set[str],
    *,
    context: str,
) -> dict[str, tuple[str, str, str]]:
    """Resolve private chart relationship identifiers into stable semantics."""
    relationships_by_id: dict[str, list[_ChartRawRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found a chart "
                f"{context} relationship without an id; affected charts have a coverage gap."
            )
    semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        values = sorted(match.semantic_key() for match in matches)
        if len(values) > 1:
            warnings.add(
                "FormulaFence found duplicate chart "
                f"{context} relationship ids; affected charts have a coverage gap."
            )
        semantics[relationship_id] = values[0]
    return semantics


def _chart_xml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    *,
    omit_cached_data: bool = False,
) -> tuple[object, ...]:
    """Canonicalize private chart XML while resolving relationship identifiers."""
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute in _CHART_RELATIONSHIP_ATTRIBUTES:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
        else:
            attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _chart_xml_fragment(
            child,
            relationship_semantics,
            omit_cached_data=omit_cached_data,
        )
        for child in element
        if not (
            omit_cached_data
            and _xml_namespace(child.tag) == _DRAWINGML_CHART_NS
            and _xml_local_name(child.tag) in _CHART_CACHE_ELEMENT_NAMES
        )
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _chart_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _ChartXmlBudget,
) -> str | None:
    """Stream chart XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _CHART_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read a chart XML part whose XML structure "
        "exceeds the safety budget; affected charts have a coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _chart_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _ChartXmlBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded chart XML part without following relationship targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded chart XML part count budget; affected "
            "charts have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a chart XML package part; affected charts "
            "were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _CHART_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized chart XML part; affected "
            "charts have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded chart XML read budget; affected charts "
            "have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = _chart_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        warnings,
        budget,
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a chart XML package part "
            f"({type(error).__name__}); affected charts were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _chart_related_part_payloads(
    archive: ZipFile,
    members: set[str],
    unresolved_entries: list[tuple[str, str]],
    warnings: set[str],
    budget: _ChartRelatedPartBudget,
) -> _ChartRelatedPartPayloadInspection:
    """Fingerprint bounded direct chart-presentation payloads without opening them."""
    entries = list(unresolved_entries)
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts == 0:
            warnings.add(
                "FormulaFence reached its bounded chart related-part count budget; "
                "affected charts have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate a chart related part; affected charts "
                "were not compared."
            )
            entries.append(("missing-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _CHART_RELATED_PART_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized chart related part; "
                "affected charts have a coverage gap."
            )
            entries.append(("oversized-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded chart related-part read budget; "
                "affected charts have a coverage gap."
            )
            entries.append(("read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as payload:
                while chunk := payload.read(_CHART_RELATED_PART_HASH_CHUNK_BYTES):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("payload exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("payload did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint a chart related part "
                f"({type(error).__name__}); affected charts were not compared."
            )
            entries.append(("unreadable-part", metadata))
            uninspected_part_count += 1
            continue
        entries.append(("payload", repr((member, digest.hexdigest()))))
        fingerprinted_part_count += 1

    entries.sort()
    return _ChartRelatedPartPayloadInspection(
        internal_part_count=len(members) + len(unresolved_entries),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_signature=_private_external_data_signature(tuple(entries)),
    )


def _chart_drawing_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _ChartXmlBudget,
) -> _ChartDrawingInspection:
    """Discover DrawingML chart bindings without interpreting worksheet cells."""
    relationships = _chart_raw_relationships(
        archive,
        member,
        warnings,
        context="worksheet or chartsheet drawing",
    )
    relationship_semantics = _chart_relationship_semantics(
        relationships,
        warnings,
        context="worksheet or chartsheet drawing",
    )
    relationship_by_id: dict[str, _ChartRawRelationship] = {}
    for relationship in relationships:
        if relationship.relationship_id and relationship.relationship_id not in relationship_by_id:
            relationship_by_id[relationship.relationship_id] = relationship

    payload, fallback_signature = _chart_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _ChartDrawingInspection(
            member=member,
            unrecognized_count=1,
            declaration_signature=fallback_signature,
            relationship_signature=_chart_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a worksheet or chartsheet drawing XML part "
            f"({type(error).__name__}); affected charts were not compared."
        )
        return _ChartDrawingInspection(
            member=member,
            unrecognized_count=1,
            declaration_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )
    if (
        _xml_local_name(root.tag) != "wsDr"
        or _xml_namespace(root.tag) != _DRAWINGML_SPREADSHEET_NS
    ):
        warnings.add(
            "FormulaFence found a worksheet or chartsheet drawing part with an unexpected "
            "root; affected charts were not compared."
        )
        return _ChartDrawingInspection(
            member=member,
            unrecognized_count=1,
            declaration_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )

    chart_tag = f"{{{_DRAWINGML_CHART_NS}}}chart"
    chart_ex_tag = f"{{{_DRAWINGML_CHART_EX_NS}}}chart"
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    chart_references = [
        ("chart-ex" if element.tag == chart_ex_tag else "chart", element)
        for element in root.iter()
        if element.tag in {chart_tag, chart_ex_tag}
    ]
    selected_relationships: list[_ChartRawRelationship] = []
    referenced_relationship_ids: set[str] = set()
    chart_members: set[str] = set()
    chart_ex_members: set[str] = set()
    unrecognized_count = 0

    for chart_kind, chart in chart_references:
        expected_relationship_type = (
            _CHART_EX_RELATIONSHIP
            if chart_kind == "chart-ex"
            else _CHART_RELATIONSHIP
        )
        reference_label = (
            "extended DrawingML chart" if chart_kind == "chart-ex" else "DrawingML chart"
        )
        relationship_id = chart.get(relationship_attribute)
        if relationship_id is None:
            warnings.add(
                "FormulaFence found a "
                f"{reference_label} reference without a relationship id; "
                "affected charts have a coverage gap."
            )
            unrecognized_count += 1
            continue
        referenced_relationship_ids.add(relationship_id)
        relationship = relationship_by_id.get(relationship_id)
        if relationship is None:
            warnings.add(
                "FormulaFence found a "
                f"{reference_label} reference without a matching "
                "relationship; affected charts have a coverage gap."
            )
            unrecognized_count += 1
            continue
        selected_relationships.append(relationship)
        if relationship.relationship_type != expected_relationship_type:
            warnings.add(
                "FormulaFence found a "
                f"{reference_label} reference with an unexpected "
                "relationship type; affected charts have a coverage gap."
            )
            unrecognized_count += 1
            continue
        if relationship.target_mode.casefold() != "internal" or relationship.safe_target is None:
            warnings.add(
                "FormulaFence found a "
                f"{reference_label} reference without a safe internal "
                "target; affected charts were not compared."
            )
            unrecognized_count += 1
            continue
        if chart_kind == "chart-ex":
            chart_ex_members.add(relationship.safe_target)
        else:
            chart_members.add(relationship.safe_target)

    for relationship in relationships:
        if relationship.relationship_type not in {
            _CHART_RELATIONSHIP,
            _CHART_EX_RELATIONSHIP,
        }:
            continue
        if (
            relationship.relationship_id is None
            or relationship.relationship_id not in referenced_relationship_ids
        ):
            warnings.add(
                "FormulaFence found a chart or extended-chart relationship not bound by an "
                "inspected drawing; "
                "affected charts have a coverage gap."
            )
            unrecognized_count += 1

    if not chart_references and not any(
        relationship.relationship_type in {_CHART_RELATIONSHIP, _CHART_EX_RELATIONSHIP}
        for relationship in relationships
    ):
        return _ChartDrawingInspection(member=member, inspected=True)
    try:
        declaration_signature = _private_external_data_signature(
            tuple(
                (
                    f"{chart_kind}-reference:{index}",
                    repr(_chart_xml_fragment(chart, relationship_semantics)),
                )
                for index, (chart_kind, chart) in enumerate(chart_references)
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested DrawingML chart "
            "binding; affected charts were not compared."
        )
        declaration_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _ChartDrawingInspection(
        member=member,
        present=bool(chart_references or any(
            relationship.relationship_type in {_CHART_RELATIONSHIP, _CHART_EX_RELATIONSHIP}
            for relationship in relationships
        )),
        chart_reference_count=sum(
            chart_kind == "chart" for chart_kind, _chart in chart_references
        ),
        chart_ex_reference_count=sum(
            chart_kind == "chart-ex" for chart_kind, _chart in chart_references
        ),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        chart_members=tuple(sorted(chart_members, key=str.casefold)),
        chart_ex_members=tuple(sorted(chart_ex_members, key=str.casefold)),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        declaration_signature=declaration_signature,
        relationship_signature=_chart_relationship_signature(tuple(selected_relationships)),
    )


def _chart_external_workbook_formula_entries(
    root: ElementTree.Element,
    namespace: str,
) -> tuple[tuple[str, str], ...]:
    """Return private external endpoint tokens from one chart XML formula set."""
    formula_tag = f"{{{namespace}}}f"
    entries: list[tuple[str, str]] = []
    for formula_index, element in enumerate(root.iter(formula_tag)):
        for endpoint_index, token in enumerate(
            _external_workbook_formula_surface_tokens(element.text)
        ):
            entries.append((f"{formula_index}:{endpoint_index}", token))
    return tuple(entries)


def _chart_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _ChartXmlBudget,
) -> _ChartPartInspection:
    """Inspect one standard chart part without evaluating series formulas."""
    relationships = _chart_raw_relationships(archive, member, warnings, context="chart")
    relationship_semantics = _chart_relationship_semantics(
        relationships,
        warnings,
        context="chart",
    )
    relationship_by_id: dict[str, _ChartRawRelationship] = {}
    for relationship in relationships:
        if relationship.relationship_id and relationship.relationship_id not in relationship_by_id:
            relationship_by_id[relationship.relationship_id] = relationship

    payload, fallback_signature = _chart_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _ChartPartInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_chart_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a chart XML part "
            f"({type(error).__name__}); affected charts were not compared."
        )
        return _ChartPartInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )
    if (
        _xml_local_name(root.tag) != "chartSpace"
        or _xml_namespace(root.tag) != _DRAWINGML_CHART_NS
    ):
        warnings.add(
            "FormulaFence found a chart part with an unexpected root; affected charts "
            "were not compared."
        )
        return _ChartPartInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )

    external_workbook_formula_entries = _chart_external_workbook_formula_entries(
        root,
        _DRAWINGML_CHART_NS,
    )

    relationship_ids = {
        value
        for element in root.iter()
        for attribute in _CHART_RELATIONSHIP_ATTRIBUTES
        if (value := element.get(attribute)) is not None
    }
    user_shapes_tag = f"{{{_DRAWINGML_CHART_NS}}}userShapes"
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    user_shape_relationship_ids = {
        relationship_id
        for element in root.iter(user_shapes_tag)
        if (relationship_id := element.get(relationship_attribute)) is not None
    }
    selected_relationships: list[_ChartRawRelationship] = []
    user_shape_members: set[str] = set()
    payload_members: set[str] = set()
    unresolved_payload_entries: list[tuple[str, str]] = []
    unrecognized_count = 0

    for relationship_id in relationship_ids:
        relationship = relationship_by_id.get(relationship_id)
        if relationship is None:
            warnings.add(
                "FormulaFence found a chart relationship reference without a matching "
                "relationship; affected charts have a coverage gap."
            )
            unrecognized_count += 1
            continue
        selected_relationships.append(relationship)
        is_user_shape = relationship_id in user_shape_relationship_ids
        if is_user_shape and relationship.relationship_type != _CHART_USER_SHAPES_RELATIONSHIP:
            warnings.add(
                "FormulaFence found a chart overlay reference with an unexpected "
                "relationship type; affected charts have a coverage gap."
            )
            unrecognized_count += 1
            continue
        if relationship.target_mode.casefold() != "internal":
            if is_user_shape:
                warnings.add(
                    "FormulaFence found a chart overlay reference without an internal target; "
                    "affected charts were not compared."
                )
                unrecognized_count += 1
            continue
        if relationship.safe_target is None:
            warnings.add(
                "FormulaFence found a chart relationship without a safe internal target; "
                "affected charts were not compared."
            )
            unresolved_payload_entries.append(
                ("unsafe-related-target", repr(relationship.semantic_key()))
            )
            unrecognized_count += 1
            continue
        if is_user_shape:
            user_shape_members.add(relationship.safe_target)
        else:
            payload_members.add(relationship.safe_target)

    for relationship in relationships:
        if (
            relationship.relationship_id is None
            or relationship.relationship_id not in relationship_ids
        ):
            warnings.add(
                "FormulaFence found a chart relationship not bound by inspected chart XML; "
                "affected charts have a coverage gap."
            )
            unrecognized_count += 1

    cache_nodes = [
        element
        for element in root.iter()
        if _xml_namespace(element.tag) == _DRAWINGML_CHART_NS
        and _xml_local_name(element.tag) in _CHART_CACHE_ELEMENT_NAMES
    ]
    literal_containers = [
        element
        for element in root.iter()
        if _xml_namespace(element.tag) == _DRAWINGML_CHART_NS
        and _xml_local_name(element.tag) in _CHART_LITERAL_ELEMENT_NAMES
    ]
    point_tag = f"{{{_DRAWINGML_CHART_NS}}}pt"
    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    "chart",
                    repr(
                        _chart_xml_fragment(
                            root,
                            relationship_semantics,
                            omit_cached_data=True,
                        )
                    ),
                ),
            )
        )
        cached_data_signature = _private_external_data_signature(
            tuple(
                (f"cache:{index}", repr(_chart_xml_fragment(cache, relationship_semantics)))
                for index, cache in enumerate(cache_nodes)
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested chart part; "
            "affected charts were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        cached_data_signature = None
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _ChartPartInspection(
        member=member,
        chart_type_count=sum(
            _xml_namespace(element.tag) == _DRAWINGML_CHART_NS
            and _xml_local_name(element.tag) in _CHART_TYPE_ELEMENT_NAMES
            for element in root.iter()
        ),
        series_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_NS}}}ser" for element in root.iter()
        ),
        title_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_NS}}}title" for element in root.iter()
        ),
        data_reference_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_NS}}}f" for element in root.iter()
        ),
        numeric_data_reference_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_NS}}}numRef" for element in root.iter()
        ),
        string_data_reference_count=sum(
            element.tag
            in {
                f"{{{_DRAWINGML_CHART_NS}}}strRef",
                f"{{{_DRAWINGML_CHART_NS}}}multiLvlStrRef",
            }
            for element in root.iter()
        ),
        literal_data_point_count=sum(
            sum(point.tag == point_tag for point in container.iter())
            for container in literal_containers
        ),
        cached_data_point_count=sum(
            sum(point.tag == point_tag for point in cache.iter()) for cache in cache_nodes
        ),
        pivot_source_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_NS}}}pivotSource" for element in root.iter()
        ),
        external_data_reference_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_NS}}}externalData" for element in root.iter()
        ),
        user_shape_reference_count=len(user_shape_relationship_ids),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        user_shape_members=tuple(sorted(user_shape_members, key=str.casefold)),
        payload_members=tuple(sorted(payload_members, key=str.casefold)),
        unresolved_payload_entries=tuple(unresolved_payload_entries),
        external_workbook_formula_entries=external_workbook_formula_entries,
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        cached_data_signature=cached_data_signature,
        relationship_signature=_chart_relationship_signature(tuple(selected_relationships)),
    )


def _chart_ex_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _ChartXmlBudget,
) -> _ChartExPartInspection:
    """Inspect a bounded Office 2016+ ChartEx part and its direct targets.

    ChartEx uses a distinct relationship graph from legacy ``c:chart`` parts:
    style and colour parts are valid fixed children even when they do not have
    an ``r:id`` in the ChartEx XML.  FormulaFence therefore fingerprints every
    supported direct internal target while retaining unsupported, external, or
    unsafe edges as explicit coverage evidence.
    """
    relationships = _chart_raw_relationships(
        archive,
        member,
        warnings,
        context="extended chart",
    )
    relationship_semantics = _chart_relationship_semantics(
        relationships,
        warnings,
        context="extended chart",
    )
    relationships_by_id: dict[str, list[_ChartRawRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)

    payload, fallback_signature = _chart_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _ChartExPartInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_chart_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect an extended-chart XML part "
            f"({type(error).__name__}); affected charts were not compared."
        )
        return _ChartExPartInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )
    if (
        _xml_local_name(root.tag) != "chartSpace"
        or _xml_namespace(root.tag) != _DRAWINGML_CHART_EX_NS
    ):
        warnings.add(
            "FormulaFence found an extended-chart part with an unexpected root; "
            "affected charts were not compared."
        )
        return _ChartExPartInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )

    external_workbook_formula_entries = _chart_external_workbook_formula_entries(
        root,
        _DRAWINGML_CHART_EX_NS,
    )

    relationship_ids = {
        value
        for element in root.iter()
        for attribute in _CHART_RELATIONSHIP_ATTRIBUTES
        if (value := element.get(attribute)) is not None
    }
    payload_members: set[str] = set()
    unresolved_payload_entries: list[tuple[str, str]] = []
    unrecognized_count = 0
    for relationship_id in relationship_ids:
        matches = relationships_by_id.get(relationship_id, [])
        if len(matches) != 1:
            warnings.add(
                "FormulaFence found an extended-chart relationship reference without "
                "one matching relationship; affected charts have a coverage gap."
            )
            unrecognized_count += 1

    for relationship in relationships:
        if relationship.relationship_id:
            continue
        warnings.add(
            "FormulaFence found an extended-chart direct relationship without an id; "
            "affected charts have a coverage gap."
        )
        unrecognized_count += 1
        unresolved_payload_entries.append(
            ("missing-extended-chart-relationship-id", repr(relationship.semantic_key()))
        )

    for relationship_id, matches in relationships_by_id.items():
        if len(matches) <= 1:
            continue
        warnings.add(
            "FormulaFence found duplicate extended-chart relationship IDs; affected "
            "charts have a coverage gap."
        )
        unrecognized_count += 1
        unresolved_payload_entries.append(
            (
                "duplicate-extended-chart-relationship",
                repr(
                    (
                        relationship_id,
                        tuple(sorted(item.semantic_key() for item in matches)),
                    )
                ),
            )
        )

    for relationship in relationships:
        if relationship.relationship_type.casefold() not in _CHART_EX_DIRECT_RELATIONSHIPS:
            warnings.add(
                "FormulaFence found an unsupported direct extended-chart relationship; "
                "affected charts have a coverage gap."
            )
            unrecognized_count += 1
            unresolved_payload_entries.append(
                ("unsupported-extended-chart-relationship", repr(relationship.semantic_key()))
            )
            continue
        if relationship.target_mode.casefold() != "internal":
            warnings.add(
                "FormulaFence found an extended-chart direct relationship without a "
                "safe internal target; affected charts were not compared."
            )
            unrecognized_count += 1
            unresolved_payload_entries.append(
                ("external-extended-chart-relationship", repr(relationship.semantic_key()))
            )
            continue
        if relationship.safe_target is None:
            warnings.add(
                "FormulaFence found an extended-chart direct relationship without a "
                "safe package target; affected charts were not compared."
            )
            unrecognized_count += 1
            unresolved_payload_entries.append(
                ("unsafe-extended-chart-relationship", repr(relationship.semantic_key()))
            )
            continue
        payload_members.add(relationship.safe_target)

    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    "extended-chart",
                    repr(_chart_xml_fragment(root, relationship_semantics)),
                ),
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested extended-chart "
            "part; affected charts were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _ChartExPartInspection(
        member=member,
        series_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_EX_NS}}}series" for element in root.iter()
        ),
        title_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_EX_NS}}}title" for element in root.iter()
        ),
        data_reference_count=sum(
            element.tag == f"{{{_DRAWINGML_CHART_EX_NS}}}f" for element in root.iter()
        ),
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        payload_members=tuple(sorted(payload_members, key=str.casefold)),
        external_workbook_formula_entries=external_workbook_formula_entries,
        unresolved_payload_entries=tuple(unresolved_payload_entries),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_chart_relationship_signature(relationships),
    )


def _chart_user_shape_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _ChartXmlBudget,
) -> _ChartUserShapeInspection:
    """Inspect one chart overlay part without rendering shapes or opening media."""
    relationships = _chart_raw_relationships(
        archive,
        member,
        warnings,
        context="chart overlay",
    )
    relationship_semantics = _chart_relationship_semantics(
        relationships,
        warnings,
        context="chart overlay",
    )
    relationship_by_id: dict[str, _ChartRawRelationship] = {}
    for relationship in relationships:
        if relationship.relationship_id and relationship.relationship_id not in relationship_by_id:
            relationship_by_id[relationship.relationship_id] = relationship

    payload, fallback_signature = _chart_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _ChartUserShapeInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_chart_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a chart overlay XML part "
            f"({type(error).__name__}); affected charts were not compared."
        )
        return _ChartUserShapeInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )
    if (
        _xml_local_name(root.tag) != "userShapes"
        or _xml_namespace(root.tag) != _DRAWINGML_CHART_DRAWING_NS
    ):
        warnings.add(
            "FormulaFence found a chart overlay part with an unexpected root; affected "
            "charts were not compared."
        )
        return _ChartUserShapeInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_chart_relationship_signature(relationships),
        )

    relationship_ids = {
        value
        for element in root.iter()
        for attribute in _CHART_RELATIONSHIP_ATTRIBUTES
        if (value := element.get(attribute)) is not None
    }
    selected_relationships: list[_ChartRawRelationship] = []
    payload_members: set[str] = set()
    unresolved_payload_entries: list[tuple[str, str]] = []
    unrecognized_count = 0
    for relationship_id in relationship_ids:
        relationship = relationship_by_id.get(relationship_id)
        if relationship is None:
            warnings.add(
                "FormulaFence found a chart overlay relationship reference without a "
                "matching relationship; affected charts have a coverage gap."
            )
            unrecognized_count += 1
            continue
        selected_relationships.append(relationship)
        if relationship.target_mode.casefold() != "internal":
            continue
        if relationship.safe_target is None:
            warnings.add(
                "FormulaFence found a chart overlay relationship without a safe internal "
                "target; affected charts were not compared."
            )
            unresolved_payload_entries.append(
                ("unsafe-overlay-target", repr(relationship.semantic_key()))
            )
            unrecognized_count += 1
            continue
        payload_members.add(relationship.safe_target)

    for relationship in relationships:
        if (
            relationship.relationship_id is None
            or relationship.relationship_id not in relationship_ids
        ):
            warnings.add(
                "FormulaFence found a chart overlay relationship not bound by inspected "
                "overlay XML; affected charts have a coverage gap."
            )
            unrecognized_count += 1
    try:
        definition_signature = _private_external_data_signature(
            (("chart-overlay", repr(_chart_xml_fragment(root, relationship_semantics))),)
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested chart overlay; "
            "affected charts were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    shape_names = {"sp", "pic", "cxnSp", "graphicFrame", "grpSp"}
    return _ChartUserShapeInspection(
        member=member,
        shape_count=sum(
            _xml_namespace(element.tag) == _DRAWINGML_CHART_DRAWING_NS
            and _xml_local_name(element.tag) in shape_names
            for element in root.iter()
        ),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        payload_members=tuple(sorted(payload_members, key=str.casefold)),
        unresolved_payload_entries=tuple(unresolved_payload_entries),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_chart_relationship_signature(tuple(selected_relationships)),
    )


def _chart_definition_metadata(path: Path) -> _ChartDefinitionMetadata:
    """Inspect legacy and Office 2016+ chart presentation parts before reading cells.

    The scan is package-only: it does not calculate a series formula, render a
    chart, open related media or embedded data, or follow external targets.
    """
    warnings: set[str] = set()
    default = ChartDefinitionSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                return _ChartDefinitionMetadata(
                    default,
                    (
                        "FormulaFence could not map worksheet OOXML for chart inspection "
                        f"({type(error).__name__}); affected charts were not compared.",
                    ),
                )

            xml_budget = _ChartXmlBudget()
            related_part_budget = _ChartRelatedPartBudget()
            drawing_sources: dict[str, set[tuple[str, str, str]]] = defaultdict(set)
            unresolved_drawing_entries: list[tuple[str, str]] = []
            unrecognized_declaration_count = 0
            for sheet, (member, sheet_kind) in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                if sheet_kind not in {"worksheet", "chartsheet"}:
                    continue
                relationships = _chart_raw_relationships(
                    archive,
                    member,
                    warnings,
                    context="worksheet or chartsheet",
                )
                for relationship in relationships:
                    if relationship.relationship_type != _WORKSHEET_DRAWING_RELATIONSHIP:
                        continue
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        warnings.add(
                            "FormulaFence found a worksheet or chartsheet drawing relationship "
                            "without a safe internal target; affected charts were not compared."
                        )
                        unresolved_drawing_entries.append(
                            (member, repr(relationship.semantic_key()))
                        )
                        unrecognized_declaration_count += 1
                        continue
                    drawing_sources[relationship.safe_target].add(
                        (sheet, sheet_kind, member)
                    )

            drawing_inspections: list[_ChartDrawingInspection] = []
            chart_sources: dict[str, set[str]] = defaultdict(set)
            chart_ex_sources: dict[str, set[str]] = defaultdict(set)
            declaration_entries: list[tuple[str, str]] = []
            for drawing_member in sorted(drawing_sources, key=str.casefold):
                sources = tuple(
                    sorted(drawing_sources[drawing_member], key=lambda item: item[0].casefold())
                )
                inspection = _chart_drawing_inspection(
                    archive,
                    drawing_member,
                    warnings,
                    xml_budget,
                )
                drawing_inspections.append(inspection)
                if not inspection.present:
                    continue
                declaration_entries.append(
                    ("chart-drawing-part", repr((drawing_member, sources)))
                )
                for chart_member in inspection.chart_members:
                    chart_sources[chart_member].add(drawing_member)
                for chart_ex_member in inspection.chart_ex_members:
                    chart_ex_sources[chart_ex_member].add(drawing_member)

            orphan_chart_part_count = 0
            discovered_chart_members = {
                entry.filename
                for entry in archive.infolist()
                if _CHART_PART_PATTERN.fullmatch(entry.filename)
            }
            for chart_member in discovered_chart_members:
                if chart_member in chart_ex_sources:
                    continue
                chart_sources.setdefault(chart_member, set())
                if chart_member not in {
                    member
                    for inspection in drawing_inspections
                    for member in inspection.chart_members
                }:
                    warnings.add(
                        "FormulaFence found a chart package part not declared by an inspected "
                        "worksheet or chartsheet drawing; affected charts have a coverage gap."
                    )
                    orphan_chart_part_count += 1

            discovered_chart_ex_members = {
                entry.filename
                for entry in archive.infolist()
                if _CHART_EX_PART_PATTERN.fullmatch(entry.filename)
            }
            for chart_ex_member in discovered_chart_ex_members:
                if chart_ex_member in chart_sources:
                    continue
                chart_ex_sources.setdefault(chart_ex_member, set())
                if chart_ex_member not in {
                    member
                    for inspection in drawing_inspections
                    for member in inspection.chart_ex_members
                }:
                    warnings.add(
                        "FormulaFence found an extended-chart package part not declared by "
                        "an inspected worksheet or chartsheet drawing; affected charts have "
                        "a coverage gap."
                    )
                    orphan_chart_part_count += 1

            chart_inspections: list[_ChartPartInspection] = []
            chart_ex_inspections: list[_ChartExPartInspection] = []
            user_shape_sources: dict[str, set[str]] = defaultdict(set)
            payload_members: set[str] = set()
            unresolved_payload_entries: list[tuple[str, str]] = []
            for chart_member in sorted(chart_sources, key=str.casefold):
                sources = tuple(sorted(chart_sources[chart_member], key=str.casefold))
                declaration_entries.append(("chart-part", repr((chart_member, sources))))
                inspection = _chart_part_inspection(
                    archive,
                    chart_member,
                    warnings,
                    xml_budget,
                )
                chart_inspections.append(inspection)
                for user_shape_member in inspection.user_shape_members:
                    user_shape_sources[user_shape_member].add(chart_member)
                payload_members.update(inspection.payload_members)
                unresolved_payload_entries.extend(inspection.unresolved_payload_entries)

            for chart_ex_member in sorted(chart_ex_sources, key=str.casefold):
                sources = tuple(sorted(chart_ex_sources[chart_ex_member], key=str.casefold))
                declaration_entries.append(
                    ("extended-chart-part", repr((chart_ex_member, sources)))
                )
                inspection = _chart_ex_part_inspection(
                    archive,
                    chart_ex_member,
                    warnings,
                    xml_budget,
                )
                chart_ex_inspections.append(inspection)
                payload_members.update(inspection.payload_members)
                unresolved_payload_entries.extend(inspection.unresolved_payload_entries)

            user_shape_inspections: list[_ChartUserShapeInspection] = []
            for user_shape_member in sorted(user_shape_sources, key=str.casefold):
                sources = tuple(sorted(user_shape_sources[user_shape_member], key=str.casefold))
                declaration_entries.append(
                    ("chart-overlay-part", repr((user_shape_member, sources)))
                )
                inspection = _chart_user_shape_inspection(
                    archive,
                    user_shape_member,
                    warnings,
                    xml_budget,
                )
                user_shape_inspections.append(inspection)
                payload_members.update(inspection.payload_members)
                unresolved_payload_entries.extend(inspection.unresolved_payload_entries)

            payload_inspection = _chart_related_part_payloads(
                archive,
                payload_members,
                unresolved_payload_entries,
                warnings,
                related_part_budget,
            )

            def aggregate_signature(
                inspections: list[object], attribute: str
            ) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            chart_host_sheets = {
                sheet
                for drawing_member, sources in drawing_sources.items()
                if any(
                    inspection.member == drawing_member and inspection.present
                    for inspection in drawing_inspections
                )
                for sheet, _sheet_kind, _member in sources
            }
            declaration_entries.extend(
                ("unresolved-sheet-drawing-relationship", entry)
                for entry in unresolved_drawing_entries
            )
            declaration_entries.sort()
            all_inspections: list[object] = [
                *drawing_inspections,
                *chart_inspections,
                *chart_ex_inspections,
                *user_shape_inspections,
            ]
            external_workbook_formula_entries = tuple(
                (inspection.member, formula_position, endpoint)
                for inspection in [*chart_inspections, *chart_ex_inspections]
                for formula_position, endpoint in inspection.external_workbook_formula_entries
            )
            external_workbook_formula_surfaces = {
                (member, formula_position)
                for member, formula_position, _endpoint in external_workbook_formula_entries
            }
            opaque_external_workbook_formula_parts = tuple(
                (inspection.member, inspection.definition_signature)
                for inspection in [*chart_inspections, *chart_ex_inspections]
                if not inspection.inspected
            )
            snapshot = ChartDefinitionSnapshot(
                chart_host_sheet_count=len(chart_host_sheets),
                chart_drawing_part_count=sum(
                    inspection.present for inspection in drawing_inspections
                ),
                chart_reference_count=sum(
                    inspection.chart_reference_count for inspection in drawing_inspections
                ),
                chart_part_count=len(chart_sources),
                chart_ex_reference_count=sum(
                    inspection.chart_ex_reference_count
                    for inspection in drawing_inspections
                ),
                chart_ex_part_count=len(chart_ex_sources),
                chart_ex_series_count=sum(
                    inspection.series_count for inspection in chart_ex_inspections
                ),
                chart_ex_title_count=sum(
                    inspection.title_count for inspection in chart_ex_inspections
                ),
                chart_ex_data_reference_count=sum(
                    inspection.data_reference_count for inspection in chart_ex_inspections
                ),
                chart_user_shape_part_count=len(user_shape_sources),
                chart_user_shape_count=sum(
                    inspection.shape_count for inspection in user_shape_inspections
                ),
                chart_type_count=sum(
                    inspection.chart_type_count for inspection in chart_inspections
                ),
                series_count=sum(
                    inspection.series_count for inspection in chart_inspections
                ),
                title_count=sum(
                    inspection.title_count for inspection in chart_inspections
                ),
                data_reference_count=sum(
                    inspection.data_reference_count for inspection in chart_inspections
                ),
                numeric_data_reference_count=sum(
                    inspection.numeric_data_reference_count
                    for inspection in chart_inspections
                ),
                string_data_reference_count=sum(
                    inspection.string_data_reference_count
                    for inspection in chart_inspections
                ),
                literal_data_point_count=sum(
                    inspection.literal_data_point_count for inspection in chart_inspections
                ),
                cached_data_point_count=sum(
                    inspection.cached_data_point_count for inspection in chart_inspections
                ),
                pivot_source_count=sum(
                    inspection.pivot_source_count for inspection in chart_inspections
                ),
                external_data_reference_count=sum(
                    inspection.external_data_reference_count
                    for inspection in chart_inspections
                ),
                user_shape_reference_count=sum(
                    inspection.user_shape_reference_count
                    for inspection in chart_inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in all_inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in all_inspections
                ),
                internal_related_part_count=payload_inspection.internal_part_count,
                fingerprinted_related_part_count=payload_inspection.fingerprinted_part_count,
                uninspected_related_part_count=payload_inspection.uninspected_part_count,
                unrecognized_part_count=(
                    unrecognized_declaration_count
                    + orphan_chart_part_count
                    + sum(inspection.unrecognized_count for inspection in all_inspections)
                ),
                external_workbook_formula_surface_count=len(
                    external_workbook_formula_surfaces
                ),
                external_workbook_formula_reference_count=len(
                    external_workbook_formula_entries
                ),
                external_workbook_formula_signature=_private_external_data_signature(
                    tuple(
                        (f"formula:{index}", repr(entry))
                        for index, entry in enumerate(
                            sorted(external_workbook_formula_entries)
                        )
                    )
                ),
                external_workbook_formula_opaque_part_count=len(
                    opaque_external_workbook_formula_parts
                ),
                external_workbook_formula_opaque_signature=(
                    _private_external_data_signature(
                        tuple(
                            (f"opaque:{index}", repr(entry))
                            for index, entry in enumerate(
                                opaque_external_workbook_formula_parts
                            )
                        )
                    )
                    if opaque_external_workbook_formula_parts
                    else None
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                definition_signature=aggregate_signature(
                    [*chart_inspections, *chart_ex_inspections], "definition_signature"
                ),
                cached_data_signature=aggregate_signature(
                    list(chart_inspections), "cached_data_signature"
                ),
                user_shape_signature=aggregate_signature(
                    list(user_shape_inspections), "definition_signature"
                ),
                relationship_signature=aggregate_signature(
                    all_inspections, "relationship_signature"
                ),
                related_part_payload_signature=payload_inspection.payload_signature,
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _ChartDefinitionMetadata(
            default,
            (
                "FormulaFence could not inspect chart OOXML "
                f"({type(error).__name__}); affected charts were not compared.",
            ),
        )
    return _ChartDefinitionMetadata(snapshot, tuple(sorted(warnings)))


def _pivot_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_PivotRawRelationship, ...]:
    """Read PivotTable-package relationships without opening their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for PivotTable inspection "
            f"({type(error).__name__}); affected PivotTables were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting PivotTables; affected "
            "PivotTables were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_PivotRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _PivotRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting PivotTables; "
            "affected PivotTables may be incomplete."
        )
    return tuple(relationships)


def _pivot_relationship_signature(
    relationships: tuple[_PivotRawRelationship, ...],
) -> str | None:
    """Fingerprint PivotTable relationship semantics without identifier churn."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _pivot_relationship_semantics(
    relationships: tuple[_PivotRawRelationship, ...],
    warnings: set[str],
    *,
    context: str,
) -> dict[str, tuple[str, str, str]]:
    """Resolve PivotTable relationship identifiers into stable private semantics."""
    relationships_by_id: dict[str, list[_PivotRawRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found a PivotTable "
                f"{context} relationship without an id; affected PivotTables have a coverage gap."
            )
    semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        values = sorted(match.semantic_key() for match in matches)
        if len(values) > 1:
            warnings.add(
                "FormulaFence found duplicate PivotTable "
                f"{context} relationship ids; affected PivotTables have a coverage gap."
            )
        semantics[relationship_id] = values[0]
    return semantics


def _pivot_xml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    *,
    cache_definition_members_by_id: Mapping[str, str] | None = None,
    omit_cache_data: bool = False,
) -> tuple[object, ...]:
    """Canonicalize private PivotTable XML while resolving relationship identifiers."""
    local_name = _xml_local_name(element.tag)
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        attribute_name = _xml_local_name(attribute)
        if (
            _xml_namespace(element.tag) == _OFFICE_2010_SPREADSHEET_NS
            and local_name == "pivotCacheDefinition"
            and attribute_name == "pivotCacheId"
        ):
            # This writer-assigned extension ID is resolved to its cache part by
            # the slicer/Timeline scanner, which can distinguish a broken link
            # from a coordinated identifier renumbering.
            continue
        if attribute in _PIVOT_RELATIONSHIP_ATTRIBUTES:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if (
            local_name == "pivotTableDefinition"
            and attribute_name == "cacheId"
            and cache_definition_members_by_id is not None
        ):
            cache_definition_member = cache_definition_members_by_id.get(value)
            resolved = (
                ("cache-definition", cache_definition_member)
                if cache_definition_member is not None
                else ("missing-cache-definition", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if (
            omit_cache_data
            and local_name == "pivotCacheDefinition"
            and attribute_name in _PIVOT_CACHE_DEFINITION_VOLATILE_ATTRIBUTES
        ):
            continue
        attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _pivot_xml_fragment(
            child,
            relationship_semantics,
            cache_definition_members_by_id=cache_definition_members_by_id,
            omit_cache_data=omit_cache_data,
        )
        for child in element
        if not (
            omit_cache_data
            and _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) in {"cacheSource", "sharedItems"}
        )
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _pivot_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _PivotXmlBudget,
) -> str | None:
    """Stream PivotTable XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _PIVOT_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read a PivotTable XML part whose XML structure "
        "exceeds the safety budget; affected PivotTables have a coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _pivot_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _PivotXmlBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded PivotTable XML part without following relationship targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded PivotTable XML part count budget; affected "
            "PivotTables have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a PivotTable XML package part; affected "
            "PivotTables were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _PIVOT_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized PivotTable XML part; affected "
            "PivotTables have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded PivotTable XML read budget; affected "
            "PivotTables have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = _pivot_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        warnings,
        budget,
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a PivotTable XML package part "
            f"({type(error).__name__}); affected PivotTables were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _pivot_cache_record_payloads(
    archive: ZipFile,
    members: set[str],
    unresolved_entries: list[tuple[str, str]],
    warnings: set[str],
    budget: _PivotCacheRecordBudget,
) -> _PivotCacheRecordPayloadInspection:
    """Fingerprint bounded raw PivotTable cache records without parsing values."""
    entries = list(unresolved_entries)
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts == 0:
            warnings.add(
                "FormulaFence reached its bounded PivotTable cache-record part count budget; "
                "affected PivotTables have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate a PivotTable cache-record part; affected "
                "PivotTables were not compared."
            )
            entries.append(("missing-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _PIVOT_CACHE_RECORD_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized PivotTable cache-record part; "
                "affected PivotTables have a coverage gap."
            )
            entries.append(("oversized-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded PivotTable cache-record read budget; "
                "affected PivotTables have a coverage gap."
            )
            entries.append(("read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as payload:
                while chunk := payload.read(_PIVOT_CACHE_RECORD_HASH_CHUNK_BYTES):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("payload exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("payload did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint a PivotTable cache-record part "
                f"({type(error).__name__}); affected PivotTables were not compared."
            )
            entries.append(("unreadable-part", metadata))
            uninspected_part_count += 1
            continue
        entries.append(("payload", repr((member, digest.hexdigest()))))
        fingerprinted_part_count += 1

    entries.sort()
    return _PivotCacheRecordPayloadInspection(
        record_part_count=len(members) + len(unresolved_entries),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_signature=_private_external_data_signature(tuple(entries)),
    )


def _pivot_table_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _PivotXmlBudget,
    cache_definition_members_by_id: Mapping[str, tuple[str, ...]],
) -> _PivotTablePartInspection:
    """Inspect one PivotTable view definition without calculating its report."""
    relationships = _pivot_raw_relationships(
        archive,
        member,
        warnings,
        context="PivotTable",
    )
    relationship_semantics = _pivot_relationship_semantics(
        relationships,
        warnings,
        context="PivotTable",
    )
    payload, fallback_signature = _pivot_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _PivotTablePartInspection(
            member=member,
            unrecognized_count=1,
            layout_signature=fallback_signature,
            relationship_signature=_pivot_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a PivotTable XML part "
            f"({type(error).__name__}); affected PivotTables were not compared."
        )
        return _PivotTablePartInspection(
            member=member,
            unrecognized_count=1,
            layout_signature=_private_payload_signature(payload),
            relationship_signature=_pivot_relationship_signature(relationships),
        )
    if (
        _xml_local_name(root.tag) != "pivotTableDefinition"
        or _xml_namespace(root.tag) != _SPREADSHEETML_NS
    ):
        warnings.add(
            "FormulaFence found a PivotTable part with an unexpected root; affected "
            "PivotTables were not compared."
        )
        return _PivotTablePartInspection(
            member=member,
            unrecognized_count=1,
            layout_signature=_private_payload_signature(payload),
            relationship_signature=_pivot_relationship_signature(relationships),
        )

    cache_id = root.get("cacheId")
    unrecognized_count = 0
    if cache_id is None:
        warnings.add(
            "FormulaFence found a PivotTable definition without a cache id; affected "
            "PivotTables have a coverage gap."
        )
        unrecognized_count += 1
    cache_relationships = tuple(
        relationship
        for relationship in relationships
        if relationship.relationship_type == _PIVOT_CACHE_DEFINITION_RELATIONSHIP
    )
    cache_definition_members: set[str] = set()
    for relationship in cache_relationships:
        if relationship.target_mode.casefold() != "internal" or relationship.safe_target is None:
            warnings.add(
                "FormulaFence found a PivotTable cache-definition relationship without a "
                "safe internal target; affected PivotTables were not compared."
            )
            unrecognized_count += 1
            continue
        cache_definition_members.add(relationship.safe_target)
    if not cache_relationships:
        warnings.add(
            "FormulaFence found a PivotTable definition without a cache-definition "
            "relationship; affected PivotTables have a coverage gap."
        )
        unrecognized_count += 1
    for relationship in relationships:
        if relationship.relationship_type == _PIVOT_CACHE_DEFINITION_RELATIONSHIP:
            continue
        warnings.add(
            "FormulaFence found an unmodelled PivotTable relationship; affected "
            "PivotTables have a coverage gap."
        )
        unrecognized_count += 1
    expected_cache_members = (
        set(cache_definition_members_by_id.get(cache_id, ())) if cache_id is not None else set()
    )
    if cache_id is not None and not expected_cache_members:
        warnings.add(
            "FormulaFence could not bind a PivotTable cache id to a workbook cache "
            "declaration; affected PivotTables have a coverage gap."
        )
        unrecognized_count += 1
    elif expected_cache_members and cache_definition_members != expected_cache_members:
        warnings.add(
            "FormulaFence found a PivotTable cache relationship that disagrees with its "
            "workbook cache declaration; affected PivotTables have a coverage gap."
        )
        unrecognized_count += 1

    def child_count(container_name: str, child_name: str) -> int:
        container = root.find(f"{{{_SPREADSHEETML_NS}}}{container_name}")
        if container is None:
            return 0
        return len(container.findall(f"{{{_SPREADSHEETML_NS}}}{child_name}"))

    try:
        layout_signature = _private_external_data_signature(
            (
                (
                    "pivot-table",
                    repr(
                        _pivot_xml_fragment(
                            root,
                            relationship_semantics,
                            cache_definition_members_by_id={
                                identifier: members[0]
                                for identifier, members in cache_definition_members_by_id.items()
                                if len(members) == 1
                            },
                        )
                    ),
                ),
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested PivotTable part; "
            "affected PivotTables were not compared."
        )
        layout_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _PivotTablePartInspection(
        member=member,
        cache_id=cache_id,
        layout_location_count=len(root.findall(f"{{{_SPREADSHEETML_NS}}}location")),
        pivot_field_count=child_count("pivotFields", "pivotField"),
        row_field_count=child_count("rowFields", "field"),
        column_field_count=child_count("colFields", "field"),
        page_field_count=child_count("pageFields", "pageField"),
        data_field_count=child_count("dataFields", "dataField"),
        filter_count=child_count("filters", "filter"),
        row_item_count=child_count("rowItems", "i"),
        column_item_count=child_count("colItems", "i"),
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        cache_definition_members=tuple(
            sorted(cache_definition_members, key=str.casefold)
        ),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        layout_signature=layout_signature,
        relationship_signature=_pivot_relationship_signature(relationships),
    )


def _pivot_cache_definition_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _PivotXmlBudget,
) -> _PivotCacheDefinitionInspection:
    """Inspect one PivotTable cache definition without opening cache-record values."""
    relationships = _pivot_raw_relationships(
        archive,
        member,
        warnings,
        context="PivotTable cache definition",
    )
    relationship_semantics = _pivot_relationship_semantics(
        relationships,
        warnings,
        context="PivotTable cache definition",
    )
    relationship_by_id: dict[str, _PivotRawRelationship] = {}
    for relationship in relationships:
        if relationship.relationship_id and relationship.relationship_id not in relationship_by_id:
            relationship_by_id[relationship.relationship_id] = relationship

    payload, fallback_signature = _pivot_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _PivotCacheDefinitionInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_pivot_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a PivotTable cache-definition XML part "
            f"({type(error).__name__}); affected PivotTables were not compared."
        )
        return _PivotCacheDefinitionInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_pivot_relationship_signature(relationships),
        )
    if (
        _xml_local_name(root.tag) != "pivotCacheDefinition"
        or _xml_namespace(root.tag) != _SPREADSHEETML_NS
    ):
        warnings.add(
            "FormulaFence found a PivotTable cache-definition part with an unexpected root; "
            "affected PivotTables were not compared."
        )
        return _PivotCacheDefinitionInspection(
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_pivot_relationship_signature(relationships),
        )

    unrecognized_count = 0
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    record_relationship_id = root.get(relationship_attribute)
    cache_record_members: set[str] = set()
    if record_relationship_id is not None:
        relationship = relationship_by_id.get(record_relationship_id)
        if relationship is None:
            warnings.add(
                "FormulaFence found a PivotTable cache-record reference without a matching "
                "relationship; affected PivotTables have a coverage gap."
            )
            unrecognized_count += 1
        elif relationship.relationship_type != _PIVOT_CACHE_RECORDS_RELATIONSHIP:
            warnings.add(
                "FormulaFence found a PivotTable cache-record reference with an unexpected "
                "relationship type; affected PivotTables have a coverage gap."
            )
            unrecognized_count += 1
        elif (
            relationship.target_mode.casefold() != "internal"
            or relationship.safe_target is None
        ):
            warnings.add(
                "FormulaFence found a PivotTable cache-record reference without a safe "
                "internal target; affected PivotTables were not compared."
            )
            unrecognized_count += 1
        else:
            cache_record_members.add(relationship.safe_target)
    for relationship in relationships:
        if relationship.relationship_type != _PIVOT_CACHE_RECORDS_RELATIONSHIP:
            warnings.add(
                "FormulaFence found an unmodelled PivotTable cache-definition relationship; "
                "affected PivotTables have a coverage gap."
            )
            unrecognized_count += 1
            continue
        if relationship.relationship_id != record_relationship_id:
            warnings.add(
                "FormulaFence found a PivotTable cache-record relationship not bound by its "
                "cache definition; affected PivotTables have a coverage gap."
            )
            unrecognized_count += 1

    cache_record_count = 0
    record_count_value = root.get("recordCount")
    if record_count_value is not None:
        try:
            cache_record_count = int(record_count_value)
            if cache_record_count < 0:
                raise ValueError("negative record count")
        except ValueError:
            warnings.add(
                "FormulaFence could not interpret a PivotTable cache record count; affected "
                "PivotTables have a coverage gap."
            )
            cache_record_count = 0
            unrecognized_count += 1
    cache_fields = [
        element
        for element in root.iter(f"{{{_SPREADSHEETML_NS}}}cacheField")
    ]
    shared_items = [
        element
        for element in root.iter(f"{{{_SPREADSHEETML_NS}}}sharedItems")
    ]
    slicer_timeline_cache_ids: set[str] = set()
    for element in root.iter():
        if (
            _xml_namespace(element.tag) != _OFFICE_2010_SPREADSHEET_NS
            or _xml_local_name(element.tag) != "pivotCacheDefinition"
        ):
            continue
        pivot_cache_id = element.get("pivotCacheId")
        if pivot_cache_id is None:
            warnings.add(
                "FormulaFence found a PivotTable cache extension without its required "
                "slicer/Timeline cache id; affected filters have a coverage gap."
            )
            unrecognized_count += 1
            continue
        slicer_timeline_cache_ids.add(pivot_cache_id)
    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    "pivot-cache-definition",
                    repr(
                        _pivot_xml_fragment(
                            root,
                            relationship_semantics,
                            omit_cache_data=True,
                        )
                    ),
                ),
            )
        )
        cached_shared_item_signature = _private_external_data_signature(
            tuple(
                [("record-count", record_count_value or "")]
                + [
                    (
                        f"shared-items:{index}",
                        repr(_pivot_xml_fragment(items, relationship_semantics)),
                    )
                    for index, items in enumerate(shared_items)
                ]
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested PivotTable cache "
            "definition; affected PivotTables were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        cached_shared_item_signature = None
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _PivotCacheDefinitionInspection(
        member=member,
        cache_field_count=len(cache_fields),
        shared_item_count=sum(len(list(items)) for items in shared_items),
        calculated_item_count=sum(
            element.tag == f"{{{_SPREADSHEETML_NS}}}calculatedItem" for element in root.iter()
        ),
        calculated_member_count=sum(
            element.tag == f"{{{_SPREADSHEETML_NS}}}calculatedMember" for element in root.iter()
        ),
        cache_record_count=cache_record_count,
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        cache_record_members=tuple(sorted(cache_record_members, key=str.casefold)),
        slicer_timeline_cache_ids=tuple(sorted(slicer_timeline_cache_ids)),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        cached_shared_item_signature=cached_shared_item_signature,
        relationship_signature=_pivot_relationship_signature(relationships),
    )


def _pivot_table_metadata(path: Path) -> _PivotTableMetadata:
    """Inspect PivotTable views and cache packages before the reader omits them.

    The scan is package-only: it neither refreshes a cache nor renders a report.
    Cache source and refresh controls are already compared by the external-data
    scanner; this scanner instead protects PivotTable presentation, cache schema,
    shared-item, and bounded cache-record material.
    """
    warnings: set[str] = set()
    default = PivotTableDefinitionSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                workbook_root = _xml_root(archive, "xl/workbook.xml")
                sheet_parts = _sheet_xml_parts(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _PivotTableMetadata(
                    default,
                    (
                        "FormulaFence could not map workbook OOXML for PivotTable inspection "
                        f"({type(error).__name__}); affected PivotTables were not compared.",
                    ),
                )

            xml_budget = _PivotXmlBudget()
            record_budget = _PivotCacheRecordBudget()
            workbook_relationships = _pivot_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
            )
            workbook_relationships_by_id: dict[
                str, list[_PivotRawRelationship]
            ] = defaultdict(list)
            for relationship in workbook_relationships:
                if relationship.relationship_id:
                    workbook_relationships_by_id[relationship.relationship_id].append(
                        relationship
                    )

            cache_definition_members_by_id: dict[str, set[str]] = defaultdict(set)
            declaration_entries: list[tuple[str, str]] = []
            unrecognized_declaration_count = 0
            declared_workbook_relationship_ids: set[str] = set()
            declared_cache_ids: set[str] = set()
            cache_container = workbook_root.find(f"{{{_SPREADSHEETML_NS}}}pivotCaches")
            if cache_container is not None:
                for cache in cache_container.findall(f"{{{_SPREADSHEETML_NS}}}pivotCache"):
                    cache_id = cache.get("cacheId")
                    relationship_id = cache.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id")
                    if cache_id is None:
                        warnings.add(
                            "FormulaFence found a PivotTable cache declaration without a cache "
                            "id; affected PivotTables have a coverage gap."
                        )
                        unrecognized_declaration_count += 1
                    elif cache_id in declared_cache_ids:
                        warnings.add(
                            "FormulaFence found duplicate PivotTable cache ids; affected "
                            "PivotTables have a coverage gap."
                        )
                        unrecognized_declaration_count += 1
                    else:
                        declared_cache_ids.add(cache_id)
                    if relationship_id is None:
                        warnings.add(
                            "FormulaFence found a PivotTable cache declaration without a "
                            "relationship; affected PivotTables have a coverage gap."
                        )
                        unrecognized_declaration_count += 1
                        continue
                    declared_workbook_relationship_ids.add(relationship_id)
                    relationship_matches = workbook_relationships_by_id.get(
                        relationship_id,
                        [],
                    )
                    if not relationship_matches:
                        warnings.add(
                            "FormulaFence found a PivotTable cache declaration without a "
                            "matching workbook relationship; affected PivotTables have a "
                            "coverage gap."
                        )
                        unrecognized_declaration_count += 1
                        continue
                    if len(relationship_matches) > 1:
                        warnings.add(
                            "FormulaFence found duplicate workbook relationship ids for a "
                            "PivotTable cache; affected PivotTables have a coverage gap."
                        )
                        unrecognized_declaration_count += 1
                        continue
                    relationship = relationship_matches[0]
                    if relationship.relationship_type != _PIVOT_CACHE_DEFINITION_RELATIONSHIP:
                        warnings.add(
                            "FormulaFence found a PivotTable cache declaration with an "
                            "unexpected relationship type; affected PivotTables have a "
                            "coverage gap."
                        )
                        unrecognized_declaration_count += 1
                        continue
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        warnings.add(
                            "FormulaFence found a PivotTable cache declaration without a safe "
                            "internal target; affected PivotTables were not compared."
                        )
                        unrecognized_declaration_count += 1
                        continue
                    declaration_entries.append(
                        ("workbook-cache-definition", relationship.safe_target)
                    )
                    if cache_id is not None:
                        cache_definition_members_by_id[cache_id].add(
                            relationship.safe_target
                        )

            for relationship in workbook_relationships:
                if relationship.relationship_type != _PIVOT_CACHE_DEFINITION_RELATIONSHIP:
                    continue
                if relationship.relationship_id in declared_workbook_relationship_ids:
                    continue
                warnings.add(
                    "FormulaFence found a workbook PivotTable cache-definition relationship "
                    "not bound by a cache declaration; affected PivotTables have a coverage "
                    "gap."
                )
                unrecognized_declaration_count += 1
            for _cache_id, members in cache_definition_members_by_id.items():
                if len(members) <= 1:
                    continue
                warnings.add(
                    "FormulaFence found one PivotTable cache id bound to multiple cache "
                    "definitions; affected PivotTables have a coverage gap."
                )
                unrecognized_declaration_count += 1

            pivot_table_sources: dict[str, set[tuple[str, str]]] = defaultdict(set)
            unresolved_sheet_entries: list[tuple[str, str]] = []
            for sheet, (member, sheet_kind) in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                if sheet_kind != "worksheet":
                    continue
                relationships = _pivot_raw_relationships(
                    archive,
                    member,
                    warnings,
                    context="worksheet",
                )
                for relationship in relationships:
                    if relationship.relationship_type != _PIVOT_TABLE_RELATIONSHIP:
                        continue
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        warnings.add(
                            "FormulaFence found a worksheet PivotTable relationship without a "
                            "safe internal target; affected PivotTables were not compared."
                        )
                        unresolved_sheet_entries.append(
                            (member, repr(relationship.semantic_key()))
                        )
                        unrecognized_declaration_count += 1
                        continue
                    pivot_table_sources[relationship.safe_target].add((sheet, member))

            referenced_pivot_table_members = set(pivot_table_sources)
            for entry in archive.infolist():
                member = entry.filename
                if not _PIVOT_TABLE_PART_PATTERN.fullmatch(member):
                    continue
                pivot_table_sources.setdefault(member, set())
                if member in referenced_pivot_table_members:
                    continue
                warnings.add(
                    "FormulaFence found a PivotTable package part not declared by an "
                    "inspected worksheet; affected PivotTables have a coverage gap."
                )
                unrecognized_declaration_count += 1

            cache_members_by_id = {
                cache_id: tuple(sorted(members, key=str.casefold))
                for cache_id, members in cache_definition_members_by_id.items()
            }
            pivot_table_inspections: list[_PivotTablePartInspection] = []
            cache_definition_sources: dict[str, set[str]] = defaultdict(set)
            for _cache_id, members in cache_members_by_id.items():
                for member in members:
                    cache_definition_sources[member].add("workbook")
            for member in sorted(pivot_table_sources, key=str.casefold):
                sources = tuple(
                    sorted(pivot_table_sources[member], key=lambda item: item[0].casefold())
                )
                declaration_entries.append(("pivot-table-part", repr((member, sources))))
                inspection = _pivot_table_part_inspection(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                    cache_members_by_id,
                )
                pivot_table_inspections.append(inspection)
                for cache_member in inspection.cache_definition_members:
                    cache_definition_sources[cache_member].add(member)

            referenced_cache_definition_members = set(cache_definition_sources)
            for entry in archive.infolist():
                member = entry.filename
                if not _PIVOT_CACHE_DEFINITION_PART_PATTERN.fullmatch(member):
                    continue
                cache_definition_sources.setdefault(member, set())
                if member in referenced_cache_definition_members:
                    continue
                warnings.add(
                    "FormulaFence found a PivotTable cache-definition package part not bound "
                    "by an inspected declaration; affected PivotTables have a coverage gap."
                )
                unrecognized_declaration_count += 1

            cache_definition_inspections: list[_PivotCacheDefinitionInspection] = []
            cache_record_members: set[str] = set()
            for member in sorted(cache_definition_sources, key=str.casefold):
                sources = tuple(sorted(cache_definition_sources[member], key=str.casefold))
                declaration_entries.append(
                    ("pivot-cache-definition-part", repr((member, sources)))
                )
                inspection = _pivot_cache_definition_inspection(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                )
                cache_definition_inspections.append(inspection)
                cache_record_members.update(inspection.cache_record_members)

            referenced_cache_record_members = set(cache_record_members)
            for entry in archive.infolist():
                member = entry.filename
                if not _PIVOT_CACHE_RECORDS_PART_PATTERN.fullmatch(member):
                    continue
                cache_record_members.add(member)
                if member in referenced_cache_record_members:
                    continue
                warnings.add(
                    "FormulaFence found a PivotTable cache-record package part not bound by "
                    "an inspected cache definition; affected PivotTables have a coverage gap."
                )
                unrecognized_declaration_count += 1

            cache_record_payloads = _pivot_cache_record_payloads(
                archive,
                cache_record_members,
                [],
                warnings,
                record_budget,
            )

            workbook_cache_definition_members = {
                member
                for members in cache_members_by_id.values()
                for member in members
            }
            slicer_timeline_pivot_cache_members_by_id: dict[str, set[str]] = defaultdict(
                set
            )
            for inspection in cache_definition_inspections:
                if (
                    not inspection.inspected
                    or inspection.member not in workbook_cache_definition_members
                ):
                    continue
                for pivot_cache_id in inspection.slicer_timeline_cache_ids:
                    slicer_timeline_pivot_cache_members_by_id[pivot_cache_id].add(
                        inspection.member
                    )
            normalized_slicer_timeline_pivot_cache_members_by_id = tuple(
                (
                    pivot_cache_id,
                    tuple(sorted(members, key=str.casefold)),
                )
                for pivot_cache_id, members in sorted(
                    slicer_timeline_pivot_cache_members_by_id.items(),
                    key=lambda item: item[0],
                )
            )

            def aggregate_signature(
                inspections: list[object], attribute: str
            ) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            pivot_table_sheets = {
                sheet
                for member, sources in pivot_table_sources.items()
                if any(inspection.member == member for inspection in pivot_table_inspections)
                for sheet, _source_member in sources
            }
            declaration_entries.extend(
                ("unresolved-worksheet-pivot-relationship", entry)
                for entry in unresolved_sheet_entries
            )
            declaration_entries.sort()
            all_inspections: list[object] = [
                *pivot_table_inspections,
                *cache_definition_inspections,
            ]
            snapshot = PivotTableDefinitionSnapshot(
                pivot_table_sheet_count=len(pivot_table_sheets),
                pivot_table_part_count=len(pivot_table_sources),
                pivot_cache_definition_part_count=len(cache_definition_sources),
                pivot_cache_records_part_count=cache_record_payloads.record_part_count,
                pivot_cache_binding_count=sum(
                    len(inspection.cache_definition_members)
                    for inspection in pivot_table_inspections
                ),
                layout_location_count=sum(
                    inspection.layout_location_count for inspection in pivot_table_inspections
                ),
                pivot_field_count=sum(
                    inspection.pivot_field_count for inspection in pivot_table_inspections
                ),
                row_field_count=sum(
                    inspection.row_field_count for inspection in pivot_table_inspections
                ),
                column_field_count=sum(
                    inspection.column_field_count for inspection in pivot_table_inspections
                ),
                page_field_count=sum(
                    inspection.page_field_count for inspection in pivot_table_inspections
                ),
                data_field_count=sum(
                    inspection.data_field_count for inspection in pivot_table_inspections
                ),
                filter_count=sum(
                    inspection.filter_count for inspection in pivot_table_inspections
                ),
                row_item_count=sum(
                    inspection.row_item_count for inspection in pivot_table_inspections
                ),
                column_item_count=sum(
                    inspection.column_item_count for inspection in pivot_table_inspections
                ),
                cache_field_count=sum(
                    inspection.cache_field_count
                    for inspection in cache_definition_inspections
                ),
                shared_item_count=sum(
                    inspection.shared_item_count
                    for inspection in cache_definition_inspections
                ),
                calculated_item_count=sum(
                    inspection.calculated_item_count
                    for inspection in cache_definition_inspections
                ),
                calculated_member_count=sum(
                    inspection.calculated_member_count
                    for inspection in cache_definition_inspections
                ),
                cache_record_count=sum(
                    inspection.cache_record_count
                    for inspection in cache_definition_inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in all_inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in all_inspections
                ),
                fingerprinted_cache_record_part_count=(
                    cache_record_payloads.fingerprinted_part_count
                ),
                uninspected_cache_record_part_count=(
                    cache_record_payloads.uninspected_part_count
                ),
                unrecognized_part_count=(
                    unrecognized_declaration_count
                    + sum(inspection.unrecognized_count for inspection in all_inspections)
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                layout_signature=aggregate_signature(
                    list(pivot_table_inspections), "layout_signature"
                ),
                cache_definition_signature=aggregate_signature(
                    list(cache_definition_inspections), "definition_signature"
                ),
                cached_shared_item_signature=aggregate_signature(
                    list(cache_definition_inspections), "cached_shared_item_signature"
                ),
                relationship_signature=aggregate_signature(
                    all_inspections, "relationship_signature"
                ),
                cache_record_payload_signature=cache_record_payloads.payload_signature,
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _PivotTableMetadata(
            default,
            (
                "FormulaFence could not inspect PivotTable OOXML "
                f"({type(error).__name__}); affected PivotTables were not compared.",
            ),
        )
    return _PivotTableMetadata(
        snapshot,
        tuple(sorted(warnings)),
        normalized_slicer_timeline_pivot_cache_members_by_id,
    )


def _slicer_timeline_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_SlicerTimelineRawRelationship, ...]:
    """Read interactive-filter relationships without opening their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for slicer/Timeline inspection "
            f"({type(error).__name__}); affected filters were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting slicer/Timeline filters; "
            "affected filters were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_SlicerTimelineRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _SlicerTimelineRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting "
            "slicer/Timeline filters; affected filters may be incomplete."
        )
    return tuple(relationships)


def _slicer_timeline_relationship_signature(
    relationships: tuple[_SlicerTimelineRawRelationship, ...],
) -> str | None:
    """Fingerprint interactive-filter relationships without identifier churn."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _slicer_timeline_relationship_semantics(
    relationships: tuple[_SlicerTimelineRawRelationship, ...],
    warnings: set[str],
    *,
    context: str,
) -> dict[str, tuple[str, str, str]]:
    """Resolve relationship IDs into stable, private semantic targets."""
    relationships_by_id: dict[str, list[_SlicerTimelineRawRelationship]] = defaultdict(
        list
    )
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found a slicer/Timeline "
                f"{context} relationship without an id; affected filters have a coverage gap."
            )
    semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        values = sorted(match.semantic_key() for match in matches)
        if len(values) > 1:
            warnings.add(
                "FormulaFence found duplicate slicer/Timeline "
                f"{context} relationship ids; affected filters have a coverage gap."
            )
        semantics[relationship_id] = values[0]
    return semantics


def _slicer_timeline_boolean(value: str) -> str:
    """Normalize the two accepted OOXML spellings of a Boolean value."""
    if value.casefold() in {"1", "true"}:
        return "true"
    if value.casefold() in {"0", "false"}:
        return "false"
    return value


def _slicer_timeline_default_attributes(
    element: ElementTree.Element,
) -> tuple[tuple[str, str], ...]:
    """Return known default attributes that compatible writers may omit."""
    namespace = _xml_namespace(element.tag)
    local_name = _xml_local_name(element.tag)
    if (
        namespace == _OFFICE_2010_SPREADSHEET_NS
        and local_name in {"tabular", "tabularSlicerCache"}
    ):
        return (
            ("sortOrder", "ascending"),
            ("customListSort", "true"),
            ("showMissing", "true"),
            ("crossFilter", "showItemsWithDataAtTop"),
        )
    if namespace == _OFFICE_2013_SPREADSHEET_NS and local_name == "tableSlicerCache":
        return (
            ("sortOrder", "ascending"),
            ("customListSort", "true"),
            ("crossFilter", "showItemsWithDataAtTop"),
        )
    if namespace == _OFFICE_2010_SPREADSHEET_NS and local_name == "i":
        return (("s", "false"), ("nd", "false"))
    return ()


def _slicer_timeline_xml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    *,
    pivot_cache_members_by_id: Mapping[str, tuple[str, ...]],
) -> tuple[object, ...]:
    """Canonicalize private filter XML while resolving volatile link IDs."""
    local_name = _xml_local_name(element.tag)
    attribute_values: dict[str, str] = dict(element.attrib)
    present_attribute_names = {
        _xml_local_name(attribute) for attribute in attribute_values
    }
    for attribute_name, default_value in _slicer_timeline_default_attributes(element):
        if attribute_name not in present_attribute_names:
            attribute_values[attribute_name] = default_value

    attributes: list[tuple[str, str]] = []
    for attribute, value in attribute_values.items():
        attribute_name = _xml_local_name(attribute)
        if attribute in _SLICER_TIMELINE_RELATIONSHIP_ATTRIBUTES:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if attribute_name == "pivotCacheId":
            members = pivot_cache_members_by_id.get(value, ())
            resolved = (
                ("pivot-cache-definition", members[0])
                if len(members) == 1
                else ("missing-pivot-cache", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if attribute_name in {"customListSort", "showMissing", "s", "nd"}:
            value = _slicer_timeline_boolean(value)
        if local_name == "timelineCacheDefinition" and attribute_name == "uid":
            value = _normalise_guid(value)
        attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _slicer_timeline_xml_fragment(
            child,
            relationship_semantics,
            pivot_cache_members_by_id=pivot_cache_members_by_id,
        )
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _slicer_timeline_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _SlicerTimelineXmlBudget,
) -> str | None:
    """Stream filter-cache XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _SLICER_TIMELINE_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read a slicer/Timeline XML part whose XML "
        "structure exceeds the safety budget; affected filters have a coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _slicer_timeline_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _SlicerTimelineXmlBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded slicer or Timeline XML part without following targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded slicer/Timeline XML part count budget; "
            "affected filters have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a slicer/Timeline XML package part; affected "
            "filters were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _SLICER_TIMELINE_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized slicer/Timeline XML part; "
            "affected filters have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded slicer/Timeline XML read budget; affected "
            "filters have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = (
        _slicer_timeline_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            warnings,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a slicer/Timeline XML package part "
            f"({type(error).__name__}); affected filters were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _slicer_timeline_relationship_kind(relationship_type: str) -> str | None:
    """Return the filter-cache kind represented by a workbook relationship."""
    if relationship_type.casefold() == _SLICER_CACHE_RELATIONSHIP.casefold():
        return "slicer"
    if relationship_type.casefold() in {
        candidate.casefold() for candidate in _TIMELINE_CACHE_RELATIONSHIPS
    }:
        return "timeline"
    return None


def _slicer_timeline_cache_inspection(
    archive: ZipFile,
    member: str,
    kind: str,
    warnings: set[str],
    xml_budget: _SlicerTimelineXmlBudget,
    pivot_cache_members_by_id: Mapping[str, tuple[str, ...]],
) -> _SlicerTimelineCacheInspection:
    """Inspect one cache definition without evaluating its active filter."""
    relationships = _slicer_timeline_raw_relationships(
        archive,
        member,
        warnings,
        context=f"{kind} cache",
    )
    relationship_semantics = _slicer_timeline_relationship_semantics(
        relationships,
        warnings,
        context=f"{kind} cache",
    )
    payload, fallback_signature = _slicer_timeline_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _SlicerTimelineCacheInspection(
            member=member,
            kind=kind,
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_slicer_timeline_relationship_signature(relationships),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a slicer/Timeline cache XML part "
            f"({type(error).__name__}); affected filters were not compared."
        )
        return _SlicerTimelineCacheInspection(
            member=member,
            kind=kind,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_slicer_timeline_relationship_signature(relationships),
        )

    expected_namespace = (
        _OFFICE_2010_SPREADSHEET_NS
        if kind == "slicer"
        else _OFFICE_2013_SPREADSHEET_NS
    )
    expected_root = "slicerCacheDefinition" if kind == "slicer" else "timelineCacheDefinition"
    if (
        _xml_local_name(root.tag) != expected_root
        or _xml_namespace(root.tag) != expected_namespace
    ):
        warnings.add(
            "FormulaFence found a slicer/Timeline cache part with an unexpected root; "
            "affected filters were not compared."
        )
        return _SlicerTimelineCacheInspection(
            member=member,
            kind=kind,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_slicer_timeline_relationship_signature(relationships),
        )

    unrecognized_count = 0
    if relationships:
        warnings.add(
            "FormulaFence found direct relationships on a slicer/Timeline cache part; "
            "affected filters have a coverage gap."
        )
        unrecognized_count += len(relationships)

    pivot_cache_binding_count = 0
    table_binding_count = 0
    pivot_table_binding_count = 0
    slicer_item_count = 0
    selected_slicer_item_count = 0
    timeline_state_count = 0
    timeline_filter_count = 0
    elements = tuple(root.iter())
    if kind == "slicer":
        pivot_cache_elements = tuple(
            element
            for element in elements
            if _xml_namespace(element.tag) == _OFFICE_2010_SPREADSHEET_NS
            and _xml_local_name(element.tag)
            in {"tabular", "olap", "tabularSlicerCache", "olapSlicerCache"}
        )
        table_elements = tuple(
            element
            for element in elements
            if _xml_namespace(element.tag) == _OFFICE_2013_SPREADSHEET_NS
            and _xml_local_name(element.tag) == "tableSlicerCache"
        )
        pivot_cache_binding_count = len(pivot_cache_elements)
        table_binding_count = len(table_elements)
        pivot_table_binding_count = sum(
            _xml_namespace(element.tag) == _OFFICE_2010_SPREADSHEET_NS
            and _xml_local_name(element.tag) == "pivotTable"
            for element in elements
        )
        slicer_items = tuple(
            element
            for element in elements
            if _xml_namespace(element.tag) == _OFFICE_2010_SPREADSHEET_NS
            and _xml_local_name(element.tag) == "i"
        )
        slicer_item_count = len(slicer_items)
        selected_slicer_item_count = sum(
            _slicer_timeline_boolean(element.get("s", "false")) == "true"
            for element in slicer_items
        )
        for element in pivot_cache_elements:
            pivot_cache_id = element.get("pivotCacheId")
            if pivot_cache_id is None:
                warnings.add(
                    "FormulaFence found a slicer cache without a PivotTable cache id; "
                    "affected filters have a coverage gap."
                )
                unrecognized_count += 1
            elif len(pivot_cache_members_by_id.get(pivot_cache_id, ())) != 1:
                warnings.add(
                    "FormulaFence could not bind a slicer cache to one PivotTable cache "
                    "definition; affected filters have a coverage gap."
                )
                unrecognized_count += 1
        for element in table_elements:
            if element.get("tableId") is None or element.get("column") is None:
                warnings.add(
                    "FormulaFence found a table slicer cache without a complete table binding; "
                    "affected filters have a coverage gap."
                )
                unrecognized_count += 1
    else:
        state_elements = tuple(
            element
            for element in elements
            if _xml_namespace(element.tag) == _OFFICE_2013_SPREADSHEET_NS
            and _xml_local_name(element.tag) == "state"
        )
        timeline_state_count = len(state_elements)
        timeline_filter_count = sum(
            _xml_namespace(element.tag) == _OFFICE_2013_SPREADSHEET_NS
            and _xml_local_name(element.tag) == "timelinePivotFilter"
            for element in elements
        )
        pivot_table_binding_count = sum(
            _xml_namespace(element.tag) == _OFFICE_2013_SPREADSHEET_NS
            and _xml_local_name(element.tag) == "pivotTable"
            for element in elements
        )
        pivot_cache_binding_count = len(state_elements)
        if not state_elements:
            warnings.add(
                "FormulaFence found a Timeline cache without state material; affected "
                "filters have a coverage gap."
            )
            unrecognized_count += 1
        for element in state_elements:
            pivot_cache_id = element.get("pivotCacheId")
            if pivot_cache_id is None:
                warnings.add(
                    "FormulaFence found a Timeline cache state without a PivotTable cache "
                    "id; affected filters have a coverage gap."
                )
                unrecognized_count += 1
            elif len(pivot_cache_members_by_id.get(pivot_cache_id, ())) != 1:
                warnings.add(
                    "FormulaFence could not bind a Timeline cache to one PivotTable cache "
                    "definition; affected filters have a coverage gap."
                )
                unrecognized_count += 1

    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    f"{kind}-cache",
                    repr(
                        _slicer_timeline_xml_fragment(
                            root,
                            relationship_semantics,
                            pivot_cache_members_by_id=pivot_cache_members_by_id,
                        )
                    ),
                ),
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested slicer/Timeline "
            "cache definition; affected filters were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _SlicerTimelineCacheInspection(
        member=member,
        kind=kind,
        pivot_cache_binding_count=pivot_cache_binding_count,
        table_binding_count=table_binding_count,
        pivot_table_binding_count=pivot_table_binding_count,
        slicer_item_count=slicer_item_count,
        selected_slicer_item_count=selected_slicer_item_count,
        timeline_state_count=timeline_state_count,
        timeline_filter_count=timeline_filter_count,
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_slicer_timeline_relationship_signature(relationships),
    )


def _slicer_timeline_metadata(
    path: Path,
    pivot_cache_members_by_id: Mapping[str, tuple[str, ...]],
) -> _SlicerTimelineMetadata:
    """Inspect slicer and Timeline caches before a workbook reader omits them.

    The scan is package-only: it neither applies a filter nor evaluates a
    PivotTable. It follows only workbook relationships to bounded cache XML and
    records private structural fingerprints for review.
    """
    warnings: set[str] = set()
    default = SlicerTimelineCacheSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                workbook_root = _xml_root(archive, "xl/workbook.xml")
            except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                return _SlicerTimelineMetadata(
                    default,
                    (
                        "FormulaFence could not map workbook OOXML for slicer/Timeline "
                        f"inspection ({type(error).__name__}); affected filters were not compared.",
                    ),
                )

            workbook_relationships = _slicer_timeline_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
            )
            relationships_by_id: dict[
                str, list[_SlicerTimelineRawRelationship]
            ] = defaultdict(list)
            for relationship in workbook_relationships:
                if relationship.relationship_id:
                    relationships_by_id[relationship.relationship_id].append(relationship)

            normalized_pivot_cache_members_by_id = {
                cache_id: tuple(sorted(members, key=str.casefold))
                for cache_id, members in pivot_cache_members_by_id.items()
            }

            declarations: list[tuple[str, str | None]] = []
            for element in workbook_root.iter():
                if (
                    _xml_namespace(element.tag)
                    in {_OFFICE_2010_SPREADSHEET_NS, _OFFICE_2013_SPREADSHEET_NS}
                    and _xml_local_name(element.tag) == "slicerCache"
                ):
                    declarations.append(
                        ("slicer", element.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"))
                    )
                elif (
                    _xml_namespace(element.tag) == _OFFICE_2013_SPREADSHEET_NS
                    and _xml_local_name(element.tag) == "timelineCacheRef"
                ):
                    declarations.append(
                        ("timeline", element.get(f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"))
                    )

            declaration_entries: list[tuple[str, str]] = []
            declared_relationship_ids: set[str] = set()
            slicer_members: set[str] = set()
            timeline_members: set[str] = set()
            slicer_workbook_binding_count = 0
            timeline_workbook_binding_count = 0
            unrecognized_declaration_count = 0
            for kind, relationship_id in declarations:
                if relationship_id is None:
                    warnings.add(
                        "FormulaFence found a slicer/Timeline workbook declaration without a "
                        "relationship; affected filters have a coverage gap."
                    )
                    declaration_entries.append((f"missing-{kind}-binding", ""))
                    unrecognized_declaration_count += 1
                    continue
                declared_relationship_ids.add(relationship_id)
                matches = relationships_by_id.get(relationship_id, ())
                if len(matches) != 1:
                    warnings.add(
                        "FormulaFence could not resolve one slicer/Timeline workbook "
                        "declaration to exactly one relationship; affected filters have a "
                        "coverage gap."
                    )
                    declaration_entries.append(
                        (f"unresolved-{kind}-binding", relationship_id)
                    )
                    unrecognized_declaration_count += 1
                    continue
                relationship = matches[0]
                actual_kind = _slicer_timeline_relationship_kind(
                    relationship.relationship_type
                )
                if actual_kind != kind:
                    warnings.add(
                        "FormulaFence found a slicer/Timeline workbook declaration with an "
                        "unexpected relationship type; affected filters have a coverage gap."
                    )
                    declaration_entries.append(
                        (
                            f"invalid-{kind}-binding",
                            repr(relationship.semantic_key()),
                        )
                    )
                    unrecognized_declaration_count += 1
                    continue
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.safe_target is None
                ):
                    warnings.add(
                        "FormulaFence found a slicer/Timeline workbook declaration without a "
                        "safe internal target; affected filters were not compared."
                    )
                    declaration_entries.append(
                        (
                            f"external-{kind}-binding",
                            repr(relationship.semantic_key()),
                        )
                    )
                    unrecognized_declaration_count += 1
                    continue
                declaration_entries.append((f"{kind}-cache-part", relationship.safe_target))
                if kind == "slicer":
                    slicer_members.add(relationship.safe_target)
                    slicer_workbook_binding_count += 1
                else:
                    timeline_members.add(relationship.safe_target)
                    timeline_workbook_binding_count += 1

            for relationship in workbook_relationships:
                kind = _slicer_timeline_relationship_kind(relationship.relationship_type)
                if kind is None or relationship.relationship_id in declared_relationship_ids:
                    continue
                warnings.add(
                    "FormulaFence found a slicer/Timeline workbook relationship not bound "
                    "by a cache declaration; affected filters have a coverage gap."
                )
                declaration_entries.append(
                    (f"unbound-{kind}-workbook-relationship", repr(relationship.semantic_key()))
                )
                unrecognized_declaration_count += 1

            referenced_slicer_members = set(slicer_members)
            referenced_timeline_members = set(timeline_members)
            for entry in archive.infolist():
                member = entry.filename
                if _SLICER_CACHE_PART_PATTERN.fullmatch(member):
                    slicer_members.add(member)
                    if member not in referenced_slicer_members:
                        warnings.add(
                            "FormulaFence found a slicer cache package part not bound by an "
                            "inspected workbook declaration; affected filters have a coverage gap."
                        )
                        declaration_entries.append(("orphan-slicer-cache-part", member))
                        unrecognized_declaration_count += 1
                elif _TIMELINE_CACHE_PART_PATTERN.fullmatch(member):
                    timeline_members.add(member)
                    if member not in referenced_timeline_members:
                        warnings.add(
                            "FormulaFence found a Timeline cache package part not bound by an "
                            "inspected workbook declaration; affected filters have a coverage gap."
                        )
                        declaration_entries.append(("orphan-timeline-cache-part", member))
                        unrecognized_declaration_count += 1

            xml_budget = _SlicerTimelineXmlBudget()
            inspections: list[_SlicerTimelineCacheInspection] = []
            for kind, members in (
                ("slicer", slicer_members),
                ("timeline", timeline_members),
            ):
                for member in sorted(members, key=str.casefold):
                    inspections.append(
                        _slicer_timeline_cache_inspection(
                            archive,
                            member,
                            kind,
                            warnings,
                            xml_budget,
                            normalized_pivot_cache_members_by_id,
                        )
                    )

            def aggregate_signature(
                selected: list[_SlicerTimelineCacheInspection],
                attribute: str,
            ) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in selected
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            slicer_inspections = [
                inspection for inspection in inspections if inspection.kind == "slicer"
            ]
            timeline_inspections = [
                inspection for inspection in inspections if inspection.kind == "timeline"
            ]
            declaration_entries.sort()
            snapshot = SlicerTimelineCacheSnapshot(
                slicer_cache_part_count=len(slicer_members),
                timeline_cache_part_count=len(timeline_members),
                slicer_workbook_binding_count=slicer_workbook_binding_count,
                timeline_workbook_binding_count=timeline_workbook_binding_count,
                slicer_pivot_cache_binding_count=sum(
                    inspection.pivot_cache_binding_count
                    for inspection in slicer_inspections
                ),
                slicer_table_binding_count=sum(
                    inspection.table_binding_count for inspection in slicer_inspections
                ),
                timeline_pivot_cache_binding_count=sum(
                    inspection.pivot_cache_binding_count
                    for inspection in timeline_inspections
                ),
                slicer_pivot_table_binding_count=sum(
                    inspection.pivot_table_binding_count
                    for inspection in slicer_inspections
                ),
                timeline_pivot_table_binding_count=sum(
                    inspection.pivot_table_binding_count
                    for inspection in timeline_inspections
                ),
                slicer_item_count=sum(
                    inspection.slicer_item_count for inspection in slicer_inspections
                ),
                selected_slicer_item_count=sum(
                    inspection.selected_slicer_item_count
                    for inspection in slicer_inspections
                ),
                timeline_state_count=sum(
                    inspection.timeline_state_count
                    for inspection in timeline_inspections
                ),
                timeline_filter_count=sum(
                    inspection.timeline_filter_count
                    for inspection in timeline_inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in inspections
                ),
                unrecognized_part_count=(
                    unrecognized_declaration_count
                    + sum(inspection.unrecognized_count for inspection in inspections)
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                slicer_definition_signature=aggregate_signature(
                    slicer_inspections, "definition_signature"
                ),
                timeline_definition_signature=aggregate_signature(
                    timeline_inspections, "definition_signature"
                ),
                relationship_signature=aggregate_signature(
                    inspections, "relationship_signature"
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _SlicerTimelineMetadata(
            default,
            (
                "FormulaFence could not inspect slicer/Timeline cache OOXML "
                f"({type(error).__name__}); affected filters were not compared.",
            ),
        )
    return _SlicerTimelineMetadata(snapshot, tuple(sorted(warnings)))


def _power_pivot_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_PowerPivotRawRelationship, ...]:
    """Read Power Pivot/Data Model relationships without opening their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for Power Pivot/Data Model inspection "
            f"({type(error).__name__}); affected models were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting a Power Pivot/Data Model; "
            "affected models were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_PowerPivotRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _PowerPivotRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting a Power "
            "Pivot/Data Model; affected models may be incomplete."
        )
    return tuple(relationships)


def _power_pivot_relationship_signature(
    relationships: tuple[_PowerPivotRawRelationship, ...],
) -> str | None:
    """Fingerprint Data Model relationship semantics without arbitrary IDs."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _power_pivot_data_model_fragment(
    element: ElementTree.Element,
) -> tuple[object, ...]:
    """Canonicalize private x15 Data Model metadata without leaking it.

    Model-table identifiers commonly carry writer-generated GUIDs. They do not
    identify the table relationship described by the extension, so normalizing
    the GUID component avoids a noisy rewrite while retaining the surrounding
    table, connection, column, and relationship material in the private hash.
    """
    attributes = tuple(
        sorted(
            (
                _xml_display_name(attribute),
                _normalise_guid(value),
            )
            for attribute, value in element.attrib.items()
        )
    )
    children = tuple(_power_pivot_data_model_fragment(child) for child in element)
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    if text is not None:
        text = _normalise_guid(text)
    return (
        _xml_display_name(element.tag),
        attributes,
        text,
        children,
    )


def _power_pivot_data_payloads(
    archive: ZipFile,
    members: set[str],
    unresolved_entries: list[tuple[str, str]],
    warnings: set[str],
    budget: _PowerPivotDataBudget,
) -> _PowerPivotDataPayloadInspection:
    """Fingerprint bounded raw Data Model payloads without parsing DAX or data."""
    entries = list(unresolved_entries)
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts == 0:
            warnings.add(
                "FormulaFence reached its bounded Power Pivot/Data Model part count "
                "budget; affected models have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate a Power Pivot/Data Model package part; "
                "affected models were not compared."
            )
            entries.append(("missing-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _POWER_PIVOT_DATA_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized Power Pivot/Data Model "
                "part; affected models have a coverage gap."
            )
            entries.append(("oversized-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded Power Pivot/Data Model read budget; "
                "affected models have a coverage gap."
            )
            entries.append(("read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as payload:
                while chunk := payload.read(_POWER_PIVOT_DATA_HASH_CHUNK_BYTES):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("payload exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("payload did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint a Power Pivot/Data Model part "
                f"({type(error).__name__}); affected models were not compared."
            )
            entries.append(("unreadable-part", metadata))
            uninspected_part_count += 1
            continue
        entries.append(("payload", repr((member, digest.hexdigest()))))
        fingerprinted_part_count += 1

    entries.sort()
    return _PowerPivotDataPayloadInspection(
        data_part_count=len(members),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_signature=_private_external_data_signature(tuple(entries)),
    )


def _power_pivot_data_model_metadata(path: Path) -> _PowerPivotDataModelMetadata:
    """Inspect an embedded Power Pivot/Data Model without loading its contents.

    The binary Data Model is an Analysis Services payload. FormulaFence does
    not deserialize it, evaluate DAX, refresh it, or expose any stored data;
    it follows only its workbook relationship and hashes bounded raw bytes.
    """
    warnings: set[str] = set()
    default = PowerPivotDataModelSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                workbook_root = _xml_root(archive, "xl/workbook.xml")
            except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                return _PowerPivotDataModelMetadata(
                    default,
                    (
                        "FormulaFence could not map workbook OOXML for Power Pivot/Data "
                        f"Model inspection ({type(error).__name__}); affected models were "
                        "not compared.",
                    ),
                )

            workbook_relationships = _power_pivot_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
            )
            power_pivot_relationships = tuple(
                relationship
                for relationship in workbook_relationships
                if relationship.relationship_type.casefold()
                == _POWER_PIVOT_DATA_RELATIONSHIP.casefold()
            )
            data_model_elements = tuple(
                element
                for element in workbook_root.iter()
                if _xml_namespace(element.tag) == _OFFICE_2013_SPREADSHEET_NS
                and _xml_local_name(element.tag) == "dataModel"
            )

            declaration_entries: list[tuple[str, str]] = []
            data_model_members: set[str] = set()
            unresolved_payload_entries: list[tuple[str, str]] = []
            workbook_binding_count = 0
            external_relationship_count = 0
            unrecognized_part_count = 0
            for relationship in power_pivot_relationships:
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.safe_target is None
                ):
                    warnings.add(
                        "FormulaFence found a Power Pivot/Data Model workbook binding "
                        "without a safe internal target; affected models were not compared."
                    )
                    declaration_entries.append(
                        ("external-workbook-binding", repr(relationship.semantic_key()))
                    )
                    unresolved_payload_entries.append(
                        ("external-workbook-binding", repr(relationship.semantic_key()))
                    )
                    external_relationship_count += int(
                        relationship.target_mode.casefold() != "internal"
                    )
                    unrecognized_part_count += 1
                    continue
                declaration_entries.append(
                    ("data-model-part", relationship.safe_target)
                )
                if not _POWER_PIVOT_DATA_PART_PATTERN.fullmatch(
                    relationship.safe_target
                ):
                    warnings.add(
                        "FormulaFence found a Power Pivot/Data Model workbook binding to "
                        "an unexpected package part; affected models have a coverage gap."
                    )
                    unrecognized_part_count += 1
                data_model_members.add(relationship.safe_target)
                workbook_binding_count += 1

            if data_model_elements and not power_pivot_relationships:
                warnings.add(
                    "FormulaFence found Power Pivot/Data Model workbook metadata without "
                    "a Power Pivot data relationship; affected models have a coverage gap."
                )
                unrecognized_part_count += len(data_model_elements)

            model_table_count = 0
            model_relationship_count = 0
            for index, element in enumerate(data_model_elements):
                model_table_count += sum(
                    _xml_namespace(child.tag) == _OFFICE_2013_SPREADSHEET_NS
                    and _xml_local_name(child.tag) == "modelTable"
                    for child in element.iter()
                )
                model_relationship_count += sum(
                    _xml_namespace(child.tag) == _OFFICE_2013_SPREADSHEET_NS
                    and _xml_local_name(child.tag) == "modelRelationship"
                    for child in element.iter()
                )
                try:
                    fragment = repr(_power_pivot_data_model_fragment(element))
                except RecursionError:
                    warnings.add(
                        "FormulaFence could not fully traverse an excessively nested Power "
                        "Pivot/Data Model declaration; affected models were not compared."
                    )
                    fragment = _private_payload_signature(
                        ElementTree.tostring(element, encoding="utf-8")
                    )
                    unrecognized_part_count += 1
                declaration_entries.append((f"data-model-declaration:{index}", fragment))

            referenced_members = set(data_model_members)
            for entry in archive.infolist():
                member = entry.filename
                if _POWER_PIVOT_DATA_PART_PATTERN.fullmatch(member):
                    data_model_members.add(member)
                    if member not in referenced_members:
                        warnings.add(
                            "FormulaFence found a Power Pivot/Data Model package part not "
                            "bound by an inspected workbook relationship; affected models "
                            "have a coverage gap."
                        )
                        declaration_entries.append(("orphan-data-model-part", member))
                        unrecognized_part_count += 1
                elif (
                    member.startswith("xl/model/")
                    and not member.startswith("xl/model/_rels/")
                    and not member.endswith("/")
                ):
                    warnings.add(
                        "FormulaFence found an unrecognized Power Pivot/Data Model package "
                        "part; affected models have a coverage gap."
                    )
                    declaration_entries.append(("unrecognized-data-model-part", member))
                    unrecognized_part_count += 1

            payload_inspection = _power_pivot_data_payloads(
                archive,
                data_model_members,
                unresolved_payload_entries,
                warnings,
                _PowerPivotDataBudget(),
            )
            relationship_entries: list[tuple[str, str]] = []
            related_relationship_count = 0
            for member in sorted(data_model_members, key=str.casefold):
                relationships = _power_pivot_raw_relationships(
                    archive,
                    member,
                    warnings,
                    context="Power Pivot/Data Model package part",
                )
                if not relationships:
                    continue
                warnings.add(
                    "FormulaFence found direct relationships on a Power Pivot/Data Model "
                    "package part; affected models have a coverage gap."
                )
                related_relationship_count += len(relationships)
                external_relationship_count += sum(
                    relationship.target_mode.casefold() != "internal"
                    for relationship in relationships
                )
                unrecognized_part_count += len(relationships)
                if signature := _power_pivot_relationship_signature(relationships):
                    relationship_entries.append((member, signature))

            declaration_entries.sort()
            relationship_entries.sort()
            snapshot = PowerPivotDataModelSnapshot(
                data_model_part_count=len(data_model_members),
                workbook_binding_count=workbook_binding_count,
                data_model_declaration_count=len(data_model_elements),
                model_table_count=model_table_count,
                model_relationship_count=model_relationship_count,
                related_relationship_count=related_relationship_count,
                external_relationship_count=external_relationship_count,
                fingerprinted_data_part_count=payload_inspection.fingerprinted_part_count,
                uninspected_data_part_count=payload_inspection.uninspected_part_count,
                unrecognized_part_count=unrecognized_part_count,
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                relationship_signature=_private_external_data_signature(
                    tuple(relationship_entries)
                ),
                payload_signature=payload_inspection.payload_signature,
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _PowerPivotDataModelMetadata(
            default,
            (
                "FormulaFence could not inspect Power Pivot/Data Model OOXML "
                f"({type(error).__name__}); affected models were not compared.",
            ),
        )
    return _PowerPivotDataModelMetadata(snapshot, tuple(sorted(warnings)))


def _pivot_reader_cache_record_replacements(
    path: Path,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep raw PivotTable packages out of the ordinary workbook reader.

    FormulaFence captures PivotTable view, cache-definition, and cache-record
    evidence through its bounded raw scanner before loading cells. The ordinary
    reader has no cell-audit need for those package graphs, but eagerly parses
    every bound cache and view. Remove only their workbook and worksheet
    bindings in its temporary copy so raw coverage remains authoritative.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            workbook = _xml_root(archive, "xl/workbook.xml")
            pivot_cache_containers = [
                child
                for child in workbook
                if (
                    _xml_local_name(child.tag) == "pivotCaches"
                    and _xml_namespace(child.tag)
                    in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                )
            ]
            if pivot_cache_containers:
                for container in pivot_cache_containers:
                    workbook.remove(container)
                replacements["xl/workbook.xml"] = ElementTree.tostring(
                    workbook,
                    encoding="utf-8",
                    xml_declaration=True,
                )

            relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
            workbook_relationship_member = _relationship_part_path("xl/workbook.xml")
            try:
                workbook_relationships = _xml_root(archive, workbook_relationship_member)
            except KeyError:
                workbook_relationships = None
            if (
                workbook_relationships is not None
                and _xml_local_name(workbook_relationships.tag) == "Relationships"
                and _xml_namespace(workbook_relationships.tag) == _PACKAGE_RELATIONSHIP_NS
            ):
                cache_relationships = [
                    relationship
                    for relationship in workbook_relationships.findall(relationship_tag)
                    if relationship.get("Type") == _PIVOT_CACHE_DEFINITION_RELATIONSHIP
                ]
                if cache_relationships:
                    for relationship in cache_relationships:
                        workbook_relationships.remove(relationship)
                    replacements[workbook_relationship_member] = ElementTree.tostring(
                        workbook_relationships,
                        encoding="utf-8",
                        xml_declaration=True,
                    )

            for _sheet, (member, sheet_kind) in _sheet_xml_parts(archive).items():
                if sheet_kind != "worksheet":
                    continue
                relationship_member = _relationship_part_path(member)
                try:
                    relationships = _xml_root(archive, relationship_member)
                except KeyError:
                    continue
                if (
                    _xml_local_name(relationships.tag) != "Relationships"
                    or _xml_namespace(relationships.tag) != _PACKAGE_RELATIONSHIP_NS
                ):
                    continue
                pivot_relationships = [
                    relationship
                    for relationship in relationships.findall(relationship_tag)
                    if relationship.get("Type") == _PIVOT_TABLE_RELATIONSHIP
                ]
                if not pivot_relationships:
                    continue
                for relationship in pivot_relationships:
                    relationships.remove(relationship)
                replacements[relationship_member] = ElementTree.tostring(
                    relationships,
                    encoding="utf-8",
                    xml_declaration=True,
                )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        reader_warnings.add(
            "FormulaFence could not prepare a PivotTable-safe workbook reader copy "
            f"({type(error).__name__})."
        )
    return replacements, tuple(sorted(reader_warnings))


def _legacy_note_reader_relationship_replacements(
    path: Path,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep legacy Note markup out of the ordinary workbook reader.

    FormulaFence has already inspected the original package through its bounded
    raw scanner. The ordinary workbook reader is only needed for cells, and its
    legacy-comment parser can differ in tolerance across writer versions. Unsafe
    external or absent VML targets are additionally removed before it follows
    them.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            sheet_parts = _sheet_xml_parts(archive)
            relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
            relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
            legacy_drawing_tag = f"{{{_SPREADSHEETML_NS}}}legacyDrawing"
            archive_members = set(archive.namelist())
            for _sheet, (member, sheet_kind) in sheet_parts.items():
                if sheet_kind != "worksheet":
                    continue
                relationship_member = _relationship_part_path(member)
                try:
                    relationships = _xml_root(archive, relationship_member)
                except KeyError:
                    continue
                if (
                    _xml_namespace(relationships.tag) != _PACKAGE_RELATIONSHIP_NS
                    or _xml_local_name(relationships.tag) != "Relationships"
                ):
                    continue

                unsafe_vml_identifiers: set[str] = set()
                removed = False
                isolated_unsafe_target = False
                for relationship in list(relationships.findall(relationship_tag)):
                    relationship_type = relationship.get("Type", "")
                    relationship_type_key = relationship_type.casefold()
                    if relationship_type_key not in {
                        _LEGACY_COMMENT_RELATIONSHIP.casefold(),
                        _LEGACY_VML_RELATIONSHIP.casefold(),
                    }:
                        continue
                    target = relationship.get("Target")
                    target_mode = relationship.get("TargetMode", "Internal")
                    safe_target = (
                        _normalise_part_target(member, target)
                        if target is not None and target_mode.casefold() == "internal"
                        else None
                    )
                    target_is_safe = (
                        safe_target is not None and safe_target in archive_members
                    )
                    if relationship_type_key == _LEGACY_COMMENT_RELATIONSHIP.casefold():
                        # FormulaFence has already captured Notes from raw OOXML.
                        # Keep openpyxl from reparsing comment markup, whose
                        # permissiveness differs across writer versions.
                        relationships.remove(relationship)
                        removed = True
                        isolated_unsafe_target = (
                            isolated_unsafe_target or not target_is_safe
                        )
                        continue
                    if target_is_safe:
                        continue
                    relationship_id = relationship.get("Id")
                    if (
                        relationship_type_key == _LEGACY_VML_RELATIONSHIP.casefold()
                        and relationship_id
                    ):
                        unsafe_vml_identifiers.add(relationship_id)
                    relationships.remove(relationship)
                    removed = True
                    isolated_unsafe_target = True

                if removed:
                    replacements[relationship_member] = ElementTree.tostring(
                        relationships,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
                    if isolated_unsafe_target:
                        reader_warnings.add(
                            "FormulaFence isolated unsafe legacy Excel Note relationships "
                            "before the underlying workbook reader ran; raw Note metadata "
                            "remains fail-closed."
                        )
                if not unsafe_vml_identifiers:
                    continue
                try:
                    worksheet = _xml_root(archive, member)
                except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError):
                    continue
                parent_by_child = {
                    child: parent
                    for parent in worksheet.iter()
                    for child in parent
                }
                changed_worksheet = False
                for legacy_drawing in list(worksheet.iter(legacy_drawing_tag)):
                    if legacy_drawing.get(relationship_attribute) not in unsafe_vml_identifiers:
                        continue
                    parent = parent_by_child.get(legacy_drawing)
                    if parent is not None:
                        parent.remove(legacy_drawing)
                        changed_worksheet = True
                if changed_worksheet:
                    replacements[member] = ElementTree.tostring(
                        worksheet,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate unsafe legacy Excel Note relationships "
            f"before the underlying workbook reader ran ({type(error).__name__})."
        )
    return replacements, tuple(sorted(reader_warnings))


def _threaded_comment_reader_relationship_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep modern-comment package bindings out of the ordinary workbook reader.

    FormulaFence has already inspected the original threaded-comment and person
    XML through its bounded raw scanner. The ordinary reader only needs cells
    and workbook structure, so remove these optional package bindings from its
    temporary copy. This prevents a future reader implementation from
    materializing a raw comment tree that the bounded scanner rejected.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            sheet_parts = _sheet_xml_parts(archive)
            relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
            source_relationship_types = {
                "xl/workbook.xml": _THREADED_COMMENT_PERSON_RELATIONSHIP.casefold(),
            }
            source_relationship_types.update(
                {
                    member: _THREADED_COMMENT_RELATIONSHIP.casefold()
                    for _sheet, (member, sheet_kind) in sheet_parts.items()
                    if sheet_kind == "worksheet"
                }
            )
            for member, relationship_type in source_relationship_types.items():
                relationship_member = _relationship_part_path(member)
                try:
                    payload = prior_replacements.get(relationship_member)
                    relationships = (
                        _xml_root_from_payload(payload)
                        if payload is not None
                        else _xml_root(archive, relationship_member)
                    )
                except KeyError:
                    continue
                if (
                    _xml_namespace(relationships.tag) != _PACKAGE_RELATIONSHIP_NS
                    or _xml_local_name(relationships.tag) != "Relationships"
                ):
                    continue
                removed = False
                for relationship in list(relationships.findall(relationship_tag)):
                    if relationship.get("Type", "").casefold() != relationship_type:
                        continue
                    relationships.remove(relationship)
                    removed = True
                if removed:
                    replacements[relationship_member] = ElementTree.tostring(
                        relationships,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate threaded-comment relationships before the "
            f"underlying workbook reader ran ({type(error).__name__})."
        )
    return replacements, tuple(sorted(reader_warnings))


def _cell_hyperlink_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep raw cell-hyperlink markup out of the ordinary workbook reader.

    FormulaFence records hyperlinks from the original package before this
    temporary reader copy is made. Removing the declarations here prevents a
    malformed link reference or relationship from making an otherwise
    reviewable workbook unloadable through the underlying workbook library.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            sheet_parts = _sheet_xml_parts(archive)
            relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
            hyperlink_container_tag = f"{{{_SPREADSHEETML_NS}}}hyperlinks"
            standard_hyperlink_tag = f"{{{_SPREADSHEETML_NS}}}hyperlink"
            revision_hyperlink_tag = f"{{{_OFFICE_2014_REVISION_NS}}}hyperlink"
            for _sheet, (member, sheet_kind) in sheet_parts.items():
                if sheet_kind != "worksheet":
                    continue
                try:
                    worksheet = reader_xml_root(member)
                except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError):
                    continue
                if (
                    _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    continue
                changed_worksheet = False
                for container in list(worksheet.findall(hyperlink_container_tag)):
                    worksheet.remove(container)
                    changed_worksheet = True
                parent_by_child = {
                    child: parent
                    for parent in worksheet.iter()
                    for child in parent
                }
                for hyperlink in list(worksheet.iter(standard_hyperlink_tag)):
                    parent = parent_by_child.get(hyperlink)
                    if parent is not None:
                        parent.remove(hyperlink)
                        changed_worksheet = True
                for hyperlink in list(worksheet.iter(revision_hyperlink_tag)):
                    parent = parent_by_child.get(hyperlink)
                    if parent is not None:
                        parent.remove(hyperlink)
                        changed_worksheet = True
                if changed_worksheet:
                    replacements[member] = ElementTree.tostring(
                        worksheet,
                        encoding="utf-8",
                        xml_declaration=True,
                    )

                relationship_member = _relationship_part_path(member)
                try:
                    relationships = reader_xml_root(relationship_member)
                except KeyError:
                    continue
                except (
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ):
                    continue
                if (
                    _xml_namespace(relationships.tag) != _PACKAGE_RELATIONSHIP_NS
                    or _xml_local_name(relationships.tag) != "Relationships"
                ):
                    continue
                removed_relationship = False
                for relationship in list(relationships.findall(relationship_tag)):
                    if (
                        relationship.get("Type", "").casefold()
                        != _CELL_HYPERLINK_RELATIONSHIP.casefold()
                    ):
                        continue
                    relationships.remove(relationship)
                    removed_relationship = True
                if removed_relationship:
                    replacements[relationship_member] = ElementTree.tostring(
                        relationships,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate cell hyperlinks before the underlying "
            f"workbook reader ran ({type(error).__name__}); raw hyperlink metadata "
            "remains fail-closed."
        )
    return replacements, tuple(sorted(reader_warnings))


def _worksheet_sparkline_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep unsupported Sparkline Group extensions out of the ordinary reader.

    FormulaFence records the original x14 declarations before constructing this
    temporary copy. Removing only extensions that contain sparklineGroups avoids
    an openpyxl warning and prevents its lossy extension handling from affecting
    the ordinary worksheet snapshot.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            sheet_parts = _sheet_xml_parts(archive)
            extension_list_tag = f"{{{_SPREADSHEETML_NS}}}extLst"
            extension_tag = f"{{{_SPREADSHEETML_NS}}}ext"
            group_container_tag = (
                f"{{{_OFFICE_2010_SPREADSHEET_NS}}}sparklineGroups"
            )
            for _sheet, (member, sheet_kind) in sheet_parts.items():
                if sheet_kind != "worksheet":
                    continue
                try:
                    worksheet = reader_xml_root(member)
                except (
                    KeyError,
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ):
                    continue
                if (
                    _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    continue
                parent_by_child = {
                    child: parent
                    for parent in worksheet.iter()
                    for child in parent
                }
                extensions_to_remove: set[ElementTree.Element] = set()
                changed_worksheet = False
                for container in list(worksheet.iter(group_container_tag)):
                    ancestor = parent_by_child.get(container)
                    while ancestor is not None and ancestor.tag != extension_tag:
                        ancestor = parent_by_child.get(ancestor)
                    if ancestor is not None:
                        extensions_to_remove.add(ancestor)
                        continue
                    parent = parent_by_child.get(container)
                    if parent is not None:
                        parent.remove(container)
                        changed_worksheet = True
                for extension in extensions_to_remove:
                    parent = parent_by_child.get(extension)
                    if parent is not None:
                        parent.remove(extension)
                        changed_worksheet = True
                for extension_list in list(worksheet.findall(extension_list_tag)):
                    if list(extension_list):
                        continue
                    worksheet.remove(extension_list)
                    changed_worksheet = True
                if changed_worksheet:
                    replacements[member] = ElementTree.tostring(
                        worksheet,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate worksheet sparklines before the "
            f"underlying workbook reader ran ({type(error).__name__}); raw "
            "sparkline metadata remains fail-closed."
        )
    return replacements, tuple(sorted(reader_warnings))


def _worksheet_web_extension_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep supported worksheet add-in bindings out of the ordinary reader.

    FormulaFence reads the original x15 worksheet binding extension before this
    temporary copy is made.  ``openpyxl`` warns that these Web Extension
    declarations are unsupported and may discard them, even though its normal
    cell reader has no use for them.  Removing just the documented extension
    URI avoids that noisy, lossy path while leaving malformed raw metadata
    covered by the dedicated add-in scanner.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            for _sheet, (member, sheet_kind) in _sheet_xml_parts(archive).items():
                if sheet_kind != "worksheet":
                    continue
                try:
                    worksheet = reader_xml_root(member)
                except (
                    KeyError,
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ):
                    continue
                namespace = _xml_namespace(worksheet.tag)
                if (
                    namespace not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    continue
                extension_list_tag = f"{{{namespace}}}extLst"
                extension_tag = f"{{{namespace}}}ext"
                changed_worksheet = False
                for extension_list in list(worksheet.findall(extension_list_tag)):
                    for extension in list(extension_list):
                        if (
                            extension.tag == extension_tag
                            and extension.get("uri", "").casefold()
                            == _WORKSHEET_WEB_EXTENSION_EXTENSION_URI.casefold()
                        ):
                            extension_list.remove(extension)
                            changed_worksheet = True
                    if not list(extension_list):
                        worksheet.remove(extension_list)
                        changed_worksheet = True
                if changed_worksheet:
                    replacements[member] = ElementTree.tostring(
                        worksheet,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate worksheet Office Web Add-in bindings before "
            f"the underlying workbook reader ran ({type(error).__name__}); raw add-in "
            "metadata remains fail-closed."
        )
    return replacements, tuple(sorted(reader_warnings))


def _worksheet_dimension_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep malformed dimension declarations out of the ordinary reader.

    The raw dimension scanner runs on the original package and retains a
    fail-closed coverage finding. This narrowly sanitizes only malformed
    dimension attributes in the temporary reader copy so an otherwise usable
    workbook can still produce that finding instead of failing inside
    ``openpyxl`` before review output is available.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            for member in _visual_worksheet_xml_paths(archive).values():
                try:
                    worksheet = reader_xml_root(member)
                except (
                    KeyError,
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ):
                    continue
                namespace = _xml_namespace(worksheet.tag)
                if (
                    namespace
                    not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    continue
                sheet_format_tag = f"{{{namespace}}}sheetFormatPr"
                cols_tag = f"{{{namespace}}}cols"
                col_tag = f"{{{namespace}}}col"
                sheet_data_tag = f"{{{namespace}}}sheetData"
                row_tag = f"{{{namespace}}}row"
                changed = False

                for sheet_format in worksheet.findall(sheet_format_tag):
                    decimal_attributes = {
                        "defaultRowHeight": _WORKSHEET_DIMENSION_MAX_ROW_HEIGHT,
                        "defaultColWidth": _WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH,
                    }
                    for name, maximum in decimal_attributes.items():
                        if (
                            name in sheet_format.attrib
                            and _worksheet_dimension_decimal(
                                sheet_format.get(name), maximum=maximum
                            )
                            is None
                        ):
                            sheet_format.attrib.pop(name, None)
                            changed = True
                    if (
                        "baseColWidth" in sheet_format.attrib
                        and _worksheet_dimension_unsigned_int(
                            sheet_format.get("baseColWidth"),
                            maximum=int(_WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH),
                        )
                        is None
                    ):
                        sheet_format.attrib.pop("baseColWidth", None)
                        changed = True
                    for name in ("customHeight", "thickTop", "thickBottom"):
                        if (
                            name in sheet_format.attrib
                            and _number_format_boolean(sheet_format.get(name), False)
                            is None
                        ):
                            sheet_format.attrib.pop(name, None)
                            changed = True

                for columns in worksheet.findall(cols_tag):
                    for column in list(columns):
                        if column.tag != col_tag:
                            continue
                        minimum = _worksheet_dimension_unsigned_int(
                            column.get("min"), maximum=MAX_EXCEL_COLUMN
                        )
                        maximum = _worksheet_dimension_unsigned_int(
                            column.get("max"), maximum=MAX_EXCEL_COLUMN
                        )
                        has_dimension_metadata = any(
                            name in column.attrib
                            for name in ("width", "bestFit", "customWidth")
                        )
                        if has_dimension_metadata and (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                        ):
                            columns.remove(column)
                            changed = True
                            continue
                        if (
                            "width" in column.attrib
                            and _worksheet_dimension_decimal(
                                column.get("width"),
                                maximum=_WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH,
                            )
                            is None
                        ):
                            column.attrib.pop("width", None)
                            changed = True
                        for name in ("bestFit", "customWidth"):
                            if (
                                name in column.attrib
                                and _number_format_boolean(column.get(name), False)
                                is None
                            ):
                                column.attrib.pop(name, None)
                                changed = True

                for sheet_data in worksheet.findall(sheet_data_tag):
                    for row in sheet_data.findall(row_tag):
                        if (
                            "ht" in row.attrib
                            and _worksheet_dimension_decimal(
                                row.get("ht"),
                                maximum=_WORKSHEET_DIMENSION_MAX_ROW_HEIGHT,
                            )
                            is None
                        ):
                            row.attrib.pop("ht", None)
                            changed = True
                        for name in ("customHeight", "thickTop", "thickBot"):
                            if (
                                name in row.attrib
                                and _number_format_boolean(row.get(name), False) is None
                            ):
                                row.attrib.pop(name, None)
                                changed = True
                if changed:
                    replacements[member] = ElementTree.tostring(
                        worksheet,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
                    reader_warnings.add(
                        "FormulaFence isolated malformed worksheet-dimension metadata "
                        "before the underlying workbook reader ran; raw dimension controls "
                        "remain fail-closed."
                    )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate malformed worksheet-dimension metadata "
            f"before the underlying workbook reader ran ({type(error).__name__})."
        )
    return replacements, tuple(sorted(reader_warnings))


def _custom_workbook_view_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep legacy Custom Views out of the ordinary workbook reader copy.

    FormulaFence has already inspected the original raw OOXML. ``openpyxl``
    parses these legacy structures unevenly (and rejects some valid values),
    while its cell/dependency reader has no need to apply an alternate view.
    Removing the isolated containers preserves the ordinary cell audit and
    leaves the raw boundary responsible for view evidence and coverage gaps.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            try:
                workbook = reader_xml_root("xl/workbook.xml")
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ):
                workbook = None
            if workbook is not None:
                custom_containers = [
                    child
                    for child in workbook
                    if _xml_local_name(child.tag) == "customWorkbookViews"
                ]
                if custom_containers:
                    for container in custom_containers:
                        workbook.remove(container)
                    replacements["xl/workbook.xml"] = ElementTree.tostring(
                        workbook,
                        encoding="utf-8",
                        xml_declaration=True,
                    )

            xlm_macro_targets: set[str] = set()
            relationship_member = _relationship_part_path("xl/workbook.xml")
            try:
                relationships = reader_xml_root(relationship_member)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ):
                relationships = None
            if (
                relationships is not None
                and _xml_namespace(relationships.tag) == _PACKAGE_RELATIONSHIP_NS
                and _xml_local_name(relationships.tag) == "Relationships"
            ):
                relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
                for relationship in relationships.findall(relationship_tag):
                    if (
                        relationship.get("Type")
                        not in _XLM_MACRO_SHEET_RELATIONSHIPS
                    ):
                        continue
                    target = relationship.get("Target")
                    if (
                        target is not None
                        and relationship.get("TargetMode", "Internal").casefold()
                        == "internal"
                        and (safe_target := _normalise_part_target("xl/workbook.xml", target))
                        is not None
                    ):
                        xlm_macro_targets.add(safe_target)

            sheet_prefixes = (
                "xl/worksheets/",
                "xl/chartsheets/",
                "xl/dialogsheets/",
            )
            for member in archive.namelist():
                if not (
                    member.endswith(".xml")
                    and member.startswith(sheet_prefixes)
                    and "/_rels/" not in member
                ):
                    continue
                if member in xlm_macro_targets:
                    continue
                try:
                    sheet = reader_xml_root(member)
                except (
                    KeyError,
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    reader_warnings.add(
                        "FormulaFence could not isolate legacy Excel Custom View metadata "
                        f"from the underlying workbook reader ({type(error).__name__})."
                    )
                    continue
                custom_containers = [
                    child
                    for child in sheet
                    if _xml_local_name(child.tag) == "customSheetViews"
                ]
                if not custom_containers:
                    continue
                for container in custom_containers:
                    sheet.remove(container)
                replacements[member] = ElementTree.tostring(
                    sheet,
                    encoding="utf-8",
                    xml_declaration=True,
                )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not prepare a legacy Excel Custom View-safe workbook "
            f"reader copy ({type(error).__name__})."
        )
    return replacements, tuple(sorted(reader_warnings))


def _table_style_control_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep presentation-only Table Style XML out of the ordinary reader copy.

    The raw scanner has already retained a private semantic inventory of these
    controls. ``openpyxl`` does not need custom Table Style definitions, a
    table's presentation selection, or its table-local format references to
    audit cells, tables, and formulas. Removing them prevents malformed
    presentation-only records from blocking that ordinary audit.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            try:
                styles = reader_xml_root("xl/styles.xml")
            except KeyError:
                styles = None
            except (
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                styles = None
                reader_warnings.add(
                    "FormulaFence could not isolate Excel Table Style definitions "
                    f"from the underlying workbook reader ({type(error).__name__})."
                )
            if styles is not None:
                style_containers = [
                    child
                    for child in styles
                    if _xml_local_name(child.tag) == "tableStyles"
                ]
                # Openpyxl writes an empty default ``tableStyles`` container
                # into ordinary workbooks. It is benign and common, so keep it
                # in place; only non-empty custom/unknown declarations need
                # isolating before the ordinary reader runs.
                style_containers_to_remove = [
                    container
                    for container in style_containers
                    if list(container) or (container.text and container.text.strip())
                ]
                if style_containers_to_remove:
                    for container in style_containers_to_remove:
                        styles.remove(container)
                    replacements["xl/styles.xml"] = ElementTree.tostring(
                        styles,
                        encoding="utf-8",
                        xml_declaration=True,
                    )

            for member in archive.namelist():
                if not (
                    member.startswith("xl/tables/")
                    and member.endswith(".xml")
                    and "/_rels/" not in member
                ):
                    continue
                try:
                    table = reader_xml_root(member)
                except (
                    KeyError,
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    reader_warnings.add(
                        "FormulaFence could not isolate Excel Table Style metadata "
                        f"from the underlying workbook reader ({type(error).__name__})."
                    )
                    continue
                changed = False
                style_infos = [
                    child
                    for child in table
                    if _xml_local_name(child.tag) == "tableStyleInfo"
                ]
                for style_info in style_infos:
                    table.remove(style_info)
                    changed = True
                for attribute in (
                    _TABLE_DIRECT_DXF_TABLE_ATTRIBUTES
                    | _TABLE_NAMED_CELL_STYLE_ATTRIBUTES
                ):
                    if attribute in table.attrib:
                        table.attrib.pop(attribute)
                        changed = True
                for table_columns in table:
                    if _xml_local_name(table_columns.tag) != "tableColumns":
                        continue
                    for column in table_columns:
                        if _xml_local_name(column.tag) != "tableColumn":
                            continue
                        for attribute in (
                            _TABLE_DIRECT_DXF_COLUMN_ATTRIBUTES
                            | _TABLE_NAMED_CELL_STYLE_ATTRIBUTES
                        ):
                            if attribute in column.attrib:
                                column.attrib.pop(attribute)
                                changed = True
                if changed:
                    replacements[member] = ElementTree.tostring(
                        table,
                        encoding="utf-8",
                        xml_declaration=True,
                    )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not prepare an Excel Table Style-safe workbook reader "
            f"copy ({type(error).__name__})."
        )
    return replacements, tuple(sorted(reader_warnings))


def _xlm_macro_sheet_reader_replacements(
    path: Path,
    prior_replacements: Mapping[str, bytes] | None = None,
) -> tuple[dict[str, bytes], tuple[str, ...]]:
    """Keep raw XLM macro programs out of the ordinary workbook reader.

    FormulaFence has already inspected the original macro sheet through its
    bounded raw scanner. ``openpyxl`` otherwise dispatches an XLM relationship
    through its regular worksheet reader, which has no use for the legacy
    program but can still materialize the complete macro XML tree. Preserve the
    sheet declaration and its ordinary workbook position by substituting an
    empty SpreadsheetML worksheet only in the temporary reader copy.
    """
    replacements: dict[str, bytes] = {}
    reader_warnings: set[str] = set()
    prior_replacements = prior_replacements or {}
    try:
        with ZipFile(path) as archive:
            def reader_xml_root(member: str) -> ElementTree.Element:
                """Read an earlier safe overlay before falling back to the package."""
                if (payload := prior_replacements.get(member)) is not None:
                    return _xml_root_from_payload(payload)
                return _xml_root(archive, member)

            archive_members = set(archive.namelist())
            candidate_members = {
                member
                for member in archive_members
                if _XLM_MACRO_SHEET_PART_PATTERN.fullmatch(member)
            }
            relationship_member = _relationship_part_path("xl/workbook.xml")
            try:
                relationships = reader_xml_root(relationship_member)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                relationships = None
                reader_warnings.add(
                    "FormulaFence could not inspect workbook relationships while "
                    "isolating XLM macro-sheet XML before the underlying workbook "
                    f"reader ran ({type(error).__name__}); conventional macro-sheet "
                    "paths remain isolated."
                )
            if (
                relationships is not None
                and _xml_namespace(relationships.tag) == _PACKAGE_RELATIONSHIP_NS
                and _xml_local_name(relationships.tag) == "Relationships"
            ):
                relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
                xlm_targets: set[str] = set()
                ordinary_targets: set[str] = set()
                for relationship in relationships.findall(relationship_tag):
                    target = relationship.get("Target")
                    target_mode = relationship.get("TargetMode", "Internal")
                    safe_target = (
                        _normalise_part_target("xl/workbook.xml", target)
                        if target is not None and target_mode.casefold() == "internal"
                        else None
                    )
                    if safe_target is None:
                        continue
                    if relationship.get("Type") in _XLM_MACRO_SHEET_RELATIONSHIPS:
                        xlm_targets.add(safe_target)
                    else:
                        ordinary_targets.add(safe_target)
                ambiguous_targets = xlm_targets & ordinary_targets
                if ambiguous_targets:
                    reader_warnings.add(
                        "FormulaFence isolated an XLM macro-sheet target also bound "
                        "through an ordinary workbook relationship before the underlying "
                        "reader ran; the ordinary-sheet view has a coverage gap."
                    )
                candidate_members.update(xlm_targets)
            elif relationships is not None:
                reader_warnings.add(
                    "FormulaFence found an unexpected workbook relationship root while "
                    "isolating XLM macro-sheet XML; conventional macro-sheet paths "
                    "remain isolated."
                )
            empty_worksheet = (
                b'<?xml version="1.0" encoding="utf-8"?>'
                b'<worksheet xmlns="http://schemas.openxmlformats.org/'
                b'spreadsheetml/2006/main"><sheetData/></worksheet>'
            )
            for member in sorted(candidate_members, key=str.casefold):
                if member not in archive_members:
                    continue
                replacements[member] = empty_worksheet
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        reader_warnings.add(
            "FormulaFence could not isolate XLM macro-sheet XML before the underlying "
            f"workbook reader ran ({type(error).__name__}); raw macro metadata remains "
            "fail-closed."
        )
    return replacements, tuple(sorted(reader_warnings))


def _openpyxl_safe_source(path: Path) -> tuple[Path, Path | None, tuple[str, ...]]:
    """Return a temporary source that limits unsafe ordinary-reader behavior."""
    replacements, reader_warnings = _pivot_reader_cache_record_replacements(path)
    legacy_replacements, legacy_reader_warnings = (
        _legacy_note_reader_relationship_replacements(path)
    )
    prior_replacements = {**replacements, **legacy_replacements}
    threaded_comment_replacements, threaded_comment_reader_warnings = (
        _threaded_comment_reader_relationship_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **threaded_comment_replacements,
    }
    cell_hyperlink_replacements, cell_hyperlink_reader_warnings = (
        _cell_hyperlink_reader_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **cell_hyperlink_replacements,
    }
    worksheet_sparkline_replacements, worksheet_sparkline_reader_warnings = (
        _worksheet_sparkline_reader_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **worksheet_sparkline_replacements,
    }
    worksheet_web_extension_replacements, worksheet_web_extension_reader_warnings = (
        _worksheet_web_extension_reader_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **worksheet_web_extension_replacements,
    }
    worksheet_dimension_replacements, worksheet_dimension_reader_warnings = (
        _worksheet_dimension_reader_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **worksheet_dimension_replacements,
    }
    custom_workbook_view_replacements, custom_workbook_view_reader_warnings = (
        _custom_workbook_view_reader_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **custom_workbook_view_replacements,
    }
    table_style_control_replacements, table_style_control_reader_warnings = (
        _table_style_control_reader_replacements(path, prior_replacements)
    )
    prior_replacements = {
        **prior_replacements,
        **table_style_control_replacements,
    }
    xlm_macro_sheet_replacements, xlm_macro_sheet_reader_warnings = (
        _xlm_macro_sheet_reader_replacements(path, prior_replacements)
    )
    replacements.update(legacy_replacements)
    replacements.update(threaded_comment_replacements)
    replacements.update(cell_hyperlink_replacements)
    replacements.update(worksheet_sparkline_replacements)
    replacements.update(worksheet_web_extension_replacements)
    replacements.update(worksheet_dimension_replacements)
    replacements.update(custom_workbook_view_replacements)
    replacements.update(table_style_control_replacements)
    replacements.update(xlm_macro_sheet_replacements)
    reader_warnings = tuple(
        sorted(
            {
                *reader_warnings,
                *legacy_reader_warnings,
                *threaded_comment_reader_warnings,
                *cell_hyperlink_reader_warnings,
                *worksheet_sparkline_reader_warnings,
                *worksheet_web_extension_reader_warnings,
                *worksheet_dimension_reader_warnings,
                *custom_workbook_view_reader_warnings,
                *table_style_control_reader_warnings,
                *xlm_macro_sheet_reader_warnings,
            }
        )
    )
    if not replacements:
        return path, None, reader_warnings

    temporary_path: Path | None = None
    warnings_for_reader = set(reader_warnings)
    try:
        descriptor, temporary_name = tempfile.mkstemp(
            prefix="formulafence-pivot-reader-",
            suffix=path.suffix,
        )
        os.close(descriptor)
        temporary_path = Path(temporary_name)
        shutil.copyfile(path, temporary_path)
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            with ZipFile(temporary_path, "a", compression=ZIP_DEFLATED) as archive:
                for member, payload in sorted(replacements.items(), key=lambda item: item[0]):
                    archive.writestr(member, payload)
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        if temporary_path is not None:
            temporary_path.unlink(missing_ok=True)
        warnings_for_reader.add(
            "FormulaFence could not prepare a safe workbook reader copy before the "
            f"underlying workbook reader ran ({type(error).__name__})."
        )
        return path, None, tuple(sorted(warnings_for_reader))
    return temporary_path, temporary_path, tuple(sorted(warnings_for_reader))


def _worksheet_control_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
    missing_is_warning: bool = False,
) -> tuple[_WorksheetControlRawRelationship, ...]:
    """Read worksheet-control relationships without opening any package target."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        if missing_is_warning:
            warnings.add(
                "FormulaFence could not locate "
                f"{context} relationships while inspecting worksheet embedded controls; "
                "affected controls may be incomplete."
            )
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for worksheet embedded controls "
            f"({type(error).__name__}); affected controls were not compared."
        )
        return ()
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting worksheet embedded controls; "
            "affected controls were not compared."
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_WorksheetControlRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _WorksheetControlRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting worksheet "
            "embedded controls; affected controls may be incomplete."
        )
    return tuple(relationships)


def _worksheet_control_relationship_signature(
    relationships: tuple[_WorksheetControlRawRelationship, ...],
) -> str | None:
    """Fingerprint control relationship semantics without identifier churn."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _worksheet_control_relationship_semantics(
    relationships: tuple[_WorksheetControlRawRelationship, ...],
    warnings: set[str],
    *,
    context: str,
) -> dict[str, tuple[str, str, str]]:
    """Resolve private relationship identifiers while preserving malformed evidence."""
    relationships_by_id: dict[str, list[_WorksheetControlRawRelationship]] = defaultdict(
        list
    )
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found a worksheet embedded-control "
                f"{context} relationship without an id; affected controls have a coverage gap."
            )
    semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        values = sorted(match.semantic_key() for match in matches)
        if len(values) > 1:
            warnings.add(
                "FormulaFence found duplicate worksheet embedded-control "
                f"{context} relationship ids; affected controls have a coverage gap."
            )
        semantics[relationship_id] = values[0]
    return semantics


def _worksheet_control_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    *,
    relationship_attributes: frozenset[str] | None = None,
) -> tuple[object, ...]:
    """Canonicalize private control XML while resolving relationship identifiers."""
    if relationship_attributes is None:
        relationship_attributes = frozenset(
            {f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"}
        )
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute in relationship_attributes:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
        else:
            attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _worksheet_control_fragment(
            child,
            relationship_semantics,
            relationship_attributes=relationship_attributes,
        )
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _worksheet_control_boolean(
    value: str | None,
    default: bool,
    warnings: set[str],
    *,
    context: str,
    attribute: str,
) -> bool:
    """Read an OOXML boolean while retaining invalid values privately."""
    if value is None:
        return default
    lowered = value.casefold()
    if lowered in {"1", "true", "on"}:
        return True
    if lowered in {"0", "false", "off"}:
        return False
    warnings.add(
        "FormulaFence could not interpret a worksheet embedded-control "
        f"{context} {attribute} boolean; the affected control has a coverage gap."
    )
    return default


def _worksheet_control_ole_auto_update(
    value: str | None,
    warnings: set[str],
) -> bool:
    """Return whether an OLE link requests automatic updates."""
    if value is None or value.casefold() == "oncall":
        return False
    if value.casefold() == "always":
        return True
    warnings.add(
        "FormulaFence found an unrecognized worksheet embedded-control OLE update "
        "setting; the affected control has a coverage gap."
    )
    return False


def _worksheet_control_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _WorksheetEmbeddedControlXmlBudget,
) -> str | None:
    """Stream control XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _WORKSHEET_EMBEDDED_CONTROL_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read a worksheet embedded-control XML part whose "
        "XML structure exceeds the safety budget; the affected controls have a "
        "coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _worksheet_control_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetEmbeddedControlXmlBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded control XML part without parsing it or following targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded worksheet embedded-control XML part count "
            "budget; the affected controls have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a worksheet embedded-control XML package part; "
            "the affected controls were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _WORKSHEET_EMBEDDED_CONTROL_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized worksheet embedded-control XML "
            "part; the affected controls have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded worksheet embedded-control XML read budget; "
            "the affected controls have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = (
        _worksheet_control_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            warnings,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a worksheet embedded-control XML package part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _worksheet_control_related_part_payloads(
    archive: ZipFile,
    members: set[str],
    unresolved_entries: list[tuple[str, str]],
    warnings: set[str],
    budget: _WorksheetEmbeddedControlRelatedPartBudget,
) -> _WorksheetControlRelatedPartPayloadInspection:
    """Fingerprint bounded direct control payloads without opening their contents.

    ActiveX binary data and OLE/package payloads are arbitrary formats. The
    scanner therefore resolves only safe internal targets and hashes their
    bytes; it never executes, parses, or follows embedded or external content.
    """
    entries = list(unresolved_entries)
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts == 0:
            warnings.add(
                "FormulaFence reached its bounded worksheet embedded-control payload "
                "part count budget; the affected controls have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate a worksheet embedded-control payload part; "
                "the affected controls were not compared."
            )
            entries.append(("missing-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _WORKSHEET_EMBEDDED_CONTROL_RELATED_PART_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized worksheet embedded-control "
                "payload part; the affected controls have a coverage gap."
            )
            entries.append(("oversized-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded worksheet embedded-control payload "
                "read budget; the affected controls have a coverage gap."
            )
            entries.append(("read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as payload:
                while chunk := payload.read(_WORKSHEET_EMBEDDED_CONTROL_HASH_CHUNK_BYTES):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("payload exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("payload did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint a worksheet embedded-control payload "
                f"part ({type(error).__name__}); the affected controls were not compared."
            )
            entries.append(("unreadable-part", metadata))
            uninspected_part_count += 1
            continue
        entries.append(("payload", repr((member, digest.hexdigest()))))
        fingerprinted_part_count += 1

    entries.sort()
    return _WorksheetControlRelatedPartPayloadInspection(
        internal_part_count=len(members) + len(unresolved_entries),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_signature=_private_external_data_signature(tuple(entries)),
    )


def _worksheet_control_sheet_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _WorksheetEmbeddedControlXmlBudget,
) -> _WorksheetControlSheetInspection:
    """Inspect one worksheet's control bindings without reading cells or payloads."""
    relationships = _worksheet_control_raw_relationships(
        archive,
        member,
        warnings,
        context="worksheet",
    )
    relationship_semantics = _worksheet_control_relationship_semantics(
        relationships,
        warnings,
        context="worksheet",
    )
    relationship_by_id: dict[str, _WorksheetControlRawRelationship] = {}
    for relationship in relationships:
        if (
            relationship.relationship_id
            and relationship.relationship_id not in relationship_by_id
        ):
            relationship_by_id[relationship.relationship_id] = relationship

    active_x_members: set[str] = set()
    control_property_members: set[str] = set()
    legacy_vml_members: set[str] = set()
    payload_members: set[str] = set()
    unresolved_payload_entries: list[tuple[str, str]] = []
    legacy_vml_relationships = tuple(
        relationship
        for relationship in relationships
        if relationship.relationship_type == _WORKSHEET_VML_DRAWING_RELATIONSHIP
    )
    legacy_vml_unrecognized_count = 0
    for relationship in legacy_vml_relationships:
        if relationship.safe_target is None:
            warnings.add(
                "FormulaFence found a legacy VML drawing relationship without a safe "
                "internal target; the affected controls were not compared."
            )
            legacy_vml_unrecognized_count += 1
        else:
            legacy_vml_members.add(relationship.safe_target)
    legacy_vml_kwargs = {
        "legacy_vml_members": tuple(sorted(legacy_vml_members, key=str.casefold)),
        "legacy_vml_relationships": legacy_vml_relationships,
        "legacy_vml_unrecognized_count": legacy_vml_unrecognized_count,
    }
    relevant_relationship_types = {
        _WORKSHEET_CONTROL_RELATIONSHIP,
        _WORKSHEET_CTRLPROP_RELATIONSHIP,
        _WORKSHEET_OLE_OBJECT_RELATIONSHIP,
        _WORKSHEET_EMBEDDED_PACKAGE_RELATIONSHIP,
        _WORKSHEET_ACTIVEX_BINARY_RELATIONSHIP,
    }
    for relationship in relationships:
        if relationship.relationship_type == _WORKSHEET_CONTROL_RELATIONSHIP:
            if relationship.safe_target is not None:
                active_x_members.add(relationship.safe_target)
        elif relationship.relationship_type == _WORKSHEET_CTRLPROP_RELATIONSHIP:
            if relationship.safe_target is not None:
                control_property_members.add(relationship.safe_target)
        elif (
            relationship.relationship_type
            in {
                _WORKSHEET_OLE_OBJECT_RELATIONSHIP,
                _WORKSHEET_EMBEDDED_PACKAGE_RELATIONSHIP,
                _WORKSHEET_ACTIVEX_BINARY_RELATIONSHIP,
            }
            and relationship.target_mode.casefold() == "internal"
        ):
            if relationship.safe_target is not None:
                payload_members.add(relationship.safe_target)
            else:
                unresolved_payload_entries.append(
                    (
                        "unsafe-direct-payload-target",
                        repr((relationship.relationship_type, relationship.target)),
                    )
                )

    relevant_relationships = tuple(
        relationship
        for relationship in relationships
        if relationship.relationship_type in relevant_relationship_types
    )
    # A conforming worksheet control or OLE object is relationship-bound. Do
    # not consume the bounded XML-read budget for ordinary worksheets that
    # have no relevant relationship declaration at all: large data sheets are
    # common, and no valid control chain can start there.
    if not relevant_relationships:
        return _WorksheetControlSheetInspection(member=member, **legacy_vml_kwargs)
    payload, fallback_signature = _worksheet_control_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _WorksheetControlSheetInspection(
            member=member,
            present=bool(relevant_relationships),
            active_x_members=tuple(sorted(active_x_members, key=str.casefold)),
            control_property_members=tuple(
                sorted(control_property_members, key=str.casefold)
            ),
            **legacy_vml_kwargs,
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=int(bool(relevant_relationships)),
            definition_signature=fallback_signature,
            relationship_signature=_worksheet_control_relationship_signature(
                relevant_relationships
            ),
        )

    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a worksheet embedded-control XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        return _WorksheetControlSheetInspection(
            member=member,
            present=bool(relevant_relationships),
            active_x_members=tuple(sorted(active_x_members, key=str.casefold)),
            control_property_members=tuple(
                sorted(control_property_members, key=str.casefold)
            ),
            **legacy_vml_kwargs,
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=int(bool(relevant_relationships)),
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relevant_relationships
            ),
        )
    if (
        _xml_local_name(root.tag) != "worksheet"
        or _xml_namespace(root.tag) != _SPREADSHEETML_NS
    ):
        warnings.add(
            "FormulaFence found a worksheet embedded-control part with an unexpected root; "
            "the affected controls were not compared."
        )
        return _WorksheetControlSheetInspection(
            member=member,
            present=bool(relevant_relationships),
            active_x_members=tuple(sorted(active_x_members, key=str.casefold)),
            control_property_members=tuple(
                sorted(control_property_members, key=str.casefold)
            ),
            **legacy_vml_kwargs,
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=int(bool(relevant_relationships)),
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relevant_relationships
            ),
        )

    controls_tag = f"{{{_SPREADSHEETML_NS}}}controls"
    control_tag = f"{{{_SPREADSHEETML_NS}}}control"
    control_properties_tag = f"{{{_SPREADSHEETML_NS}}}controlPr"
    ole_objects_tag = f"{{{_SPREADSHEETML_NS}}}oleObjects"
    ole_object_tag = f"{{{_SPREADSHEETML_NS}}}oleObject"
    object_properties_tag = f"{{{_SPREADSHEETML_NS}}}objectPr"
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"

    controls_containers = list(root.iter(controls_tag))
    ole_objects_containers = list(root.iter(ole_objects_tag))
    raw_controls = [
        control
        for container in controls_containers
        for control in container.iter(control_tag)
    ]
    controls: list[ElementTree.Element] = []
    seen_control_keys: set[tuple[str, ...]] = set()
    for index, control in enumerate(raw_controls):
        relationship_id = control.get(relationship_attribute)
        if relationship_id:
            key = ("relationship", relationship_id)
        else:
            key = (
                "unbound",
                str(index),
                control.get("shapeId", ""),
                control.get("name", ""),
            )
        if key in seen_control_keys:
            continue
        seen_control_keys.add(key)
        controls.append(control)
    ole_objects = [
        ole_object
        for container in ole_objects_containers
        for ole_object in container
        if ole_object.tag == ole_object_tag
    ]

    selected_relationship_ids: set[str] = set()
    unrecognized_count = 0

    def relationship_for(
        relationship_id: str,
        *,
        context: str,
    ) -> _WorksheetControlRawRelationship | None:
        nonlocal unrecognized_count
        selected_relationship_ids.add(relationship_id)
        if relationship_id not in relationship_semantics:
            warnings.add(
                "FormulaFence found a worksheet embedded-control "
                f"{context} reference without a matching relationship; affected controls "
                "have a coverage gap."
            )
            unrecognized_count += 1
            return None
        return relationship_by_id.get(relationship_id)

    control_macro_assignment_count = 0
    control_cell_link_count = 0
    control_source_range_count = 0
    for control in controls:
        relationship_id = control.get(relationship_attribute)
        if relationship_id is None:
            warnings.add(
                "FormulaFence found a worksheet control without a relationship id; "
                "the affected controls have a coverage gap."
            )
            unrecognized_count += 1
        elif relationship := relationship_for(relationship_id, context="control"):
            if relationship.relationship_type == _WORKSHEET_CONTROL_RELATIONSHIP:
                if relationship.safe_target is None:
                    warnings.add(
                        "FormulaFence found a worksheet control without a safe internal "
                        "ActiveX target; the affected controls were not compared."
                    )
                    unrecognized_count += 1
                else:
                    active_x_members.add(relationship.safe_target)
            elif relationship.relationship_type == _WORKSHEET_CTRLPROP_RELATIONSHIP:
                if relationship.safe_target is None:
                    warnings.add(
                        "FormulaFence found a worksheet control without a safe internal "
                        "form-control properties target; the affected controls were not compared."
                    )
                    unrecognized_count += 1
                else:
                    control_property_members.add(relationship.safe_target)
            else:
                warnings.add(
                    "FormulaFence found a worksheet control with an unexpected relationship "
                    "type; the affected controls have a coverage gap."
                )
                unrecognized_count += 1

        for properties in control:
            if properties.tag != control_properties_tag:
                continue
            control_macro_assignment_count += int(properties.get("macro") is not None)
            control_cell_link_count += int(properties.get("linkedCell") is not None)
            control_source_range_count += int(
                properties.get("listFillRange") is not None
            )
            properties_relationship_id = properties.get(relationship_attribute)
            if properties_relationship_id is None:
                continue
            if relationship := relationship_for(
                properties_relationship_id,
                context="control properties",
            ):
                # An inline controlPr can bind an image/presentation relationship
                # for an ActiveX control as well as a ctrlProp package part for a
                # form control. Retain every relationship semantically, but only
                # traverse the documented ctrlProp target type.
                if relationship.relationship_type == _WORKSHEET_CTRLPROP_RELATIONSHIP:
                    if relationship.safe_target is None:
                        warnings.add(
                            "FormulaFence found worksheet control properties without a safe "
                            "internal target; the affected controls were not compared."
                        )
                        unrecognized_count += 1
                    else:
                        control_property_members.add(relationship.safe_target)
                elif relationship.relationship_type == _WORKSHEET_CONTROL_RELATIONSHIP:
                    warnings.add(
                        "FormulaFence found worksheet control properties with a control-part "
                        "relationship; the affected controls have a coverage gap."
                    )
                    unrecognized_count += 1

    linked_ole_object_count = 0
    auto_load_ole_object_count = 0
    auto_update_ole_object_count = 0
    for ole_object in ole_objects:
        relationship_id = ole_object.get(relationship_attribute)
        relationship: _WorksheetControlRawRelationship | None = None
        if relationship_id is None:
            warnings.add(
                "FormulaFence found a worksheet OLE object without a relationship id; "
                "the affected controls have a coverage gap."
            )
            unrecognized_count += 1
        else:
            relationship = relationship_for(relationship_id, context="OLE object")
            if relationship is not None and relationship.relationship_type not in {
                _WORKSHEET_OLE_OBJECT_RELATIONSHIP,
                _WORKSHEET_EMBEDDED_PACKAGE_RELATIONSHIP,
            }:
                warnings.add(
                    "FormulaFence found a worksheet OLE object with an unexpected relationship "
                    "type; the affected controls have a coverage gap."
                )
                unrecognized_count += 1
        linked_ole_object_count += int(
            ole_object.get("link") is not None
            or (
                relationship is not None
                and relationship.target_mode.casefold() != "internal"
            )
        )
        auto_load_ole_object_count += _worksheet_control_boolean(
            ole_object.get("autoLoad"),
            False,
            warnings,
            context="OLE object",
            attribute="autoLoad",
        )
        auto_update_ole_object_count += _worksheet_control_ole_auto_update(
            ole_object.get("oleUpdate"),
            warnings,
        )
        for properties in ole_object.iter(object_properties_tag):
            properties_relationship_id = properties.get(relationship_attribute)
            if properties_relationship_id is not None:
                relationship_for(
                    properties_relationship_id,
                    context="OLE presentation",
                )

    for relationship in relevant_relationships:
        if (
            relationship.relationship_id is None
            or relationship.relationship_id not in selected_relationship_ids
        ):
            warnings.add(
                "FormulaFence found a worksheet embedded-control relationship not bound "
                "by inspected worksheet markup; the affected controls have a coverage gap."
            )
            unrecognized_count += 1

    selected_relationships = tuple(
        relationship
        for relationship in relationships
        if (
            relationship.relationship_id in selected_relationship_ids
            or relationship.relationship_type in relevant_relationship_types
        )
    )
    fragments: list[tuple[str, str]] = []
    try:
        fragments.extend(
            (
                f"controls:{index}",
                repr(_worksheet_control_fragment(container, relationship_semantics)),
            )
            for index, container in enumerate(controls_containers)
        )
        fragments.extend(
            (
                f"ole-objects:{index}",
                repr(_worksheet_control_fragment(container, relationship_semantics)),
            )
            for index, container in enumerate(ole_objects_containers)
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested worksheet "
            "embedded-control part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        definition_signature = _private_external_data_signature(tuple(fragments))
        inspected = True
    return _WorksheetControlSheetInspection(
        member=member,
        present=bool(controls_containers or ole_objects_containers or relevant_relationships),
        worksheet_control_count=len(controls),
        control_macro_assignment_count=control_macro_assignment_count,
        control_cell_link_count=control_cell_link_count,
        control_source_range_count=control_source_range_count,
        ole_object_count=len(ole_objects),
        linked_ole_object_count=linked_ole_object_count,
        auto_load_ole_object_count=auto_load_ole_object_count,
        auto_update_ole_object_count=auto_update_ole_object_count,
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        active_x_members=tuple(sorted(active_x_members, key=str.casefold)),
        control_property_members=tuple(
            sorted(control_property_members, key=str.casefold)
        ),
        **legacy_vml_kwargs,
        payload_members=tuple(sorted(payload_members, key=str.casefold)),
        unresolved_payload_entries=tuple(unresolved_payload_entries),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_worksheet_control_relationship_signature(
            selected_relationships
        ),
    )


def _worksheet_control_activex_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _WorksheetEmbeddedControlXmlBudget,
) -> _WorksheetControlActiveXInspection:
    """Inspect one ActiveX persistence XML part without interpreting its binary data."""
    relationships = _worksheet_control_raw_relationships(
        archive,
        member,
        warnings,
        context="ActiveX control",
    )
    relationship_semantics = _worksheet_control_relationship_semantics(
        relationships,
        warnings,
        context="ActiveX control",
    )
    relationship_by_id: dict[str, _WorksheetControlRawRelationship] = {}
    for relationship in relationships:
        if (
            relationship.relationship_id
            and relationship.relationship_id not in relationship_by_id
        ):
            relationship_by_id[relationship.relationship_id] = relationship

    payload_members: set[str] = set()
    unresolved_payload_entries: list[tuple[str, str]] = []
    for relationship in relationships:
        if relationship.relationship_type != _WORKSHEET_ACTIVEX_BINARY_RELATIONSHIP:
            continue
        if relationship.target_mode.casefold() != "internal":
            continue
        if relationship.safe_target is not None:
            payload_members.add(relationship.safe_target)
        else:
            unresolved_payload_entries.append(
                (
                    "unsafe-activex-binary-target",
                    repr((relationship.relationship_type, relationship.target)),
                )
            )

    payload, fallback_signature = _worksheet_control_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _WorksheetControlActiveXInspection(
            member=member,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect an ActiveX control XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        return _WorksheetControlActiveXInspection(
            member=member,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )
    if _xml_local_name(root.tag) != "ocx" or _xml_namespace(root.tag) != _ACTIVEX_NS:
        warnings.add(
            "FormulaFence found an ActiveX control part with an unexpected root; "
            "the affected controls were not compared."
        )
        return _WorksheetControlActiveXInspection(
            member=member,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )

    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    referenced_relationship_ids = {
        relationship_id
        for element in root.iter()
        if (relationship_id := element.get(relationship_attribute)) is not None
    }
    unrecognized_count = 0
    for relationship_id in referenced_relationship_ids:
        semantic = relationship_semantics.get(relationship_id)
        if semantic is None:
            warnings.add(
                "FormulaFence found an ActiveX control binary reference without a matching "
                "relationship; the affected controls have a coverage gap."
            )
            unrecognized_count += 1
            continue
        if semantic[0] != _WORKSHEET_ACTIVEX_BINARY_RELATIONSHIP:
            warnings.add(
                "FormulaFence found an ActiveX control reference with an unexpected "
                "relationship type; the affected controls have a coverage gap."
            )
            unrecognized_count += 1
            continue
        relationship = relationship_by_id.get(relationship_id)
        if relationship is None or relationship.safe_target is None:
            warnings.add(
                "FormulaFence found an ActiveX control binary reference without a safe "
                "internal target; the affected controls were not compared."
            )
            unrecognized_count += 1
            continue
        payload_members.add(relationship.safe_target)

    for relationship in relationships:
        if relationship.relationship_type != _WORKSHEET_ACTIVEX_BINARY_RELATIONSHIP:
            warnings.add(
                "FormulaFence found an unexpected ActiveX control relationship type; "
                "the affected controls have a coverage gap."
            )
            unrecognized_count += 1
            continue
        if (
            relationship.relationship_id is None
            or relationship.relationship_id not in referenced_relationship_ids
        ):
            warnings.add(
                "FormulaFence found an ActiveX binary relationship not bound by the "
                "control definition; the affected controls have a coverage gap."
            )
            unrecognized_count += 1

    try:
        definition_signature = _private_external_data_signature(
            (("activex", repr(_worksheet_control_fragment(root, relationship_semantics))),)
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested ActiveX control "
            "part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _WorksheetControlActiveXInspection(
        member=member,
        binary_reference_count=len(referenced_relationship_ids),
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        payload_members=tuple(sorted(payload_members, key=str.casefold)),
        unresolved_payload_entries=tuple(unresolved_payload_entries),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_worksheet_control_relationship_signature(relationships),
    )


def _worksheet_control_property_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _WorksheetEmbeddedControlXmlBudget,
) -> _WorksheetControlPropertyInspection:
    """Inspect one form-control properties part without disclosing formulas or labels."""
    relationships = _worksheet_control_raw_relationships(
        archive,
        member,
        warnings,
        context="form-control properties",
    )
    relationship_semantics = _worksheet_control_relationship_semantics(
        relationships,
        warnings,
        context="form-control properties",
    )
    payload_members: set[str] = set()
    unresolved_payload_entries: list[tuple[str, str]] = []
    for relationship in relationships:
        if relationship.target_mode.casefold() != "internal":
            continue
        if relationship.safe_target is not None:
            payload_members.add(relationship.safe_target)
        else:
            unresolved_payload_entries.append(
                (
                    "unsafe-control-properties-target",
                    repr((relationship.relationship_type, relationship.target)),
                )
            )

    payload, fallback_signature = _worksheet_control_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _WorksheetControlPropertyInspection(
            member=member,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a form-control properties XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        return _WorksheetControlPropertyInspection(
            member=member,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )
    if (
        _xml_local_name(root.tag) != "formControlPr"
        or _xml_namespace(root.tag) != _OFFICE_2010_SPREADSHEET_NS
    ):
        warnings.add(
            "FormulaFence found a form-control properties part with an unexpected root; "
            "the affected controls were not compared."
        )
        return _WorksheetControlPropertyInspection(
            member=member,
            related_relationship_count=len(relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in relationships
            ),
            payload_members=tuple(sorted(payload_members, key=str.casefold)),
            unresolved_payload_entries=tuple(unresolved_payload_entries),
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )

    unrecognized_count = 0
    if relationships:
        warnings.add(
            "FormulaFence found relationships from a form-control properties part; "
            "the affected controls have a coverage gap."
        )
        unrecognized_count += len(relationships)
    formula_attributes = ("fmlaGroup", "fmlaLink", "fmlaRange", "fmlaTxbx")
    formula_binding_count = sum(
        root.get(attribute) is not None for attribute in formula_attributes
    )
    cell_link_count = sum(
        root.get(attribute) is not None
        for attribute in ("fmlaGroup", "fmlaLink", "fmlaTxbx")
    )
    source_range_count = int(root.get("fmlaRange") is not None)
    try:
        definition_signature = _private_external_data_signature(
            (
                (
                    "form-control-properties",
                    repr(_worksheet_control_fragment(root, relationship_semantics)),
                ),
            )
        )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested form-control "
            "properties part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _WorksheetControlPropertyInspection(
        member=member,
        formula_binding_count=formula_binding_count,
        cell_link_count=cell_link_count,
        source_range_count=source_range_count,
        related_relationship_count=len(relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in relationships
        ),
        payload_members=tuple(sorted(payload_members, key=str.casefold)),
        unresolved_payload_entries=tuple(unresolved_payload_entries),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_worksheet_control_relationship_signature(relationships),
    )


def _worksheet_vml_drawing_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    xml_budget: _WorksheetEmbeddedControlXmlBudget,
) -> _WorksheetVmlDrawingInspection:
    """Inspect legacy VML controls without rendering drawings or evaluating bindings.

    VML drawing parts also carry ordinary comment notes. Only ``ClientData`` nodes
    whose ``ObjectType`` is not ``Note`` enter this control inventory, so comment
    layout and note text do not create control findings.
    """
    relationships = _worksheet_control_raw_relationships(
        archive,
        member,
        warnings,
        context="legacy VML drawing",
    )
    relationship_semantics = _worksheet_control_relationship_semantics(
        relationships,
        warnings,
        context="legacy VML drawing",
    )
    relationship_by_id: dict[str, _WorksheetControlRawRelationship] = {}
    for relationship in relationships:
        if (
            relationship.relationship_id
            and relationship.relationship_id not in relationship_by_id
        ):
            relationship_by_id[relationship.relationship_id] = relationship

    payload, fallback_signature = _worksheet_control_xml_payload(
        archive,
        member,
        warnings,
        xml_budget,
    )
    if payload is None:
        return _WorksheetVmlDrawingInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a legacy VML control XML part "
            f"({type(error).__name__}); the affected controls were not compared."
        )
        return _WorksheetVmlDrawingInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )
    if _xml_local_name(root.tag) != "xml" or _xml_namespace(root.tag) not in {
        None,
        _VML_NS,
    }:
        warnings.add(
            "FormulaFence found a legacy VML control part with an unexpected root; "
            "the affected controls were not compared."
        )
        return _WorksheetVmlDrawingInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
            relationship_signature=_worksheet_control_relationship_signature(
                relationships
            ),
        )

    client_data_tag = f"{{{_VML_EXCEL_NS}}}ClientData"
    client_data_nodes = list(root.iter(client_data_tag))
    parent_by_child = {
        child: parent
        for parent in root.iter()
        for child in parent
    }
    controls: list[ElementTree.Element] = []
    control_containers: list[ElementTree.Element] = []
    seen_containers: set[int] = set()
    unrecognized_count = 0
    for client_data in client_data_nodes:
        object_type = (client_data.get("ObjectType") or "").strip()
        if object_type.casefold() == "note":
            continue
        if not object_type:
            warnings.add(
                "FormulaFence found legacy VML ClientData without an ObjectType; "
                "the affected controls have a coverage gap."
            )
            unrecognized_count += 1
        controls.append(client_data)
        container = parent_by_child.get(client_data, client_data)
        if id(container) not in seen_containers:
            seen_containers.add(id(container))
            control_containers.append(container)

    if not controls:
        return _WorksheetVmlDrawingInspection(member=member, inspected=True)

    relationship_attributes = frozenset(
        {
            f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id",
            f"{{{_VML_OFFICE_NS}}}relid",
        }
    )
    referenced_relationship_ids = {
        relationship_id
        for container in control_containers
        for element in container.iter()
        for relationship_attribute in relationship_attributes
        if (relationship_id := element.get(relationship_attribute)) is not None
    }
    selected_relationships: list[_WorksheetControlRawRelationship] = []
    for relationship_id in sorted(referenced_relationship_ids):
        semantic = relationship_semantics.get(relationship_id)
        if semantic is None:
            warnings.add(
                "FormulaFence found a legacy VML control relationship reference without "
                "a matching relationship; the affected controls have a coverage gap."
            )
            unrecognized_count += 1
            continue
        relationship = relationship_by_id.get(relationship_id)
        if relationship is not None:
            selected_relationships.append(relationship)

    macro_tag = f"{{{_VML_EXCEL_NS}}}FmlaMacro"
    cell_link_tags = {
        f"{{{_VML_EXCEL_NS}}}FmlaGroup",
        f"{{{_VML_EXCEL_NS}}}FmlaLink",
        f"{{{_VML_EXCEL_NS}}}FmlaTxbx",
    }
    source_range_tag = f"{{{_VML_EXCEL_NS}}}FmlaRange"
    camera_source_range_tag = f"{{{_VML_EXCEL_NS}}}FmlaPict"
    try:
        fragments = tuple(
            (
                f"legacy-vml-control:{index}",
                repr(
                    _worksheet_control_fragment(
                        container,
                        relationship_semantics,
                        relationship_attributes=relationship_attributes,
                    )
                ),
            )
            for index, container in enumerate(control_containers)
        )
        definition_signature = _private_external_data_signature(fragments)
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested legacy VML "
            "control part; the affected controls were not compared."
        )
        definition_signature = _private_payload_signature(payload)
        inspected = False
        unrecognized_count += 1
    else:
        inspected = True
    return _WorksheetVmlDrawingInspection(
        member=member,
        present=True,
        control_count=len(controls),
        macro_assignment_count=sum(
            sum(child.tag == macro_tag for child in client_data)
            for client_data in controls
        ),
        cell_link_count=sum(
            sum(child.tag in cell_link_tags for child in client_data)
            for client_data in controls
        ),
        source_range_count=sum(
            sum(child.tag == source_range_tag for child in client_data)
            for client_data in controls
        ),
        camera_source_range_count=sum(
            sum(child.tag == camera_source_range_tag for child in client_data)
            for client_data in controls
        ),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        unrecognized_count=unrecognized_count,
        inspected=inspected,
        definition_signature=definition_signature,
        relationship_signature=_worksheet_control_relationship_signature(
            tuple(selected_relationships)
        ),
    )


def _worksheet_embedded_control_metadata(
    path: Path,
) -> _WorksheetEmbeddedControlMetadata:
    """Inspect worksheet controls and OLE data before load time.

    This scan is intentionally package-only: it does not initialize controls,
    deserialize OLE data, open embedded packages, render VML, or follow external
    targets.
    """
    warnings: set[str] = set()
    default = WorksheetEmbeddedControlSnapshot()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                return _WorksheetEmbeddedControlMetadata(
                    default,
                    (
                        "FormulaFence could not map worksheet OOXML for embedded-control "
                        f"inspection ({type(error).__name__}); affected controls were not "
                        "compared.",
                    ),
                )

            xml_budget = _WorksheetEmbeddedControlXmlBudget()
            payload_budget = _WorksheetEmbeddedControlRelatedPartBudget()
            sheet_inspections: list[_WorksheetControlSheetInspection] = []
            active_x_sources: dict[str, set[str]] = defaultdict(set)
            control_property_sources: dict[str, set[str]] = defaultdict(set)
            legacy_vml_sources: dict[str, set[str]] = defaultdict(set)
            legacy_vml_declarations: dict[
                str, list[tuple[str, tuple[str, str, str]]]
            ] = defaultdict(list)
            declared_active_x_members: set[str] = set()
            declared_control_property_members: set[str] = set()
            declared_legacy_vml_members: set[str] = set()
            payload_members: set[str] = set()
            unresolved_payload_entries: list[tuple[str, str]] = []
            declaration_entries: list[tuple[str, str]] = []
            unresolved_legacy_vml_declarations: list[tuple[str, str]] = []

            for _, (member, sheet_kind) in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                if sheet_kind != "worksheet":
                    continue
                inspection = _worksheet_control_sheet_inspection(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                )
                sheet_inspections.append(inspection)
                if inspection.present:
                    declaration_entries.append(
                        (
                            "worksheet-control-part",
                            repr(
                                (
                                    member,
                                    inspection.active_x_members,
                                    inspection.control_property_members,
                                    inspection.payload_members,
                                )
                            ),
                        )
                    )
                for active_x_member in inspection.active_x_members:
                    active_x_sources[active_x_member].add(member)
                    declared_active_x_members.add(active_x_member)
                for control_property_member in inspection.control_property_members:
                    control_property_sources[control_property_member].add(member)
                    declared_control_property_members.add(control_property_member)
                for legacy_vml_member in inspection.legacy_vml_members:
                    legacy_vml_sources[legacy_vml_member].add(member)
                    declared_legacy_vml_members.add(legacy_vml_member)
                for relationship in inspection.legacy_vml_relationships:
                    if relationship.safe_target is None:
                        unresolved_legacy_vml_declarations.append(
                            (member, repr(relationship.semantic_key()))
                        )
                    else:
                        legacy_vml_declarations[relationship.safe_target].append(
                            (member, relationship.semantic_key())
                        )
                payload_members.update(inspection.payload_members)
                unresolved_payload_entries.extend(inspection.unresolved_payload_entries)

            orphan_part_count = 0
            discovered_active_x_members = {
                entry.filename
                for entry in archive.infolist()
                if _WORKSHEET_ACTIVEX_PART_PATTERN.fullmatch(entry.filename)
            }
            for member in discovered_active_x_members:
                active_x_sources.setdefault(member, set())
                if member not in declared_active_x_members:
                    warnings.add(
                        "FormulaFence found an ActiveX control package part not declared "
                        "by an inspected worksheet; the affected controls have a coverage gap."
                    )
                    orphan_part_count += 1

            discovered_control_property_members = {
                entry.filename
                for entry in archive.infolist()
                if _WORKSHEET_CONTROL_PROPERTY_PART_PATTERN.fullmatch(entry.filename)
            }
            for member in discovered_control_property_members:
                control_property_sources.setdefault(member, set())
                if member not in declared_control_property_members:
                    warnings.add(
                        "FormulaFence found a form-control properties package part not declared "
                        "by an inspected worksheet; the affected controls have a coverage gap."
                    )
                    orphan_part_count += 1

            discovered_legacy_vml_members = {
                entry.filename
                for entry in archive.infolist()
                if _WORKSHEET_LEGACY_VML_PART_PATTERN.fullmatch(entry.filename)
            }
            for member in discovered_legacy_vml_members:
                legacy_vml_sources.setdefault(member, set())
                if member not in declared_legacy_vml_members:
                    warnings.add(
                        "FormulaFence found a legacy VML drawing package part not declared "
                        "by an inspected worksheet; the affected controls have a coverage gap."
                    )
                    orphan_part_count += 1

            active_x_inspections: list[_WorksheetControlActiveXInspection] = []
            for member in sorted(active_x_sources, key=str.casefold):
                sources = tuple(sorted(active_x_sources[member], key=str.casefold))
                declaration_entries.append(
                    ("activex-part", repr((member, sources)))
                )
                inspection = _worksheet_control_activex_inspection(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                )
                active_x_inspections.append(inspection)
                payload_members.update(inspection.payload_members)
                unresolved_payload_entries.extend(inspection.unresolved_payload_entries)

            control_property_inspections: list[_WorksheetControlPropertyInspection] = []
            for member in sorted(control_property_sources, key=str.casefold):
                sources = tuple(sorted(control_property_sources[member], key=str.casefold))
                declaration_entries.append(
                    ("form-control-properties-part", repr((member, sources)))
                )
                inspection = _worksheet_control_property_inspection(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                )
                control_property_inspections.append(inspection)
                payload_members.update(inspection.payload_members)
                unresolved_payload_entries.extend(inspection.unresolved_payload_entries)

            legacy_vml_inspections: list[_WorksheetVmlDrawingInspection] = []
            for member in sorted(legacy_vml_sources, key=str.casefold):
                inspection = _worksheet_vml_drawing_inspection(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                )
                legacy_vml_inspections.append(inspection)
                if inspection.present:
                    declarations = tuple(
                        sorted(
                            legacy_vml_declarations.get(member, []),
                            key=repr,
                        )
                    )
                    declaration_entries.append(
                        ("legacy-vml-drawing-part", repr((member, declarations)))
                    )
            declaration_entries.extend(
                ("legacy-vml-worksheet-relationship", repr(declaration))
                for declaration in unresolved_legacy_vml_declarations
            )

            payload_inspection = _worksheet_control_related_part_payloads(
                archive,
                payload_members,
                unresolved_payload_entries,
                warnings,
                payload_budget,
            )

            def aggregate_signature(
                inspections: list[object],
                attribute: str,
            ) -> str | None:
                material = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(material))

            control_sheet_members = {
                inspection.member
                for inspection in sheet_inspections
                if inspection.present
            }
            active_legacy_vml_members = {
                inspection.member
                for inspection in legacy_vml_inspections
                if inspection.present
            }
            active_legacy_vml_source_relationships = [
                relationship
                for inspection in sheet_inspections
                for relationship in inspection.legacy_vml_relationships
                if relationship.safe_target in active_legacy_vml_members
            ]
            for inspection in legacy_vml_inspections:
                if inspection.present:
                    control_sheet_members.update(legacy_vml_sources[inspection.member])
            all_inspections: list[object] = [
                *sheet_inspections,
                *active_x_inspections,
                *control_property_inspections,
                *legacy_vml_inspections,
            ]
            declaration_entries.sort()
            snapshot = WorksheetEmbeddedControlSnapshot(
                control_sheet_count=len(control_sheet_members),
                worksheet_control_count=sum(
                    inspection.worksheet_control_count for inspection in sheet_inspections
                ),
                active_x_part_count=len(active_x_sources),
                active_x_binary_reference_count=sum(
                    inspection.binary_reference_count
                    for inspection in active_x_inspections
                ),
                form_control_property_part_count=len(control_property_sources),
                legacy_vml_drawing_part_count=sum(
                    inspection.present for inspection in legacy_vml_inspections
                ),
                legacy_vml_control_count=sum(
                    inspection.control_count for inspection in legacy_vml_inspections
                ),
                legacy_vml_macro_assignment_count=sum(
                    inspection.macro_assignment_count
                    for inspection in legacy_vml_inspections
                ),
                legacy_vml_cell_link_count=sum(
                    inspection.cell_link_count for inspection in legacy_vml_inspections
                ),
                legacy_vml_source_range_count=sum(
                    inspection.source_range_count
                    for inspection in legacy_vml_inspections
                ),
                legacy_vml_camera_source_range_count=sum(
                    inspection.camera_source_range_count
                    for inspection in legacy_vml_inspections
                ),
                control_macro_assignment_count=sum(
                    inspection.control_macro_assignment_count
                    for inspection in sheet_inspections
                )
                + sum(
                    inspection.macro_assignment_count
                    for inspection in legacy_vml_inspections
                ),
                control_cell_link_count=sum(
                    inspection.control_cell_link_count for inspection in sheet_inspections
                )
                + sum(
                    inspection.cell_link_count
                    for inspection in control_property_inspections
                )
                + sum(
                    inspection.cell_link_count for inspection in legacy_vml_inspections
                ),
                control_source_range_count=sum(
                    inspection.control_source_range_count
                    for inspection in sheet_inspections
                )
                + sum(
                    inspection.source_range_count
                    for inspection in control_property_inspections
                )
                + sum(
                    inspection.source_range_count
                    for inspection in legacy_vml_inspections
                ),
                form_control_formula_binding_count=sum(
                    inspection.formula_binding_count
                    for inspection in control_property_inspections
                ),
                ole_object_count=sum(
                    inspection.ole_object_count for inspection in sheet_inspections
                ),
                linked_ole_object_count=sum(
                    inspection.linked_ole_object_count for inspection in sheet_inspections
                ),
                auto_load_ole_object_count=sum(
                    inspection.auto_load_ole_object_count for inspection in sheet_inspections
                ),
                auto_update_ole_object_count=sum(
                    inspection.auto_update_ole_object_count
                    for inspection in sheet_inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in all_inspections
                )
                + len(active_legacy_vml_source_relationships),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in all_inspections
                )
                + sum(
                    relationship.target_mode.casefold() != "internal"
                    for relationship in active_legacy_vml_source_relationships
                ),
                internal_related_part_count=payload_inspection.internal_part_count,
                fingerprinted_related_part_count=payload_inspection.fingerprinted_part_count,
                uninspected_related_part_count=payload_inspection.uninspected_part_count,
                unrecognized_part_count=orphan_part_count
                + sum(inspection.unrecognized_count for inspection in all_inspections)
                + sum(
                    inspection.legacy_vml_unrecognized_count
                    for inspection in sheet_inspections
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(declaration_entries)
                ),
                control_definition_signature=aggregate_signature(
                    list(sheet_inspections),
                    "definition_signature",
                ),
                active_x_definition_signature=aggregate_signature(
                    list(active_x_inspections),
                    "definition_signature",
                ),
                form_control_property_signature=aggregate_signature(
                    list(control_property_inspections),
                    "definition_signature",
                ),
                legacy_vml_definition_signature=aggregate_signature(
                    list(legacy_vml_inspections),
                    "definition_signature",
                ),
                legacy_vml_relationship_signature=aggregate_signature(
                    list(legacy_vml_inspections),
                    "relationship_signature",
                ),
                relationship_signature=aggregate_signature(
                    all_inspections,
                    "relationship_signature",
                ),
                related_part_payload_signature=payload_inspection.payload_signature,
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _WorksheetEmbeddedControlMetadata(
            default,
            (
                "FormulaFence could not inspect worksheet embedded-control OOXML "
                f"({type(error).__name__}); affected controls were not compared.",
            ),
        )
    return _WorksheetEmbeddedControlMetadata(snapshot, tuple(sorted(warnings)))


def _dynamic_array_metadata_coverage_signature(
    archive: ZipFile,
    info: ZipInfo,
    *,
    reason: str,
) -> str:
    """Fingerprint an unread dynamic-array metadata part without retaining it."""
    metadata = repr((info.filename, info.file_size, info.compress_size, info.CRC))
    entries: list[tuple[str, str]] = [
        ("dynamic-array-metadata-coverage-gap", reason),
        ("metadata", metadata),
    ]
    if (
        payload_signature := _private_archive_member_payload_signature(archive, info)
    ) is not None:
        entries.append(("payload", payload_signature))
    return _private_external_data_signature(tuple(entries))


def _dynamic_array_metadata_failure(
    archive: ZipFile,
    info: ZipInfo,
    *,
    reason: str,
    warning: str,
) -> _DynamicArrayMetadataInspection:
    """Return fail-closed dynamic-array metadata coverage evidence."""
    return _DynamicArrayMetadataInspection(
        dynamic_indexes=frozenset(),
        complete=False,
        coverage_signature=_dynamic_array_metadata_coverage_signature(
            archive,
            info,
            reason=reason,
        ),
        warnings=(warning,),
    )


def _dynamic_metadata_indexes(archive: ZipFile) -> _DynamicArrayMetadataInspection:
    """Return bounded dynamic-array indexes from the canonical metadata part."""
    try:
        info = archive.getinfo("xl/metadata.xml")
    except KeyError:
        return _DynamicArrayMetadataInspection(
            dynamic_indexes=frozenset(),
            complete=True,
            coverage_signature=None,
            warnings=(),
        )
    if info.file_size > _DYNAMIC_ARRAY_METADATA_MAX_XML_PART_BYTES:
        return _dynamic_array_metadata_failure(
            archive,
            info,
            reason="oversized-metadata-part",
            warning=(
                "FormulaFence did not fully read an oversized dynamic-array metadata "
                "XML part; dynamic-array output aliases were not traced."
            ),
        )
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            info.filename,
            maximum_element_count=_DYNAMIC_ARRAY_METADATA_MAX_XML_ELEMENT_COUNT,
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        return _dynamic_array_metadata_failure(
            archive,
            info,
            reason=f"stream-parse-{type(error).__name__}",
            warning=(
                "FormulaFence could not inspect array-formula OOXML metadata "
                f"({type(error).__name__}); fixed CSE output aliases were not traced."
            ),
        )
    if element_count is None:
        return _dynamic_array_metadata_failure(
            archive,
            info,
            reason="xml-structure-budget-exhausted",
            warning=(
                "FormulaFence did not fully read dynamic-array metadata XML whose XML "
                "structure exceeds the safety budget; dynamic-array output aliases "
                "were not traced."
            ),
        )
    try:
        metadata = _xml_root(archive, info.filename)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        return _dynamic_array_metadata_failure(
            archive,
            info,
            reason=f"tree-parse-{type(error).__name__}",
            warning=(
                "FormulaFence could not inspect array-formula OOXML metadata "
                f"({type(error).__name__}); fixed CSE output aliases were not traced."
            ),
        )

    def tag(name: str) -> str:
        return f"{{{_SPREADSHEETML_NS}}}{name}"

    metadata_types = [
        metadata_type.get("name", "")
        for metadata_type in metadata.findall(f"./{tag('metadataTypes')}/{tag('metadataType')}")
    ]
    dynamic_future_indexes: dict[str, set[int]] = {}
    dynamic_properties_tag = f"{{{_DYNAMIC_ARRAY_NS}}}dynamicArrayProperties"
    for future_metadata in metadata.findall(tag("futureMetadata")):
        name = future_metadata.get("name")
        if not name:
            continue
        dynamic_indexes: set[int] = set()
        for index, metadata_block in enumerate(future_metadata.findall(tag("bk"))):
            if any(
                element.tag == dynamic_properties_tag
                and element.get("fDynamic", "").casefold() in {"1", "true"}
                for element in metadata_block.iter()
            ):
                dynamic_indexes.add(index)
        if dynamic_indexes:
            dynamic_future_indexes[name] = dynamic_indexes

    cell_metadata = metadata.find(tag("cellMetadata"))
    if cell_metadata is None:
        return _DynamicArrayMetadataInspection(
            dynamic_indexes=frozenset(),
            complete=True,
            coverage_signature=None,
            warnings=(),
        )
    dynamic_cell_indexes: set[int] = set()
    for cell_index, metadata_block in enumerate(cell_metadata.findall(tag("bk")), start=1):
        for record in metadata_block.findall(tag("rc")):
            try:
                type_index = int(record.get("t", ""))
                value_index = int(record.get("v", ""))
            except ValueError:
                continue
            if not 1 <= type_index <= len(metadata_types):
                continue
            type_name = metadata_types[type_index - 1]
            if value_index in dynamic_future_indexes.get(type_name, set()):
                dynamic_cell_indexes.add(cell_index)
                break
    return _DynamicArrayMetadataInspection(
        dynamic_indexes=frozenset(dynamic_cell_indexes),
        complete=True,
        coverage_signature=None,
        warnings=(),
    )


_WHAT_IF_DATA_TABLE_FORMULA_TYPE = "dataTable"
_WHAT_IF_DATA_TABLE_KNOWN_ATTRIBUTES = frozenset(
    {
        "t",
        "aca",
        "ref",
        "dt2D",
        "dtr",
        "del1",
        "del2",
        "r1",
        "r2",
        "ca",
        "si",
        "bx",
    }
)


def _canonical_what_if_data_table_range(
    value: str | None,
) -> tuple[str | None, tuple[int, int, int, int] | None]:
    """Normalize a local A1 range without accepting unbounded sheet spans."""
    if value is None or not (candidate := value.strip()):
        return None, None
    try:
        min_column, min_row, max_column, max_row = range_boundaries(candidate)
    except ValueError:
        return None, None
    if (
        min_column is None
        or min_row is None
        or max_column is None
        or max_row is None
        or min_column < 1
        or min_row < 1
        or max_column > MAX_EXCEL_COLUMN
        or max_row > MAX_EXCEL_ROW
    ):
        return None, None
    anchor = f"{get_column_letter(min_column)}{min_row}"
    endpoint = f"{get_column_letter(max_column)}{max_row}"
    return (
        anchor if anchor == endpoint else f"{anchor}:{endpoint}",
        (min_column, min_row, max_column, max_row),
    )


def _canonical_what_if_data_table_cell(value: str | None) -> str | None:
    """Normalize a local single-cell input reference from a Data Table."""
    reference, bounds = _canonical_what_if_data_table_range(value)
    if bounds is None:
        return None
    min_column, min_row, max_column, max_row = bounds
    if min_column != max_column or min_row != max_row:
        return None
    return reference


def _what_if_data_table_boolean(
    value: str | None,
    default: bool = False,
) -> tuple[bool | None, str]:
    """Read one OOXML boolean while retaining malformed material privately."""
    if value is None:
        return default, "true" if default else "false"
    lowered = value.casefold()
    if lowered in {"1", "true"}:
        return True, "true"
    if lowered in {"0", "false"}:
        return False, "false"
    return None, f"invalid:{value}"


def _what_if_data_table_shared_index(value: str | None) -> tuple[int | None, str]:
    """Canonicalize the optional generic formula shared-index attribute."""
    if value is None:
        return None, "none"
    if value.isascii() and value.isdecimal():
        return int(value), str(int(value))
    return None, f"invalid:{value}"


def _what_if_data_table_metadata(path: Path) -> _WhatIfDataTableMetadata:
    """Inventory Excel What-If Data Table masters directly from worksheet XML.

    The declarations are data-bearing sensitivity controls rather than ordinary
    formulas. Raw OOXML is read before openpyxl can reduce them to unstable
    object representations, while private signatures keep all table ranges and
    input-cell references out of emitted artifacts.
    """
    warnings: set[str] = set()
    default = WhatIfDataTableSnapshot()
    definitions: list[_WhatIfDataTableDefinition] = []
    try:
        with ZipFile(path) as archive:
            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            formula_tag = f"{{{_SPREADSHEETML_NS}}}f"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                for cell in worksheet.iter(cell_tag):
                    formulas = cell.findall(formula_tag)
                    for formula in formulas:
                        if formula.get("t") != _WHAT_IF_DATA_TABLE_FORMULA_TYPE:
                            continue

                        issues: set[str] = set()
                        coordinate_raw = cell.get("r")
                        coordinate = _canonical_what_if_data_table_cell(coordinate_raw)
                        if coordinate is None:
                            issues.add("invalid-master-coordinate")

                        ref_raw = formula.get("ref")
                        ref, bounds = _canonical_what_if_data_table_range(ref_raw)
                        if bounds is None:
                            issues.add("invalid-output-range")

                        dt2d, dt2d_signature = _what_if_data_table_boolean(
                            formula.get("dt2D")
                        )
                        dtr, dtr_signature = _what_if_data_table_boolean(
                            formula.get("dtr")
                        )
                        deleted_input_1, deleted_input_1_signature = (
                            _what_if_data_table_boolean(formula.get("del1"))
                        )
                        deleted_input_2, deleted_input_2_signature = (
                            _what_if_data_table_boolean(formula.get("del2"))
                        )
                        recalculate, recalculate_signature = _what_if_data_table_boolean(
                            formula.get("ca")
                        )
                        always_calculate, always_calculate_signature = (
                            _what_if_data_table_boolean(formula.get("aca"))
                        )
                        assigns_name, assigns_name_signature = _what_if_data_table_boolean(
                            formula.get("bx")
                        )
                        shared_index, shared_index_signature = (
                            _what_if_data_table_shared_index(formula.get("si"))
                        )
                        boolean_values = (
                            dt2d,
                            dtr,
                            deleted_input_1,
                            deleted_input_2,
                            recalculate,
                            always_calculate,
                            assigns_name,
                        )
                        if any(value is None for value in boolean_values):
                            issues.add("invalid-boolean")
                        if formula.get("si") is not None and shared_index is None:
                            issues.add("invalid-shared-index")
                        if always_calculate is True or assigns_name is True:
                            issues.add("unmodelled-generic-formula-control")
                        if shared_index is not None:
                            issues.add("unexpected-shared-index")

                        input_1_raw = formula.get("r1")
                        input_2_raw = formula.get("r2")
                        input_1 = _canonical_what_if_data_table_cell(input_1_raw)
                        input_2 = _canonical_what_if_data_table_cell(input_2_raw)
                        if input_1_raw is not None and input_1 is None:
                            issues.add("invalid-first-input")
                        if input_2_raw is not None and input_2 is None:
                            issues.add("invalid-second-input")

                        if bounds is not None and coordinate is not None:
                            min_column, min_row, _, _ = bounds
                            expected_anchor = f"{get_column_letter(min_column)}{min_row}"
                            if coordinate != expected_anchor:
                                issues.add("master-does-not-match-output-range")

                        if dt2d is True:
                            if input_1 is None and deleted_input_1 is not True:
                                issues.add("missing-first-input")
                            if input_2 is None and deleted_input_2 is not True:
                                issues.add("missing-second-input")
                            if dtr is True:
                                issues.add("row-orientation-on-two-variable-table")
                        elif dt2d is False:
                            if input_1 is None and deleted_input_1 is not True:
                                issues.add("missing-first-input")
                            if input_2_raw is not None or deleted_input_2 is True:
                                issues.add("second-input-on-one-variable-table")

                        unknown_attributes = tuple(
                            sorted(
                                (
                                    _xml_display_name(attribute),
                                    value,
                                )
                                for attribute, value in formula.attrib.items()
                                if attribute not in _WHAT_IF_DATA_TABLE_KNOWN_ATTRIBUTES
                            )
                        )
                        if unknown_attributes:
                            issues.add("unknown-attributes")
                        formula_text = (formula.text or "").strip()
                        if formula_text:
                            issues.add("unexpected-formula-text")
                        child_signatures = tuple(
                            _private_payload_signature(
                                ElementTree.tostring(child, encoding="utf-8")
                            )
                            for child in formula
                        )
                        if child_signatures:
                            issues.add("unexpected-formula-children")
                        if len(formulas) != 1:
                            issues.add("multiple-cell-formulas")

                        coordinate_signature = (
                            coordinate
                            if coordinate is not None
                            else f"invalid:{coordinate_raw or ''}"
                        )
                        ref_signature = (
                            ref if ref is not None else f"invalid:{ref_raw or ''}"
                        )
                        input_1_signature = (
                            input_1
                            if input_1 is not None
                            else "none"
                            if input_1_raw is None
                            else f"invalid:{input_1_raw}"
                        )
                        input_2_signature = (
                            input_2
                            if input_2 is not None
                            else "none"
                            if input_2_raw is None
                            else f"invalid:{input_2_raw}"
                        )
                        signature_material = (
                            ("coordinate", coordinate_signature),
                            ("ref", ref_signature),
                            ("dt2D", dt2d_signature),
                            ("dtr", dtr_signature),
                            ("del1", deleted_input_1_signature),
                            ("del2", deleted_input_2_signature),
                            ("r1", input_1_signature),
                            ("r2", input_2_signature),
                            ("ca", recalculate_signature),
                            ("aca", always_calculate_signature),
                            ("bx", assigns_name_signature),
                            ("si", shared_index_signature),
                            ("unknown_attributes", repr(unknown_attributes)),
                            ("formula_text", formula_text),
                            ("child_signatures", repr(child_signatures)),
                            ("formula_count", str(len(formulas))),
                        )
                        definitions.append(
                            _WhatIfDataTableDefinition(
                                sheet=sheet,
                                coordinate=coordinate,
                                ref=ref,
                                min_column=bounds[0] if bounds is not None else None,
                                min_row=bounds[1] if bounds is not None else None,
                                max_column=bounds[2] if bounds is not None else None,
                                max_row=bounds[3] if bounds is not None else None,
                                two_dimensional=dt2d,
                                row_oriented=dtr,
                                recalculation_requested=recalculate,
                                deleted_input_reference_count=sum(
                                    value is True
                                    for value in (
                                        deleted_input_1,
                                        deleted_input_2,
                                    )
                                ),
                                signature_entry=(
                                    f"{sheet.casefold()}!{coordinate_signature}",
                                    repr(signature_material),
                                ),
                                issues=issues,
                            )
                        )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _WhatIfDataTableMetadata(
            default,
            (
                "FormulaFence could not inspect What-If Data Table OOXML "
                f"({type(error).__name__}); affected sensitivity controls were not compared.",
            ),
        )

    definitions_by_sheet: dict[str, list[_WhatIfDataTableDefinition]] = defaultdict(list)
    for definition in definitions:
        if None not in {
            definition.min_column,
            definition.min_row,
            definition.max_column,
            definition.max_row,
        }:
            definitions_by_sheet[definition.sheet.casefold()].append(definition)
    overlap_found = False
    for sheet_definitions in definitions_by_sheet.values():
        for index, definition in enumerate(sheet_definitions):
            for other in sheet_definitions[index + 1 :]:
                if (
                    definition.min_column <= other.max_column
                    and other.min_column <= definition.max_column
                    and definition.min_row <= other.max_row
                    and other.min_row <= definition.max_row
                ):
                    definition.issues.add("overlapping-output-ranges")
                    other.issues.add("overlapping-output-ranges")
                    overlap_found = True
    if overlap_found:
        warnings.add(
            "FormulaFence found overlapping What-If Data Table output ranges; "
            "the affected sensitivity controls have a coverage gap."
        )
    if any(definition.issues for definition in definitions):
        warnings.add(
            "FormulaFence found malformed or unsupported What-If Data Table formula "
            "metadata; the affected sensitivity controls have a coverage gap."
        )

    snapshot = WhatIfDataTableSnapshot(
        data_table_count=len(definitions),
        one_variable_data_table_count=sum(
            definition.two_dimensional is False for definition in definitions
        ),
        two_variable_data_table_count=sum(
            definition.two_dimensional is True for definition in definitions
        ),
        one_variable_row_oriented_count=sum(
            definition.two_dimensional is False and definition.row_oriented is True
            for definition in definitions
        ),
        one_variable_column_oriented_count=sum(
            definition.two_dimensional is False and definition.row_oriented is False
            for definition in definitions
        ),
        declared_output_cell_count=sum(
            (definition.max_column - definition.min_column + 1)
            * (definition.max_row - definition.min_row + 1)
            for definition in definitions
            if None
            not in {
                definition.min_column,
                definition.min_row,
                definition.max_column,
                definition.max_row,
            }
        ),
        recalculation_requested_count=sum(
            definition.recalculation_requested is True for definition in definitions
        ),
        deleted_input_reference_count=sum(
            definition.deleted_input_reference_count for definition in definitions
        ),
        unrecognized_data_table_count=sum(
            bool(definition.issues) for definition in definitions
        ),
        definition_signature=_private_external_data_signature(
            tuple(sorted(definition.signature_entry for definition in definitions))
        ),
    )
    return _WhatIfDataTableMetadata(snapshot, tuple(sorted(warnings)))


_SCENARIO_MANAGER_KNOWN_ATTRIBUTES = frozenset({"current", "show", "sqref"})
_SCENARIO_MANAGER_SCENARIO_KNOWN_ATTRIBUTES = frozenset(
    {"name", "locked", "hidden", "count", "user", "comment"}
)
_SCENARIO_MANAGER_INPUT_KNOWN_ATTRIBUTES = frozenset(
    {"r", "deleted", "undone", "val", "numFmtId"}
)
_SCENARIO_MANAGER_UNSIGNED_INT_MAXIMUM = 4_294_967_295


def _scenario_manager_unsigned_int(value: str | None) -> tuple[int | None, str]:
    """Canonicalize one unsigned Scenario Manager integer attribute."""
    if value is None:
        return None, "none"
    candidate = value.strip()
    if candidate.isascii() and candidate.isdecimal():
        parsed = int(candidate)
        if parsed <= _SCENARIO_MANAGER_UNSIGNED_INT_MAXIMUM:
            return parsed, str(parsed)
    return None, f"invalid:{value}"


def _scenario_manager_summary_references(
    value: str | None,
) -> tuple[tuple[str, ...] | None, str]:
    """Normalize local Scenario Manager summary references without exposing them."""
    if value is None or not value.strip():
        return (), "none"
    references: list[str] = []
    for raw_reference in value.split():
        reference, _ = _canonical_what_if_data_table_range(raw_reference)
        if reference is None:
            return None, f"invalid:{value}"
        references.append(reference)
    return tuple(references), " ".join(references)


def _scenario_manager_metadata(path: Path) -> _ScenarioManagerMetadata:
    """Inventory Excel Scenario Manager definitions directly from worksheet XML.

    Scenario Manager persists alternate input values, names, comments, user
    details, and summary targets outside ordinary cells. The raw OOXML pass is
    therefore performed before openpyxl can omit those declarations. All
    values and references remain inside a private signature.
    """
    warnings: set[str] = set()
    default = ScenarioManagerSnapshot()
    definitions: list[_ScenarioManagerDefinition] = []
    try:
        with ZipFile(path) as archive:
            scenarios_tag = f"{{{_SPREADSHEETML_NS}}}scenarios"
            scenario_tag = f"{{{_SPREADSHEETML_NS}}}scenario"
            input_cell_tag = f"{{{_SPREADSHEETML_NS}}}inputCells"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                scenario_containers = list(worksheet.findall(scenarios_tag))
                for container_index, container in enumerate(scenario_containers):
                    issues: set[str] = set()
                    if len(scenario_containers) != 1:
                        issues.add("multiple-scenarios-containers")

                    unknown_attributes = tuple(
                        sorted(
                            (
                                _xml_display_name(attribute),
                                value,
                            )
                            for attribute, value in container.attrib.items()
                            if attribute not in _SCENARIO_MANAGER_KNOWN_ATTRIBUTES
                        )
                    )
                    if unknown_attributes:
                        issues.add("unknown-container-attributes")

                    scenario_elements = [
                        child for child in container if child.tag == scenario_tag
                    ]
                    unknown_child_signatures = tuple(
                        _private_payload_signature(
                            ElementTree.tostring(child, encoding="utf-8")
                        )
                        for child in container
                        if child.tag != scenario_tag
                    )
                    if unknown_child_signatures:
                        issues.add("unknown-container-children")
                    if not scenario_elements:
                        issues.add("missing-scenarios")

                    current, current_signature = _scenario_manager_unsigned_int(
                        container.get("current")
                    )
                    shown, shown_signature = _scenario_manager_unsigned_int(
                        container.get("show")
                    )
                    if container.get("current") is not None and current is None:
                        issues.add("invalid-current-scenario")
                    if container.get("show") is not None and shown is None:
                        issues.add("invalid-shown-scenario")
                    if current is not None and current >= len(scenario_elements):
                        issues.add("current-scenario-out-of-range")
                    if shown is not None and shown >= len(scenario_elements):
                        issues.add("shown-scenario-out-of-range")

                    summary_references, summary_reference_signature = (
                        _scenario_manager_summary_references(container.get("sqref"))
                    )
                    if summary_references is None:
                        issues.add("invalid-summary-references")
                        summary_reference_count = 0
                    else:
                        summary_reference_count = len(summary_references)

                    scenarios: list[_ScenarioManagerScenario] = []
                    for scenario_element in scenario_elements:
                        scenario_issues: set[str] = set()
                        name = scenario_element.get("name")
                        if name is None or not name.strip():
                            scenario_issues.add("missing-scenario-name")
                            name_key = None
                            name_signature = "missing" if name is None else f"invalid:{name}"
                        else:
                            name_key = name.casefold()
                            name_signature = name

                        locked, locked_signature = _what_if_data_table_boolean(
                            scenario_element.get("locked")
                        )
                        hidden, hidden_signature = _what_if_data_table_boolean(
                            scenario_element.get("hidden")
                        )
                        if locked is None or hidden is None:
                            scenario_issues.add("invalid-scenario-boolean")

                        input_elements = [
                            child
                            for child in scenario_element
                            if child.tag == input_cell_tag
                        ]
                        unknown_scenario_child_signatures = tuple(
                            _private_payload_signature(
                                ElementTree.tostring(child, encoding="utf-8")
                            )
                            for child in scenario_element
                            if child.tag != input_cell_tag
                        )
                        if unknown_scenario_child_signatures:
                            scenario_issues.add("unknown-scenario-children")
                        if not input_elements:
                            scenario_issues.add("missing-input-cells")

                        declared_count, declared_count_signature = (
                            _scenario_manager_unsigned_int(scenario_element.get("count"))
                        )
                        if scenario_element.get("count") is not None and declared_count is None:
                            scenario_issues.add("invalid-input-cell-count")
                        elif (
                            declared_count is not None
                            and declared_count != len(input_elements)
                        ):
                            scenario_issues.add("mismatched-input-cell-count")
                        elif declared_count is None:
                            declared_count_signature = str(len(input_elements))

                        unknown_scenario_attributes = tuple(
                            sorted(
                                (
                                    _xml_display_name(attribute),
                                    value,
                                )
                                for attribute, value in scenario_element.attrib.items()
                                if attribute
                                not in _SCENARIO_MANAGER_SCENARIO_KNOWN_ATTRIBUTES
                            )
                        )
                        if unknown_scenario_attributes:
                            scenario_issues.add("unknown-scenario-attributes")

                        input_signatures: list[tuple[tuple[str, str], ...]] = []
                        input_references: set[str] = set()
                        deleted_input_cell_count = 0
                        undone_input_cell_count = 0
                        formatted_input_cell_count = 0
                        for input_element in input_elements:
                            input_issues: set[str] = set()
                            raw_reference = input_element.get("r")
                            reference = _canonical_what_if_data_table_cell(raw_reference)
                            if reference is None:
                                input_issues.add("invalid-input-reference")
                                reference_signature = (
                                    "missing"
                                    if raw_reference is None
                                    else f"invalid:{raw_reference}"
                                )
                            else:
                                reference_signature = reference
                                if reference.casefold() in input_references:
                                    input_issues.add("duplicate-input-reference")
                                input_references.add(reference.casefold())

                            value = input_element.get("val")
                            if value is None:
                                input_issues.add("missing-input-value")
                                value_signature = "missing"
                            else:
                                value_signature = value

                            deleted, deleted_signature = _what_if_data_table_boolean(
                                input_element.get("deleted")
                            )
                            undone, undone_signature = _what_if_data_table_boolean(
                                input_element.get("undone")
                            )
                            if deleted is None or undone is None:
                                input_issues.add("invalid-input-boolean")
                            if deleted is True:
                                deleted_input_cell_count += 1
                            if undone is True:
                                undone_input_cell_count += 1

                            number_format, number_format_signature = (
                                _scenario_manager_unsigned_int(
                                    input_element.get("numFmtId")
                                )
                            )
                            if input_element.get("numFmtId") is not None:
                                if number_format is None:
                                    input_issues.add("invalid-input-number-format")
                                else:
                                    formatted_input_cell_count += 1

                            unknown_input_attributes = tuple(
                                sorted(
                                    (
                                        _xml_display_name(attribute),
                                        raw_value,
                                    )
                                    for attribute, raw_value in input_element.attrib.items()
                                    if attribute
                                    not in _SCENARIO_MANAGER_INPUT_KNOWN_ATTRIBUTES
                                )
                            )
                            if unknown_input_attributes:
                                input_issues.add("unknown-input-attributes")
                            input_child_signatures = tuple(
                                _private_payload_signature(
                                    ElementTree.tostring(child, encoding="utf-8")
                                )
                                for child in input_element
                            )
                            if input_child_signatures:
                                input_issues.add("unexpected-input-children")
                            scenario_issues.update(input_issues)
                            input_signatures.append(
                                (
                                    ("reference", reference_signature),
                                    ("value", value_signature),
                                    ("deleted", deleted_signature),
                                    ("undone", undone_signature),
                                    ("number_format", number_format_signature),
                                    (
                                        "unknown_attributes",
                                        repr(unknown_input_attributes),
                                    ),
                                    ("child_signatures", repr(input_child_signatures)),
                                )
                            )

                        scenarios.append(
                            _ScenarioManagerScenario(
                                sheet=sheet,
                                name_key=name_key,
                                locked=locked,
                                hidden=hidden,
                                input_cell_count=len(input_elements),
                                has_comment=scenario_element.get("comment") is not None,
                                has_user=scenario_element.get("user") is not None,
                                deleted_input_cell_count=deleted_input_cell_count,
                                undone_input_cell_count=undone_input_cell_count,
                                formatted_input_cell_count=formatted_input_cell_count,
                                signature=(
                                    ("name", name_signature),
                                    ("locked", locked_signature),
                                    ("hidden", hidden_signature),
                                    ("count", declared_count_signature),
                                    (
                                        "user",
                                        scenario_element.get("user", "none"),
                                    ),
                                    (
                                        "comment",
                                        scenario_element.get("comment", "none"),
                                    ),
                                    (
                                        "input_cells",
                                        repr(tuple(sorted(input_signatures))),
                                    ),
                                    (
                                        "unknown_attributes",
                                        repr(unknown_scenario_attributes),
                                    ),
                                    (
                                        "child_signatures",
                                        repr(unknown_scenario_child_signatures),
                                    ),
                                ),
                                issues=scenario_issues,
                            )
                        )

                    definitions.append(
                        _ScenarioManagerDefinition(
                            sheet=sheet,
                            current_scenario_selected=current is not None,
                            shown_scenario_selected=shown is not None,
                            summary_reference_count=summary_reference_count,
                            signature_prefix=(
                                ("current", current_signature),
                                ("show", shown_signature),
                                ("summary_references", summary_reference_signature),
                                ("unknown_attributes", repr(unknown_attributes)),
                                ("child_signatures", repr(unknown_child_signatures)),
                                ("container_index", str(container_index)),
                            ),
                            scenarios=scenarios,
                            issues=issues,
                        )
                    )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _ScenarioManagerMetadata(
            default,
            (
                "FormulaFence could not inspect Scenario Manager OOXML "
                f"({type(error).__name__}); affected what-if controls were not compared.",
            ),
        )

    scenarios_by_sheet_and_name: dict[
        tuple[str, str], list[_ScenarioManagerScenario]
    ] = defaultdict(list)
    for definition in definitions:
        for scenario in definition.scenarios:
            if scenario.name_key is not None:
                scenarios_by_sheet_and_name[
                    (scenario.sheet.casefold(), scenario.name_key)
                ].append(scenario)
    for matching_scenarios in scenarios_by_sheet_and_name.values():
        if len(matching_scenarios) > 1:
            for scenario in matching_scenarios:
                scenario.issues.add("duplicate-scenario-name")

    if any(
        definition.issues or any(scenario.issues for scenario in definition.scenarios)
        for definition in definitions
    ):
        warnings.add(
            "FormulaFence found malformed or unsupported Scenario Manager metadata; "
            "the affected what-if controls have a coverage gap."
        )

    signature_entries = tuple(
        sorted(
            (
                f"{definition.sheet.casefold()}:{index}",
                repr(
                    (
                        definition.signature_prefix,
                        tuple(scenario.signature for scenario in definition.scenarios),
                    )
                ),
            )
            for index, definition in enumerate(definitions)
        )
    )
    snapshot = ScenarioManagerSnapshot(
        scenario_sheet_count=len({definition.sheet.casefold() for definition in definitions}),
        scenario_count=sum(len(definition.scenarios) for definition in definitions),
        input_cell_count=sum(
            scenario.input_cell_count
            for definition in definitions
            for scenario in definition.scenarios
        ),
        locked_scenario_count=sum(
            scenario.locked is True
            for definition in definitions
            for scenario in definition.scenarios
        ),
        hidden_scenario_count=sum(
            scenario.hidden is True
            for definition in definitions
            for scenario in definition.scenarios
        ),
        scenario_with_comment_count=sum(
            scenario.has_comment
            for definition in definitions
            for scenario in definition.scenarios
        ),
        scenario_with_user_count=sum(
            scenario.has_user
            for definition in definitions
            for scenario in definition.scenarios
        ),
        summary_reference_count=sum(
            definition.summary_reference_count for definition in definitions
        ),
        current_scenario_selection_count=sum(
            definition.current_scenario_selected for definition in definitions
        ),
        shown_scenario_selection_count=sum(
            definition.shown_scenario_selected for definition in definitions
        ),
        deleted_input_cell_count=sum(
            scenario.deleted_input_cell_count
            for definition in definitions
            for scenario in definition.scenarios
        ),
        undone_input_cell_count=sum(
            scenario.undone_input_cell_count
            for definition in definitions
            for scenario in definition.scenarios
        ),
        formatted_input_cell_count=sum(
            scenario.formatted_input_cell_count
            for definition in definitions
            for scenario in definition.scenarios
        ),
        unrecognized_scenario_count=sum(
            bool(definition.issues) + sum(
                bool(scenario.issues) for scenario in definition.scenarios
            )
            for definition in definitions
        ),
        definition_signature=_private_external_data_signature(signature_entries),
    )
    return _ScenarioManagerMetadata(snapshot, tuple(sorted(warnings)))


_IGNORED_ERROR_EXTENSION_NS = (
    "http://schemas.microsoft.com/office/spreadsheetml/2009/9/main"
)
_IGNORED_ERROR_FLAG_ATTRIBUTES = (
    "evalError",
    "formula",
    "formulaRange",
    "unlockedFormula",
    "emptyCellReference",
    "listDataValidation",
    "calculatedColumn",
    "numberStoredAsText",
    "twoDigitTextYear",
)
_IGNORED_ERROR_KNOWN_ATTRIBUTES = frozenset(
    {"sqref", *_IGNORED_ERROR_FLAG_ATTRIBUTES}
)


def _ignored_error_ranges(value: str | None) -> tuple[str, ...] | None:
    """Normalize private local ignored-error target ranges without emitting them."""
    if value is None or not (candidate := value.strip()):
        return None
    ranges: set[str] = set()
    for raw_range in candidate.split():
        reference, bounds = _canonical_what_if_data_table_range(raw_range)
        if reference is None or bounds is None:
            return None
        ranges.add(reference)
    return tuple(sorted(ranges, key=str.casefold)) or None


def _ignored_error_opaque_signature(element: ElementTree.Element) -> str:
    """Fingerprint unsupported ignored-error XML without serializing it."""
    return _private_payload_signature(ElementTree.tostring(element, encoding="utf-8"))


def _ignored_error_metadata(path: Path) -> _IgnoredErrorMetadata:
    """Inspect Excel error-warning suppressions before a reader can discard them.

    Standard SpreadsheetML declarations and Office 2010's extension form both
    hold private target ranges. Canonical comparison keeps those ranges inside a
    digest; emitted profiles report only the kinds and counts of warnings that
    have been suppressed.
    """
    warnings: set[str] = set()
    default = IgnoredErrorSnapshot()
    signature_entries: list[tuple[str, str]] = []
    semantic_ranges: dict[tuple[str, str], set[str]] = defaultdict(set)
    worksheets_with_controls: set[str] = set()
    standard_container_count = 0
    extension_container_count = 0
    unrecognized_ignored_error_count = 0

    def inspect_container(
        container: ElementTree.Element,
        *,
        sheet: str,
        kind: str,
        container_index: int,
        namespace: str,
    ) -> None:
        nonlocal unrecognized_ignored_error_count
        container_issues: set[str] = set()
        error_tag = f"{{{namespace}}}ignoredError"
        extension_tag = f"{{{namespace}}}extLst"
        unknown_attributes = tuple(
            sorted(
                (
                    _xml_display_name(attribute),
                    value,
                )
                for attribute, value in container.attrib.items()
            )
        )
        if unknown_attributes:
            container_issues.add("unknown-container-attributes")
        if (container.text or "").strip():
            container_issues.add("unexpected-container-text")

        rules: list[ElementTree.Element] = []
        for child in container:
            if child.tag == error_tag:
                rules.append(child)
                continue
            if child.tag == extension_tag:
                if child.attrib or list(child) or (child.text or "").strip():
                    container_issues.add("unsupported-container-extension")
                continue
            container_issues.add("unexpected-container-child")

        for rule_index, rule in enumerate(rules):
            rule_issues: set[str] = set()
            ranges = _ignored_error_ranges(rule.get("sqref"))
            if ranges is None:
                rule_issues.add("invalid-target-ranges")

            enabled_flags: list[str] = []
            for flag in _IGNORED_ERROR_FLAG_ATTRIBUTES:
                enabled, _ = _what_if_data_table_boolean(rule.get(flag))
                if enabled is None:
                    rule_issues.add(f"invalid-{flag}")
                elif enabled:
                    enabled_flags.append(flag)
            if not enabled_flags:
                rule_issues.add("no-enabled-error-types")

            unknown_rule_attributes = tuple(
                sorted(
                    (
                        _xml_display_name(attribute),
                        value,
                    )
                    for attribute, value in rule.attrib.items()
                    if attribute not in _IGNORED_ERROR_KNOWN_ATTRIBUTES
                )
            )
            if unknown_rule_attributes:
                rule_issues.add("unknown-rule-attributes")
            if list(rule):
                rule_issues.add("unexpected-rule-children")
            if (rule.text or "").strip():
                rule_issues.add("unexpected-rule-text")

            if ranges is not None:
                for flag in enabled_flags:
                    semantic_ranges[(sheet.casefold(), flag)].update(ranges)
            if rule_issues:
                unrecognized_ignored_error_count += 1
                signature_entries.append(
                    (
                        f"ignored-error-opaque:{sheet.casefold()}:{kind}:"
                        f"{container_index}:{rule_index}",
                        _ignored_error_opaque_signature(rule),
                    )
                )

        if container_issues:
            unrecognized_ignored_error_count += 1
            signature_entries.append(
                (
                    f"ignored-errors-container-opaque:{sheet.casefold()}:{kind}:"
                    f"{container_index}",
                    _ignored_error_opaque_signature(container),
                )
            )

    try:
        with ZipFile(path) as archive:
            standard_tag = f"{{{_SPREADSHEETML_NS}}}ignoredErrors"
            extension_tag = f"{{{_IGNORED_ERROR_EXTENSION_NS}}}ignoredErrors"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                standard_containers = list(worksheet.findall(standard_tag))
                extension_containers = list(worksheet.iter(extension_tag))
                if standard_containers or extension_containers:
                    worksheets_with_controls.add(sheet.casefold())
                standard_container_count += len(standard_containers)
                extension_container_count += len(extension_containers)
                if len(standard_containers) > 1:
                    unrecognized_ignored_error_count += 1
                    signature_entries.append(
                        (
                            f"multiple-standard-ignored-errors:{sheet.casefold()}",
                            str(len(standard_containers)),
                        )
                    )
                for container_index, container in enumerate(standard_containers):
                    inspect_container(
                        container,
                        sheet=sheet,
                        kind="standard",
                        container_index=container_index,
                        namespace=_SPREADSHEETML_NS,
                    )
                for container_index, container in enumerate(extension_containers):
                    inspect_container(
                        container,
                        sheet=sheet,
                        kind="extension",
                        container_index=container_index,
                        namespace=_IGNORED_ERROR_EXTENSION_NS,
                    )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _IgnoredErrorMetadata(
            default,
            (
                "FormulaFence could not inspect ignored-error OOXML "
                f"({type(error).__name__}); affected review warnings were not compared.",
            ),
        )

    category_counts = {
        flag: sum(
            len(ranges)
            for (_, current_flag), ranges in semantic_ranges.items()
            if current_flag == flag
        )
        for flag in _IGNORED_ERROR_FLAG_ATTRIBUTES
    }
    for (sheet, flag), ranges in sorted(semantic_ranges.items()):
        signature_entries.append(
            (
                f"ignored-error:{sheet}:{flag}",
                repr(tuple(sorted(ranges, key=str.casefold))),
            )
        )
    if unrecognized_ignored_error_count:
        warnings.add(
            "FormulaFence found malformed or unsupported ignored-error metadata; "
            "the affected Excel review warnings have a coverage gap."
        )

    target_ranges = {
        (sheet, reference)
        for (sheet, _), ranges in semantic_ranges.items()
        for reference in ranges
    }
    snapshot = IgnoredErrorSnapshot(
        worksheet_count=len(worksheets_with_controls),
        standard_container_count=standard_container_count,
        extension_container_count=extension_container_count,
        ignored_error_rule_count=sum(category_counts.values()),
        target_range_count=len(target_ranges),
        evaluation_error_count=category_counts.get("evalError", 0),
        inconsistent_formula_count=category_counts.get("formula", 0),
        formula_range_omission_count=category_counts.get("formulaRange", 0),
        unlocked_formula_count=category_counts.get("unlockedFormula", 0),
        empty_cell_reference_count=category_counts.get("emptyCellReference", 0),
        list_data_validation_count=category_counts.get("listDataValidation", 0),
        calculated_column_count=category_counts.get("calculatedColumn", 0),
        number_stored_as_text_count=category_counts.get("numberStoredAsText", 0),
        two_digit_text_year_count=category_counts.get("twoDigitTextYear", 0),
        unrecognized_ignored_error_count=unrecognized_ignored_error_count,
        definition_signature=_private_external_data_signature(
            tuple(sorted(signature_entries))
        ),
    )
    return _IgnoredErrorMetadata(snapshot, tuple(sorted(warnings)))


_FILTER_VISIBILITY_UNSIGNED_INT_MAXIMUM = 4_294_967_295
_FILTER_VISIBILITY_OUTLINE_LEVEL_MAXIMUM = 255
_FILTER_VISIBILITY_COLUMN_OUTLINE_LEVEL_MAXIMUM = 7
_FILTER_VISIBILITY_COLUMN_UPDATE_BUDGET = 16_777_216
_FILTER_VISIBILITY_MAX_COLUMN_WIDTH = Decimal("255")
_FILTER_VISIBILITY_MAX_ROW_HEIGHT = Decimal("409")
_FILTER_VISIBILITY_DIMENSION_PATTERN = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[Ee][+-]?[0-9]+)?"
)
_FILTER_VISIBILITY_COLUMN_KNOWN_ATTRIBUTES = frozenset(
    {
        "min",
        "max",
        "width",
        "style",
        "hidden",
        "bestFit",
        "customWidth",
        "phonetic",
        "outlineLevel",
        "collapsed",
    }
)
_FILTER_VISIBILITY_FILTER_CRITERIA_CHILDREN = frozenset(
    {
        "filters",
        "top10",
        "customFilters",
        "dynamicFilter",
        "colorFilter",
        "iconFilter",
    }
)


def _filter_visibility_boolean(
    value: str | None,
    default: bool,
) -> tuple[bool | None, str]:
    """Normalize one OOXML Boolean while retaining invalid material privately."""
    return _what_if_data_table_boolean(value, default)


def _filter_visibility_unsigned_int(
    value: str | None,
    *,
    maximum: int = _FILTER_VISIBILITY_UNSIGNED_INT_MAXIMUM,
) -> tuple[int | None, str]:
    """Normalize one bounded unsigned XML integer for a private signature."""
    if value is None:
        return None, "none"
    candidate = value.strip()
    if candidate.isascii() and candidate.isdecimal():
        parsed = int(candidate)
        if parsed <= maximum:
            return parsed, str(parsed)
    return None, f"invalid:{value}"


def _filter_visibility_zero_dimension(
    value: str | None,
    *,
    maximum: Decimal,
) -> tuple[bool | None, str]:
    """Classify a finite OOXML dimension without retaining its private size.

    FormulaFence's visibility boundary intentionally distinguishes only the
    documented zero-sized state, which Excel treats as hidden. Ordinary positive
    resize operations remain outside the boundary, but a malformed dimension is
    a coverage issue rather than a silent omission.
    """
    if value is None:
        return None, "none"
    candidate = value.strip()
    if not _FILTER_VISIBILITY_DIMENSION_PATTERN.fullmatch(candidate):
        return None, f"invalid:{value}"
    try:
        parsed = Decimal(candidate)
        invalid = not parsed.is_finite() or parsed < 0 or parsed > maximum
    except (InvalidOperation, ValueError):
        return None, f"invalid:{value}"
    if invalid:
        return None, f"invalid:{value}"
    return parsed == 0, "zero" if parsed == 0 else "nonzero"


def _filter_visibility_reference(
    value: str | None,
) -> tuple[tuple[int, int, int, int] | None, str]:
    """Normalize a local bounded filter or sort reference without emitting it."""
    reference, bounds = _canonical_what_if_data_table_range(value)
    if reference is not None:
        return bounds, reference
    return None, "missing" if value is None else f"invalid:{value}"


def _filter_visibility_attributes(
    element: ElementTree.Element,
    *,
    known: frozenset[str],
    issues: set[str],
    boolean_defaults: Mapping[str, bool] = {},
    unsigned_ints: frozenset[str] = frozenset(),
    references: frozenset[str] = frozenset(),
    required: frozenset[str] = frozenset(),
    unsigned_int_maximums: Mapping[str, int] = {},
    string_defaults: Mapping[str, str] = {},
    guid_attributes: frozenset[str] = frozenset(),
    ignored_namespaced_attributes: frozenset[tuple[str, str]] = frozenset(),
) -> tuple[tuple[str, str], ...]:
    """Canonicalize known control attributes and fail closed for unfamiliar ones."""
    values: dict[str, str] = {
        name: "true" if value else "false" for name, value in boolean_defaults.items()
    }
    values.update(string_defaults)
    for attribute, value in element.attrib.items():
        local_name = _xml_local_name(attribute)
        namespace = _xml_namespace(attribute)
        if (namespace, local_name) in ignored_namespaced_attributes:
            continue
        if namespace is not None or local_name not in known:
            issues.add("unknown-attribute")
            values[f"unknown:{_xml_display_name(attribute)}"] = value
            continue
        if local_name in boolean_defaults:
            parsed, signature = _filter_visibility_boolean(
                value,
                boolean_defaults[local_name],
            )
            if parsed is None:
                issues.add(f"invalid-{local_name}")
            values[local_name] = signature
        elif local_name in unsigned_ints:
            parsed, signature = _filter_visibility_unsigned_int(
                value,
                maximum=unsigned_int_maximums.get(
                    local_name,
                    _FILTER_VISIBILITY_UNSIGNED_INT_MAXIMUM,
                ),
            )
            if parsed is None:
                issues.add(f"invalid-{local_name}")
            values[local_name] = signature
        elif local_name in references:
            bounds, signature = _filter_visibility_reference(value)
            if bounds is None:
                issues.add(f"invalid-{local_name}")
            values[local_name] = signature
        elif local_name in guid_attributes:
            candidate = value.strip()
            if _GUID_PATTERN.fullmatch(candidate):
                values[local_name] = "{GUID}"
            else:
                issues.add(f"invalid-{local_name}")
                values[local_name] = f"invalid:{value}"
        else:
            values[local_name] = value
    for name in required:
        if name not in values:
            issues.add(f"missing-{name}")
            values[name] = "missing"
    return tuple(sorted(values.items()))


def _filter_visibility_unknown_child_signature(
    element: ElementTree.Element,
) -> tuple[str, str, str]:
    """Hash unsupported XML without retaining it in an inspectable object."""
    return (
        "unknown",
        _xml_display_name(element.tag),
        _private_payload_signature(ElementTree.tostring(element, encoding="utf-8")),
    )


def _filter_visibility_leaf_signature(
    element: ElementTree.Element,
    *,
    known_attributes: frozenset[str],
    issues: set[str],
    boolean_defaults: Mapping[str, bool] = {},
    unsigned_ints: frozenset[str] = frozenset(),
    references: frozenset[str] = frozenset(),
    required: frozenset[str] = frozenset(),
    string_defaults: Mapping[str, str] = {},
) -> tuple[object, ...]:
    """Capture a supported leaf declaration while preserving private values only."""
    children = tuple(
        _filter_visibility_unknown_child_signature(child) for child in element
    )
    if children:
        issues.add("unexpected-leaf-children")
    text = element.text if (element.text or "").strip() else None
    return (
        _xml_local_name(element.tag),
        _filter_visibility_attributes(
            element,
            known=known_attributes,
            issues=issues,
            boolean_defaults=boolean_defaults,
            unsigned_ints=unsigned_ints,
            references=references,
            required=required,
            string_defaults=string_defaults,
        ),
        text,
        children,
    )


def _filter_visibility_criterion_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[object, ...]:
    """Canonicalize one standard AutoFilter criterion without exposing its values."""
    local_name = _xml_local_name(element.tag)
    if _xml_namespace(element.tag) != _SPREADSHEETML_NS:
        issues.add("unsupported-filter-criterion-namespace")
        return _filter_visibility_unknown_child_signature(element)
    if local_name == "filters":
        children: list[tuple[object, ...]] = []
        for child in element:
            child_name = _xml_local_name(child.tag)
            if _xml_namespace(child.tag) != _SPREADSHEETML_NS:
                issues.add("unsupported-filters-child")
                children.append(_filter_visibility_unknown_child_signature(child))
            elif child_name == "filter":
                children.append(
                    _filter_visibility_leaf_signature(
                        child,
                        known_attributes=frozenset({"val"}),
                        issues=issues,
                    )
                )
            elif child_name == "dateGroupItem":
                children.append(
                    _filter_visibility_leaf_signature(
                        child,
                        known_attributes=frozenset(
                            {
                                "year",
                                "month",
                                "day",
                                "hour",
                                "minute",
                                "second",
                                "dateTimeGrouping",
                            }
                        ),
                        issues=issues,
                        unsigned_ints=frozenset(
                            {"year", "month", "day", "hour", "minute", "second"}
                        ),
                        required=frozenset({"dateTimeGrouping"}),
                    )
                )
            else:
                issues.add("unsupported-filters-child")
                children.append(_filter_visibility_unknown_child_signature(child))
        return (
            local_name,
            _filter_visibility_attributes(
                element,
                known=frozenset({"blank", "calendarType"}),
                issues=issues,
                boolean_defaults={"blank": False},
                string_defaults={"calendarType": "none"},
            ),
            tuple(sorted(children, key=repr)),
        )
    if local_name == "customFilters":
        children = []
        for child in element:
            if (
                _xml_namespace(child.tag) == _SPREADSHEETML_NS
                and _xml_local_name(child.tag) == "customFilter"
            ):
                children.append(
                    _filter_visibility_leaf_signature(
                        child,
                        known_attributes=frozenset({"operator", "val"}),
                        issues=issues,
                        string_defaults={"operator": "equal"},
                    )
                )
            else:
                issues.add("unsupported-custom-filters-child")
                children.append(_filter_visibility_unknown_child_signature(child))
        if not 1 <= len(children) <= 2:
            issues.add("invalid-custom-filter-count")
        return (
            local_name,
            _filter_visibility_attributes(
                element,
                known=frozenset({"and"}),
                issues=issues,
                boolean_defaults={"and": False},
            ),
            tuple(sorted(children, key=repr)),
        )
    if local_name == "top10":
        return _filter_visibility_leaf_signature(
            element,
            known_attributes=frozenset({"top", "percent", "val", "filterVal"}),
            issues=issues,
            boolean_defaults={"top": True, "percent": False},
            required=frozenset({"val"}),
        )
    if local_name == "dynamicFilter":
        return _filter_visibility_leaf_signature(
            element,
            known_attributes=frozenset({"type", "val", "maxVal"}),
            issues=issues,
            required=frozenset({"type"}),
        )
    if local_name == "colorFilter":
        return _filter_visibility_leaf_signature(
            element,
            known_attributes=frozenset({"dxfId", "cellColor"}),
            issues=issues,
            boolean_defaults={"cellColor": False},
            unsigned_ints=frozenset({"dxfId"}),
        )
    if local_name == "iconFilter":
        return _filter_visibility_leaf_signature(
            element,
            known_attributes=frozenset({"iconSet", "iconId"}),
            issues=issues,
            unsigned_ints=frozenset({"iconId"}),
        )
    issues.add("unsupported-filter-criterion")
    return _filter_visibility_unknown_child_signature(element)


def _filter_visibility_filter_column_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[tuple[object, ...], int | None, int]:
    """Canonicalize a filter column and return its ID and criterion count."""
    column_id, _ = _filter_visibility_unsigned_int(element.get("colId"))
    if column_id is None:
        issues.add("invalid-filter-column-id")
    children: list[tuple[object, ...]] = []
    criterion_count = 0
    for child in element:
        child_name = _xml_local_name(child.tag)
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and child_name in _FILTER_VISIBILITY_FILTER_CRITERIA_CHILDREN
        ):
            criterion_count += 1
            children.append(_filter_visibility_criterion_signature(child, issues))
        else:
            issues.add("unsupported-filter-column-child")
            children.append(_filter_visibility_unknown_child_signature(child))
    if len(children) > 1:
        issues.add("multiple-filter-column-criteria")
    return (
        (
            "filterColumn",
            _filter_visibility_attributes(
                element,
                known=frozenset({"colId", "hiddenButton", "showButton"}),
                issues=issues,
                boolean_defaults={"hiddenButton": False, "showButton": True},
                unsigned_ints=frozenset({"colId"}),
                required=frozenset({"colId"}),
            ),
            tuple(sorted(children, key=repr)),
        ),
        column_id,
        criterion_count,
    )


def _filter_visibility_sort_state_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[tuple[object, ...], int]:
    """Canonicalize a sort state while retaining keys and lists privately."""
    conditions: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    for child in element:
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) == "sortCondition"
        ):
            conditions.append(
                _filter_visibility_leaf_signature(
                    child,
                    known_attributes=frozenset(
                        {
                            "descending",
                            "sortBy",
                            "ref",
                            "customList",
                            "dxfId",
                            "iconSet",
                            "iconId",
                        }
                    ),
                    issues=issues,
                    boolean_defaults={"descending": False},
                    unsigned_ints=frozenset({"dxfId", "iconId"}),
                    references=frozenset({"ref"}),
                    required=frozenset({"ref"}),
                    string_defaults={"sortBy": "value", "iconSet": "3Arrows"},
                )
            )
        else:
            issues.add("unsupported-sort-state-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    if len(conditions) > 64:
        issues.add("too-many-sort-conditions")
    return (
        (
            "sortState",
            _filter_visibility_attributes(
                element,
                known=frozenset({"columnSort", "caseSensitive", "sortMethod", "ref"}),
                issues=issues,
                boolean_defaults={"columnSort": False, "caseSensitive": False},
                references=frozenset({"ref"}),
                required=frozenset({"ref"}),
                string_defaults={"sortMethod": "none"},
            ),
            tuple(conditions),
            tuple(sorted(extensions, key=repr)),
        ),
        len(conditions),
    )


def _filter_visibility_auto_filter_uid(
    element: ElementTree.Element,
    issues: set[str],
) -> str | None:
    """Read an optional revision-2 AutoFilter UID without treating GUID churn as semantic."""
    values = [
        value
        for attribute, value in element.attrib.items()
        if _xml_namespace(attribute) in _FILTER_VISIBILITY_AUTO_FILTER_UID_NAMESPACES
        and _xml_local_name(attribute) == "uid"
    ]
    if not values:
        return None
    if len(values) != 1:  # pragma: no cover - ElementTree de-duplicates exact attributes
        issues.add("multiple-auto-filter-uids")
        return None
    candidate = values[0].strip()
    if not _GUID_PATTERN.fullmatch(candidate):
        issues.add("invalid-auto-filter-uid")
        return None
    return candidate.casefold()


def _filter_visibility_auto_filter_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[tuple[object, ...], int, int, int, int]:
    """Canonicalize one AutoFilter declaration and its private filter material."""
    _filter_visibility_auto_filter_uid(element, issues)
    bounds, _ = _filter_visibility_reference(element.get("ref"))
    if bounds is None:
        issues.add("invalid-auto-filter-reference")
    filter_columns: list[tuple[object, ...]] = []
    filter_column_ids: list[int] = []
    sort_states: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    criterion_count = 0
    sort_condition_count = 0
    for child in element:
        child_name = _xml_local_name(child.tag)
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and child_name == "filterColumn"
        ):
            signature, column_id, count = _filter_visibility_filter_column_signature(
                child,
                issues,
            )
            filter_columns.append(signature)
            criterion_count += count
            if column_id is not None:
                filter_column_ids.append(column_id)
                if bounds is not None:
                    min_column, _, max_column, _ = bounds
                    if column_id >= max_column - min_column + 1:
                        issues.add("filter-column-out-of-range")
        elif (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and child_name == "sortState"
        ):
            signature, count = _filter_visibility_sort_state_signature(child, issues)
            sort_states.append(signature)
            sort_condition_count += count
        else:
            issues.add("unsupported-auto-filter-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    if len(filter_column_ids) != len(set(filter_column_ids)):
        issues.add("duplicate-filter-column")
    if len(sort_states) > 1:
        issues.add("multiple-auto-filter-sort-states")
    return (
        (
            "autoFilter",
            _filter_visibility_attributes(
                element,
                known=frozenset({"ref"}),
                issues=issues,
                references=frozenset({"ref"}),
                required=frozenset({"ref"}),
                ignored_namespaced_attributes=frozenset(
                    {
                        (namespace, "uid")
                        for namespace in _FILTER_VISIBILITY_AUTO_FILTER_UID_NAMESPACES
                    }
                ),
            ),
            tuple(sorted(filter_columns, key=repr)),
            tuple(sort_states),
            tuple(sorted(extensions, key=repr)),
        ),
        len(filter_columns),
        criterion_count,
        len(sort_states),
        sort_condition_count,
    )


def _filter_visibility_row_signature(
    row: ElementTree.Element,
    *,
    default_hidden: bool,
    default_zero_height: bool,
    issues: set[str],
) -> tuple[tuple[object, ...], bool, bool, bool, bool, bool] | None:
    """Capture a semantically relevant row visibility record without its cells."""
    visibility_attributes = {"hidden", "outlineLevel", "collapsed", "ht"}
    if not any(attribute in row.attrib for attribute in visibility_attributes):
        return None
    raw_row_index = row.get("r")
    row_index, row_index_signature = _filter_visibility_unsigned_int(
        raw_row_index,
        maximum=MAX_EXCEL_ROW,
    )
    if row_index is None or row_index < 1:
        issues.add("invalid-row-index")
    hidden, hidden_signature = _filter_visibility_boolean(row.get("hidden"), False)
    if hidden is None:
        issues.add("invalid-row-hidden")
    outline_level, outline_level_signature = _filter_visibility_unsigned_int(
        row.get("outlineLevel"),
        maximum=_FILTER_VISIBILITY_OUTLINE_LEVEL_MAXIMUM,
    )
    if row.get("outlineLevel") is None:
        outline_level = 0
        outline_level_signature = "0"
    elif outline_level is None:
        issues.add("invalid-row-outline-level")
    collapsed, collapsed_signature = _filter_visibility_boolean(row.get("collapsed"), False)
    if collapsed is None:
        issues.add("invalid-row-collapsed")
    zero_height: bool | None = False
    zero_height_signature = "none"
    if "ht" in row.attrib:
        zero_height, zero_height_signature = _filter_visibility_zero_dimension(
            row.get("ht"),
            maximum=_FILTER_VISIBILITY_MAX_ROW_HEIGHT,
        )
        if zero_height is None:
            issues.add("invalid-row-height")
    has_explicit_hidden = "hidden" in row.attrib
    has_explicit_height = "ht" in row.attrib
    effective_hidden = (
        hidden if has_explicit_hidden and hidden is not None else default_hidden
    )
    effective_zero_height = (
        zero_height
        if has_explicit_height and zero_height is not None
        else default_zero_height
    )
    is_hidden = hidden is True
    is_zero_height = zero_height is True and not default_zero_height
    is_outlined = bool(outline_level)
    is_collapsed = collapsed is True
    is_visible_override = (
        (default_hidden or default_zero_height)
        and not effective_hidden
        and not effective_zero_height
        and (
            (has_explicit_hidden and hidden is False)
            or (has_explicit_height and zero_height is False)
        )
    )
    if not (
        is_hidden
        or is_zero_height
        or is_outlined
        or is_collapsed
        or is_visible_override
        or row_index is None
        or row_index < 1
        or hidden is None
        or zero_height is None
        or outline_level is None
        or collapsed is None
    ):
        return None
    return (
        (
            "row",
            (
                ("r", row_index_signature),
                ("hidden", hidden_signature),
                ("zeroHeight", zero_height_signature),
                ("outlineLevel", outline_level_signature),
                ("collapsed", collapsed_signature),
            ),
        ),
        is_hidden,
        is_zero_height,
        is_outlined,
        is_collapsed,
        is_visible_override,
    )


def _filter_visibility_column_control(
    column: ElementTree.Element,
    *,
    issues: set[str],
) -> tuple[int, int, bool | None, int | None, bool | None, bool | None] | None:
    """Parse one layered column-visibility declaration from raw SpreadsheetML.

    SpreadsheetML ``<col>`` declarations can overlap. Writers such as Apache
    POI merge a later record's *present* attributes into the earlier record, so
    an omitted ``hidden``/``outlineLevel``/``collapsed`` flag must not erase an
    existing visibility setting. The same applies to a ``width`` declaration:
    a later positive width can reveal an earlier zero-width column without
    altering its hidden or outline flags. Callers therefore apply only the
    non-``None`` attributes from this return value in XML order.
    """
    visibility_attributes = {"hidden", "outlineLevel", "collapsed", "width"}
    has_visibility_attribute = any(
        attribute in column.attrib for attribute in visibility_attributes
    )
    if list(column):
        issues.add("unexpected-column-children")
    if (column.text or "").strip():
        issues.add("unexpected-column-text")
    for attribute in column.attrib:
        local_name = _xml_local_name(attribute)
        if (
            _xml_namespace(attribute) is not None
            or local_name not in _FILTER_VISIBILITY_COLUMN_KNOWN_ATTRIBUTES
        ):
            issues.add("unsupported-column-attribute")
    if not has_visibility_attribute:
        return None

    minimum, _ = _filter_visibility_unsigned_int(
        column.get("min"),
        maximum=MAX_EXCEL_COLUMN,
    )
    maximum, _ = _filter_visibility_unsigned_int(
        column.get("max"),
        maximum=MAX_EXCEL_COLUMN,
    )
    if minimum is None or maximum is None or minimum < 1 or maximum < minimum:
        issues.add("invalid-column-bounds")
        return None

    hidden: bool | None = None
    if "hidden" in column.attrib:
        hidden, _ = _filter_visibility_boolean(column.get("hidden"), False)
        if hidden is None:
            issues.add("invalid-column-hidden")

    outline_level: int | None = None
    if "outlineLevel" in column.attrib:
        outline_level, _ = _filter_visibility_unsigned_int(
            column.get("outlineLevel"),
            maximum=_FILTER_VISIBILITY_COLUMN_OUTLINE_LEVEL_MAXIMUM,
        )
        if outline_level is None:
            issues.add("invalid-column-outline-level")

    collapsed: bool | None = None
    if "collapsed" in column.attrib:
        collapsed, _ = _filter_visibility_boolean(column.get("collapsed"), False)
        if collapsed is None:
            issues.add("invalid-column-collapsed")

    zero_width: bool | None = None
    if "width" in column.attrib:
        zero_width, _ = _filter_visibility_zero_dimension(
            column.get("width"),
            maximum=_FILTER_VISIBILITY_MAX_COLUMN_WIDTH,
        )
        if zero_width is None:
            issues.add("invalid-column-width")
    return minimum, maximum, hidden, outline_level, collapsed, zero_width


def _filter_visibility_column_state_signature(
    hidden_columns: bytearray,
    outline_levels: bytearray,
    collapsed_columns: bytearray,
    zero_width_columns: bytearray,
) -> tuple[tuple[int, int, bool, int, bool, bool], ...]:
    """Compress effective column controls into a private canonical signature."""
    segments: list[tuple[int, int, bool, int, bool, bool]] = []
    start: int | None = None
    previous_state: tuple[bool, int, bool, bool] | None = None
    for index in range(1, MAX_EXCEL_COLUMN + 1):
        state = (
            bool(hidden_columns[index]),
            int(outline_levels[index]),
            bool(collapsed_columns[index]),
            bool(zero_width_columns[index]),
        )
        if state == (False, 0, False, False):
            if start is not None and previous_state is not None:
                segments.append((start, index - 1, *previous_state))
            start = None
            previous_state = None
            continue
        if start is None:
            start = index
            previous_state = state
            continue
        if state != previous_state:
            segments.append((start, index - 1, *previous_state))
            start = index
            previous_state = state
    if start is not None and previous_state is not None:
        segments.append((start, MAX_EXCEL_COLUMN, *previous_state))
    return tuple(segments)


def _filter_visibility_metadata(path: Path) -> _FilterVisibilityMetadata:
    """Inspect filter, sort, and visibility controls from raw SpreadsheetML.

    Filter member values, custom sort lists, and report ranges can be sensitive.
    They are canonicalized only inside a private signature. The public snapshot
    is intentionally limited to structural counts.
    """
    warnings: set[str] = set()
    default = FilterVisibilitySnapshot()
    entries: list[tuple[str, str]] = []
    worksheet_auto_filter_count = 0
    table_auto_filter_count = 0
    filter_column_count = 0
    filter_criterion_count = 0
    sort_state_count = 0
    sort_condition_count = 0
    default_hidden_sheet_count = 0
    default_zero_height_sheet_count = 0
    default_zero_width_sheet_count = 0
    hidden_row_count = 0
    zero_height_row_count = 0
    outlined_row_count = 0
    collapsed_row_count = 0
    visible_row_override_count = 0
    hidden_column_count = 0
    zero_width_column_count = 0
    outlined_column_count = 0
    collapsed_column_count = 0
    column_update_count = 0
    unrecognized_control_count = 0

    def add_auto_filter(
        element: ElementTree.Element,
        *,
        key: str,
        table: bool,
        multiple: bool,
    ) -> None:
        nonlocal worksheet_auto_filter_count
        nonlocal table_auto_filter_count
        nonlocal filter_column_count
        nonlocal filter_criterion_count
        nonlocal sort_state_count
        nonlocal sort_condition_count
        nonlocal unrecognized_control_count
        issues: set[str] = {"multiple-auto-filters"} if multiple else set()
        signature, columns, criteria, states, conditions = (
            _filter_visibility_auto_filter_signature(element, issues)
        )
        entries.append((key, repr(signature)))
        if table:
            table_auto_filter_count += 1
        else:
            worksheet_auto_filter_count += 1
        filter_column_count += columns
        filter_criterion_count += criteria
        sort_state_count += states
        sort_condition_count += conditions
        unrecognized_control_count += bool(issues)

    def add_sort_state(
        element: ElementTree.Element,
        *,
        key: str,
        multiple: bool,
    ) -> None:
        nonlocal sort_state_count, sort_condition_count, unrecognized_control_count
        issues: set[str] = {"multiple-sort-states"} if multiple else set()
        signature, conditions = _filter_visibility_sort_state_signature(element, issues)
        entries.append((key, repr(signature)))
        sort_state_count += 1
        sort_condition_count += conditions
        unrecognized_control_count += bool(issues)

    try:
        with ZipFile(path) as archive:
            auto_filter_tag = f"{{{_SPREADSHEETML_NS}}}autoFilter"
            sort_state_tag = f"{{{_SPREADSHEETML_NS}}}sortState"
            sheet_format_tag = f"{{{_SPREADSHEETML_NS}}}sheetFormatPr"
            cols_tag = f"{{{_SPREADSHEETML_NS}}}cols"
            col_tag = f"{{{_SPREADSHEETML_NS}}}col"
            sheet_data_tag = f"{{{_SPREADSHEETML_NS}}}sheetData"
            row_tag = f"{{{_SPREADSHEETML_NS}}}row"
            table_parts_tag = f"{{{_SPREADSHEETML_NS}}}tableParts"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                sheet_formats = worksheet.findall(sheet_format_tag)
                default_hidden = False
                default_zero_height = False
                default_zero_width = False
                if sheet_formats:
                    sheet_format_issues: set[str] = set()
                    if len(sheet_formats) > 1:
                        sheet_format_issues.add("multiple-sheet-format-properties")
                    default_hidden_value, default_hidden_signature = (
                        _filter_visibility_boolean(
                            sheet_formats[0].get("zeroHeight"),
                            False,
                        )
                    )
                    if default_hidden_value is None:
                        sheet_format_issues.add("invalid-default-row-hidden")
                    else:
                        default_hidden = default_hidden_value
                    default_zero_height_value, default_zero_height_signature = (
                        _filter_visibility_zero_dimension(
                            sheet_formats[0].get("defaultRowHeight"),
                            maximum=_FILTER_VISIBILITY_MAX_ROW_HEIGHT,
                        )
                    )
                    if (
                        "defaultRowHeight" in sheet_formats[0].attrib
                        and default_zero_height_value is None
                    ):
                        sheet_format_issues.add("invalid-default-row-height")
                    elif default_zero_height_value is not None:
                        default_zero_height = default_zero_height_value
                    default_zero_width_value, default_zero_width_signature = (
                        _filter_visibility_zero_dimension(
                            sheet_formats[0].get("defaultColWidth"),
                            maximum=_FILTER_VISIBILITY_MAX_COLUMN_WIDTH,
                        )
                    )
                    if (
                        "defaultColWidth" in sheet_formats[0].attrib
                        and default_zero_width_value is None
                    ):
                        sheet_format_issues.add("invalid-default-column-width")
                    elif default_zero_width_value is not None:
                        default_zero_width = default_zero_width_value
                    if (
                        default_hidden
                        or default_zero_height
                        or default_zero_width
                        or sheet_format_issues
                    ):
                        entries.append(
                            (
                                f"default-row-visibility:{sheet.casefold()}",
                                repr(
                                    (
                                        "sheetFormatPr",
                                        ("zeroHeight", default_hidden_signature),
                                        (
                                            "defaultRowHeight",
                                            default_zero_height_signature,
                                        ),
                                        (
                                            "defaultColWidth",
                                            default_zero_width_signature,
                                        ),
                                    )
                                ),
                            )
                        )
                    default_hidden_sheet_count += default_hidden
                    default_zero_height_sheet_count += default_zero_height
                    default_zero_width_sheet_count += default_zero_width
                    unrecognized_control_count += bool(sheet_format_issues)

                column_issues: set[str] = set()
                column_sets = worksheet.findall(cols_tag)
                hidden_columns = bytearray(MAX_EXCEL_COLUMN + 1)
                outline_levels = bytearray(MAX_EXCEL_COLUMN + 1)
                collapsed_columns = bytearray(MAX_EXCEL_COLUMN + 1)
                zero_width_columns = bytearray(MAX_EXCEL_COLUMN + 1)
                if default_zero_width:
                    zero_width_columns[1:] = bytes([1]) * MAX_EXCEL_COLUMN
                for columns in column_sets:
                    if not list(columns):
                        column_issues.add("empty-column-information")
                    if (columns.text or "").strip():
                        column_issues.add("unexpected-column-information-text")
                    for column in columns:
                        if column.tag != col_tag:
                            column_issues.add("unsupported-column-information-child")
                            continue
                        captured_column = _filter_visibility_column_control(
                            column,
                            issues=column_issues,
                        )
                        if captured_column is None:
                            continue
                        (
                            minimum,
                            maximum,
                            hidden,
                            outline_level,
                            collapsed,
                            zero_width,
                        ) = captured_column
                        attribute_count = sum(
                            value is not None
                            for value in (hidden, outline_level, collapsed, zero_width)
                        )
                        if not attribute_count:
                            continue
                        span = maximum - minimum + 1
                        if (
                            column_update_count + span * attribute_count
                            > _FILTER_VISIBILITY_COLUMN_UPDATE_BUDGET
                        ):
                            column_issues.add("column-visibility-update-budget")
                            continue
                        if hidden is not None:
                            hidden_columns[minimum : maximum + 1] = (
                                bytes([int(hidden)]) * span
                            )
                        if outline_level is not None:
                            outline_levels[minimum : maximum + 1] = (
                                bytes([outline_level]) * span
                            )
                        if collapsed is not None:
                            collapsed_columns[minimum : maximum + 1] = (
                                bytes([int(collapsed)]) * span
                            )
                        if zero_width is not None:
                            zero_width_columns[minimum : maximum + 1] = (
                                bytes([int(zero_width)]) * span
                            )
                        column_update_count += span * attribute_count
                column_signature = _filter_visibility_column_state_signature(
                    hidden_columns,
                    outline_levels,
                    collapsed_columns,
                    zero_width_columns,
                )
                if column_signature:
                    entries.append(
                        (
                            f"column-visibility:{sheet.casefold()}",
                            repr(column_signature),
                        )
                    )
                hidden_column_count += sum(hidden_columns)
                zero_width_column_count += sum(zero_width_columns)
                outlined_column_count += sum(level > 0 for level in outline_levels)
                collapsed_column_count += sum(collapsed_columns)
                if column_issues:
                    entries.append(
                        (
                            f"column-visibility-issues:{sheet.casefold()}",
                            _private_payload_signature(
                                b"".join(
                                    ElementTree.tostring(
                                        columns,
                                        encoding="utf-8",
                                    )
                                    for columns in column_sets
                                )
                            ),
                        )
                    )
                    unrecognized_control_count += 1

                auto_filters = worksheet.findall(auto_filter_tag)
                for auto_filter in auto_filters:
                    add_auto_filter(
                        auto_filter,
                        key=f"worksheet-auto-filter:{sheet.casefold()}",
                        table=False,
                        multiple=len(auto_filters) > 1,
                    )
                sort_states = worksheet.findall(sort_state_tag)
                for sort_state in sort_states:
                    add_sort_state(
                        sort_state,
                        key=f"worksheet-sort-state:{sheet.casefold()}",
                        multiple=len(sort_states) > 1,
                    )

                row_issues: set[str] = set()
                for sheet_data in worksheet.findall(sheet_data_tag):
                    for row in sheet_data.findall(row_tag):
                        captured = _filter_visibility_row_signature(
                            row,
                            default_hidden=default_hidden,
                            default_zero_height=default_zero_height,
                            issues=row_issues,
                        )
                        if captured is None:
                            continue
                        (
                            signature,
                            hidden,
                            zero_height,
                            outlined,
                            collapsed,
                            visible_override,
                        ) = captured
                        entries.append(
                            (
                                f"row-visibility:{sheet.casefold()}",
                                repr(signature),
                            )
                        )
                        hidden_row_count += hidden
                        zero_height_row_count += zero_height
                        outlined_row_count += outlined
                        collapsed_row_count += collapsed
                        visible_row_override_count += visible_override
                if row_issues:
                    unrecognized_control_count += 1

                relationship_member = _relationship_part_path(member)
                has_table_parts = worksheet.find(table_parts_tag) is not None
                if relationship_member not in archive.namelist():
                    if has_table_parts:
                        warnings.add(
                            "FormulaFence could not locate worksheet table relationships while "
                            "inspecting filter controls; affected table filters were not compared."
                        )
                        entries.append(
                            (
                                f"missing-table-relationships:{sheet.casefold()}",
                                "missing",
                            )
                        )
                        unrecognized_control_count += 1
                    continue
                try:
                    relationships = _package_relationships(archive, member)
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    warnings.add(
                        "FormulaFence could not inspect worksheet table relationships while "
                        f"inspecting filter controls ({type(error).__name__}); affected table "
                        "filters were not compared."
                    )
                    entries.append(
                        (
                            f"invalid-table-relationships:{sheet.casefold()}",
                            type(error).__name__,
                        )
                    )
                    unrecognized_control_count += 1
                    continue
                table_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type.rsplit("/", maxsplit=1)[-1] == "table"
                ]
                for relationship in table_relationships:
                    if relationship.target is None:
                        warnings.add(
                            "FormulaFence found a worksheet table relationship without a safe "
                            "internal target; affected table filters were not compared."
                        )
                        entries.append(
                            (
                                f"unsafe-table-relationship:{sheet.casefold()}",
                                repr((relationship.relationship_type, relationship.target_mode)),
                            )
                        )
                        unrecognized_control_count += 1
                        continue
                    try:
                        table = _xml_root(archive, relationship.target)
                    except (
                        ElementTree.ParseError,
                        KeyError,
                        OSError,
                        RuntimeError,
                        ValueError,
                    ) as error:
                        warnings.add(
                            "FormulaFence could not inspect a worksheet table part while "
                            f"inspecting filter controls ({type(error).__name__}); affected "
                            "table filters were not compared."
                        )
                        entries.append(
                            (
                                f"unreadable-table-part:{sheet.casefold()}",
                                type(error).__name__,
                            )
                        )
                        unrecognized_control_count += 1
                        continue
                    if (
                        _xml_namespace(table.tag) != _SPREADSHEETML_NS
                        or _xml_local_name(table.tag) != "table"
                    ):
                        warnings.add(
                            "FormulaFence found a worksheet table part with an unexpected root; "
                            "affected table filters were not compared."
                        )
                        entries.append(
                            (
                                f"unexpected-table-root:{sheet.casefold()}",
                                _private_payload_signature(
                                    ElementTree.tostring(table, encoding="utf-8")
                                ),
                            )
                        )
                        unrecognized_control_count += 1
                        continue
                    table_auto_filters = table.findall(auto_filter_tag)
                    for auto_filter in table_auto_filters:
                        add_auto_filter(
                            auto_filter,
                            key=(
                                "table-auto-filter:"
                                f"{sheet.casefold()}"
                            ),
                            table=True,
                            multiple=len(table_auto_filters) > 1,
                        )
                    table_sort_states = table.findall(sort_state_tag)
                    for sort_state in table_sort_states:
                        add_sort_state(
                            sort_state,
                            key=(
                                "table-sort-state:"
                                f"{sheet.casefold()}"
                            ),
                            multiple=len(table_sort_states) > 1,
                        )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _FilterVisibilityMetadata(
            default,
            (
                "FormulaFence could not inspect filter and visibility OOXML "
                f"({type(error).__name__}); affected report controls were not compared.",
            ),
        )

    if unrecognized_control_count:
        warnings.add(
            "FormulaFence found malformed or unsupported filter, sort, or visibility "
            "metadata; the affected report controls have a coverage gap."
        )
    snapshot = FilterVisibilitySnapshot(
        worksheet_auto_filter_count=worksheet_auto_filter_count,
        table_auto_filter_count=table_auto_filter_count,
        filter_column_count=filter_column_count,
        filter_criterion_count=filter_criterion_count,
        sort_state_count=sort_state_count,
        sort_condition_count=sort_condition_count,
        default_hidden_sheet_count=default_hidden_sheet_count,
        default_zero_height_sheet_count=default_zero_height_sheet_count,
        default_zero_width_sheet_count=default_zero_width_sheet_count,
        hidden_row_count=hidden_row_count,
        zero_height_row_count=zero_height_row_count,
        outlined_row_count=outlined_row_count,
        collapsed_row_count=collapsed_row_count,
        visible_row_override_count=visible_row_override_count,
        hidden_column_count=hidden_column_count,
        zero_width_column_count=zero_width_column_count,
        outlined_column_count=outlined_column_count,
        collapsed_column_count=collapsed_column_count,
        unrecognized_control_count=unrecognized_control_count,
        definition_signature=_private_external_data_signature(tuple(sorted(entries))),
    )
    return _FilterVisibilityMetadata(snapshot, tuple(sorted(warnings)))


def _named_sheet_view_guid(value: str | None) -> str | None:
    """Return one valid GUID in a stable private form, if present."""
    if value is None:
        return None
    candidate = value.strip()
    return candidate.casefold() if _GUID_PATTERN.fullmatch(candidate) else None


def _named_sheet_view_auto_filter_binding(
    element: ElementTree.Element,
    *,
    owner: str,
    table_id: int | None,
    fallback_reference: str | None = None,
    table_column_uids: tuple[tuple[str, int], ...] = (),
    issues: set[str],
) -> _NamedSheetViewAutoFilterBinding:
    """Capture one base AutoFilter used by a Named Sheet View reconciliation."""
    raw_reference = element.get("ref") or fallback_reference
    reference_bounds, reference_signature = _filter_visibility_reference(raw_reference)
    if reference_bounds is None:
        issues.add("invalid-named-sheet-view-base-filter-reference")
    uid_values = [
        value
        for attribute, value in element.attrib.items()
        if _xml_namespace(attribute) in _FILTER_VISIBILITY_AUTO_FILTER_UID_NAMESPACES
        and _xml_local_name(attribute) == "uid"
    ]
    if len(uid_values) > 1:
        issues.add("multiple-named-sheet-view-base-filter-uids")
    uid = _named_sheet_view_guid(uid_values[0]) if uid_values else None
    if any(_named_sheet_view_guid(value) is None for value in uid_values):
        issues.add("invalid-named-sheet-view-base-filter-uid")
    return _NamedSheetViewAutoFilterBinding(
        owner=owner,
        reference_signature=reference_signature,
        reference_bounds=reference_bounds,
        table_id=table_id,
        uid=uid,
        table_column_uids=table_column_uids,
    )


def _named_sheet_view_table_column_uids(
    table: ElementTree.Element,
    issues: set[str],
) -> tuple[tuple[str, int], ...]:
    """Read private table-column UIDs for the documented reconciliation path."""
    table_columns_tag = f"{{{_SPREADSHEETML_NS}}}tableColumns"
    table_column_tag = f"{{{_SPREADSHEETML_NS}}}tableColumn"
    table_columns = table.find(table_columns_tag)
    if table_columns is None:
        return ()
    captured: list[tuple[str, int]] = []
    for index, table_column in enumerate(table_columns.findall(table_column_tag)):
        values = [
            value
            for attribute, value in table_column.attrib.items()
            if _xml_namespace(attribute) in _FILTER_VISIBILITY_AUTO_FILTER_UID_NAMESPACES
            and _xml_local_name(attribute) == "uid"
        ]
        if len(values) > 1:
            issues.add("multiple-named-sheet-view-table-column-uids")
            continue
        uid = _named_sheet_view_guid(values[0]) if values else None
        if values and uid is None:
            issues.add("invalid-named-sheet-view-table-column-uid")
        if uid is not None:
            captured.append((uid, index))
    if len({uid for uid, _ in captured}) != len(captured):
        issues.add("duplicate-named-sheet-view-table-column-uid")
    return tuple(sorted(captured))


def _named_sheet_view_base_filter_bindings(
    archive: ZipFile,
    *,
    worksheet_member: str,
    relationships: tuple[_PackageRelationship, ...],
) -> tuple[tuple[_NamedSheetViewAutoFilterBinding, ...], tuple[str, ...]]:
    """Collect the worksheet and table AutoFilters that a view can target.

    Modern Excel resolves a Named Sheet View filter by its AutoFilter UID, then
    by a table ID, then by a worksheet-owned AutoFilter. This inventory allows
    FormulaFence to compare the resolved target rather than treating GUID
    churn as a material change.
    """
    issues: set[str] = set()
    bindings: list[_NamedSheetViewAutoFilterBinding] = []
    auto_filter_tag = f"{{{_SPREADSHEETML_NS}}}autoFilter"
    table_tag = f"{{{_SPREADSHEETML_NS}}}table"
    try:
        worksheet = _xml_root(archive, worksheet_member)
    except (
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ):
        return (), ("unreadable-named-sheet-view-worksheet",)

    worksheet_filters = worksheet.findall(auto_filter_tag)
    if len(worksheet_filters) > 1:
        issues.add("multiple-named-sheet-view-worksheet-auto-filters")
    for auto_filter in worksheet_filters:
        bindings.append(
            _named_sheet_view_auto_filter_binding(
                auto_filter,
                owner="worksheet",
                table_id=None,
                issues=issues,
            )
        )

    table_relationships = [
        relationship
        for relationship in relationships
        if relationship.relationship_type.rsplit("/", maxsplit=1)[-1] == "table"
    ]
    table_part_bytes = 0
    for relationship_index, relationship in enumerate(table_relationships):
        if relationship_index >= _NAMED_SHEET_VIEW_TOTAL_MAX_COUNT:
            issues.add("named-sheet-view-table-part-count-limit")
            break
        if relationship.target is None:
            issues.add("unsafe-named-sheet-view-table-relationship")
            continue
        try:
            table_part_size = archive.getinfo(relationship.target).file_size
        except KeyError:
            issues.add("missing-named-sheet-view-table")
            continue
        if table_part_size > _NAMED_SHEET_VIEW_MAX_PART_BYTES:
            issues.add("oversized-named-sheet-view-table")
            continue
        if table_part_bytes + table_part_size > _NAMED_SHEET_VIEW_TOTAL_MAX_BYTES:
            issues.add("named-sheet-view-table-size-limit")
            continue
        table_part_bytes += table_part_size
        try:
            table = _xml_root(archive, relationship.target)
        except (
            ElementTree.ParseError,
            KeyError,
            OSError,
            RuntimeError,
            ValueError,
        ):
            issues.add("unreadable-named-sheet-view-table")
            continue
        if _xml_namespace(table.tag) != _SPREADSHEETML_NS or table.tag != table_tag:
            issues.add("unexpected-named-sheet-view-table-root")
            continue
        table_id, _ = _filter_visibility_unsigned_int(table.get("id"))
        if table_id is None or table_id == 0:
            issues.add("invalid-named-sheet-view-table-id")
            continue
        table_reference = table.get("ref")
        table_column_uids = _named_sheet_view_table_column_uids(table, issues)
        table_filters = table.findall(auto_filter_tag)
        if len(table_filters) > 1:
            issues.add("multiple-named-sheet-view-table-auto-filters")
        for auto_filter in table_filters:
            bindings.append(
                _named_sheet_view_auto_filter_binding(
                    auto_filter,
                    owner="table",
                    table_id=table_id,
                    fallback_reference=table_reference,
                    table_column_uids=table_column_uids,
                    issues=issues,
                )
            )

    uids = [binding.uid for binding in bindings if binding.uid is not None]
    if len(uids) != len(set(uids)):
        issues.add("duplicate-named-sheet-view-auto-filter-uid")
    table_ids = [binding.table_id for binding in bindings if binding.table_id is not None]
    if len(table_ids) != len(set(table_ids)):
        issues.add("duplicate-named-sheet-view-table-id")
    return tuple(bindings), tuple(sorted(issues))


def _named_sheet_view_resolve_filter_binding(
    element: ElementTree.Element,
    *,
    bindings: tuple[_NamedSheetViewAutoFilterBinding, ...],
    issues: set[str],
) -> _NamedSheetViewAutoFilterBinding | None:
    """Resolve an nsvFilter using Excel's documented priority sequence."""
    filter_id = _named_sheet_view_guid(element.get("filterId"))
    if filter_id is not None:
        matches = [binding for binding in bindings if binding.uid == filter_id]
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            issues.add("ambiguous-named-sheet-view-filter-uid")
            return None

    table_id, _ = _filter_visibility_unsigned_int(element.get("tableId"))
    if table_id is None:
        issues.add("unmatched-named-sheet-view-filter")
        return None
    if table_id:
        matches = [binding for binding in bindings if binding.table_id == table_id]
    else:
        matches = [binding for binding in bindings if binding.owner == "worksheet"]
    if len(matches) == 1:
        return matches[0]
    if len(matches) > 1:
        issues.add("ambiguous-named-sheet-view-filter-target")
    else:
        issues.add("unmatched-named-sheet-view-filter")
    return None


def _named_sheet_view_binding_signature(
    binding: _NamedSheetViewAutoFilterBinding | None,
) -> tuple[str, ...]:
    """Keep a resolved target private while making rebinding material to a diff."""
    if binding is None:
        return ("unmatched",)
    return (
        "bound",
        binding.owner,
        binding.reference_signature,
        "none" if binding.table_id is None else str(binding.table_id),
    )


def _named_sheet_view_validate_column_binding(
    element: ElementTree.Element,
    *,
    binding: _NamedSheetViewAutoFilterBinding | None,
    issues: set[str],
) -> None:
    """Verify a view's column target can reconcile to its base AutoFilter."""
    if binding is None:
        return
    column_id, _ = _filter_visibility_unsigned_int(element.get("colId"))
    column_uid = _named_sheet_view_guid(element.get("id"))
    if binding.owner == "table" and column_uid is not None:
        if any(uid == column_uid for uid, _ in binding.table_column_uids):
            return
    if column_id is None or binding.reference_bounds is None:
        issues.add("unmatched-named-sheet-view-column")
        return
    minimum_column, _, maximum_column, _ = binding.reference_bounds
    if column_id >= maximum_column - minimum_column + 1:
        issues.add("named-sheet-view-column-out-of-range")


def _named_sheet_view_column_filter_signature(
    element: ElementTree.Element,
    issues: set[str],
    *,
    binding: _NamedSheetViewAutoFilterBinding | None,
) -> tuple[tuple[object, ...], int]:
    """Canonicalize one Named Sheet View column filter without exposing criteria."""
    filters: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    criterion_count = 0
    outer_column_id, _ = _filter_visibility_unsigned_int(element.get("colId"))
    _named_sheet_view_validate_column_binding(
        element,
        binding=binding,
        issues=issues,
    )
    for child in element:
        if (
            _xml_namespace(child.tag) in {_SPREADSHEETML_NS, _NAMED_SHEET_VIEW_NS}
            and _xml_local_name(child.tag) == "filter"
        ):
            signature, inner_column_id, count = _filter_visibility_filter_column_signature(
                child,
                issues,
            )
            if (
                outer_column_id is not None
                and inner_column_id is not None
                and outer_column_id != inner_column_id
            ):
                issues.add("mismatched-named-sheet-view-column-filter-id")
            filters.append(signature)
            criterion_count += count
        else:
            issues.add("unsupported-named-sheet-view-column-filter-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    return (
        (
            "columnFilter",
            _filter_visibility_attributes(
                element,
                known=frozenset({"colId", "id"}),
                issues=issues,
                unsigned_ints=frozenset({"colId"}),
                required=frozenset({"colId"}),
                guid_attributes=frozenset({"id"}),
            ),
            tuple(sorted(filters, key=repr)),
            tuple(sorted(extensions, key=repr)),
        ),
        criterion_count,
    )


def _named_sheet_view_sort_rule_signature(
    element: ElementTree.Element,
    issues: set[str],
    *,
    binding: _NamedSheetViewAutoFilterBinding | None,
) -> tuple[tuple[object, ...], int]:
    """Canonicalize one Named Sheet View sort rule without exposing its range."""
    conditions: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    _named_sheet_view_validate_column_binding(
        element,
        binding=binding,
        issues=issues,
    )
    for child in element:
        namespace = _xml_namespace(child.tag)
        local_name = _xml_local_name(child.tag)
        if namespace in {_NAMED_SHEET_VIEW_NS, _OFFICE_2010_SPREADSHEET_NS} and local_name == (
            "sortCondition"
        ):
            conditions.append(
                _filter_visibility_leaf_signature(
                    child,
                    known_attributes=frozenset(
                        {
                            "descending",
                            "sortBy",
                            "ref",
                            "customList",
                            "dxfId",
                            "iconSet",
                            "iconId",
                        }
                    ),
                    issues=issues,
                    boolean_defaults={"descending": False},
                    unsigned_ints=frozenset({"dxfId", "iconId"}),
                    references=frozenset({"ref"}),
                    required=frozenset({"ref"}),
                    string_defaults={"sortBy": "value", "iconSet": "3Arrows"},
                )
            )
        else:
            issues.add("unsupported-named-sheet-view-sort-rule-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    if len(conditions) > 1:
        issues.add("multiple-named-sheet-view-sort-conditions")
    return (
        (
            "sortRule",
            _filter_visibility_attributes(
                element,
                known=frozenset({"colId", "id"}),
                issues=issues,
                unsigned_ints=frozenset({"colId"}),
                required=frozenset({"colId"}),
                guid_attributes=frozenset({"id"}),
            ),
            tuple(conditions),
            tuple(sorted(extensions, key=repr)),
        ),
        len(conditions),
    )


def _named_sheet_view_sort_rules_signature(
    element: ElementTree.Element,
    issues: set[str],
    *,
    binding: _NamedSheetViewAutoFilterBinding | None,
) -> tuple[tuple[object, ...], int, int]:
    """Canonicalize one Named Sheet View sort-rule container."""
    rules: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    condition_count = 0
    for child in element:
        if (
            _xml_namespace(child.tag) == _NAMED_SHEET_VIEW_NS
            and _xml_local_name(child.tag) == "sortRule"
        ):
            signature, count = _named_sheet_view_sort_rule_signature(
                child,
                issues,
                binding=binding,
            )
            rules.append(signature)
            condition_count += count
        else:
            issues.add("unsupported-named-sheet-view-sort-rules-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    if len(rules) > 64:
        issues.add("too-many-named-sheet-view-sort-rules")
    return (
        (
            "sortRules",
            _filter_visibility_attributes(
                element,
                known=frozenset({"sortMethod", "caseSensitive"}),
                issues=issues,
                boolean_defaults={"caseSensitive": False},
                string_defaults={"sortMethod": "none"},
            ),
            tuple(rules),
            tuple(sorted(extensions, key=repr)),
        ),
        len(rules),
        condition_count,
    )


def _named_sheet_view_filter_signature(
    element: ElementTree.Element,
    issues: set[str],
    *,
    bindings: tuple[_NamedSheetViewAutoFilterBinding, ...],
) -> tuple[tuple[object, ...], int, int, int, int]:
    """Canonicalize one alternate Named Sheet View filter and sort declaration."""
    column_filters: list[tuple[object, ...]] = []
    sort_rules: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    criterion_count = 0
    sort_rule_count = 0
    sort_condition_count = 0
    binding = _named_sheet_view_resolve_filter_binding(
        element,
        bindings=bindings,
        issues=issues,
    )
    for child in element:
        if (
            _xml_namespace(child.tag) == _NAMED_SHEET_VIEW_NS
            and _xml_local_name(child.tag) == "columnFilter"
        ):
            signature, count = _named_sheet_view_column_filter_signature(
                child,
                issues,
                binding=binding,
            )
            column_filters.append(signature)
            criterion_count += count
        elif (
            _xml_namespace(child.tag) == _NAMED_SHEET_VIEW_NS
            and _xml_local_name(child.tag) == "sortRules"
        ):
            signature, rules, conditions = _named_sheet_view_sort_rules_signature(
                child,
                issues,
                binding=binding,
            )
            sort_rules.append(signature)
            sort_rule_count += rules
            sort_condition_count += conditions
        else:
            issues.add("unsupported-named-sheet-view-filter-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    if len(sort_rules) > 1:
        issues.add("multiple-named-sheet-view-sort-rule-containers")
    return (
        (
            "nsvFilter",
            _named_sheet_view_binding_signature(binding),
            _filter_visibility_attributes(
                element,
                known=frozenset({"filterId", "ref", "tableId"}),
                issues=issues,
                unsigned_ints=frozenset({"tableId"}),
                references=frozenset({"ref"}),
                required=frozenset({"filterId"}),
                string_defaults={"ref": "none", "tableId": "none"},
                guid_attributes=frozenset({"filterId"}),
            ),
            tuple(sorted(column_filters, key=repr)),
            tuple(sort_rules),
            tuple(sorted(extensions, key=repr)),
        ),
        len(column_filters),
        criterion_count,
        sort_rule_count,
        sort_condition_count,
    )


def _named_sheet_view_part_signature(
    root: ElementTree.Element,
    issues: set[str],
    *,
    bindings: tuple[_NamedSheetViewAutoFilterBinding, ...],
) -> tuple[tuple[object, ...], int, int, int, int, int, int]:
    """Canonicalize one Named Sheet Views part while retaining settings privately."""
    named_views: list[tuple[object, ...]] = []
    extensions: list[tuple[object, ...]] = []
    filter_count = 0
    column_filter_count = 0
    criterion_count = 0
    sort_rule_count = 0
    sort_condition_count = 0
    for child in root:
        if (
            _xml_namespace(child.tag) == _NAMED_SHEET_VIEW_NS
            and _xml_local_name(child.tag) == "namedSheetView"
        ):
            filters: list[tuple[object, ...]] = []
            view_extensions: list[tuple[object, ...]] = []
            for view_child in child:
                if (
                    _xml_namespace(view_child.tag) == _NAMED_SHEET_VIEW_NS
                    and _xml_local_name(view_child.tag) == "nsvFilter"
                ):
                    signature, columns, criteria, rules, conditions = (
                        _named_sheet_view_filter_signature(
                            view_child,
                            issues,
                            bindings=bindings,
                        )
                    )
                    filters.append(signature)
                    filter_count += 1
                    column_filter_count += columns
                    criterion_count += criteria
                    sort_rule_count += rules
                    sort_condition_count += conditions
                else:
                    issues.add("unsupported-named-sheet-view-child")
                    view_extensions.append(
                        _filter_visibility_unknown_child_signature(view_child)
                    )
            named_views.append(
                (
                    "namedSheetView",
                    _filter_visibility_attributes(
                        child,
                        known=frozenset({"name", "id"}),
                        issues=issues,
                        required=frozenset({"name", "id"}),
                        guid_attributes=frozenset({"id"}),
                    ),
                    tuple(sorted(filters, key=repr)),
                    tuple(sorted(view_extensions, key=repr)),
                )
            )
        else:
            issues.add("unsupported-named-sheet-views-child")
            extensions.append(_filter_visibility_unknown_child_signature(child))
    return (
        (
            "namedSheetViews",
            _filter_visibility_attributes(
                root,
                known=frozenset(),
                issues=issues,
                ignored_namespaced_attributes=frozenset(
                    {(_MARKUP_COMPATIBILITY_NS, "Ignorable")}
                ),
            ),
            tuple(sorted(named_views, key=repr)),
            tuple(sorted(extensions, key=repr)),
        ),
        len(named_views),
        filter_count,
        column_filter_count,
        criterion_count,
        sort_rule_count,
        sort_condition_count,
    )


def _named_sheet_view_metadata(path: Path) -> _NamedSheetViewMetadata:
    """Inspect relationship-backed modern Excel Named Sheet Views from raw OOXML.

    View names, filter values, sort keys, and targets can be sensitive. Their
    complete canonical forms are retained only inside ``definition_signature``;
    public output contains counts and coverage state.
    """
    warnings: set[str] = set()
    default = NamedSheetViewSnapshot()
    entries: list[tuple[str, str]] = []
    worksheets_with_views: set[str] = set()
    part_count = 0
    named_sheet_view_count = 0
    named_filter_count = 0
    column_filter_count = 0
    filter_criterion_count = 0
    sort_rule_count = 0
    sort_condition_count = 0
    unrecognized_named_sheet_view_count = 0
    total_part_bytes = 0
    inspected_part_count = 0

    try:
        with ZipFile(path) as archive:
            for sheet, worksheet_member in _worksheet_xml_paths(archive).items():
                relationship_member = _relationship_part_path(worksheet_member)
                if relationship_member not in archive.namelist():
                    continue
                try:
                    relationships = _package_relationships(archive, worksheet_member)
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    warnings.add(
                        "FormulaFence could not inspect worksheet relationships while "
                        f"reading Named Sheet Views ({type(error).__name__}); affected "
                        "alternate views were not compared."
                    )
                    entries.append(
                        (
                            f"named-sheet-views-relationships:{sheet.casefold()}",
                            type(error).__name__,
                        )
                    )
                    unrecognized_named_sheet_view_count += 1
                    continue
                view_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type == _NAMED_SHEET_VIEW_RELATIONSHIP
                ]
                if not view_relationships:
                    continue
                worksheets_with_views.add(sheet.casefold())
                bindings, binding_issues = _named_sheet_view_base_filter_bindings(
                    archive,
                    worksheet_member=worksheet_member,
                    relationships=relationships,
                )
                if binding_issues:
                    warnings.add(
                        "FormulaFence could not fully reconcile Named Sheet Views to their "
                        "base AutoFilters; affected alternate filter and sort controls have "
                        "a coverage gap."
                    )
                    entries.append(
                        (
                            f"named-sheet-view-bindings:{sheet.casefold()}",
                            repr(binding_issues),
                        )
                    )
                    unrecognized_named_sheet_view_count += 1
                part_count += len(view_relationships)
                seen_targets: set[str] = set()
                for relationship_index, relationship in enumerate(view_relationships):
                    context = (
                        f"named-sheet-views:{sheet.casefold()}:{relationship_index}"
                    )
                    if relationship.target is None:
                        warnings.add(
                            "FormulaFence found an unsafe or external Named Sheet View "
                            "relationship; the affected alternate view was not compared."
                        )
                        entries.append(
                            (
                                f"{context}:unsafe-relationship",
                                repr(
                                    (
                                        relationship.relationship_type,
                                        relationship.target_mode,
                                    )
                                ),
                            )
                        )
                        unrecognized_named_sheet_view_count += 1
                        continue
                    if relationship.target in seen_targets:
                        warnings.add(
                            "FormulaFence found repeated Named Sheet View relationships; "
                            "the affected alternate view has a coverage gap."
                        )
                        entries.append(
                            (f"{context}:repeated-target", "repeated")
                        )
                        unrecognized_named_sheet_view_count += 1
                        continue
                    seen_targets.add(relationship.target)
                    if inspected_part_count >= _NAMED_SHEET_VIEW_TOTAL_MAX_COUNT:
                        warnings.add(
                            "FormulaFence did not inspect all Named Sheet View parts because "
                            "the part-count limit was exceeded."
                        )
                        entries.append((f"{context}:part-count-limit", "exceeded"))
                        unrecognized_named_sheet_view_count += 1
                        continue
                    try:
                        part_size = archive.getinfo(relationship.target).file_size
                    except KeyError:
                        warnings.add(
                            "FormulaFence could not locate a Named Sheet View part; the "
                            "affected alternate view was not compared."
                        )
                        entries.append((f"{context}:missing-part", "missing"))
                        unrecognized_named_sheet_view_count += 1
                        continue
                    if part_size > _NAMED_SHEET_VIEW_MAX_PART_BYTES:
                        warnings.add(
                            "FormulaFence did not fully read an oversized Named Sheet View "
                            "part; the affected alternate view has a coverage gap."
                        )
                        entries.append((f"{context}:part-size-limit", str(part_size)))
                        unrecognized_named_sheet_view_count += 1
                        continue
                    if total_part_bytes + part_size > _NAMED_SHEET_VIEW_TOTAL_MAX_BYTES:
                        warnings.add(
                            "FormulaFence did not inspect all Named Sheet View parts because "
                            "the aggregate XML-size limit was exceeded."
                        )
                        entries.append((f"{context}:total-size-limit", str(part_size)))
                        unrecognized_named_sheet_view_count += 1
                        continue
                    total_part_bytes += part_size
                    inspected_part_count += 1
                    try:
                        root = _xml_root(archive, relationship.target)
                    except (
                        ElementTree.ParseError,
                        KeyError,
                        OSError,
                        RuntimeError,
                        ValueError,
                    ) as error:
                        warnings.add(
                            "FormulaFence could not read a Named Sheet View part "
                            f"({type(error).__name__}); the affected alternate view was not "
                            "compared."
                        )
                        entries.append((f"{context}:unreadable-part", type(error).__name__))
                        unrecognized_named_sheet_view_count += 1
                        continue
                    if (
                        _xml_namespace(root.tag) != _NAMED_SHEET_VIEW_NS
                        or _xml_local_name(root.tag) != "namedSheetViews"
                    ):
                        warnings.add(
                            "FormulaFence found a Named Sheet View relationship with an "
                            "unexpected root; the affected alternate view was not compared."
                        )
                        entries.append(
                            (
                                f"{context}:unexpected-root",
                                _private_payload_signature(
                                    ElementTree.tostring(root, encoding="utf-8")
                                ),
                            )
                        )
                        unrecognized_named_sheet_view_count += 1
                        continue
                    issues: set[str] = set()
                    (
                        signature,
                        views,
                        filters,
                        columns,
                        criteria,
                        rules,
                        conditions,
                    ) = _named_sheet_view_part_signature(
                        root,
                        issues,
                        bindings=bindings,
                    )
                    entries.append((context, repr(signature)))
                    named_sheet_view_count += views
                    named_filter_count += filters
                    column_filter_count += columns
                    filter_criterion_count += criteria
                    sort_rule_count += rules
                    sort_condition_count += conditions
                    unrecognized_named_sheet_view_count += bool(issues)
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _NamedSheetViewMetadata(
            default,
            (
                "FormulaFence could not inspect Named Sheet View OOXML "
                f"({type(error).__name__}); alternate filter and sort controls were not "
                "compared.",
            ),
        )

    if unrecognized_named_sheet_view_count:
        warnings.add(
            "FormulaFence found malformed or unsupported Named Sheet View metadata; "
            "alternate filter and sort controls have a coverage gap."
        )
    snapshot = NamedSheetViewSnapshot(
        worksheet_count=len(worksheets_with_views),
        part_count=part_count,
        named_sheet_view_count=named_sheet_view_count,
        named_filter_count=named_filter_count,
        column_filter_count=column_filter_count,
        filter_criterion_count=filter_criterion_count,
        sort_rule_count=sort_rule_count,
        sort_condition_count=sort_condition_count,
        unrecognized_named_sheet_view_count=unrecognized_named_sheet_view_count,
        definition_signature=_private_external_data_signature(tuple(sorted(entries))),
    )
    return _NamedSheetViewMetadata(snapshot, tuple(sorted(warnings)))


def _custom_workbook_view_unsigned(value: str | None) -> int | None:
    """Read one bounded XML unsigned integer without unbounded conversion."""
    if value is None:
        return None
    candidate = value.strip()
    if not (candidate.isascii() and candidate.isdecimal()):
        return None
    significant = candidate.lstrip("0") or "0"
    if len(significant) > len(str(_CUSTOM_WORKBOOK_VIEW_UNSIGNED_MAXIMUM)):
        return None
    parsed = int(significant)
    return parsed if parsed <= _CUSTOM_WORKBOOK_VIEW_UNSIGNED_MAXIMUM else None


def _custom_workbook_view_signed(value: str | None) -> int | None:
    """Read one bounded XML signed integer without accepting arbitrary values."""
    if value is None:
        return None
    candidate = value.strip()
    sign = ""
    if candidate[:1] in {"+", "-"}:
        sign, candidate = candidate[:1], candidate[1:]
    if not (candidate.isascii() and candidate.isdecimal()):
        return None
    significant = candidate.lstrip("0") or "0"
    if len(significant) > 10:
        return None
    parsed = int(f"{sign}{significant}")
    if _CUSTOM_WORKBOOK_VIEW_SIGNED_MINIMUM <= parsed <= _CUSTOM_WORKBOOK_VIEW_SIGNED_MAXIMUM:
        return parsed
    return None


def _custom_workbook_view_attributes(
    element: ElementTree.Element,
    *,
    known: frozenset[str],
    issues: set[str],
    boolean_defaults: Mapping[str, bool] = {},
    unsigned_defaults: Mapping[str, int] = {},
    signed_defaults: Mapping[str, int] = {},
    enum_defaults: Mapping[str, str] = {},
    enum_values: Mapping[str, frozenset[str]] = {},
    unsigned_attributes: frozenset[str] = frozenset(),
    signed_attributes: frozenset[str] = frozenset(),
    guid_attributes: frozenset[str] = frozenset(),
    required: frozenset[str] = frozenset(),
    ignored: frozenset[str] = frozenset(),
) -> tuple[tuple[str, str], ...]:
    """Canonicalize one Custom View attribute set without public disclosure.

    SpreadsheetML writers commonly choose different Boolean and integer
    spellings. Defaults are materialized here while GUID values are represented
    only by a stable token; their workbook-to-sheet linkage is reconciled later.
    """
    values: dict[str, str] = {
        name: "true" if value else "false"
        for name, value in boolean_defaults.items()
    }
    values.update({name: str(value) for name, value in unsigned_defaults.items()})
    values.update({name: str(value) for name, value in signed_defaults.items()})
    values.update(enum_defaults)
    seen: set[str] = set()
    for attribute, value in element.attrib.items():
        local_name = _xml_local_name(attribute)
        namespace = _xml_namespace(attribute)
        if local_name in ignored and namespace is None:
            continue
        if namespace is not None or local_name not in known:
            issues.add(f"unknown-attribute:{_xml_display_name(attribute)}")
            values[f"unknown:{_xml_display_name(attribute)}"] = value
            continue
        seen.add(local_name)
        if local_name in boolean_defaults:
            parsed = _number_format_boolean(value, boolean_defaults[local_name])
            if parsed is None:
                issues.add(f"invalid-{local_name}")
                values[local_name] = f"invalid:{value}"
            else:
                values[local_name] = "true" if parsed else "false"
        elif local_name in unsigned_attributes or local_name in unsigned_defaults:
            parsed = _custom_workbook_view_unsigned(value)
            if parsed is None:
                issues.add(f"invalid-{local_name}")
                values[local_name] = f"invalid:{value}"
            else:
                values[local_name] = str(parsed)
        elif local_name in signed_attributes or local_name in signed_defaults:
            parsed = _custom_workbook_view_signed(value)
            if parsed is None:
                issues.add(f"invalid-{local_name}")
                values[local_name] = f"invalid:{value}"
            else:
                values[local_name] = str(parsed)
        elif local_name in enum_values:
            if value not in enum_values[local_name]:
                issues.add(f"invalid-{local_name}")
                values[local_name] = f"invalid:{value}"
            else:
                values[local_name] = value
        elif local_name in guid_attributes:
            if _named_sheet_view_guid(value) is None:
                issues.add(f"invalid-{local_name}")
                values[local_name] = f"invalid:{value}"
            else:
                values[local_name] = "{GUID}"
        else:
            values[local_name] = value
    for name in required:
        if name not in seen:
            issues.add(f"missing-{name}")
            values[name] = "missing"
    return tuple(sorted(values.items()))


def _custom_workbook_view_attribute_value(
    attributes: tuple[tuple[str, str], ...], name: str
) -> str | None:
    """Return one private canonical Custom View attribute value."""
    return dict(attributes).get(name)


def _custom_workbook_view_replace_attribute(
    attributes: tuple[tuple[str, str], ...], name: str, value: str
) -> tuple[tuple[str, str], ...]:
    """Replace an already-canonical attribute without changing its ordering."""
    return tuple(
        (attribute, value if attribute == name else current)
        for attribute, current in attributes
    )


def _custom_workbook_view_compatibility_element(
    element: ElementTree.Element,
) -> ElementTree.Element:
    """Map strict SpreadsheetML names to transitional names for shared parsers."""
    if not any(
        _xml_namespace(current.tag) == _STRICT_SPREADSHEETML_NS
        or any(
            _xml_namespace(attribute) == _STRICT_SPREADSHEETML_NS
            for attribute in current.attrib
        )
        for current in element.iter()
    ):
        return element
    compatible = _xml_root_from_payload(ElementTree.tostring(element, encoding="utf-8"))
    for current in compatible.iter():
        if _xml_namespace(current.tag) == _STRICT_SPREADSHEETML_NS:
            current.tag = f"{{{_SPREADSHEETML_NS}}}{_xml_local_name(current.tag)}"
        replacements = {
            attribute: f"{{{_SPREADSHEETML_NS}}}{_xml_local_name(attribute)}"
            for attribute in current.attrib
            if _xml_namespace(attribute) == _STRICT_SPREADSHEETML_NS
        }
        for old_name, new_name in replacements.items():
            current.attrib[new_name] = current.attrib.pop(old_name)
    return compatible


def _custom_workbook_view_generic_signature(element: ElementTree.Element) -> str:
    """Hash a known-but-not-specialized Custom View subtree deterministically."""

    def canonical_name(name: str) -> tuple[str, str]:
        namespace = _xml_namespace(name)
        if namespace == _STRICT_SPREADSHEETML_NS:
            namespace = _SPREADSHEETML_NS
        return namespace or "", _xml_local_name(name)

    def canonical(current: ElementTree.Element) -> tuple[object, ...]:
        attributes: list[tuple[tuple[str, str], str]] = []
        for attribute, value in current.attrib.items():
            normalized = (
                "{GUID}"
                if _xml_local_name(attribute) == "guid"
                and _named_sheet_view_guid(value) is not None
                else value
            )
            attributes.append((canonical_name(attribute), normalized))
        return (
            canonical_name(current.tag),
            tuple(sorted(attributes)),
            current.text or "",
            tuple(canonical(child) for child in current),
        )

    return _private_external_data_signature(
        (("custom-workbook-view-generic", repr(canonical(element))),)
    ) or ""


def _custom_workbook_view_unknown_signature(
    element: ElementTree.Element,
) -> tuple[str, str, str]:
    """Keep unsupported Custom View XML private while retaining a stable digest."""
    return (
        "unknown",
        _xml_display_name(element.tag),
        _custom_workbook_view_generic_signature(element),
    )


def _custom_workbook_view_pane_signature(
    element: ElementTree.Element, issues: set[str]
) -> tuple[tuple[object, ...], bool]:
    """Canonicalize material split/frozen state while ignoring navigation noise."""
    values: list[tuple[str, str]] = []
    unknown: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        local_name = _xml_local_name(attribute)
        if _xml_namespace(attribute) is not None or local_name not in {
            "activePane",
            "state",
            "topLeftCell",
            "xSplit",
            "ySplit",
        }:
            issues.add("unsupported-pane-attribute")
            unknown.append((_xml_display_name(attribute), value))
            continue
        if local_name in {"activePane", "topLeftCell"}:
            # Selection and navigation change constantly during ordinary use;
            # this boundary tracks display state, not where a user last clicked.
            continue
        if local_name in {"xSplit", "ySplit"}:
            parsed = _worksheet_display_decimal(value)
            if parsed is None:
                issues.add(f"invalid-pane-{local_name}")
                values.append((local_name, f"invalid:{value}"))
            elif parsed != "0":
                values.append((local_name, parsed))
            continue
        if value not in _WORKSHEET_DISPLAY_PANE_STATES:
            issues.add("invalid-pane-state")
            values.append(("state", f"invalid:{value}"))
        elif value != "split":
            values.append(("state", value))
    if list(element):
        issues.add("unexpected-pane-children")
        unknown.extend(
            ("child", _custom_workbook_view_generic_signature(child))
            for child in element
        )
    signature = ("pane", tuple(sorted(values)), tuple(sorted(unknown)))
    return signature, bool(values)


def _custom_workbook_view_standard_sheet_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[tuple[object, ...], str | None, bool, bool, bool, bool]:
    """Canonicalize one worksheet/dialog-sheet Custom View declaration."""
    view = _custom_workbook_view_compatibility_element(element)
    attributes = _custom_workbook_view_attributes(
        view,
        known=frozenset(
            {
                "guid",
                "scale",
                "colorId",
                "showPageBreaks",
                "showFormulas",
                "showGridLines",
                "showRowCol",
                "outlineSymbols",
                "zeroValues",
                "fitToPage",
                "printArea",
                "filter",
                "showAutoFilter",
                "hiddenRows",
                "hiddenColumns",
                "state",
                "filterUnique",
                "view",
                "showRuler",
                "topLeftCell",
            }
        ),
        issues=issues,
        boolean_defaults={
            "showPageBreaks": False,
            "showFormulas": False,
            "showGridLines": True,
            "showRowCol": True,
            "outlineSymbols": True,
            "zeroValues": True,
            "fitToPage": False,
            "printArea": False,
            "filter": False,
            "showAutoFilter": False,
            "hiddenRows": False,
            "hiddenColumns": False,
            "filterUnique": False,
            "showRuler": True,
        },
        unsigned_defaults={"scale": 100, "colorId": 64},
        enum_defaults={"state": "visible", "view": "normal"},
        enum_values={
            "state": _CUSTOM_WORKBOOK_VIEW_SHEET_STATE_VALUES,
            "view": _CUSTOM_WORKBOOK_VIEW_SHEET_VIEW_VALUES,
        },
        unsigned_attributes=frozenset({"scale", "colorId"}),
        guid_attributes=frozenset({"guid"}),
        required=frozenset({"guid"}),
        ignored=frozenset({"topLeftCell"}),
    )
    raw_scale = _custom_workbook_view_unsigned(view.get("scale"))
    if raw_scale is not None and not 10 <= raw_scale <= 400:
        issues.add("invalid-scale-range")
    values = dict(attributes)
    child_signatures: list[tuple[object, ...]] = []
    seen_children: dict[str, int] = {}
    last_child_order = -1
    pane_material = False
    has_filter_child = False
    has_print_child = False
    for child in view:
        namespace = _xml_namespace(child.tag)
        local_name = _xml_local_name(child.tag)
        if (
            namespace != _SPREADSHEETML_NS
            or local_name not in _CUSTOM_WORKBOOK_VIEW_STANDARD_CHILD_ORDER
        ):
            issues.add("unsupported-custom-sheet-view-child")
            child_signatures.append(_custom_workbook_view_unknown_signature(child))
            continue
        order = _CUSTOM_WORKBOOK_VIEW_STANDARD_CHILD_ORDER[local_name]
        if order < last_child_order:
            issues.add("out-of-order-custom-sheet-view-child")
        last_child_order = max(last_child_order, order)
        seen_children[local_name] = seen_children.get(local_name, 0) + 1
        if seen_children[local_name] > 1:
            issues.add(f"multiple-custom-sheet-view-{local_name}")
        if local_name == "selection":
            # Selections are explicitly navigation-only and do not alter the
            # saved review/print surface. Their values remain unreported.
            continue
        if local_name == "pane":
            signature, material = _custom_workbook_view_pane_signature(child, issues)
            pane_material = pane_material or material
            if material or signature[2]:
                child_signatures.append(signature)
            continue
        if local_name in {"rowBreaks", "colBreaks"}:
            axis = "row" if local_name == "rowBreaks" else "column"
            signature, _count = _worksheet_print_layout_breaks_signature(
                child,
                axis=axis,
                context=f"custom-sheet-view:{local_name}",
                note_issue=lambda reason, detail, name=local_name: issues.add(
                    f"{name}:{reason}"
                ),
            )
            child_signatures.append((local_name, signature))
            has_print_child = True
            continue
        if local_name == "pageMargins":
            signature = _worksheet_print_layout_page_margins_signature(
                child,
                context="custom-sheet-view:pageMargins",
                note_issue=lambda reason, detail: issues.add(
                    f"pageMargins:{reason}"
                ),
            )
            child_signatures.append((local_name, signature))
            has_print_child = True
            continue
        if local_name == "printOptions":
            signature, _active = _worksheet_print_layout_print_options_signature(
                child,
                context="custom-sheet-view:printOptions",
                note_issue=lambda reason, detail: issues.add(
                    f"printOptions:{reason}"
                ),
            )
            child_signatures.append((local_name, signature))
            has_print_child = True
            continue
        if local_name == "pageSetup":
            fit_to_page = (
                True
                if values.get("fitToPage") == "true"
                else False
                if values.get("fitToPage") == "false"
                else None
            )
            signature, _material = _worksheet_print_layout_page_setup_signature(
                child,
                context="custom-sheet-view:pageSetup",
                note_issue=lambda reason, detail: issues.add(f"pageSetup:{reason}"),
                fit_to_page=fit_to_page,
            )
            child_signatures.append((local_name, signature))
            has_print_child = True
            continue
        if local_name == "headerFooter":
            signature, _material = _worksheet_print_layout_header_footer_signature(
                child,
                context="custom-sheet-view:headerFooter",
                note_issue=lambda reason, detail: issues.add(
                    f"headerFooter:{reason}"
                ),
            )
            child_signatures.append((local_name, signature))
            has_print_child = True
            continue
        if local_name == "autoFilter":
            signature, _columns, _criteria, _sorts, _conditions = (
                _filter_visibility_auto_filter_signature(child, issues)
            )
            child_signatures.append((local_name, signature))
            has_filter_child = True
            continue
        issues.add("unsupported-custom-sheet-view-extension")
        child_signatures.append(_custom_workbook_view_unknown_signature(child))

    hidden = values.get("hiddenRows") == "true" or values.get("hiddenColumns") == "true"
    filtered = (
        values.get("filter") == "true"
        or values.get("filterUnique") == "true"
        or has_filter_child
    )
    print_settings = (
        values.get("scale") != "100"
        or values.get("fitToPage") == "true"
        or values.get("printArea") == "true"
        or has_print_child
    )
    display_settings = pane_material or any(
        values.get(name) != default
        for name, default in {
            "colorId": "64",
            "showPageBreaks": "false",
            "showFormulas": "false",
            "showGridLines": "true",
            "showRowCol": "true",
            "outlineSymbols": "true",
            "zeroValues": "true",
            "showAutoFilter": "false",
            "state": "visible",
            "view": "normal",
            "showRuler": "true",
        }.items()
    )
    return (
        ("customSheetView", attributes, tuple(child_signatures)),
        _named_sheet_view_guid(view.get("guid")),
        hidden,
        filtered,
        print_settings,
        display_settings,
    )


def _custom_workbook_view_chart_page_setup_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[object, ...]:
    """Canonicalize a chart-sheet page setup without claiming printer support."""
    page_setup = _custom_workbook_view_compatibility_element(element)
    attributes = _custom_workbook_view_attributes(
        page_setup,
        known=frozenset(
            set(_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_BOOLEAN_DEFAULTS)
            | set(_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_UNSIGNED_DEFAULTS)
            | set(_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_ENUM_DEFAULTS)
            | {"paperHeight", "paperWidth"}
        ),
        issues=issues,
        boolean_defaults=_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_BOOLEAN_DEFAULTS,
        unsigned_defaults=_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_UNSIGNED_DEFAULTS,
        enum_defaults=_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_ENUM_DEFAULTS,
        enum_values=_CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_ENUM_VALUES,
        unsigned_attributes=frozenset(
            _CUSTOM_WORKBOOK_VIEW_CHART_PAGE_SETUP_UNSIGNED_DEFAULTS
        ),
    )
    for name in ("paperHeight", "paperWidth"):
        raw_value = page_setup.get(name)
        if raw_value is None:
            continue
        value = _worksheet_print_layout_measure(raw_value, units=None)
        if value is None:
            issues.add(f"invalid-chart-{name}")
            attributes = _custom_workbook_view_replace_attribute(
                attributes,
                name,
                f"invalid:{raw_value}",
            )
        else:
            attributes = _custom_workbook_view_replace_attribute(
                attributes,
                name,
                value,
            )

    unexpected_children: list[tuple[str, str, str]] = []
    if page_setup.text and page_setup.text.strip():
        issues.add("unexpected-chart-page-setup-text")
        unexpected_children.append(
            ("text", "", _custom_workbook_view_generic_signature(page_setup))
        )
    for child in page_setup:
        issues.add("unexpected-chart-page-setup-child")
        unexpected_children.append(_custom_workbook_view_unknown_signature(child))
    return ("chartPageSetup", attributes, tuple(unexpected_children))


def _custom_workbook_view_chart_sheet_signature(
    element: ElementTree.Element,
    issues: set[str],
) -> tuple[tuple[object, ...], str | None, bool, bool, bool, bool]:
    """Canonicalize one chart-sheet Custom View declaration."""
    view = _custom_workbook_view_compatibility_element(element)
    attributes = _custom_workbook_view_attributes(
        view,
        known=frozenset({"guid", "scale", "state", "zoomToFit"}),
        issues=issues,
        boolean_defaults={"zoomToFit": False},
        unsigned_defaults={"scale": 100},
        enum_defaults={"state": "visible"},
        enum_values={"state": _CUSTOM_WORKBOOK_VIEW_SHEET_STATE_VALUES},
        unsigned_attributes=frozenset({"scale"}),
        guid_attributes=frozenset({"guid"}),
        required=frozenset({"guid"}),
    )
    raw_scale = _custom_workbook_view_unsigned(view.get("scale"))
    if raw_scale is not None and not 10 <= raw_scale <= 400:
        issues.add("invalid-chart-scale-range")
    values = dict(attributes)
    child_signatures: list[tuple[object, ...]] = []
    seen_children: dict[str, int] = {}
    last_child_order = -1
    has_print_child = False
    for child in view:
        namespace = _xml_namespace(child.tag)
        local_name = _xml_local_name(child.tag)
        if (
            namespace != _SPREADSHEETML_NS
            or local_name not in _CUSTOM_WORKBOOK_VIEW_CHART_CHILD_ORDER
        ):
            issues.add("unsupported-chart-custom-sheet-view-child")
            child_signatures.append(_custom_workbook_view_unknown_signature(child))
            continue
        order = _CUSTOM_WORKBOOK_VIEW_CHART_CHILD_ORDER[local_name]
        if order < last_child_order:
            issues.add("out-of-order-chart-custom-sheet-view-child")
        last_child_order = max(last_child_order, order)
        seen_children[local_name] = seen_children.get(local_name, 0) + 1
        if seen_children[local_name] > 1:
            issues.add(f"multiple-chart-custom-sheet-view-{local_name}")
        if local_name == "pageMargins":
            signature = _worksheet_print_layout_page_margins_signature(
                child,
                context="chart-custom-sheet-view:pageMargins",
                note_issue=lambda reason, detail: issues.add(
                    f"chart-pageMargins:{reason}"
                ),
            )
        elif local_name == "headerFooter":
            signature, _material = _worksheet_print_layout_header_footer_signature(
                child,
                context="chart-custom-sheet-view:headerFooter",
                note_issue=lambda reason, detail: issues.add(
                    f"chart-headerFooter:{reason}"
                ),
            )
        else:
            signature = _custom_workbook_view_chart_page_setup_signature(child, issues)
        child_signatures.append((local_name, signature))
        has_print_child = True
    print_settings = values.get("scale") != "100" or has_print_child
    display_settings = (
        values.get("state") != "visible" or values.get("zoomToFit") == "true"
    )
    return (
        ("chartCustomSheetView", attributes, tuple(child_signatures)),
        _named_sheet_view_guid(view.get("guid")),
        False,
        False,
        print_settings,
        display_settings,
    )


def _custom_workbook_view_workbook_signature(
    element: ElementTree.Element,
    issues: set[str],
    *,
    sheet_index_by_id: Mapping[int, int],
) -> tuple[tuple[object, ...], str | None]:
    """Canonicalize one workbook-level Custom View and bind its active sheet."""
    attributes = _custom_workbook_view_attributes(
        element,
        known=frozenset(
            {
                "name",
                "guid",
                "autoUpdate",
                "mergeInterval",
                "changesSavedWin",
                "onlySync",
                "personalView",
                "includePrintSettings",
                "includeHiddenRowCol",
                "maximized",
                "minimized",
                "showHorizontalScroll",
                "showVerticalScroll",
                "showSheetTabs",
                "xWindow",
                "yWindow",
                "windowWidth",
                "windowHeight",
                "tabRatio",
                "activeSheetId",
                "showFormulaBar",
                "showStatusbar",
                "showComments",
                "showObjects",
            }
        ),
        issues=issues,
        boolean_defaults={
            "autoUpdate": False,
            "changesSavedWin": False,
            "onlySync": False,
            "personalView": False,
            "includePrintSettings": True,
            "includeHiddenRowCol": True,
            "maximized": False,
            "minimized": False,
            "showHorizontalScroll": True,
            "showVerticalScroll": True,
            "showSheetTabs": True,
            "showFormulaBar": True,
            "showStatusbar": True,
        },
        signed_defaults={"xWindow": 0, "yWindow": 0},
        unsigned_defaults={"tabRatio": 600},
        enum_defaults={"showComments": "commIndicator", "showObjects": "all"},
        enum_values={
            "showComments": _CUSTOM_WORKBOOK_VIEW_COMMENTS_VALUES,
            "showObjects": _CUSTOM_WORKBOOK_VIEW_OBJECT_VALUES,
        },
        unsigned_attributes=frozenset(
            {"mergeInterval", "windowWidth", "windowHeight", "tabRatio", "activeSheetId"}
        ),
        signed_attributes=frozenset({"xWindow", "yWindow"}),
        guid_attributes=frozenset({"guid"}),
        required=frozenset(
            {"name", "guid", "windowWidth", "windowHeight", "activeSheetId"}
        ),
    )
    active_sheet_id = _custom_workbook_view_unsigned(element.get("activeSheetId"))
    if active_sheet_id is None:
        issues.add("invalid-active-sheet-id")
    elif (sheet_index := sheet_index_by_id.get(active_sheet_id)) is None:
        issues.add("unbound-active-sheet-id")
    else:
        attributes = _custom_workbook_view_replace_attribute(
            attributes, "activeSheetId", f"sheet:{sheet_index}"
        )
    children: list[tuple[object, ...]] = []
    extension_count = 0
    for child in element:
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) == "extLst"
        ):
            extension_count += 1
            issues.add("unsupported-custom-workbook-view-extension")
            children.append(_custom_workbook_view_unknown_signature(child))
        else:
            issues.add("unsupported-custom-workbook-view-child")
            children.append(_custom_workbook_view_unknown_signature(child))
    if extension_count > 1:
        issues.add("multiple-custom-workbook-view-extensions")
    return (
        ("customWorkbookView", attributes, tuple(children)),
        _named_sheet_view_guid(element.get("guid")),
    )


def _custom_workbook_view_sheet_bindings(
    archive: ZipFile,
    workbook: ElementTree.Element,
    *,
    note_issue: Callable[[str, object], None],
) -> tuple[_CustomWorkbookViewSheetBinding, ...]:
    """Resolve workbook sheet IDs to package parts without disclosing titles."""
    namespace = _xml_namespace(workbook.tag)
    if (
        _xml_local_name(workbook.tag) != "workbook"
        or namespace not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
    ):
        note_issue("workbook:unexpected-root", workbook.tag)
        return ()
    relationship_groups: dict[str, list[_PackageRelationship]] = defaultdict(list)
    for relationship in _package_relationships(archive, "xl/workbook.xml"):
        if relationship.relationship_id:
            relationship_groups[relationship.relationship_id].append(relationship)
    sheets_tag = f"{{{namespace}}}sheets"
    sheet_tag = f"{{{namespace}}}sheet"
    containers = [child for child in workbook if child.tag == sheets_tag]
    if len(containers) != 1:
        note_issue("workbook:invalid-sheets-container-count", len(containers))
    if not containers:
        return ()
    bindings: list[_CustomWorkbookViewSheetBinding] = []
    seen_sheet_ids: set[int] = set()
    relationship_attributes = (
        f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id",
        f"{{{_STRICT_DOCUMENT_RELATIONSHIP_NS}}}id",
    )
    for sheet_index, sheet in enumerate(containers[0]):
        context = f"sheet:{sheet_index}"
        if sheet.tag != sheet_tag:
            note_issue(f"{context}:unsupported-child", sheet.tag)
            continue
        sheet_id = _custom_workbook_view_unsigned(sheet.get("sheetId"))
        if sheet_id is None:
            note_issue(f"{context}:invalid-sheet-id", sheet.get("sheetId"))
        elif sheet_id in seen_sheet_ids:
            note_issue(f"{context}:duplicate-sheet-id", sheet_id)
        else:
            seen_sheet_ids.add(sheet_id)
        relationship_ids = [
            value for attribute in relationship_attributes if (value := sheet.get(attribute))
        ]
        if len(relationship_ids) != 1:
            note_issue(f"{context}:invalid-relationship-id", tuple(relationship_ids))
            bindings.append(
                _CustomWorkbookViewSheetBinding(sheet_index, sheet_id, None, None)
            )
            continue
        relationships = relationship_groups.get(relationship_ids[0], [])
        if len(relationships) != 1:
            note_issue(
                f"{context}:invalid-relationship-binding",
                tuple(
                    (
                        relationship.relationship_type,
                        relationship.target_mode,
                        relationship.raw_target,
                    )
                    for relationship in relationships
                ),
            )
            bindings.append(
                _CustomWorkbookViewSheetBinding(sheet_index, sheet_id, None, None)
            )
            continue
        relationship = relationships[0]
        if relationship.target is None:
            note_issue(
                f"{context}:unsafe-or-external-sheet-target",
                (relationship.target_mode, relationship.raw_target),
            )
            bindings.append(
                _CustomWorkbookViewSheetBinding(sheet_index, sheet_id, None, None)
            )
            continue
        kind = relationship.relationship_type.rsplit("/", maxsplit=1)[-1]
        bindings.append(
            _CustomWorkbookViewSheetBinding(
                sheet_index,
                sheet_id,
                relationship.target,
                kind,
            )
        )
    return tuple(bindings)


def _custom_workbook_view_metadata(path: Path) -> _CustomWorkbookViewMetadata:
    """Inspect legacy Excel Custom Views directly from their raw OOXML parts.

    A workbook-level ``customWorkbookView`` binds its alternate display/print
    settings to ``customSheetView`` declarations through a GUID. The scanner
    resolves that linkage privately, normalizing a coordinated GUID rewrite
    while failing closed for ambiguous or incomplete associations.
    """
    default = CustomWorkbookViewSnapshot()
    warnings: set[str] = set()
    issues: dict[str, str] = {}
    association_issues: dict[str, str] = {}
    has_custom_view_container = False

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    def note_association_issue(context: str, detail: object) -> None:
        """Defer sheet-binding errors until this boundary is actually present."""
        association_issues.setdefault(context, repr(detail))

    custom_workbook_view_count = 0
    custom_sheet_view_count = 0
    custom_view_sheet_indices: set[int] = set()
    sheet_records: list[_CustomWorkbookViewSheetRecord] = []
    workbook_records: list[tuple[str | None, tuple[object, ...]]] = []
    bindings: tuple[_CustomWorkbookViewSheetBinding, ...] = ()
    try:
        with ZipFile(path) as archive:
            workbook = _xml_root(archive, "xl/workbook.xml")
            bindings = _custom_workbook_view_sheet_bindings(
                archive, workbook, note_issue=note_association_issue
            )
            xlm_macro_members = {
                binding.member
                for binding in bindings
                if (
                    binding.member is not None
                    and (binding.kind or "").casefold()
                    in {"xlmacrosheet", "xlintlmacrosheet"}
                )
            }
            sheet_index_by_id: dict[int, int] = {}
            duplicate_sheet_ids: set[int] = set()
            for binding in bindings:
                if binding.sheet_id is None:
                    continue
                if binding.sheet_id in sheet_index_by_id:
                    duplicate_sheet_ids.add(binding.sheet_id)
                    continue
                sheet_index_by_id[binding.sheet_id] = binding.index
            for duplicate_id in duplicate_sheet_ids:
                sheet_index_by_id.pop(duplicate_id, None)

            workbook_namespace = _xml_namespace(workbook.tag)
            containers = [
                child
                for child in workbook
                if _xml_local_name(child.tag) == "customWorkbookViews"
            ]
            has_custom_view_container = bool(containers)
            if workbook_namespace in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}:
                if len(containers) > 1:
                    note_issue(
                        "workbook:multiple-custom-workbook-view-containers",
                        len(containers),
                    )
                for container_index, container in enumerate(containers):
                    container_context = f"workbook:custom-views:{container_index}"
                    if _xml_namespace(container.tag) not in {
                        _SPREADSHEETML_NS,
                        _STRICT_SPREADSHEETML_NS,
                    }:
                        note_issue(
                            f"{container_context}:unsupported-namespace", container.tag
                        )
                        continue
                    compatible = _custom_workbook_view_compatibility_element(container)
                    if compatible.attrib:
                        note_issue(
                            f"{container_context}:unexpected-attributes",
                            tuple(sorted(compatible.attrib.items())),
                        )
                    if not list(compatible):
                        note_issue(f"{container_context}:missing-custom-views", "empty")
                    for view_index, view in enumerate(compatible):
                        view_context = f"{container_context}:view:{view_index}"
                        if (
                            _xml_namespace(view.tag) != _SPREADSHEETML_NS
                            or _xml_local_name(view.tag) != "customWorkbookView"
                        ):
                            note_issue(
                                f"{view_context}:unsupported-child",
                                _custom_workbook_view_unknown_signature(view),
                            )
                            continue
                        custom_workbook_view_count += 1
                        view_issues: set[str] = set()
                        signature, guid = _custom_workbook_view_workbook_signature(
                            view,
                            view_issues,
                            sheet_index_by_id=sheet_index_by_id,
                        )
                        if view_issues:
                            note_issue(
                                view_context,
                                (tuple(sorted(view_issues)), signature),
                            )
                        workbook_records.append((guid, signature))
            elif containers:
                note_issue("workbook:unsupported-namespace", workbook.tag)

            inspected_members: set[str] = set()
            total_sheet_part_bytes = 0
            inspected_sheet_part_count = 0
            for binding in bindings:
                context = f"sheet:{binding.index}"
                if binding.member is None:
                    continue
                if binding.member in xlm_macro_members:
                    # XLM source is privately covered by its dedicated raw
                    # macro scanner. This also covers an invalid second ordinary
                    # relationship to the same part. A Custom View can only be
                    # meaningful when its workbook-level declarations are
                    # present; defer an explicit association gap until that
                    # boundary exists rather than materializing an executable
                    # macro tree in an unrelated presentation scanner.
                    note_association_issue(
                        f"{context}:xlm-macro-sheet-not-scanned",
                        binding.member,
                    )
                    continue
                if binding.member in inspected_members:
                    note_association_issue(
                        f"{context}:repeated-sheet-target", binding.member
                    )
                    continue
                inspected_members.add(binding.member)
                if inspected_sheet_part_count >= _CUSTOM_WORKBOOK_VIEW_TOTAL_SHEET_PART_COUNT:
                    note_association_issue(
                        f"{context}:sheet-part-count-limit", binding.member
                    )
                    continue
                try:
                    info = archive.getinfo(binding.member)
                except KeyError:
                    note_association_issue(
                        f"{context}:missing-sheet-part", binding.member
                    )
                    continue
                if info.file_size > _CUSTOM_WORKBOOK_VIEW_MAX_SHEET_PART_BYTES:
                    note_association_issue(
                        f"{context}:oversized-sheet-part", info.file_size
                    )
                    continue
                if (
                    total_sheet_part_bytes + info.file_size
                    > _CUSTOM_WORKBOOK_VIEW_TOTAL_SHEET_PART_BYTES
                ):
                    note_association_issue(
                        f"{context}:total-sheet-part-size-limit", info.file_size
                    )
                    continue
                total_sheet_part_bytes += info.file_size
                inspected_sheet_part_count += 1
                try:
                    sheet_root = _xml_root(archive, binding.member)
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    note_association_issue(
                        f"{context}:unreadable-sheet-part", type(error).__name__
                    )
                    continue
                root_namespace = _xml_namespace(sheet_root.tag)
                root_name = _xml_local_name(sheet_root.tag)
                containers = [
                    child
                    for child in sheet_root
                    if _xml_local_name(child.tag) == "customSheetViews"
                ]
                if not containers:
                    continue
                has_custom_view_container = True
                if len(containers) > 1:
                    note_issue(
                        f"{context}:multiple-custom-sheet-view-containers",
                        len(containers),
                    )
                for container_index, container in enumerate(containers):
                    container_context = f"{context}:custom-sheet-views:{container_index}"
                    if _xml_namespace(container.tag) not in {
                        _SPREADSHEETML_NS,
                        _STRICT_SPREADSHEETML_NS,
                    }:
                        note_issue(
                            f"{container_context}:unsupported-namespace", container.tag
                        )
                        continue
                    compatible = _custom_workbook_view_compatibility_element(container)
                    if compatible.attrib:
                        note_issue(
                            f"{container_context}:unexpected-attributes",
                            tuple(sorted(compatible.attrib.items())),
                        )
                    if (
                        not list(compatible)
                        and root_name != _CUSTOM_WORKBOOK_VIEW_CHART_SHEET_ROOT
                    ):
                        note_issue(f"{container_context}:missing-custom-views", "empty")
                    for view_index, view in enumerate(compatible):
                        view_context = f"{container_context}:view:{view_index}"
                        if (
                            _xml_namespace(view.tag) != _SPREADSHEETML_NS
                            or _xml_local_name(view.tag) != "customSheetView"
                        ):
                            note_issue(
                                f"{view_context}:unsupported-child",
                                _custom_workbook_view_unknown_signature(view),
                            )
                            continue
                        custom_sheet_view_count += 1
                        view_issues: set[str] = set()
                        if (
                            root_namespace
                            in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                            and root_name in _CUSTOM_WORKBOOK_VIEW_STANDARD_SHEET_ROOTS
                        ):
                            (
                                signature,
                                guid,
                                hidden,
                                filtered,
                                print_settings,
                                display_settings,
                            ) = _custom_workbook_view_standard_sheet_signature(
                                view, view_issues
                            )
                        elif (
                            root_namespace
                            in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                            and root_name == _CUSTOM_WORKBOOK_VIEW_CHART_SHEET_ROOT
                        ):
                            (
                                signature,
                                guid,
                                hidden,
                                filtered,
                                print_settings,
                                display_settings,
                            ) = _custom_workbook_view_chart_sheet_signature(
                                view, view_issues
                            )
                        else:
                            view_issues.add("unsupported-custom-view-sheet-root")
                            signature = (
                                "unsupportedCustomSheetView",
                                _custom_workbook_view_generic_signature(view),
                            )
                            guid = _named_sheet_view_guid(view.get("guid"))
                            hidden = filtered = print_settings = display_settings = False
                        if view_issues:
                            note_issue(
                                view_context,
                                (tuple(sorted(view_issues)), signature),
                            )
                        custom_view_sheet_indices.add(binding.index)
                        sheet_records.append(
                            _CustomWorkbookViewSheetRecord(
                                guid=guid,
                                sheet_index=binding.index,
                                signature=signature,
                                hidden=hidden,
                                filtered=filtered,
                                print_settings=print_settings,
                                display_settings=display_settings,
                            )
                        )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _CustomWorkbookViewMetadata(
            default,
            (
                "FormulaFence could not inspect legacy Excel Custom View OOXML "
                f"({type(error).__name__}); alternate display and print views were not "
                "compared.",
            ),
        )

    if has_custom_view_container:
        for context, detail in association_issues.items():
            issues.setdefault(context, detail)

    records_by_guid: dict[str, list[_CustomWorkbookViewSheetRecord]] = defaultdict(list)
    for record in sheet_records:
        if record.guid is None:
            note_issue(
                f"sheet:{record.sheet_index}:custom-view:invalid-guid", record.signature
            )
        else:
            records_by_guid[record.guid].append(record)
    workbook_by_guid: dict[str, list[tuple[int, tuple[object, ...]]]] = defaultdict(list)
    for workbook_index, (guid, signature) in enumerate(workbook_records):
        if guid is None:
            note_issue(f"workbook:custom-view:{workbook_index}:invalid-guid", signature)
        else:
            workbook_by_guid[guid].append((workbook_index, signature))
    for guid, records in workbook_by_guid.items():
        if len(records) > 1:
            note_issue("workbook:duplicate-custom-view-guid", (guid, len(records)))
    for guid, records in records_by_guid.items():
        if guid not in workbook_by_guid:
            note_issue(
                "sheet:unbound-custom-view-guid",
                tuple((record.sheet_index, record.signature) for record in records),
            )

    definition_entries: list[tuple[str, str]] = []
    expected_sheet_indices = tuple(binding.index for binding in bindings)
    for guid, views in sorted(workbook_by_guid.items()):
        matching_sheet_records = records_by_guid.get(guid, [])
        for workbook_index, workbook_signature in views:
            linked_sheets: list[tuple[int, tuple[object, ...]]] = []
            for sheet_index in expected_sheet_indices:
                matching = [
                    record
                    for record in matching_sheet_records
                    if record.sheet_index == sheet_index
                ]
                if len(matching) != 1:
                    note_issue(
                        (
                            f"workbook:custom-view:{workbook_index}:"
                            f"sheet:{sheet_index}:association"
                        ),
                        tuple(record.signature for record in matching),
                    )
                    linked_sheets.append((sheet_index, ("association", len(matching))))
                    continue
                linked_sheets.append((sheet_index, matching[0].signature))
            definition_entries.append(
                (
                    f"custom-workbook-view:{workbook_index}",
                    repr((workbook_signature, tuple(linked_sheets))),
                )
            )

    issue_entries = tuple(
        (f"custom-workbook-view-issue:{context}", detail)
        for context, detail in sorted(issues.items())
    )
    if issues:
        warnings.add(
            "FormulaFence found malformed, unsupported, or incompletely linked legacy "
            "Excel Custom View metadata; affected alternate display and print views have "
            "a coverage gap."
        )
    snapshot = CustomWorkbookViewSnapshot(
        custom_workbook_view_count=custom_workbook_view_count,
        custom_sheet_view_count=custom_sheet_view_count,
        custom_view_sheet_count=len(custom_view_sheet_indices),
        hidden_row_or_column_view_count=sum(record.hidden for record in sheet_records),
        filtered_view_count=sum(record.filtered for record in sheet_records),
        print_setting_view_count=sum(record.print_settings for record in sheet_records),
        display_setting_view_count=sum(record.display_settings for record in sheet_records),
        unrecognized_custom_view_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(definition_entries)))
            if definition_entries
            else None
        ),
        unrecognized_signature=(
            _private_external_data_signature(issue_entries) if issue_entries else None
        ),
    )
    return _CustomWorkbookViewMetadata(snapshot, tuple(sorted(warnings)))


def _table_style_control_boolean(value: str | None, default: bool) -> bool | None:
    """Read one Table Style Boolean without treating malformed XML as a default."""
    return _number_format_boolean(value, default)


def _table_style_control_unsigned(value: str | None) -> int | None:
    """Read one bounded Table Style unsigned integer."""
    return _custom_workbook_view_unsigned(value)


def _table_style_control_fragment_signature(element: ElementTree.Element) -> str:
    """Keep differential-style material private while resolving ID rewrites."""
    return _private_external_data_signature(
        (("table-style-differential", repr(_xml_fragment(element, normalise_formulas=True))),)
    ) or ""


def _table_style_control_unknown_signature(
    element: ElementTree.Element,
) -> tuple[str, str, str]:
    """Fingerprint unsupported Table Style XML without serializing it publicly."""
    return (
        "unknown",
        _xml_display_name(element.tag),
        _custom_workbook_view_generic_signature(element),
    )


def _table_style_control_is_builtin(name: str) -> bool:
    """Return whether a style name is one of Excel's standard table styles."""
    return name.casefold() == "tablestylenone" or bool(
        _TABLE_STYLE_BUILT_IN_NAME.fullmatch(name)
    )


def _table_style_controls_metadata(path: Path) -> _TableStyleControlsMetadata:
    """Inspect applied Excel Table Styles directly from raw OOXML.

    Table definitions select a style through ``tableStyleInfo`` while custom
    style definitions and their differential formats live in ``styles.xml``.
    The reader sees only a flattened representation, so this preflight keeps
    the complete presentation declaration private and compares stable semantic
    signatures instead of volatile ``dxfId`` indexes.
    """
    default = TableStyleControlsSnapshot()
    warnings: set[str] = set()
    issues: dict[str, str] = {}
    definition_entries: list[tuple[str, str]] = []
    custom_style_records: list[tuple[str, tuple[object, ...]]] = []
    custom_style_definitions: dict[str, tuple[object, ...]] = {}
    differential_signatures: tuple[str, ...] = ()
    table_style_info_count = 0
    styled_table_count = 0
    custom_table_style_count = 0
    custom_table_style_element_count = 0
    custom_style_applied_table_count = 0
    table_direct_dxf_assignment_count = 0
    table_direct_dxf_table_indexes: set[int] = set()
    table_named_cell_style_assignment_count = 0
    row_striped_table_count = 0
    column_striped_table_count = 0
    emphasized_column_table_count = 0
    has_table_style_surface = False
    styles_unavailable = False

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    def compatible(element: ElementTree.Element) -> ElementTree.Element:
        return _custom_workbook_view_compatibility_element(element)

    def parse_boolean_attribute(
        element: ElementTree.Element,
        name: str,
        *,
        default_value: bool,
        context: str,
    ) -> bool:
        parsed = _table_style_control_boolean(element.get(name), default_value)
        if parsed is None:
            note_issue(f"{context}:invalid-{name}", element.get(name))
            return default_value
        return parsed

    def record_direct_table_format_attributes(
        element: ElementTree.Element,
        *,
        dxf_attributes: frozenset[str],
        context: str,
        table_identity: str,
        table_index: int,
        target: str,
    ) -> None:
        """Retain private semantic references for table-local format controls."""
        nonlocal has_table_style_surface
        nonlocal table_direct_dxf_assignment_count
        nonlocal table_named_cell_style_assignment_count

        for attribute, value in element.attrib.items():
            if (
                _xml_namespace(attribute) is not None
                and _xml_local_name(attribute)
                in (dxf_attributes | _TABLE_NAMED_CELL_STYLE_ATTRIBUTES)
            ):
                note_issue(
                    f"{context}:namespaced-presentation-attribute",
                    (attribute, value),
                )

        for attribute in sorted(dxf_attributes):
            raw_dxf_id = element.get(attribute)
            if raw_dxf_id is None:
                continue
            has_table_style_surface = True
            table_direct_dxf_assignment_count += 1
            table_direct_dxf_table_indexes.add(table_index)
            dxf_id = _table_style_control_unsigned(raw_dxf_id)
            if dxf_id is None or dxf_id >= len(differential_signatures):
                note_issue(f"{context}:unresolved-{attribute}", raw_dxf_id)
                dxf_signature = f"unresolved:{raw_dxf_id}"
            else:
                dxf_signature = differential_signatures[dxf_id]
            definition_entries.append(
                (
                    f"table-direct-dxf:{table_identity}:{target}:{attribute}",
                    repr(("tableDirectDxf", attribute, dxf_signature)),
                )
            )

        for attribute in sorted(_TABLE_NAMED_CELL_STYLE_ATTRIBUTES):
            raw_style_name = element.get(attribute)
            if raw_style_name is None:
                continue
            has_table_style_surface = True
            table_named_cell_style_assignment_count += 1
            definition_entries.append(
                (
                    f"table-named-cell-style:{table_identity}:{target}:{attribute}",
                    repr(
                        (
                            "tableNamedCellStyle",
                            attribute,
                            raw_style_name.casefold(),
                        )
                    ),
                )
            )

    try:
        with ZipFile(path) as archive:
            total_bytes = 0
            styles_root: ElementTree.Element | None = None
            try:
                styles_info = archive.getinfo("xl/styles.xml")
            except KeyError:
                styles_unavailable = True
            else:
                if styles_info.file_size > _TABLE_STYLE_MAX_STYLES_PART_BYTES:
                    styles_unavailable = True
                elif styles_info.file_size > _TABLE_STYLE_TOTAL_MAX_BYTES:
                    styles_unavailable = True
                else:
                    total_bytes += styles_info.file_size
                    try:
                        styles_root = compatible(_xml_root(archive, "xl/styles.xml"))
                    except (
                        ElementTree.ParseError,
                        KeyError,
                        OSError,
                        RuntimeError,
                        ValueError,
                    ):
                        styles_unavailable = True

            if styles_root is not None:
                if (
                    _xml_namespace(styles_root.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(styles_root.tag) != "styleSheet"
                ):
                    styles_unavailable = True
                else:
                    dxfs = styles_root.find(f"{{{_SPREADSHEETML_NS}}}dxfs")
                    if dxfs is not None:
                        differential_signatures = tuple(
                            _table_style_control_fragment_signature(dxf)
                            for dxf in dxfs
                            if (
                                _xml_namespace(dxf.tag) == _SPREADSHEETML_NS
                                and _xml_local_name(dxf.tag) == "dxf"
                            )
                        )

                    table_style_containers = [
                        child
                        for child in styles_root
                        if _xml_local_name(child.tag) == "tableStyles"
                    ]
                    if table_style_containers:
                        has_table_style_surface = True
                    if len(table_style_containers) > 1:
                        note_issue(
                            "styles:multiple-table-styles-containers",
                            len(table_style_containers),
                        )
                    for container_index, original_container in enumerate(
                        table_style_containers
                    ):
                        container_context = f"styles:table-styles:{container_index}"
                        if _xml_namespace(original_container.tag) not in {
                            _SPREADSHEETML_NS,
                            _STRICT_SPREADSHEETML_NS,
                        }:
                            note_issue(
                                f"{container_context}:unsupported-namespace",
                                original_container.tag,
                            )
                            continue
                        container = compatible(original_container)
                        unexpected_attributes = tuple(
                            sorted(
                                (_xml_display_name(attribute), value)
                                for attribute, value in container.attrib.items()
                                if _xml_local_name(attribute)
                                not in {"count", "defaultTableStyle", "defaultPivotStyle"}
                                or _xml_namespace(attribute) is not None
                            )
                        )
                        if unexpected_attributes:
                            note_issue(
                                f"{container_context}:unexpected-attributes",
                                unexpected_attributes,
                            )
                        # ``defaultTableStyle`` applies when a user creates a
                        # new table. Existing tables identify their own style
                        # with ``tableStyleInfo`` and are the review surface
                        # guarded here.
                        for style_index, style in enumerate(container):
                            style_context = f"{container_context}:style:{style_index}"
                            if (
                                _xml_namespace(style.tag) != _SPREADSHEETML_NS
                                or _xml_local_name(style.tag) != "tableStyle"
                            ):
                                note_issue(
                                    f"{style_context}:unsupported-child",
                                    _table_style_control_unknown_signature(style),
                                )
                                continue
                            table_enabled = parse_boolean_attribute(
                                style,
                                "table",
                                default_value=True,
                                context=style_context,
                            )
                            if not table_enabled:
                                # Pivot-only definitions stay within the existing
                                # PivotTable boundary rather than creating Table
                                # Style noise for ordinary worksheet tables.
                                continue
                            has_table_style_surface = True
                            style_name = style.get("name")
                            if not style_name:
                                note_issue(
                                    f"{style_context}:missing-style-name",
                                    _table_style_control_unknown_signature(style),
                                )
                                style_key = f"invalid:{style_index}"
                            else:
                                style_key = style_name.casefold()
                            unexpected_style_attributes = tuple(
                                sorted(
                                    (_xml_display_name(attribute), value)
                                    for attribute, value in style.attrib.items()
                                    if not (
                                        (
                                            _xml_namespace(attribute) is None
                                            and _xml_local_name(attribute)
                                            in {"name", "pivot", "table", "count"}
                                        )
                                        # Excel emits this revision identifier for
                                        # custom styles. It is package provenance,
                                        # not a presentation declaration, and may
                                        # change on a no-op writer round trip.
                                        or (
                                            _xml_namespace(attribute)
                                            == _OFFICE_2016_REVISION9_NS
                                            and _xml_local_name(attribute) == "uid"
                                        )
                                    )
                                )
                            )
                            if unexpected_style_attributes:
                                note_issue(
                                    f"{style_context}:unexpected-attributes",
                                    unexpected_style_attributes,
                                )
                            if style.text and style.text.strip():
                                note_issue(
                                    f"{style_context}:unexpected-text",
                                    _table_style_control_unknown_signature(style),
                                )
                            element_records: list[tuple[object, ...]] = []
                            seen_element_types: set[str] = set()
                            for element_index, element in enumerate(style):
                                element_context = f"{style_context}:element:{element_index}"
                                if (
                                    _xml_namespace(element.tag) != _SPREADSHEETML_NS
                                    or _xml_local_name(element.tag)
                                    != "tableStyleElement"
                                ):
                                    note_issue(
                                        f"{element_context}:unsupported-child",
                                        _table_style_control_unknown_signature(element),
                                    )
                                    continue
                                element_type = element.get("type")
                                if element_type not in _TABLE_STYLE_ELEMENT_TYPES:
                                    note_issue(
                                        f"{element_context}:invalid-type",
                                        element_type,
                                    )
                                    continue
                                if element_type not in _TABLE_STYLE_TABLE_ELEMENT_TYPES:
                                    # This element only affects a PivotTable view,
                                    # so retain no Table Style signature for it.
                                    continue
                                if element_type in seen_element_types:
                                    note_issue(
                                        f"{style_context}:duplicate-element-type",
                                        element_type,
                                    )
                                seen_element_types.add(element_type)
                                size = _table_style_control_unsigned(element.get("size"))
                                if size is None:
                                    if element.get("size") is not None:
                                        note_issue(
                                            f"{element_context}:invalid-size",
                                            element.get("size"),
                                        )
                                    size = 1
                                dxf_signature: str | None = None
                                if (raw_dxf_id := element.get("dxfId")) is not None:
                                    dxf_id = _table_style_control_unsigned(raw_dxf_id)
                                    if (
                                        dxf_id is None
                                        or dxf_id >= len(differential_signatures)
                                    ):
                                        note_issue(
                                            f"{element_context}:unresolved-dxf",
                                            raw_dxf_id,
                                        )
                                        dxf_signature = f"unresolved:{raw_dxf_id}"
                                    else:
                                        dxf_signature = differential_signatures[dxf_id]
                                unexpected_element_attributes = tuple(
                                    sorted(
                                        (_xml_display_name(attribute), value)
                                        for attribute, value in element.attrib.items()
                                        if _xml_local_name(attribute)
                                        not in {"type", "size", "dxfId"}
                                        or _xml_namespace(attribute) is not None
                                    )
                                )
                                if unexpected_element_attributes:
                                    note_issue(
                                        f"{element_context}:unexpected-attributes",
                                        unexpected_element_attributes,
                                    )
                                if list(element) or (element.text and element.text.strip()):
                                    note_issue(
                                        f"{element_context}:unexpected-content",
                                        _table_style_control_unknown_signature(element),
                                    )
                                element_records.append(
                                    (element_type, str(size), dxf_signature)
                                )
                            custom_table_style_count += 1
                            custom_table_style_element_count += len(element_records)
                            custom_style_records.append(
                                (
                                    style_key,
                                    (
                                        "customTableStyle",
                                        style_key,
                                        tuple(sorted(element_records)),
                                    ),
                                )
                            )

            records_by_name: dict[str, list[tuple[object, ...]]] = defaultdict(list)
            for style_key, signature in custom_style_records:
                records_by_name[style_key].append(signature)
            for style_key, signatures in records_by_name.items():
                if len(signatures) == 1:
                    custom_style_definitions[style_key] = signatures[0]
                else:
                    note_issue(
                        "styles:duplicate-custom-table-style-name",
                        (style_key, tuple(signatures)),
                    )
            for index, (style_key, signature) in enumerate(
                sorted(custom_style_records, key=lambda item: (item[0], repr(item[1])))
            ):
                definition_entries.append(
                    (f"custom-table-style:{style_key}:{index}", repr(signature))
                )

            table_members_raw = [
                member
                for member in archive.namelist()
                if (
                    member.startswith("xl/tables/")
                    and member.endswith(".xml")
                    and "/_rels/" not in member
                )
            ]
            table_members = sorted(set(table_members_raw), key=str.casefold)
            if len(table_members_raw) != len(table_members):
                has_table_style_surface = True
                note_issue(
                    "tables:duplicate-package-members",
                    tuple(sorted(table_members_raw)),
                )
            if len(table_members) > _TABLE_STYLE_TOTAL_MAX_COUNT:
                has_table_style_surface = True
                note_issue(
                    "tables:part-count-limit",
                    len(table_members),
                )
            for member_index, member in enumerate(table_members):
                if member_index >= _TABLE_STYLE_TOTAL_MAX_COUNT:
                    break
                table_context = f"table-part:{member_index}"
                try:
                    info = archive.getinfo(member)
                except KeyError:
                    has_table_style_surface = True
                    note_issue(f"{table_context}:missing-part", member)
                    continue
                if info.file_size > _TABLE_STYLE_MAX_TABLE_PART_BYTES:
                    has_table_style_surface = True
                    note_issue(f"{table_context}:oversized-part", info.file_size)
                    continue
                if total_bytes + info.file_size > _TABLE_STYLE_TOTAL_MAX_BYTES:
                    has_table_style_surface = True
                    note_issue(f"{table_context}:total-size-limit", info.file_size)
                    continue
                total_bytes += info.file_size
                try:
                    table = compatible(_xml_root(archive, member))
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    has_table_style_surface = True
                    note_issue(f"{table_context}:unreadable-part", type(error).__name__)
                    continue
                if (
                    _xml_namespace(table.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(table.tag) != "table"
                ):
                    has_table_style_surface = True
                    note_issue(f"{table_context}:unsupported-root", table.tag)
                    continue
                style_infos = [
                    child
                    for child in table
                    if _xml_local_name(child.tag) == "tableStyleInfo"
                ]
                table_name = table.get("displayName") or table.get("name")
                if table_name:
                    table_identity = table_name.casefold()
                else:
                    # The package-part position is stable enough for this raw
                    # inventory and avoids putting mutable raw table XML into
                    # the identity hash when a malformed table lacks a name.
                    table_identity = f"anonymous:{member_index}"

                direct_dxf_before = table_direct_dxf_assignment_count
                named_style_before = table_named_cell_style_assignment_count
                record_direct_table_format_attributes(
                    table,
                    dxf_attributes=_TABLE_DIRECT_DXF_TABLE_ATTRIBUTES,
                    context=f"{table_context}:table",
                    table_identity=table_identity,
                    table_index=member_index,
                    target="table",
                )
                column_index = 0
                for table_columns in table:
                    if (
                        _xml_namespace(table_columns.tag) != _SPREADSHEETML_NS
                        or _xml_local_name(table_columns.tag) != "tableColumns"
                    ):
                        continue
                    for column in table_columns:
                        if (
                            _xml_namespace(column.tag) != _SPREADSHEETML_NS
                            or _xml_local_name(column.tag) != "tableColumn"
                        ):
                            continue
                        record_direct_table_format_attributes(
                            column,
                            dxf_attributes=_TABLE_DIRECT_DXF_COLUMN_ATTRIBUTES,
                            context=f"{table_context}:column:{column_index}",
                            table_identity=table_identity,
                            table_index=member_index,
                            target=f"column:{column_index}",
                        )
                        column_index += 1

                if (
                    table_name is None
                    and (
                        style_infos
                        or table_direct_dxf_assignment_count != direct_dxf_before
                        or table_named_cell_style_assignment_count != named_style_before
                    )
                ):
                    note_issue(
                        f"{table_context}:missing-table-identity",
                        _table_style_control_unknown_signature(table),
                    )

                if not style_infos:
                    continue
                has_table_style_surface = True
                if len(style_infos) > 1:
                    note_issue(
                        f"{table_context}:multiple-style-info-containers",
                        len(style_infos),
                    )
                for style_index, original_style_info in enumerate(style_infos):
                    style_context = f"{table_context}:style-info:{style_index}"
                    if _xml_namespace(original_style_info.tag) not in {
                        _SPREADSHEETML_NS,
                        _STRICT_SPREADSHEETML_NS,
                    }:
                        note_issue(
                            f"{style_context}:unsupported-namespace",
                            original_style_info.tag,
                        )
                        continue
                    style_info = compatible(original_style_info)
                    table_style_info_count += 1
                    unexpected_attributes = tuple(
                        sorted(
                            (_xml_display_name(attribute), value)
                            for attribute, value in style_info.attrib.items()
                            if _xml_local_name(attribute)
                            not in {
                                "name",
                                "showFirstColumn",
                                "showLastColumn",
                                "showRowStripes",
                                "showColumnStripes",
                            }
                            or _xml_namespace(attribute) is not None
                        )
                    )
                    if unexpected_attributes:
                        note_issue(
                            f"{style_context}:unexpected-attributes",
                            unexpected_attributes,
                        )
                    if list(style_info) or (
                        style_info.text and style_info.text.strip()
                    ):
                        note_issue(
                            f"{style_context}:unexpected-content",
                            _table_style_control_unknown_signature(style_info),
                        )
                    raw_name = style_info.get("name")
                    style_key = (
                        raw_name.casefold() if raw_name not in {None, ""} else None
                    )
                    if style_key is not None:
                        styled_table_count += 1
                        if style_key in custom_style_definitions:
                            custom_style_applied_table_count += 1
                        elif not _table_style_control_is_builtin(raw_name or ""):
                            note_issue(
                                f"{style_context}:unresolved-style-name",
                                raw_name,
                            )
                    show_first_column = parse_boolean_attribute(
                        style_info,
                        "showFirstColumn",
                        default_value=False,
                        context=style_context,
                    )
                    show_last_column = parse_boolean_attribute(
                        style_info,
                        "showLastColumn",
                        default_value=False,
                        context=style_context,
                    )
                    show_row_stripes = parse_boolean_attribute(
                        style_info,
                        "showRowStripes",
                        default_value=False,
                        context=style_context,
                    )
                    show_column_stripes = parse_boolean_attribute(
                        style_info,
                        "showColumnStripes",
                        default_value=False,
                        context=style_context,
                    )
                    row_striped_table_count += int(show_row_stripes)
                    column_striped_table_count += int(show_column_stripes)
                    emphasized_column_table_count += int(
                        show_first_column or show_last_column
                    )
                    signature = (
                        "tableStyleInfo",
                        style_key,
                        show_first_column,
                        show_last_column,
                        show_row_stripes,
                        show_column_stripes,
                    )
                    definition_entries.append(
                        (
                            f"table-style-binding:{table_identity}:{style_index}",
                            repr(signature),
                        )
                    )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _TableStyleControlsMetadata(
            default,
            (
                "FormulaFence could not inspect Excel Table Style OOXML "
                f"({type(error).__name__}); table presentation controls were not "
                "compared.",
            ),
        )

    if has_table_style_surface and styles_unavailable:
        note_issue("styles:unavailable", "styles.xml")
    if issues:
        warnings.add(
            "FormulaFence found malformed, unsupported, unresolved, or bounded Excel "
            "Table Style metadata; affected table presentation controls have a coverage "
            "gap."
        )
    issue_entries = tuple(
        (f"table-style-issue:{context}", detail)
        for context, detail in sorted(issues.items())
    )
    snapshot = TableStyleControlsSnapshot(
        table_style_info_count=table_style_info_count,
        styled_table_count=styled_table_count,
        custom_table_style_count=custom_table_style_count,
        custom_table_style_element_count=custom_table_style_element_count,
        custom_style_applied_table_count=custom_style_applied_table_count,
        table_direct_dxf_assignment_count=table_direct_dxf_assignment_count,
        table_direct_dxf_table_count=len(table_direct_dxf_table_indexes),
        table_named_cell_style_assignment_count=(
            table_named_cell_style_assignment_count
        ),
        row_striped_table_count=row_striped_table_count,
        column_striped_table_count=column_striped_table_count,
        emphasized_column_table_count=emphasized_column_table_count,
        unrecognized_table_style_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(definition_entries)))
            if definition_entries
            else None
        ),
        unrecognized_signature=(
            _private_external_data_signature(issue_entries) if issue_entries else None
        ),
    )
    return _TableStyleControlsMetadata(snapshot, tuple(sorted(warnings)))


def _shared_workbook_revision_xml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[object, ...]],
    *,
    normalise_header_controls: bool = False,
) -> tuple[object, ...]:
    """Canonicalize private revision XML while resolving relationship-ID noise."""

    def normalise_value(attribute: str, value: str) -> str:
        if not normalise_header_controls:
            return value
        name = _xml_local_name(attribute)
        if name in _SHARED_WORKBOOK_REVISION_HEADER_BOOLEAN_ATTRIBUTES:
            parsed = _number_format_boolean(value, False)
            if parsed is not None:
                return "true" if parsed else "false"
        if name in (
            _SHARED_WORKBOOK_REVISION_HEADER_UNSIGNED_ATTRIBUTES
            | frozenset({"maxRId", "maxSheetId", "minRId"})
        ):
            if (parsed := _custom_workbook_view_unsigned(value)) is not None:
                return str(parsed)
        if name in _SHARED_WORKBOOK_REVISION_HEADER_SIGNED_ATTRIBUTES:
            if (parsed := _custom_workbook_view_signed(value)) is not None:
                return str(parsed)
        return value

    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute in _SHARED_WORKBOOK_REVISION_RELATIONSHIP_ATTRIBUTES:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            # Strict and transitional SpreadsheetML use distinct namespace
            # spellings for the same relationship identifier attribute.
            attributes.append(("relationship-id", repr(resolved)))
        else:
            attributes.append(
                (_xml_display_name(attribute), normalise_value(attribute, value))
            )
    children = tuple(
        _shared_workbook_revision_xml_fragment(
            child,
            relationship_semantics,
            normalise_header_controls=normalise_header_controls,
        )
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    tail = element.tail
    if tail is not None and not tail.strip():
        tail = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
        tail,
    )


def _shared_workbook_revision_relationship_type(value: str) -> str:
    """Canonicalize Strict and transitional Office relationship type spelling."""
    normalized = value.casefold()
    strict_prefix = f"{_STRICT_DOCUMENT_RELATIONSHIP_NS}/".casefold()
    if normalized.startswith(strict_prefix):
        return (
            f"{_DOCUMENT_RELATIONSHIP_NS}/".casefold()
            + normalized[len(strict_prefix) :]
        )
    return normalized


def _shared_workbook_revision_relationship_semantics(
    relationships: tuple[_PackageRelationship, ...],
    issues: dict[str, str],
    *,
    context: str,
) -> dict[str, tuple[object, ...]]:
    """Resolve revision relationship IDs to stable private semantics."""
    by_id: dict[str, list[tuple[object, ...]]] = defaultdict(list)
    for relationship in relationships:
        semantic = (
            _shared_workbook_revision_relationship_type(
                relationship.relationship_type
            ),
            relationship.target_mode.casefold(),
            (
                relationship.target
                if relationship.target_mode.casefold() == "internal"
                else relationship.raw_target
            ),
        )
        if relationship.relationship_id:
            by_id[relationship.relationship_id].append(semantic)
        else:
            issues.setdefault(
                f"{context}:relationship-without-id",
                repr(semantic),
            )
    resolved: dict[str, tuple[object, ...]] = {}
    for relationship_id, values in by_id.items():
        distinct = sorted(set(values), key=repr)
        if len(values) > 1:
            issues.setdefault(
                f"{context}:duplicate-relationship-id:{relationship_id}",
                repr(tuple(distinct)),
            )
        resolved[relationship_id] = distinct[0]
    return resolved


def _shared_workbook_revision_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info: ZipInfo,
    budget: _SharedWorkbookRevisionBudget,
) -> str | None:
    """Stream revision XML before its complete private tree is canonicalized."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _SHARED_WORKBOOK_REVISION_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the existing materializing parser diagnostic for malformed
        # or unreadable XML. Only a successfully streamed overage can bypass
        # that parser safely.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    signature_entries = [
        (
            "xml-structure-budget-exhausted",
            repr((member, info.file_size, info.compress_size, info.CRC)),
        )
    ]
    if (payload_signature := _private_archive_member_payload_signature(archive, info)) is not None:
        signature_entries.append(("payload", payload_signature))
    return _private_external_data_signature(
        tuple(signature_entries)
    )


def _shared_workbook_revision_metadata(path: Path) -> _SharedWorkbookRevisionMetadata:
    """Inspect legacy shared-workbook revision history before readers omit it.

    Revision headers and logs retain a private audit trail that can include old
    values, coordinates, authors, timestamps, comments, formatting, and
    conflict-resolution records. This scanner compares complete bounded raw
    declarations without exposing any record material in a profile or report.
    """
    warnings: set[str] = set()
    issues: dict[str, str] = {}
    header_entries: list[tuple[str, str]] = []
    log_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    revision_header_part_count = 0
    revision_header_count = 0
    revision_log_part_count = 0
    revision_log_entry_count = 0
    shared_workbook_enabled_count = 0
    track_revisions_enabled_count = 0
    revision_history_enabled_count = 0
    keep_change_history_enabled_count = 0
    revision_history_protected_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    def read_root(
        archive: ZipFile,
        members: set[str],
        member: str,
        *,
        context: str,
        budget: _SharedWorkbookRevisionBudget,
    ) -> ElementTree.Element | None:
        if member not in members:
            note_issue(f"{context}:missing-part", member)
            return None
        try:
            info = archive.getinfo(member)
        except KeyError:
            note_issue(f"{context}:missing-part", member)
            return None
        if info.file_size > _SHARED_WORKBOOK_REVISION_MAX_PART_BYTES:
            note_issue(f"{context}:oversized-part", info.file_size)
            return None
        if budget.remaining_parts <= 0:
            note_issue(f"{context}:part-count-limit", member)
            return None
        if budget.remaining_bytes < info.file_size:
            note_issue(f"{context}:total-size-limit", info.file_size)
            return None
        budget.remaining_parts -= 1
        budget.remaining_bytes -= info.file_size
        structure_fallback_signature = (
            _shared_workbook_revision_xml_structure_budget_fallback_signature(
                archive,
                member,
                info,
                budget,
            )
        )
        if structure_fallback_signature is not None:
            warnings.add(
                "FormulaFence did not fully read a legacy shared-workbook revision "
                "XML part whose XML structure exceeds the safety budget; affected "
                "revision history has a coverage gap."
            )
            note_issue(
                f"{context}:xml-structure-budget-exhausted",
                structure_fallback_signature,
            )
            return None
        try:
            return _xml_root_from_payload(archive.read(member))
        except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
            note_issue(f"{context}:unreadable-part", type(error).__name__)
            return None

    def relationships_for(
        archive: ZipFile,
        members: set[str],
        source_member: str,
        *,
        context: str,
        budget: _SharedWorkbookRevisionBudget,
    ) -> tuple[_PackageRelationship, ...]:
        relationship_member = _relationship_part_path(source_member)
        if relationship_member not in members:
            return ()
        root = read_root(
            archive,
            members,
            relationship_member,
            context=f"{context}:relationships",
            budget=budget,
        )
        if root is None:
            return ()
        if (
            _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
            or _xml_local_name(root.tag) != "Relationships"
        ):
            note_issue(f"{context}:relationships:unexpected-root", root.tag)
            return ()
        relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
        parsed: list[_PackageRelationship] = []
        for child_index, relationship in enumerate(root):
            if relationship.tag != relationship_tag:
                note_issue(
                    f"{context}:relationships:unsupported-child:{child_index}",
                    _shared_workbook_revision_xml_fragment(relationship, {}),
                )
                continue
            target_mode = relationship.get("TargetMode", "Internal")
            raw_target = relationship.get("Target")
            parsed.append(
                _PackageRelationship(
                    relationship_id=relationship.get("Id"),
                    relationship_type=relationship.get("Type", ""),
                    target=(
                        _normalise_part_target(source_member, raw_target)
                        if raw_target is not None
                        and target_mode.casefold() == "internal"
                        else None
                    ),
                    target_mode=target_mode,
                    raw_target=raw_target,
                )
            )
        return tuple(parsed)

    def relationship_entry(
        context: str,
        relationship: _PackageRelationship,
    ) -> tuple[str, str]:
        return (
            context,
            repr(
                (
                    _shared_workbook_revision_relationship_type(
                        relationship.relationship_type
                    ),
                    relationship.target_mode.casefold(),
                    (
                        relationship.target
                        if relationship.target_mode.casefold() == "internal"
                        else relationship.raw_target
                    ),
                )
            ),
        )

    try:
        with ZipFile(path) as archive:
            members = set(archive.namelist())
            member_counts: dict[str, int] = defaultdict(int)
            for info in archive.infolist():
                member_counts[info.filename] += 1
            revision_members = {
                member
                for member in members
                if member.casefold().startswith("xl/revisions/")
            }
            budget = _SharedWorkbookRevisionBudget()
            if len(revision_members) > _SHARED_WORKBOOK_REVISION_TOTAL_MAX_COUNT:
                note_issue("revisions:part-count-limit", len(revision_members))
            for member in sorted(revision_members):
                if member_counts[member] > 1:
                    note_issue(
                        f"revisions:duplicate-package-member:{member}",
                        member_counts[member],
                    )

            try:
                workbook_relationships = _package_relationships(archive, "xl/workbook.xml")
            except (
                ElementTree.ParseError,
                KeyError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                note_issue("workbook:relationship-scan-failure", type(error).__name__)
                workbook_relationships = ()

            declared_headers: set[str] = set()
            revision_header_relationship_count = 0
            for relationship in workbook_relationships:
                if (
                    relationship.relationship_type.casefold()
                    not in _SHARED_WORKBOOK_REVISION_HEADERS_RELATIONSHIPS
                ):
                    continue
                revision_header_relationship_count += 1
                relationship_entries.append(
                    relationship_entry("workbook:revision-header-relationship", relationship)
                )
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                ):
                    note_issue(
                        "workbook:unsafe-revision-header-relationship",
                        relationship_entry("", relationship)[1],
                    )
                    continue
                declared_headers.add(relationship.target)
                if relationship.target not in members:
                    note_issue(
                        "workbook:missing-revision-header-target",
                        relationship.target,
                    )
            if revision_header_relationship_count != len(declared_headers):
                note_issue(
                    "workbook:duplicate-revision-header-target",
                    tuple(sorted(declared_headers)),
                )

            discovered_headers = {
                member
                for member in revision_members
                if _SHARED_WORKBOOK_REVISION_HEADERS_MEMBER_PATTERN.fullmatch(member)
            } | declared_headers
            header_members = sorted(member for member in discovered_headers if member in members)
            revision_header_part_count = len(header_members)
            for member in header_members:
                if member not in declared_headers:
                    note_issue("revisions:unbound-revision-header-part", member)

            declared_logs: set[str] = set()
            inspected_relationship_members: set[str] = set()
            for header_index, member in enumerate(header_members):
                context = f"revision-header:{header_index}"
                root = read_root(
                    archive,
                    members,
                    member,
                    context=context,
                    budget=budget,
                )
                if root is None:
                    header_entries.append((f"{context}:unreadable", member))
                    continue
                root = _custom_workbook_view_compatibility_element(root)
                if (
                    _xml_namespace(root.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(root.tag) != "headers"
                ):
                    note_issue(f"{context}:unexpected-root", root.tag)
                if root.text and root.text.strip():
                    note_issue(f"{context}:unexpected-text", root.text)
                for attribute_index, (attribute, value) in enumerate(
                    root.attrib.items()
                ):
                    if (
                        _xml_namespace(attribute) is None
                        and _xml_local_name(attribute)
                        in _SHARED_WORKBOOK_REVISION_HEADERS_ATTRIBUTES
                    ):
                        continue
                    note_issue(
                        f"{context}:unexpected-attribute:{attribute_index}",
                        (_xml_display_name(attribute), value),
                    )

                relationships = relationships_for(
                    archive,
                    members,
                    member,
                    context=context,
                    budget=budget,
                )
                relationship_member = _relationship_part_path(member)
                if relationship_member in members:
                    inspected_relationship_members.add(relationship_member)
                relationship_semantics = _shared_workbook_revision_relationship_semantics(
                    relationships,
                    issues,
                    context=context,
                )
                revision_log_relationships = []
                for relationship in relationships:
                    relationship_entries.append(
                        relationship_entry(f"{context}:relationship", relationship)
                    )
                    if (
                        relationship.relationship_type.casefold()
                        not in _SHARED_WORKBOOK_REVISION_LOG_RELATIONSHIPS
                    ):
                        note_issue(
                            f"{context}:unsupported-relationship",
                            relationship_entry("", relationship)[1],
                        )
                        continue
                    revision_log_relationships.append(relationship)
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        note_issue(
                            f"{context}:unsafe-revision-log-relationship",
                            relationship_entry("", relationship)[1],
                        )
                        continue
                    declared_logs.add(relationship.target)
                    if relationship.target not in members:
                        note_issue(
                            f"{context}:missing-revision-log-target",
                            relationship.target,
                        )

                boolean_controls: dict[str, bool] = {}
                for attribute in _SHARED_WORKBOOK_REVISION_HEADER_BOOLEAN_ATTRIBUTES:
                    parsed = _number_format_boolean(root.get(attribute), False)
                    if parsed is None:
                        note_issue(f"{context}:invalid-{attribute}", root.get(attribute))
                        parsed = False
                    boolean_controls[attribute] = parsed
                shared_workbook_enabled_count += int(boolean_controls["shared"])
                track_revisions_enabled_count += int(boolean_controls["trackRevisions"])
                revision_history_enabled_count += int(boolean_controls["history"])
                keep_change_history_enabled_count += int(
                    boolean_controls["keepChangeHistory"]
                )
                revision_history_protected_count += int(boolean_controls["protected"])
                for attribute in _SHARED_WORKBOOK_REVISION_HEADER_UNSIGNED_ATTRIBUTES:
                    raw_value = root.get(attribute)
                    if raw_value is not None and _custom_workbook_view_unsigned(raw_value) is None:
                        note_issue(f"{context}:invalid-{attribute}", raw_value)
                raw_version = root.get("version")
                if raw_version is not None and _custom_workbook_view_signed(raw_version) is None:
                    note_issue(f"{context}:invalid-version", raw_version)

                for child_index, child in enumerate(root):
                    if (
                        _xml_namespace(child.tag) != _SPREADSHEETML_NS
                        or _xml_local_name(child.tag)
                        not in _SHARED_WORKBOOK_REVISION_HEADER_CHILDREN
                    ):
                        note_issue(
                            f"{context}:unsupported-child:{child_index}",
                            _shared_workbook_revision_xml_fragment(
                                child,
                                relationship_semantics,
                                normalise_header_controls=True,
                            ),
                        )
                        continue
                    revision_header_count += 1
                    if child.text and child.text.strip():
                        note_issue(
                            f"{context}:header:{child_index}:unexpected-text",
                            child.text,
                        )
                    for attribute_index, (attribute, value) in enumerate(
                        child.attrib.items()
                    ):
                        if attribute in _SHARED_WORKBOOK_REVISION_RELATIONSHIP_ATTRIBUTES:
                            continue
                        if (
                            _xml_namespace(attribute) is None
                            and _xml_local_name(attribute)
                            in _SHARED_WORKBOOK_REVISION_HEADER_ATTRIBUTES
                        ):
                            continue
                        note_issue(
                            (
                                f"{context}:header:{child_index}:"
                                f"unexpected-attribute:{attribute_index}"
                            ),
                            (_xml_display_name(attribute), value),
                        )
                    for content_index, content in enumerate(child):
                        if (
                            _xml_namespace(content.tag) != _SPREADSHEETML_NS
                            or _xml_local_name(content.tag)
                            not in _SHARED_WORKBOOK_REVISION_HEADER_CONTENT_CHILDREN
                        ):
                            note_issue(
                                (
                                    f"{context}:header:{child_index}:"
                                    f"unsupported-child:{content_index}"
                                ),
                                _shared_workbook_revision_xml_fragment(
                                    content,
                                    relationship_semantics,
                                    normalise_header_controls=True,
                                ),
                            )
                    for attribute in ("maxRId", "maxSheetId", "minRId"):
                        raw_value = child.get(attribute)
                        if (
                            raw_value is not None
                            and _custom_workbook_view_unsigned(raw_value) is None
                        ):
                            note_issue(
                                (
                                    f"{context}:header:{child_index}:"
                                    f"invalid-{attribute}"
                                ),
                                raw_value,
                            )
                    relationship_id = next(
                        (
                            child.get(attribute)
                            for attribute in _SHARED_WORKBOOK_REVISION_RELATIONSHIP_ATTRIBUTES
                            if child.get(attribute) is not None
                        ),
                        None,
                    )
                    if (
                        relationship_id is not None
                        and relationship_id not in relationship_semantics
                    ):
                        note_issue(
                            f"{context}:header-missing-revision-log-relationship",
                            relationship_id,
                        )
                header_entries.append(
                    (
                        f"revision-header-part:{header_index}",
                        repr(
                            _shared_workbook_revision_xml_fragment(
                                root,
                                relationship_semantics,
                                normalise_header_controls=True,
                            )
                        ),
                    )
                )
                local_log_targets = {
                    relationship.target
                    for relationship in revision_log_relationships
                    if relationship.target is not None
                    and relationship.target_mode.casefold() == "internal"
                }
                if len(revision_log_relationships) != len(local_log_targets):
                    # The aggregate set is checked below; this local branch keeps
                    # duplicate log targets visible even when other headers exist.
                    note_issue(
                        f"{context}:duplicate-revision-log-target",
                        tuple(
                            sorted(
                                relationship.target
                                for relationship in revision_log_relationships
                                if relationship.target is not None
                            )
                        ),
                    )

            discovered_logs = {
                member
                for member in revision_members
                if _SHARED_WORKBOOK_REVISION_LOG_MEMBER_PATTERN.fullmatch(member)
            } | declared_logs
            log_members = sorted(member for member in discovered_logs if member in members)
            revision_log_part_count = len(log_members)
            for member in log_members:
                if member not in declared_logs:
                    note_issue("revisions:unbound-revision-log-part", member)
            for member in sorted(revision_members):
                if member.endswith(".rels"):
                    continue
                if member not in set(header_members) | set(log_members):
                    note_issue("revisions:unsupported-part", member)

            for log_index, member in enumerate(log_members):
                context = f"revision-log:{log_index}"
                root = read_root(
                    archive,
                    members,
                    member,
                    context=context,
                    budget=budget,
                )
                if root is None:
                    log_entries.append((f"{context}:unreadable", member))
                    continue
                root = _custom_workbook_view_compatibility_element(root)
                if (
                    _xml_namespace(root.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(root.tag) != "revisions"
                ):
                    note_issue(f"{context}:unexpected-root", root.tag)
                if root.text and root.text.strip():
                    note_issue(f"{context}:unexpected-text", root.text)
                for attribute_index, (attribute, value) in enumerate(
                    root.attrib.items()
                ):
                    note_issue(
                        f"{context}:unexpected-attribute:{attribute_index}",
                        (_xml_display_name(attribute), value),
                    )
                relationships = relationships_for(
                    archive,
                    members,
                    member,
                    context=context,
                    budget=budget,
                )
                relationship_member = _relationship_part_path(member)
                if relationship_member in members:
                    inspected_relationship_members.add(relationship_member)
                relationship_semantics = _shared_workbook_revision_relationship_semantics(
                    relationships,
                    issues,
                    context=context,
                )
                for relationship in relationships:
                    relationship_entries.append(
                        relationship_entry(f"{context}:relationship", relationship)
                    )
                    note_issue(
                        f"{context}:unsupported-relationship",
                        relationship_entry("", relationship)[1],
                    )
                for child_index, child in enumerate(root):
                    if (
                        _xml_namespace(child.tag) != _SPREADSHEETML_NS
                        or _xml_local_name(child.tag)
                        not in _SHARED_WORKBOOK_REVISION_LOG_CHILDREN
                    ):
                        note_issue(
                            f"{context}:unsupported-child:{child_index}",
                            _shared_workbook_revision_xml_fragment(
                                child,
                                relationship_semantics,
                            ),
                        )
                        continue
                    revision_log_entry_count += 1
                log_entries.append(
                    (
                        f"revision-log-part:{log_index}",
                        repr(
                            _shared_workbook_revision_xml_fragment(
                                root,
                                relationship_semantics,
                            )
                        ),
                    )
                )

            for member in sorted(revision_members):
                if member.endswith(".rels") and member not in inspected_relationship_members:
                    note_issue("revisions:unbound-relationship-part", member)
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _SharedWorkbookRevisionMetadata(
            SharedWorkbookRevisionSnapshot(
                unrecognized_shared_workbook_revision_count=1,
                unrecognized_signature=_private_external_data_signature(
                    (("shared-workbook-revision-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect legacy shared-workbook revision OOXML "
                f"({type(error).__name__}); revision history was not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed, unsupported, unresolved, or bounded legacy "
            "shared-workbook revision metadata; affected revision history has a coverage gap."
        )
    issue_entries = tuple(
        (f"shared-workbook-revision-issue:{context}", detail)
        for context, detail in sorted(issues.items())
    )
    snapshot = SharedWorkbookRevisionSnapshot(
        revision_header_part_count=revision_header_part_count,
        revision_header_count=revision_header_count,
        revision_log_part_count=revision_log_part_count,
        revision_log_entry_count=revision_log_entry_count,
        shared_workbook_enabled_count=shared_workbook_enabled_count,
        track_revisions_enabled_count=track_revisions_enabled_count,
        revision_history_enabled_count=revision_history_enabled_count,
        keep_change_history_enabled_count=keep_change_history_enabled_count,
        revision_history_protected_count=revision_history_protected_count,
        unrecognized_shared_workbook_revision_count=len(issues),
        header_signature=(
            _private_external_data_signature(tuple(header_entries))
            if header_entries
            else None
        ),
        log_signature=(
            _private_external_data_signature(tuple(log_entries)) if log_entries else None
        ),
        relationship_signature=(
            _private_external_data_signature(tuple(sorted(relationship_entries)))
            if relationship_entries
            else None
        ),
        unrecognized_signature=(
            _private_external_data_signature(issue_entries) if issue_entries else None
        ),
    )
    return _SharedWorkbookRevisionMetadata(snapshot, tuple(sorted(warnings)))


_NUMBER_FORMAT_BUILT_IN_MAXIMUM = 163
_NUMBER_FORMAT_UNSIGNED_INT_MAXIMUM = 4_294_967_295
_NUMBER_FORMAT_COLUMN_UPDATE_BUDGET = 16_777_216
_NUMBER_FORMAT_MAX_CODE_LENGTH = 255


@dataclass(frozen=True)
class _NumberFormatStyle:
    """One effective number format retained only for private comparison."""

    category: str
    value: str


_GENERAL_NUMBER_FORMAT = _NumberFormatStyle("built-in", "0")


def _number_format_unrecognized(*parts: object) -> _NumberFormatStyle:
    """Fingerprint unsupported format material without retaining it in output models."""
    payload = repr(parts).encode("utf-8", errors="surrogatepass")
    return _NumberFormatStyle("unrecognized", hashlib.sha256(payload).hexdigest())


def _number_format_unsigned_int(value: str | None) -> int | None:
    """Read one bounded XML unsigned integer with schema whitespace normalized."""
    if value is None:
        return None
    candidate = value.strip()
    if candidate.isascii() and candidate.isdecimal():
        # Avoid an unbounded ``int()`` conversion on malformed XML while still
        # treating schema-valid leading zeroes as the same unsigned integer.
        significant_digits = candidate.lstrip("0") or "0"
        if len(significant_digits) > len(str(_NUMBER_FORMAT_UNSIGNED_INT_MAXIMUM)):
            return None
        parsed = int(significant_digits)
        if parsed <= _NUMBER_FORMAT_UNSIGNED_INT_MAXIMUM:
            return parsed
    return None


def _number_format_boolean(value: str | None, default: bool) -> bool | None:
    """Read a schema Boolean while distinguishing malformed material from defaults."""
    if value is None:
        return default
    lowered = value.strip().casefold()
    if lowered in {"1", "true"}:
        return True
    if lowered in {"0", "false"}:
        return False
    return None


def _number_format_column_state_signature(
    states: list[_NumberFormatStyle],
    default: _NumberFormatStyle,
) -> tuple[tuple[int, int, str, str], ...]:
    """Compress effective column defaults so equivalent range splitting stays quiet."""
    segments: list[tuple[int, int, str, str]] = []
    start: int | None = None
    previous: _NumberFormatStyle | None = None
    for column in range(1, MAX_EXCEL_COLUMN + 1):
        current = states[column]
        if current == default:
            if start is not None and previous is not None:
                segments.append((start, column - 1, previous.category, previous.value))
            start = None
            previous = None
            continue
        if start is None:
            start = column
            previous = current
            continue
        if current != previous:
            segments.append((start, column - 1, previous.category, previous.value))
            start = column
            previous = current
    if start is not None and previous is not None:
        segments.append((start, MAX_EXCEL_COLUMN, previous.category, previous.value))
    return tuple(segments)


def _number_format_metadata(path: Path) -> _NumberFormatMetadata:
    """Inspect effective cell, row, and column number formats from raw OOXML.

    Number formats can hide or materially reinterpret an unchanged stored value.
    The scanner resolves reusable style records, custom-ID remapping, inheritance,
    and ``applyNumberFormat`` before keeping a private signature. Public output
    contains counts only: codes, style IDs, and report locations never leave the
    local comparison process.
    """
    warnings: set[str] = set()
    default_snapshot = NumberFormatSnapshot()
    entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    default_format_override_count = 0
    cell_format_assignment_count = 0
    row_format_assignment_count = 0
    column_format_assignment_count = 0
    built_in_format_assignment_count = 0
    custom_format_assignment_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    def count_style(style: _NumberFormatStyle, amount: int = 1) -> None:
        nonlocal built_in_format_assignment_count, custom_format_assignment_count
        if style.category == "built-in":
            built_in_format_assignment_count += amount
        elif style.category == "custom":
            custom_format_assignment_count += amount

    try:
        with ZipFile(path) as archive:
            try:
                styles = _xml_root(archive, "xl/styles.xml")
            except KeyError:
                styles = None

            custom_formats: dict[int, _NumberFormatStyle] = {}
            if styles is not None:
                if (
                    _xml_namespace(styles.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(styles.tag) != "styleSheet"
                ):
                    note_issue("style-sheet-root", styles.tag)
                    styles = None

            if styles is not None:
                num_fmts_tag = f"{{{_SPREADSHEETML_NS}}}numFmts"
                num_fmt_tag = f"{{{_SPREADSHEETML_NS}}}numFmt"
                num_fmt_containers = styles.findall(num_fmts_tag)
                if len(num_fmt_containers) > 1:
                    note_issue("multiple-number-format-containers", len(num_fmt_containers))
                for container_index, container in enumerate(num_fmt_containers):
                    for format_index, number_format in enumerate(container):
                        context = f"numFmt:{container_index}:{format_index}"
                        if number_format.tag != num_fmt_tag:
                            note_issue(f"{context}:unsupported-child", number_format.tag)
                            continue
                        identifier = _number_format_unsigned_int(
                            number_format.get("numFmtId")
                        )
                        code = number_format.get("formatCode")
                        if identifier is None or code is None:
                            note_issue(
                                f"{context}:missing-or-invalid-attributes",
                                (number_format.get("numFmtId"), code),
                            )
                            continue
                        if len(code) > _NUMBER_FORMAT_MAX_CODE_LENGTH:
                            note_issue(f"{context}:oversized-code", (identifier, len(code)))
                            custom_formats[identifier] = _number_format_unrecognized(
                                "oversized-number-format-code", identifier, len(code)
                            )
                            continue
                        if identifier <= _NUMBER_FORMAT_BUILT_IN_MAXIMUM:
                            note_issue(f"{context}:built-in-override", (identifier, code))
                            custom_formats[identifier] = _number_format_unrecognized(
                                "built-in-number-format-override", identifier, code
                            )
                            continue
                        style = (
                            _GENERAL_NUMBER_FORMAT
                            if code.casefold() == "general"
                            else _NumberFormatStyle("custom", code)
                        )
                        existing = custom_formats.get(identifier)
                        if existing is not None and existing != style:
                            note_issue(
                                f"{context}:duplicate-format-id", (identifier, code)
                            )
                            custom_formats[identifier] = _number_format_unrecognized(
                                "duplicate-number-format-id", identifier, existing, code
                            )
                            continue
                        custom_formats[identifier] = style

            def resolve_number_format(
                identifier: int,
                *,
                context: str,
            ) -> _NumberFormatStyle:
                if identifier in custom_formats:
                    return custom_formats[identifier]
                if identifier <= _NUMBER_FORMAT_BUILT_IN_MAXIMUM:
                    return _NumberFormatStyle("built-in", str(identifier))
                note_issue(f"{context}:unknown-custom-format", identifier)
                return _number_format_unrecognized(
                    "unknown-custom-number-format", context, identifier
                )

            def parse_style_index(
                value: str | None,
                *,
                context: str,
            ) -> int | None:
                if value is None:
                    return None
                parsed = _number_format_unsigned_int(value)
                if parsed is None:
                    note_issue(f"{context}:invalid-style-index", value)
                return parsed

            def resolve_xf(
                xf: ElementTree.Element,
                inherited: _NumberFormatStyle,
                *,
                context: str,
            ) -> _NumberFormatStyle:
                applies = _number_format_boolean(xf.get("applyNumberFormat"), True)
                if applies is None:
                    note_issue(
                        f"{context}:invalid-apply-number-format",
                        xf.get("applyNumberFormat"),
                    )
                    return _number_format_unrecognized(
                        "invalid-apply-number-format", context, xf.get("applyNumberFormat")
                    )
                identifier_value = xf.get("numFmtId")
                if not applies or identifier_value is None:
                    return inherited
                identifier = _number_format_unsigned_int(identifier_value)
                if identifier is None:
                    note_issue(f"{context}:invalid-number-format-id", identifier_value)
                    return _number_format_unrecognized(
                        "invalid-number-format-id", context, identifier_value
                    )
                return resolve_number_format(identifier, context=context)

            base_xfs: list[_NumberFormatStyle] = []
            effective_xfs: list[_NumberFormatStyle] = []
            if styles is not None:
                xf_tag = f"{{{_SPREADSHEETML_NS}}}xf"
                cell_style_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellStyleXfs"
                cell_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellXfs"
                base_containers = styles.findall(cell_style_xfs_tag)
                if len(base_containers) > 1:
                    note_issue("multiple-cell-style-xf-containers", len(base_containers))
                for container_index, container in enumerate(base_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"base-xf:{container_index}:{index}:unsupported-child", xf.tag
                            )
                            continue
                        base_xfs.append(
                            resolve_xf(
                                xf,
                                _GENERAL_NUMBER_FORMAT,
                                context=f"base-xf:{container_index}:{index}",
                            )
                        )
                if not base_xfs:
                    base_xfs.append(_GENERAL_NUMBER_FORMAT)

                cell_containers = styles.findall(cell_xfs_tag)
                if len(cell_containers) > 1:
                    note_issue("multiple-cell-xf-containers", len(cell_containers))
                for container_index, container in enumerate(cell_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"cell-xf:{container_index}:{index}:unsupported-child", xf.tag
                            )
                            continue
                        xf_id_value = xf.get("xfId")
                        inherited = _GENERAL_NUMBER_FORMAT
                        if xf_id_value is not None:
                            xf_id = parse_style_index(
                                xf_id_value,
                                context=f"cell-xf:{container_index}:{index}:base",
                            )
                            if xf_id is None or xf_id >= len(base_xfs):
                                note_issue(
                                    f"cell-xf:{container_index}:{index}:unknown-base-style",
                                    xf_id_value,
                                )
                                inherited = _number_format_unrecognized(
                                    "unknown-number-format-base-style",
                                    container_index,
                                    index,
                                    xf_id_value,
                                )
                            else:
                                inherited = base_xfs[xf_id]
                        effective_xfs.append(
                            resolve_xf(
                                xf,
                                inherited,
                                context=f"cell-xf:{container_index}:{index}",
                            )
                        )
            if not effective_xfs:
                effective_xfs.append(_GENERAL_NUMBER_FORMAT)

            default_style = effective_xfs[0]

            def style_for_assignment(
                value: str | None,
                *,
                context: str,
            ) -> _NumberFormatStyle | None:
                index = parse_style_index(value, context=context)
                if value is None:
                    return None
                if index is None or index >= len(effective_xfs):
                    note_issue(f"{context}:unknown-style", value)
                    return _number_format_unrecognized(
                        "unknown-number-format-style", context, value
                    )
                return effective_xfs[index]

            if default_style != _GENERAL_NUMBER_FORMAT:
                default_format_override_count += 1
                count_style(default_style)
                entries.append(("default-number-format", repr(default_style)))

            cols_tag = f"{{{_SPREADSHEETML_NS}}}cols"
            col_tag = f"{{{_SPREADSHEETML_NS}}}col"
            sheet_data_tag = f"{{{_SPREADSHEETML_NS}}}sheetData"
            row_tag = f"{{{_SPREADSHEETML_NS}}}row"
            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                column_states = [default_style] * (MAX_EXCEL_COLUMN + 1)
                column_updates = 0
                column_sets = worksheet.findall(cols_tag)
                for columns_index, columns in enumerate(column_sets):
                    for column_index, column in enumerate(columns):
                        context = f"column:{sheet.casefold()}:{columns_index}:{column_index}"
                        if column.tag != col_tag:
                            note_issue(f"{context}:unsupported-child", column.tag)
                            continue
                        if column.get("style") is None:
                            continue
                        minimum = _number_format_unsigned_int(column.get("min"))
                        maximum = _number_format_unsigned_int(column.get("max"))
                        style = style_for_assignment(column.get("style"), context=context)
                        if (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                            or maximum > MAX_EXCEL_COLUMN
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-column-span",
                                (column.get("min"), column.get("max"), column.get("style")),
                            )
                            continue
                        span = maximum - minimum + 1
                        if column_updates + span > _NUMBER_FORMAT_COLUMN_UPDATE_BUDGET:
                            note_issue(f"{context}:column-update-budget", span)
                            continue
                        column_states[minimum : maximum + 1] = [style] * span
                        column_updates += span

                column_signature = _number_format_column_state_signature(
                    column_states, default_style
                )
                if column_signature:
                    entries.append(
                        (
                            f"column-number-formats:{sheet.casefold()}",
                            repr(column_signature),
                        )
                    )
                    for minimum, maximum, category, _value in column_signature:
                        amount = maximum - minimum + 1
                        column_format_assignment_count += amount
                        if category == "built-in":
                            built_in_format_assignment_count += amount
                        elif category == "custom":
                            custom_format_assignment_count += amount

                raw_rows: list[tuple[int, _NumberFormatStyle]] = []
                for sheet_data_index, sheet_data in enumerate(worksheet.findall(sheet_data_tag)):
                    for row_index, row in enumerate(sheet_data):
                        context = (
                            f"row:{sheet.casefold()}:{sheet_data_index}:{row_index}"
                        )
                        if row.tag != row_tag:
                            continue
                        custom_format = _number_format_boolean(
                            row.get("customFormat"), False
                        )
                        if custom_format is None:
                            note_issue(
                                f"{context}:invalid-custom-format", row.get("customFormat")
                            )
                            continue
                        if not custom_format:
                            continue
                        row_number = _number_format_unsigned_int(row.get("r"))
                        style = style_for_assignment(row.get("s"), context=context)
                        if (
                            row_number is None
                            or row_number < 1
                            or row_number > MAX_EXCEL_ROW
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-row-assignment",
                                (row.get("r"), row.get("s")),
                            )
                            continue
                        raw_rows.append((row_number, style))

                relevant_rows = {
                    row_number
                    for row_number, style in raw_rows
                    if style != default_style
                }
                has_relevant_columns = bool(column_signature)
                for row_number, style in raw_rows:
                    if style == default_style and not has_relevant_columns:
                        continue
                    entries.append(
                        (
                            f"row-number-format:{sheet.casefold()}:{row_number}",
                            repr(style),
                        )
                    )
                    row_format_assignment_count += 1
                    count_style(style)

                seen_cells: set[str] = set()
                for cell in worksheet.iter(cell_tag):
                    if cell.get("s") is None:
                        continue
                    context = f"cell:{sheet.casefold()}"
                    coordinate = cell.get("r")
                    style = style_for_assignment(cell.get("s"), context=context)
                    match = (
                        re.fullmatch(r"([A-Za-z]+)([1-9][0-9]*)", coordinate)
                        if coordinate is not None
                        else None
                    )
                    if style is None or match is None:
                        note_issue(
                            f"{context}:invalid-cell-assignment", (coordinate, cell.get("s"))
                        )
                        continue
                    column_letters, raw_row_number = match.groups()
                    try:
                        column_number = (
                            column_index_from_string(column_letters)
                            if len(column_letters) <= 3
                            else 0
                        )
                    except ValueError:
                        column_number = 0
                    row_number = _number_format_unsigned_int(raw_row_number)
                    if row_number is None:
                        note_issue(
                            f"{context}:invalid-cell-row", (coordinate, cell.get("s"))
                        )
                        continue
                    if (
                        column_number < 1
                        or column_number > MAX_EXCEL_COLUMN
                        or row_number > MAX_EXCEL_ROW
                    ):
                        note_issue(
                            f"{context}:out-of-bounds-cell", (coordinate, cell.get("s"))
                        )
                        continue
                    canonical_coordinate = coordinate.upper()
                    if canonical_coordinate in seen_cells:
                        note_issue(
                            f"{context}:duplicate-cell", (canonical_coordinate, cell.get("s"))
                        )
                    seen_cells.add(canonical_coordinate)
                    if (
                        style == default_style
                        and row_number not in relevant_rows
                        and column_states[column_number] == default_style
                    ):
                        continue
                    entries.append(
                        (
                            f"cell-number-format:{sheet.casefold()}:{canonical_coordinate}",
                            repr(style),
                        )
                    )
                    cell_format_assignment_count += 1
                    count_style(style)
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _NumberFormatMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect cell number-format OOXML "
                f"({type(error).__name__}); affected display controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported cell number-format metadata; "
            "affected display controls have a coverage gap."
        )
        entries.extend(
            (f"number-format-issue:{context}", detail)
            for context, detail in sorted(issues.items())
        )
    snapshot = NumberFormatSnapshot(
        default_format_override_count=default_format_override_count,
        cell_format_assignment_count=cell_format_assignment_count,
        row_format_assignment_count=row_format_assignment_count,
        column_format_assignment_count=column_format_assignment_count,
        built_in_format_assignment_count=built_in_format_assignment_count,
        custom_format_assignment_count=custom_format_assignment_count,
        unrecognized_number_format_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
    )
    return _NumberFormatMetadata(snapshot, tuple(sorted(warnings)))


_FONT_COLUMN_UPDATE_BUDGET = 16_777_216
_FONT_BOOLEAN_CHILDREN = frozenset(
    {"b", "i", "strike", "outline", "shadow", "condense", "extend"}
)
_FONT_VALUE_CHILDREN = frozenset(
    {"name", "charset", "family", "sz", "u", "vertAlign", "scheme"}
)
_FONT_KNOWN_CHILDREN = _FONT_BOOLEAN_CHILDREN | _FONT_VALUE_CHILDREN | {"color"}
_FONT_COLOR_ATTRIBUTES = frozenset({"rgb", "indexed", "auto", "theme", "tint"})


@dataclass(frozen=True)
class _FontStyle:
    """One effective cell font retained only for private comparison."""

    category: str
    value: str


_DEFAULT_FONT_STYLE = _FontStyle("default", "0")


def _font_private_digest(value: object) -> str:
    """Hash private font material before it can reach an output model."""
    payload = repr(value).encode("utf-8", errors="surrogatepass")
    return hashlib.sha256(payload).hexdigest()


def _font_unrecognized(*parts: object) -> _FontStyle:
    """Fingerprint malformed font material without retaining it in output models."""
    return _FontStyle("unrecognized", _font_private_digest(parts))


def _font_decimal(value: str | None) -> str | None:
    """Normalize one finite OOXML decimal without accepting malformed text."""
    if value is None:
        return None
    try:
        parsed = Decimal(value.strip())
    except InvalidOperation:
        return None
    if not parsed.is_finite():
        return None
    if parsed == 0:
        return "0"
    normalized = parsed.normalize()
    return format(normalized, "f")


def _font_child_signature(
    child: ElementTree.Element,
    *,
    name: str,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[object, ...], bool]:
    """Return one canonical private font child and whether it was malformed.

    Font child order and common Boolean spellings vary between writers. This
    normalizes only documented leaf controls while leaving unsupported material
    fail-closed and privately fingerprinted by the caller.
    """
    invalid = False
    if child.text is not None and child.text.strip():
        note_issue(f"{context}:unexpected-text", child.text)
        invalid = True
    if any(child):
        note_issue(
            f"{context}:unexpected-child", tuple(current.tag for current in child)
        )
        invalid = True
    if child.tail is not None and child.tail.strip():
        note_issue(f"{context}:unexpected-tail", child.tail)
        invalid = True

    def unexpected_attributes(allowed: frozenset[str]) -> None:
        nonlocal invalid
        for attribute, value in child.attrib.items():
            local_name = _xml_local_name(attribute)
            if _xml_namespace(attribute) is not None or local_name not in allowed:
                note_issue(
                    f"{context}:unsupported-attribute",
                    (_xml_display_name(attribute), value),
                )
                invalid = True

    if name in _FONT_BOOLEAN_CHILDREN:
        unexpected_attributes(frozenset({"val"}))
        enabled = _number_format_boolean(child.get("val"), True)
        if enabled is None:
            note_issue(f"{context}:invalid-boolean", child.get("val"))
            invalid = True
            enabled = False
        return ((name, enabled), invalid)

    if name == "color":
        unexpected_attributes(_FONT_COLOR_ATTRIBUTES)
        entries: list[tuple[str, object]] = []
        selected = 0
        for attribute, value in child.attrib.items():
            local_name = _xml_local_name(attribute)
            if _xml_namespace(attribute) is not None or local_name not in _FONT_COLOR_ATTRIBUTES:
                continue
            candidate = value.strip()
            if local_name == "rgb":
                selected += 1
                if not re.fullmatch(r"[0-9A-Fa-f]{8}", candidate):
                    note_issue(f"{context}:invalid-rgb", value)
                    invalid = True
                candidate = candidate.upper()
            elif local_name in {"indexed", "theme"}:
                selected += 1
                parsed = _number_format_unsigned_int(candidate)
                if parsed is None:
                    note_issue(f"{context}:invalid-{local_name}", value)
                    invalid = True
                else:
                    candidate = str(parsed)
            elif local_name == "auto":
                selected += 1
                parsed_boolean = _number_format_boolean(candidate, True)
                if parsed_boolean is None:
                    note_issue(f"{context}:invalid-auto", value)
                    invalid = True
                else:
                    candidate = "true" if parsed_boolean else "false"
            else:  # ``tint`` is compatible with any one colour source.
                parsed_decimal = _font_decimal(candidate)
                if parsed_decimal is None:
                    note_issue(f"{context}:invalid-tint", value)
                    invalid = True
                else:
                    candidate = parsed_decimal
            entries.append((local_name, candidate))
        if selected > 1:
            note_issue(f"{context}:conflicting-colour-source", tuple(entries))
            invalid = True
        return ((name, tuple(sorted(entries))), invalid)

    unexpected_attributes(frozenset({"val"}))
    value = child.get("val")
    if value is None:
        note_issue(f"{context}:missing-value", name)
        return ((name, ""), True)
    if name in {"charset", "family"}:
        parsed = _number_format_unsigned_int(value)
        if parsed is None:
            note_issue(f"{context}:invalid-{name}", value)
            return ((name, value), True)
        return ((name, str(parsed)), invalid)
    if name == "sz":
        parsed = _font_decimal(value)
        if parsed is None:
            note_issue(f"{context}:invalid-size", value)
            return ((name, value), True)
        return ((name, parsed), invalid)
    if name == "u":
        return ((name, value.strip().casefold()), invalid)
    return ((name, value), invalid)


def _font_definition_style(
    font: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> _FontStyle:
    """Canonicalize a ``font`` record without exposing its private values."""
    invalid = False
    if font.attrib:
        note_issue(
            f"{context}:unsupported-attributes", tuple(sorted(font.attrib.items()))
        )
        invalid = True
    if font.text is not None and font.text.strip():
        note_issue(f"{context}:unexpected-text", font.text)
        invalid = True

    entries: list[tuple[object, ...]] = []
    opaque_children: list[object] = []
    seen: set[str] = set()
    for child_index, child in enumerate(font):
        child_context = f"{context}:child:{child_index}"
        name = _xml_local_name(child.tag)
        if _xml_namespace(child.tag) != _SPREADSHEETML_NS or name not in _FONT_KNOWN_CHILDREN:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        if name in seen:
            note_issue(f"{child_context}:duplicate-child", name)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        seen.add(name)
        signature, child_invalid = _font_child_signature(
            child,
            name=name,
            context=child_context,
            note_issue=note_issue,
        )
        if child_invalid:
            invalid = True
        # An explicit ``false`` Boolean is semantically equivalent to no
        # Boolean child, so this also normalizes common writer spellings.
        if name in _FONT_BOOLEAN_CHILDREN and signature[1] is False:
            continue
        entries.append(signature)

    definition = tuple(sorted(entries, key=repr))
    if invalid:
        return _font_unrecognized("font-definition", context, definition, opaque_children)
    return _FontStyle("font", _font_private_digest(definition))


def _font_column_state_signature(
    states: list[_FontStyle],
    default: _FontStyle,
) -> tuple[tuple[int, int, str, str], ...]:
    """Compress effective column fonts so equivalent range splitting stays quiet."""
    segments: list[tuple[int, int, str, str]] = []
    start: int | None = None
    previous: _FontStyle | None = None
    for column in range(1, MAX_EXCEL_COLUMN + 1):
        current = states[column]
        if current == default:
            if start is not None and previous is not None:
                segments.append((start, column - 1, previous.category, previous.value))
            start = None
            previous = None
            continue
        if start is None:
            start = column
            previous = current
            continue
        if current != previous:
            segments.append((start, column - 1, previous.category, previous.value))
            start = column
            previous = current
    if start is not None and previous is not None:
        segments.append((start, MAX_EXCEL_COLUMN, previous.category, previous.value))
    return tuple(segments)


def _font_metadata(path: Path) -> _FontMetadata:
    """Inspect effective cell, row, and column fonts from raw OOXML.

    A font can make a value substantially less visible without changing its
    stored content. The scanner resolves reusable style records, ``xfId``
    inheritance, and ``applyFont`` before keeping a private signature. Font
    definitions, style IDs, and report locations never leave this process.
    """
    warnings: set[str] = set()
    default_snapshot = FontSnapshot()
    entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    default_font_definition_count = 0
    cell_font_assignment_count = 0
    row_font_assignment_count = 0
    column_font_assignment_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            try:
                styles = _xml_root(archive, "xl/styles.xml")
            except KeyError:
                styles = None
            if styles is not None and (
                _xml_namespace(styles.tag) != _SPREADSHEETML_NS
                or _xml_local_name(styles.tag) != "styleSheet"
            ):
                note_issue("style-sheet-root", styles.tag)
                styles = None

            fonts: list[_FontStyle] = []
            if styles is not None:
                fonts_tag = f"{{{_SPREADSHEETML_NS}}}fonts"
                font_tag = f"{{{_SPREADSHEETML_NS}}}font"
                font_containers = styles.findall(fonts_tag)
                if len(font_containers) > 1:
                    note_issue("multiple-font-containers", len(font_containers))
                for container_index, container in enumerate(font_containers):
                    for font_index, font in enumerate(container):
                        context = f"font:{container_index}:{font_index}"
                        if font.tag != font_tag:
                            note_issue(f"{context}:unsupported-child", font.tag)
                            continue
                        fonts.append(
                            _font_definition_style(
                                font,
                                context=context,
                                note_issue=note_issue,
                            )
                        )

            def resolve_font(identifier: int, *, context: str) -> _FontStyle:
                if 0 <= identifier < len(fonts):
                    return fonts[identifier]
                note_issue(f"{context}:unknown-font", identifier)
                return _font_unrecognized("unknown-font", context, identifier)

            def parse_style_index(value: str | None, *, context: str) -> int | None:
                if value is None:
                    return None
                parsed = _number_format_unsigned_int(value)
                if parsed is None:
                    note_issue(f"{context}:invalid-style-index", value)
                return parsed

            def resolve_xf(
                xf: ElementTree.Element,
                inherited: _FontStyle,
                *,
                context: str,
            ) -> _FontStyle:
                applies = _number_format_boolean(xf.get("applyFont"), True)
                if applies is None:
                    note_issue(f"{context}:invalid-apply-font", xf.get("applyFont"))
                    return _font_unrecognized(
                        "invalid-apply-font", context, xf.get("applyFont")
                    )
                identifier_value = xf.get("fontId")
                if not applies or identifier_value is None:
                    return inherited
                identifier = _number_format_unsigned_int(identifier_value)
                if identifier is None:
                    note_issue(f"{context}:invalid-font-id", identifier_value)
                    return _font_unrecognized("invalid-font-id", context, identifier_value)
                return resolve_font(identifier, context=context)

            base_xfs: list[_FontStyle] = []
            effective_xfs: list[_FontStyle] = []
            if styles is not None:
                xf_tag = f"{{{_SPREADSHEETML_NS}}}xf"
                cell_style_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellStyleXfs"
                cell_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellXfs"
                base_containers = styles.findall(cell_style_xfs_tag)
                if len(base_containers) > 1:
                    note_issue("multiple-cell-style-xf-containers", len(base_containers))
                for container_index, container in enumerate(base_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"base-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        base_xfs.append(
                            resolve_xf(
                                xf,
                                _DEFAULT_FONT_STYLE,
                                context=f"base-xf:{container_index}:{index}",
                            )
                        )
                if not base_xfs:
                    base_xfs.append(_DEFAULT_FONT_STYLE)

                cell_containers = styles.findall(cell_xfs_tag)
                if len(cell_containers) > 1:
                    note_issue("multiple-cell-xf-containers", len(cell_containers))
                for container_index, container in enumerate(cell_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"cell-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        xf_id_value = xf.get("xfId")
                        inherited = _DEFAULT_FONT_STYLE
                        if xf_id_value is not None:
                            xf_id = parse_style_index(
                                xf_id_value,
                                context=f"cell-xf:{container_index}:{index}:base",
                            )
                            if xf_id is None or xf_id >= len(base_xfs):
                                note_issue(
                                    f"cell-xf:{container_index}:{index}:unknown-base-style",
                                    xf_id_value,
                                )
                                inherited = _font_unrecognized(
                                    "unknown-font-base-style",
                                    container_index,
                                    index,
                                    xf_id_value,
                                )
                            else:
                                inherited = base_xfs[xf_id]
                        effective_xfs.append(
                            resolve_xf(
                                xf,
                                inherited,
                                context=f"cell-xf:{container_index}:{index}",
                            )
                        )
            if not effective_xfs:
                effective_xfs.append(_DEFAULT_FONT_STYLE)

            default_style = effective_xfs[0]

            def style_for_assignment(
                value: str | None,
                *,
                context: str,
            ) -> _FontStyle | None:
                index = parse_style_index(value, context=context)
                if value is None:
                    return None
                if index is None or index >= len(effective_xfs):
                    note_issue(f"{context}:unknown-style", value)
                    return _font_unrecognized("unknown-font-style", context, value)
                return effective_xfs[index]

            if default_style != _DEFAULT_FONT_STYLE:
                default_font_definition_count = 1
                entries.append(("default-font", repr(default_style)))

            cols_tag = f"{{{_SPREADSHEETML_NS}}}cols"
            col_tag = f"{{{_SPREADSHEETML_NS}}}col"
            sheet_data_tag = f"{{{_SPREADSHEETML_NS}}}sheetData"
            row_tag = f"{{{_SPREADSHEETML_NS}}}row"
            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                column_states = [default_style] * (MAX_EXCEL_COLUMN + 1)
                column_updates = 0
                for columns_index, columns in enumerate(worksheet.findall(cols_tag)):
                    for column_index, column in enumerate(columns):
                        context = f"column:{sheet.casefold()}:{columns_index}:{column_index}"
                        if column.tag != col_tag:
                            note_issue(f"{context}:unsupported-child", column.tag)
                            continue
                        if column.get("style") is None:
                            continue
                        minimum = _number_format_unsigned_int(column.get("min"))
                        maximum = _number_format_unsigned_int(column.get("max"))
                        style = style_for_assignment(column.get("style"), context=context)
                        if (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                            or maximum > MAX_EXCEL_COLUMN
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-column-span",
                                (column.get("min"), column.get("max"), column.get("style")),
                            )
                            continue
                        span = maximum - minimum + 1
                        if column_updates + span > _FONT_COLUMN_UPDATE_BUDGET:
                            note_issue(f"{context}:column-update-budget", span)
                            continue
                        column_states[minimum : maximum + 1] = [style] * span
                        column_updates += span

                column_signature = _font_column_state_signature(column_states, default_style)
                if column_signature:
                    entries.append(
                        (f"column-fonts:{sheet.casefold()}", repr(column_signature))
                    )
                    column_font_assignment_count += sum(
                        maximum - minimum + 1
                        for minimum, maximum, _category, _value in column_signature
                    )

                raw_rows: list[tuple[int, _FontStyle]] = []
                for sheet_data_index, sheet_data in enumerate(worksheet.findall(sheet_data_tag)):
                    for row_index, row in enumerate(sheet_data):
                        context = f"row:{sheet.casefold()}:{sheet_data_index}:{row_index}"
                        if row.tag != row_tag:
                            continue
                        custom_format = _number_format_boolean(
                            row.get("customFormat"), False
                        )
                        if custom_format is None:
                            note_issue(
                                f"{context}:invalid-custom-format",
                                row.get("customFormat"),
                            )
                            continue
                        if not custom_format:
                            continue
                        row_number = _number_format_unsigned_int(row.get("r"))
                        style = style_for_assignment(row.get("s"), context=context)
                        if (
                            row_number is None
                            or row_number < 1
                            or row_number > MAX_EXCEL_ROW
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-row-assignment",
                                (row.get("r"), row.get("s")),
                            )
                            continue
                        raw_rows.append((row_number, style))

                relevant_rows = {
                    row_number
                    for row_number, style in raw_rows
                    if style != default_style
                }
                has_relevant_columns = bool(column_signature)
                for row_number, style in raw_rows:
                    if style == default_style and not has_relevant_columns:
                        continue
                    entries.append(
                        (
                            f"row-font:{sheet.casefold()}:{row_number}",
                            repr(style),
                        )
                    )
                    row_font_assignment_count += 1

                seen_cells: set[str] = set()
                for cell in worksheet.iter(cell_tag):
                    if cell.get("s") is None:
                        continue
                    context = f"cell:{sheet.casefold()}"
                    coordinate = cell.get("r")
                    style = style_for_assignment(cell.get("s"), context=context)
                    match = (
                        re.fullmatch(r"([A-Za-z]+)([1-9][0-9]*)", coordinate)
                        if coordinate is not None
                        else None
                    )
                    if style is None or match is None:
                        note_issue(
                            f"{context}:invalid-cell-assignment",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    column_letters, raw_row_number = match.groups()
                    try:
                        column_number = (
                            column_index_from_string(column_letters)
                            if len(column_letters) <= 3
                            else 0
                        )
                    except ValueError:
                        column_number = 0
                    row_number = _number_format_unsigned_int(raw_row_number)
                    if row_number is None:
                        note_issue(
                            f"{context}:invalid-cell-row",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    if (
                        column_number < 1
                        or column_number > MAX_EXCEL_COLUMN
                        or row_number > MAX_EXCEL_ROW
                    ):
                        note_issue(
                            f"{context}:out-of-bounds-cell",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    canonical_coordinate = coordinate.upper()
                    if canonical_coordinate in seen_cells:
                        note_issue(
                            f"{context}:duplicate-cell",
                            (canonical_coordinate, cell.get("s")),
                        )
                    seen_cells.add(canonical_coordinate)
                    if (
                        style == default_style
                        and row_number not in relevant_rows
                        and column_states[column_number] == default_style
                    ):
                        continue
                    entries.append(
                        (
                            f"cell-font:{sheet.casefold()}:{canonical_coordinate}",
                            repr(style),
                        )
                    )
                    cell_font_assignment_count += 1
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _FontMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect cell-font OOXML "
                f"({type(error).__name__}); affected display controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported cell-font metadata; "
            "affected display controls have a coverage gap."
        )
        entries.extend(
            (f"font-issue:{context}", detail)
            for context, detail in sorted(issues.items())
        )
    snapshot = FontSnapshot(
        default_font_definition_count=default_font_definition_count,
        cell_font_assignment_count=cell_font_assignment_count,
        row_font_assignment_count=row_font_assignment_count,
        column_font_assignment_count=column_font_assignment_count,
        unrecognized_font_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
    )
    return _FontMetadata(snapshot, tuple(sorted(warnings)))


_FILL_COLUMN_UPDATE_BUDGET = 16_777_216
_FILL_MAX_GRADIENT_STOPS = 4_096
_FILL_COLOR_ATTRIBUTES = frozenset({"rgb", "indexed", "auto", "theme", "tint"})
_FILL_PATTERN_TYPES = frozenset(
    {
        "none",
        "solid",
        "mediumGray",
        "darkGray",
        "lightGray",
        "darkHorizontal",
        "darkVertical",
        "darkDown",
        "darkUp",
        "darkGrid",
        "darkTrellis",
        "lightHorizontal",
        "lightVertical",
        "lightDown",
        "lightUp",
        "lightGrid",
        "lightTrellis",
        "gray125",
        "gray0625",
    }
)
_FILL_GRADIENT_TYPES = frozenset({"linear", "path"})


@dataclass(frozen=True)
class _FillStyle:
    """One effective cell fill retained only for private comparison."""

    category: str
    value: str


_DEFAULT_FILL_STYLE = _FillStyle("default", "0")


def _fill_private_digest(value: object) -> str:
    """Hash private fill material before it can reach an output model."""
    payload = repr(value).encode("utf-8", errors="surrogatepass")
    return hashlib.sha256(payload).hexdigest()


def _fill_unrecognized(*parts: object) -> _FillStyle:
    """Fingerprint unsupported fill material without retaining it in output models."""
    return _FillStyle("unrecognized", _fill_private_digest(parts))


def _fill_decimal(value: str | None) -> str | None:
    """Normalize one finite OOXML decimal without accepting malformed text."""
    if value is None:
        return None
    try:
        parsed = Decimal(value.strip())
    except InvalidOperation:
        return None
    if not parsed.is_finite():
        return None
    if parsed == 0:
        return "0"
    normalized = parsed.normalize()
    return format(normalized, "f")


def _fill_unit_interval_decimal(value: str | None) -> str | None:
    """Normalize an OOXML decimal constrained to the inclusive [0, 1] interval."""
    normalized = _fill_decimal(value)
    if normalized is None:
        return None
    parsed = Decimal(normalized)
    if parsed < 0 or parsed > 1:
        return None
    return normalized


def _fill_unexpected_attributes(
    element: ElementTree.Element,
    *,
    allowed: frozenset[str],
    context: str,
    note_issue: Callable[[str, object], None],
) -> bool:
    """Record unsupported attributes while keeping their values private."""
    invalid = False
    for attribute, value in element.attrib.items():
        local_name = _xml_local_name(attribute)
        if _xml_namespace(attribute) is not None or local_name not in allowed:
            note_issue(
                f"{context}:unsupported-attribute",
                (_xml_display_name(attribute), value),
            )
            invalid = True
    return invalid


def _fill_unexpected_text(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> bool:
    """Record unexpected character data without including it in public output."""
    invalid = False
    if element.text is not None and element.text.strip():
        note_issue(f"{context}:unexpected-text", element.text)
        invalid = True
    if element.tail is not None and element.tail.strip():
        note_issue(f"{context}:unexpected-tail", element.tail)
        invalid = True
    return invalid


def _fill_color_signature(
    color: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[tuple[str, object], ...], bool]:
    """Canonicalize one private OOXML colour expression used by a fill."""
    invalid = _fill_unexpected_text(color, context=context, note_issue=note_issue)
    if any(color):
        note_issue(f"{context}:unexpected-child", tuple(child.tag for child in color))
        invalid = True
    if _fill_unexpected_attributes(
        color,
        allowed=_FILL_COLOR_ATTRIBUTES,
        context=context,
        note_issue=note_issue,
    ):
        invalid = True

    entries: list[tuple[str, object]] = []
    selected = 0
    for attribute, value in color.attrib.items():
        local_name = _xml_local_name(attribute)
        if _xml_namespace(attribute) is not None or local_name not in _FILL_COLOR_ATTRIBUTES:
            continue
        candidate = value.strip()
        if local_name == "rgb":
            selected += 1
            if not re.fullmatch(r"[0-9A-Fa-f]{8}", candidate):
                note_issue(f"{context}:invalid-rgb", value)
                invalid = True
            candidate = candidate.upper()
        elif local_name in {"indexed", "theme"}:
            selected += 1
            parsed = _number_format_unsigned_int(candidate)
            if parsed is None:
                note_issue(f"{context}:invalid-{local_name}", value)
                invalid = True
            else:
                candidate = str(parsed)
        elif local_name == "auto":
            selected += 1
            parsed_boolean = _number_format_boolean(candidate, True)
            if parsed_boolean is None:
                note_issue(f"{context}:invalid-auto", value)
                invalid = True
            else:
                candidate = "true" if parsed_boolean else "false"
        else:  # ``tint`` can accompany exactly one colour source.
            parsed_decimal = _fill_decimal(candidate)
            if parsed_decimal is None:
                note_issue(f"{context}:invalid-tint", value)
                invalid = True
            else:
                candidate = parsed_decimal
        entries.append((local_name, candidate))
    if selected > 1:
        note_issue(f"{context}:conflicting-colour-source", tuple(entries))
        invalid = True
    return tuple(sorted(entries)), invalid


def _fill_pattern_signature(
    pattern_fill: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[object, ...], bool]:
    """Canonicalize a pattern fill while normalizing semantically inert fields."""
    invalid = _fill_unexpected_text(pattern_fill, context=context, note_issue=note_issue)
    if _fill_unexpected_attributes(
        pattern_fill,
        allowed=frozenset({"patternType"}),
        context=context,
        note_issue=note_issue,
    ):
        invalid = True
    raw_pattern_type = pattern_fill.get("patternType")
    pattern_type = raw_pattern_type.strip() if raw_pattern_type is not None else "none"
    if pattern_type not in _FILL_PATTERN_TYPES:
        note_issue(f"{context}:invalid-pattern-type", raw_pattern_type)
        invalid = True
        pattern_type = "none"

    color_tags = {
        "fgColor": f"{{{_SPREADSHEETML_NS}}}fgColor",
        "bgColor": f"{{{_SPREADSHEETML_NS}}}bgColor",
    }
    colors: dict[str, tuple[tuple[str, object], ...]] = {}
    for child_index, child in enumerate(pattern_fill):
        child_context = f"{context}:child:{child_index}"
        color_name = next(
            (name for name, tag in color_tags.items() if child.tag == tag),
            None,
        )
        if color_name is None:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            invalid = True
            continue
        if color_name in colors:
            note_issue(f"{child_context}:duplicate-child", color_name)
            invalid = True
            continue
        signature, color_invalid = _fill_color_signature(
            child,
            context=child_context,
            note_issue=note_issue,
        )
        if color_invalid:
            invalid = True
        colors[color_name] = signature

    # OOXML specifies ``none`` as the default. Neither colour is rendered for
    # it, and only fgColor is rendered for solid fills, so disregarding inert
    # valid declarations avoids alerting on writer-only noise.
    if pattern_type == "none":
        return (("pattern", "none"), invalid)
    if pattern_type == "solid":
        return (("pattern", "solid", colors.get("fgColor")), invalid)
    return (
        (
            "pattern",
            pattern_type,
            colors.get("fgColor"),
            colors.get("bgColor"),
        ),
        invalid,
    )


def _fill_gradient_stop_signature(
    stop: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[object, ...], bool]:
    """Canonicalize one gradient stop and its private colour expression."""
    invalid = _fill_unexpected_text(stop, context=context, note_issue=note_issue)
    if _fill_unexpected_attributes(
        stop,
        allowed=frozenset({"position"}),
        context=context,
        note_issue=note_issue,
    ):
        invalid = True
    position = _fill_unit_interval_decimal(stop.get("position"))
    if position is None:
        note_issue(f"{context}:invalid-position", stop.get("position"))
        invalid = True
        position = ""

    color_tag = f"{{{_SPREADSHEETML_NS}}}color"
    color_signature: tuple[tuple[str, object], ...] | None = None
    for child_index, child in enumerate(stop):
        child_context = f"{context}:child:{child_index}"
        if child.tag != color_tag:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            invalid = True
            continue
        if color_signature is not None:
            note_issue(f"{child_context}:duplicate-colour", child.tag)
            invalid = True
            continue
        color_signature, color_invalid = _fill_color_signature(
            child,
            context=child_context,
            note_issue=note_issue,
        )
        if color_invalid:
            invalid = True
    if color_signature is None:
        note_issue(f"{context}:missing-colour", stop.tag)
        invalid = True
    return (("stop", position, color_signature), invalid)


def _fill_gradient_signature(
    gradient_fill: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[object, ...], bool]:
    """Canonicalize a linear or path gradient fill without rendering it."""
    invalid = _fill_unexpected_text(gradient_fill, context=context, note_issue=note_issue)
    if _fill_unexpected_attributes(
        gradient_fill,
        allowed=frozenset({"type", "degree", "left", "right", "top", "bottom"}),
        context=context,
        note_issue=note_issue,
    ):
        invalid = True
    raw_gradient_type = gradient_fill.get("type")
    gradient_type = (
        raw_gradient_type.strip() if raw_gradient_type is not None else "linear"
    )
    if gradient_type not in _FILL_GRADIENT_TYPES:
        note_issue(f"{context}:invalid-gradient-type", raw_gradient_type)
        invalid = True
        gradient_type = "linear"

    degree = _fill_decimal(gradient_fill.get("degree", "0"))
    if degree is None:
        note_issue(f"{context}:invalid-degree", gradient_fill.get("degree"))
        invalid = True
        degree = ""
    boundaries: list[tuple[str, str]] = []
    for name in ("left", "right", "top", "bottom"):
        normalized = _fill_unit_interval_decimal(gradient_fill.get(name, "0"))
        if normalized is None:
            note_issue(f"{context}:invalid-{name}", gradient_fill.get(name))
            invalid = True
            normalized = ""
        boundaries.append((name, normalized))

    stop_tag = f"{{{_SPREADSHEETML_NS}}}stop"
    stops: list[tuple[object, ...]] = []
    for child_index, child in enumerate(gradient_fill):
        child_context = f"{context}:child:{child_index}"
        if child_index >= _FILL_MAX_GRADIENT_STOPS:
            note_issue(f"{context}:gradient-stop-budget", child_index + 1)
            invalid = True
            break
        if child.tag != stop_tag:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            invalid = True
            continue
        signature, stop_invalid = _fill_gradient_stop_signature(
            child,
            context=child_context,
            note_issue=note_issue,
        )
        if stop_invalid:
            invalid = True
        stops.append(signature)
    if len(stops) < 2:
        note_issue(f"{context}:insufficient-gradient-stops", len(stops))
        invalid = True

    # Path boundaries do not affect linear gradients, while degree does not
    # affect path gradients. Parse both kinds fail-closed, but retain only the
    # rendering-relevant values in the canonical signature.
    if gradient_type == "linear":
        return (("gradient", "linear", degree, tuple(stops)), invalid)
    return (("gradient", "path", tuple(boundaries), tuple(stops)), invalid)


def _fill_definition_style(
    fill: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> _FillStyle:
    """Canonicalize one ``fill`` record without exposing private values."""
    invalid = _fill_unexpected_text(fill, context=context, note_issue=note_issue)
    if fill.attrib:
        note_issue(
            f"{context}:unsupported-attributes", tuple(sorted(fill.attrib.items()))
        )
        invalid = True

    pattern_fill_tag = f"{{{_SPREADSHEETML_NS}}}patternFill"
    gradient_fill_tag = f"{{{_SPREADSHEETML_NS}}}gradientFill"
    definitions: list[tuple[object, ...]] = []
    opaque_children: list[object] = []
    for child_index, child in enumerate(fill):
        child_context = f"{context}:child:{child_index}"
        if child.tag == pattern_fill_tag:
            signature, child_invalid = _fill_pattern_signature(
                child,
                context=child_context,
                note_issue=note_issue,
            )
        elif child.tag == gradient_fill_tag:
            signature, child_invalid = _fill_gradient_signature(
                child,
                context=child_context,
                note_issue=note_issue,
            )
        else:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        if definitions:
            note_issue(f"{child_context}:multiple-fill-definitions", child.tag)
            invalid = True
            continue
        definitions.append(signature)
        if child_invalid:
            invalid = True
    if not definitions:
        note_issue(f"{context}:missing-fill-definition", fill.tag)
        invalid = True

    definition = tuple(definitions)
    if invalid:
        return _fill_unrecognized("fill-definition", context, definition, opaque_children)
    if definition == (("pattern", "none"),):
        return _DEFAULT_FILL_STYLE
    return _FillStyle("fill", _fill_private_digest(definition))


def _fill_column_state_signature(
    states: list[_FillStyle],
    default: _FillStyle,
) -> tuple[tuple[int, int, str, str], ...]:
    """Compress effective column fills so equivalent range splitting stays quiet."""
    segments: list[tuple[int, int, str, str]] = []
    start: int | None = None
    previous: _FillStyle | None = None
    for column in range(1, MAX_EXCEL_COLUMN + 1):
        current = states[column]
        if current == default:
            if start is not None and previous is not None:
                segments.append((start, column - 1, previous.category, previous.value))
            start = None
            previous = None
            continue
        if start is None:
            start = column
            previous = current
            continue
        if current != previous:
            segments.append((start, column - 1, previous.category, previous.value))
            start = column
            previous = current
    if start is not None and previous is not None:
        segments.append((start, MAX_EXCEL_COLUMN, previous.category, previous.value))
    return tuple(segments)


def _fill_metadata(path: Path) -> _FillMetadata:
    """Inspect effective cell, row, and column fills from raw OOXML.

    A fill can make a value, warning, or visual classification much less
    visible without changing its stored content. The scanner resolves reusable
    style records, ``xfId`` inheritance, and ``applyFill`` before keeping a
    private signature. Fill definitions, style IDs, and report locations never
    leave this process.
    """
    warnings: set[str] = set()
    default_snapshot = FillSnapshot()
    entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    default_fill_definition_count = 0
    cell_fill_assignment_count = 0
    row_fill_assignment_count = 0
    column_fill_assignment_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            try:
                styles = _xml_root(archive, "xl/styles.xml")
            except KeyError:
                styles = None
            if styles is not None and (
                _xml_namespace(styles.tag) != _SPREADSHEETML_NS
                or _xml_local_name(styles.tag) != "styleSheet"
            ):
                note_issue("style-sheet-root", styles.tag)
                styles = None

            fills: list[_FillStyle] = []
            if styles is not None:
                fills_tag = f"{{{_SPREADSHEETML_NS}}}fills"
                fill_tag = f"{{{_SPREADSHEETML_NS}}}fill"
                fill_containers = styles.findall(fills_tag)
                if len(fill_containers) > 1:
                    note_issue("multiple-fill-containers", len(fill_containers))
                for container_index, container in enumerate(fill_containers):
                    for fill_index, fill in enumerate(container):
                        context = f"fill:{container_index}:{fill_index}"
                        if fill.tag != fill_tag:
                            note_issue(f"{context}:unsupported-child", fill.tag)
                            continue
                        fills.append(
                            _fill_definition_style(
                                fill,
                                context=context,
                                note_issue=note_issue,
                            )
                        )

            def resolve_fill(identifier: int, *, context: str) -> _FillStyle:
                if 0 <= identifier < len(fills):
                    return fills[identifier]
                note_issue(f"{context}:unknown-fill", identifier)
                return _fill_unrecognized("unknown-fill", context, identifier)

            def parse_style_index(value: str | None, *, context: str) -> int | None:
                if value is None:
                    return None
                parsed = _number_format_unsigned_int(value)
                if parsed is None:
                    note_issue(f"{context}:invalid-style-index", value)
                return parsed

            def resolve_xf(
                xf: ElementTree.Element,
                inherited: _FillStyle,
                *,
                context: str,
            ) -> _FillStyle:
                applies = _number_format_boolean(xf.get("applyFill"), True)
                if applies is None:
                    note_issue(f"{context}:invalid-apply-fill", xf.get("applyFill"))
                    return _fill_unrecognized(
                        "invalid-apply-fill", context, xf.get("applyFill")
                    )
                identifier_value = xf.get("fillId")
                if not applies or identifier_value is None:
                    return inherited
                identifier = _number_format_unsigned_int(identifier_value)
                if identifier is None:
                    note_issue(f"{context}:invalid-fill-id", identifier_value)
                    return _fill_unrecognized("invalid-fill-id", context, identifier_value)
                return resolve_fill(identifier, context=context)

            base_xfs: list[_FillStyle] = []
            effective_xfs: list[_FillStyle] = []
            if styles is not None:
                xf_tag = f"{{{_SPREADSHEETML_NS}}}xf"
                cell_style_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellStyleXfs"
                cell_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellXfs"
                base_containers = styles.findall(cell_style_xfs_tag)
                if len(base_containers) > 1:
                    note_issue("multiple-cell-style-xf-containers", len(base_containers))
                for container_index, container in enumerate(base_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"base-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        base_xfs.append(
                            resolve_xf(
                                xf,
                                _DEFAULT_FILL_STYLE,
                                context=f"base-xf:{container_index}:{index}",
                            )
                        )
                if not base_xfs:
                    base_xfs.append(_DEFAULT_FILL_STYLE)

                cell_containers = styles.findall(cell_xfs_tag)
                if len(cell_containers) > 1:
                    note_issue("multiple-cell-xf-containers", len(cell_containers))
                for container_index, container in enumerate(cell_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"cell-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        xf_id_value = xf.get("xfId")
                        inherited = _DEFAULT_FILL_STYLE
                        if xf_id_value is not None:
                            xf_id = parse_style_index(
                                xf_id_value,
                                context=f"cell-xf:{container_index}:{index}:base",
                            )
                            if xf_id is None or xf_id >= len(base_xfs):
                                note_issue(
                                    f"cell-xf:{container_index}:{index}:unknown-base-style",
                                    xf_id_value,
                                )
                                inherited = _fill_unrecognized(
                                    "unknown-fill-base-style",
                                    container_index,
                                    index,
                                    xf_id_value,
                                )
                            else:
                                inherited = base_xfs[xf_id]
                        effective_xfs.append(
                            resolve_xf(
                                xf,
                                inherited,
                                context=f"cell-xf:{container_index}:{index}",
                            )
                        )
            if not effective_xfs:
                effective_xfs.append(_DEFAULT_FILL_STYLE)

            default_style = effective_xfs[0]

            def style_for_assignment(
                value: str | None,
                *,
                context: str,
            ) -> _FillStyle | None:
                index = parse_style_index(value, context=context)
                if value is None:
                    return None
                if index is None or index >= len(effective_xfs):
                    note_issue(f"{context}:unknown-style", value)
                    return _fill_unrecognized("unknown-fill-style", context, value)
                return effective_xfs[index]

            if default_style != _DEFAULT_FILL_STYLE:
                default_fill_definition_count = 1
                entries.append(("default-fill", repr(default_style)))

            cols_tag = f"{{{_SPREADSHEETML_NS}}}cols"
            col_tag = f"{{{_SPREADSHEETML_NS}}}col"
            sheet_data_tag = f"{{{_SPREADSHEETML_NS}}}sheetData"
            row_tag = f"{{{_SPREADSHEETML_NS}}}row"
            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                column_states = [default_style] * (MAX_EXCEL_COLUMN + 1)
                column_updates = 0
                for columns_index, columns in enumerate(worksheet.findall(cols_tag)):
                    for column_index, column in enumerate(columns):
                        context = f"column:{sheet.casefold()}:{columns_index}:{column_index}"
                        if column.tag != col_tag:
                            note_issue(f"{context}:unsupported-child", column.tag)
                            continue
                        if column.get("style") is None:
                            continue
                        minimum = _number_format_unsigned_int(column.get("min"))
                        maximum = _number_format_unsigned_int(column.get("max"))
                        style = style_for_assignment(column.get("style"), context=context)
                        if (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                            or maximum > MAX_EXCEL_COLUMN
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-column-span",
                                (column.get("min"), column.get("max"), column.get("style")),
                            )
                            continue
                        span = maximum - minimum + 1
                        if column_updates + span > _FILL_COLUMN_UPDATE_BUDGET:
                            note_issue(f"{context}:column-update-budget", span)
                            continue
                        column_states[minimum : maximum + 1] = [style] * span
                        column_updates += span

                column_signature = _fill_column_state_signature(
                    column_states, default_style
                )
                if column_signature:
                    entries.append(
                        (f"column-fills:{sheet.casefold()}", repr(column_signature))
                    )
                    column_fill_assignment_count += sum(
                        maximum - minimum + 1
                        for minimum, maximum, _category, _value in column_signature
                    )

                raw_rows: list[tuple[int, _FillStyle]] = []
                for sheet_data_index, sheet_data in enumerate(worksheet.findall(sheet_data_tag)):
                    for row_index, row in enumerate(sheet_data):
                        context = f"row:{sheet.casefold()}:{sheet_data_index}:{row_index}"
                        if row.tag != row_tag:
                            continue
                        custom_format = _number_format_boolean(
                            row.get("customFormat"), False
                        )
                        if custom_format is None:
                            note_issue(
                                f"{context}:invalid-custom-format",
                                row.get("customFormat"),
                            )
                            continue
                        if not custom_format:
                            continue
                        row_number = _number_format_unsigned_int(row.get("r"))
                        style = style_for_assignment(row.get("s"), context=context)
                        if (
                            row_number is None
                            or row_number < 1
                            or row_number > MAX_EXCEL_ROW
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-row-assignment",
                                (row.get("r"), row.get("s")),
                            )
                            continue
                        raw_rows.append((row_number, style))

                relevant_rows = {
                    row_number
                    for row_number, style in raw_rows
                    if style != default_style
                }
                has_relevant_columns = bool(column_signature)
                for row_number, style in raw_rows:
                    if style == default_style and not has_relevant_columns:
                        continue
                    entries.append(
                        (f"row-fill:{sheet.casefold()}:{row_number}", repr(style))
                    )
                    row_fill_assignment_count += 1

                seen_cells: set[str] = set()
                for cell in worksheet.iter(cell_tag):
                    if cell.get("s") is None:
                        continue
                    context = f"cell:{sheet.casefold()}"
                    coordinate = cell.get("r")
                    style = style_for_assignment(cell.get("s"), context=context)
                    match = (
                        re.fullmatch(r"([A-Za-z]+)([1-9][0-9]*)", coordinate)
                        if coordinate is not None
                        else None
                    )
                    if style is None or match is None:
                        note_issue(
                            f"{context}:invalid-cell-assignment",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    column_letters, raw_row_number = match.groups()
                    try:
                        column_number = (
                            column_index_from_string(column_letters)
                            if len(column_letters) <= 3
                            else 0
                        )
                    except ValueError:
                        column_number = 0
                    row_number = _number_format_unsigned_int(raw_row_number)
                    if row_number is None:
                        note_issue(
                            f"{context}:invalid-cell-row",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    if (
                        column_number < 1
                        or column_number > MAX_EXCEL_COLUMN
                        or row_number > MAX_EXCEL_ROW
                    ):
                        note_issue(
                            f"{context}:out-of-bounds-cell",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    canonical_coordinate = coordinate.upper()
                    if canonical_coordinate in seen_cells:
                        note_issue(
                            f"{context}:duplicate-cell",
                            (canonical_coordinate, cell.get("s")),
                        )
                    seen_cells.add(canonical_coordinate)
                    if (
                        style == default_style
                        and row_number not in relevant_rows
                        and column_states[column_number] == default_style
                    ):
                        continue
                    entries.append(
                        (
                            f"cell-fill:{sheet.casefold()}:{canonical_coordinate}",
                            repr(style),
                        )
                    )
                    cell_fill_assignment_count += 1
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _FillMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect cell-fill OOXML "
                f"({type(error).__name__}); affected display controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported cell-fill metadata; "
            "affected display controls have a coverage gap."
        )
        entries.extend(
            (f"fill-issue:{context}", detail)
            for context, detail in sorted(issues.items())
        )
    snapshot = FillSnapshot(
        default_fill_definition_count=default_fill_definition_count,
        cell_fill_assignment_count=cell_fill_assignment_count,
        row_fill_assignment_count=row_fill_assignment_count,
        column_fill_assignment_count=column_fill_assignment_count,
        unrecognized_fill_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
    )
    return _FillMetadata(snapshot, tuple(sorted(warnings)))


_ALIGNMENT_COLUMN_UPDATE_BUDGET = 16_777_216
_ALIGNMENT_HORIZONTAL_VALUES = frozenset(
    {
        "general",
        "left",
        "center",
        "right",
        "fill",
        "justify",
        "centerContinuous",
        "distributed",
    }
)
_ALIGNMENT_VERTICAL_VALUES = frozenset(
    {"top", "center", "bottom", "justify", "distributed"}
)
_ALIGNMENT_ATTRIBUTES = frozenset(
    {
        "horizontal",
        "vertical",
        "textRotation",
        "wrapText",
        "shrinkToFit",
        "indent",
        "relativeIndent",
        "justifyLastLine",
        "readingOrder",
        "mergeCell",
    }
)
_ALIGNMENT_TEXT_ROTATION_VALUES = frozenset((*range(181), 255))
_ALIGNMENT_INDENT_MAXIMUM = 255
_ALIGNMENT_READING_ORDER_VALUES = frozenset({0, 1, 2})
_ALIGNMENT_INT32_MINIMUM = -(2**31)
_ALIGNMENT_INT32_MAXIMUM = 2**31 - 1


@dataclass(frozen=True)
class _AlignmentStyle:
    """One effective cell alignment retained only for private comparison."""

    category: str
    value: str


_DEFAULT_ALIGNMENT_STYLE = _AlignmentStyle("default", "0")


def _alignment_private_digest(value: object) -> str:
    """Hash private alignment material before it can reach an output model."""
    payload = repr(value).encode("utf-8", errors="surrogatepass")
    return hashlib.sha256(payload).hexdigest()


def _alignment_unrecognized(*parts: object) -> _AlignmentStyle:
    """Fingerprint unsupported alignment material without public retention."""
    return _AlignmentStyle("unrecognized", _alignment_private_digest(parts))


def _alignment_signed_int32(value: str | None) -> int | None:
    """Read one bounded XML signed Int32 with schema whitespace normalized."""
    if value is None:
        return None
    candidate = value.strip()
    negative = candidate.startswith("-")
    if candidate.startswith(("-", "+")):
        candidate = candidate[1:]
    if not candidate.isascii() or not candidate.isdecimal():
        return None
    significant_digits = candidate.lstrip("0") or "0"
    maximum = (
        _ALIGNMENT_INT32_MAXIMUM + 1
        if negative
        else _ALIGNMENT_INT32_MAXIMUM
    )
    if len(significant_digits) > len(str(maximum)):
        return None
    parsed = int(significant_digits)
    if parsed > maximum:
        return None
    normalized = -parsed if negative else parsed
    if not _ALIGNMENT_INT32_MINIMUM <= normalized <= _ALIGNMENT_INT32_MAXIMUM:
        return None
    return normalized


def _alignment_definition_style(
    alignment: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> _AlignmentStyle:
    """Canonicalize one effective alignment element without exposing values."""
    invalid = False
    raw_attributes = tuple(
        sorted(
            (_xml_display_name(attribute), value)
            for attribute, value in alignment.attrib.items()
        )
    )
    for attribute, value in alignment.attrib.items():
        local_name = _xml_local_name(attribute)
        if (
            _xml_namespace(attribute) is not None
            or local_name not in _ALIGNMENT_ATTRIBUTES
        ):
            note_issue(
                f"{context}:unsupported-attribute",
                (_xml_display_name(attribute), value),
            )
            invalid = True
    if alignment.text is not None and alignment.text.strip():
        note_issue(f"{context}:unexpected-text", alignment.text)
        invalid = True
    if alignment.tail is not None and alignment.tail.strip():
        note_issue(f"{context}:unexpected-tail", alignment.tail)
        invalid = True
    opaque_children: list[object] = []
    for child_index, child in enumerate(alignment):
        note_issue(f"{context}:child:{child_index}:unsupported-child", child.tag)
        opaque_children.append(_xml_fragment(child).sort_key())
        invalid = True

    horizontal = (alignment.get("horizontal") or "general").strip()
    if horizontal not in _ALIGNMENT_HORIZONTAL_VALUES:
        note_issue(f"{context}:invalid-horizontal", alignment.get("horizontal"))
        invalid = True

    vertical = (alignment.get("vertical") or "bottom").strip()
    if vertical not in _ALIGNMENT_VERTICAL_VALUES:
        note_issue(f"{context}:invalid-vertical", alignment.get("vertical"))
        invalid = True

    text_rotation = _number_format_unsigned_int(alignment.get("textRotation"))
    if text_rotation is None:
        if alignment.get("textRotation") is None:
            text_rotation = 0
        else:
            note_issue(
                f"{context}:invalid-text-rotation",
                alignment.get("textRotation"),
            )
            invalid = True
            text_rotation = 0
    elif text_rotation not in _ALIGNMENT_TEXT_ROTATION_VALUES:
        note_issue(
            f"{context}:out-of-range-text-rotation",
            alignment.get("textRotation"),
        )
        invalid = True

    wrap_text = _number_format_boolean(alignment.get("wrapText"), False)
    if wrap_text is None:
        note_issue(f"{context}:invalid-wrap-text", alignment.get("wrapText"))
        invalid = True
        wrap_text = False

    shrink_to_fit = _number_format_boolean(alignment.get("shrinkToFit"), False)
    if shrink_to_fit is None:
        note_issue(
            f"{context}:invalid-shrink-to-fit",
            alignment.get("shrinkToFit"),
        )
        invalid = True
        shrink_to_fit = False

    indent = _number_format_unsigned_int(alignment.get("indent"))
    if indent is None:
        if alignment.get("indent") is None:
            indent = 0
        else:
            note_issue(f"{context}:invalid-indent", alignment.get("indent"))
            invalid = True
            indent = 0
    elif indent > _ALIGNMENT_INDENT_MAXIMUM:
        note_issue(f"{context}:out-of-range-indent", alignment.get("indent"))
        invalid = True

    relative_indent = _alignment_signed_int32(alignment.get("relativeIndent"))
    if relative_indent is None:
        if alignment.get("relativeIndent") is None:
            relative_indent = 0
        else:
            note_issue(
                f"{context}:invalid-relative-indent",
                alignment.get("relativeIndent"),
            )
            invalid = True
            relative_indent = 0

    justify_last_line = _number_format_boolean(
        alignment.get("justifyLastLine"),
        False,
    )
    if justify_last_line is None:
        note_issue(
            f"{context}:invalid-justify-last-line",
            alignment.get("justifyLastLine"),
        )
        invalid = True
        justify_last_line = False

    reading_order = _number_format_unsigned_int(alignment.get("readingOrder"))
    if reading_order is None:
        if alignment.get("readingOrder") is None:
            reading_order = 0
        else:
            note_issue(
                f"{context}:invalid-reading-order",
                alignment.get("readingOrder"),
            )
            invalid = True
            reading_order = 0
    elif reading_order not in _ALIGNMENT_READING_ORDER_VALUES:
        note_issue(
            f"{context}:out-of-range-reading-order",
            alignment.get("readingOrder"),
        )
        invalid = True

    # mergeCell is specified as an unused, non-interoperable compatibility
    # flag. Validate its spelling for coverage, but omit it from effective
    # visual semantics so inert writer noise cannot produce a finding.
    merge_cell = _number_format_boolean(alignment.get("mergeCell"), False)
    if merge_cell is None:
        note_issue(f"{context}:invalid-merge-cell", alignment.get("mergeCell"))
        invalid = True

    definition = tuple(
        entry
        for entry in (
            ("horizontal", horizontal) if horizontal != "general" else None,
            ("vertical", vertical) if vertical != "bottom" else None,
            (
                ("textRotation", str(text_rotation))
                if text_rotation != 0
                else None
            ),
            ("wrapText", "true") if wrap_text else None,
            ("shrinkToFit", "true") if shrink_to_fit else None,
            ("indent", str(indent)) if indent != 0 else None,
            (
                ("relativeIndent", str(relative_indent))
                if relative_indent != 0
                else None
            ),
            ("justifyLastLine", "true") if justify_last_line else None,
            ("readingOrder", str(reading_order)) if reading_order != 0 else None,
        )
        if entry is not None
    )
    if invalid:
        return _alignment_unrecognized(
            "alignment-definition",
            context,
            raw_attributes,
            definition,
            opaque_children,
        )
    if not definition:
        return _DEFAULT_ALIGNMENT_STYLE
    return _AlignmentStyle("alignment", _alignment_private_digest(definition))


def _alignment_column_state_signature(
    states: list[_AlignmentStyle],
    default: _AlignmentStyle,
) -> tuple[tuple[int, int, str, str], ...]:
    """Compress effective alignments so equivalent range splitting stays quiet."""
    segments: list[tuple[int, int, str, str]] = []
    start: int | None = None
    previous: _AlignmentStyle | None = None
    for column in range(1, MAX_EXCEL_COLUMN + 1):
        current = states[column]
        if current == default:
            if start is not None and previous is not None:
                segments.append((start, column - 1, previous.category, previous.value))
            start = None
            previous = None
            continue
        if start is None:
            start = column
            previous = current
            continue
        if current != previous:
            segments.append((start, column - 1, previous.category, previous.value))
            start = column
            previous = current
    if start is not None and previous is not None:
        segments.append((start, MAX_EXCEL_COLUMN, previous.category, previous.value))
    return tuple(segments)


def _alignment_metadata(path: Path) -> _AlignmentMetadata:
    """Inspect effective cell, row, and column alignment from raw OOXML.

    Alignment can reposition, rotate, wrap, indent, or shrink visible content
    without changing a stored value. The scanner resolves xf inheritance and
    applyAlignment before retaining a private signature. Alignment definitions,
    style IDs, and target locations never leave this process.
    """
    warnings: set[str] = set()
    default_snapshot = AlignmentSnapshot()
    entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    default_alignment_definition_count = 0
    cell_alignment_assignment_count = 0
    row_alignment_assignment_count = 0
    column_alignment_assignment_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            try:
                styles = _xml_root(archive, "xl/styles.xml")
            except KeyError:
                styles = None
            if styles is not None and (
                _xml_namespace(styles.tag) != _SPREADSHEETML_NS
                or _xml_local_name(styles.tag) != "styleSheet"
            ):
                note_issue("style-sheet-root", styles.tag)
                styles = None

            def parse_style_index(value: str | None, *, context: str) -> int | None:
                if value is None:
                    return None
                parsed = _number_format_unsigned_int(value)
                if parsed is None:
                    note_issue(f"{context}:invalid-style-index", value)
                return parsed

            base_xfs: list[_AlignmentStyle] = []
            effective_xfs: list[_AlignmentStyle] = []
            if styles is not None:
                xf_tag = f"{{{_SPREADSHEETML_NS}}}xf"
                alignment_tag = f"{{{_SPREADSHEETML_NS}}}alignment"

                def resolve_xf(
                    xf: ElementTree.Element,
                    inherited: _AlignmentStyle,
                    *,
                    context: str,
                ) -> _AlignmentStyle:
                    applies = _number_format_boolean(xf.get("applyAlignment"), True)
                    if applies is None:
                        note_issue(
                            f"{context}:invalid-apply-alignment",
                            xf.get("applyAlignment"),
                        )
                        return _alignment_unrecognized(
                            "invalid-apply-alignment",
                            context,
                            xf.get("applyAlignment"),
                        )
                    foreign_alignments = [
                        child
                        for child in xf
                        if (
                            _xml_local_name(child.tag) == "alignment"
                            and child.tag != alignment_tag
                        )
                    ]
                    if foreign_alignments:
                        note_issue(
                            f"{context}:unsupported-alignment-child",
                            tuple(child.tag for child in foreign_alignments),
                        )
                        return _alignment_unrecognized(
                            "unsupported-alignment-child",
                            context,
                            tuple(
                                _xml_fragment(child).sort_key()
                                for child in foreign_alignments
                            ),
                        )
                    alignments = [
                        child for child in xf if child.tag == alignment_tag
                    ]
                    if len(alignments) > 1:
                        note_issue(
                            f"{context}:multiple-alignment-children",
                            len(alignments),
                        )
                        return _alignment_unrecognized(
                            "multiple-alignment-children",
                            context,
                            tuple(
                                _xml_fragment(child).sort_key() for child in alignments
                            ),
                        )
                    if not applies or not alignments:
                        return inherited
                    return _alignment_definition_style(
                        alignments[0],
                        context=f"{context}:alignment",
                        note_issue=note_issue,
                    )

                cell_style_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellStyleXfs"
                cell_xfs_tag = f"{{{_SPREADSHEETML_NS}}}cellXfs"
                base_containers = styles.findall(cell_style_xfs_tag)
                if len(base_containers) > 1:
                    note_issue("multiple-cell-style-xf-containers", len(base_containers))
                for container_index, container in enumerate(base_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"base-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        base_xfs.append(
                            resolve_xf(
                                xf,
                                _DEFAULT_ALIGNMENT_STYLE,
                                context=f"base-xf:{container_index}:{index}",
                            )
                        )
                if not base_xfs:
                    base_xfs.append(_DEFAULT_ALIGNMENT_STYLE)

                cell_containers = styles.findall(cell_xfs_tag)
                if len(cell_containers) > 1:
                    note_issue("multiple-cell-xf-containers", len(cell_containers))
                for container_index, container in enumerate(cell_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"cell-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        xf_id_value = xf.get("xfId")
                        inherited = _DEFAULT_ALIGNMENT_STYLE
                        if xf_id_value is not None:
                            xf_id = parse_style_index(
                                xf_id_value,
                                context=f"cell-xf:{container_index}:{index}:base",
                            )
                            if xf_id is None or xf_id >= len(base_xfs):
                                note_issue(
                                    f"cell-xf:{container_index}:{index}:unknown-base-style",
                                    xf_id_value,
                                )
                                inherited = _alignment_unrecognized(
                                    "unknown-alignment-base-style",
                                    container_index,
                                    index,
                                    xf_id_value,
                                )
                            else:
                                inherited = base_xfs[xf_id]
                        effective_xfs.append(
                            resolve_xf(
                                xf,
                                inherited,
                                context=f"cell-xf:{container_index}:{index}",
                            )
                        )
            if not effective_xfs:
                effective_xfs.append(_DEFAULT_ALIGNMENT_STYLE)

            default_style = effective_xfs[0]

            def style_for_assignment(
                value: str | None,
                *,
                context: str,
            ) -> _AlignmentStyle | None:
                index = parse_style_index(value, context=context)
                if value is None:
                    return None
                if index is None or index >= len(effective_xfs):
                    note_issue(f"{context}:unknown-style", value)
                    return _alignment_unrecognized(
                        "unknown-alignment-style",
                        context,
                        value,
                    )
                return effective_xfs[index]

            if default_style != _DEFAULT_ALIGNMENT_STYLE:
                default_alignment_definition_count = 1
                entries.append(("default-alignment", repr(default_style)))

            cols_tag = f"{{{_SPREADSHEETML_NS}}}cols"
            col_tag = f"{{{_SPREADSHEETML_NS}}}col"
            sheet_data_tag = f"{{{_SPREADSHEETML_NS}}}sheetData"
            row_tag = f"{{{_SPREADSHEETML_NS}}}row"
            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                column_states = [default_style] * (MAX_EXCEL_COLUMN + 1)
                column_updates = 0
                for columns_index, columns in enumerate(worksheet.findall(cols_tag)):
                    for column_index, column in enumerate(columns):
                        context = (
                            f"column:{sheet.casefold()}:{columns_index}:{column_index}"
                        )
                        if column.tag != col_tag:
                            note_issue(f"{context}:unsupported-child", column.tag)
                            continue
                        if column.get("style") is None:
                            continue
                        minimum = _number_format_unsigned_int(column.get("min"))
                        maximum = _number_format_unsigned_int(column.get("max"))
                        style = style_for_assignment(
                            column.get("style"),
                            context=context,
                        )
                        if (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                            or maximum > MAX_EXCEL_COLUMN
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-column-span",
                                (
                                    column.get("min"),
                                    column.get("max"),
                                    column.get("style"),
                                ),
                            )
                            continue
                        span = maximum - minimum + 1
                        if column_updates + span > _ALIGNMENT_COLUMN_UPDATE_BUDGET:
                            note_issue(f"{context}:column-update-budget", span)
                            continue
                        column_states[minimum : maximum + 1] = [style] * span
                        column_updates += span

                column_signature = _alignment_column_state_signature(
                    column_states,
                    default_style,
                )
                if column_signature:
                    entries.append(
                        (
                            f"column-alignments:{sheet.casefold()}",
                            repr(column_signature),
                        )
                    )
                    column_alignment_assignment_count += sum(
                        maximum - minimum + 1
                        for minimum, maximum, _category, _value in column_signature
                    )

                raw_rows: list[tuple[int, _AlignmentStyle]] = []
                for sheet_data_index, sheet_data in enumerate(
                    worksheet.findall(sheet_data_tag)
                ):
                    for row_index, row in enumerate(sheet_data):
                        context = (
                            f"row:{sheet.casefold()}:{sheet_data_index}:{row_index}"
                        )
                        if row.tag != row_tag:
                            continue
                        custom_format = _number_format_boolean(
                            row.get("customFormat"),
                            False,
                        )
                        if custom_format is None:
                            note_issue(
                                f"{context}:invalid-custom-format",
                                row.get("customFormat"),
                            )
                            continue
                        if not custom_format:
                            continue
                        row_number = _number_format_unsigned_int(row.get("r"))
                        style = style_for_assignment(row.get("s"), context=context)
                        if (
                            row_number is None
                            or row_number < 1
                            or row_number > MAX_EXCEL_ROW
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-row-assignment",
                                (row.get("r"), row.get("s")),
                            )
                            continue
                        raw_rows.append((row_number, style))

                relevant_rows = {
                    row_number
                    for row_number, style in raw_rows
                    if style != default_style
                }
                has_relevant_columns = bool(column_signature)
                for row_number, style in raw_rows:
                    if style == default_style and not has_relevant_columns:
                        continue
                    entries.append(
                        (
                            f"row-alignment:{sheet.casefold()}:{row_number}",
                            repr(style),
                        )
                    )
                    row_alignment_assignment_count += 1

                seen_cells: set[str] = set()
                for cell in worksheet.iter(cell_tag):
                    if cell.get("s") is None:
                        continue
                    context = f"cell:{sheet.casefold()}"
                    coordinate = cell.get("r")
                    style = style_for_assignment(cell.get("s"), context=context)
                    match = (
                        re.fullmatch(r"([A-Za-z]+)([1-9][0-9]*)", coordinate)
                        if coordinate is not None
                        else None
                    )
                    if style is None or match is None:
                        note_issue(
                            f"{context}:invalid-cell-assignment",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    column_letters, raw_row_number = match.groups()
                    try:
                        column_number = (
                            column_index_from_string(column_letters)
                            if len(column_letters) <= 3
                            else 0
                        )
                    except ValueError:
                        column_number = 0
                    row_number = _number_format_unsigned_int(raw_row_number)
                    if row_number is None:
                        note_issue(
                            f"{context}:invalid-cell-row",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    if (
                        column_number < 1
                        or column_number > MAX_EXCEL_COLUMN
                        or row_number > MAX_EXCEL_ROW
                    ):
                        note_issue(
                            f"{context}:out-of-bounds-cell",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    canonical_coordinate = coordinate.upper()
                    if canonical_coordinate in seen_cells:
                        note_issue(
                            f"{context}:duplicate-cell",
                            (canonical_coordinate, cell.get("s")),
                        )
                    seen_cells.add(canonical_coordinate)
                    if (
                        style == default_style
                        and row_number not in relevant_rows
                        and column_states[column_number] == default_style
                    ):
                        continue
                    entries.append(
                        (
                            f"cell-alignment:{sheet.casefold()}:{canonical_coordinate}",
                            repr(style),
                        )
                    )
                    cell_alignment_assignment_count += 1
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _AlignmentMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect cell-alignment OOXML "
                f"({type(error).__name__}); affected display controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported cell-alignment metadata; "
            "affected display controls have a coverage gap."
        )
        entries.extend(
            (f"alignment-issue:{context}", detail)
            for context, detail in sorted(issues.items())
        )
    snapshot = AlignmentSnapshot(
        default_alignment_definition_count=default_alignment_definition_count,
        cell_alignment_assignment_count=cell_alignment_assignment_count,
        row_alignment_assignment_count=row_alignment_assignment_count,
        column_alignment_assignment_count=column_alignment_assignment_count,
        unrecognized_alignment_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
    )
    return _AlignmentMetadata(snapshot, tuple(sorted(warnings)))


_BORDER_COLUMN_UPDATE_BUDGET = 16_777_216
_BORDER_SIDE_NAMES = (
    "start",
    "end",
    "left",
    "right",
    "top",
    "bottom",
    "diagonal",
    "vertical",
    "horizontal",
)
_BORDER_STYLE_VALUES = frozenset(
    {
        "none",
        "thin",
        "medium",
        "dashed",
        "dotted",
        "thick",
        "double",
        "hair",
        "mediumDashed",
        "dashDot",
        "mediumDashDot",
        "dashDotDot",
        "mediumDashDotDot",
        "slantDashDot",
    }
)
_BORDER_ATTRIBUTES = frozenset({"diagonalUp", "diagonalDown", "outline"})
_BORDER_EDGE_NAMES = frozenset({"start", "end", "left", "right", "top", "bottom"})
_BORDER_INNER_NAMES = frozenset({"vertical", "horizontal"})


@dataclass(frozen=True)
class _BorderStyle:
    """One effective ordinary cell border retained only for private comparison."""

    category: str
    value: str


_DEFAULT_BORDER_STYLE = _BorderStyle("default", "0")


def _border_private_digest(value: object) -> str:
    """Hash private border material before it can reach an output model."""
    payload = repr(value).encode("utf-8", errors="surrogatepass")
    return hashlib.sha256(payload).hexdigest()


def _border_unrecognized(*parts: object) -> _BorderStyle:
    """Fingerprint unsupported border material without public retention."""
    return _BorderStyle("unrecognized", _border_private_digest(parts))


def _border_side_signature(
    side: ElementTree.Element,
    *,
    name: str,
    namespace: str,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[object, ...] | None, bool]:
    """Canonicalize one border side while retaining colour material privately."""
    invalid = _fill_unexpected_text(side, context=context, note_issue=note_issue)
    if _fill_unexpected_attributes(
        side,
        allowed=frozenset({"style"}),
        context=context,
        note_issue=note_issue,
    ):
        invalid = True

    raw_style = side.get("style")
    style = raw_style.strip() if raw_style is not None else "none"
    if style not in _BORDER_STYLE_VALUES:
        note_issue(f"{context}:invalid-style", raw_style)
        invalid = True
        style = "none"

    color_tag = f"{{{namespace}}}color"
    colour: tuple[tuple[str, object], ...] | None = None
    for child_index, child in enumerate(side):
        child_context = f"{context}:child:{child_index}"
        if child.tag != color_tag:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            invalid = True
            continue
        if colour is not None:
            note_issue(f"{child_context}:duplicate-colour", child.tag)
            invalid = True
            continue
        colour, colour_invalid = _fill_color_signature(
            child,
            context=child_context,
            note_issue=note_issue,
        )
        if colour_invalid:
            invalid = True

    # A no-border style cannot render a colour. Preserve malformed colour
    # evidence above, but ignore otherwise inert valid writer declarations.
    if style == "none":
        return None, invalid
    return (name, style, colour or None), invalid


def _border_definition_style(
    border: ElementTree.Element,
    *,
    namespace: str,
    context: str,
    note_issue: Callable[[str, object], None],
) -> _BorderStyle:
    """Canonicalize one reusable ``border`` record without exposing its values."""
    invalid = _fill_unexpected_text(border, context=context, note_issue=note_issue)
    raw_attributes = tuple(
        sorted(
            (_xml_display_name(attribute), value)
            for attribute, value in border.attrib.items()
        )
    )
    for attribute, value in border.attrib.items():
        local_name = _xml_local_name(attribute)
        if _xml_namespace(attribute) is not None or local_name not in _BORDER_ATTRIBUTES:
            note_issue(
                f"{context}:unsupported-attribute",
                (_xml_display_name(attribute), value),
            )
            invalid = True

    diagonal_up = _number_format_boolean(border.get("diagonalUp"), False)
    if diagonal_up is None:
        note_issue(f"{context}:invalid-diagonal-up", border.get("diagonalUp"))
        invalid = True
        diagonal_up = False
    diagonal_down = _number_format_boolean(border.get("diagonalDown"), False)
    if diagonal_down is None:
        note_issue(f"{context}:invalid-diagonal-down", border.get("diagonalDown"))
        invalid = True
        diagonal_down = False
    outline = _number_format_boolean(border.get("outline"), True)
    if outline is None:
        note_issue(f"{context}:invalid-outline", border.get("outline"))
        invalid = True
        outline = True

    side_tags = {
        name: f"{{{namespace}}}{name}" for name in _BORDER_SIDE_NAMES
    }
    sides: dict[str, tuple[object, ...]] = {}
    opaque_children: list[object] = []
    for child_index, child in enumerate(border):
        child_context = f"{context}:child:{child_index}"
        name = next((key for key, tag in side_tags.items() if child.tag == tag), None)
        if name is None:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        if name in sides:
            note_issue(f"{child_context}:duplicate-side", name)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        signature, side_invalid = _border_side_signature(
            child,
            name=name,
            namespace=namespace,
            context=child_context,
            note_issue=note_issue,
        )
        if side_invalid:
            invalid = True
        if signature is not None:
            if name in _BORDER_INNER_NAMES:
                # The SpreadsheetML schema documents inner borders as
                # differential-format material. They do not have ordinary
                # cellXf rendering semantics, so retain a private coverage
                # warning rather than claiming to model them here.
                note_issue(f"{child_context}:unsupported-inner-border", name)
                invalid = True
            sides[name] = signature

    diagonal = sides.pop("diagonal", None)
    if diagonal is not None and not (diagonal_up or diagonal_down):
        diagonal = None
    edge_sides = [
        (name, sides[name])
        for name in _BORDER_SIDE_NAMES
        if name in _BORDER_EDGE_NAMES and name in sides
    ]
    ordinary_sides = [
        (name, sides[name])
        for name in _BORDER_SIDE_NAMES
        if name not in _BORDER_INNER_NAMES and name != "diagonal" and name in sides
    ]
    definition_entries: list[object] = [*ordinary_sides]
    if diagonal is not None:
        definition_entries.append(
            ("diagonal", diagonal, diagonal_up, diagonal_down)
        )
    # Outline has no effect unless one of the ordinary edge borders exists.
    if not outline and edge_sides:
        definition_entries.append(("outline", False))
    definition = tuple(definition_entries)
    if invalid:
        return _border_unrecognized(
            "border-definition",
            context,
            raw_attributes,
            definition,
            opaque_children,
        )
    if not definition:
        return _DEFAULT_BORDER_STYLE
    return _BorderStyle("border", _border_private_digest(definition))


def _border_column_state_signature(
    states: list[_BorderStyle],
    default: _BorderStyle,
) -> tuple[tuple[int, int, str, str], ...]:
    """Compress effective borders so equivalent range splitting stays quiet."""
    segments: list[tuple[int, int, str, str]] = []
    start: int | None = None
    previous: _BorderStyle | None = None
    for column in range(1, MAX_EXCEL_COLUMN + 1):
        current = states[column]
        if current == default:
            if start is not None and previous is not None:
                segments.append((start, column - 1, previous.category, previous.value))
            start = None
            previous = None
            continue
        if start is None:
            start = column
            previous = current
            continue
        if current != previous:
            segments.append((start, column - 1, previous.category, previous.value))
            start = column
            previous = current
    if start is not None and previous is not None:
        segments.append((start, MAX_EXCEL_COLUMN, previous.category, previous.value))
    return tuple(segments)


def _border_metadata(path: Path) -> _BorderMetadata:
    """Inspect effective ordinary cell borders directly from raw OOXML.

    Borders can alter report grouping, totals, warnings, and printed output
    without touching a value. The scanner resolves reusable border records,
    ``xfId`` inheritance, and ``applyBorder`` before retaining a private
    signature. Border definitions, style indexes, and target locations never
    leave this process.
    """
    warnings: set[str] = set()
    default_snapshot = BorderSnapshot()
    entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    default_border_definition_count = 0
    cell_border_assignment_count = 0
    row_border_assignment_count = 0
    column_border_assignment_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            try:
                styles = _xml_root(archive, "xl/styles.xml")
            except KeyError:
                styles = None
            styles_namespace = _SPREADSHEETML_NS
            if styles is not None:
                namespace = _xml_namespace(styles.tag)
                if (
                    namespace not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                    or _xml_local_name(styles.tag) != "styleSheet"
                ):
                    note_issue("style-sheet-root", styles.tag)
                    styles = None
                else:
                    styles_namespace = namespace

            borders: list[_BorderStyle] = []
            if styles is not None:
                borders_tag = f"{{{styles_namespace}}}borders"
                border_tag = f"{{{styles_namespace}}}border"
                containers = styles.findall(borders_tag)
                if len(containers) > 1:
                    note_issue("multiple-border-containers", len(containers))
                for container_index, container in enumerate(containers):
                    for border_index, border in enumerate(container):
                        context = f"border:{container_index}:{border_index}"
                        if border.tag != border_tag:
                            note_issue(f"{context}:unsupported-child", border.tag)
                            continue
                        borders.append(
                            _border_definition_style(
                                border,
                                namespace=styles_namespace,
                                context=context,
                                note_issue=note_issue,
                            )
                        )

            def resolve_border(identifier: int, *, context: str) -> _BorderStyle:
                if 0 <= identifier < len(borders):
                    return borders[identifier]
                note_issue(f"{context}:unknown-border", identifier)
                return _border_unrecognized("unknown-border", context, identifier)

            def parse_style_index(value: str | None, *, context: str) -> int | None:
                if value is None:
                    return None
                parsed = _number_format_unsigned_int(value)
                if parsed is None:
                    note_issue(f"{context}:invalid-style-index", value)
                return parsed

            def resolve_xf(
                xf: ElementTree.Element,
                inherited: _BorderStyle,
                *,
                context: str,
            ) -> _BorderStyle:
                applies = _number_format_boolean(xf.get("applyBorder"), True)
                if applies is None:
                    note_issue(
                        f"{context}:invalid-apply-border",
                        xf.get("applyBorder"),
                    )
                    return _border_unrecognized(
                        "invalid-apply-border",
                        context,
                        xf.get("applyBorder"),
                    )
                identifier_value = xf.get("borderId")
                if not applies or identifier_value is None:
                    return inherited
                identifier = _number_format_unsigned_int(identifier_value)
                if identifier is None:
                    note_issue(f"{context}:invalid-border-id", identifier_value)
                    return _border_unrecognized(
                        "invalid-border-id", context, identifier_value
                    )
                return resolve_border(identifier, context=context)

            base_xfs: list[_BorderStyle] = []
            effective_xfs: list[_BorderStyle] = []
            if styles is not None:
                xf_tag = f"{{{styles_namespace}}}xf"
                cell_style_xfs_tag = f"{{{styles_namespace}}}cellStyleXfs"
                cell_xfs_tag = f"{{{styles_namespace}}}cellXfs"
                base_containers = styles.findall(cell_style_xfs_tag)
                if len(base_containers) > 1:
                    note_issue("multiple-cell-style-xf-containers", len(base_containers))
                for container_index, container in enumerate(base_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"base-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        base_xfs.append(
                            resolve_xf(
                                xf,
                                _DEFAULT_BORDER_STYLE,
                                context=f"base-xf:{container_index}:{index}",
                            )
                        )
                if not base_xfs:
                    base_xfs.append(_DEFAULT_BORDER_STYLE)

                cell_containers = styles.findall(cell_xfs_tag)
                if len(cell_containers) > 1:
                    note_issue("multiple-cell-xf-containers", len(cell_containers))
                for container_index, container in enumerate(cell_containers):
                    for index, xf in enumerate(container):
                        if xf.tag != xf_tag:
                            note_issue(
                                f"cell-xf:{container_index}:{index}:unsupported-child",
                                xf.tag,
                            )
                            continue
                        xf_id_value = xf.get("xfId")
                        inherited = _DEFAULT_BORDER_STYLE
                        if xf_id_value is not None:
                            xf_id = parse_style_index(
                                xf_id_value,
                                context=f"cell-xf:{container_index}:{index}:base",
                            )
                            if xf_id is None or xf_id >= len(base_xfs):
                                note_issue(
                                    f"cell-xf:{container_index}:{index}:unknown-base-style",
                                    xf_id_value,
                                )
                                inherited = _border_unrecognized(
                                    "unknown-border-base-style",
                                    container_index,
                                    index,
                                    xf_id_value,
                                )
                            else:
                                inherited = base_xfs[xf_id]
                        effective_xfs.append(
                            resolve_xf(
                                xf,
                                inherited,
                                context=f"cell-xf:{container_index}:{index}",
                            )
                        )
            if not effective_xfs:
                effective_xfs.append(_DEFAULT_BORDER_STYLE)

            default_style = effective_xfs[0]

            def style_for_assignment(
                value: str | None,
                *,
                context: str,
            ) -> _BorderStyle | None:
                index = parse_style_index(value, context=context)
                if value is None:
                    return None
                if index is None or index >= len(effective_xfs):
                    note_issue(f"{context}:unknown-style", value)
                    return _border_unrecognized("unknown-border-style", context, value)
                return effective_xfs[index]

            if default_style != _DEFAULT_BORDER_STYLE:
                default_border_definition_count = 1
                entries.append(("default-border", repr(default_style)))

            for sheet, member in _visual_worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                worksheet_namespace = _xml_namespace(worksheet.tag)
                if (
                    worksheet_namespace
                    not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    note_issue(
                        f"worksheet:{sheet.casefold()}:root",
                        worksheet.tag,
                    )
                    continue
                cols_tag = f"{{{worksheet_namespace}}}cols"
                col_tag = f"{{{worksheet_namespace}}}col"
                sheet_data_tag = f"{{{worksheet_namespace}}}sheetData"
                row_tag = f"{{{worksheet_namespace}}}row"
                cell_tag = f"{{{worksheet_namespace}}}c"
                column_states = [default_style] * (MAX_EXCEL_COLUMN + 1)
                column_updates = 0
                for columns_index, columns in enumerate(worksheet.findall(cols_tag)):
                    for column_index, column in enumerate(columns):
                        context = (
                            f"column:{sheet.casefold()}:{columns_index}:{column_index}"
                        )
                        if column.tag != col_tag:
                            note_issue(f"{context}:unsupported-child", column.tag)
                            continue
                        if column.get("style") is None:
                            continue
                        minimum = _number_format_unsigned_int(column.get("min"))
                        maximum = _number_format_unsigned_int(column.get("max"))
                        style = style_for_assignment(
                            column.get("style"),
                            context=context,
                        )
                        if (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                            or maximum > MAX_EXCEL_COLUMN
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-column-span",
                                (
                                    column.get("min"),
                                    column.get("max"),
                                    column.get("style"),
                                ),
                            )
                            continue
                        span = maximum - minimum + 1
                        if column_updates + span > _BORDER_COLUMN_UPDATE_BUDGET:
                            note_issue(f"{context}:column-update-budget", span)
                            continue
                        column_states[minimum : maximum + 1] = [style] * span
                        column_updates += span

                column_signature = _border_column_state_signature(
                    column_states,
                    default_style,
                )
                if column_signature:
                    entries.append(
                        (
                            f"column-borders:{sheet.casefold()}",
                            repr(column_signature),
                        )
                    )
                    column_border_assignment_count += sum(
                        maximum - minimum + 1
                        for minimum, maximum, _category, _value in column_signature
                    )

                raw_rows: list[tuple[int, _BorderStyle]] = []
                for sheet_data_index, sheet_data in enumerate(
                    worksheet.findall(sheet_data_tag)
                ):
                    for row_index, row in enumerate(sheet_data):
                        context = (
                            f"row:{sheet.casefold()}:{sheet_data_index}:{row_index}"
                        )
                        if row.tag != row_tag:
                            continue
                        custom_format = _number_format_boolean(
                            row.get("customFormat"),
                            False,
                        )
                        if custom_format is None:
                            note_issue(
                                f"{context}:invalid-custom-format",
                                row.get("customFormat"),
                            )
                            continue
                        if not custom_format:
                            continue
                        row_number = _number_format_unsigned_int(row.get("r"))
                        style = style_for_assignment(row.get("s"), context=context)
                        if (
                            row_number is None
                            or row_number < 1
                            or row_number > MAX_EXCEL_ROW
                            or style is None
                        ):
                            note_issue(
                                f"{context}:invalid-row-assignment",
                                (row.get("r"), row.get("s")),
                            )
                            continue
                        raw_rows.append((row_number, style))

                relevant_rows = {
                    row_number
                    for row_number, style in raw_rows
                    if style != default_style
                }
                has_relevant_columns = bool(column_signature)
                for row_number, style in raw_rows:
                    if style == default_style and not has_relevant_columns:
                        continue
                    entries.append(
                        (
                            f"row-border:{sheet.casefold()}:{row_number}",
                            repr(style),
                        )
                    )
                    row_border_assignment_count += 1

                seen_cells: set[str] = set()
                for cell in worksheet.iter(cell_tag):
                    if cell.get("s") is None:
                        continue
                    context = f"cell:{sheet.casefold()}"
                    coordinate = cell.get("r")
                    style = style_for_assignment(cell.get("s"), context=context)
                    match = (
                        re.fullmatch(r"([A-Za-z]+)([1-9][0-9]*)", coordinate)
                        if coordinate is not None
                        else None
                    )
                    if style is None or match is None:
                        note_issue(
                            f"{context}:invalid-cell-assignment",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    column_letters, raw_row_number = match.groups()
                    try:
                        column_number = (
                            column_index_from_string(column_letters)
                            if len(column_letters) <= 3
                            else 0
                        )
                    except ValueError:
                        column_number = 0
                    row_number = _number_format_unsigned_int(raw_row_number)
                    if row_number is None:
                        note_issue(
                            f"{context}:invalid-cell-row",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    if (
                        column_number < 1
                        or column_number > MAX_EXCEL_COLUMN
                        or row_number > MAX_EXCEL_ROW
                    ):
                        note_issue(
                            f"{context}:out-of-bounds-cell",
                            (coordinate, cell.get("s")),
                        )
                        continue
                    canonical_coordinate = coordinate.upper()
                    if canonical_coordinate in seen_cells:
                        note_issue(
                            f"{context}:duplicate-cell",
                            (canonical_coordinate, cell.get("s")),
                        )
                    seen_cells.add(canonical_coordinate)
                    if (
                        style == default_style
                        and row_number not in relevant_rows
                        and column_states[column_number] == default_style
                    ):
                        continue
                    entries.append(
                        (
                            f"cell-border:{sheet.casefold()}:{canonical_coordinate}",
                            repr(style),
                        )
                    )
                    cell_border_assignment_count += 1
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _BorderMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect ordinary cell-border OOXML "
                f"({type(error).__name__}); affected visual controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported ordinary cell-border "
            "metadata; affected visual controls have a coverage gap."
        )
    snapshot = BorderSnapshot(
        default_border_definition_count=default_border_definition_count,
        cell_border_assignment_count=cell_border_assignment_count,
        row_border_assignment_count=row_border_assignment_count,
        column_border_assignment_count=column_border_assignment_count,
        unrecognized_border_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
        unrecognized_signature=(
            _private_external_data_signature(tuple(sorted(issues.items())))
            if issues
            else None
        ),
    )
    return _BorderMetadata(snapshot, tuple(sorted(warnings)))


_WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH = Decimal("255")
_WORKSHEET_DIMENSION_MAX_ROW_HEIGHT = Decimal("409")
_WORKSHEET_DIMENSION_COLUMN_UPDATE_BUDGET = 16_777_216
_WORKSHEET_DIMENSION_DECIMAL_PATTERN = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[Ee][+-]?[0-9]+)?"
)
_WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE = (
    f"{{{_OFFICE_2010_AC_NS}}}dyDescent"
)
_WORKSHEET_DIMENSION_SHEET_FORMAT_ATTRIBUTES = frozenset(
    {
        "baseColWidth",
        "defaultColWidth",
        "defaultRowHeight",
        "customHeight",
        "zeroHeight",
        "thickTop",
        "thickBottom",
        "outlineLevelRow",
        "outlineLevelCol",
    }
)
_WORKSHEET_DIMENSION_ROW_ATTRIBUTES = frozenset(
    {
        "r",
        "spans",
        "s",
        "customFormat",
        "ht",
        "hidden",
        "customHeight",
        "outlineLevel",
        "collapsed",
        "thickTop",
        "thickBot",
        "ph",
    }
)
_WORKSHEET_DIMENSION_COLUMN_ATTRIBUTES = frozenset(
    {
        "min",
        "max",
        "width",
        "style",
        "hidden",
        "bestFit",
        "customWidth",
        "phonetic",
        "outlineLevel",
        "collapsed",
    }
)


def _worksheet_dimension_decimal(
    value: str | None,
    *,
    maximum: Decimal | None,
    minimum: Decimal | None = Decimal("0"),
) -> str | None:
    """Normalize one finite SpreadsheetML dimension privately."""
    if value is None:
        return None
    candidate = value.strip()
    if not _WORKSHEET_DIMENSION_DECIMAL_PATTERN.fullmatch(candidate):
        return None
    try:
        parsed = Decimal(candidate)
    except (InvalidOperation, ValueError):
        return None
    if (
        not parsed.is_finite()
        or (minimum is not None and parsed < minimum)
        or (maximum is not None and parsed > maximum)
    ):
        return None
    if parsed == 0:
        return "0"
    return format(parsed.normalize(), "f")


def _worksheet_dimension_unsigned_int(
    value: str | None,
    *,
    maximum: int,
) -> int | None:
    """Read one bounded unsigned integer without retaining malformed text."""
    parsed = _number_format_unsigned_int(value)
    if parsed is None or parsed > maximum:
        return None
    return parsed


def _worksheet_dimension_unexpected_attributes(
    element: ElementTree.Element,
    *,
    known: frozenset[str],
    allowed_namespaced: frozenset[tuple[str, str]] = frozenset(),
    context: str,
    note_issue: Callable[[str, object], None],
) -> None:
    """Record unsupported raw metadata without letting it leave the scanner."""
    for attribute, value in element.attrib.items():
        namespace = _xml_namespace(attribute)
        local_name = _xml_local_name(attribute)
        if (
            (namespace is not None and (namespace, local_name) not in allowed_namespaced)
            or (namespace is None and local_name not in known)
        ):
            note_issue(
                f"{context}:unsupported-attribute",
                (_xml_display_name(attribute), value),
            )


def _worksheet_dimension_column_state_signature(
    states: list[tuple[str | None, bool]],
) -> tuple[tuple[int, int, str | None, bool], ...]:
    """Compress layered effective columns so range splitting stays quiet."""
    segments: list[tuple[int, int, str | None, bool]] = []
    start: int | None = None
    previous: tuple[str | None, bool] | None = None
    for column in range(1, MAX_EXCEL_COLUMN + 1):
        current = states[column]
        if current == (None, False):
            if start is not None and previous is not None:
                segments.append((start, column - 1, *previous))
            start = None
            previous = None
            continue
        if start is None:
            start = column
            previous = current
            continue
        if current != previous:
            segments.append((start, column - 1, *previous))
            start = column
            previous = current
    if start is not None and previous is not None:
        segments.append((start, MAX_EXCEL_COLUMN, *previous))
    return tuple(segments)


def _worksheet_dimension_metadata(path: Path) -> _WorksheetDimensionMetadata:
    """Inspect material worksheet dimensions directly from raw SpreadsheetML.

    Height and width values, row/column targets, and writer metadata remain in
    private canonical signatures. The public snapshot only counts the kinds of
    sizing controls present. Zero and hidden dimensions stay in FF036's
    visibility boundary; this scanner covers ordinary positive sizing, AutoFit,
    Office 2010 baseline adjustments, and automatic border-driven row-height
    adjustments.
    """
    warnings: set[str] = set()
    default_snapshot = WorksheetDimensionSnapshot()
    entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    default_row_height_count = 0
    default_column_width_count = 0
    default_baseline_adjustment_sheet_count = 0
    default_border_adjustment_sheet_count = 0
    row_height_assignment_count = 0
    row_baseline_adjustment_count = 0
    row_border_adjustment_count = 0
    column_width_assignment_count = 0
    best_fit_column_assignment_count = 0
    column_update_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    def boolean_attribute(
        element: ElementTree.Element,
        name: str,
        *,
        default: bool,
        context: str,
    ) -> bool | None:
        parsed = _number_format_boolean(element.get(name), default)
        if name in element.attrib and parsed is None:
            note_issue(f"{context}:invalid-{name}", element.get(name))
        return parsed

    try:
        with ZipFile(path) as archive:
            for sheet, member in _visual_worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                worksheet_namespace = _xml_namespace(worksheet.tag)
                sheet_key = sheet.casefold()
                if (
                    worksheet_namespace
                    not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    note_issue(f"worksheet:{sheet_key}:root", worksheet.tag)
                    continue

                sheet_format_tag = f"{{{worksheet_namespace}}}sheetFormatPr"
                cols_tag = f"{{{worksheet_namespace}}}cols"
                col_tag = f"{{{worksheet_namespace}}}col"
                sheet_data_tag = f"{{{worksheet_namespace}}}sheetData"
                row_tag = f"{{{worksheet_namespace}}}row"
                sheet_formats = worksheet.findall(sheet_format_tag)
                if len(sheet_formats) > 1:
                    note_issue(
                        f"sheet-format:{sheet_key}:multiple",
                        len(sheet_formats),
                    )
                if sheet_formats:
                    sheet_format = sheet_formats[0]
                    format_context = f"sheet-format:{sheet_key}"
                    _worksheet_dimension_unexpected_attributes(
                        sheet_format,
                        known=_WORKSHEET_DIMENSION_SHEET_FORMAT_ATTRIBUTES,
                        allowed_namespaced=frozenset(
                            {(_OFFICE_2010_AC_NS, "dyDescent")}
                        ),
                        context=format_context,
                        note_issue=note_issue,
                    )
                    if list(sheet_format):
                        note_issue(
                            f"{format_context}:unexpected-children",
                            len(sheet_format),
                        )
                    if (sheet_format.text or "").strip():
                        note_issue(
                            f"{format_context}:unexpected-text",
                            sheet_format.text,
                        )

                    default_row_height = None
                    if "defaultRowHeight" in sheet_format.attrib:
                        default_row_height = _worksheet_dimension_decimal(
                            sheet_format.get("defaultRowHeight"),
                            maximum=_WORKSHEET_DIMENSION_MAX_ROW_HEIGHT,
                        )
                        if default_row_height is None:
                            note_issue(
                                f"{format_context}:invalid-default-row-height",
                                sheet_format.get("defaultRowHeight"),
                            )
                    default_column_width = None
                    if "defaultColWidth" in sheet_format.attrib:
                        default_column_width = _worksheet_dimension_decimal(
                            sheet_format.get("defaultColWidth"),
                            maximum=_WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH,
                        )
                        if default_column_width is None:
                            note_issue(
                                f"{format_context}:invalid-default-column-width",
                                sheet_format.get("defaultColWidth"),
                            )
                    base_column_width = None
                    if "baseColWidth" in sheet_format.attrib:
                        base_column_width = _worksheet_dimension_unsigned_int(
                            sheet_format.get("baseColWidth"),
                            maximum=int(_WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH),
                        )
                        if base_column_width is None:
                            note_issue(
                                f"{format_context}:invalid-base-column-width",
                                sheet_format.get("baseColWidth"),
                            )
                    dy_descent = None
                    if _WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE in sheet_format.attrib:
                        dy_descent = _worksheet_dimension_decimal(
                            sheet_format.get(_WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE),
                            maximum=None,
                            minimum=None,
                        )
                        if dy_descent is None:
                            note_issue(
                                f"{format_context}:invalid-dy-descent",
                                sheet_format.get(_WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE),
                            )
                    custom_height = boolean_attribute(
                        sheet_format,
                        "customHeight",
                        default=False,
                        context=format_context,
                    )
                    # dyDescent has a documented side effect of making the row
                    # custom-height even if the ordinary Boolean says otherwise.
                    effective_custom_height = (
                        True if dy_descent is not None else custom_height
                    )
                    # A custom-height flag without a corresponding numeric default
                    # or baseline adjustment is not a stable rendered declaration.
                    if (
                        custom_height is True
                        and default_row_height is None
                        and dy_descent is None
                    ):
                        note_issue(
                            f"{format_context}:custom-height-without-default-row-height",
                            "true",
                        )

                    default_row_components: list[tuple[str, object]] = []
                    if default_row_height not in {None, "0"} and (
                        default_row_height != "15"
                        or (
                            effective_custom_height is True
                            and dy_descent is None
                        )
                    ):
                        default_row_components.append(
                            ("height", default_row_height)
                        )
                        default_row_components.append(
                            ("customHeight", effective_custom_height)
                        )
                        default_row_height_count += 1

                    baseline_adjustment_components: list[tuple[str, object]] = []
                    if dy_descent is not None:
                        baseline_adjustment_components.append(
                            ("dyDescent", dy_descent)
                        )
                        default_baseline_adjustment_sheet_count += 1

                    default_column_components: list[tuple[str, object]] = []
                    if (
                        default_column_width is not None
                        and default_column_width != "0"
                    ):
                        default_column_components.append(
                            ("width", default_column_width)
                        )
                    if base_column_width is not None and base_column_width != 8:
                        default_column_components.append(
                            ("baseWidth", base_column_width)
                        )
                    if default_column_components:
                        default_column_width_count += 1

                    # In automatic-height mode, thick top/bottom borders add a
                    # documented vertical adjustment. With a custom height they
                    # are inert and intentionally normalized away.
                    border_adjustment_components: list[tuple[str, object]] = []
                    if (
                        effective_custom_height is False
                        and default_row_height != "0"
                    ):
                        thick_top = boolean_attribute(
                            sheet_format,
                            "thickTop",
                            default=False,
                            context=format_context,
                        )
                        thick_bottom = boolean_attribute(
                            sheet_format,
                            "thickBottom",
                            default=False,
                            context=format_context,
                        )
                        if thick_top or thick_bottom:
                            border_adjustment_components.extend(
                                (
                                    ("thickTop", thick_top),
                                    ("thickBottom", thick_bottom),
                                )
                            )
                            default_border_adjustment_sheet_count += 1

                    sheet_components = (
                        default_row_components
                        + baseline_adjustment_components
                        + default_column_components
                        + border_adjustment_components
                    )
                    if sheet_components:
                        entries.append(
                            (
                                f"default-dimension:{sheet_key}",
                                repr(tuple(sheet_components)),
                            )
                        )

                column_states: list[tuple[str | None, bool]] = [
                    (None, False)
                ] * (MAX_EXCEL_COLUMN + 1)
                column_sets = worksheet.findall(cols_tag)
                if len(column_sets) > 1:
                    note_issue(f"columns:{sheet_key}:multiple", len(column_sets))
                for columns_index, columns in enumerate(column_sets):
                    columns_context = f"columns:{sheet_key}:{columns_index}"
                    if (columns.text or "").strip():
                        note_issue(
                            f"{columns_context}:unexpected-text",
                            columns.text,
                        )
                    for column_index, column in enumerate(columns):
                        context = (
                            f"column:{sheet_key}:{columns_index}:{column_index}"
                        )
                        if column.tag != col_tag:
                            note_issue(f"{context}:unsupported-child", column.tag)
                            continue
                        _worksheet_dimension_unexpected_attributes(
                            column,
                            known=_WORKSHEET_DIMENSION_COLUMN_ATTRIBUTES,
                            context=context,
                            note_issue=note_issue,
                        )
                        if list(column):
                            note_issue(
                                f"{context}:unexpected-children", len(column)
                            )
                        if (column.text or "").strip():
                            note_issue(
                                f"{context}:unexpected-text", column.text
                            )

                        has_width = "width" in column.attrib
                        has_best_fit = "bestFit" in column.attrib
                        has_custom_width = "customWidth" in column.attrib
                        if not (has_width or has_best_fit or has_custom_width):
                            continue
                        minimum = _worksheet_dimension_unsigned_int(
                            column.get("min"), maximum=MAX_EXCEL_COLUMN
                        )
                        maximum = _worksheet_dimension_unsigned_int(
                            column.get("max"), maximum=MAX_EXCEL_COLUMN
                        )
                        if (
                            minimum is None
                            or maximum is None
                            or minimum < 1
                            or maximum < minimum
                        ):
                            note_issue(
                                f"{context}:invalid-column-bounds",
                                (column.get("min"), column.get("max")),
                            )
                            continue

                        width: str | None = None
                        valid_width = False
                        if has_width:
                            parsed_width = _worksheet_dimension_decimal(
                                column.get("width"),
                                maximum=_WORKSHEET_DIMENSION_MAX_COLUMN_WIDTH,
                            )
                            if parsed_width is None:
                                note_issue(
                                    f"{context}:invalid-column-width",
                                    column.get("width"),
                                )
                            else:
                                # Zero-sized columns are FF036 visibility
                                # controls. A later positive declaration can
                                # still override it, so it clears this scanner's
                                # ordinary-width state in XML order.
                                width = (
                                    parsed_width
                                    if parsed_width != "0"
                                    else None
                                )
                                valid_width = True

                        best_fit: bool | None = None
                        if has_best_fit:
                            best_fit = boolean_attribute(
                                column,
                                "bestFit",
                                default=False,
                                context=context,
                            )
                        if has_custom_width:
                            # customWidth is a writer/manual-setting hint, not
                            # an independent current dimension. Validate it but
                            # deliberately omit it from effective state.
                            boolean_attribute(
                                column,
                                "customWidth",
                                default=False,
                                context=context,
                            )

                        update_count = int(valid_width) + int(best_fit is not None)
                        if not update_count:
                            continue
                        span = maximum - minimum + 1
                        if (
                            column_update_count + span * update_count
                            > _WORKSHEET_DIMENSION_COLUMN_UPDATE_BUDGET
                        ):
                            note_issue(
                                f"{context}:column-update-budget",
                                span * update_count,
                            )
                            continue
                        for column_number in range(minimum, maximum + 1):
                            old_width, old_best_fit = column_states[column_number]
                            column_states[column_number] = (
                                width if valid_width else old_width,
                                best_fit if best_fit is not None else old_best_fit,
                            )
                        column_update_count += span * update_count

                column_signature = _worksheet_dimension_column_state_signature(
                    column_states
                )
                if column_signature:
                    entries.append(
                        (
                            f"column-dimensions:{sheet_key}",
                            repr(column_signature),
                        )
                    )
                    column_width_assignment_count += sum(
                        maximum - minimum + 1
                        for minimum, maximum, width, _best_fit in column_signature
                        if width is not None
                    )
                    best_fit_column_assignment_count += sum(
                        maximum - minimum + 1
                        for minimum, maximum, _width, best_fit in column_signature
                        if best_fit
                    )

                seen_rows: set[int] = set()
                for sheet_data_index, sheet_data in enumerate(
                    worksheet.findall(sheet_data_tag)
                ):
                    for row_index, row in enumerate(sheet_data):
                        if row.tag != row_tag:
                            continue
                        relevant = {
                            "ht",
                            "customHeight",
                            "thickTop",
                            "thickBot",
                        }
                        if not (
                            any(attribute in row.attrib for attribute in relevant)
                            or _WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE in row.attrib
                        ):
                            continue
                        context = f"row:{sheet_key}:{sheet_data_index}:{row_index}"
                        _worksheet_dimension_unexpected_attributes(
                            row,
                            known=_WORKSHEET_DIMENSION_ROW_ATTRIBUTES,
                            allowed_namespaced=frozenset(
                                {(_OFFICE_2010_AC_NS, "dyDescent")}
                            ),
                            context=context,
                            note_issue=note_issue,
                        )
                        row_number = _worksheet_dimension_unsigned_int(
                            row.get("r"), maximum=MAX_EXCEL_ROW
                        )
                        if row_number is None or row_number < 1:
                            note_issue(
                                f"{context}:invalid-row-index", row.get("r")
                            )
                            continue
                        if row_number in seen_rows:
                            note_issue(
                                f"{context}:duplicate-row", row_number
                            )
                            continue
                        seen_rows.add(row_number)

                        custom_height = boolean_attribute(
                            row,
                            "customHeight",
                            default=False,
                            context=context,
                        )
                        dy_descent = None
                        if _WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE in row.attrib:
                            dy_descent = _worksheet_dimension_decimal(
                                row.get(_WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE),
                                maximum=None,
                                minimum=None,
                            )
                            if dy_descent is None:
                                note_issue(
                                    f"{context}:invalid-dy-descent",
                                    row.get(
                                        _WORKSHEET_DIMENSION_DY_DESCENT_ATTRIBUTE
                                    ),
                                )
                        effective_custom_height = (
                            True if dy_descent is not None else custom_height
                        )
                        height = None
                        if "ht" in row.attrib:
                            height = _worksheet_dimension_decimal(
                                row.get("ht"),
                                maximum=_WORKSHEET_DIMENSION_MAX_ROW_HEIGHT,
                            )
                            if height is None:
                                note_issue(
                                    f"{context}:invalid-row-height", row.get("ht")
                                )
                        elif custom_height is True and dy_descent is None:
                            note_issue(
                                f"{context}:custom-height-without-height", "true"
                            )

                        row_components: list[tuple[str, object]] = []
                        if height not in {None, "0"}:
                            row_components.extend(
                                (
                                    ("height", height),
                                    ("customHeight", effective_custom_height),
                                )
                            )
                            row_height_assignment_count += 1

                        if dy_descent is not None:
                            row_components.append(("dyDescent", dy_descent))
                            row_baseline_adjustment_count += 1

                        # A fixed custom height supersedes border-driven
                        # adjustment, so normalize any thick flags away there.
                        if effective_custom_height is False and height != "0":
                            thick_top = boolean_attribute(
                                row,
                                "thickTop",
                                default=False,
                                context=context,
                            )
                            thick_bottom = boolean_attribute(
                                row,
                                "thickBot",
                                default=False,
                                context=context,
                            )
                            if thick_top or thick_bottom:
                                row_components.extend(
                                    (
                                        ("thickTop", thick_top),
                                        ("thickBottom", thick_bottom),
                                    )
                                )
                                row_border_adjustment_count += 1
                        if row_components:
                            entries.append(
                                (
                                    f"row-dimension:{sheet_key}:{row_number}",
                                    repr(tuple(row_components)),
                                )
                            )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _WorksheetDimensionMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect material worksheet-dimension OOXML "
                f"({type(error).__name__}); affected visual controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported worksheet-dimension "
            "metadata; affected visual controls have a coverage gap."
        )
    snapshot = WorksheetDimensionSnapshot(
        default_row_height_count=default_row_height_count,
        default_column_width_count=default_column_width_count,
        default_baseline_adjustment_sheet_count=(
            default_baseline_adjustment_sheet_count
        ),
        default_border_adjustment_sheet_count=default_border_adjustment_sheet_count,
        row_height_assignment_count=row_height_assignment_count,
        row_baseline_adjustment_count=row_baseline_adjustment_count,
        row_border_adjustment_count=row_border_adjustment_count,
        column_width_assignment_count=column_width_assignment_count,
        best_fit_column_assignment_count=best_fit_column_assignment_count,
        unrecognized_dimension_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
        unrecognized_signature=(
            _private_external_data_signature(tuple(sorted(issues.items())))
            if issues
            else None
        ),
    )
    return _WorksheetDimensionMetadata(snapshot, tuple(sorted(warnings)))


_WORKSHEET_DISPLAY_SHEET_VIEW_KNOWN_ATTRIBUTES = frozenset(
    {
        "colorId",
        "defaultGridColor",
        "rightToLeft",
        "showFormulas",
        "showGridLines",
        "showOutlineSymbols",
        "showRowColHeaders",
        "showRuler",
        "showWhiteSpace",
        "showZeros",
        "tabSelected",
        "topLeftCell",
        "view",
        "windowProtection",
        "workbookViewId",
        "zoomScale",
        "zoomScaleNormal",
        "zoomScalePageLayoutView",
        "zoomScaleSheetLayoutView",
    }
)
_WORKSHEET_DISPLAY_PANE_KNOWN_ATTRIBUTES = frozenset(
    {"activePane", "state", "topLeftCell", "xSplit", "ySplit"}
)
_WORKSHEET_DISPLAY_IGNORED_CHILDREN = frozenset(
    {"extLst", "pivotSelection", "selection"}
)
_WORKSHEET_DISPLAY_VIEW_VALUES = frozenset(
    {"normal", "pageBreakPreview", "pageLayout"}
)
_WORKSHEET_DISPLAY_PANE_STATES = frozenset(
    {"split", "frozen", "frozenSplit"}
)


def _worksheet_display_decimal(value: str | None) -> str | None:
    """Normalize one finite, non-negative pane split without evaluating it."""
    normalized = _font_decimal(value)
    if normalized is None:
        return None
    try:
        return normalized if Decimal(normalized) >= 0 else None
    except (InvalidOperation, ValueError):
        return None


def _worksheet_display_view_signature(
    view: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[tuple[str, str], ...], frozenset[str]]:
    """Canonicalize material visibility controls in one sheetView element.

    Active-cell, selection, top-left navigation, and zoom state are deliberately
    ignored: writers change them during ordinary navigation and they do not by
    themselves hide stored values. Material defaults are normalized so omitted
    controls and explicit default spellings compare equal.
    """
    signature: list[tuple[str, str]] = []
    active_controls: set[str] = set()
    for attribute, value in sorted(view.attrib.items()):
        local_name = _xml_local_name(attribute)
        if (
            _xml_namespace(attribute)
            or local_name not in _WORKSHEET_DISPLAY_SHEET_VIEW_KNOWN_ATTRIBUTES
        ):
            note_issue(f"{context}:unsupported-attribute:{attribute}", value)
            signature.append(
                (
                    "unsupported-attribute",
                    repr((attribute, value)),
                )
            )

    def material_boolean(name: str, default: bool) -> bool | None:
        parsed = _number_format_boolean(view.get(name), default)
        if parsed is None:
            note_issue(f"{context}:invalid-{name}", view.get(name))
            signature.append((name, repr(("invalid", view.get(name)))))
            return None
        if parsed != default:
            signature.append((name, "true" if parsed else "false"))
            active_controls.add(name)
        return parsed

    material_boolean("showZeros", True)
    material_boolean("showFormulas", False)
    material_boolean("showGridLines", True)
    default_grid_color = material_boolean("defaultGridColor", True)
    if default_grid_color is False:
        raw_color_id = view.get("colorId", "64")
        color_id = _number_format_unsigned_int(raw_color_id)
        if color_id is None:
            note_issue(f"{context}:invalid-colorId", raw_color_id)
            signature.append(("gridline-color", repr(("invalid", raw_color_id))))
        else:
            signature.append(("gridline-color", str(color_id)))
            active_controls.add("gridlineColor")
    elif default_grid_color is None and view.get("colorId") is not None:
        # A malformed default-grid-color declaration leaves the color's effect
        # ambiguous. Retain the otherwise private raw declaration so changes
        # remain detectable alongside the coverage warning.
        raw_color_id = view.get("colorId")
        color_id = _number_format_unsigned_int(raw_color_id)
        signature.append(
            (
                "gridline-color-ambiguous",
                repr(("invalid" if color_id is None else "value", raw_color_id)),
            )
        )
        if color_id is None:
            note_issue(f"{context}:invalid-colorId", raw_color_id)
    material_boolean("showRowColHeaders", True)
    material_boolean("showOutlineSymbols", True)
    material_boolean("showRuler", True)
    material_boolean("showWhiteSpace", True)
    material_boolean("rightToLeft", False)

    view_type = view.get("view", "normal")
    if view_type not in _WORKSHEET_DISPLAY_VIEW_VALUES:
        note_issue(f"{context}:invalid-view", view_type)
        signature.append(("view", repr(("invalid", view_type))))
    elif view_type != "normal":
        signature.append(("view", view_type))
        active_controls.add("view")

    view_namespace = _xml_namespace(view.tag) or _SPREADSHEETML_NS
    pane_tag = f"{{{view_namespace}}}pane"
    panes = [child for child in view if child.tag == pane_tag]
    if len(panes) > 1:
        note_issue(f"{context}:multiple-pane-children", len(panes))
    for child_index, child in enumerate(view):
        if (
            child.tag == pane_tag
            or (
                _xml_namespace(child.tag) == view_namespace
                and _xml_local_name(child.tag) in _WORKSHEET_DISPLAY_IGNORED_CHILDREN
            )
        ):
            continue
        note_issue(f"{context}:unsupported-child:{child_index}", child.tag)
        signature.append(("unsupported-child", repr(_xml_fragment(child).sort_key())))

    for pane_index, pane in enumerate(panes):
        pane_context = f"{context}:pane:{pane_index}"
        for attribute, value in sorted(pane.attrib.items()):
            local_name = _xml_local_name(attribute)
            if (
                _xml_namespace(attribute)
                or local_name not in _WORKSHEET_DISPLAY_PANE_KNOWN_ATTRIBUTES
            ):
                note_issue(f"{pane_context}:unsupported-attribute:{attribute}", value)
                signature.append(
                    (
                        "unsupported-pane-attribute",
                        repr((attribute, value)),
                    )
                )

        state = pane.get("state", "split")
        state_valid = state in _WORKSHEET_DISPLAY_PANE_STATES
        if not state_valid:
            note_issue(f"{pane_context}:invalid-state", state)
            signature.append(("pane-state", repr(("invalid", state))))

        splits: list[tuple[str, str]] = []
        for attribute_name in ("xSplit", "ySplit"):
            raw_value = pane.get(attribute_name)
            if raw_value is None:
                continue
            normalized = _worksheet_display_decimal(raw_value)
            if normalized is None:
                note_issue(
                    f"{pane_context}:invalid-{attribute_name}",
                    raw_value,
                )
                signature.append(
                    (
                        f"pane-{attribute_name}",
                        repr(("invalid", raw_value)),
                    )
                )
                continue
            if normalized != "0":
                splits.append((attribute_name, normalized))

        if state_valid and (state != "split" or splits):
            signature.append(("pane", repr((state, tuple(splits)))))
            active_controls.add("pane")

    return tuple(sorted(signature)), frozenset(active_controls)


def _worksheet_display_metadata(path: Path) -> _WorksheetDisplayMetadata:
    """Inspect raw, material worksheet display controls without reader loss.

    The boundary covers visibility and view-mode declarations that can change a
    reviewer's surface while leaving values and formulas untouched. It excludes
    ordinary navigation state such as active cells, selections, top-left scroll
    positions, and zoom factors to avoid routine writer churn.
    """
    default_snapshot = WorksheetDisplaySnapshot()
    warnings: set[str] = set()
    issues: dict[str, str] = {}
    entries: list[tuple[str, str]] = []
    counts: Counter[str] = Counter()

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            for sheet_index, member in enumerate(_worksheet_display_xml_paths(archive)):
                worksheet = _xml_root(archive, member)
                worksheet_context = f"worksheet:{sheet_index}"
                worksheet_namespace = _xml_namespace(worksheet.tag)
                if (
                    _xml_local_name(worksheet.tag) != "worksheet"
                    or worksheet_namespace
                    not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                ):
                    note_issue(f"{worksheet_context}:unexpected-root", worksheet.tag)
                    continue
                sheet_views_tag = f"{{{worksheet_namespace}}}sheetViews"
                sheet_view_tag = f"{{{worksheet_namespace}}}sheetView"
                containers = worksheet.findall(sheet_views_tag)
                if len(containers) > 1:
                    note_issue(
                        f"{worksheet_context}:multiple-sheet-views-containers",
                        len(containers),
                    )
                for container_index, container in enumerate(containers):
                    context = f"{worksheet_context}:sheet-views:{container_index}"
                    if container.attrib:
                        note_issue(
                            f"{context}:unexpected-attributes",
                            tuple(sorted(container.attrib.items())),
                        )
                    for child_index, child in enumerate(container):
                        if child.tag != sheet_view_tag:
                            note_issue(
                                f"{context}:unsupported-child:{child_index}",
                                child.tag,
                            )
                    for view_index, view in enumerate(
                        child
                        for child in container
                        if child.tag == sheet_view_tag
                    ):
                        view_context = f"{context}:view:{view_index}"
                        signature, active_controls = _worksheet_display_view_signature(
                            view,
                            context=view_context,
                            note_issue=note_issue,
                        )
                        if signature:
                            entries.append(
                                (
                                    (
                                        "worksheet-display:"
                                        f"{sheet_index}:{container_index}:{view_index}"
                                    ),
                                    repr(signature),
                                )
                            )
                        counts.update(active_controls)
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _WorksheetDisplayMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect worksheet-display OOXML "
                f"({type(error).__name__}); affected display controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported worksheet-display metadata; "
            "affected display controls have a coverage gap."
        )
        entries.extend(
            (f"worksheet-display-issue:{context}", detail)
            for context, detail in sorted(issues.items())
        )
    snapshot = WorksheetDisplaySnapshot(
        zero_hidden_view_count=counts["showZeros"],
        formula_view_count=counts["showFormulas"],
        gridlines_hidden_view_count=counts["showGridLines"],
        custom_gridline_color_view_count=counts["gridlineColor"],
        headers_hidden_view_count=counts["showRowColHeaders"],
        outline_symbols_hidden_view_count=counts["showOutlineSymbols"],
        ruler_hidden_view_count=counts["showRuler"],
        white_space_hidden_view_count=counts["showWhiteSpace"],
        right_to_left_view_count=counts["rightToLeft"],
        non_normal_view_count=counts["view"],
        split_or_frozen_pane_count=counts["pane"],
        unrecognized_display_control_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
    )
    return _WorksheetDisplayMetadata(snapshot, tuple(sorted(warnings)))


_WORKSHEET_PRINT_LAYOUT_PRINT_OPTIONS_ATTRIBUTES = frozenset(
    {
        "gridLines",
        "gridLinesSet",
        "headings",
        "horizontalCentered",
        "verticalCentered",
    }
)
_WORKSHEET_PRINT_LAYOUT_PAGE_MARGIN_ATTRIBUTES = frozenset(
    {"bottom", "footer", "header", "left", "right", "top"}
)
_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_BOOLEAN_DEFAULTS = {
    "blackAndWhite": False,
    "draft": False,
    "useFirstPageNumber": False,
    "usePrinterDefaults": True,
}
_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_UNSIGNED_DEFAULTS = {
    "copies": 1,
    "firstPageNumber": 1,
    "fitToHeight": 1,
    "fitToWidth": 1,
    "horizontalDpi": 600,
    "paperSize": 1,
    "scale": 100,
    "verticalDpi": 600,
}
_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_ENUM_DEFAULTS = {
    "cellComments": ("none", frozenset({"none", "asDisplayed", "atEnd"})),
    "errors": ("displayed", frozenset({"displayed", "blank", "dash", "NA"})),
    "orientation": (
        "default",
        frozenset({"default", "portrait", "landscape"}),
    ),
    "pageOrder": (
        "downThenOver",
        frozenset({"downThenOver", "overThenDown"}),
    ),
}
_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_ATTRIBUTES = frozenset(
    set(_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_BOOLEAN_DEFAULTS)
    | set(_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_UNSIGNED_DEFAULTS)
    | set(_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_ENUM_DEFAULTS)
    | {"paperHeight", "paperUnits", "paperWidth"}
)
_WORKSHEET_PRINT_LAYOUT_HEADER_FOOTER_ATTRIBUTES = frozenset(
    {
        "alignWithMargins",
        "differentFirst",
        "differentOddEven",
        "scaleWithDoc",
    }
)
_WORKSHEET_PRINT_LAYOUT_HEADER_FOOTER_CHILDREN = frozenset(
    {
        "evenFooter",
        "evenHeader",
        "firstFooter",
        "firstHeader",
        "oddFooter",
        "oddHeader",
    }
)
_WORKSHEET_PRINT_LAYOUT_BREAK_ATTRIBUTES = frozenset(
    {"id", "man", "max", "min", "pt"}
)
_WORKSHEET_PRINT_LAYOUT_BREAK_CONTAINER_ATTRIBUTES = frozenset(
    {"count", "manualBreakCount"}
)
_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_PROPERTY_ATTRIBUTES = frozenset(
    {"autoPageBreaks", "fitToPage"}
)
_WORKSHEET_PRINT_LAYOUT_BUILTIN_NAMES = {
    "_xlnm.print_area": "print-area",
    "_xlnm.print_titles": "print-titles",
}
_WORKSHEET_PRINT_LAYOUT_MEASURE = re.compile(
    r"^([+]?(?:\d+(?:\.\d*)?|\.\d+))(mm|cm|in|pt|pc|pi)?$",
    flags=re.IGNORECASE,
)
_XML_SPACE_ATTRIBUTE = "{http://www.w3.org/XML/1998/namespace}space"


def _worksheet_print_layout_boolean(
    element: ElementTree.Element,
    name: str,
    default: bool,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> bool | None:
    """Read one documented print-layout Boolean, retaining malformed input privately."""
    value = _number_format_boolean(element.get(name), default)
    if value is None:
        note_issue(f"{context}:invalid-{name}", element.get(name))
    return value


def _worksheet_print_layout_unsigned_int(
    element: ElementTree.Element,
    name: str,
    default: int,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> int | None:
    """Read one bounded integer print-layout setting with an OOXML default."""
    raw_value = element.get(name)
    if raw_value is None:
        return default
    value = _number_format_unsigned_int(raw_value)
    if value is None:
        note_issue(f"{context}:invalid-{name}", raw_value)
    return value


def _worksheet_print_layout_leaf_issues(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> None:
    """Record non-schema text or children on a known print-layout leaf."""
    if element.text and element.text.strip():
        note_issue(f"{context}:unexpected-text", element.text)
    for child_index, child in enumerate(element):
        note_issue(
            f"{context}:unexpected-child:{child_index}",
            _xml_fragment(child).sort_key(),
        )


def _worksheet_print_layout_unexpected_attributes(
    element: ElementTree.Element,
    *,
    known: frozenset[str],
    context: str,
    note_issue: Callable[[str, object], None],
    relationship_id_allowed: bool = False,
) -> tuple[tuple[str, str], ...]:
    """Fingerprint unknown attributes while keeping their values out of output."""
    unknown: list[tuple[str, str]] = []
    for attribute, value in sorted(element.attrib.items()):
        namespace = _xml_namespace(attribute)
        local_name = _xml_local_name(attribute)
        if namespace is None and local_name in known:
            continue
        if (
            relationship_id_allowed
            and local_name == "id"
            and namespace
            in {_DOCUMENT_RELATIONSHIP_NS, _STRICT_DOCUMENT_RELATIONSHIP_NS}
        ):
            note_issue(f"{context}:printer-settings-reference", "present")
            unknown.append(("printer-settings-reference", "present"))
            continue
        note_issue(f"{context}:unsupported-attribute:{attribute}", value)
        unknown.append(("unsupported-attribute", repr((attribute, value))))
    return tuple(unknown)


def _worksheet_print_layout_measure(
    value: str | None,
    *,
    units: str | None,
) -> str | None:
    """Canonicalize one custom-paper measure without evaluating its geometry."""
    if value is None:
        return None
    match = _WORKSHEET_PRINT_LAYOUT_MEASURE.fullmatch(value.strip())
    if match is None:
        return None
    number = _font_decimal(match.group(1))
    unit = (match.group(2) or units or "").casefold()
    if number is None or Decimal(number) <= 0 or unit not in {
        "mm",
        "cm",
        "in",
        "pt",
        "pc",
        "pi",
    }:
        return None
    return f"{number}{unit}"


def _worksheet_print_layout_page_setup_signature(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
    fit_to_page: bool | None,
) -> tuple[tuple[tuple[str, str], ...], bool]:
    """Canonicalize effective, printer-independent page setup privately.

    ``fitToPage`` lives in ``sheetPr/pageSetUpPr`` rather than this element.
    It determines whether the fit dimensions or percentage scale affect the
    saved output, so the caller resolves it before handing us a page setup.
    """
    signature: list[tuple[str, str]] = list(
        _worksheet_print_layout_unexpected_attributes(
            element,
            known=_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_ATTRIBUTES,
            context=context,
            note_issue=note_issue,
            relationship_id_allowed=True,
        )
    )
    _worksheet_print_layout_leaf_issues(
        element, context=context, note_issue=note_issue
    )
    material_entries: set[str] = set()
    invalid_entries: set[str] = set()

    for name, default in _WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_BOOLEAN_DEFAULTS.items():
        value = _worksheet_print_layout_boolean(
            element, name, default, context=context, note_issue=note_issue
        )
        if value is None:
            signature.append((name, repr(("invalid", element.get(name)))))
            invalid_entries.add(name)
        elif value != default:
            signature.append((name, "true" if value else "false"))
            material_entries.add(name)

    for name, default in _WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_UNSIGNED_DEFAULTS.items():
        value = _worksheet_print_layout_unsigned_int(
            element, name, default, context=context, note_issue=note_issue
        )
        if value is None:
            signature.append((name, repr(("invalid", element.get(name)))))
            invalid_entries.add(name)
        elif value != default:
            if name == "scale" and not 10 <= value <= 400:
                note_issue(f"{context}:invalid-scale", element.get(name))
                signature.append((name, repr(("invalid", element.get(name)))))
                invalid_entries.add(name)
            else:
                signature.append((name, str(value)))
                material_entries.add(name)

    for name, (default, allowed) in _WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_ENUM_DEFAULTS.items():
        raw_value = element.get(name)
        value = default if raw_value is None else raw_value.strip()
        if value not in allowed:
            note_issue(f"{context}:invalid-{name}", raw_value)
            signature.append((name, repr(("invalid", raw_value))))
            invalid_entries.add(name)
        elif value != default:
            signature.append((name, value))
            material_entries.add(name)

    raw_units = element.get("paperUnits")
    units = raw_units.strip().casefold() if raw_units is not None else None
    if units is not None and units not in {"mm", "cm", "in", "pt", "pc", "pi"}:
        note_issue(f"{context}:invalid-paperUnits", raw_units)
        signature.append(("paperUnits", repr(("invalid", raw_units))))
        units = None
    for name in ("paperHeight", "paperWidth"):
        raw_value = element.get(name)
        if raw_value is None:
            continue
        value = _worksheet_print_layout_measure(raw_value, units=units)
        if value is None:
            note_issue(f"{context}:invalid-{name}", raw_value)
            signature.append((name, repr(("invalid", raw_value))))
            invalid_entries.add(name)
        else:
            signature.append((name, value))
            material_entries.add(name)
    if raw_units is not None and not any(
        element.get(name) is not None for name in ("paperHeight", "paperWidth")
    ):
        note_issue(f"{context}:orphan-paperUnits", raw_units)
        signature.append(("paperUnits", repr(("orphan", raw_units))))

    # ``firstPageNumber`` is inert until the explicit enable flag is on. Its
    # value remains validated above, but omitting an inactive value avoids
    # ordinary writer churn without losing an enabled page-number change.
    use_first_page_number = _worksheet_print_layout_boolean(
        element,
        "useFirstPageNumber",
        False,
        context=context,
        note_issue=note_issue,
    )
    if use_first_page_number is False:
        signature = [entry for entry in signature if entry[0] != "firstPageNumber"]
        material_entries.discard("firstPageNumber")
    elif use_first_page_number is None:
        # The invalid flag is already retained above; leave any page number in
        # the private signature because its effect is ambiguous.
        pass

    # Fit-to-page selects ``fitToWidth`` / ``fitToHeight``; otherwise scale
    # selects the print size. The standard explicitly says scale is overridden
    # when fit dimensions are in use. Preserve malformed inert values as a
    # coverage signal, but avoid high-severity churn for well-formed values
    # whose saved setting cannot affect this worksheet's print output.
    if fit_to_page is True:
        inert_entries = {"scale"}
    elif fit_to_page is False:
        inert_entries = {"fitToHeight", "fitToWidth"}
    else:
        inert_entries = set()
    if inert_entries:
        signature = [
            entry
            for entry in signature
            if entry[0] not in inert_entries or entry[0] in invalid_entries
        ]
        material_entries.difference_update(inert_entries)

    return tuple(sorted(signature)), bool(material_entries)


def _worksheet_print_layout_print_options_signature(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[tuple[str, str], ...], frozenset[str]]:
    """Canonicalize effective print-option flags, not writer-only spelling."""
    signature: list[tuple[str, str]] = list(
        _worksheet_print_layout_unexpected_attributes(
            element,
            known=_WORKSHEET_PRINT_LAYOUT_PRINT_OPTIONS_ATTRIBUTES,
            context=context,
            note_issue=note_issue,
        )
    )
    _worksheet_print_layout_leaf_issues(
        element, context=context, note_issue=note_issue
    )
    active: set[str] = set()
    values: dict[str, bool | None] = {}
    for name, default in (
        ("gridLines", False),
        ("gridLinesSet", True),
        ("headings", False),
        ("horizontalCentered", False),
        ("verticalCentered", False),
    ):
        value = _worksheet_print_layout_boolean(
            element, name, default, context=context, note_issue=note_issue
        )
        values[name] = value
        if value is None:
            signature.append((name, repr(("invalid", element.get(name)))))

    if values["gridLines"] is True and values["gridLinesSet"] is True:
        signature.append(("gridLines", "true"))
        active.add("gridLines")
    elif values["gridLines"] is None or values["gridLinesSet"] is None:
        # The invalid declarations are already fingerprinted above. Do not
        # guess whether gridlines will print.
        pass
    for name, active_name in (
        ("headings", "headings"),
        ("horizontalCentered", "horizontalCentered"),
        ("verticalCentered", "verticalCentered"),
    ):
        if values[name] is True:
            signature.append((name, "true"))
            active.add(active_name)
    return tuple(sorted(signature)), frozenset(active)


def _worksheet_print_layout_page_margins_signature(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[str, str], ...]:
    """Canonicalize all required page margins in inches without rendering them."""
    signature: list[tuple[str, str]] = list(
        _worksheet_print_layout_unexpected_attributes(
            element,
            known=_WORKSHEET_PRINT_LAYOUT_PAGE_MARGIN_ATTRIBUTES,
            context=context,
            note_issue=note_issue,
        )
    )
    _worksheet_print_layout_leaf_issues(
        element, context=context, note_issue=note_issue
    )
    for name in sorted(_WORKSHEET_PRINT_LAYOUT_PAGE_MARGIN_ATTRIBUTES):
        raw_value = element.get(name)
        value = _font_decimal(raw_value)
        if value is None:
            note_issue(f"{context}:invalid-{name}", raw_value)
            signature.append((name, repr(("invalid", raw_value))))
        else:
            signature.append((name, value))
    return tuple(sorted(signature))


def _worksheet_print_layout_header_footer_signature(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[tuple[str, str], ...], bool]:
    """Compare effective header/footer declarations without exposing their text."""
    signature: list[tuple[str, str]] = list(
        _worksheet_print_layout_unexpected_attributes(
            element,
            known=_WORKSHEET_PRINT_LAYOUT_HEADER_FOOTER_ATTRIBUTES,
            context=context,
            note_issue=note_issue,
        )
    )
    defaults = {
        "alignWithMargins": True,
        "differentFirst": False,
        "differentOddEven": False,
        "scaleWithDoc": True,
    }
    values: dict[str, bool | None] = {}
    material = False
    for name, default in defaults.items():
        value = _worksheet_print_layout_boolean(
            element, name, default, context=context, note_issue=note_issue
        )
        values[name] = value
        if value is None:
            signature.append((name, repr(("invalid", element.get(name)))))
        elif value != default:
            signature.append((name, "true" if value else "false"))
            material = True

    children: dict[str, tuple[str, str | None]] = {}
    namespace = _xml_namespace(element.tag)
    for child_index, child in enumerate(element):
        child_context = f"{context}:child:{child_index}"
        local_name = _xml_local_name(child.tag)
        if _xml_namespace(child.tag) != namespace or local_name not in (
            _WORKSHEET_PRINT_LAYOUT_HEADER_FOOTER_CHILDREN
        ):
            note_issue(f"{child_context}:unsupported-child", child.tag)
            signature.append(("unsupported-child", repr(_xml_fragment(child).sort_key())))
            continue
        if local_name in children:
            note_issue(f"{child_context}:duplicate-child", local_name)
            signature.append(("duplicate-child", repr(_xml_fragment(child).sort_key())))
            continue
        for attribute, value in sorted(child.attrib.items()):
            if attribute == _XML_SPACE_ATTRIBUTE and value in {"default", "preserve"}:
                continue
            note_issue(f"{child_context}:unsupported-attribute:{attribute}", value)
            signature.append(
                ("unsupported-header-footer-attribute", repr((attribute, value)))
            )
        if list(child):
            note_issue(
                f"{child_context}:unexpected-child",
                _xml_fragment(child).sort_key(),
            )
        children[local_name] = (child.text or "", child.get(_XML_SPACE_ATTRIBUTE))

    active_children = {"oddHeader", "oddFooter"}
    if values["differentOddEven"] is True:
        active_children.update({"evenHeader", "evenFooter"})
    if values["differentFirst"] is True:
        active_children.update({"firstHeader", "firstFooter"})
    for name in sorted(active_children):
        value = children.get(name)
        if value is not None and value[0]:
            signature.append((name, repr(value)))
            material = True
    return tuple(sorted(signature)), material


def _worksheet_print_layout_breaks_signature(
    element: ElementTree.Element,
    *,
    axis: str,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[tuple[str, str], ...], int]:
    """Retain manual page-break positions, not generated automatic breaks."""
    signature: list[tuple[str, str]] = list(
        _worksheet_print_layout_unexpected_attributes(
            element,
            known=_WORKSHEET_PRINT_LAYOUT_BREAK_CONTAINER_ATTRIBUTES,
            context=context,
            note_issue=note_issue,
        )
    )
    manual_breaks: list[tuple[int, int, int]] = []
    namespace = _xml_namespace(element.tag)
    break_count = 0
    for child_index, child in enumerate(element):
        child_context = f"{context}:break:{child_index}"
        if _xml_namespace(child.tag) != namespace or _xml_local_name(child.tag) != "brk":
            note_issue(f"{child_context}:unsupported-child", child.tag)
            signature.append(("unsupported-child", repr(_xml_fragment(child).sort_key())))
            continue
        break_count += 1
        signature.extend(
            _worksheet_print_layout_unexpected_attributes(
                child,
                known=_WORKSHEET_PRINT_LAYOUT_BREAK_ATTRIBUTES,
                context=child_context,
                note_issue=note_issue,
            )
        )
        _worksheet_print_layout_leaf_issues(
            child, context=child_context, note_issue=note_issue
        )
        manual = _worksheet_print_layout_boolean(
            child, "man", False, context=child_context, note_issue=note_issue
        )
        pivot = _worksheet_print_layout_boolean(
            child, "pt", False, context=child_context, note_issue=note_issue
        )
        values: list[int | None] = []
        for name in ("id", "min", "max"):
            value = _worksheet_print_layout_unsigned_int(
                child, name, 0, context=child_context, note_issue=note_issue
            )
            values.append(value)
        if manual is None or pivot is None or any(value is None for value in values):
            signature.append(("invalid-break", repr((manual, pivot, tuple(values)))))
            continue
        if manual:
            manual_breaks.append((values[0] or 0, values[1] or 0, values[2] or 0))

    for name, expected in (
        ("count", break_count),
        ("manualBreakCount", len(manual_breaks)),
    ):
        raw_value = element.get(name)
        if raw_value is None:
            continue
        value = _number_format_unsigned_int(raw_value)
        if value is None:
            note_issue(f"{context}:invalid-{name}", raw_value)
            signature.append((name, repr(("invalid", raw_value))))
        elif value != expected:
            note_issue(f"{context}:inconsistent-{name}", raw_value)
            signature.append((name, repr(("inconsistent", value, expected))))

    if len(set(manual_breaks)) != len(manual_breaks):
        note_issue(f"{context}:duplicate-manual-break", len(manual_breaks))
    for index, values in enumerate(sorted(manual_breaks)):
        signature.append((f"{axis}-manual-break:{index}", repr(values)))
    return tuple(sorted(signature)), len(manual_breaks)


def _worksheet_print_layout_page_setup_properties_signature(
    element: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[tuple[tuple[str, str], ...], bool | None]:
    """Compare the saved fit-to-page switch while ignoring view-only noise."""
    signature: list[tuple[str, str]] = list(
        _worksheet_print_layout_unexpected_attributes(
            element,
            known=_WORKSHEET_PRINT_LAYOUT_PAGE_SETUP_PROPERTY_ATTRIBUTES,
            context=context,
            note_issue=note_issue,
        )
    )
    _worksheet_print_layout_leaf_issues(
        element, context=context, note_issue=note_issue
    )
    # ``autoPageBreaks`` controls the on-screen indicator, not the saved print
    # surface. Accept and validate it so writers can round-trip it quietly.
    _worksheet_print_layout_boolean(
        element, "autoPageBreaks", True, context=context, note_issue=note_issue
    )
    fit_to_page = _worksheet_print_layout_boolean(
        element, "fitToPage", False, context=context, note_issue=note_issue
    )
    if fit_to_page is None:
        signature.append(("fitToPage", repr(("invalid", element.get("fitToPage")))))
    elif fit_to_page:
        signature.append(("fitToPage", "true"))
    return tuple(sorted(signature)), fit_to_page


def _worksheet_print_layout_metadata(path: Path) -> _WorksheetPrintLayoutMetadata:
    """Inspect persisted, printer-independent worksheet print controls.

    The raw boundary deliberately stays separate from workbook readers: print
    area/title names, page settings, headers, and manual breaks can otherwise
    be normalized away while cells and formulas remain identical. It covers
    standard worksheet declarations in transitional and strict SpreadsheetML.
    Printer-specific devMode settings and legacy custom sheet views remain
    coverage limits rather than guessed render results.
    """
    default_snapshot = WorksheetPrintLayoutSnapshot()
    warnings: set[str] = set()
    issues: dict[str, str] = {}
    entries: list[tuple[str, str]] = []
    print_area_definition_count = 0
    print_title_definition_count = 0
    print_gridline_sheets: set[int] = set()
    print_heading_sheets: set[int] = set()
    horizontally_centered_sheets: set[int] = set()
    vertically_centered_sheets: set[int] = set()
    page_margin_sheets: set[int] = set()
    page_setup_sheets: set[int] = set()
    header_footer_sheets: set[int] = set()
    manual_row_page_break_count = 0
    manual_column_page_break_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            workbook = _xml_root(archive, "xl/workbook.xml")
            workbook_namespace = _xml_namespace(workbook.tag)
            if (
                _xml_local_name(workbook.tag) != "workbook"
                or workbook_namespace
                not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
            ):
                note_issue("workbook:unexpected-root", workbook.tag)
            elif workbook_namespace is not None:
                sheet_tag = f"{{{workbook_namespace}}}sheet"
                sheets_tag = f"{{{workbook_namespace}}}sheets"
                sheet_count = sum(
                    1
                    for container in workbook.findall(sheets_tag)
                    for child in container
                    if child.tag == sheet_tag
                )
                defined_names_tag = f"{{{workbook_namespace}}}definedNames"
                defined_name_tag = f"{{{workbook_namespace}}}definedName"
                containers = workbook.findall(defined_names_tag)
                if len(containers) > 1:
                    note_issue("workbook:multiple-defined-names-containers", len(containers))
                seen_builtin_definitions: set[tuple[str, str]] = set()
                for container_index, container in enumerate(containers):
                    context = f"workbook:defined-names:{container_index}"
                    if container.attrib:
                        note_issue(
                            f"{context}:unexpected-attributes",
                            tuple(sorted(container.attrib.items())),
                        )
                    for definition_index, definition in enumerate(container):
                        definition_context = f"{context}:definition:{definition_index}"
                        if definition.tag != defined_name_tag:
                            note_issue(
                                f"{definition_context}:unsupported-child", definition.tag
                            )
                            continue
                        raw_name = definition.get("name")
                        kind = (
                            _WORKSHEET_PRINT_LAYOUT_BUILTIN_NAMES.get(
                                raw_name.casefold()
                            )
                            if raw_name is not None
                            else None
                        )
                        if kind is None:
                            continue
                        for attribute, value in sorted(definition.attrib.items()):
                            local_name = _xml_local_name(attribute)
                            if _xml_namespace(attribute) is None and local_name in {
                                "name",
                                "localSheetId",
                                "hidden",
                            }:
                                if local_name == "hidden" and _number_format_boolean(
                                    value, False
                                ) is None:
                                    note_issue(
                                        f"{definition_context}:invalid-hidden", value
                                    )
                                continue
                            note_issue(
                                f"{definition_context}:unsupported-attribute:{attribute}",
                                value,
                            )
                        local_sheet_id = _number_format_unsigned_int(
                            definition.get("localSheetId")
                        )
                        if local_sheet_id is None or local_sheet_id >= sheet_count:
                            note_issue(
                                f"{definition_context}:invalid-local-sheet-id",
                                definition.get("localSheetId"),
                            )
                            scope = "invalid"
                        else:
                            scope = str(local_sheet_id)
                        definition_text = (definition.text or "").strip()
                        if not definition_text:
                            note_issue(
                                f"{definition_context}:missing-definition", definition.text
                            )
                        if list(definition):
                            note_issue(
                                f"{definition_context}:unexpected-child",
                                _xml_fragment(definition).sort_key(),
                            )
                        duplicate_key = (kind, scope)
                        if duplicate_key in seen_builtin_definitions:
                            note_issue(
                                f"{definition_context}:duplicate-builtin-definition",
                                duplicate_key,
                            )
                        seen_builtin_definitions.add(duplicate_key)
                        entries.append(
                            (f"worksheet-print-layout:{kind}:{scope}", definition_text)
                        )
                        if kind == "print-area":
                            print_area_definition_count += 1
                        else:
                            print_title_definition_count += 1

            for sheet_index, member in enumerate(_worksheet_display_xml_paths(archive)):
                worksheet = _xml_root(archive, member)
                worksheet_context = f"worksheet:{sheet_index}"
                worksheet_namespace = _xml_namespace(worksheet.tag)
                if (
                    _xml_local_name(worksheet.tag) != "worksheet"
                    or worksheet_namespace
                    not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                ):
                    note_issue(f"{worksheet_context}:unexpected-root", worksheet.tag)
                    continue
                if worksheet_namespace is None:  # guarded above; helps type checkers
                    continue

                def direct_children(
                    name: str,
                    *,
                    root: ElementTree.Element = worksheet,
                    namespace: str = worksheet_namespace,
                ) -> list[ElementTree.Element]:
                    tag = f"{{{namespace}}}{name}"
                    return [child for child in root if child.tag == tag]

                # ``fitToPage`` changes which pageSetup fields are effective,
                # so read it before canonicalising pageSetup itself. Duplicate
                # or invalid declarations leave that relationship ambiguous;
                # retain both sides privately rather than guessing.
                sheet_properties = direct_children("sheetPr")
                if len(sheet_properties) > 1:
                    note_issue(
                        f"{worksheet_context}:multiple-sheet-properties", len(sheet_properties)
                    )
                page_setup_properties_tag = f"{{{worksheet_namespace}}}pageSetUpPr"
                fit_to_page_states: list[bool | None] = []
                for properties_index, properties in enumerate(sheet_properties):
                    controls = [
                        child
                        for child in properties
                        if child.tag == page_setup_properties_tag
                    ]
                    if len(controls) > 1:
                        note_issue(
                            (
                                f"{worksheet_context}:sheet-properties:{properties_index}:"
                                "multiple-page-setup-properties"
                            ),
                            len(controls),
                        )
                    for control_index, control in enumerate(controls):
                        context = (
                            f"{worksheet_context}:sheet-properties:{properties_index}:"
                            f"page-setup-properties:{control_index}"
                        )
                        signature, state = (
                            _worksheet_print_layout_page_setup_properties_signature(
                                control, context=context, note_issue=note_issue
                            )
                        )
                        fit_to_page_states.append(state)
                        if signature:
                            entries.append(
                                (
                                    (
                                        "worksheet-print-layout:"
                                        f"page-setup-properties:{sheet_index}:"
                                        f"{properties_index}:{control_index}"
                                    ),
                                    repr(signature),
                                )
                            )
                            if ("fitToPage", "true") in signature:
                                page_setup_sheets.add(sheet_index)
                if not fit_to_page_states:
                    fit_to_page: bool | None = False
                elif any(state is None for state in fit_to_page_states):
                    fit_to_page = None
                elif len(set(fit_to_page_states)) == 1:
                    fit_to_page = fit_to_page_states[0]
                else:
                    note_issue(
                        f"{worksheet_context}:conflicting-fit-to-page-settings",
                        tuple(fit_to_page_states),
                    )
                    fit_to_page = None

                for name, parser in (
                    ("printOptions", _worksheet_print_layout_print_options_signature),
                    ("pageMargins", _worksheet_print_layout_page_margins_signature),
                    ("headerFooter", _worksheet_print_layout_header_footer_signature),
                ):
                    controls = direct_children(name)
                    if len(controls) > 1:
                        note_issue(
                            f"{worksheet_context}:multiple-{name}-elements", len(controls)
                        )
                    for control_index, control in enumerate(controls):
                        context = f"{worksheet_context}:{name}:{control_index}"
                        parsed = parser(
                            control, context=context, note_issue=note_issue
                        )
                        if name == "printOptions":
                            signature, active_controls = parsed
                            if "gridLines" in active_controls:
                                print_gridline_sheets.add(sheet_index)
                            if "headings" in active_controls:
                                print_heading_sheets.add(sheet_index)
                            if "horizontalCentered" in active_controls:
                                horizontally_centered_sheets.add(sheet_index)
                            if "verticalCentered" in active_controls:
                                vertically_centered_sheets.add(sheet_index)
                        elif name == "pageMargins":
                            signature = parsed
                            page_margin_sheets.add(sheet_index)
                        else:
                            signature, material = parsed
                            if name == "headerFooter" and material:
                                header_footer_sheets.add(sheet_index)
                        if signature:
                            entries.append(
                                (
                                    (
                                        "worksheet-print-layout:"
                                        f"{name}:{sheet_index}:{control_index}"
                                    ),
                                    repr(signature),
                                )
                            )

                page_setups = direct_children("pageSetup")
                if len(page_setups) > 1:
                    note_issue(
                        f"{worksheet_context}:multiple-pageSetup-elements",
                        len(page_setups),
                    )
                for control_index, control in enumerate(page_setups):
                    context = f"{worksheet_context}:pageSetup:{control_index}"
                    signature, material = _worksheet_print_layout_page_setup_signature(
                        control,
                        context=context,
                        note_issue=note_issue,
                        fit_to_page=fit_to_page,
                    )
                    if material:
                        page_setup_sheets.add(sheet_index)
                    if signature:
                        entries.append(
                            (
                                (
                                    "worksheet-print-layout:"
                                    f"pageSetup:{sheet_index}:{control_index}"
                                ),
                                repr(signature),
                            )
                        )

                for name, axis in (("rowBreaks", "row"), ("colBreaks", "column")):
                    controls = direct_children(name)
                    if len(controls) > 1:
                        note_issue(
                            f"{worksheet_context}:multiple-{name}-elements", len(controls)
                        )
                    for control_index, control in enumerate(controls):
                        context = f"{worksheet_context}:{name}:{control_index}"
                        signature, count = _worksheet_print_layout_breaks_signature(
                            control,
                            axis=axis,
                            context=context,
                            note_issue=note_issue,
                        )
                        if axis == "row":
                            manual_row_page_break_count += count
                        else:
                            manual_column_page_break_count += count
                        if signature:
                            entries.append(
                                (
                                    (
                                        "worksheet-print-layout:"
                                        f"{name}:{sheet_index}:{control_index}"
                                    ),
                                    repr(signature),
                                )
                            )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _WorksheetPrintLayoutMetadata(
            default_snapshot,
            (
                "FormulaFence could not inspect worksheet print-layout OOXML "
                f"({type(error).__name__}); affected print controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported worksheet print-layout "
            "metadata; affected print controls have a coverage gap."
        )
        issue_entries = tuple(
            (f"worksheet-print-layout-issue:{context}", detail)
            for context, detail in sorted(issues.items())
        )
        entries.extend(issue_entries)
    else:
        issue_entries = ()
    snapshot = WorksheetPrintLayoutSnapshot(
        print_area_definition_count=print_area_definition_count,
        print_title_definition_count=print_title_definition_count,
        print_gridlines_sheet_count=len(print_gridline_sheets),
        print_headings_sheet_count=len(print_heading_sheets),
        horizontally_centered_print_sheet_count=len(horizontally_centered_sheets),
        vertically_centered_print_sheet_count=len(vertically_centered_sheets),
        page_margin_sheet_count=len(page_margin_sheets),
        page_setup_sheet_count=len(page_setup_sheets),
        header_footer_sheet_count=len(header_footer_sheets),
        manual_row_page_break_count=manual_row_page_break_count,
        manual_column_page_break_count=manual_column_page_break_count,
        unrecognized_print_layout_count=len(issues),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
        unrecognized_signature=(
            _private_external_data_signature(issue_entries) if issue_entries else None
        ),
    )
    return _WorksheetPrintLayoutMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _WorkbookThemeBudget:
    """Bound raw workbook-theme reads across XML and direct image parts."""

    remaining_parts: int = _WORKBOOK_THEME_TOTAL_PARTS
    remaining_bytes: int = _WORKBOOK_THEME_TOTAL_BYTES
    remaining_xml_elements: int = _WORKBOOK_THEME_TOTAL_XML_MAX_ELEMENT_COUNT


def _workbook_theme_issue(
    issues: list[tuple[str, str]],
    context: str,
    detail: object,
) -> None:
    """Record private theme coverage evidence without exposing visual material."""
    issues.append((context, repr(detail)))


def _workbook_theme_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _WorkbookThemeBudget,
    *,
    report_failure: bool,
) -> str | None:
    """Stream theme XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _WORKBOOK_THEME_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    if report_failure:
        warnings.add(
            "FormulaFence did not fully read a workbook-theme XML part whose XML "
            "structure exceeds the safety budget; affected theme controls have a "
            "coverage gap."
        )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _workbook_theme_bounded_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorkbookThemeBudget,
    *,
    kind: str,
    report_failure: bool = True,
    structural_xml: bool = False,
) -> tuple[bytes | None, str | None]:
    """Read one theme-related package member inside fixed scan budgets."""
    if budget.remaining_parts <= 0:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded workbook-theme part count budget; "
                "affected theme controls were not compared."
            )
        return None, _private_external_data_signature(
            (("workbook-theme-part-budget-exhausted", repr((kind, member))),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        if report_failure:
            warnings.add(
                "FormulaFence could not locate a workbook-theme package part; "
                "affected theme controls were not compared."
            )
        return None, _private_external_data_signature(
            (("missing-workbook-theme-member", repr((kind, member))),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _WORKBOOK_THEME_MAX_PART_BYTES:
        if report_failure:
            warnings.add(
                "FormulaFence did not fully read an oversized workbook-theme part; "
                "affected theme controls have a coverage gap."
            )
        return None, _private_external_data_signature(
            (("oversized-workbook-theme-member", repr((kind, metadata))),)
        )
    if info.file_size > budget.remaining_bytes:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded workbook-theme read budget; "
                "affected theme controls were not compared."
            )
        return None, _private_external_data_signature(
            (("workbook-theme-read-budget-exhausted", repr((kind, metadata))),)
        )
    if structural_xml:
        structure_fallback_signature = (
            _workbook_theme_xml_structure_budget_fallback_signature(
                archive,
                member,
                info,
                warnings,
                budget,
                report_failure=report_failure,
            )
        )
        if structure_fallback_signature is not None:
            return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not read a workbook-theme package part "
                f"({type(error).__name__}); affected theme controls were not compared."
            )
        return None, _private_external_data_signature(
            (("unreadable-workbook-theme-member", repr((kind, metadata))),)
        )


def _workbook_theme_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorkbookThemeBudget,
    *,
    kind: str,
    report_failure: bool = True,
) -> tuple[ElementTree.Element | None, str | None]:
    """Return one bounded theme XML root or a private failure signature."""
    payload, fallback_signature = _workbook_theme_bounded_payload(
        archive,
        member,
        warnings,
        budget,
        kind=kind,
        report_failure=report_failure,
        structural_xml=True,
    )
    if payload is None:
        return None, fallback_signature
    try:
        return _xml_root_from_payload(payload), None
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not parse a workbook-theme XML package part "
                f"({type(error).__name__}); affected theme controls were not compared."
            )
        return None, _private_payload_signature(payload)


def _workbook_theme_part_relationships(
    archive: ZipFile,
    source_member: str,
    members: set[str],
    warnings: set[str],
    budget: _WorkbookThemeBudget,
    issues: list[tuple[str, str]],
    *,
    context: str,
    required: bool,
    report_failure: bool = True,
) -> tuple[_PackageRelationship, ...]:
    """Read a theme-related relationship part without opening any target."""
    relationship_member = _relationship_part_path(source_member)
    if relationship_member not in members:
        if required:
            _workbook_theme_issue(
                issues,
                f"missing-{context}-relationship-part",
                relationship_member,
            )
        return ()
    root, fallback_signature = _workbook_theme_bounded_root(
        archive,
        relationship_member,
        warnings,
        budget,
        kind=f"{context}-relationships",
        report_failure=report_failure,
    )
    if root is None:
        _workbook_theme_issue(
            issues,
            f"unreadable-{context}-relationship-part",
            (relationship_member, fallback_signature),
        )
        return ()
    if (
        _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
        or _xml_local_name(root.tag) != "Relationships"
    ):
        _workbook_theme_issue(
            issues,
            f"unexpected-{context}-relationship-root",
            _xml_display_name(root.tag),
        )
        return ()

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_PackageRelationship] = []
    identifiers: list[str] = []
    for child in root:
        if child.tag != relationship_tag:
            _workbook_theme_issue(
                issues,
                f"unexpected-{context}-relationship-child",
                _xml_fragment(child).sort_key(),
            )
            continue
        relationship_id = child.get("Id")
        relationship_type = child.get("Type")
        raw_target = child.get("Target")
        target_mode = child.get("TargetMode", "Internal")
        if relationship_id is None:
            _workbook_theme_issue(
                issues,
                f"missing-{context}-relationship-id",
                _xml_fragment(child).sort_key(),
            )
        else:
            identifiers.append(relationship_id)
        if relationship_type is None or raw_target is None:
            _workbook_theme_issue(
                issues,
                f"malformed-{context}-relationship",
                _xml_fragment(child).sort_key(),
            )
        relationships.append(
            _PackageRelationship(
                relationship_id=relationship_id,
                relationship_type=relationship_type or "",
                target=(
                    _normalise_part_target(source_member, raw_target)
                    if raw_target is not None
                    and target_mode.casefold() == "internal"
                    else None
                ),
                target_mode=target_mode,
                raw_target=raw_target,
            )
        )
    if len(identifiers) != len(set(identifiers)):
        _workbook_theme_issue(
            issues,
            f"duplicate-{context}-relationship-id",
            tuple(sorted(identifiers)),
        )
    return tuple(relationships)


def _workbook_theme_relationship_semantic(
    relationship: _PackageRelationship,
    image_payload_signatures: Mapping[str, str],
) -> tuple[object, ...]:
    """Return private relationship semantics while ignoring writer-selected IDs."""
    relationship_type = relationship.relationship_type.casefold()
    target_mode = relationship.target_mode.casefold()
    if relationship_type in _WORKBOOK_THEME_IMAGE_RELATIONSHIPS:
        if target_mode == "internal" and relationship.target is not None:
            target: object = (
                "theme-image",
                image_payload_signatures.get(
                    relationship.target,
                    ("unreadable-theme-image", relationship.target),
                ),
            )
        else:
            target = ("external-theme-image", relationship.raw_target or "")
    else:
        target = (
            relationship.target
            if target_mode == "internal" and relationship.target is not None
            else relationship.raw_target or ""
        )
    return (relationship_type, target_mode, target)


def _workbook_theme_relationship_semantics(
    relationships: tuple[_PackageRelationship, ...],
    image_payload_signatures: Mapping[str, str],
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> dict[str, tuple[object, ...]]:
    """Resolve theme relationship identifiers to stable private semantics."""
    by_identifier: dict[str, list[_PackageRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id is None:
            continue
        by_identifier[relationship.relationship_id].append(relationship)
    result: dict[str, tuple[object, ...]] = {}
    for identifier, matches in by_identifier.items():
        semantics = sorted(
            (
                _workbook_theme_relationship_semantic(
                    relationship,
                    image_payload_signatures,
                )
                for relationship in matches
            ),
            key=repr,
        )
        if len(semantics) > 1:
            _workbook_theme_issue(
                issues,
                f"duplicate-{context}-relationship-id",
                tuple(semantics),
            )
        result[identifier] = semantics[0]
    return result


def _workbook_theme_xml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[object, ...]],
) -> tuple[object, ...]:
    """Canonicalize private Theme XML while resolving relationship identifiers."""
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if attribute in _WORKBOOK_THEME_RELATIONSHIP_ATTRIBUTES:
            relationship = relationship_semantics.get(value)
            resolved = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
        else:
            attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _workbook_theme_xml_fragment(child, relationship_semantics)
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _workbook_theme_scheme_counts(
    root: ElementTree.Element,
    issues: list[tuple[str, str]],
) -> tuple[int, int, int]:
    """Count Theme schemes without retaining their names or visual controls."""
    namespace = _xml_namespace(root.tag)
    if (
        _xml_local_name(root.tag) != "theme"
        or namespace not in {_DRAWINGML_MAIN_NS, _DRAWINGML_STRICT_MAIN_NS}
    ):
        _workbook_theme_issue(
            issues,
            "unexpected-workbook-theme-root",
            _xml_display_name(root.tag),
        )
        return 0, 0, 0
    theme_elements = [
        child
        for child in root
        if _xml_namespace(child.tag) == namespace
        and _xml_local_name(child.tag) == "themeElements"
    ]
    if len(theme_elements) != 1:
        _workbook_theme_issue(
            issues,
            "invalid-workbook-theme-elements-count",
            len(theme_elements),
        )
    colour_scheme_count = 0
    font_scheme_count = 0
    format_scheme_count = 0
    for element in theme_elements:
        for child in element:
            if _xml_namespace(child.tag) != namespace:
                continue
            if _xml_local_name(child.tag) == "clrScheme":
                colour_scheme_count += 1
            elif _xml_local_name(child.tag) == "fontScheme":
                font_scheme_count += 1
            elif _xml_local_name(child.tag) == "fmtScheme":
                format_scheme_count += 1
    return colour_scheme_count, font_scheme_count, format_scheme_count


def _workbook_theme_metadata(path: Path) -> _WorkbookThemeMetadata:
    """Inventory the workbook Theme part without rendering workbook appearance.

    The Theme part is a workbook-level source of DrawingML colour, font, and
    format/effect schemes. It can also bind direct image payloads. This scanner
    performs bounded raw package inspection and private comparison only; it
    does not resolve effective styles, render a workbook, decode an image,
    fetch a target, or infer Excel client behavior.
    """
    default_snapshot = WorkbookThemeSnapshot()
    warnings: set[str] = set()
    issues: list[tuple[str, str]] = []
    definition_entries: list[tuple[str, str]] = []
    image_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    try:
        with ZipFile(path) as archive:
            raw_members = archive.namelist()
            members = set(raw_members)
            member_counts = Counter(raw_members)
            conventional_theme_members = {
                member
                for member in members
                if _WORKBOOK_THEME_PART_PATTERN.fullmatch(member)
            }
            workbook_relationship_member = _relationship_part_path("xl/workbook.xml")
            if not conventional_theme_members and workbook_relationship_member not in members:
                return _WorkbookThemeMetadata(default_snapshot, ())

            budget = _WorkbookThemeBudget()
            probe_warnings: set[str] = set()
            probe_issues: list[tuple[str, str]] = []
            workbook_relationships = _workbook_theme_part_relationships(
                archive,
                "xl/workbook.xml",
                members,
                probe_warnings,
                budget,
                probe_issues,
                context="workbook-theme",
                required=bool(conventional_theme_members),
                report_failure=bool(conventional_theme_members),
            )
            theme_relationships = tuple(
                relationship
                for relationship in workbook_relationships
                if relationship.relationship_type.casefold()
                in _WORKBOOK_THEME_RELATIONSHIPS
            )
            if not conventional_theme_members and not theme_relationships:
                return _WorkbookThemeMetadata(default_snapshot, ())

            warnings.update(probe_warnings)
            issues.extend(probe_issues)
            declared_theme_members: set[str] = set()
            external_theme_relationship_count = 0
            for relationship in theme_relationships:
                if relationship.target_mode.casefold() == "external":
                    external_theme_relationship_count += 1
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                ):
                    _workbook_theme_issue(
                        issues,
                        "unsafe-workbook-theme-relationship",
                        (
                            relationship.relationship_type,
                            relationship.target_mode,
                            relationship.raw_target,
                        ),
                    )
                    continue
                declared_theme_members.add(relationship.target)
                if relationship.target not in members:
                    _workbook_theme_issue(
                        issues,
                        "missing-workbook-theme-part",
                        relationship.target,
                    )

            theme_members = conventional_theme_members | declared_theme_members
            actual_theme_members = {
                member for member in theme_members if member in members
            }
            for member in sorted(conventional_theme_members - declared_theme_members):
                _workbook_theme_issue(
                    issues,
                    "unbound-workbook-theme-part",
                    member,
                )
            if len(actual_theme_members) > 1:
                _workbook_theme_issue(
                    issues,
                    "multiple-workbook-theme-parts",
                    tuple(sorted(actual_theme_members, key=str.casefold)),
                )

            relevant_members = set(actual_theme_members)
            if workbook_relationship_member in members:
                relevant_members.add(workbook_relationship_member)
            for member in sorted(relevant_members, key=str.casefold):
                if member_counts[member] > 1:
                    _workbook_theme_issue(
                        issues,
                        "duplicate-workbook-theme-package-member",
                        (member, member_counts[member]),
                    )

            roots: dict[str, ElementTree.Element] = {}
            relationships_by_member: dict[str, tuple[_PackageRelationship, ...]] = {}
            colour_scheme_count = 0
            font_scheme_count = 0
            format_scheme_count = 0
            image_members: set[str] = set()
            theme_image_relationship_count = 0
            external_theme_image_relationship_count = 0
            for member in sorted(actual_theme_members, key=str.casefold):
                root, fallback_signature = _workbook_theme_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                    kind="theme",
                )
                if root is None:
                    _workbook_theme_issue(
                        issues,
                        "unreadable-workbook-theme-part",
                        (member, fallback_signature),
                    )
                    definition_entries.append(
                        (
                            "unreadable-workbook-theme-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                roots[member] = root
                counts = _workbook_theme_scheme_counts(root, issues)
                colour_scheme_count += counts[0]
                font_scheme_count += counts[1]
                format_scheme_count += counts[2]

                relationships = _workbook_theme_part_relationships(
                    archive,
                    member,
                    members,
                    warnings,
                    budget,
                    issues,
                    context="theme",
                    required=False,
                )
                relationships_by_member[member] = relationships
                for relationship in relationships:
                    if (
                        relationship.relationship_type.casefold()
                        not in _WORKBOOK_THEME_IMAGE_RELATIONSHIPS
                    ):
                        _workbook_theme_issue(
                            issues,
                            "unsupported-workbook-theme-relationship",
                            (
                                relationship.relationship_type,
                                relationship.target_mode,
                                relationship.raw_target,
                            ),
                        )
                        continue
                    theme_image_relationship_count += 1
                    if relationship.target_mode.casefold() == "external":
                        external_theme_image_relationship_count += 1
                        continue
                    if relationship.target is None:
                        _workbook_theme_issue(
                            issues,
                            "unsafe-workbook-theme-image-relationship",
                            (
                                relationship.relationship_type,
                                relationship.target_mode,
                                relationship.raw_target,
                            ),
                        )
                        continue
                    if relationship.target not in members:
                        _workbook_theme_issue(
                            issues,
                            "missing-workbook-theme-image-part",
                            relationship.target,
                        )
                        continue
                    image_members.add(relationship.target)

            image_payload_signatures: dict[str, str] = {}
            for member in sorted(image_members, key=str.casefold):
                if member_counts[member] > 1:
                    _workbook_theme_issue(
                        issues,
                        "duplicate-workbook-theme-image-package-member",
                        (member, member_counts[member]),
                    )
                payload, fallback_signature = _workbook_theme_bounded_payload(
                    archive,
                    member,
                    warnings,
                    budget,
                    kind="theme-image",
                )
                if payload is None:
                    _workbook_theme_issue(
                        issues,
                        "unreadable-workbook-theme-image-part",
                        (member, fallback_signature),
                    )
                    image_entries.append(
                        (
                            "unreadable-workbook-theme-image-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                signature = _private_payload_signature(payload)
                image_payload_signatures[member] = signature
                image_entries.append(("workbook-theme-image", signature))

            for member, root in sorted(roots.items(), key=lambda item: item[0].casefold()):
                relationships = relationships_by_member.get(member, ())
                semantics = _workbook_theme_relationship_semantics(
                    relationships,
                    image_payload_signatures,
                    issues,
                    context="theme",
                )
                for element in root.iter():
                    for attribute, value in element.attrib.items():
                        if (
                            attribute in _WORKBOOK_THEME_RELATIONSHIP_ATTRIBUTES
                            and value not in semantics
                        ):
                            _workbook_theme_issue(
                                issues,
                                "missing-workbook-theme-xml-relationship",
                                value,
                            )
                fragment = _workbook_theme_xml_fragment(root, semantics)
                signature = _private_external_data_signature(
                    (("workbook-theme-definition", repr(fragment)),)
                )
                definition_entries.append(("workbook-theme-definition", signature))
                relationship_entries.append(
                    (
                        "workbook-theme-direct-relationships",
                        repr(
                            tuple(
                                sorted(
                                    (
                                        _workbook_theme_relationship_semantic(
                                            relationship,
                                            image_payload_signatures,
                                        )
                                        for relationship in relationships
                                    ),
                                    key=repr,
                                )
                            )
                        ),
                    )
                )

            for relationship in theme_relationships:
                relationship_type = relationship.relationship_type.casefold()
                target_mode = relationship.target_mode.casefold()
                if target_mode == "internal" and relationship.target is not None:
                    target: object = ("workbook-theme", "internal-target")
                else:
                    target = ("external-workbook-theme", relationship.raw_target or "")
                relationship_entries.append(
                    (
                        "workbook-theme-relationship",
                        repr((relationship_type, target_mode, target)),
                    )
                )

            if issues:
                warnings.add(
                    "FormulaFence found malformed, unsupported, or incomplete "
                    "workbook-theme metadata; affected theme controls have a coverage gap."
                )
            relationship_entries.extend(
                ("workbook-theme-issue", repr(issue))
                for issue in sorted(issues)
            )
            snapshot = WorkbookThemeSnapshot(
                theme_part_count=len(actual_theme_members),
                colour_scheme_count=colour_scheme_count,
                font_scheme_count=font_scheme_count,
                format_scheme_count=format_scheme_count,
                theme_relationship_count=len(theme_relationships),
                external_theme_relationship_count=external_theme_relationship_count,
                theme_image_part_count=len(image_members),
                theme_image_relationship_count=theme_image_relationship_count,
                external_theme_image_relationship_count=(
                    external_theme_image_relationship_count
                ),
                unrecognized_theme_count=len(issues),
                definition_signature=(
                    _private_external_data_signature(tuple(sorted(definition_entries)))
                    if definition_entries
                    else None
                ),
                image_payload_signature=(
                    _private_external_data_signature(tuple(sorted(image_entries)))
                    if image_entries
                    else None
                ),
                relationship_signature=(
                    _private_external_data_signature(tuple(sorted(relationship_entries)))
                    if relationship_entries
                    else None
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _WorkbookThemeMetadata(
            WorkbookThemeSnapshot(
                unrecognized_theme_count=1,
                relationship_signature=_private_external_data_signature(
                    (("workbook-theme-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect workbook-theme OOXML "
                f"({type(error).__name__}); affected theme controls were not compared.",
            ),
        )
    return _WorkbookThemeMetadata(snapshot, tuple(sorted(warnings)))


_FORMULA_CACHED_RESULT_DECIMAL_PATTERN = re.compile(
    r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[Ee][+-]?[0-9]+)?"
)
_FORMULA_CACHED_RESULT_MAX_EXPONENT = 308
_FORMULA_CACHED_RESULT_TYPES = frozenset({"b", "e", "n", "str"})
_FORMULA_CACHED_RESULT_FORMULA_TYPES = frozenset({"array", "dataTable", "shared"})


def _formula_cached_result_number(value: str) -> str | None:
    """Normalize one finite Excel numeric cache without retaining its text."""
    if not _FORMULA_CACHED_RESULT_DECIMAL_PATTERN.fullmatch(value):
        return None
    try:
        numeric = Decimal(value)
    except InvalidOperation:
        return None
    if (
        not numeric.is_finite()
        or (
            not numeric.is_zero()
            and abs(numeric.adjusted()) > _FORMULA_CACHED_RESULT_MAX_EXPONENT
        )
    ):
        return None
    if numeric.is_zero():
        return "0"
    sign, digits, exponent = numeric.as_tuple()
    digit_text = "".join(str(digit) for digit in digits)
    while digit_text.endswith("0"):
        digit_text = digit_text[:-1]
        exponent += 1
    return f"{'-' if sign else ''}{digit_text}e{exponent}"


def _formula_cached_result_boolean(value: str) -> str | None:
    """Normalize the Boolean spellings accepted by compatible writers."""
    lowered = value.casefold()
    if lowered in {"0", "false"}:
        return "false"
    if lowered in {"1", "true"}:
        return "true"
    return None


def _formula_cached_result_signature(result_type: str, value: str) -> str:
    """Digest a private formula result without retaining its material."""
    return _private_payload_signature(repr((result_type, value)).encode("utf-8"))


def _formula_cached_result_metadata(path: Path) -> _FormulaCachedResultMetadata:
    """Inspect stored formula results directly from worksheet XML.

    The workbook reader exposes either formula text or a stored result, not
    both at once. FormulaFence needs both representations to distinguish a
    cache-only change from a formula or ordinary input change. Values and
    locations remain inside private per-entry digests.
    """
    warnings: set[str] = set()
    default = FormulaCachedResultSnapshot()
    entries: list[FormulaCachedResultEntry] = []
    signature_entries: list[tuple[str, str]] = []
    formula_cell_count = 0
    cached_result_cell_count = 0
    missing_cached_result_cell_count = 0
    numeric_cached_result_count = 0
    string_cached_result_count = 0
    boolean_cached_result_count = 0
    error_cached_result_count = 0
    unrecognized_cached_result_count = 0

    try:
        with ZipFile(path) as archive:
            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            formula_tag = f"{{{_SPREADSHEETML_NS}}}f"
            value_tag = f"{{{_SPREADSHEETML_NS}}}v"
            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                if (
                    _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    unrecognized_cached_result_count += 1
                    signature_entries.append(
                        (
                            f"formula-cache-root:{sheet.casefold()}",
                            _private_payload_signature(
                                ElementTree.tostring(worksheet, encoding="utf-8")
                            ),
                        )
                    )
                    continue

                seen_coordinates: set[str] = set()
                for cell_index, cell in enumerate(worksheet.iter(cell_tag)):
                    formulas = cell.findall(formula_tag)
                    if not formulas:
                        continue
                    formula_cell_count += 1
                    issues: set[str] = set()
                    raw_coordinate = cell.get("r")
                    coordinate = _canonical_what_if_data_table_cell(raw_coordinate)
                    if coordinate is None:
                        issues.add("invalid-coordinate")
                        coordinate = f"invalid-{cell_index + 1}"
                    elif coordinate in seen_coordinates:
                        issues.add("duplicate-coordinate")
                    seen_coordinates.add(coordinate)

                    if len(formulas) != 1:
                        issues.add("multiple-formulas")
                    formula = formulas[0]
                    formula_type = formula.get("t")
                    if (
                        formula_type is not None
                        and formula_type not in _FORMULA_CACHED_RESULT_FORMULA_TYPES
                    ):
                        issues.add("unsupported-formula-type")

                    values = cell.findall(value_tag)
                    if len(values) > 1:
                        issues.add("multiple-cached-values")
                    value_element = values[0] if values else None
                    cell_type = cell.get("t", "n")
                    if cell_type not in _FORMULA_CACHED_RESULT_TYPES:
                        issues.add("unsupported-result-type")

                    result_type = "missing"
                    result_value = "missing"
                    value_is_blank = (
                        value_element is None
                        or value_element.text is None
                        or value_element.text == ""
                    )
                    if cell_type == "str" and value_element is not None:
                        # A formula-string result may validly be the empty string.
                        result_type = "string"
                        result_value = value_element.text or ""
                        cached_result_cell_count += 1
                        string_cached_result_count += 1
                    elif value_is_blank:
                        missing_cached_result_cell_count += 1
                    elif cell_type in {"n", ""}:
                        normalized = _formula_cached_result_number(value_element.text or "")
                        if normalized is None:
                            issues.add("invalid-numeric-result")
                            result_type = "unrecognized"
                            result_value = value_element.text or ""
                        else:
                            result_type = "numeric"
                            result_value = normalized
                            cached_result_cell_count += 1
                            numeric_cached_result_count += 1
                    elif cell_type == "b":
                        normalized = _formula_cached_result_boolean(value_element.text or "")
                        if normalized is None:
                            issues.add("invalid-boolean-result")
                            result_type = "unrecognized"
                            result_value = value_element.text or ""
                        else:
                            result_type = "boolean"
                            result_value = normalized
                            cached_result_cell_count += 1
                            boolean_cached_result_count += 1
                    elif cell_type == "e":
                        result_type = "error"
                        result_value = value_element.text or ""
                        cached_result_cell_count += 1
                        error_cached_result_count += 1
                    elif cell_type == "str":
                        result_type = "string"
                        result_value = value_element.text or ""
                        cached_result_cell_count += 1
                        string_cached_result_count += 1
                    else:
                        result_type = "unrecognized"
                        result_value = (
                            "missing" if value_element is None else value_element.text or ""
                        )

                    if issues:
                        unrecognized_cached_result_count += 1
                        result_type = "unrecognized"

                    result_signature = _formula_cached_result_signature(
                        result_type,
                        result_value,
                    )
                    entries.append(
                        FormulaCachedResultEntry(
                            sheet=sheet,
                            coordinate=coordinate,
                            result_type=result_type,
                            result_signature=result_signature,
                        )
                    )
                    signature_entries.append(
                        (
                            (
                                "formula-cache:"
                                f"{sheet.casefold()}:{coordinate.casefold()}"
                            ),
                            repr((result_type, result_signature, tuple(sorted(issues)))),
                        )
                    )
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _FormulaCachedResultMetadata(
            default,
            (
                "FormulaFence could not inspect formula cached-result OOXML "
                f"({type(error).__name__}); affected displayed results were not compared.",
            ),
        )

    if unrecognized_cached_result_count:
        warnings.add(
            "FormulaFence found malformed or unsupported formula cached-result metadata; "
            "affected displayed results have a coverage gap."
        )
    snapshot = FormulaCachedResultSnapshot(
        formula_cell_count=formula_cell_count,
        cached_result_cell_count=cached_result_cell_count,
        missing_cached_result_cell_count=missing_cached_result_cell_count,
        numeric_cached_result_count=numeric_cached_result_count,
        string_cached_result_count=string_cached_result_count,
        boolean_cached_result_count=boolean_cached_result_count,
        error_cached_result_count=error_cached_result_count,
        unrecognized_cached_result_count=unrecognized_cached_result_count,
        definition_signature=_private_external_data_signature(
            tuple(sorted(signature_entries))
        ),
        entries=tuple(
            sorted(
                entries,
                key=lambda entry: (
                    entry.sheet.casefold(),
                    entry.coordinate.casefold(),
                ),
            )
        ),
    )
    return _FormulaCachedResultMetadata(snapshot, tuple(sorted(warnings)))


_XML_SPACE_ATTRIBUTE = "{http://www.w3.org/XML/1998/namespace}space"
_RICH_TEXT_BOOLEAN_PROPERTIES = _FONT_BOOLEAN_CHILDREN
_RICH_TEXT_VALUE_PROPERTIES = frozenset(
    {"rFont", "charset", "family", "sz", "u", "vertAlign", "scheme"}
)
_RICH_TEXT_PROPERTIES = (
    _RICH_TEXT_BOOLEAN_PROPERTIES | _RICH_TEXT_VALUE_PROPERTIES | {"color"}
)
_RICH_TEXT_DEFAULT_STYLE = ("default", "")


@dataclass(frozen=True)
class _RichTextItem:
    """One private shared or inline rich-string presentation record."""

    has_rich_runs: bool
    rich_run_count: int
    phonetic_run_count: int
    phonetic_property_count: int
    text_signature: str
    style_sequence_signature: str | None
    style_layout_signature: str | None
    unrecognized: bool
    issue_signature: str | None

    @property
    def needs_guard(self) -> bool:
        return bool(
            self.has_rich_runs
            or self.phonetic_run_count
            or self.phonetic_property_count
            or self.unrecognized
        )


def _rich_text_private_digest(value: object) -> str:
    """Digest private rich-string material before it reaches an output model."""
    return hashlib.sha256(
        repr(value).encode("utf-8", errors="surrogatepass")
    ).hexdigest()


def _rich_text_text_signature(value: str) -> str:
    """Digest displayed rich-string text without retaining it."""
    return hashlib.sha256(
        value.encode("utf-8", errors="surrogatepass")
    ).hexdigest()


def _rich_text_text_value(
    text: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[str, bool, bool]:
    """Read one rich-string text element and retain only private state."""
    invalid = False
    preserve_space = False
    if any(text):
        note_issue(f"{context}:unexpected-child", tuple(child.tag for child in text))
        invalid = True
    if text.tail is not None and text.tail.strip():
        note_issue(f"{context}:unexpected-tail", text.tail)
        invalid = True
    for attribute, value in text.attrib.items():
        if attribute != _XML_SPACE_ATTRIBUTE:
            note_issue(
                f"{context}:unsupported-attribute",
                (_xml_display_name(attribute), value),
            )
            invalid = True
            continue
        if value == "preserve":
            preserve_space = True
        elif value != "default":
            note_issue(f"{context}:invalid-space", value)
            invalid = True
    return text.text or "", preserve_space, invalid


def _rich_text_run_style(
    properties: ElementTree.Element | None,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[str, str]:
    """Canonicalize one rich-run property set without exposing its values."""
    if properties is None:
        return _RICH_TEXT_DEFAULT_STYLE

    invalid = False
    opaque_children: list[object] = []
    if properties.attrib:
        note_issue(
            f"{context}:unsupported-attributes",
            tuple(sorted(properties.attrib.items())),
        )
        invalid = True
    if properties.text is not None and properties.text.strip():
        note_issue(f"{context}:unexpected-text", properties.text)
        invalid = True

    entries: list[tuple[object, ...]] = []
    seen: set[str] = set()
    for child_index, child in enumerate(properties):
        child_context = f"{context}:child:{child_index}"
        name = _xml_local_name(child.tag)
        if (
            _xml_namespace(child.tag) != _SPREADSHEETML_NS
            or name not in _RICH_TEXT_PROPERTIES
        ):
            note_issue(f"{child_context}:unsupported-child", child.tag)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        if name in seen:
            note_issue(f"{child_context}:duplicate-child", name)
            opaque_children.append(_xml_fragment(child).sort_key())
            invalid = True
            continue
        seen.add(name)
        font_name = "name" if name == "rFont" else name
        signature, child_invalid = _font_child_signature(
            child,
            name=font_name,
            context=child_context,
            note_issue=note_issue,
        )
        if name == "rFont":
            signature = (name, *signature[1:])
        if child_invalid:
            invalid = True
        if name in _RICH_TEXT_BOOLEAN_PROPERTIES and signature[1] is False:
            continue
        entries.append(signature)

    definition = tuple(sorted(entries, key=repr))
    if invalid:
        return (
            "unrecognized",
            _rich_text_private_digest(
                ("run-properties", context, definition, tuple(opaque_children))
            ),
        )
    if not definition:
        return _RICH_TEXT_DEFAULT_STYLE
    return ("style", _rich_text_private_digest(definition))


def _rich_text_run(
    run: ElementTree.Element,
    *,
    context: str,
    note_issue: Callable[[str, object], None],
) -> tuple[str, tuple[str, str], bool, bool]:
    """Read one rich text run as text, private style, space mode, and validity."""
    invalid = False
    if run.attrib:
        note_issue(f"{context}:unsupported-attributes", tuple(sorted(run.attrib.items())))
        invalid = True
    if run.text is not None and run.text.strip():
        note_issue(f"{context}:unexpected-text", run.text)
        invalid = True

    properties: list[ElementTree.Element] = []
    texts: list[ElementTree.Element] = []
    seen_text = False
    rpr_tag = f"{{{_SPREADSHEETML_NS}}}rPr"
    text_tag = f"{{{_SPREADSHEETML_NS}}}t"
    for child_index, child in enumerate(run):
        child_context = f"{context}:child:{child_index}"
        if child.tag == rpr_tag:
            if seen_text:
                note_issue(f"{child_context}:out-of-order-properties", child.tag)
                invalid = True
            properties.append(child)
        elif child.tag == text_tag:
            seen_text = True
            texts.append(child)
        else:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            invalid = True
    if len(properties) > 1:
        note_issue(f"{context}:multiple-properties", len(properties))
        invalid = True
    if len(texts) != 1:
        note_issue(f"{context}:text-count", len(texts))
        invalid = True

    style = _rich_text_run_style(
        properties[0] if properties else None,
        context=f"{context}:properties",
        note_issue=note_issue,
    )
    if style[0] == "unrecognized":
        invalid = True
    if not texts:
        return "", style, False, True
    value, preserve_space, text_invalid = _rich_text_text_value(
        texts[0],
        context=f"{context}:text",
        note_issue=note_issue,
    )
    return value, style, preserve_space, invalid or text_invalid


def _rich_text_item(
    item: ElementTree.Element,
    *,
    context: str,
) -> _RichTextItem | None:
    """Parse one rich string item only when it has presentation controls."""
    issues: list[tuple[str, str]] = []

    def note_issue(issue_context: str, detail: object) -> None:
        issues.append((issue_context, repr(detail)))

    run_tag = f"{{{_SPREADSHEETML_NS}}}r"
    text_tag = f"{{{_SPREADSHEETML_NS}}}t"
    phonetic_run_tag = f"{{{_SPREADSHEETML_NS}}}rPh"
    phonetic_properties_tag = f"{{{_SPREADSHEETML_NS}}}phoneticPr"
    has_presentation_child = any(
        child.tag in {run_tag, phonetic_run_tag, phonetic_properties_tag}
        for child in item
    )
    if not has_presentation_child:
        return None

    if item.attrib:
        note_issue(f"{context}:unsupported-attributes", tuple(sorted(item.attrib.items())))
    if item.text is not None and item.text.strip():
        note_issue(f"{context}:unexpected-text", item.text)

    direct_texts: list[ElementTree.Element] = []
    runs: list[tuple[str, tuple[str, str], bool]] = []
    phonetic_fragments: list[object] = []
    phonetic_run_count = 0
    phonetic_property_count = 0
    invalid = False
    for child_index, child in enumerate(item):
        child_context = f"{context}:child:{child_index}"
        if child.tag == run_tag:
            text, style, preserve_space, run_invalid = _rich_text_run(
                child,
                context=child_context,
                note_issue=note_issue,
            )
            runs.append((text, style, preserve_space))
            invalid = invalid or run_invalid
        elif child.tag == text_tag:
            direct_texts.append(child)
        elif child.tag == phonetic_run_tag:
            phonetic_run_count += 1
            phonetic_fragments.append(_xml_fragment(child).sort_key())
        elif child.tag == phonetic_properties_tag:
            phonetic_property_count += 1
            phonetic_fragments.append(_xml_fragment(child).sort_key())
        else:
            note_issue(f"{child_context}:unsupported-child", child.tag)
            invalid = True

    if runs and direct_texts:
        note_issue(f"{context}:mixed-direct-and-run-text", len(direct_texts))
        invalid = True
    if len(direct_texts) > 1:
        note_issue(f"{context}:multiple-direct-texts", len(direct_texts))
        invalid = True

    direct_text = ""
    if direct_texts:
        direct_text, _preserve_space, text_invalid = _rich_text_text_value(
            direct_texts[0],
            context=f"{context}:direct-text",
            note_issue=note_issue,
        )
        invalid = invalid or text_invalid

    normalized_runs: list[tuple[str, tuple[str, str], bool]] = []
    for text, style, preserve_space in runs:
        if (
            normalized_runs
            and normalized_runs[-1][1:] == (style, preserve_space)
        ):
            previous_text, _previous_style, _previous_preserve_space = normalized_runs[-1]
            normalized_runs[-1] = (previous_text + text, style, preserve_space)
        else:
            normalized_runs.append((text, style, preserve_space))

    base_text = "".join(text for text, _style, _preserve_space in normalized_runs)
    if not runs:
        base_text = direct_text
    sequence: list[tuple[str, str, bool]] = []
    layout: list[tuple[int, int, str, str, bool]] = []
    offset = 0
    for text, style, preserve_space in normalized_runs:
        controlled = style != _RICH_TEXT_DEFAULT_STYLE or preserve_space
        if controlled:
            sequence.append((style[0], style[1], preserve_space))
            layout.append((offset, len(text), style[0], style[1], preserve_space))
        offset += len(text)
    if issues:
        invalid = True
        issue_signature = _rich_text_private_digest(tuple(sorted(issues)))
        sequence.append(("unrecognized", issue_signature, False))
        layout.append((0, len(base_text), "unrecognized", issue_signature, False))
    else:
        issue_signature = None

    phonetic_material = tuple(phonetic_fragments)
    controlled = bool(sequence or phonetic_material)
    return _RichTextItem(
        has_rich_runs=bool(runs),
        rich_run_count=len(runs),
        phonetic_run_count=phonetic_run_count,
        phonetic_property_count=phonetic_property_count,
        text_signature=_rich_text_text_signature(base_text),
        style_sequence_signature=(
            _rich_text_private_digest((tuple(sequence), phonetic_material))
            if controlled
            else None
        ),
        style_layout_signature=(
            _rich_text_private_digest((tuple(layout), phonetic_material))
            if controlled
            else None
        ),
        unrecognized=invalid,
        issue_signature=issue_signature,
    )


def _rich_text_shared_string_member(
    archive: ZipFile,
) -> tuple[str | None, str | None]:
    """Find the shared-string part through its workbook relationship."""
    relationships = _package_relationships(archive, "xl/workbook.xml")
    targets = [
        relationship.target
        for relationship in relationships
        if relationship.relationship_type == _OOXML_SHARED_STRINGS_RELATIONSHIP
        and relationship.target is not None
    ]
    if len(targets) > 1:
        return None, "multiple-shared-string-parts"
    if targets:
        target = targets[0]
        if target in archive.namelist():
            return target, None
        return None, "missing-shared-string-part"
    if "xl/sharedStrings.xml" in archive.namelist():
        return "xl/sharedStrings.xml", None
    return None, None


def _rich_text_shared_string_items(
    archive: ZipFile,
    member: str,
) -> tuple[list[_RichTextItem | None] | None, str | None]:
    """Stream one shared-string table without retaining unrelated XML entries.

    Only one ``si`` item's run tree is needed at a time for the private
    rich-text signature. Retaining the whole ``sst`` tree first makes ignored
    foreign entries and a large table of plain strings allocate before the
    scanner can determine that they contain no presentation control. The
    semantic-reader preflight has already bounded every materialized ``si``
    item; remove every completed root child as this stream advances.
    """
    shared_table_tag = f"{{{_SPREADSHEETML_NS}}}sst"
    shared_item_tag = f"{{{_SPREADSHEETML_NS}}}si"
    root: ElementTree.Element | None = None
    stack: list[ElementTree.Element] = []
    items: list[_RichTextItem | None] = []

    with archive.open(member) as xml_stream:
        for event, element in _iterparse_ooxml_xml_with_character_data_budget(
            xml_stream
        ):
            if event == "start":
                stack.append(element)
                if len(stack) == 1:
                    root = element
                    if root.tag != shared_table_tag:
                        return None, "invalid-shared-string-root"
                continue

            depth = len(stack)
            parent = stack[-2] if depth > 1 else None
            is_direct_shared_item = depth == 2 and element.tag == shared_item_tag
            in_direct_shared_item = (
                len(stack) > 1 and stack[1].tag == shared_item_tag
            )
            if is_direct_shared_item:
                items.append(
                    _rich_text_item(
                        element,
                        context=f"shared-string:{len(items)}",
                    )
                )
                if root is not None:
                    root.remove(element)
                element.clear()
            elif not in_direct_shared_item:
                # A root-level foreign child used to stay attached to ``sst``
                # until the whole table had parsed. Remove it (and its already
                # completed descendants) immediately; FormulaFence's old
                # ``findall(si)`` path ignored it as well.
                if parent is not None:
                    parent.remove(element)
                element.clear()
            stack.pop()

    if root is None:
        return None, "invalid-shared-string-root"
    return items, None


def _rich_text_run_metadata(path: Path) -> _RichTextRunMetadata:
    """Inspect shared and inline character-level presentation controls.

    Workbook readers usually return concatenated rich-string text and discard
    the individual run properties. This scan follows shared-string references
    and inline strings directly, retaining only private signatures keyed to
    their effective cells. Shared-string table reorderings and a switch between
    equivalent shared and inline storage therefore stay quiet.
    """
    warnings: set[str] = set()
    entries: list[RichTextRunEntry] = []
    signature_entries: list[tuple[str, str]] = []
    issues: dict[str, str] = {}
    shared_rich_text_indexes: set[int] = set()
    shared_phonetic_indexes: set[int] = set()
    shared_unrecognized_indexes: set[int] = set()
    inline_unrecognized_keys: set[tuple[str, str]] = set()
    shared_rich_text_cell_count = 0
    inline_rich_text_cell_count = 0
    inline_rich_text_run_count = 0
    inline_phonetic_run_count = 0
    inline_phonetic_property_count = 0

    def note_issue(context: str, detail: object) -> None:
        issues.setdefault(context, repr(detail))

    try:
        with ZipFile(path) as archive:
            shared_member, shared_member_issue = _rich_text_shared_string_member(archive)
            shared_items: list[_RichTextItem | None] | None = None
            if shared_member is not None:
                shared_items, shared_item_issue = _rich_text_shared_string_items(
                    archive,
                    shared_member,
                )
                if shared_item_issue is not None:
                    shared_member_issue = shared_item_issue

            cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
            value_tag = f"{{{_SPREADSHEETML_NS}}}v"
            inline_string_tag = f"{{{_SPREADSHEETML_NS}}}is"
            seen_locations: set[tuple[str, str]] = set()

            def add_entry(
                sheet: str,
                raw_coordinate: str | None,
                item: _RichTextItem,
                *,
                context: str,
            ) -> tuple[str, str] | None:
                coordinate = _canonical_what_if_data_table_cell(raw_coordinate)
                if coordinate is None:
                    note_issue(f"{context}:invalid-coordinate", raw_coordinate)
                    return None
                location = (sheet, coordinate)
                if location in seen_locations:
                    note_issue(f"{context}:duplicate-coordinate", coordinate)
                    return None
                seen_locations.add(location)
                entry = RichTextRunEntry(
                    sheet=sheet,
                    coordinate=coordinate,
                    text_signature=item.text_signature,
                    style_sequence_signature=item.style_sequence_signature,
                    style_layout_signature=item.style_layout_signature,
                )
                entries.append(entry)
                signature_entries.append(
                    (
                        (
                            "rich-text:"
                            f"{sheet.casefold()}:{coordinate.casefold()}"
                        ),
                        repr(
                            (
                                entry.text_signature,
                                entry.style_sequence_signature,
                                entry.style_layout_signature,
                            )
                        ),
                    )
                )
                return location

            for sheet, member in _worksheet_xml_paths(archive).items():
                worksheet = _xml_root(archive, member)
                if (
                    _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    note_issue(f"worksheet:{sheet.casefold()}:root", worksheet.tag)
                    continue
                for cell_index, cell in enumerate(worksheet.iter(cell_tag)):
                    cell_context = f"cell:{sheet.casefold()}:{cell_index}"
                    cell_type = cell.get("t")
                    if cell_type == "s":
                        values = cell.findall(value_tag)
                        if len(values) != 1:
                            note_issue(
                                f"{cell_context}:shared-string-value-count",
                                len(values),
                            )
                            continue
                        value = values[0].text or ""
                        string_index = _number_format_unsigned_int(value)
                        if shared_items is None:
                            note_issue(
                                f"{cell_context}:missing-shared-string-table",
                                shared_member_issue or "not-found",
                            )
                            continue
                        if (
                            string_index is None
                            or string_index >= len(shared_items)
                        ):
                            note_issue(
                                f"{cell_context}:invalid-shared-string-index",
                                value,
                            )
                            continue
                        item = shared_items[string_index]
                        if item is None or not item.needs_guard:
                            continue
                        location = add_entry(
                            sheet,
                            cell.get("r"),
                            item,
                            context=cell_context,
                        )
                        if location is None:
                            continue
                        if item.has_rich_runs:
                            shared_rich_text_cell_count += 1
                            shared_rich_text_indexes.add(string_index)
                        if item.phonetic_run_count or item.phonetic_property_count:
                            shared_phonetic_indexes.add(string_index)
                        if item.unrecognized:
                            shared_unrecognized_indexes.add(string_index)
                        continue

                    inline_items = cell.findall(inline_string_tag)
                    if not inline_items:
                        continue
                    if len(inline_items) != 1:
                        note_issue(
                            f"{cell_context}:inline-string-count",
                            len(inline_items),
                        )
                    item = _rich_text_item(
                        inline_items[0],
                        context=f"{cell_context}:inline-string",
                    )
                    if item is None or not item.needs_guard:
                        continue
                    if cell_type != "inlineStr":
                        note_issue(
                            f"{cell_context}:inline-string-cell-type",
                            cell_type,
                        )
                    location = add_entry(
                        sheet,
                        cell.get("r"),
                        item,
                        context=cell_context,
                    )
                    if location is None:
                        continue
                    if item.has_rich_runs:
                        inline_rich_text_cell_count += 1
                        inline_rich_text_run_count += item.rich_run_count
                    inline_phonetic_run_count += item.phonetic_run_count
                    inline_phonetic_property_count += item.phonetic_property_count
                    if item.unrecognized:
                        inline_unrecognized_keys.add(location)
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        failed_snapshot = RichTextRunSnapshot(
            unrecognized_rich_text_count=1,
            definition_signature=_rich_text_private_digest(
                ("rich-text-scan-failure", type(error).__name__)
            ),
        )
        return _RichTextRunMetadata(
            failed_snapshot,
            (
                "FormulaFence could not inspect rich-text run OOXML "
                f"({type(error).__name__}); affected character-level presentation "
                "controls were not compared.",
            ),
        )

    if issues or shared_unrecognized_indexes or inline_unrecognized_keys:
        warnings.add(
            "FormulaFence found malformed or unsupported rich-text run metadata; "
            "affected character-level presentation controls have a coverage gap."
        )
    signature_entries.extend(
        (f"rich-text-issue:{context}", detail)
        for context, detail in sorted(issues.items())
    )
    shared_rich_text_run_count = sum(
        shared_items[index].rich_run_count
        for index in shared_rich_text_indexes
        if shared_items is not None and shared_items[index] is not None
    )
    shared_phonetic_run_count = sum(
        shared_items[index].phonetic_run_count
        for index in shared_phonetic_indexes
        if shared_items is not None and shared_items[index] is not None
    )
    shared_phonetic_property_count = sum(
        shared_items[index].phonetic_property_count
        for index in shared_phonetic_indexes
        if shared_items is not None and shared_items[index] is not None
    )
    snapshot = RichTextRunSnapshot(
        shared_rich_text_item_count=len(shared_rich_text_indexes),
        shared_rich_text_cell_count=shared_rich_text_cell_count,
        shared_rich_text_run_count=shared_rich_text_run_count,
        inline_rich_text_cell_count=inline_rich_text_cell_count,
        inline_rich_text_run_count=inline_rich_text_run_count,
        phonetic_run_count=shared_phonetic_run_count + inline_phonetic_run_count,
        phonetic_property_count=(
            shared_phonetic_property_count + inline_phonetic_property_count
        ),
        unrecognized_rich_text_count=(
            len(issues)
            + len(shared_unrecognized_indexes)
            + len(inline_unrecognized_keys)
        ),
        definition_signature=(
            _private_external_data_signature(tuple(sorted(signature_entries)))
            if signature_entries
            else None
        ),
        entries=tuple(
            sorted(
                entries,
                key=lambda entry: (
                    entry.sheet.casefold(),
                    entry.coordinate.casefold(),
                ),
            )
        ),
    )
    return _RichTextRunMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _CellHyperlinkBudget:
    """Bounded raw worksheet XML reads for cell-hyperlink inspection."""

    remaining_bytes: int = _CELL_HYPERLINK_TOTAL_XML_MAX_BYTES
    remaining_parts: int = _CELL_HYPERLINK_TOTAL_XML_MAX_COUNT


@dataclass(frozen=True)
class _CellHyperlinkRawRelationship:
    """One private relationship referenced by a worksheet cell hyperlink."""

    relationship_id: str | None
    relationship_type: str
    target: str | None
    target_mode: str
    safe_target: str | None
    unknown_attributes: tuple[tuple[str, str], ...] = field(
        default=(), repr=False
    )

    def semantic_key(self) -> tuple[str, str, str]:
        """Return target semantics while ignoring a writer-selected relationship ID."""
        target = self.target or ""
        if self.target_mode.casefold() == "internal" and self.safe_target is not None:
            target = self.safe_target
        return (
            self.relationship_type,
            self.target_mode.casefold(),
            target,
        )


@dataclass(frozen=True)
class _CellHyperlinkWorksheetInspection:
    """Private result of parsing one worksheet's stored hyperlink declarations."""

    sheet: str
    member: str
    hyperlink_count: int = 0
    hyperlink_with_location_count: int = 0
    hyperlink_with_display_count: int = 0
    hyperlink_with_tooltip_count: int = 0
    binding_relationship_count: int = 0
    external_relationship_count: int = 0
    unrecognized_count: int = 0
    declaration_signature: str | None = None
    definition_signature: str | None = None
    relationship_signature: str | None = None

    @property
    def present(self) -> bool:
        return bool(self.hyperlink_count or self.unrecognized_count)


def _cell_hyperlink_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _CellHyperlinkBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded worksheet part before a reader can normalize links."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded cell-hyperlink worksheet XML part "
            "count budget; affected hyperlinks have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("cell-hyperlink-part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a worksheet XML part while inspecting "
            "cell hyperlinks; affected hyperlinks were not compared."
        )
        return None, _private_external_data_signature(
            (("missing-cell-hyperlink-worksheet", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _CELL_HYPERLINK_MAX_WORKSHEET_XML_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized worksheet XML part while "
            "inspecting cell hyperlinks; affected hyperlinks have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("oversized-cell-hyperlink-worksheet", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded cell-hyperlink worksheet XML read "
            "budget; affected hyperlinks have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("cell-hyperlink-read-budget-exhausted", metadata),)
        )
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a worksheet XML part while inspecting "
            f"cell hyperlinks ({type(error).__name__}); affected hyperlinks were "
            "not compared."
        )
        return None, _private_external_data_signature(
            (("unreadable-cell-hyperlink-worksheet", metadata),)
        )


def _cell_hyperlink_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
) -> tuple[_CellHyperlinkRawRelationship, ...] | None:
    """Read worksheet relationships without following hyperlink targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect worksheet relationships for cell "
            f"hyperlinks ({type(error).__name__}); affected hyperlinks were not "
            "compared."
        )
        return None
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected worksheet relationship root while "
            "inspecting cell hyperlinks; affected hyperlinks were not compared."
        )
        return None

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    known_attributes = frozenset({"Id", "Type", "Target", "TargetMode"})
    relationships: list[_CellHyperlinkRawRelationship] = []
    for child in root:
        if child.tag != relationship_tag:
            warnings.add(
                "FormulaFence found unmodelled relationship XML while inspecting "
                "cell hyperlinks; affected hyperlinks have a coverage gap."
            )
            return None
        target = child.get("Target")
        target_mode = child.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _CellHyperlinkRawRelationship(
                relationship_id=child.get("Id"),
                relationship_type=child.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
                unknown_attributes=tuple(
                    sorted(
                        (attribute, value)
                        for attribute, value in child.attrib.items()
                        if attribute not in known_attributes
                    )
                ),
            )
        )
    return tuple(relationships)


def _cell_hyperlink_reference(value: str | None) -> str | None:
    """Normalize a worksheet-local cell or range reference for one hyperlink."""
    if value is None or not (candidate := value.strip()):
        return None
    try:
        min_column, min_row, max_column, max_row = range_boundaries(candidate)
    except ValueError:
        return None
    if (
        min_column is None
        or min_row is None
        or max_column is None
        or max_row is None
        or min_column < 1
        or min_row < 1
        or max_column > MAX_EXCEL_COLUMN
        or max_row > MAX_EXCEL_ROW
    ):
        return None
    start = f"{get_column_letter(min_column)}{min_row}"
    end = f"{get_column_letter(max_column)}{max_row}"
    return start if start == end else f"{start}:{end}"


def _cell_hyperlink_worksheet_inspection(
    archive: ZipFile,
    *,
    sheet: str,
    member: str,
    archive_members: set[str],
    warnings: set[str],
    budget: _CellHyperlinkBudget,
) -> _CellHyperlinkWorksheetInspection:
    """Inspect one worksheet's standard and revision cell hyperlinks privately."""
    payload, fallback_signature = _cell_hyperlink_xml_payload(
        archive,
        member,
        warnings,
        budget,
    )
    if payload is None:
        return _CellHyperlinkWorksheetInspection(
            sheet=sheet,
            member=member,
            unrecognized_count=1,
            declaration_signature=fallback_signature,
            definition_signature=fallback_signature,
        )
    try:
        worksheet = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect worksheet XML for cell hyperlinks "
            f"({type(error).__name__}); affected hyperlinks were not compared."
        )
        return _CellHyperlinkWorksheetInspection(
            sheet=sheet,
            member=member,
            unrecognized_count=1,
            declaration_signature=_private_payload_signature(payload),
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
        or _xml_local_name(worksheet.tag) != "worksheet"
    ):
        warnings.add(
            "FormulaFence found a worksheet part with an unexpected root while "
            "inspecting cell hyperlinks; affected hyperlinks were not compared."
        )
        return _CellHyperlinkWorksheetInspection(
            sheet=sheet,
            member=member,
            unrecognized_count=1,
            declaration_signature=_private_payload_signature(payload),
            definition_signature=_private_payload_signature(payload),
        )

    hyperlink_container_tag = f"{{{_SPREADSHEETML_NS}}}hyperlinks"
    standard_hyperlink_tag = f"{{{_SPREADSHEETML_NS}}}hyperlink"
    revision_hyperlink_tag = f"{{{_OFFICE_2014_REVISION_NS}}}hyperlink"
    relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
    revision_uid_attribute = f"{{{_OFFICE_2014_REVISION_NS}}}uid"
    candidates: list[tuple[str, ElementTree.Element]] = []
    contained_standard_elements: set[int] = set()
    coverage_entries: list[tuple[str, str]] = []
    containers = list(worksheet.findall(hyperlink_container_tag))
    if len(containers) > 1:
        coverage_entries.append(
            ("multiple-cell-hyperlink-containers", str(len(containers)))
        )
    for container_index, container in enumerate(containers):
        if container.attrib or (
            container.text is not None and container.text.strip()
        ):
            coverage_entries.append(
                (
                    "malformed-cell-hyperlink-container",
                    repr((container_index, tuple(sorted(container.attrib.items())))),
                )
            )
        for child_index, child in enumerate(container):
            if child.tag != standard_hyperlink_tag:
                coverage_entries.append(
                    (
                        "unexpected-cell-hyperlink-container-child",
                        repr((container_index, child_index, _xml_display_name(child.tag))),
                    )
                )
                continue
            contained_standard_elements.add(id(child))
            candidates.append(("standard", child))
    for element in worksheet.iter(standard_hyperlink_tag):
        if id(element) in contained_standard_elements:
            continue
        coverage_entries.append(
            (
                "out-of-container-standard-cell-hyperlink",
                _private_payload_signature(
                    ElementTree.tostring(element, encoding="utf-8")
                ),
            )
        )
        candidates.append(("standard", element))
    for element in worksheet.iter(revision_hyperlink_tag):
        candidates.append(("revision", element))

    if not candidates and not coverage_entries:
        return _CellHyperlinkWorksheetInspection(sheet=sheet, member=member)

    has_relationship_reference = any(
        element.get(relationship_attribute) is not None
        for _kind, element in candidates
    )
    relationships: tuple[_CellHyperlinkRawRelationship, ...] | None = ()
    if has_relationship_reference:
        relationships = _cell_hyperlink_raw_relationships(archive, member, warnings)
        if relationships is None:
            coverage_entries.append(
                ("unreadable-cell-hyperlink-relationships", member)
            )
            relationships = ()

    relationships_by_id: dict[str, list[_CellHyperlinkRawRelationship]] = defaultdict(
        list
    )
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
    for relationship_id, matches in relationships_by_id.items():
        if len(matches) > 1:
            coverage_entries.append(
                (
                    "duplicate-cell-hyperlink-relationship-id",
                    repr((relationship_id, len(matches))),
                )
            )

    known_attributes = frozenset(
        {
            "ref",
            "location",
            "display",
            "tooltip",
            relationship_attribute,
            revision_uid_attribute,
        }
    )
    definition_entries: list[tuple[str, str]] = []
    declaration_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    selected_relationships: dict[str, _CellHyperlinkRawRelationship] = {}
    seen_references: dict[tuple[str, str], int] = defaultdict(int)
    hyperlink_with_location_count = 0
    hyperlink_with_display_count = 0
    hyperlink_with_tooltip_count = 0

    for index, (kind, hyperlink) in enumerate(candidates):
        raw_reference = hyperlink.get("ref")
        reference = _cell_hyperlink_reference(raw_reference)
        if reference is None:
            coverage_entries.append(
                (
                    "invalid-cell-hyperlink-reference",
                    repr((kind, index, raw_reference or "")),
                )
            )
            reference_material: object = ("invalid", raw_reference or "")
        else:
            reference_material = reference
            seen_references[(kind, reference)] += 1

        location = hyperlink.get("location")
        display = hyperlink.get("display")
        tooltip = hyperlink.get("tooltip")
        relationship_id = hyperlink.get(relationship_attribute)
        if location is not None:
            hyperlink_with_location_count += 1
        if display is not None:
            hyperlink_with_display_count += 1
        if tooltip is not None:
            hyperlink_with_tooltip_count += 1
        if not relationship_id and not location:
            coverage_entries.append(
                (
                    "cell-hyperlink-without-target",
                    repr((kind, index, reference_material)),
                )
            )
        if relationship_id and relationship_id not in relationships_by_id:
            coverage_entries.append(
                (
                    "unbound-cell-hyperlink-relationship",
                    repr((kind, index, relationship_id)),
                )
            )

        relationship_material: object = None
        if relationship_id and (matches := relationships_by_id.get(relationship_id)):
            relationship = matches[0]
            selected_relationships[relationship_id] = relationship
            relationship_material = relationship.semantic_key()
            if (
                relationship.relationship_type.casefold()
                != _CELL_HYPERLINK_RELATIONSHIP.casefold()
            ):
                coverage_entries.append(
                    (
                        "wrong-cell-hyperlink-relationship-type",
                        repr((kind, index, relationship.semantic_key())),
                    )
                )
            if relationship.target is None:
                coverage_entries.append(
                    (
                        "cell-hyperlink-relationship-without-target",
                        repr((kind, index, relationship.semantic_key())),
                    )
                )
            if relationship.target_mode.casefold() not in {"internal", "external"}:
                coverage_entries.append(
                    (
                        "invalid-cell-hyperlink-target-mode",
                        repr((kind, index, relationship.semantic_key())),
                    )
                )
            if (
                relationship.target_mode.casefold() == "internal"
                and (
                    relationship.safe_target is None
                    or relationship.safe_target not in archive_members
                )
            ):
                coverage_entries.append(
                    (
                        "unsafe-internal-cell-hyperlink-relationship",
                        repr((kind, index, relationship.semantic_key())),
                    )
                )
            if relationship.unknown_attributes:
                coverage_entries.append(
                    (
                        "unsupported-cell-hyperlink-relationship-attributes",
                        repr(
                            (
                                kind,
                                index,
                                relationship.semantic_key(),
                                relationship.unknown_attributes,
                            )
                        ),
                    )
                )

        unknown_attributes = tuple(
            sorted(
                (attribute, value)
                for attribute, value in hyperlink.attrib.items()
                if attribute not in known_attributes
            )
        )
        if unknown_attributes:
            coverage_entries.append(
                (
                    "unsupported-cell-hyperlink-attributes",
                    repr((kind, index, unknown_attributes)),
                )
            )
        if list(hyperlink) or (
            hyperlink.text is not None and hyperlink.text.strip()
        ):
            coverage_entries.append(
                (
                    "nonleaf-cell-hyperlink",
                    _private_payload_signature(
                        ElementTree.tostring(hyperlink, encoding="utf-8")
                    ),
                )
            )

        binding_material = (
            kind,
            reference_material,
            relationship_material,
            location or "",
        )
        declaration_entries.append(
            ("cell-hyperlink-binding", repr((sheet, binding_material)))
        )
        definition_entries.append(
            (
                "cell-hyperlink-definition",
                repr(
                    (
                        sheet,
                        binding_material,
                        display or "",
                        tooltip or "",
                        unknown_attributes,
                    )
                ),
            )
        )

    for (kind, reference), count in seen_references.items():
        if count > 1:
            coverage_entries.append(
                (
                    "duplicate-cell-hyperlink-reference",
                    repr((kind, reference, count)),
                )
            )
    selected_relationship_ids = set(selected_relationships)
    for relationship in relationships:
        if (
            relationship.relationship_type.casefold()
            == _CELL_HYPERLINK_RELATIONSHIP.casefold()
            and relationship.relationship_id not in selected_relationship_ids
        ):
            coverage_entries.append(
                (
                    "unbound-cell-hyperlink-relationship",
                    repr(relationship.semantic_key()),
                )
            )
    relationship_entries.extend(
        (
            "cell-hyperlink-relationship",
            repr(relationship.semantic_key()),
        )
        for relationship in selected_relationships.values()
    )
    declaration_entries.extend(coverage_entries)
    definition_entries.extend(coverage_entries)
    return _CellHyperlinkWorksheetInspection(
        sheet=sheet,
        member=member,
        hyperlink_count=len(candidates),
        hyperlink_with_location_count=hyperlink_with_location_count,
        hyperlink_with_display_count=hyperlink_with_display_count,
        hyperlink_with_tooltip_count=hyperlink_with_tooltip_count,
        binding_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() == "external"
            for relationship in selected_relationships.values()
        ),
        unrecognized_count=len(coverage_entries),
        declaration_signature=_private_external_data_signature(
            tuple(sorted(declaration_entries))
        ),
        definition_signature=_private_external_data_signature(
            tuple(sorted(definition_entries))
        ),
        relationship_signature=_private_external_data_signature(
            tuple(sorted(relationship_entries))
        ),
    )


def _cell_hyperlink_metadata(path: Path) -> _CellHyperlinkMetadata:
    """Inspect raw cell hyperlinks before the ordinary reader normalizes them."""
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _CellHyperlinkMetadata(
                    CellHyperlinkSnapshot(
                        unrecognized_cell_hyperlink_count=1,
                        definition_signature=_private_external_data_signature(
                            (("cell-hyperlink-sheet-part-scan-failure", type(error).__name__),)
                        ),
                    ),
                    (
                        "FormulaFence could not inspect worksheet OOXML parts for "
                        f"cell hyperlinks ({type(error).__name__}); affected "
                        "hyperlinks were not compared.",
                    ),
                )

            budget = _CellHyperlinkBudget()
            archive_members = set(archive.namelist())
            inspections = [
                _cell_hyperlink_worksheet_inspection(
                    archive,
                    sheet=sheet,
                    member=member,
                    archive_members=archive_members,
                    warnings=warnings,
                    budget=budget,
                )
                for sheet, (member, sheet_kind) in sorted(
                    sheet_parts.items(),
                    key=lambda item: item[0].casefold(),
                )
                if sheet_kind == "worksheet"
            ]
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _CellHyperlinkMetadata(
            CellHyperlinkSnapshot(
                unrecognized_cell_hyperlink_count=1,
                definition_signature=_private_external_data_signature(
                    (("cell-hyperlink-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect cell-hyperlink OOXML "
                f"({type(error).__name__}); affected hyperlinks were not compared.",
            ),
        )

    if any(inspection.unrecognized_count for inspection in inspections):
        warnings.add(
            "FormulaFence found malformed, unbound, or unsupported cell-hyperlink "
            "metadata; affected hyperlinks have a coverage gap."
        )
    present_inspections = [inspection for inspection in inspections if inspection.present]
    snapshot = CellHyperlinkSnapshot(
        worksheet_hyperlink_sheet_count=len(present_inspections),
        hyperlink_count=sum(
            inspection.hyperlink_count for inspection in present_inspections
        ),
        hyperlink_with_location_count=sum(
            inspection.hyperlink_with_location_count
            for inspection in present_inspections
        ),
        hyperlink_with_display_count=sum(
            inspection.hyperlink_with_display_count
            for inspection in present_inspections
        ),
        hyperlink_with_tooltip_count=sum(
            inspection.hyperlink_with_tooltip_count
            for inspection in present_inspections
        ),
        binding_relationship_count=sum(
            inspection.binding_relationship_count
            for inspection in present_inspections
        ),
        external_relationship_count=sum(
            inspection.external_relationship_count
            for inspection in present_inspections
        ),
        unrecognized_cell_hyperlink_count=sum(
            inspection.unrecognized_count for inspection in present_inspections
        ),
        declaration_signature=_private_external_data_signature(
            tuple(
                sorted(
                    (
                        "cell-hyperlink-worksheet",
                        repr((inspection.sheet, inspection.declaration_signature)),
                    )
                    for inspection in present_inspections
                )
            )
        ),
        definition_signature=_private_external_data_signature(
            tuple(
                sorted(
                    (
                        "cell-hyperlink-definition",
                        repr((inspection.sheet, inspection.definition_signature)),
                    )
                    for inspection in present_inspections
                )
            )
        ),
        relationship_signature=_private_external_data_signature(
            tuple(
                sorted(
                    (
                        "cell-hyperlink-relationships",
                        repr((inspection.sheet, inspection.relationship_signature)),
                    )
                    for inspection in present_inspections
                )
            )
        ),
    )
    return _CellHyperlinkMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _WorksheetSparklineBudget:
    """Bounded raw worksheet XML reads for worksheet-sparkline inspection."""

    remaining_bytes: int = _WORKSHEET_SPARKLINE_TOTAL_XML_MAX_BYTES
    remaining_parts: int = _WORKSHEET_SPARKLINE_TOTAL_XML_MAX_COUNT


@dataclass(frozen=True)
class _WorksheetSparklineWorksheetInspection:
    """Private result of parsing one worksheet's x14 sparkline extensions."""

    sheet: str
    member: str
    sparkline_group_count: int = 0
    sparkline_count: int = 0
    sparkline_with_source_count: int = 0
    group_date_axis_source_count: int = 0
    color_control_count: int = 0
    unrecognized_count: int = 0
    binding_signature: str | None = None
    definition_signature: str | None = None

    @property
    def present(self) -> bool:
        return bool(
            self.sparkline_group_count
            or self.sparkline_count
            or self.unrecognized_count
        )


def _worksheet_sparkline_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetSparklineBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded worksheet part before the ordinary reader drops x14 data."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded worksheet-sparkline XML part count "
            "budget; affected sparklines have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("worksheet-sparkline-part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a worksheet XML part while inspecting "
            "worksheet sparklines; affected sparklines were not compared."
        )
        return None, _private_external_data_signature(
            (("missing-worksheet-sparkline-worksheet", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _WORKSHEET_SPARKLINE_MAX_WORKSHEET_XML_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized worksheet XML part while "
            "inspecting worksheet sparklines; affected sparklines have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("oversized-worksheet-sparkline-worksheet", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded worksheet-sparkline XML read budget; "
            "affected sparklines have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("worksheet-sparkline-read-budget-exhausted", metadata),)
        )
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a worksheet XML part while inspecting "
            f"worksheet sparklines ({type(error).__name__}); affected sparklines "
            "were not compared."
        )
        return None, _private_external_data_signature(
            (("unreadable-worksheet-sparkline-worksheet", metadata),)
        )


def _worksheet_sparkline_boolean(value: str) -> str | None:
    """Normalise an XML boolean without accepting a non-standard spelling."""
    return {
        "0": "false",
        "false": "false",
        "1": "true",
        "true": "true",
    }.get(value.strip().casefold())


def _worksheet_sparkline_decimal(value: str) -> str | None:
    """Normalise a finite XML decimal without evaluating it."""
    try:
        decimal = Decimal(value.strip())
    except (InvalidOperation, ValueError):
        return None
    if not decimal.is_finite():
        return None
    normalised = decimal.normalize()
    return "0" if normalised == 0 else format(normalised, "f")


def _worksheet_sparkline_formula_material(
    value: str | None,
    *,
    sheet: str,
) -> tuple[object, ...] | None:
    """Retain a private source formula while normalising a direct local range."""
    candidate = (value or "").strip()
    if not candidate:
        return None
    reference = parse_reference_token(candidate)
    if (
        reference is not None
        and not reference.is_external
        and reference.min_column is not None
        and reference.min_row is not None
        and reference.max_column is not None
        and reference.max_row is not None
    ):
        return (
            "range",
            (reference.sheet or sheet).casefold(),
            reference.min_column,
            reference.min_row,
            reference.max_column,
            reference.max_row,
        )
    return ("formula", candidate)


def _worksheet_sparkline_destination(value: str | None) -> str | None:
    """Normalise the required single-cell destination from a sparkline sqref."""
    if value is None or not (candidate := value.strip()):
        return None
    try:
        min_column, min_row, max_column, max_row = range_boundaries(candidate)
    except ValueError:
        return None
    if (
        min_column is None
        or min_row is None
        or max_column is None
        or max_row is None
        or min_column != max_column
        or min_row != max_row
        or min_column < 1
        or min_row < 1
        or max_column > MAX_EXCEL_COLUMN
        or max_row > MAX_EXCEL_ROW
    ):
        return None
    return f"{get_column_letter(min_column)}{min_row}"


def _worksheet_sparkline_group_attributes(
    group: ElementTree.Element,
    *,
    context: tuple[object, ...],
    coverage_entries: list[tuple[str, str]],
) -> tuple[tuple[str, str], ...]:
    """Normalise the supported x14:sparklineGroup attribute vocabulary."""
    boolean_attributes = frozenset(
        {
            "dateAxis",
            "displayHidden",
            "displayXAxis",
            "first",
            "high",
            "last",
            "low",
            "markers",
            "negative",
            "rightToLeft",
        }
    )
    decimal_attributes = frozenset({"lineWeight", "manualMax", "manualMin"})
    enum_values = {
        "displayEmptyCellsAs": frozenset({"gap", "span", "zero"}),
        "maxAxisType": frozenset({"custom", "group", "individual"}),
        "minAxisType": frozenset({"custom", "group", "individual"}),
        "type": frozenset({"column", "line", "stacked"}),
    }
    known_attributes = boolean_attributes | decimal_attributes | frozenset(enum_values)
    attribute_values: dict[str, str] = {}
    material: list[tuple[str, str]] = []
    for attribute, value in sorted(group.attrib.items()):
        attribute_name = _xml_local_name(attribute)
        attribute_values[attribute_name] = value
        if attribute_name not in known_attributes or _xml_namespace(attribute):
            coverage_entries.append(
                (
                    "unsupported-worksheet-sparkline-group-attribute",
                    repr((context, attribute, value)),
                )
            )
            material.append((attribute, value))
            continue
        if attribute_name in boolean_attributes:
            normalised = _worksheet_sparkline_boolean(value)
        elif attribute_name in decimal_attributes:
            normalised = _worksheet_sparkline_decimal(value)
        else:
            normalised = value.strip().casefold()
            if normalised not in enum_values[attribute_name]:
                normalised = None
        if normalised is None:
            coverage_entries.append(
                (
                    "invalid-worksheet-sparkline-group-attribute",
                    repr((context, attribute_name, value)),
                )
            )
            normalised = value
        material.append((attribute_name, normalised))

    line_weight = attribute_values.get("lineWeight")
    if line_weight is not None:
        normalised_weight = _worksheet_sparkline_decimal(line_weight)
        if normalised_weight is None or not (
            Decimal("0") <= Decimal(normalised_weight) <= Decimal("1584")
        ):
            coverage_entries.append(
                (
                    "invalid-worksheet-sparkline-line-weight",
                    repr((context, line_weight)),
                )
            )
    if (
        "manualMax" in attribute_values
        and attribute_values.get("maxAxisType", "").casefold() != "custom"
    ):
        coverage_entries.append(
            (
                "worksheet-sparkline-manual-max-without-custom-axis",
                repr(context),
            )
        )
    if (
        "manualMin" in attribute_values
        and attribute_values.get("minAxisType", "").casefold() != "custom"
    ):
        coverage_entries.append(
            (
                "worksheet-sparkline-manual-min-without-custom-axis",
                repr(context),
            )
        )
    return tuple(material)


def _worksheet_sparkline_color_material(
    color: ElementTree.Element,
    *,
    context: tuple[object, ...],
    coverage_entries: list[tuple[str, str]],
) -> tuple[tuple[str, str], ...]:
    """Return private CT_Color material while failing closed on extensions."""
    known_attributes = frozenset({"auto", "indexed", "rgb", "theme", "tint"})
    material: list[tuple[str, str]] = []
    for attribute, value in sorted(color.attrib.items()):
        attribute_name = _xml_local_name(attribute)
        normalised = value
        if attribute_name not in known_attributes or _xml_namespace(attribute):
            coverage_entries.append(
                (
                    "unsupported-worksheet-sparkline-colour-attribute",
                    repr((context, attribute, value)),
                )
            )
        elif attribute_name == "auto":
            boolean = _worksheet_sparkline_boolean(value)
            if boolean is None:
                coverage_entries.append(
                    (
                        "invalid-worksheet-sparkline-colour-auto",
                        repr((context, value)),
                    )
                )
            else:
                normalised = boolean
        elif attribute_name == "rgb":
            normalised = value.upper()
        elif attribute_name == "tint":
            normalised = _worksheet_sparkline_decimal(value) or value
            if normalised == value and _worksheet_sparkline_decimal(value) is None:
                coverage_entries.append(
                    (
                        "invalid-worksheet-sparkline-colour-tint",
                        repr((context, value)),
                    )
                )
        material.append((attribute_name, normalised))
    if list(color) or (color.text is not None and color.text.strip()):
        coverage_entries.append(
            (
                "nonleaf-worksheet-sparkline-colour",
                _private_payload_signature(
                    ElementTree.tostring(color, encoding="utf-8")
                ),
            )
        )
    return tuple(material)


def _worksheet_sparkline_worksheet_inspection(
    archive: ZipFile,
    *,
    sheet: str,
    member: str,
    warnings: set[str],
    budget: _WorksheetSparklineBudget,
) -> _WorksheetSparklineWorksheetInspection:
    """Inspect a worksheet's Office 2010 sparkline extension privately."""
    payload, fallback_signature = _worksheet_sparkline_xml_payload(
        archive,
        member,
        warnings,
        budget,
    )
    if payload is None:
        return _WorksheetSparklineWorksheetInspection(
            sheet=sheet,
            member=member,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        worksheet = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect worksheet XML for worksheet sparklines "
            f"({type(error).__name__}); affected sparklines were not compared."
        )
        return _WorksheetSparklineWorksheetInspection(
            sheet=sheet,
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
        or _xml_local_name(worksheet.tag) != "worksheet"
    ):
        warnings.add(
            "FormulaFence found a worksheet part with an unexpected root while "
            "inspecting worksheet sparklines; affected sparklines were not compared."
        )
        return _WorksheetSparklineWorksheetInspection(
            sheet=sheet,
            member=member,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    extension_list_tag = f"{{{_SPREADSHEETML_NS}}}extLst"
    extension_tag = f"{{{_SPREADSHEETML_NS}}}ext"
    group_container_tag = f"{{{_OFFICE_2010_SPREADSHEET_NS}}}sparklineGroups"
    group_tag = f"{{{_OFFICE_2010_SPREADSHEET_NS}}}sparklineGroup"
    sparklines_tag = f"{{{_OFFICE_2010_SPREADSHEET_NS}}}sparklines"
    sparkline_tag = f"{{{_OFFICE_2010_SPREADSHEET_NS}}}sparkline"
    formula_tag = f"{{{_EXCEL_2006_MAIN_NS}}}f"
    destination_tag = f"{{{_EXCEL_2006_MAIN_NS}}}sqref"
    colour_names = frozenset(
        {
            "colorAxis",
            "colorFirst",
            "colorHigh",
            "colorLast",
            "colorLow",
            "colorMarkers",
            "colorNegative",
            "colorSeries",
        }
    )
    colour_tags = {
        f"{{{_OFFICE_2010_SPREADSHEET_NS}}}{name}" for name in colour_names
    }
    coverage_entries: list[tuple[str, str]] = []
    accepted_containers: list[ElementTree.Element] = []
    accepted_container_ids: set[int] = set()
    for extension_list_index, extension_list in enumerate(
        worksheet.findall(extension_list_tag)
    ):
        for extension_index, extension in enumerate(extension_list):
            if extension.tag != extension_tag:
                continue
            if (
                extension.get("uri", "").casefold()
                != _WORKSHEET_SPARKLINE_EXTENSION_URI.casefold()
            ):
                continue
            context = (sheet, extension_list_index, extension_index)
            if set(extension.attrib) != {"uri"} or (
                extension.text is not None and extension.text.strip()
            ):
                coverage_entries.append(
                    (
                        "malformed-worksheet-sparkline-extension",
                        repr((context, tuple(sorted(extension.attrib.items())))),
                    )
                )
            containers = [
                child for child in extension if child.tag == group_container_tag
            ]
            if len(containers) != 1:
                coverage_entries.append(
                    (
                        "invalid-worksheet-sparkline-group-container-count",
                        repr((context, len(containers))),
                    )
                )
            for child_index, child in enumerate(extension):
                if child.tag != group_container_tag:
                    coverage_entries.append(
                        (
                            "unexpected-worksheet-sparkline-extension-child",
                            repr((context, child_index, _xml_display_name(child.tag))),
                        )
                    )
            accepted_containers.extend(containers)
            accepted_container_ids.update(id(container) for container in containers)

    for container in worksheet.iter(group_container_tag):
        if id(container) in accepted_container_ids:
            continue
        coverage_entries.append(
            (
                "out-of-container-worksheet-sparkline-groups",
                _private_payload_signature(
                    ElementTree.tostring(container, encoding="utf-8")
                ),
            )
        )

    if not accepted_containers and not coverage_entries:
        return _WorksheetSparklineWorksheetInspection(sheet=sheet, member=member)

    binding_entries: list[tuple[str, str]] = []
    definition_entries: list[tuple[str, str]] = []
    sparkline_group_count = 0
    sparkline_count = 0
    sparkline_with_source_count = 0
    group_date_axis_source_count = 0
    colour_control_count = 0
    destinations: dict[str, int] = defaultdict(int)

    for container_index, container in enumerate(accepted_containers):
        container_context = (sheet, container_index)
        if container.attrib or (
            container.text is not None and container.text.strip()
        ):
            coverage_entries.append(
                (
                    "malformed-worksheet-sparkline-groups",
                    repr((container_context, tuple(sorted(container.attrib.items())))),
                )
            )
        groups: list[ElementTree.Element] = []
        for child_index, child in enumerate(container):
            if child.tag != group_tag:
                coverage_entries.append(
                    (
                        "unexpected-worksheet-sparkline-groups-child",
                        repr(
                            (
                                container_context,
                                child_index,
                                _xml_display_name(child.tag),
                            )
                        ),
                    )
                )
                continue
            groups.append(child)
        if not groups:
            coverage_entries.append(
                ("empty-worksheet-sparkline-groups", repr(container_context))
            )

        for group_index, group in enumerate(groups):
            sparkline_group_count += 1
            group_context = (sheet, container_index, group_index)
            if group.text is not None and group.text.strip():
                coverage_entries.append(
                    (
                        "nonleaf-worksheet-sparkline-group",
                        _private_payload_signature(
                            ElementTree.tostring(group, encoding="utf-8")
                        ),
                    )
                )
            group_attributes = _worksheet_sparkline_group_attributes(
                group,
                context=group_context,
                coverage_entries=coverage_entries,
            )
            children_by_tag: dict[str, list[ElementTree.Element]] = defaultdict(list)
            for child_index, child in enumerate(group):
                if child.tag not in colour_tags | {formula_tag, sparklines_tag}:
                    coverage_entries.append(
                        (
                            "unexpected-worksheet-sparkline-group-child",
                            repr(
                                (
                                    group_context,
                                    child_index,
                                    _xml_display_name(child.tag),
                                )
                            ),
                        )
                    )
                    continue
                children_by_tag[child.tag].append(child)

            colours: list[tuple[str, tuple[tuple[str, str], ...]]] = []
            for colour_tag in sorted(colour_tags):
                colour_elements = children_by_tag.get(colour_tag, [])
                if len(colour_elements) > 1:
                    coverage_entries.append(
                        (
                            "duplicate-worksheet-sparkline-colour",
                            repr((group_context, _xml_local_name(colour_tag))),
                        )
                    )
                for colour_index, colour in enumerate(colour_elements):
                    colour_control_count += 1
                    colours.append(
                        (
                            _xml_local_name(colour.tag),
                            _worksheet_sparkline_color_material(
                                colour,
                                context=(
                                    *group_context,
                                    _xml_local_name(colour.tag),
                                    colour_index,
                                ),
                                coverage_entries=coverage_entries,
                            ),
                        )
                    )

            group_formula_elements = children_by_tag.get(formula_tag, [])
            if len(group_formula_elements) > 1:
                coverage_entries.append(
                    (
                        "duplicate-worksheet-sparkline-group-formula",
                        repr(group_context),
                    )
                )
            group_formula_material: tuple[object, ...] | None = None
            if group_formula_elements:
                group_formula = group_formula_elements[0]
                if group_formula.attrib or list(group_formula):
                    coverage_entries.append(
                        (
                            "malformed-worksheet-sparkline-group-formula",
                            _private_payload_signature(
                                ElementTree.tostring(group_formula, encoding="utf-8")
                            ),
                        )
                    )
                group_formula_material = _worksheet_sparkline_formula_material(
                    group_formula.text,
                    sheet=sheet,
                )
                if group_formula_material is None:
                    coverage_entries.append(
                        (
                            "empty-worksheet-sparkline-group-formula",
                            repr(group_context),
                        )
                    )
                else:
                    group_date_axis_source_count += 1

            sparklines_containers = children_by_tag.get(sparklines_tag, [])
            if len(sparklines_containers) != 1:
                coverage_entries.append(
                    (
                        "invalid-worksheet-sparklines-container-count",
                        repr((group_context, len(sparklines_containers))),
                    )
                )
            sparkline_definitions: list[tuple[object, ...]] = []
            for sparklines_index, sparklines in enumerate(sparklines_containers):
                sparklines_context = (*group_context, sparklines_index)
                if sparklines.attrib or (
                    sparklines.text is not None and sparklines.text.strip()
                ):
                    coverage_entries.append(
                        (
                            "malformed-worksheet-sparklines-container",
                            repr(
                                (
                                    sparklines_context,
                                    tuple(sorted(sparklines.attrib.items())),
                                )
                            ),
                        )
                    )
                sparkline_elements: list[ElementTree.Element] = []
                for child_index, child in enumerate(sparklines):
                    if child.tag != sparkline_tag:
                        coverage_entries.append(
                            (
                                "unexpected-worksheet-sparklines-child",
                                repr(
                                    (
                                        sparklines_context,
                                        child_index,
                                        _xml_display_name(child.tag),
                                    )
                                ),
                            )
                        )
                        continue
                    sparkline_elements.append(child)
                if not sparkline_elements:
                    coverage_entries.append(
                        (
                            "empty-worksheet-sparklines-container",
                            repr(sparklines_context),
                        )
                    )

                for sparkline_index, sparkline in enumerate(sparkline_elements):
                    sparkline_count += 1
                    sparkline_context = (*sparklines_context, sparkline_index)
                    if sparkline.attrib or (
                        sparkline.text is not None and sparkline.text.strip()
                    ):
                        coverage_entries.append(
                            (
                                "malformed-worksheet-sparkline",
                                _private_payload_signature(
                                    ElementTree.tostring(sparkline, encoding="utf-8")
                                ),
                            )
                        )
                    sparkline_children: dict[str, list[ElementTree.Element]] = (
                        defaultdict(list)
                    )
                    for child_index, child in enumerate(sparkline):
                        if child.tag not in {formula_tag, destination_tag}:
                            coverage_entries.append(
                                (
                                    "unexpected-worksheet-sparkline-child",
                                    repr(
                                        (
                                            sparkline_context,
                                            child_index,
                                            _xml_display_name(child.tag),
                                        )
                                    ),
                                )
                            )
                            continue
                        sparkline_children[child.tag].append(child)

                    source_elements = sparkline_children.get(formula_tag, [])
                    if len(source_elements) > 1:
                        coverage_entries.append(
                            (
                                "duplicate-worksheet-sparkline-source",
                                repr(sparkline_context),
                            )
                        )
                    source_material: tuple[object, ...] | None = None
                    if source_elements:
                        source = source_elements[0]
                        if source.attrib or list(source):
                            coverage_entries.append(
                                (
                                    "malformed-worksheet-sparkline-source",
                                    _private_payload_signature(
                                        ElementTree.tostring(source, encoding="utf-8")
                                    ),
                                )
                            )
                        source_material = _worksheet_sparkline_formula_material(
                            source.text,
                            sheet=sheet,
                        )
                        if source_material is None:
                            coverage_entries.append(
                                (
                                    "empty-worksheet-sparkline-source",
                                    repr(sparkline_context),
                                )
                            )
                        else:
                            sparkline_with_source_count += 1
                            if (
                                source_material[0] == "range"
                                and source_material[2] != source_material[4]
                                and source_material[3] != source_material[5]
                            ):
                                coverage_entries.append(
                                    (
                                        "nonlinear-worksheet-sparkline-source",
                                        repr((sparkline_context, source_material)),
                                    )
                                )

                    destination_elements = sparkline_children.get(destination_tag, [])
                    if len(destination_elements) != 1:
                        coverage_entries.append(
                            (
                                "invalid-worksheet-sparkline-destination-count",
                                repr((sparkline_context, len(destination_elements))),
                            )
                        )
                    destination_material: object = ("missing",)
                    if destination_elements:
                        destination = destination_elements[0]
                        if destination.attrib or list(destination):
                            coverage_entries.append(
                                (
                                    "malformed-worksheet-sparkline-destination",
                                    _private_payload_signature(
                                        ElementTree.tostring(
                                            destination,
                                            encoding="utf-8",
                                        )
                                    ),
                                )
                            )
                        location = _worksheet_sparkline_destination(destination.text)
                        if location is None:
                            coverage_entries.append(
                                (
                                    "invalid-worksheet-sparkline-destination",
                                    repr(
                                        (
                                            sparkline_context,
                                            (destination.text or "").strip(),
                                        )
                                    ),
                                )
                            )
                            destination_material = (
                                "invalid",
                                (destination.text or "").strip(),
                            )
                        else:
                            destinations[location] += 1
                            destination_material = location

                    binding_material = (
                        group_formula_material,
                        source_material,
                        destination_material,
                    )
                    binding_entries.append(
                        (
                            "worksheet-sparkline-binding",
                            repr((sheet, binding_material)),
                        )
                    )
                    sparkline_definitions.append(binding_material)

            definition_entries.append(
                (
                    "worksheet-sparkline-group",
                    repr(
                        (
                            sheet,
                            group_attributes,
                            tuple(sorted(colours)),
                            group_formula_material,
                            tuple(sorted(sparkline_definitions, key=repr)),
                        )
                    ),
                )
            )

    for destination, count in destinations.items():
        if count > 1:
            coverage_entries.append(
                (
                    "duplicate-worksheet-sparkline-destination",
                    repr((sheet, destination, count)),
                )
            )
    definition_entries.extend(coverage_entries)
    return _WorksheetSparklineWorksheetInspection(
        sheet=sheet,
        member=member,
        sparkline_group_count=sparkline_group_count,
        sparkline_count=sparkline_count,
        sparkline_with_source_count=sparkline_with_source_count,
        group_date_axis_source_count=group_date_axis_source_count,
        color_control_count=colour_control_count,
        unrecognized_count=len(coverage_entries),
        binding_signature=_private_external_data_signature(
            tuple(sorted(binding_entries))
        ),
        definition_signature=_private_external_data_signature(
            tuple(sorted(definition_entries))
        ),
    )


def _worksheet_sparkline_metadata(path: Path) -> _WorksheetSparklineMetadata:
    """Inspect raw worksheet sparklines before the ordinary reader omits them."""
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _WorksheetSparklineMetadata(
                    WorksheetSparklineSnapshot(
                        unrecognized_worksheet_sparkline_count=1,
                        definition_signature=_private_external_data_signature(
                            (
                                (
                                    "worksheet-sparkline-sheet-part-scan-failure",
                                    type(error).__name__,
                                ),
                            )
                        ),
                    ),
                    (
                        "FormulaFence could not inspect worksheet OOXML parts for "
                        f"worksheet sparklines ({type(error).__name__}); affected "
                        "sparklines were not compared.",
                    ),
                )
            budget = _WorksheetSparklineBudget()
            inspections = [
                _worksheet_sparkline_worksheet_inspection(
                    archive,
                    sheet=sheet,
                    member=member,
                    warnings=warnings,
                    budget=budget,
                )
                for sheet, (member, sheet_kind) in sorted(
                    sheet_parts.items(),
                    key=lambda item: item[0].casefold(),
                )
                if sheet_kind == "worksheet"
            ]
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _WorksheetSparklineMetadata(
            WorksheetSparklineSnapshot(
                unrecognized_worksheet_sparkline_count=1,
                definition_signature=_private_external_data_signature(
                    (("worksheet-sparkline-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect worksheet-sparkline OOXML "
                f"({type(error).__name__}); affected sparklines were not compared.",
            ),
        )

    if any(inspection.unrecognized_count for inspection in inspections):
        warnings.add(
            "FormulaFence found malformed or unsupported worksheet-sparkline "
            "metadata; affected sparklines have a coverage gap."
        )
    present_inspections = [inspection for inspection in inspections if inspection.present]
    snapshot = WorksheetSparklineSnapshot(
        worksheet_sparkline_sheet_count=len(present_inspections),
        sparkline_group_count=sum(
            inspection.sparkline_group_count for inspection in present_inspections
        ),
        sparkline_count=sum(
            inspection.sparkline_count for inspection in present_inspections
        ),
        sparkline_with_source_count=sum(
            inspection.sparkline_with_source_count
            for inspection in present_inspections
        ),
        group_date_axis_source_count=sum(
            inspection.group_date_axis_source_count
            for inspection in present_inspections
        ),
        color_control_count=sum(
            inspection.color_control_count for inspection in present_inspections
        ),
        unrecognized_worksheet_sparkline_count=sum(
            inspection.unrecognized_count for inspection in present_inspections
        ),
        binding_signature=_private_external_data_signature(
            tuple(
                sorted(
                    (
                        "worksheet-sparkline-bindings",
                        repr((inspection.sheet, inspection.binding_signature)),
                    )
                    for inspection in present_inspections
                )
            )
        ),
        definition_signature=_private_external_data_signature(
            tuple(
                sorted(
                    (
                        "worksheet-sparkline-definition",
                        repr((inspection.sheet, inspection.definition_signature)),
                    )
                    for inspection in present_inspections
                )
            )
        ),
    )
    return _WorksheetSparklineMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _XmlMappingBudget:
    """Bound raw XML reads across XML-map declarations and bindings."""

    remaining_parts: int = _XML_MAPPING_TOTAL_XML_PARTS
    remaining_bytes: int = _XML_MAPPING_TOTAL_XML_BYTES
    remaining_xml_elements: int = _XML_MAPPING_TOTAL_XML_MAX_ELEMENT_COUNT


@dataclass(frozen=True)
class _XmlMappingMapPartInspection:
    """Private result of inspecting one SpreadsheetML XML Maps part."""

    member: str
    schema_count: int = 0
    map_count: int = 0
    data_binding_count: int = 0
    file_binding_count: int = 0
    connection_binding_count: int = 0
    map_ids: tuple[int, ...] = ()
    definition_signature: str | None = None
    issues: tuple[tuple[str, str], ...] = ()


def _xml_mapping_issue(
    issues: list[tuple[str, str]],
    context: str,
    detail: object,
) -> None:
    """Record private malformed XML-map evidence without serialising it."""
    issues.append((context, repr(detail)))


def _xml_mapping_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _XmlMappingBudget,
) -> str | None:
    """Stream XML-map XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _XML_MAPPING_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read an XML-mapping XML part whose XML "
        "structure exceeds the safety budget; affected XML mappings have a "
        "coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _xml_mapping_bounded_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _XmlMappingBudget,
    *,
    context: str,
) -> tuple[bytes | None, str | None]:
    """Read one XML-map package part within fixed scan budgets."""
    if budget.remaining_parts <= 0:
        warnings.add(
            "FormulaFence reached its bounded XML-mapping XML part count budget; "
            "affected XML mappings have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("xml-mapping-part-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate an XML-mapping package part; "
            "affected XML mappings were not compared."
        )
        return None, _private_external_data_signature(
            (("missing-xml-mapping-member", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _XML_MAPPING_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized XML-mapping XML part; "
            "affected XML mappings have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded XML-mapping XML read budget; "
            "affected XML mappings have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("xml-mapping-read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = (
        _xml_mapping_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            warnings,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read an XML-mapping XML package part "
            f"({type(error).__name__}); affected XML mappings were not compared."
        )
        return None, _private_external_data_signature(
            (("unreadable-xml-mapping-part", metadata),)
        )


def _xml_mapping_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _XmlMappingBudget,
    *,
    context: str,
) -> tuple[ElementTree.Element | None, str | None]:
    """Return one bounded XML-map root or a private failure signature."""
    payload, fallback_signature = _xml_mapping_bounded_payload(
        archive,
        member,
        warnings,
        budget,
        context=context,
    )
    if payload is None:
        return None, fallback_signature
    try:
        return _xml_root_from_payload(payload), None
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not parse an XML-mapping XML package part "
            f"({type(error).__name__}); affected XML mappings were not compared."
        )
        return None, _private_payload_signature(payload)


def _xml_mapping_unsigned(
    value: str | None,
    issues: list[tuple[str, str]],
    *,
    context: str,
    required: bool = True,
) -> int | None:
    """Read one unsigned XML-map identifier without accepting malformed input."""
    if value is None:
        if required:
            _xml_mapping_issue(issues, f"missing-{context}", None)
        return None
    candidate = value.strip()
    if not _XML_MAPPING_UNSIGNED_PATTERN.fullmatch(candidate):
        _xml_mapping_issue(issues, f"invalid-{context}", value)
        return None
    try:
        parsed = int(candidate)
    except ValueError:
        _xml_mapping_issue(issues, f"invalid-{context}", value)
        return None
    if not 0 <= parsed <= 4_294_967_295:
        _xml_mapping_issue(issues, f"out-of-range-{context}", value)
        return None
    return parsed


def _xml_mapping_boolean(
    value: str | None,
    issues: list[tuple[str, str]],
    *,
    context: str,
    default: bool | None = None,
) -> bool | None:
    """Normalize XML boolean spellings while preserving invalid evidence privately."""
    if value is None:
        if default is None:
            _xml_mapping_issue(issues, f"missing-{context}", None)
        return default
    candidate = value.strip()
    if candidate in {"1", "true"}:
        return True
    if candidate in {"0", "false"}:
        return False
    _xml_mapping_issue(issues, f"invalid-{context}", value)
    return None


def _xml_mapping_required_text(
    value: str | None,
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> str:
    """Retain required private text while marking absent or empty values unsafe."""
    candidate = value or ""
    if not candidate.strip():
        _xml_mapping_issue(issues, f"missing-{context}", value)
    return candidate


def _xml_mapping_unknown_material(
    element: ElementTree.Element,
    *,
    known_attributes: frozenset[str],
    known_children: frozenset[str],
    issues: list[tuple[str, str]],
    context: str,
) -> tuple[tuple[tuple[str, str], ...], tuple[tuple[object, ...], ...]]:
    """Retain unexpected XML-map material only inside a private signature."""
    attributes = tuple(
        sorted(
            (
                _xml_display_name(attribute),
                value,
            )
            for attribute, value in element.attrib.items()
            if (
                attribute != f"{{{_MARKUP_COMPATIBILITY_NS}}}Ignorable"
                and _xml_local_name(attribute) not in known_attributes
            )
        )
    )
    children = tuple(
        _xml_fragment(child).sort_key()
        for child in element
        if (
            _xml_namespace(child.tag) != _SPREADSHEETML_NS
            or _xml_local_name(child.tag) not in known_children
        )
    )
    if attributes:
        _xml_mapping_issue(issues, f"unknown-{context}-attributes", attributes)
    if children:
        _xml_mapping_issue(issues, f"unknown-{context}-children", children)
    return attributes, children


def _xml_mapping_binding_material(
    element: ElementTree.Element,
    issues: list[tuple[str, str]],
    *,
    context: str,
    table_column: bool,
) -> tuple[int | None, tuple[object, ...]]:
    """Canonicalize one private XML table or single-cell binding declaration."""
    map_id = _xml_mapping_unsigned(
        element.get("mapId"),
        issues,
        context=f"{context}-map-id",
    )
    xpath = _xml_mapping_required_text(
        element.get("xpath"),
        issues,
        context=f"{context}-xpath",
    )
    xml_data_type = _xml_mapping_required_text(
        element.get("xmlDataType"),
        issues,
        context=f"{context}-xml-data-type",
    )
    denormalized: bool | None = None
    known_attributes = {"mapId", "xpath", "xmlDataType"}
    if table_column:
        known_attributes.add("denormalized")
        denormalized = _xml_mapping_boolean(
            element.get("denormalized"),
            issues,
            context=f"{context}-denormalized",
            default=False,
        )
    unknown_attributes, unknown_children = _xml_mapping_unknown_material(
        element,
        known_attributes=frozenset(known_attributes),
        known_children=frozenset({"extLst"}),
        issues=issues,
        context=context,
    )
    extension_fragments = tuple(
        _xml_fragment(child).sort_key()
        for child in element
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) == "extLst"
        )
    )
    if extension_fragments:
        _xml_mapping_issue(
            issues,
            f"unrecognized-{context}-extensions",
            extension_fragments,
        )
    return (
        map_id,
        (
            map_id,
            xpath,
            xml_data_type,
            denormalized,
            unknown_attributes,
            extension_fragments,
            unknown_children,
        ),
    )


def _xml_mapping_map_part_inspection(
    root: ElementTree.Element,
    member: str,
) -> _XmlMappingMapPartInspection:
    """Inspect a SpreadsheetML XML Maps part without exposing its definitions."""
    issues: list[tuple[str, str]] = []
    if (
        _xml_namespace(root.tag) != _SPREADSHEETML_NS
        or _xml_local_name(root.tag) != "MapInfo"
    ):
        _xml_mapping_issue(
            issues,
            "unexpected-xml-map-root",
            _xml_fragment(root).sort_key(),
        )
        return _XmlMappingMapPartInspection(
            member=member,
            definition_signature=_private_payload_signature(
                ElementTree.tostring(root, encoding="utf-8")
            ),
            issues=tuple(issues),
        )

    raw_selection_namespaces = root.get("SelectionNamespaces")
    if raw_selection_namespaces is None:
        _xml_mapping_issue(
            issues,
            "missing-xml-map-selection-namespaces",
            None,
        )
        selection_namespaces = ""
    else:
        # Excel permits an empty namespace declaration when the map's XPath
        # expressions only use unqualified element names.
        selection_namespaces = raw_selection_namespaces
    root_unknown_attributes, root_unknown_children = _xml_mapping_unknown_material(
        root,
        known_attributes=frozenset({"SelectionNamespaces"}),
        known_children=frozenset({"Schema", "Map"}),
        issues=issues,
        context="xml-map-root",
    )
    schemas = [
        child
        for child in root
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) == "Schema"
        )
    ]
    maps = [
        child
        for child in root
        if (
            _xml_namespace(child.tag) == _SPREADSHEETML_NS
            and _xml_local_name(child.tag) == "Map"
        )
    ]
    if not schemas:
        _xml_mapping_issue(issues, "missing-xml-map-schemas", None)
    if not maps:
        _xml_mapping_issue(issues, "missing-xml-maps", None)
    seen_map = False
    for child_index, child in enumerate(root):
        if _xml_namespace(child.tag) != _SPREADSHEETML_NS:
            continue
        child_name = _xml_local_name(child.tag)
        if child_name == "Map":
            seen_map = True
        elif child_name == "Schema" and seen_map:
            _xml_mapping_issue(
                issues,
                "xml-map-schema-after-map",
                child_index,
            )

    schema_entries: list[tuple[str, str]] = []
    schema_ids: list[str] = []
    for schema_index, schema in enumerate(schemas):
        schema_id = _xml_mapping_required_text(
            schema.get("ID"),
            issues,
            context=f"xml-map-schema-{schema_index}-id",
        )
        schema_ids.append(schema_id)
        schema_unknown_attributes = tuple(
            sorted(
                (
                    _xml_display_name(attribute),
                    value,
                )
                for attribute, value in schema.attrib.items()
                if (
                    attribute != f"{{{_MARKUP_COMPATIBILITY_NS}}}Ignorable"
                    and _xml_local_name(attribute)
                    not in {"ID", "SchemaRef", "Namespace", "SchemaLanguage"}
                )
            )
        )
        if schema_unknown_attributes:
            _xml_mapping_issue(
                issues,
                f"unknown-xml-map-schema-{schema_index}-attributes",
                schema_unknown_attributes,
            )
        if len(schema) != 1:
            _xml_mapping_issue(
                issues,
                "invalid-xml-map-schema-content-count",
                (schema_index, len(schema)),
            )
        schema_entries.append(
            (
                "xml-map-schema",
                repr((schema_id, _xml_fragment(schema).sort_key())),
            )
        )
    for schema_id in sorted(
        {value for value in schema_ids if value},
        key=str.casefold,
    ):
        if schema_ids.count(schema_id) > 1:
            _xml_mapping_issue(
                issues,
                "duplicate-xml-map-schema-id",
                schema_id,
            )

    map_entries: list[tuple[str, str]] = []
    map_ids: list[int] = []
    data_binding_count = 0
    file_binding_count = 0
    connection_binding_count = 0
    for map_index, xml_map in enumerate(maps):
        map_id = _xml_mapping_unsigned(
            xml_map.get("ID"),
            issues,
            context=f"xml-map-{map_index}-id",
        )
        if map_id is not None:
            map_ids.append(map_id)
        name = _xml_mapping_required_text(
            xml_map.get("Name"),
            issues,
            context=f"xml-map-{map_index}-name",
        )
        root_element = _xml_mapping_required_text(
            xml_map.get("RootElement"),
            issues,
            context=f"xml-map-{map_index}-root-element",
        )
        schema_id = _xml_mapping_required_text(
            xml_map.get("SchemaID"),
            issues,
            context=f"xml-map-{map_index}-schema-id",
        )
        if schema_id and schema_id not in schema_ids:
            _xml_mapping_issue(
                issues,
                "xml-map-reference-to-unknown-schema",
                (map_id, schema_id),
            )
        behavior = tuple(
            _xml_mapping_boolean(
                xml_map.get(attribute),
                issues,
                context=f"xml-map-{map_index}-{attribute}",
            )
            for attribute in (
                "ShowImportExportValidationErrors",
                "AutoFit",
                "Append",
                "PreserveSortAFLayout",
                "PreserveFormat",
            )
        )
        data_bindings = [
            child
            for child in xml_map
            if (
                _xml_namespace(child.tag) == _SPREADSHEETML_NS
                and _xml_local_name(child.tag) == "DataBinding"
            )
        ]
        if len(data_bindings) > 1:
            _xml_mapping_issue(
                issues,
                "multiple-xml-map-data-bindings",
                (map_id, len(data_bindings)),
            )
        data_binding_entries: list[tuple[object, ...]] = []
        for binding_index, data_binding in enumerate(data_bindings):
            data_binding_count += 1
            file_binding = _xml_mapping_boolean(
                data_binding.get("FileBinding"),
                issues,
                context=f"xml-map-{map_index}-data-binding-{binding_index}-file-binding",
                default=False,
            )
            connection_id = _xml_mapping_unsigned(
                data_binding.get("ConnectionID"),
                issues,
                context=(
                    f"xml-map-{map_index}-data-binding-{binding_index}-connection-id"
                ),
                required=False,
            )
            load_mode = _xml_mapping_unsigned(
                data_binding.get("DataBindingLoadMode"),
                issues,
                context=(
                    f"xml-map-{map_index}-data-binding-{binding_index}-load-mode"
                ),
            )
            file_binding_count += int(file_binding is True)
            connection_binding_count += int(connection_id is not None)
            unknown_attributes, unknown_children = _xml_mapping_unknown_material(
                data_binding,
                known_attributes=frozenset(
                    {
                        "DataBindingName",
                        "FileBinding",
                        "ConnectionID",
                        "FileBindingName",
                        "DataBindingLoadMode",
                    }
                ),
                known_children=frozenset(),
                issues=issues,
                context=f"xml-map-data-binding-{map_index}-{binding_index}",
            )
            data_binding_entries.append(
                (
                    _xml_mapping_required_text(
                        data_binding.get("DataBindingName"),
                        issues,
                        context=(
                            f"xml-map-{map_index}-data-binding-{binding_index}-name"
                        ),
                    )
                    if data_binding.get("DataBindingName") is not None
                    else "",
                    file_binding,
                    connection_id,
                    _xml_mapping_required_text(
                        data_binding.get("FileBindingName"),
                        issues,
                        context=(
                            f"xml-map-{map_index}-data-binding-{binding_index}-file-name"
                        ),
                    )
                    if data_binding.get("FileBindingName") is not None
                    else "",
                    load_mode,
                    unknown_attributes,
                    unknown_children,
                )
            )
        unknown_attributes, unknown_children = _xml_mapping_unknown_material(
            xml_map,
            known_attributes=frozenset(
                {
                    "ID",
                    "Name",
                    "RootElement",
                    "SchemaID",
                    "ShowImportExportValidationErrors",
                    "AutoFit",
                    "Append",
                    "PreserveSortAFLayout",
                    "PreserveFormat",
                }
            ),
            known_children=frozenset({"DataBinding"}),
            issues=issues,
            context=f"xml-map-{map_index}",
        )
        map_entries.append(
            (
                "xml-map",
                repr(
                    (
                        map_id,
                        name,
                        root_element,
                        schema_id,
                        behavior,
                        tuple(sorted(data_binding_entries, key=repr)),
                        unknown_attributes,
                        unknown_children,
                    )
                ),
            )
        )
    for map_id in sorted(set(map_ids)):
        if map_ids.count(map_id) > 1:
            _xml_mapping_issue(issues, "duplicate-xml-map-id", map_id)

    entries = [
        (
            "xml-map-root",
            repr(
                (
                    selection_namespaces,
                    root_unknown_attributes,
                    root_unknown_children,
                )
            ),
        ),
        *schema_entries,
        *map_entries,
        *issues,
    ]
    return _XmlMappingMapPartInspection(
        member=member,
        schema_count=len(schemas),
        map_count=len(maps),
        data_binding_count=data_binding_count,
        file_binding_count=file_binding_count,
        connection_binding_count=connection_binding_count,
        map_ids=tuple(sorted(map_ids)),
        definition_signature=_private_external_data_signature(
            tuple(sorted(entries))
        ),
        issues=tuple(issues),
    )


@dataclass(frozen=True)
class _XmlMappingTableInspection:
    """Private XML-map binding evidence from one SpreadsheetML table part."""

    member: str
    present: bool = False
    binding_count: int = 0
    map_ids: tuple[int, ...] = ()
    binding_signature: str | None = None
    issues: tuple[tuple[str, str], ...] = ()


@dataclass(frozen=True)
class _XmlMappingSingleCellInspection:
    """Private XML-map binding evidence from one single-cell-table part."""

    member: str
    present: bool = False
    binding_count: int = 0
    connection_binding_count: int = 0
    map_ids: tuple[int, ...] = ()
    binding_signature: str | None = None
    issues: tuple[tuple[str, str], ...] = ()


def _xml_mapping_cell_reference(
    value: str | None,
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> str | None:
    """Normalize one single-cell XML mapping target without exposing it."""
    candidate = _xml_mapping_required_text(value, issues, context=context)
    if not candidate:
        return None
    try:
        min_column, min_row, max_column, max_row = range_boundaries(candidate)
    except ValueError:
        _xml_mapping_issue(issues, f"invalid-{context}", candidate)
        return None
    if (
        min_column is None
        or min_row is None
        or max_column is None
        or max_row is None
        or min_column != max_column
        or min_row != max_row
        or min_column < 1
        or min_row < 1
        or min_column > MAX_EXCEL_COLUMN
        or min_row > MAX_EXCEL_ROW
    ):
        _xml_mapping_issue(issues, f"invalid-{context}", candidate)
        return None
    return f"{get_column_letter(min_column)}{min_row}"


def _xml_mapping_table_inspection(
    root: ElementTree.Element,
    member: str,
    sources: tuple[str, ...],
) -> _XmlMappingTableInspection:
    """Inspect table XML map bindings without serialising table identifiers."""
    issues: list[tuple[str, str]] = []
    if (
        _xml_namespace(root.tag) != _SPREADSHEETML_NS
        or _xml_local_name(root.tag) != "table"
    ):
        _xml_mapping_issue(
            issues,
            "unexpected-xml-mapping-table-root",
            _xml_fragment(root).sort_key(),
        )
        return _XmlMappingTableInspection(
            member=member,
            binding_signature=_private_payload_signature(
                ElementTree.tostring(root, encoding="utf-8")
            ),
            issues=tuple(issues),
        )

    table_type = (root.get("tableType") or "").strip().casefold()
    table_id = _xml_mapping_unsigned(
        root.get("id"),
        issues,
        context="xml-mapping-table-id",
    )
    connection_id = _xml_mapping_unsigned(
        root.get("connectionId"),
        issues,
        context="xml-mapping-table-connection-id",
        required=False,
    )
    table_columns_tag = f"{{{_SPREADSHEETML_NS}}}tableColumns"
    table_column_tag = f"{{{_SPREADSHEETML_NS}}}tableColumn"
    xml_column_tag = f"{{{_SPREADSHEETML_NS}}}xmlColumnPr"
    column_containers = root.findall(table_columns_tag)
    if len(column_containers) > 1:
        _xml_mapping_issue(
            issues,
            "multiple-xml-mapping-table-column-containers",
            len(column_containers),
        )

    map_ids: list[int] = []
    binding_entries: list[tuple[object, ...]] = []
    binding_count = 0
    for container_index, container in enumerate(column_containers):
        for column_index, column in enumerate(container.findall(table_column_tag)):
            bindings = column.findall(xml_column_tag)
            if len(bindings) > 1:
                _xml_mapping_issue(
                    issues,
                    "multiple-xml-mapping-table-column-bindings",
                    (container_index, column_index, len(bindings)),
                )
            for binding_index, binding in enumerate(bindings):
                binding_count += 1
                map_id, material = _xml_mapping_binding_material(
                    binding,
                    issues,
                    context=(
                        "xml-mapping-table-binding-"
                        f"{container_index}-{column_index}-{binding_index}"
                    ),
                    table_column=True,
                )
                if map_id is not None:
                    map_ids.append(map_id)
                binding_entries.append(
                    (
                        column.get("id", ""),
                        column.get("uniqueName", ""),
                        container_index,
                        column_index,
                        material,
                    )
                )

    present = table_type == "xml" or bool(binding_entries)
    if not present:
        return _XmlMappingTableInspection(member=member)
    if not sources:
        _xml_mapping_issue(
            issues,
            "unbound-xml-mapping-table-part",
            _private_payload_signature(ElementTree.tostring(root, encoding="utf-8")),
        )
    material = (
        tuple(sorted(sources, key=str.casefold)),
        table_id,
        table_type,
        connection_id,
        root.get("ref", ""),
        tuple(binding_entries),
    )
    entries = [("xml-mapping-table", repr(material)), *issues]
    return _XmlMappingTableInspection(
        member=member,
        present=True,
        binding_count=binding_count,
        map_ids=tuple(sorted(map_ids)),
        binding_signature=_private_external_data_signature(tuple(sorted(entries))),
        issues=tuple(issues),
    )


def _xml_mapping_single_cell_inspection(
    root: ElementTree.Element,
    member: str,
    sources: tuple[str, ...],
) -> _XmlMappingSingleCellInspection:
    """Inspect single-cell XML map bindings without exposing cells or XPaths."""
    issues: list[tuple[str, str]] = []
    if (
        _xml_namespace(root.tag) != _SPREADSHEETML_NS
        or _xml_local_name(root.tag) != "singleXmlCells"
    ):
        _xml_mapping_issue(
            issues,
            "unexpected-xml-mapping-single-cell-root",
            _xml_fragment(root).sort_key(),
        )
        return _XmlMappingSingleCellInspection(
            member=member,
            binding_signature=_private_payload_signature(
                ElementTree.tostring(root, encoding="utf-8")
            ),
            issues=tuple(issues),
        )

    cell_tag = f"{{{_SPREADSHEETML_NS}}}singleXmlCell"
    cell_property_tag = f"{{{_SPREADSHEETML_NS}}}xmlCellPr"
    properties_tag = f"{{{_SPREADSHEETML_NS}}}xmlPr"
    root_unknown_attributes, root_unknown_children = _xml_mapping_unknown_material(
        root,
        known_attributes=frozenset(),
        known_children=frozenset({"singleXmlCell"}),
        issues=issues,
        context="xml-mapping-single-cell-root",
    )
    cells = root.findall(cell_tag)
    if not cells:
        _xml_mapping_issue(issues, "empty-xml-mapping-single-cell-part", None)

    map_ids: list[int] = []
    entries: list[tuple[object, ...]] = []
    connection_binding_count = 0
    for cell_index, cell in enumerate(cells):
        cell_id = _xml_mapping_unsigned(
            cell.get("id"),
            issues,
            context=f"xml-mapping-single-cell-{cell_index}-id",
        )
        reference = _xml_mapping_cell_reference(
            cell.get("r"),
            issues,
            context=f"xml-mapping-single-cell-{cell_index}-reference",
        )
        connection_id = _xml_mapping_unsigned(
            cell.get("connectionId"),
            issues,
            context=f"xml-mapping-single-cell-{cell_index}-connection-id",
        )
        connection_binding_count += int(connection_id is not None)
        cell_properties = cell.findall(cell_property_tag)
        if len(cell_properties) != 1:
            _xml_mapping_issue(
                issues,
                "invalid-xml-mapping-single-cell-properties",
                (cell_index, len(cell_properties)),
            )
        property_entries: list[tuple[object, ...]] = []
        for property_index, cell_property in enumerate(cell_properties):
            property_id = _xml_mapping_unsigned(
                cell_property.get("id"),
                issues,
                context=(
                    f"xml-mapping-single-cell-{cell_index}-property-{property_index}-id"
                ),
            )
            xml_properties = cell_property.findall(properties_tag)
            if len(xml_properties) != 1:
                _xml_mapping_issue(
                    issues,
                    "invalid-xml-mapping-single-cell-xml-properties",
                    (cell_index, property_index, len(xml_properties)),
                )
            property_materials: list[tuple[object, ...]] = []
            for xml_property_index, xml_property in enumerate(xml_properties):
                map_id, material = _xml_mapping_binding_material(
                    xml_property,
                    issues,
                    context=(
                        "xml-mapping-single-cell-binding-"
                        f"{cell_index}-{property_index}-{xml_property_index}"
                    ),
                    table_column=False,
                )
                if map_id is not None:
                    map_ids.append(map_id)
                property_materials.append(material)
            unknown_attributes, unknown_children = _xml_mapping_unknown_material(
                cell_property,
                known_attributes=frozenset({"id", "uniqueName"}),
                known_children=frozenset({"xmlPr", "extLst"}),
                issues=issues,
                context=f"xml-mapping-single-cell-property-{cell_index}-{property_index}",
            )
            extension_fragments = tuple(
                _xml_fragment(child).sort_key()
                for child in cell_property
                if (
                    _xml_namespace(child.tag) == _SPREADSHEETML_NS
                    and _xml_local_name(child.tag) == "extLst"
                )
            )
            if extension_fragments:
                _xml_mapping_issue(
                    issues,
                    "unrecognized-xml-mapping-single-cell-property-extensions",
                    extension_fragments,
                )
            property_entries.append(
                (
                    property_id,
                    cell_property.get("uniqueName", ""),
                    tuple(property_materials),
                    unknown_attributes,
                    extension_fragments,
                    unknown_children,
                )
            )
        unknown_attributes, unknown_children = _xml_mapping_unknown_material(
            cell,
            known_attributes=frozenset({"id", "r", "connectionId"}),
            known_children=frozenset({"xmlCellPr", "extLst"}),
            issues=issues,
            context=f"xml-mapping-single-cell-{cell_index}",
        )
        extension_fragments = tuple(
            _xml_fragment(child).sort_key()
            for child in cell
            if (
                _xml_namespace(child.tag) == _SPREADSHEETML_NS
                and _xml_local_name(child.tag) == "extLst"
            )
        )
        if extension_fragments:
            _xml_mapping_issue(
                issues,
                "unrecognized-xml-mapping-single-cell-extensions",
                extension_fragments,
            )
        entries.append(
            (
                cell_id,
                reference,
                connection_id,
                tuple(property_entries),
                unknown_attributes,
                extension_fragments,
                unknown_children,
            )
        )

    present = bool(cells or issues)
    if present and not sources:
        _xml_mapping_issue(
            issues,
            "unbound-xml-mapping-single-cell-part",
            _private_payload_signature(ElementTree.tostring(root, encoding="utf-8")),
        )
    if not present:
        return _XmlMappingSingleCellInspection(member=member)
    material = (
        tuple(sorted(sources, key=str.casefold)),
        root_unknown_attributes,
        root_unknown_children,
        tuple(entries),
    )
    signature_entries = [("xml-mapping-single-cells", repr(material)), *issues]
    return _XmlMappingSingleCellInspection(
        member=member,
        present=True,
        binding_count=len(cells),
        connection_binding_count=connection_binding_count,
        map_ids=tuple(sorted(map_ids)),
        binding_signature=_private_external_data_signature(
            tuple(sorted(signature_entries))
        ),
        issues=tuple(issues),
    )


def _xml_mapping_relationship_suffix(relationship: _PackageRelationship) -> str:
    """Return a case-insensitive package relationship suffix for dispatch."""
    return relationship.relationship_type.rsplit("/", maxsplit=1)[-1].casefold()


def _xml_mapping_relationship_target(relationship: _PackageRelationship) -> str | None:
    """Return private target material, retaining unsafe targets only for hashing."""
    return relationship.target if relationship.target is not None else relationship.raw_target


def _xml_mapping_metadata(path: Path) -> _XmlMappingMetadata:
    """Inspect XML map declarations and bindings before reader-library loss.

    XML Maps direct import/export and refresh data into XML table columns or
    specific cells. The scanner compares private canonical declarations and
    bindings only; it does not import, export, validate, fetch, or execute
    mappings.
    """
    warnings: set[str] = set()
    issues: list[tuple[str, str]] = []
    declaration_entries: list[tuple[str, str]] = []
    binding_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    try:
        with ZipFile(path) as archive:
            member_counts: dict[str, int] = defaultdict(int)
            for member in archive.namelist():
                if (
                    _XML_MAPPING_MAP_PART_PATTERN.fullmatch(member)
                    or _XML_MAPPING_TABLE_PART_PATTERN.fullmatch(member)
                    or _XML_MAPPING_SINGLE_CELL_PART_PATTERN.fullmatch(member)
                ):
                    member_counts[member] += 1
            for member, count in member_counts.items():
                if count > 1:
                    _xml_mapping_issue(
                        issues,
                        "duplicate-xml-mapping-package-member",
                        (member, count),
                    )

            discovered_map_members = {
                member
                for member in archive.namelist()
                if _XML_MAPPING_MAP_PART_PATTERN.fullmatch(member)
            }
            table_members = {
                member
                for member in archive.namelist()
                if _XML_MAPPING_TABLE_PART_PATTERN.fullmatch(member)
            }
            single_cell_members = {
                member
                for member in archive.namelist()
                if _XML_MAPPING_SINGLE_CELL_PART_PATTERN.fullmatch(member)
            }

            try:
                workbook_relationships = _package_relationships(archive, "xl/workbook.xml")
            except (
                ElementTree.ParseError,
                KeyError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                _xml_mapping_issue(
                    issues,
                    "xml-mapping-workbook-relationship-scan-failure",
                    type(error).__name__,
                )
                workbook_relationships = ()

            declared_map_members: set[str] = set()
            for relationship in workbook_relationships:
                if _xml_mapping_relationship_suffix(relationship) != "xmlmaps":
                    continue
                relationship_target = _xml_mapping_relationship_target(relationship)
                relationship_entries.append(
                    (
                        "workbook-xml-map-relationship",
                        repr(
                            (
                                relationship.relationship_type,
                                relationship.target_mode.casefold(),
                                relationship_target,
                            )
                        ),
                    )
                )
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                ):
                    _xml_mapping_issue(
                        issues,
                        "unsafe-xml-map-workbook-relationship",
                        (
                            relationship.relationship_type,
                            relationship.target_mode,
                            relationship_target,
                        ),
                    )
                    continue
                declared_map_members.add(relationship.target)
                if not _XML_MAPPING_MAP_PART_PATTERN.fullmatch(relationship.target):
                    _xml_mapping_issue(
                        issues,
                        "unexpected-xml-map-workbook-target",
                        relationship.target,
                    )
            if len(declared_map_members) != sum(
                _xml_mapping_relationship_suffix(relationship) == "xmlmaps"
                and relationship.target_mode.casefold() == "internal"
                and relationship.target is not None
                for relationship in workbook_relationships
            ):
                _xml_mapping_issue(
                    issues,
                    "duplicate-xml-map-workbook-target",
                    tuple(sorted(declared_map_members)),
                )
            for member in discovered_map_members - declared_map_members:
                _xml_mapping_issue(
                    issues,
                    "unbound-xml-map-package-part",
                    member,
                )
            map_members = discovered_map_members | declared_map_members

            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (
                ElementTree.ParseError,
                KeyError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                _xml_mapping_issue(
                    issues,
                    "xml-mapping-sheet-part-scan-failure",
                    type(error).__name__,
                )
                sheet_parts = {}

            table_sources: dict[str, set[str]] = defaultdict(set)
            single_cell_sources: dict[str, set[str]] = defaultdict(set)
            table_relationship_entries: dict[str, list[tuple[str, str]]] = defaultdict(
                list
            )
            single_cell_relationship_entries: dict[
                str, list[tuple[str, str]]
            ] = defaultdict(list)
            for sheet, (member, sheet_kind) in sheet_parts.items():
                if sheet_kind != "worksheet":
                    continue
                relationship_member = _relationship_part_path(member)
                if relationship_member not in archive.namelist():
                    continue
                try:
                    relationships = _package_relationships(archive, member)
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    _xml_mapping_issue(
                        issues,
                        "xml-mapping-worksheet-relationship-scan-failure",
                        (sheet, type(error).__name__),
                    )
                    continue
                for relationship in relationships:
                    suffix = _xml_mapping_relationship_suffix(relationship)
                    if suffix not in {"table", "tablesinglecells"}:
                        continue
                    relationship_target = _xml_mapping_relationship_target(relationship)
                    relationship_entry = (
                        f"worksheet-{suffix}-relationship",
                        repr(
                            (
                                sheet,
                                relationship.relationship_type,
                                relationship.target_mode.casefold(),
                                relationship_target,
                            )
                        )
                    )
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        if suffix == "tablesinglecells" or map_members:
                            relationship_entries.append(relationship_entry)
                            _xml_mapping_issue(
                                issues,
                                f"unsafe-xml-mapping-worksheet-{suffix}-relationship",
                                (
                                    sheet,
                                    relationship.relationship_type,
                                    relationship.target_mode,
                                    relationship_target,
                                ),
                            )
                        continue
                    if suffix == "table":
                        table_members.add(relationship.target)
                        table_sources[relationship.target].add(sheet)
                        table_relationship_entries[relationship.target].append(
                            relationship_entry
                        )
                    else:
                        single_cell_members.add(relationship.target)
                        single_cell_sources[relationship.target].add(sheet)
                        single_cell_relationship_entries[relationship.target].append(
                            relationship_entry
                        )

            budget = _XmlMappingBudget()
            map_inspections: list[_XmlMappingMapPartInspection] = []
            for member in sorted(map_members, key=str.casefold):
                root, fallback_signature = _xml_mapping_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                    context="XML Maps",
                )
                if root is None:
                    _xml_mapping_issue(
                        issues,
                        "unreadable-xml-map-part",
                        (member, fallback_signature),
                    )
                    declaration_entries.append(
                        (
                            "unreadable-xml-map-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                inspection = _xml_mapping_map_part_inspection(root, member)
                map_inspections.append(inspection)
                if inspection.definition_signature is not None:
                    declaration_entries.append(
                        ("xml-map-part", inspection.definition_signature)
                    )
                issues.extend(inspection.issues)

            table_inspections: list[_XmlMappingTableInspection] = []
            unreadable_table_members: set[str] = set()
            table_members_to_inspect = (
                table_members if map_members or single_cell_members else set()
            )
            for member in sorted(table_members_to_inspect, key=str.casefold):
                root, fallback_signature = _xml_mapping_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                    context="XML-mapped table",
                )
                if root is None:
                    if map_members:
                        unreadable_table_members.add(member)
                        _xml_mapping_issue(
                            issues,
                            "unreadable-xml-mapping-table-part",
                            (member, fallback_signature),
                        )
                        binding_entries.append(
                            (
                                "unreadable-xml-mapping-table-part",
                                fallback_signature or "",
                            )
                        )
                    continue
                inspection = _xml_mapping_table_inspection(
                    root,
                    member,
                    tuple(sorted(table_sources.get(member, set()), key=str.casefold)),
                )
                table_inspections.append(inspection)
                if inspection.present and inspection.binding_signature is not None:
                    binding_entries.append(
                        ("xml-mapping-table-binding", inspection.binding_signature)
                    )
                if inspection.present or map_members:
                    issues.extend(inspection.issues)
            for member in (
                {
                    inspection.member
                    for inspection in table_inspections
                    if inspection.present
                }
                | unreadable_table_members
            ):
                relationship_entries.extend(table_relationship_entries.get(member, ()))

            single_cell_inspections: list[_XmlMappingSingleCellInspection] = []
            unreadable_single_cell_members: set[str] = set()
            for member in sorted(single_cell_members, key=str.casefold):
                root, fallback_signature = _xml_mapping_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                    context="XML-mapped single-cell table",
                )
                if root is None:
                    unreadable_single_cell_members.add(member)
                    _xml_mapping_issue(
                        issues,
                        "unreadable-xml-mapping-single-cell-part",
                        (member, fallback_signature),
                    )
                    binding_entries.append(
                        (
                            "unreadable-xml-mapping-single-cell-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                inspection = _xml_mapping_single_cell_inspection(
                    root,
                    member,
                    tuple(
                        sorted(
                            single_cell_sources.get(member, set()),
                            key=str.casefold,
                        )
                    ),
                )
                single_cell_inspections.append(inspection)
                if inspection.binding_signature is not None:
                    binding_entries.append(
                        (
                            "xml-mapping-single-cell-binding",
                            inspection.binding_signature,
                        )
                    )
                issues.extend(inspection.issues)
            for member in (
                {
                    inspection.member
                    for inspection in single_cell_inspections
                    if inspection.present
                }
                | unreadable_single_cell_members
            ):
                relationship_entries.extend(
                    single_cell_relationship_entries.get(member, ())
                )

            declared_map_id_values = tuple(
                map_id
                for inspection in map_inspections
                for map_id in inspection.map_ids
            )
            declared_map_ids = set(declared_map_id_values)
            for map_id in sorted(declared_map_ids):
                if declared_map_id_values.count(map_id) > 1:
                    _xml_mapping_issue(
                        issues,
                        "duplicate-xml-map-id-across-parts",
                        map_id,
                    )
            referenced_map_ids = {
                map_id
                for inspection in table_inspections
                for map_id in inspection.map_ids
            } | {
                map_id
                for inspection in single_cell_inspections
                for map_id in inspection.map_ids
            }
            for map_id in sorted(referenced_map_ids - declared_map_ids):
                _xml_mapping_issue(
                    issues,
                    "xml-mapping-binding-references-unknown-map",
                    map_id,
                )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _XmlMappingMetadata(
            XmlMappingSnapshot(
                unrecognized_xml_mapping_count=1,
                declaration_signature=_private_external_data_signature(
                    (("xml-mapping-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect XML-mapping OOXML "
                f"({type(error).__name__}); affected XML mappings were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported XML-mapping metadata; "
            "affected XML mappings have a coverage gap."
        )
    declaration_entries.extend(
        ("xml-mapping-issue", repr(issue))
        for issue in issues
    )
    snapshot = XmlMappingSnapshot(
        xml_map_part_count=len(map_members),
        xml_schema_count=sum(inspection.schema_count for inspection in map_inspections),
        xml_map_count=sum(inspection.map_count for inspection in map_inspections),
        xml_map_data_binding_count=sum(
            inspection.data_binding_count for inspection in map_inspections
        ),
        xml_map_file_binding_count=sum(
            inspection.file_binding_count for inspection in map_inspections
        ),
        xml_map_connection_binding_count=sum(
            inspection.connection_binding_count for inspection in map_inspections
        ),
        table_xml_binding_part_count=sum(
            inspection.present for inspection in table_inspections
        ),
        table_xml_binding_count=sum(
            inspection.binding_count for inspection in table_inspections
        ),
        single_cell_xml_binding_sheet_count=len(
            {
                sheet
                for inspection in single_cell_inspections
                if inspection.present
                for sheet in single_cell_sources.get(inspection.member, set())
            }
        ),
        single_cell_xml_binding_part_count=sum(
            inspection.present for inspection in single_cell_inspections
        ),
        single_cell_xml_binding_count=sum(
            inspection.binding_count for inspection in single_cell_inspections
        ),
        single_cell_xml_connection_binding_count=sum(
            inspection.connection_binding_count
            for inspection in single_cell_inspections
        ),
        unrecognized_xml_mapping_count=len(issues),
        declaration_signature=(
            _private_external_data_signature(tuple(sorted(declaration_entries)))
            if declaration_entries
            else None
        ),
        binding_signature=(
            _private_external_data_signature(tuple(sorted(binding_entries)))
            if binding_entries
            else None
        ),
        relationship_signature=(
            _private_external_data_signature(tuple(sorted(relationship_entries)))
            if relationship_entries
            else None
        ),
    )
    return _XmlMappingMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _DigitalSignatureBudget:
    """Bound raw package- and VBA-signature reads."""

    remaining_parts: int = _DIGITAL_SIGNATURE_TOTAL_PARTS
    remaining_bytes: int = _DIGITAL_SIGNATURE_TOTAL_BYTES
    remaining_xml_elements: int = _DIGITAL_SIGNATURE_TOTAL_XML_MAX_ELEMENT_COUNT


@dataclass(frozen=True)
class _DigitalSignatureXmlInspection:
    """Private inspection result for one OPC XML signature part."""

    member: str
    reference_count: int = 0
    certificate_count: int = 0
    signature: str | None = None
    issues: tuple[tuple[str, str], ...] = ()


def _digital_signature_issue(
    issues: list[tuple[str, str]],
    context: str,
    detail: object,
) -> None:
    """Retain malformed signature evidence only inside a private fingerprint."""
    issues.append((context, repr(detail)))


def _digital_signature_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _DigitalSignatureBudget,
    *,
    report_failure: bool,
) -> str | None:
    """Stream signature XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _DIGITAL_SIGNATURE_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    if report_failure:
        warnings.add(
            "FormulaFence did not fully read a digital-signature XML part whose XML "
            "structure exceeds the safety budget; affected signature controls have a "
            "coverage gap."
        )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _digital_signature_bounded_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _DigitalSignatureBudget,
    *,
    kind: str,
    structural_xml: bool = False,
    report_failure: bool = True,
) -> tuple[bytes | None, str | None]:
    """Read one signature package member within fixed defensive limits."""
    if budget.remaining_parts <= 0:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded digital-signature part-count budget; "
                "affected signature controls have a coverage gap."
            )
        return None, _private_external_data_signature(
            (("digital-signature-part-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        if report_failure:
            warnings.add(
                "FormulaFence could not locate a digital-signature package member; "
                "affected signature controls were not compared."
            )
        return None, _private_external_data_signature(
            (("missing-digital-signature-member", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _DIGITAL_SIGNATURE_MAX_PART_BYTES:
        if report_failure:
            warnings.add(
                "FormulaFence did not fully read an oversized digital-signature "
                f"{kind} part; affected signature controls have a coverage gap."
            )
        return None, _private_external_data_signature(
            (("oversized-digital-signature-member", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded digital-signature read budget; "
                "affected signature controls have a coverage gap."
            )
        return None, _private_external_data_signature(
            (("digital-signature-read-budget-exhausted", metadata),)
        )
    if structural_xml:
        structure_fallback_signature = (
            _digital_signature_xml_structure_budget_fallback_signature(
                archive,
                member,
                info,
                warnings,
                budget,
                report_failure=report_failure,
            )
        )
        if structure_fallback_signature is not None:
            return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not read a digital-signature "
                f"{kind} part ({type(error).__name__}); affected signature controls "
                "were not compared."
            )
        return None, _private_external_data_signature(
            (("unreadable-digital-signature-member", metadata),)
        )


def _digital_signature_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _DigitalSignatureBudget,
    *,
    report_failure: bool = True,
) -> tuple[ElementTree.Element | None, str | None]:
    """Return one bounded XML-signature root or a private failure fingerprint."""
    payload, fallback_signature = _digital_signature_bounded_payload(
        archive,
        member,
        warnings,
        budget,
        kind="XML",
        structural_xml=True,
        report_failure=report_failure,
    )
    if payload is None:
        return None, fallback_signature
    try:
        return _xml_root_from_payload(payload), None
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not parse a digital-signature XML part "
                f"({type(error).__name__}); affected signature controls were not compared."
            )
        return None, _private_payload_signature(payload)


def _digital_signature_target(relationship: _PackageRelationship) -> str | None:
    """Retain a relationship endpoint privately even when it is unsafe."""
    return (
        relationship.target
        if relationship.target is not None
        else relationship.raw_target
    )


def _digital_signature_content_type_declarations(
    archive: ZipFile,
    warnings: set[str],
    budget: _DigitalSignatureBudget,
    issues: list[tuple[str, str]],
) -> tuple[dict[str, tuple[str, ...]], dict[str, tuple[str, ...]]]:
    """Read only signature-relevant OPC content-type declarations."""
    overrides: dict[str, list[str]] = defaultdict(list)
    defaults: dict[str, list[str]] = defaultdict(list)
    payload, fallback_signature = _digital_signature_bounded_payload(
        archive,
        "[Content_Types].xml",
        warnings,
        budget,
        kind="XML",
        structural_xml=True,
        report_failure=False,
    )
    if payload is None:
        warnings.add(
            "FormulaFence could not inspect OPC content types for digital signatures; "
            "affected signature controls may be incomplete."
        )
        _digital_signature_issue(
            issues,
            "digital-signature-content-type-scan",
            fallback_signature or "unreadable",
        )
        return {}, {}
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect OPC content types for digital "
            f"signatures ({type(error).__name__}); affected signature controls may be incomplete."
        )
        _digital_signature_issue(
            issues,
            "digital-signature-content-type-scan",
            type(error).__name__,
        )
        return {}, {}
    if (
        _xml_namespace(root.tag) != _CONTENT_TYPES_NS
        or _xml_local_name(root.tag) != "Types"
    ):
        warnings.add(
            "FormulaFence found an unexpected OPC content-types root while "
            "inspecting digital signatures; affected signature controls may be incomplete."
        )
        _digital_signature_issue(
            issues,
            "unexpected-digital-signature-content-types-root",
            _xml_display_name(root.tag),
        )
        return {}, {}

    override_tag = f"{{{_CONTENT_TYPES_NS}}}Override"
    default_tag = f"{{{_CONTENT_TYPES_NS}}}Default"
    for child in root:
        if child.tag == override_tag:
            content_type = child.get("ContentType")
            raw_member = child.get("PartName")
            member = (
                _normalise_content_type_part_name(raw_member)
                if raw_member is not None
                else None
            )
            relevant = bool(
                content_type
                in {
                    _DIGITAL_SIGNATURE_ORIGIN_CONTENT_TYPE,
                    _DIGITAL_SIGNATURE_XML_CONTENT_TYPE,
                    _DIGITAL_SIGNATURE_CERTIFICATE_CONTENT_TYPE,
                }
                or (
                    member is not None
                    and (
                        _DIGITAL_SIGNATURE_ORIGIN_PART_PATTERN.fullmatch(member)
                        or _DIGITAL_SIGNATURE_XML_PART_PATTERN.fullmatch(member)
                        or _DIGITAL_SIGNATURE_CERTIFICATE_PART_PATTERN.fullmatch(
                            member
                        )
                    )
                )
            )
            if not relevant:
                continue
            if member is None or content_type is None:
                _digital_signature_issue(
                    issues,
                    "malformed-digital-signature-content-type-override",
                    _xml_display_name(child.tag),
                )
                continue
            overrides[member].append(content_type)
            continue
        if child.tag != default_tag:
            continue
        extension = child.get("Extension")
        content_type = child.get("ContentType")
        if (
            extension is None
            or content_type is None
            or (
                extension.casefold() != "sigs"
                and content_type
                not in {
                    _DIGITAL_SIGNATURE_ORIGIN_CONTENT_TYPE,
                    _DIGITAL_SIGNATURE_XML_CONTENT_TYPE,
                    _DIGITAL_SIGNATURE_CERTIFICATE_CONTENT_TYPE,
                }
            )
        ):
            continue
        defaults[extension.casefold()].append(content_type)

    duplicate_overrides = {
        member: values
        for member, values in overrides.items()
        if len(values) > 1
    }
    for member, values in duplicate_overrides.items():
        _digital_signature_issue(
            issues,
            "duplicate-digital-signature-content-type-override",
            (member, tuple(sorted(values))),
        )
    duplicate_defaults = {
        extension: values
        for extension, values in defaults.items()
        if len(values) > 1
    }
    for extension, values in duplicate_defaults.items():
        _digital_signature_issue(
            issues,
            "duplicate-digital-signature-content-type-default",
            (extension, tuple(sorted(values))),
        )
    return (
        {member: tuple(sorted(values)) for member, values in overrides.items()},
        {extension: tuple(sorted(values)) for extension, values in defaults.items()},
    )


def _digital_signature_content_type_status(
    member: str,
    expected: str,
    overrides: Mapping[str, tuple[str, ...]],
    defaults: Mapping[str, tuple[str, ...]],
) -> str:
    """Classify a signature part's OPC content-type declaration."""
    declared = overrides.get(member)
    if declared is None:
        extension = member.rsplit(".", maxsplit=1)[-1].casefold() if "." in member else ""
        declared = defaults.get(extension, ())
    if expected in declared:
        return "declared"
    return "mismatched" if declared else "unlisted"


def _digital_signature_fragment(element: ElementTree.Element) -> tuple[object, ...]:
    """Canonicalise signature XML while retaining cryptographic material privately."""
    base64_elements = frozenset(
        {
            "DigestValue",
            "SignatureValue",
            "X509Certificate",
            "X509CRL",
            "PGPKeyID",
            "PGPKeyPacket",
            "SPKISexp",
            "Modulus",
            "Exponent",
        }
    )
    children = tuple(_digital_signature_fragment(child) for child in element)
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    if (
        text is not None
        and _xml_namespace(element.tag) == _XML_DIGITAL_SIGNATURE_NS
        and _xml_local_name(element.tag) in base64_elements
    ):
        text = "".join(text.split())
    return (
        _xml_display_name(element.tag),
        tuple(
            sorted(
                (_xml_display_name(attribute), value)
                for attribute, value in element.attrib.items()
            )
        ),
        text,
        children,
    )


def _digital_signature_xml_inspection(
    root: ElementTree.Element,
    member: str,
) -> _DigitalSignatureXmlInspection:
    """Inspect an XMLDSIG envelope without evaluating its cryptography."""
    issues: list[tuple[str, str]] = []
    signature_tag = f"{{{_XML_DIGITAL_SIGNATURE_NS}}}Signature"
    if root.tag != signature_tag:
        _digital_signature_issue(
            issues,
            "unexpected-package-signature-root",
            _digital_signature_fragment(root),
        )
        return _DigitalSignatureXmlInspection(
            member=member,
            signature=_private_external_data_signature(
                (("unexpected-package-signature-root", repr(_digital_signature_fragment(root))),)
            ),
            issues=tuple(issues),
        )

    signed_info_tag = f"{{{_XML_DIGITAL_SIGNATURE_NS}}}SignedInfo"
    signature_value_tag = f"{{{_XML_DIGITAL_SIGNATURE_NS}}}SignatureValue"
    reference_tag = f"{{{_XML_DIGITAL_SIGNATURE_NS}}}Reference"
    certificate_tag = f"{{{_XML_DIGITAL_SIGNATURE_NS}}}X509Certificate"
    signed_infos = root.findall(signed_info_tag)
    signature_values = root.findall(signature_value_tag)
    if len(signed_infos) != 1:
        _digital_signature_issue(
            issues,
            "invalid-package-signature-signed-info-count",
            len(signed_infos),
        )
    if len(signature_values) != 1:
        _digital_signature_issue(
            issues,
            "invalid-package-signature-value-count",
            len(signature_values),
        )
    references = (
        signed_infos[0].findall(reference_tag)
        if len(signed_infos) == 1
        else []
    )
    if not references:
        _digital_signature_issue(issues, "empty-package-signature-references", None)
    return _DigitalSignatureXmlInspection(
        member=member,
        reference_count=len(references),
        certificate_count=len(root.findall(f".//{certificate_tag}")),
        signature=_private_external_data_signature(
            (("package-xml-signature", repr(_digital_signature_fragment(root))),)
        ),
        issues=tuple(issues),
    )


def _digital_signature_metadata(path: Path) -> _DigitalSignatureMetadata:
    """Inventory package and VBA signature envelopes without validating them.

    A package XML signature and a VBA code signature are separate Excel trust
    surfaces. The scanner records only safe aggregate counts and private hashes;
    it never validates certificates, cryptographic values, trust chains,
    revocation, timestamps, or signed package contents.
    """
    warnings: set[str] = set()
    issues: list[tuple[str, str]] = []
    package_entries: list[tuple[str, str]] = []
    vba_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    try:
        with ZipFile(path) as archive:
            members = set(archive.namelist())
            member_counts: dict[str, int] = defaultdict(int)
            for entry in archive.infolist():
                member_counts[entry.filename] += 1

            budget = _DigitalSignatureBudget()
            overrides, defaults = _digital_signature_content_type_declarations(
                archive,
                warnings,
                budget,
                issues,
            )
            discovered_origins = {
                member
                for member in members
                if _DIGITAL_SIGNATURE_ORIGIN_PART_PATTERN.fullmatch(member)
            } | {
                member
                for member, content_types in overrides.items()
                if _DIGITAL_SIGNATURE_ORIGIN_CONTENT_TYPE in content_types
            }
            discovered_xml_signatures = {
                member
                for member in members
                if _DIGITAL_SIGNATURE_XML_PART_PATTERN.fullmatch(member)
            } | {
                member
                for member, content_types in overrides.items()
                if _DIGITAL_SIGNATURE_XML_CONTENT_TYPE in content_types
            }
            discovered_package_certificates = {
                member
                for member in members
                if _DIGITAL_SIGNATURE_CERTIFICATE_PART_PATTERN.fullmatch(member)
            } | {
                member
                for member, content_types in overrides.items()
                if _DIGITAL_SIGNATURE_CERTIFICATE_CONTENT_TYPE in content_types
            }

            try:
                root_relationships = _package_relationships(archive, "")
            except (
                ElementTree.ParseError,
                KeyError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                _digital_signature_issue(
                    issues,
                    "package-signature-root-relationship-scan-failure",
                    type(error).__name__,
                )
                root_relationships = ()

            declared_origins: set[str] = set()
            declared_origin_relationship_count = 0
            for relationship in root_relationships:
                if (
                    relationship.relationship_type.casefold()
                    != _DIGITAL_SIGNATURE_ORIGIN_RELATIONSHIP.casefold()
                ):
                    continue
                relationship_target = _digital_signature_target(relationship)
                relationship_entries.append(
                    (
                        "package-signature-origin-relationship",
                        repr(
                            (
                                relationship.relationship_type,
                                relationship.target_mode.casefold(),
                                relationship_target,
                            )
                        ),
                    )
                )
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                ):
                    _digital_signature_issue(
                        issues,
                        "unsafe-package-signature-origin-relationship",
                        (
                            relationship.relationship_type,
                            relationship.target_mode,
                            relationship_target,
                        ),
                    )
                    continue
                declared_origin_relationship_count += 1
                declared_origins.add(relationship.target)
            if len(declared_origins) != declared_origin_relationship_count:
                _digital_signature_issue(
                    issues,
                    "duplicate-package-signature-origin-target",
                    tuple(sorted(declared_origins)),
                )
            for member in discovered_origins - declared_origins:
                _digital_signature_issue(
                    issues,
                    "unbound-package-signature-origin-part",
                    member,
                )
            origin_members = discovered_origins | declared_origins

            declared_xml_signatures: set[str] = set()
            declared_xml_signature_relationship_count = 0
            for origin_member in sorted(origin_members, key=str.casefold):
                origin_status = _digital_signature_content_type_status(
                    origin_member,
                    _DIGITAL_SIGNATURE_ORIGIN_CONTENT_TYPE,
                    overrides,
                    defaults,
                )
                if origin_status != "declared":
                    _digital_signature_issue(
                        issues,
                        "invalid-package-signature-origin-content-type",
                        (origin_member, origin_status),
                    )
                payload, fallback_signature = _digital_signature_bounded_payload(
                    archive,
                    origin_member,
                    warnings,
                    budget,
                    kind="origin",
                )
                if payload is None:
                    _digital_signature_issue(
                        issues,
                        "unreadable-package-signature-origin-part",
                        (origin_member, fallback_signature),
                    )
                    package_entries.append(
                        (
                            "unreadable-package-signature-origin-part",
                            fallback_signature or "",
                        )
                    )
                elif payload:
                    _digital_signature_issue(
                        issues,
                        "nonempty-package-signature-origin-part",
                        _private_payload_signature(payload),
                    )
                    package_entries.append(
                        (
                            "nonempty-package-signature-origin-part",
                            _private_payload_signature(payload),
                        )
                    )

                relationship_member = _relationship_part_path(origin_member)
                if relationship_member not in members:
                    continue
                try:
                    origin_relationships = _package_relationships(archive, origin_member)
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    _digital_signature_issue(
                        issues,
                        "package-signature-origin-relationship-scan-failure",
                        (origin_member, type(error).__name__),
                    )
                    continue
                for relationship in origin_relationships:
                    if (
                        relationship.relationship_type.casefold()
                        != _DIGITAL_SIGNATURE_SIGNATURE_RELATIONSHIP.casefold()
                    ):
                        continue
                    relationship_target = _digital_signature_target(relationship)
                    relationship_entries.append(
                        (
                            "package-xml-signature-relationship",
                            repr(
                                (
                                    relationship.relationship_type,
                                    relationship.target_mode.casefold(),
                                    relationship_target,
                                )
                            ),
                        )
                    )
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        _digital_signature_issue(
                            issues,
                            "unsafe-package-xml-signature-relationship",
                            (
                                origin_member,
                                relationship.relationship_type,
                                relationship.target_mode,
                                relationship_target,
                            ),
                        )
                        continue
                    declared_xml_signature_relationship_count += 1
                    declared_xml_signatures.add(relationship.target)
            if (
                len(declared_xml_signatures)
                != declared_xml_signature_relationship_count
            ):
                _digital_signature_issue(
                    issues,
                    "duplicate-package-xml-signature-target",
                    tuple(sorted(declared_xml_signatures)),
                )
            for member in discovered_xml_signatures - declared_xml_signatures:
                _digital_signature_issue(
                    issues,
                    "unbound-package-xml-signature-part",
                    member,
                )
            xml_signature_members = discovered_xml_signatures | declared_xml_signatures

            xml_inspections: list[_DigitalSignatureXmlInspection] = []
            for member in sorted(xml_signature_members, key=str.casefold):
                signature_status = _digital_signature_content_type_status(
                    member,
                    _DIGITAL_SIGNATURE_XML_CONTENT_TYPE,
                    overrides,
                    defaults,
                )
                if signature_status != "declared":
                    _digital_signature_issue(
                        issues,
                        "invalid-package-xml-signature-content-type",
                        (member, signature_status),
                    )
                root, fallback_signature = _digital_signature_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if root is None:
                    _digital_signature_issue(
                        issues,
                        "unreadable-package-xml-signature-part",
                        (member, fallback_signature),
                    )
                    package_entries.append(
                        (
                            "unreadable-package-xml-signature-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                inspection = _digital_signature_xml_inspection(root, member)
                xml_inspections.append(inspection)
                if inspection.signature is not None:
                    package_entries.append(
                        ("package-xml-signature", inspection.signature)
                    )
                issues.extend(inspection.issues)

            declared_package_certificates: set[str] = set()
            package_certificate_relationship_count = 0
            declared_certificate_relationship_count = 0
            for signature_member in sorted(xml_signature_members, key=str.casefold):
                relationship_member = _relationship_part_path(signature_member)
                if relationship_member not in members:
                    continue
                try:
                    certificate_relationships = _package_relationships(
                        archive,
                        signature_member,
                    )
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    _digital_signature_issue(
                        issues,
                        "package-signature-certificate-relationship-scan-failure",
                        (signature_member, type(error).__name__),
                    )
                    continue
                for relationship in certificate_relationships:
                    if (
                        relationship.relationship_type.casefold()
                        != _DIGITAL_SIGNATURE_CERTIFICATE_RELATIONSHIP.casefold()
                    ):
                        continue
                    package_certificate_relationship_count += 1
                    relationship_target = _digital_signature_target(relationship)
                    relationship_entries.append(
                        (
                            "package-signature-certificate-relationship",
                            repr(
                                (
                                    relationship.relationship_type,
                                    relationship.target_mode.casefold(),
                                    relationship_target,
                                )
                            ),
                        )
                    )
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        _digital_signature_issue(
                            issues,
                            "unsafe-package-signature-certificate-relationship",
                            (
                                signature_member,
                                relationship.relationship_type,
                                relationship.target_mode,
                                relationship_target,
                            ),
                        )
                        continue
                    declared_certificate_relationship_count += 1
                    declared_package_certificates.add(relationship.target)
            if (
                len(declared_package_certificates)
                != declared_certificate_relationship_count
            ):
                _digital_signature_issue(
                    issues,
                    "duplicate-package-signature-certificate-target",
                    tuple(sorted(declared_package_certificates)),
                )
            for member in discovered_package_certificates - declared_package_certificates:
                _digital_signature_issue(
                    issues,
                    "unbound-package-signature-certificate-part",
                    member,
                )
            package_certificate_members = (
                discovered_package_certificates | declared_package_certificates
            )
            for member in sorted(package_certificate_members, key=str.casefold):
                certificate_status = _digital_signature_content_type_status(
                    member,
                    _DIGITAL_SIGNATURE_CERTIFICATE_CONTENT_TYPE,
                    overrides,
                    defaults,
                )
                if certificate_status != "declared":
                    _digital_signature_issue(
                        issues,
                        "invalid-package-signature-certificate-content-type",
                        (member, certificate_status),
                    )
                payload, fallback_signature = _digital_signature_bounded_payload(
                    archive,
                    member,
                    warnings,
                    budget,
                    kind="certificate",
                )
                if payload is None:
                    _digital_signature_issue(
                        issues,
                        "unreadable-package-signature-certificate-part",
                        (member, fallback_signature),
                    )
                    package_entries.append(
                        (
                            "unreadable-package-signature-certificate-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                package_entries.append(
                    (
                        "package-signature-certificate",
                        repr((member, _private_payload_signature(payload))),
                    )
                )

            discovered_vba_signatures = {
                member
                for member in members
                if _VBA_PROJECT_SIGNATURE_PART_PATTERN.fullmatch(member)
            }
            declared_vba_signatures: set[str] = set()
            vba_signature_relationship_count = 0
            declared_vba_signature_relationship_count = 0
            vba_project_member = "xl/vbaProject.bin"
            vba_relationship_member = _relationship_part_path(vba_project_member)
            if vba_relationship_member in members:
                try:
                    vba_relationships = _package_relationships(
                        archive,
                        vba_project_member,
                    )
                except (
                    ElementTree.ParseError,
                    KeyError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    _digital_signature_issue(
                        issues,
                        "vba-signature-relationship-scan-failure",
                        type(error).__name__,
                    )
                    vba_relationships = ()
                for relationship in vba_relationships:
                    relationship_suffix = relationship.relationship_type.rsplit(
                        "/",
                        maxsplit=1,
                    )[-1].casefold()
                    if not relationship_suffix.startswith("vbaprojectsignature"):
                        continue
                    vba_signature_relationship_count += 1
                    relationship_target = _digital_signature_target(relationship)
                    relationship_entries.append(
                        (
                            "vba-project-signature-relationship",
                            repr(
                                (
                                    relationship.relationship_type,
                                    relationship.target_mode.casefold(),
                                    relationship_target,
                                )
                            ),
                        )
                    )
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        _digital_signature_issue(
                            issues,
                            "unsafe-vba-project-signature-relationship",
                            (
                                relationship.relationship_type,
                                relationship.target_mode,
                                relationship_target,
                            ),
                        )
                        continue
                    declared_vba_signature_relationship_count += 1
                    declared_vba_signatures.add(relationship.target)
            elif discovered_vba_signatures:
                _digital_signature_issue(
                    issues,
                    "missing-vba-project-signature-relationship-part",
                    vba_project_member,
                )

            if discovered_vba_signatures and vba_project_member not in members:
                _digital_signature_issue(
                    issues,
                    "vba-project-signature-without-vba-project",
                    tuple(sorted(discovered_vba_signatures)),
                )
            if (
                len(declared_vba_signatures)
                != declared_vba_signature_relationship_count
            ):
                _digital_signature_issue(
                    issues,
                    "duplicate-vba-project-signature-target",
                    tuple(sorted(declared_vba_signatures)),
                )
            for member in discovered_vba_signatures - declared_vba_signatures:
                _digital_signature_issue(
                    issues,
                    "unbound-vba-project-signature-part",
                    member,
                )
            vba_signature_members = discovered_vba_signatures | declared_vba_signatures
            for member in sorted(
                origin_members
                | xml_signature_members
                | package_certificate_members
                | vba_signature_members,
                key=str.casefold,
            ):
                if (count := member_counts.get(member, 0)) > 1:
                    _digital_signature_issue(
                        issues,
                        "duplicate-digital-signature-package-member",
                        (member, count),
                    )
            for member in sorted(vba_signature_members, key=str.casefold):
                payload, fallback_signature = _digital_signature_bounded_payload(
                    archive,
                    member,
                    warnings,
                    budget,
                    kind="VBA",
                )
                if payload is None:
                    _digital_signature_issue(
                        issues,
                        "unreadable-vba-project-signature-part",
                        (member, fallback_signature),
                    )
                    vba_entries.append(
                        (
                            "unreadable-vba-project-signature-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                vba_entries.append(
                    (
                        "vba-project-signature",
                        repr((member, _private_payload_signature(payload))),
                    )
                )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _DigitalSignatureMetadata(
            DigitalSignatureSnapshot(
                unrecognized_digital_signature_count=1,
                package_signature_signature=_private_external_data_signature(
                    (("digital-signature-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect digital-signature OOXML "
                f"({type(error).__name__}); affected signature controls were not compared.",
            ),
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported digital-signature metadata; "
            "affected signature controls have a coverage gap."
        )
    package_entries.extend(
        ("digital-signature-issue", repr(issue))
        for issue in issues
    )
    snapshot = DigitalSignatureSnapshot(
        package_signature_origin_count=len(origin_members),
        package_xml_signature_count=len(xml_signature_members),
        package_signature_reference_count=sum(
            inspection.reference_count for inspection in xml_inspections
        ),
        package_signature_certificate_count=sum(
            inspection.certificate_count for inspection in xml_inspections
        ),
        package_signature_certificate_part_count=len(package_certificate_members),
        package_signature_certificate_relationship_count=(
            package_certificate_relationship_count
        ),
        vba_project_signature_count=len(vba_signature_members),
        vba_project_signature_relationship_count=vba_signature_relationship_count,
        unrecognized_digital_signature_count=len(issues),
        package_signature_signature=(
            _private_external_data_signature(tuple(sorted(package_entries)))
            if package_entries
            else None
        ),
        vba_signature_payload_signature=(
            _private_external_data_signature(tuple(sorted(vba_entries)))
            if vba_entries
            else None
        ),
        relationship_signature=(
            _private_external_data_signature(tuple(sorted(relationship_entries)))
            if relationship_entries
            else None
        ),
    )
    return _DigitalSignatureMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _PythonInExcelBudget:
    """Bound raw reads across Python-in-Excel package declarations."""

    remaining_parts: int = _PYTHON_IN_EXCEL_TOTAL_XML_PARTS
    remaining_bytes: int = _PYTHON_IN_EXCEL_TOTAL_XML_BYTES
    remaining_xml_elements: int = _PYTHON_IN_EXCEL_TOTAL_XML_MAX_ELEMENT_COUNT


def _python_in_excel_issue(
    issues: list[tuple[str, str]],
    context: str,
    detail: object,
) -> None:
    """Record private Python-in-Excel coverage evidence without source code."""
    issues.append((context, repr(detail)))


def _python_in_excel_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _PythonInExcelBudget,
    *,
    report_failure: bool,
) -> str | None:
    """Stream Python-in-Excel XML before recursively canonicalizing its tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _PYTHON_IN_EXCEL_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    if report_failure:
        warnings.add(
            "FormulaFence did not fully read a Python-in-Excel XML part whose XML "
            "structure exceeds the safety budget; affected Python code has a "
            "coverage gap."
        )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _python_in_excel_variant_for_member(member: str | None) -> str | None:
    """Return the recognized Python package variant for one normalized member."""
    if member is None:
        return None
    return _PYTHON_IN_EXCEL_VARIANT_BY_MEMBER.get(member.casefold())


def _python_in_excel_variant_for_content_type(
    content_type: str | None,
) -> str | None:
    """Return the recognized Python package variant for one content type."""
    if content_type is None:
        return None
    return _PYTHON_IN_EXCEL_VARIANT_BY_CONTENT_TYPE.get(content_type.casefold())


def _python_in_excel_variant_for_relationship(
    relationship_type: str | None,
) -> str | None:
    """Return the recognized Python package variant for one relationship."""
    if relationship_type is None:
        return None
    return _PYTHON_IN_EXCEL_VARIANT_BY_RELATIONSHIP.get(
        relationship_type.casefold()
    )


def _python_in_excel_variant_for_root(root: ElementTree.Element) -> str | None:
    """Return the recognized Python package variant for one XML root."""
    return _PYTHON_IN_EXCEL_VARIANT_BY_ROOT.get(
        (_xml_namespace(root.tag), _xml_local_name(root.tag))
    )


def _python_in_excel_bounded_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _PythonInExcelBudget,
    *,
    report_failure: bool = True,
) -> tuple[bytes | None, str | None]:
    """Read one Python-in-Excel XML member within fixed scan budgets."""
    if budget.remaining_parts <= 0:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded Python-in-Excel XML part count "
                "budget; affected Python code was not compared."
            )
        return None, _private_external_data_signature(
            (("python-in-excel-part-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        if report_failure:
            warnings.add(
                "FormulaFence could not locate a Python-in-Excel package part; "
                "affected Python code was not compared."
            )
        return None, _private_external_data_signature(
            (("missing-python-in-excel-member", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _PYTHON_IN_EXCEL_MAX_XML_PART_BYTES:
        if report_failure:
            warnings.add(
                "FormulaFence did not fully read an oversized Python-in-Excel XML "
                "part; affected Python code has a coverage gap."
            )
        return None, _private_external_data_signature(
            (("oversized-python-in-excel-part", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded Python-in-Excel XML read budget; "
                "affected Python code was not compared."
            )
        return None, _private_external_data_signature(
            (("python-in-excel-read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = (
        _python_in_excel_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            warnings,
            budget,
            report_failure=report_failure,
        )
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not read a Python-in-Excel XML package part "
                f"({type(error).__name__}); affected Python code was not compared."
            )
        return None, _private_external_data_signature(
            (("unreadable-python-in-excel-member", metadata),)
        )


def _python_in_excel_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _PythonInExcelBudget,
    *,
    report_failure: bool = True,
) -> tuple[ElementTree.Element | None, str | None]:
    """Return one bounded Python-in-Excel XML root or private failure evidence."""
    payload, fallback_signature = _python_in_excel_bounded_payload(
        archive,
        member,
        warnings,
        budget,
        report_failure=report_failure,
    )
    if payload is None:
        return None, fallback_signature
    try:
        return _xml_root_from_payload(payload), None
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not parse a Python-in-Excel XML package part "
                f"({type(error).__name__}); affected Python code was not compared."
            )
        return None, _private_payload_signature(payload)


def _python_in_excel_content_type_members(
    archive: ZipFile,
    warnings: set[str],
    budget: _PythonInExcelBudget,
    issues: list[tuple[str, str]],
) -> tuple[dict[str, str], str | None]:
    """Discover Python parts declared by content type without exposing paths."""
    root, fallback_signature = _python_in_excel_bounded_root(
        archive,
        "[Content_Types].xml",
        warnings,
        budget,
        report_failure=False,
    )
    if root is None:
        return {}, fallback_signature
    if (
        _xml_namespace(root.tag) != _CONTENT_TYPES_NS
        or _xml_local_name(root.tag) != "Types"
    ):
        return {}, _private_external_data_signature(
            (
                (
                    "unexpected-python-in-excel-content-types-root",
                    _xml_display_name(root.tag),
                ),
            )
        )

    members: dict[str, str] = {}
    override_tag = f"{{{_CONTENT_TYPES_NS}}}Override"
    for child in root:
        if child.tag != override_tag:
            continue
        raw_member = child.get("PartName")
        raw_content_type = child.get("ContentType")
        member = (
            _normalise_content_type_part_name(raw_member)
            if raw_member is not None
            else None
        )
        content_type = raw_content_type.casefold() if raw_content_type else None
        member_variant = _python_in_excel_variant_for_member(member)
        content_type_variant = _python_in_excel_variant_for_content_type(
            content_type
        )
        if member_variant is None and content_type_variant is None:
            continue
        if member is None or content_type is None:
            _python_in_excel_issue(
                issues,
                "malformed-python-in-excel-content-type-override",
                (raw_member, raw_content_type),
            )
            continue
        variant = content_type_variant or member_variant
        if variant is None:
            continue
        if (
            member_variant is not None
            and content_type_variant is not None
            and member_variant != content_type_variant
        ):
            _python_in_excel_issue(
                issues,
                "mismatched-python-in-excel-content-type-contract",
                (member, member_variant, content_type_variant),
            )
        elif member_variant is not None and content_type_variant is None:
            _python_in_excel_issue(
                issues,
                "unexpected-python-in-excel-content-type",
                (member, content_type),
            )
        existing_variant = members.get(member)
        if existing_variant is not None and existing_variant != variant:
            _python_in_excel_issue(
                issues,
                "ambiguous-python-in-excel-content-type-contract",
                (member, existing_variant, variant),
            )
            continue
        members[member] = variant
    return members, None


def _python_in_excel_workbook_relationships(
    archive: ZipFile,
    members: set[str],
    warnings: set[str],
    budget: _PythonInExcelBudget,
    issues: list[tuple[str, str]],
) -> tuple[tuple[tuple[_PackageRelationship, str], ...], str | None]:
    """Read only Python-relevant workbook relationships without following them."""
    relationship_member = _relationship_part_path("xl/workbook.xml")
    if relationship_member not in members:
        return (), None
    root, fallback_signature = _python_in_excel_bounded_root(
        archive,
        relationship_member,
        warnings,
        budget,
        report_failure=False,
    )
    if root is None:
        return (), fallback_signature
    if (
        _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
        or _xml_local_name(root.tag) != "Relationships"
    ):
        return (), _private_external_data_signature(
            (
                (
                    "unexpected-python-in-excel-workbook-relationship-root",
                    _xml_display_name(root.tag),
                ),
            )
        )

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    result: list[tuple[_PackageRelationship, str]] = []
    identifiers: list[str] = []
    for child in root:
        if child.tag != relationship_tag:
            continue
        relationship_type = child.get("Type")
        raw_target = child.get("Target")
        target_mode = child.get("TargetMode", "Internal")
        target = (
            _normalise_part_target("xl/workbook.xml", raw_target)
            if raw_target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationship_variant = _python_in_excel_variant_for_relationship(
            relationship_type
        )
        target_variant = _python_in_excel_variant_for_member(target)
        if relationship_variant is None and target_variant is None:
            continue
        variant = relationship_variant or target_variant
        if variant is None:
            continue
        relationship_id = child.get("Id")
        if not relationship_id:
            _python_in_excel_issue(
                issues,
                "missing-python-in-excel-workbook-relationship-id",
                _xml_fragment(child).sort_key(),
            )
        else:
            identifiers.append(relationship_id)
        if relationship_type is None or raw_target is None:
            _python_in_excel_issue(
                issues,
                "malformed-python-in-excel-workbook-relationship",
                _xml_fragment(child).sort_key(),
            )
        if (
            relationship_variant is not None
            and target_variant is not None
            and relationship_variant != target_variant
        ):
            _python_in_excel_issue(
                issues,
                "mismatched-python-in-excel-workbook-relationship-contract",
                (relationship_type, target),
            )
        elif relationship_variant is None:
            _python_in_excel_issue(
                issues,
                "unexpected-python-in-excel-workbook-relationship-type",
                relationship_type,
            )
        if target_mode.casefold() != "internal" or target is None:
            _python_in_excel_issue(
                issues,
                "unsafe-python-in-excel-workbook-relationship-target",
                (target_mode, raw_target),
            )
        result.append(
            (
                _PackageRelationship(
                    relationship_id=relationship_id,
                    relationship_type=relationship_type or "",
                    target=target,
                    target_mode=target_mode,
                    raw_target=raw_target,
                ),
                variant,
            )
        )
    if len(identifiers) != len(set(identifiers)):
        _python_in_excel_issue(
            issues,
            "duplicate-python-in-excel-workbook-relationship-id",
            tuple(sorted(identifiers)),
        )
    return tuple(result), None


def _python_in_excel_metadata(path: Path) -> _PythonInExcelMetadata:
    """Inventory stored Python-in-Excel code without executing or exposing it.

    Excel can keep Python code in the documented workbook-level ``xl/python.xml``
    part and in a separately stored 2022 ``xl/pythonScripts.xml`` part. This
    scanner fingerprints both bounded XML contracts privately, while publishing
    only aggregate physical-part, script, environment, and coverage counts. It
    never loads the code as Python, contacts the Microsoft Cloud, or evaluates a
    formula.
    """
    warnings: set[str] = set()
    issues: list[tuple[str, str]] = []
    definition_entries: list[tuple[str, str]] = []
    try:
        with ZipFile(path) as archive:
            raw_members = archive.namelist()
            members = set(raw_members)
            member_counts = Counter(raw_members)
            budget = _PythonInExcelBudget()
            probe_issues: list[tuple[str, str]] = []
            content_type_members, content_type_fallback = (
                _python_in_excel_content_type_members(
                    archive,
                    warnings,
                    budget,
                    probe_issues,
                )
            )
            relationship_issues: list[tuple[str, str]] = []
            workbook_relationships, relationship_fallback = (
                _python_in_excel_workbook_relationships(
                    archive,
                    members,
                    warnings,
                    budget,
                    relationship_issues,
                )
            )
            relationship_members = {
                relationship.target
                for relationship, _variant in workbook_relationships
                if relationship.target is not None
            }
            python_member_variants: dict[str, set[str]] = defaultdict(set)
            for member, variant in content_type_members.items():
                python_member_variants[member].add(variant)
            for relationship, variant in workbook_relationships:
                if relationship.target is not None:
                    python_member_variants[relationship.target].add(variant)
            for member, variant in (
                (
                    _PYTHON_IN_EXCEL_CANONICAL_MEMBER,
                    _PYTHON_IN_EXCEL_VARIANT_PYTHON,
                ),
                (
                    _PYTHON_IN_EXCEL_SCRIPTS_CANONICAL_MEMBER,
                    _PYTHON_IN_EXCEL_VARIANT_PYTHON_SCRIPTS,
                ),
            ):
                if member in members:
                    python_member_variants[member].add(variant)
            python_members = set(python_member_variants)
            python_evidence = bool(python_members or workbook_relationships)
            if not python_evidence:
                return _PythonInExcelMetadata(PythonInExcelSnapshot(), ())

            issues.extend(probe_issues)
            issues.extend(relationship_issues)
            if content_type_fallback is not None:
                _python_in_excel_issue(
                    issues,
                    "unreadable-python-in-excel-content-types",
                    content_type_fallback,
                )
            if relationship_fallback is not None:
                _python_in_excel_issue(
                    issues,
                    "unreadable-python-in-excel-workbook-relationships",
                    relationship_fallback,
                )

            for member, variant in sorted(
                content_type_members.items(), key=lambda item: item[0].casefold()
            ):
                definition_entries.append(
                    ("python-in-excel-content-type", repr((member, variant)))
                )
            relationship_semantics = tuple(
                sorted(
                    (
                        variant,
                        relationship.relationship_type.casefold(),
                        relationship.target_mode.casefold(),
                        relationship.target
                        if relationship.target is not None
                        else relationship.raw_target or "",
                    )
                    for relationship, variant in workbook_relationships
                )
            )
            if relationship_semantics:
                definition_entries.append(
                    (
                        "python-in-excel-workbook-relationships",
                        repr(relationship_semantics),
                    )
                )

            for member in sorted(python_members, key=str.casefold):
                if member not in members:
                    _python_in_excel_issue(
                        issues,
                        "missing-python-in-excel-package-member",
                        member,
                    )
                    continue
                if (count := member_counts[member]) > 1:
                    _python_in_excel_issue(
                        issues,
                        "duplicate-python-in-excel-package-member",
                        (member, count),
                    )

            for member, variants in sorted(
                python_member_variants.items(), key=lambda item: item[0].casefold()
            ):
                if len(variants) > 1:
                    _python_in_excel_issue(
                        issues,
                        "ambiguous-python-in-excel-package-contract",
                        (member, tuple(sorted(variants))),
                    )

            if relationship_fallback is None:
                for member in sorted(python_members, key=str.casefold):
                    if member in members and member not in relationship_members:
                        _python_in_excel_issue(
                            issues,
                            "unbound-python-in-excel-package-member",
                            member,
                        )

            python_part_count = 0
            python_script_count = 0
            python_environment_definition_count = 0
            python_initialization_count = 0
            root_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}python"
            environment_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}environmentDefinition"
            initialization_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}initialization"
            scripts_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}pythonScripts"
            script_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}pythonScript"
            code_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}code"
            extension_tag = f"{{{_PYTHON_IN_EXCEL_NS}}}extLst"
            scripts_root_tag = f"{{{_PYTHON_IN_EXCEL_SCRIPTS_NS}}}pythonScripts"
            scripts_script_tag = f"{{{_PYTHON_IN_EXCEL_SCRIPTS_NS}}}pythonScript"
            scripts_code_tag = f"{{{_PYTHON_IN_EXCEL_SCRIPTS_NS}}}code"

            for member in sorted(python_members & members, key=str.casefold):
                python_part_count += 1
                root, fallback_signature = _python_in_excel_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if root is None:
                    _python_in_excel_issue(
                        issues,
                        "unreadable-python-in-excel-package-member",
                        (member, fallback_signature),
                    )
                    continue
                definition_entries.append(
                    (
                        "python-in-excel-package-part",
                        repr(
                            (
                                member,
                                tuple(sorted(python_member_variants[member])),
                                _xml_fragment(root).sort_key(),
                            )
                        ),
                    )
                )
                root_variant = _python_in_excel_variant_for_root(root)
                if root_variant is None:
                    _python_in_excel_issue(
                        issues,
                        "unexpected-python-in-excel-root",
                        (member, _xml_display_name(root.tag)),
                    )
                    continue
                if root_variant not in python_member_variants[member]:
                    _python_in_excel_issue(
                        issues,
                        "mismatched-python-in-excel-package-root-contract",
                        (
                            member,
                            tuple(sorted(python_member_variants[member])),
                            root_variant,
                        ),
                    )

                if root_variant == _PYTHON_IN_EXCEL_VARIANT_PYTHON:
                    if root.tag != root_tag:
                        _python_in_excel_issue(
                            issues,
                            "unexpected-python-in-excel-root",
                            (member, _xml_display_name(root.tag)),
                        )
                        continue
                    environment_definitions = [
                        child for child in root if child.tag == environment_tag
                    ]
                    scripts_containers = [
                        child for child in root if child.tag == scripts_tag
                    ]
                    python_environment_definition_count += len(environment_definitions)
                    if len(environment_definitions) > 1:
                        _python_in_excel_issue(
                            issues,
                            "duplicate-python-in-excel-environment-definition",
                            (member, len(environment_definitions)),
                        )
                    if len(scripts_containers) > 1:
                        _python_in_excel_issue(
                            issues,
                            "duplicate-python-in-excel-script-container",
                            (member, len(scripts_containers)),
                        )
                    for child in root:
                        if child.tag not in {
                            environment_tag,
                            scripts_tag,
                            extension_tag,
                        }:
                            _python_in_excel_issue(
                                issues,
                                "unexpected-python-in-excel-root-child",
                                (member, _xml_display_name(child.tag)),
                            )

                    for environment in environment_definitions:
                        initializations = [
                            child
                            for child in environment
                            if child.tag == initialization_tag
                        ]
                        python_initialization_count += len(initializations)
                        if len(initializations) > 1:
                            _python_in_excel_issue(
                                issues,
                                "duplicate-python-in-excel-environment-initialization",
                                (member, len(initializations)),
                            )
                        for child in environment:
                            if child.tag not in {initialization_tag, extension_tag}:
                                _python_in_excel_issue(
                                    issues,
                                    "unexpected-python-in-excel-environment-child",
                                    (member, _xml_display_name(child.tag)),
                                )
                        for initialization in initializations:
                            code_children = [
                                child
                                for child in initialization
                                if child.tag == code_tag
                            ]
                            if (
                                len(code_children) > 1
                                or len(code_children) != len(initialization)
                            ):
                                _python_in_excel_issue(
                                    issues,
                                    (
                                        "malformed-python-in-excel-"
                                        "environment-initialization"
                                    ),
                                    (
                                        member,
                                        _xml_fragment(initialization).sort_key(),
                                    ),
                                )

                    for scripts in scripts_containers:
                        script_children = [
                            child for child in scripts if child.tag == script_tag
                        ]
                        python_script_count += len(script_children)
                        if not script_children:
                            _python_in_excel_issue(
                                issues,
                                "empty-python-in-excel-script-container",
                                member,
                            )
                        if len(script_children) != len(scripts):
                            _python_in_excel_issue(
                                issues,
                                "unexpected-python-in-excel-script-container-child",
                                (member, _xml_fragment(scripts).sort_key()),
                            )
                        for script in script_children:
                            code_children = [
                                child for child in script if child.tag == code_tag
                            ]
                            if (
                                len(code_children) > 1
                                or any(
                                    child.tag not in {code_tag, extension_tag}
                                    for child in script
                                )
                            ):
                                _python_in_excel_issue(
                                    issues,
                                    "malformed-python-in-excel-script",
                                    (member, _xml_fragment(script).sort_key()),
                                )
                else:
                    if root.tag != scripts_root_tag:
                        _python_in_excel_issue(
                            issues,
                            "unexpected-python-in-excel-root",
                            (member, _xml_display_name(root.tag)),
                        )
                        continue
                    script_children = [
                        child for child in root if child.tag == scripts_script_tag
                    ]
                    python_script_count += len(script_children)
                    if not script_children:
                        _python_in_excel_issue(
                            issues,
                            "empty-python-in-excel-scripts-part",
                            member,
                        )
                    if len(script_children) != len(root):
                        _python_in_excel_issue(
                            issues,
                            "unexpected-python-in-excel-scripts-part-child",
                            (member, _xml_fragment(root).sort_key()),
                        )
                    for script in script_children:
                        code_children = [
                            child for child in script if child.tag == scripts_code_tag
                        ]
                        if (
                            len(code_children) != 1
                            or len(code_children) != len(script)
                        ):
                            _python_in_excel_issue(
                                issues,
                                "malformed-python-in-excel-scripts-script",
                                (member, _xml_fragment(script).sort_key()),
                            )

            if issues:
                warnings.add(
                    "FormulaFence found malformed or unsupported Python-in-Excel "
                    "metadata; affected Python code has a coverage gap."
                )
            definition_entries.extend(
                ("python-in-excel-issue", repr(issue)) for issue in issues
            )
            return _PythonInExcelMetadata(
                PythonInExcelSnapshot(
                    python_part_count=python_part_count,
                    python_script_count=python_script_count,
                    python_environment_definition_count=(
                        python_environment_definition_count
                    ),
                    python_initialization_count=python_initialization_count,
                    unrecognized_python_in_excel_count=len(issues),
                    definition_signature=_private_external_data_signature(
                        tuple(sorted(definition_entries))
                    ),
                ),
                tuple(sorted(warnings)),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _PythonInExcelMetadata(
            PythonInExcelSnapshot(
                unrecognized_python_in_excel_count=1,
                definition_signature=_private_external_data_signature(
                    (("python-in-excel-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect Python-in-Excel OOXML "
                f"({type(error).__name__}); affected Python code was not compared.",
            ),
        )


@dataclass
class _RichDataBudget:
    """Bound raw XML reads across rich-data package declarations."""

    remaining_parts: int = _RICH_DATA_TOTAL_XML_PARTS
    remaining_bytes: int = _RICH_DATA_TOTAL_XML_BYTES
    remaining_xml_elements: int = _RICH_DATA_TOTAL_XML_MAX_ELEMENT_COUNT


def _rich_data_issue(
    issues: list[tuple[str, str]],
    context: str,
    detail: object,
) -> None:
    """Record private rich-data coverage evidence without exposing content."""
    issues.append((context, repr(detail)))


def _rich_data_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _RichDataBudget,
    *,
    report_failure: bool,
) -> str | None:
    """Stream rich-data XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _RICH_DATA_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    if report_failure:
        warnings.add(
            "FormulaFence did not fully read a rich-data XML part whose XML "
            "structure exceeds the safety budget; affected rich data has a "
            "coverage gap."
        )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _rich_data_bounded_member_info(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _RichDataBudget,
    *,
    report_failure: bool,
):
    """Reserve one raw rich-data member before reading or streaming it."""
    if budget.remaining_parts <= 0:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded rich-data XML part count budget; "
                "affected rich data was not compared."
            )
        return None, _private_external_data_signature(
            (("rich-data-part-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        if report_failure:
            warnings.add(
                "FormulaFence could not locate a rich-data package part; "
                "affected rich data was not compared."
            )
        return None, _private_external_data_signature(
            (("missing-rich-data-member", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _RICH_DATA_MAX_XML_PART_BYTES:
        if report_failure:
            warnings.add(
                "FormulaFence did not fully read an oversized rich-data XML part; "
                "affected rich data has a coverage gap."
            )
        return None, _private_external_data_signature(
            (("oversized-rich-data-part", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded rich-data XML read budget; "
                "affected rich data was not compared."
            )
        return None, _private_external_data_signature(
            (("rich-data-read-budget-exhausted", metadata),)
        )
    return info, None


def _rich_data_bounded_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _RichDataBudget,
    *,
    report_failure: bool = True,
) -> tuple[bytes | None, str | None]:
    """Read one rich-data XML member within fixed scan budgets."""
    info, fallback_signature = _rich_data_bounded_member_info(
        archive,
        member,
        warnings,
        budget,
        report_failure=report_failure,
    )
    if info is None:
        return None, fallback_signature
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    structure_fallback_signature = _rich_data_xml_structure_budget_fallback_signature(
        archive,
        member,
        info,
        warnings,
        budget,
        report_failure=report_failure,
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not read a rich-data XML package part "
                f"({type(error).__name__}); affected rich data was not compared."
            )
        return None, _private_external_data_signature(
            (("unreadable-rich-data-member", metadata),)
        )


def _rich_data_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _RichDataBudget,
    *,
    report_failure: bool = True,
) -> tuple[ElementTree.Element | None, str | None]:
    """Return one bounded rich-data XML root or a private failure signature."""
    payload, fallback_signature = _rich_data_bounded_payload(
        archive,
        member,
        warnings,
        budget,
        report_failure=report_failure,
    )
    if payload is None:
        return None, fallback_signature
    try:
        return _xml_root_from_payload(payload), None
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not parse a rich-data XML package part "
                f"({type(error).__name__}); affected rich data was not compared."
            )
        return None, _private_payload_signature(payload)


def _rich_data_unsigned(
    value: str | None,
    issues: list[tuple[str, str]],
    *,
    context: str,
    required: bool = True,
) -> int | None:
    """Read one bounded unsigned rich-data index without accepting malformed input."""
    if value is None:
        if required:
            _rich_data_issue(issues, f"missing-{context}", None)
        return None
    candidate = value.strip()
    if not _RICH_DATA_UNSIGNED_PATTERN.fullmatch(candidate):
        _rich_data_issue(issues, f"invalid-{context}", value)
        return None
    try:
        parsed = int(candidate)
    except ValueError:
        _rich_data_issue(issues, f"invalid-{context}", value)
        return None
    if not 0 <= parsed <= 2_147_483_647:
        _rich_data_issue(issues, f"out-of-range-{context}", value)
        return None
    return parsed


def _rich_data_worksheet_value_metadata_bindings(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _RichDataBudget,
    issues: list[tuple[str, str]],
    value_metadata_indexes: frozenset[int],
    *,
    worksheet_tag: str,
    cell_tag: str,
) -> tuple[str | None, tuple[tuple[str, int], ...], str | None]:
    """Stream rich-value cell bindings without building a worksheet XML tree.

    Worksheet XML has already passed the shared semantic-reader preflight. This
    raw pass needs only ``vm`` and ``r`` attributes from matching cells, so
    retaining a second complete tree would impose a separate allocation cost on
    otherwise ordinary large worksheets.
    """
    info, fallback_signature = _rich_data_bounded_member_info(
        archive,
        member,
        warnings,
        budget,
        report_failure=True,
    )
    if info is None:
        return None, (), fallback_signature

    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    budget.remaining_bytes -= info.file_size
    root_tag: str | None = None
    bindings: list[tuple[str, int]] = []
    parents: list[ElementTree.Element] = []
    try:
        with archive.open(member) as xml_stream:
            for event, element in _iterparse_ooxml_xml_with_character_data_budget(
                xml_stream
            ):
                if event == "start":
                    if not parents:
                        root_tag = element.tag
                    parents.append(element)
                    if root_tag != worksheet_tag or element.tag != cell_tag:
                        continue
                    raw_value_metadata_index = element.get("vm")
                    if raw_value_metadata_index is None:
                        continue
                    value_metadata_index = _rich_data_unsigned(
                        raw_value_metadata_index,
                        issues,
                        context="rich-data-cell-value-metadata-index",
                    )
                    if value_metadata_index is None:
                        continue
                    if value_metadata_index <= 0:
                        _rich_data_issue(
                            issues,
                            "out-of-range-rich-data-cell-value-metadata-index",
                            (member, value_metadata_index),
                        )
                        continue
                    if value_metadata_index not in value_metadata_indexes:
                        continue
                    coordinate = element.get("r")
                    if not coordinate:
                        _rich_data_issue(
                            issues,
                            "missing-rich-data-bound-cell-coordinate",
                            member,
                        )
                        continue
                    bindings.append((coordinate, value_metadata_index))
                    continue

                parents.pop()
                if parents:
                    parents[-1].remove(element)
                element.clear()
    except (BadZipFile, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not parse a rich-data worksheet XML package part "
            f"({type(error).__name__}); affected rich data was not compared."
        )
        return None, (), _private_external_data_signature(
            (
                ("unparseable-rich-data-worksheet", metadata),
                ("error", type(error).__name__),
            )
        )
    return root_tag, tuple(bindings), None


def _rich_data_declared_count(
    root: ElementTree.Element,
    actual_count: int,
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> None:
    """Check a rich-data count attribute without treating an invalid count as safe."""
    declared_count = _rich_data_unsigned(
        root.get("count"),
        issues,
        context=f"{context}-count",
        required=False,
    )
    if declared_count is not None and declared_count != actual_count:
        _rich_data_issue(
            issues,
            f"mismatched-{context}-count",
            (declared_count, actual_count),
        )


def _rich_data_content_type_declarations(
    archive: ZipFile,
    warnings: set[str],
    budget: _RichDataBudget,
    issues: list[tuple[str, str]],
) -> tuple[dict[str, tuple[str, ...]], str | None]:
    """Read rich-data-relevant OPC content types without exposing part content."""
    root, fallback_signature = _rich_data_bounded_root(
        archive,
        "[Content_Types].xml",
        warnings,
        budget,
        report_failure=False,
    )
    if root is None:
        return {}, fallback_signature
    if (
        _xml_namespace(root.tag) != _CONTENT_TYPES_NS
        or _xml_local_name(root.tag) != "Types"
    ):
        return {}, _private_external_data_signature(
            (
                (
                    "unexpected-rich-data-content-types-root",
                    _xml_display_name(root.tag),
                ),
            )
        )
    declarations: dict[str, list[str]] = defaultdict(list)
    override_tag = f"{{{_CONTENT_TYPES_NS}}}Override"
    for child in root:
        if child.tag != override_tag:
            continue
        raw_member = child.get("PartName")
        raw_content_type = child.get("ContentType")
        member = (
            _normalise_content_type_part_name(raw_member)
            if raw_member is not None
            else None
        )
        content_type = raw_content_type.casefold() if raw_content_type else None
        raw_is_rich_path = bool(
            raw_member
            and raw_member.lstrip("/").casefold().startswith("xl/richdata/")
        )
        is_rich_path = bool(
            member and member.casefold().startswith("xl/richdata/")
        )
        if (
            not raw_is_rich_path
            and not is_rich_path
            and content_type not in _RICH_DATA_PART_CONTENT_TYPES
        ):
            continue
        if member is None or content_type is None:
            _rich_data_issue(
                issues,
                "malformed-rich-data-content-type-override",
                (raw_member, raw_content_type),
            )
            continue
        declarations[member].append(content_type)
    return (
        {
            member: tuple(sorted(values))
            for member, values in declarations.items()
        },
        None,
    )


def _rich_data_part_relationships(
    archive: ZipFile,
    source_member: str,
    members: set[str],
    warnings: set[str],
    budget: _RichDataBudget,
    issues: list[tuple[str, str]],
    *,
    required: bool,
    context: str,
    report_failure: bool = True,
) -> tuple[_PackageRelationship, ...]:
    """Read one rich-data relationship part without following target endpoints."""
    relationship_member = _relationship_part_path(source_member)
    if relationship_member not in members:
        if required:
            _rich_data_issue(
                issues,
                f"missing-{context}-relationship-part",
                relationship_member,
            )
        return ()
    root, fallback_signature = _rich_data_bounded_root(
        archive,
        relationship_member,
        warnings,
        budget,
        report_failure=report_failure,
    )
    if root is None:
        _rich_data_issue(
            issues,
            f"unreadable-{context}-relationship-part",
            (relationship_member, fallback_signature),
        )
        return ()
    if (
        _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
        or _xml_local_name(root.tag) != "Relationships"
    ):
        _rich_data_issue(
            issues,
            f"unexpected-{context}-relationship-root",
            _xml_display_name(root.tag),
        )
        return ()
    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_PackageRelationship] = []
    ids: list[str] = []
    for child in root:
        if child.tag != relationship_tag:
            _rich_data_issue(
                issues,
                f"unexpected-{context}-relationship-child",
                _xml_fragment(child).sort_key(),
            )
            continue
        relationship_id = child.get("Id")
        if relationship_id is None or not relationship_id:
            _rich_data_issue(
                issues,
                f"missing-{context}-relationship-id",
                _xml_fragment(child).sort_key(),
            )
        else:
            ids.append(relationship_id)
        relationship_type = child.get("Type")
        raw_target = child.get("Target")
        target_mode = child.get("TargetMode", "Internal")
        if relationship_type is None or raw_target is None:
            _rich_data_issue(
                issues,
                f"malformed-{context}-relationship",
                _xml_fragment(child).sort_key(),
            )
        relationships.append(
            _PackageRelationship(
                relationship_id=relationship_id,
                relationship_type=relationship_type or "",
                target=(
                    _normalise_part_target(source_member, raw_target)
                    if raw_target is not None
                    and target_mode.casefold() == "internal"
                    else None
                ),
                target_mode=target_mode,
                raw_target=raw_target,
            )
        )
    if len(ids) != len(set(ids)):
        _rich_data_issue(
            issues,
            f"duplicate-{context}-relationship-id",
            tuple(sorted(ids)),
        )
    return tuple(relationships)


def _rich_data_relationship_target(relationship: _PackageRelationship) -> str | None:
    """Keep a relationship endpoint only inside a private rich-data signature."""
    return (
        relationship.target
        if relationship.target is not None
        else relationship.raw_target
    )


def _rich_data_relationship_semantic(
    relationship: _PackageRelationship,
) -> tuple[str, str, str | None]:
    """Return relationship semantics while ignoring writer-selected IDs and order."""
    return (
        relationship.relationship_type.casefold(),
        relationship.target_mode.casefold(),
        _rich_data_relationship_target(relationship),
    )


def _rich_data_category_for_member(member: str) -> str | None:
    """Classify a conventional rich-data part name without trusting its XML."""
    if not member.casefold().startswith("xl/richdata/"):
        return None
    return _RICH_DATA_PART_BASENAMES.get(posixpath.basename(member).casefold())


def _rich_data_relationship_lookup(
    relationships: tuple[_PackageRelationship, ...],
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> dict[str, _PackageRelationship]:
    """Resolve unique relationship IDs while retaining duplicate IDs as gaps."""
    relationships_by_id: dict[str, list[_PackageRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
    result: dict[str, _PackageRelationship] = {}
    for relationship_id, candidates in relationships_by_id.items():
        if len(candidates) != 1:
            _rich_data_issue(
                issues,
                f"duplicate-{context}-relationship-id",
                relationship_id,
            )
            continue
        result[relationship_id] = candidates[0]
    return result


def _rich_data_relationship_aware_fragment(
    root: ElementTree.Element,
    relationships_by_id: Mapping[str, _PackageRelationship],
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> tuple[tuple[object, ...], tuple[str, ...]]:
    """Canonicalise XML relationship references without retaining writer IDs.

    The resolved endpoints remain only inside the private comparison signature.
    Relationship declaration order and assigned `rId` values therefore do not
    create a change by themselves.
    """
    references: list[str] = []

    def fragment(element: ElementTree.Element) -> tuple[object, ...]:
        attributes: list[tuple[str, object]] = []
        for attribute, value in element.attrib.items():
            if (
                _xml_namespace(attribute) == _DOCUMENT_RELATIONSHIP_NS
                and _xml_local_name(attribute) == "id"
            ):
                references.append(value)
                relationship = relationships_by_id.get(value)
                if relationship is None:
                    _rich_data_issue(
                        issues,
                        f"unresolved-{context}-relationship-reference",
                        value,
                    )
                    attributes.append(
                        (
                            _xml_display_name(attribute),
                            ("unresolved-relationship-reference", value),
                        )
                    )
                else:
                    attributes.append(
                        (
                            _xml_display_name(attribute),
                            (
                                "relationship",
                                *_rich_data_relationship_semantic(relationship),
                            ),
                        )
                    )
                continue
            attributes.append((_xml_display_name(attribute), value))
        children = tuple(fragment(child) for child in element)
        text = element.text
        if children and text is not None and not text.strip():
            text = None
        return (
            _xml_display_name(element.tag),
            tuple(sorted(attributes, key=repr)),
            text,
            children,
        )

    return fragment(root), tuple(references)


def _rich_data_relationship_entries(
    relationships: tuple[_PackageRelationship, ...],
    *,
    context: str,
) -> list[tuple[str, str]]:
    """Create order- and ID-independent private relationship evidence."""
    return [
        (
            context,
            repr(
                tuple(
                    sorted(
                        _rich_data_relationship_semantic(relationship)
                        for relationship in relationships
                    )
                )
            ),
        )
    ]


@dataclass(frozen=True)
class _RichDataMetadataInspection:
    """Private rich value-metadata bindings before worksheet-cell resolution."""

    present: bool = False
    binding_count: int = 0
    value_metadata_indexes: frozenset[int] = frozenset()
    rich_value_indexes: tuple[int, ...] = ()
    signature_entries: tuple[tuple[str, str], ...] = ()


def _rich_data_metadata_inspection(
    root: ElementTree.Element,
    issues: list[tuple[str, str]],
) -> _RichDataMetadataInspection:
    """Parse only XLRICHVALUE metadata records without exporting their values."""
    if (
        _xml_namespace(root.tag) != _SPREADSHEETML_NS
        or _xml_local_name(root.tag) != "metadata"
    ):
        _rich_data_issue(
            issues,
            "unexpected-rich-data-metadata-root",
            _xml_display_name(root.tag),
        )
        return _RichDataMetadataInspection()

    metadata_types_tag = f"{{{_SPREADSHEETML_NS}}}metadataTypes"
    metadata_type_tag = f"{{{_SPREADSHEETML_NS}}}metadataType"
    future_metadata_tag = f"{{{_SPREADSHEETML_NS}}}futureMetadata"
    value_metadata_tag = f"{{{_SPREADSHEETML_NS}}}valueMetadata"
    block_tag = f"{{{_SPREADSHEETML_NS}}}bk"
    record_tag = f"{{{_SPREADSHEETML_NS}}}rc"
    extension_tag = f"{{{_SPREADSHEETML_NS}}}ext"
    rich_value_binding_tag = f"{{{_RICH_DATA_NS}}}rvb"

    metadata_types = root.find(metadata_types_tag)
    rich_type_indexes: set[int] = set()
    metadata_entries: list[tuple[str, str]] = []
    if metadata_types is not None:
        type_nodes = list(metadata_types.findall(metadata_type_tag))
        _rich_data_declared_count(
            metadata_types,
            len(type_nodes),
            issues,
            context="rich-data-metadata-types",
        )
        for index, metadata_type in enumerate(type_nodes, start=1):
            if (
                metadata_type.get("name", "").casefold()
                != _RICH_DATA_METADATA_TYPE_NAME.casefold()
            ):
                continue
            rich_type_indexes.add(index)
            metadata_entries.append(
                (
                    "rich-data-metadata-type",
                    repr((index, _xml_fragment(metadata_type).sort_key())),
                )
            )

    future_sections = [
        section
        for section in root.findall(future_metadata_tag)
        if section.get("name", "").casefold()
        == _RICH_DATA_METADATA_TYPE_NAME.casefold()
    ]
    if len(future_sections) > 1:
        _rich_data_issue(
            issues,
            "duplicate-rich-data-future-metadata-sections",
            len(future_sections),
        )
    rich_value_indexes: list[int] = []
    for section_index, section in enumerate(future_sections):
        blocks = list(section.findall(block_tag))
        _rich_data_declared_count(
            section,
            len(blocks),
            issues,
            context="rich-data-future-metadata",
        )
        section_entries: list[tuple[int, tuple[object, ...]]] = []
        for block_index, block in enumerate(blocks):
            bindings: list[ElementTree.Element] = []
            for extension in block.iter(extension_tag):
                if (
                    extension.get("uri", "").casefold()
                    != _RICH_DATA_METADATA_EXTENSION_URI.casefold()
                ):
                    continue
                bindings.extend(extension.findall(f".//{rich_value_binding_tag}"))
            if len(bindings) != 1:
                _rich_data_issue(
                    issues,
                    "invalid-rich-data-future-metadata-binding-count",
                    (section_index, block_index, len(bindings)),
                )
                continue
            rich_value_index = _rich_data_unsigned(
                bindings[0].get("i"),
                issues,
                context="rich-data-value-index",
            )
            if rich_value_index is None:
                continue
            rich_value_indexes.append(rich_value_index)
            section_entries.append((block_index, _xml_fragment(block).sort_key()))
        if section_entries:
            metadata_entries.append(
                (
                    "rich-data-future-metadata",
                    repr((section_index, tuple(section_entries))),
                )
            )

    value_metadata_sections = list(root.findall(value_metadata_tag))
    if len(value_metadata_sections) > 1:
        _rich_data_issue(
            issues,
            "duplicate-rich-data-value-metadata-sections",
            len(value_metadata_sections),
        )
    value_metadata_indexes: set[int] = set()
    binding_count = 0
    for section_index, section in enumerate(value_metadata_sections):
        blocks = list(section.findall(block_tag))
        _rich_data_declared_count(
            section,
            len(blocks),
            issues,
            context="rich-data-value-metadata",
        )
        for block_index, block in enumerate(blocks, start=1):
            records = list(block.findall(record_tag))
            matching_records: list[tuple[object, ...]] = []
            for record in records:
                type_index = _rich_data_unsigned(
                    record.get("t"),
                    issues,
                    context="rich-data-value-metadata-type-index",
                )
                if type_index is None or type_index not in rich_type_indexes:
                    continue
                future_index = _rich_data_unsigned(
                    record.get("v"),
                    issues,
                    context="rich-data-value-metadata-value-index",
                )
                if future_index is None:
                    continue
                if future_index >= len(rich_value_indexes):
                    _rich_data_issue(
                        issues,
                        "out-of-range-rich-data-value-metadata-value-index",
                        (section_index, block_index, future_index),
                    )
                    continue
                binding_count += 1
                value_metadata_indexes.add(block_index)
                matching_records.append(_xml_fragment(record).sort_key())
            if matching_records:
                metadata_entries.append(
                    (
                        "rich-data-value-metadata-binding",
                        repr((section_index, block_index, tuple(matching_records))),
                    )
                )

    present = bool(
        rich_type_indexes
        or future_sections
        or value_metadata_indexes
        or rich_value_indexes
    )
    if present and not rich_type_indexes:
        _rich_data_issue(issues, "missing-rich-data-metadata-type", None)
    if present and not future_sections:
        _rich_data_issue(issues, "missing-rich-data-future-metadata", None)
    return _RichDataMetadataInspection(
        present=present,
        binding_count=binding_count,
        value_metadata_indexes=frozenset(value_metadata_indexes),
        rich_value_indexes=tuple(rich_value_indexes),
        signature_entries=tuple(sorted(metadata_entries)),
    )


def _rich_data_metadata(path: Path) -> _RichDataMetadata:
    """Inventory Excel rich-data controls without resolving providers or URLs.

    Rich values can contain provider-backed entities, attached fields, and web
    image associations outside normal cells. This scanner records aggregate
    counts and private semantic fingerprints only. It does not fetch external
    targets, refresh values, calculate formulas, inspect provider services, or
    emit entity data, field names, identifiers, URLs, relationship IDs, or
    bound-cell locations.
    """
    warnings: set[str] = set()
    issues: list[tuple[str, str]] = []
    definition_entries: list[tuple[str, str]] = []
    value_entries: list[tuple[str, str]] = []
    metadata_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    try:
        with ZipFile(path) as archive:
            members = set(archive.namelist())
            member_counts: dict[str, int] = defaultdict(int)
            for entry in archive.infolist():
                member_counts[entry.filename] += 1
            budget = _RichDataBudget()

            content_type_warnings: set[str] = set()
            content_type_probe_issues: list[tuple[str, str]] = []
            content_types, content_type_fallback = _rich_data_content_type_declarations(
                archive,
                content_type_warnings,
                budget,
                content_type_probe_issues,
            )
            category_members: dict[str, set[str]] = defaultdict(set)
            rich_package_candidate = False
            for member in sorted(members):
                if not member.casefold().startswith("xl/richdata/"):
                    continue
                if "/_rels/" in member.casefold():
                    continue
                rich_package_candidate = True
                category = _rich_data_category_for_member(member)
                if category is None:
                    _rich_data_issue(
                        issues,
                        "unrecognized-rich-data-package-member",
                        member,
                    )
                    continue
                category_members[category].add(member)

            for member, declarations in sorted(content_types.items()):
                rich_package_candidate = True
                if len(declarations) != 1:
                    _rich_data_issue(
                        issues,
                        "duplicate-rich-data-content-type-declaration",
                        (member, declarations),
                    )
                if member not in members:
                    _rich_data_issue(
                        issues,
                        "missing-rich-data-content-type-member",
                        member,
                    )
                for declaration in declarations:
                    category = _RICH_DATA_PART_CONTENT_TYPES.get(declaration)
                    if category is None:
                        _rich_data_issue(
                            issues,
                            "unrecognized-rich-data-content-type",
                            (member, declaration),
                        )
                        continue
                    category_members[category].add(member)
                    definition_entries.append(
                        (
                            "rich-data-content-type",
                            repr((category, member, declaration)),
                        )
                    )

            relationship_probe_warnings: set[str] = set()
            relationship_probe_issues: list[tuple[str, str]] = []
            workbook_relationships = _rich_data_part_relationships(
                archive,
                "xl/workbook.xml",
                members,
                relationship_probe_warnings,
                budget,
                relationship_probe_issues,
                required=False,
                context="workbook-rich-data",
                report_failure=False,
            )
            rich_workbook_relationships: list[
                tuple[str, _PackageRelationship]
            ] = []
            metadata_workbook_relationships: list[_PackageRelationship] = []
            for relationship in workbook_relationships:
                relationship_type = relationship.relationship_type.casefold()
                category = _RICH_DATA_RELATIONSHIP_TYPES.get(relationship_type)
                if category is not None:
                    rich_workbook_relationships.append((category, relationship))
                    if relationship.target_mode.casefold() != "internal":
                        _rich_data_issue(
                            issues,
                            "external-rich-data-workbook-relationship",
                            (category, _rich_data_relationship_semantic(relationship)),
                        )
                        continue
                    if relationship.target is None:
                        _rich_data_issue(
                            issues,
                            "unsafe-rich-data-workbook-relationship-target",
                            (
                                category,
                                _rich_data_relationship_semantic(relationship),
                            ),
                        )
                        continue
                    category_members[category].add(relationship.target)
                    continue
                if (
                    relationship.target is not None
                    and relationship.target.casefold().startswith("xl/richdata/")
                ):
                    rich_package_candidate = True
                    _rich_data_issue(
                        issues,
                        "unrecognized-rich-data-workbook-relationship",
                        _rich_data_relationship_semantic(relationship),
                    )
                if relationship_type.endswith("/sheetmetadata"):
                    metadata_workbook_relationships.append(relationship)

            metadata_probe_warnings: set[str] = set()
            metadata_probe_issues: list[tuple[str, str]] = []
            metadata_roots: dict[str, ElementTree.Element] = {}
            metadata_failures: dict[str, str | None] = {}
            canonical_metadata_member = "xl/metadata.xml"
            if canonical_metadata_member in members:
                metadata_root, metadata_fallback = _rich_data_bounded_root(
                    archive,
                    canonical_metadata_member,
                    metadata_probe_warnings,
                    budget,
                    report_failure=False,
                )
                if metadata_root is not None:
                    metadata_roots[canonical_metadata_member] = metadata_root
                else:
                    metadata_failures[canonical_metadata_member] = metadata_fallback

            preliminary_rich_data = bool(
                rich_package_candidate
                or category_members
                or rich_workbook_relationships
                or content_type_probe_issues
            )
            probe_metadata_inspections: dict[str, _RichDataMetadataInspection] = {}
            for member, metadata_root in metadata_roots.items():
                inspection = _rich_data_metadata_inspection(
                    metadata_root,
                    metadata_probe_issues,
                )
                probe_metadata_inspections[member] = inspection
                preliminary_rich_data = preliminary_rich_data or inspection.present

            if not preliminary_rich_data:
                return _RichDataMetadata(RichDataSnapshot(), ())

            warnings.update(content_type_warnings)
            warnings.update(relationship_probe_warnings)
            warnings.update(metadata_probe_warnings)
            issues.extend(content_type_probe_issues)
            issues.extend(relationship_probe_issues)
            issues.extend(metadata_probe_issues)
            if content_type_fallback is not None:
                _rich_data_issue(
                    issues,
                    "unreadable-rich-data-content-types",
                    content_type_fallback,
                )

            for category, relationship in rich_workbook_relationships:
                relationship_entries.extend(
                    _rich_data_relationship_entries(
                        (relationship,),
                        context=f"workbook-rich-data-relationship:{category}",
                    )
                )
                target = relationship.target
                if target is None:
                    continue
                target_category = _rich_data_category_for_member(target)
                if target_category is not None and target_category != category:
                    _rich_data_issue(
                        issues,
                        "mismatched-rich-data-workbook-relationship-target",
                        (category, target_category, target),
                    )
                if target not in members:
                    _rich_data_issue(
                        issues,
                        "missing-rich-data-workbook-relationship-target",
                        (category, target),
                    )

            metadata_members: set[str] = set(metadata_roots)
            for relationship in metadata_workbook_relationships:
                relationship_entries.extend(
                    _rich_data_relationship_entries(
                        (relationship,),
                        context="workbook-rich-data-metadata-relationship",
                    )
                )
                if relationship.target_mode.casefold() != "internal":
                    _rich_data_issue(
                        issues,
                        "external-rich-data-metadata-relationship",
                        _rich_data_relationship_semantic(relationship),
                    )
                    continue
                if relationship.target is None:
                    _rich_data_issue(
                        issues,
                        "unsafe-rich-data-metadata-relationship-target",
                        _rich_data_relationship_semantic(relationship),
                    )
                    continue
                metadata_members.add(relationship.target)
                if relationship.target not in members:
                    _rich_data_issue(
                        issues,
                        "missing-rich-data-metadata-relationship-target",
                        relationship.target,
                    )

            if not metadata_workbook_relationships:
                _rich_data_issue(
                    issues,
                    "missing-rich-data-metadata-workbook-relationship",
                    None,
                )

            metadata_inspections: dict[str, _RichDataMetadataInspection] = {}
            for metadata_member in sorted(metadata_members):
                if metadata_member not in members:
                    continue
                metadata_root = metadata_roots.get(metadata_member)
                if metadata_root is None:
                    if metadata_member in metadata_failures:
                        _rich_data_issue(
                            issues,
                            "unreadable-rich-data-metadata-member",
                            (
                                metadata_member,
                                metadata_failures[metadata_member],
                            ),
                        )
                        continue
                    metadata_root, metadata_fallback = _rich_data_bounded_root(
                        archive,
                        metadata_member,
                        warnings,
                        budget,
                    )
                    if metadata_root is None:
                        _rich_data_issue(
                            issues,
                            "unreadable-rich-data-metadata-member",
                            (metadata_member, metadata_fallback),
                        )
                        continue
                    metadata_roots[metadata_member] = metadata_root
                inspection = probe_metadata_inspections.get(metadata_member)
                if inspection is None:
                    inspection = _rich_data_metadata_inspection(metadata_root, issues)
                if not inspection.present:
                    continue
                metadata_inspections[metadata_member] = inspection
                metadata_entries.extend(inspection.signature_entries)

            actual_category_members: dict[str, set[str]] = {
                category: {
                    member
                    for member in declared_members
                    if member in members
                }
                for category, declared_members in category_members.items()
            }
            members_to_categories: dict[str, set[str]] = defaultdict(set)
            for category, declared_members in actual_category_members.items():
                for member in declared_members:
                    members_to_categories[member].add(category)
            for member, categories in members_to_categories.items():
                if len(categories) > 1:
                    _rich_data_issue(
                        issues,
                        "ambiguous-rich-data-part-category",
                        (member, tuple(sorted(categories))),
                    )

            rich_value_count = 0
            rich_value_structure_count = 0
            linked_entity_structure_count = 0
            rich_value_array_count = 0
            supporting_property_bag_count = 0
            web_image_count = 0
            web_image_part_roots: list[tuple[str, ElementTree.Element]] = []
            rich_value_relationship_part_roots: list[
                tuple[str, ElementTree.Element]
            ] = []

            for category in sorted(actual_category_members):
                declared_members = actual_category_members[category]
                if len(declared_members) > 1:
                    _rich_data_issue(
                        issues,
                        "duplicate-rich-data-category-part",
                        (category, tuple(sorted(declared_members))),
                    )
                expected_content_types = {
                    content_type
                    for content_type, content_category in _RICH_DATA_PART_CONTENT_TYPES.items()
                    if content_category == category
                }
                expected_root = _RICH_DATA_PART_ROOTS.get(category)
                if expected_root is None:
                    _rich_data_issue(
                        issues,
                        "unrecognized-rich-data-part-category",
                        category,
                    )
                    continue
                for member in sorted(declared_members):
                    if member_counts[member] != 1:
                        _rich_data_issue(
                            issues,
                            "duplicate-rich-data-archive-member",
                            (member, member_counts[member]),
                        )
                    declarations = content_types.get(member, ())
                    if not declarations:
                        _rich_data_issue(
                            issues,
                            "unlisted-rich-data-content-type",
                            (category, member),
                        )
                    elif any(
                        declaration not in expected_content_types
                        for declaration in declarations
                    ):
                        _rich_data_issue(
                            issues,
                            "mismatched-rich-data-content-type",
                            (category, member, declarations),
                        )
                    root, fallback_signature = _rich_data_bounded_root(
                        archive,
                        member,
                        warnings,
                        budget,
                    )
                    if root is None:
                        _rich_data_issue(
                            issues,
                            "unreadable-rich-data-part",
                            (category, member, fallback_signature),
                        )
                        continue
                    if (
                        _xml_namespace(root.tag) != expected_root[0]
                        or _xml_local_name(root.tag) != expected_root[1]
                    ):
                        _rich_data_issue(
                            issues,
                            "unexpected-rich-data-part-root",
                            (category, member, _xml_display_name(root.tag)),
                        )
                    part_fragment = _xml_fragment(root).sort_key()
                    if category in _RICH_DATA_DEFINITION_CATEGORIES:
                        definition_entries.append(
                            (
                                "rich-data-definition",
                                repr((category, member, part_fragment)),
                            )
                        )
                    elif category in _RICH_DATA_VALUE_CATEGORIES:
                        value_entries.append(
                            (
                                "rich-data-values",
                                repr((category, member, part_fragment)),
                            )
                        )

                    if category == "rich-value-data":
                        value_tag = f"{{{_RICH_DATA_NS}}}rv"
                        values = [child for child in root if child.tag == value_tag]
                        _rich_data_declared_count(
                            root,
                            len(values),
                            issues,
                            context="rich-value-data",
                        )
                        if len(values) != len(root):
                            _rich_data_issue(
                                issues,
                                "unexpected-rich-value-data-child",
                                (member, len(root) - len(values)),
                            )
                        rich_value_count += len(values)
                    elif category == "rich-value-structure":
                        structure_tag = f"{{{_RICH_DATA_NS}}}s"
                        structures = [
                            child for child in root if child.tag == structure_tag
                        ]
                        _rich_data_declared_count(
                            root,
                            len(structures),
                            issues,
                            context="rich-value-structure",
                        )
                        if len(structures) != len(root):
                            _rich_data_issue(
                                issues,
                                "unexpected-rich-value-structure-child",
                                (member, len(root) - len(structures)),
                            )
                        rich_value_structure_count += len(structures)
                        linked_entity_structure_count += sum(
                            structure.get("t", "")
                            .casefold()
                            .startswith("_linkedentity")
                            for structure in structures
                        )
                    elif category == "rich-value-array":
                        array_tag = f"{{{_RICH_DATA_2_NS}}}a"
                        arrays = [child for child in root if child.tag == array_tag]
                        _rich_data_declared_count(
                            root,
                            len(arrays),
                            issues,
                            context="rich-value-array",
                        )
                        if len(arrays) != len(root):
                            _rich_data_issue(
                                issues,
                                "unexpected-rich-value-array-child",
                                (member, len(root) - len(arrays)),
                            )
                        rich_value_array_count += len(arrays)
                    elif category == "supporting-property-bag":
                        bag_tag = f"{{{_RICH_DATA_2_NS}}}a"
                        supporting_property_bag_count += len(
                            root.findall(f".//{bag_tag}")
                        )
                    elif category == "rich-value-web-image":
                        image_tag = f"{{{_RICH_DATA_WEB_IMAGE_NS}}}webImageSrd"
                        images = [child for child in root if child.tag == image_tag]
                        if len(images) != len(root):
                            _rich_data_issue(
                                issues,
                                "unexpected-rich-value-web-image-child",
                                (member, len(root) - len(images)),
                            )
                        web_image_count += len(images)
                        web_image_part_roots.append((member, root))
                    elif category == "rich-value-relationships":
                        rich_value_relationship_part_roots.append((member, root))

            core_parts_present = bool(
                actual_category_members.get("rich-value-data")
                or actual_category_members.get("rich-value-structure")
            )
            related_parts_present = bool(actual_category_members)
            if related_parts_present and not core_parts_present:
                _rich_data_issue(issues, "missing-rich-data-core-parts", None)
            if core_parts_present:
                for category in ("rich-value-data", "rich-value-structure"):
                    if not actual_category_members.get(category):
                        _rich_data_issue(
                            issues,
                            "missing-required-rich-data-core-part",
                            category,
                        )
            if related_parts_present and not metadata_inspections:
                _rich_data_issue(issues, "missing-rich-data-metadata", None)
            if metadata_inspections and not core_parts_present:
                _rich_data_issue(
                    issues,
                    "rich-data-metadata-without-core-parts",
                    None,
                )

            for metadata_member, inspection in metadata_inspections.items():
                for rich_value_index in inspection.rich_value_indexes:
                    if rich_value_index >= rich_value_count:
                        _rich_data_issue(
                            issues,
                            "out-of-range-rich-data-value-metadata-index",
                            (metadata_member, rich_value_index, rich_value_count),
                        )

            if len(metadata_inspections) > 1:
                _rich_data_issue(
                    issues,
                    "multiple-rich-data-metadata-members",
                    tuple(sorted(metadata_inspections)),
                )

            rich_value_bound_cell_count = 0
            value_metadata_indexes = frozenset().union(
                *(
                    inspection.value_metadata_indexes
                    for inspection in metadata_inspections.values()
                )
            )
            if value_metadata_indexes:
                worksheet_tag = f"{{{_SPREADSHEETML_NS}}}worksheet"
                cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
                worksheet_members = sorted(
                    member
                    for member in members
                    if member.casefold().startswith("xl/worksheets/")
                    and member.casefold().endswith(".xml")
                )
                for worksheet_member in worksheet_members:
                    (
                        worksheet_root_tag,
                        worksheet_bindings,
                        worksheet_fallback,
                    ) = _rich_data_worksheet_value_metadata_bindings(
                        archive,
                        worksheet_member,
                        warnings,
                        budget,
                        issues,
                        value_metadata_indexes,
                        worksheet_tag=worksheet_tag,
                        cell_tag=cell_tag,
                    )
                    if worksheet_root_tag is None:
                        _rich_data_issue(
                            issues,
                            "unreadable-rich-data-worksheet",
                            (worksheet_member, worksheet_fallback),
                        )
                        continue
                    if worksheet_root_tag != worksheet_tag:
                        _rich_data_issue(
                            issues,
                            "unexpected-rich-data-worksheet-root",
                            (worksheet_member, _xml_display_name(worksheet_root_tag)),
                        )
                        continue
                    rich_value_bound_cell_count += len(worksheet_bindings)
                    metadata_entries.extend(
                        (
                            "rich-data-cell-binding",
                            repr(
                                (
                                    worksheet_member,
                                    coordinate,
                                    value_metadata_index,
                                )
                            ),
                        )
                        for coordinate, value_metadata_index in worksheet_bindings
                    )

            web_image_relationship_count = 0
            external_web_image_relationship_count = 0
            rich_value_relationship_reference_count = 0
            external_rich_value_relationship_count = 0
            for category, member, root in (
                [
                    ("rich-value-web-image", member, root)
                    for member, root in web_image_part_roots
                ]
                + [
                    ("rich-value-relationships", member, root)
                    for member, root in rich_value_relationship_part_roots
                ]
            ):
                relationships = _rich_data_part_relationships(
                    archive,
                    member,
                    members,
                    warnings,
                    budget,
                    issues,
                    required=False,
                    context=category,
                )
                relationships_by_id = _rich_data_relationship_lookup(
                    relationships,
                    issues,
                    context=category,
                )
                fragment, references = _rich_data_relationship_aware_fragment(
                    root,
                    relationships_by_id,
                    issues,
                    context=category,
                )
                relationship_entries.append(
                    (
                        f"rich-data-{category}-references",
                        repr((member, fragment)),
                    )
                )
                relationship_entries.extend(
                    _rich_data_relationship_entries(
                        relationships,
                        context=f"rich-data-{category}-relationships",
                    )
                )
                if references and _relationship_part_path(member) not in members:
                    _rich_data_issue(
                        issues,
                        f"missing-{category}-relationship-part",
                        member,
                    )
                used_relationships = [
                    relationships_by_id[reference]
                    for reference in references
                    if reference in relationships_by_id
                ]
                external_used_count = sum(
                    relationship.target_mode.casefold() == "external"
                    for relationship in used_relationships
                )
                if category == "rich-value-web-image":
                    web_image_relationship_count += len(references)
                    external_web_image_relationship_count += external_used_count
                else:
                    rich_value_relationship_reference_count += len(references)
                    external_rich_value_relationship_count += external_used_count

            issue_entries = [
                ("rich-data-issue", repr(issue))
                for issue in sorted(issues)
            ]
            definition_entries.extend(issue_entries)
            if issues:
                warnings.add(
                    "FormulaFence found malformed, unsupported, or incomplete "
                    "rich-data metadata; affected rich-data controls have a coverage gap."
                )
            snapshot = RichDataSnapshot(
                rich_value_data_part_count=len(
                    actual_category_members.get("rich-value-data", set())
                ),
                rich_value_structure_part_count=len(
                    actual_category_members.get("rich-value-structure", set())
                ),
                rich_value_type_part_count=len(
                    actual_category_members.get("rich-value-types", set())
                ),
                rich_value_array_part_count=len(
                    actual_category_members.get("rich-value-array", set())
                ),
                supporting_property_bag_part_count=len(
                    actual_category_members.get("supporting-property-bag", set())
                ),
                supporting_property_bag_structure_part_count=len(
                    actual_category_members.get(
                        "supporting-property-bag-structure",
                        set(),
                    )
                ),
                rich_style_part_count=len(
                    actual_category_members.get("rich-styles", set())
                ),
                rich_value_web_image_part_count=len(
                    actual_category_members.get("rich-value-web-image", set())
                ),
                rich_value_relationship_part_count=len(
                    actual_category_members.get(
                        "rich-value-relationships",
                        set(),
                    )
                ),
                rich_value_count=rich_value_count,
                rich_value_structure_count=rich_value_structure_count,
                linked_entity_structure_count=linked_entity_structure_count,
                rich_value_array_count=rich_value_array_count,
                supporting_property_bag_count=supporting_property_bag_count,
                rich_value_metadata_binding_count=sum(
                    inspection.binding_count
                    for inspection in metadata_inspections.values()
                ),
                rich_value_bound_cell_count=rich_value_bound_cell_count,
                web_image_count=web_image_count,
                web_image_relationship_count=web_image_relationship_count,
                external_web_image_relationship_count=(
                    external_web_image_relationship_count
                ),
                rich_value_relationship_reference_count=(
                    rich_value_relationship_reference_count
                ),
                external_rich_value_relationship_count=(
                    external_rich_value_relationship_count
                ),
                unrecognized_rich_data_count=len(issues),
                definition_signature=_private_external_data_signature(
                    tuple(sorted(definition_entries))
                ),
                value_signature=_private_external_data_signature(
                    tuple(sorted(value_entries))
                ),
                metadata_binding_signature=_private_external_data_signature(
                    tuple(sorted(metadata_entries))
                ),
                relationship_signature=_private_external_data_signature(
                    tuple(sorted(relationship_entries))
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _RichDataMetadata(
            RichDataSnapshot(
                unrecognized_rich_data_count=1,
                definition_signature=_private_external_data_signature(
                    (("rich-data-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect rich-data OOXML "
                f"({type(error).__name__}); affected rich-data controls were not compared.",
            ),
        )
    return _RichDataMetadata(snapshot, tuple(sorted(warnings)))


@dataclass
class _CustomDataStoreBudget:
    """Bound raw reads across custom workbook data-store package parts."""

    remaining_parts: int = _CUSTOM_DATA_STORE_TOTAL_PARTS
    remaining_bytes: int = _CUSTOM_DATA_STORE_TOTAL_BYTES
    remaining_xml_elements: int = _CUSTOM_DATA_STORE_TOTAL_XML_MAX_ELEMENT_COUNT


def _custom_data_store_issue(
    issues: list[tuple[str, str]],
    context: str,
    detail: object,
) -> None:
    """Record private custom-store coverage evidence without exposing content."""
    issues.append((context, repr(detail)))


def _custom_data_store_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _CustomDataStoreBudget,
    *,
    report_failure: bool,
) -> str | None:
    """Stream custom-state XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _CUSTOM_DATA_STORE_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    if report_failure:
        warnings.add(
            "FormulaFence did not fully read a custom data-store XML part whose XML "
            "structure exceeds the safety budget; affected persisted state has a "
            "coverage gap."
        )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _custom_data_store_bounded_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _CustomDataStoreBudget,
    *,
    report_failure: bool = True,
    structural_xml: bool = False,
) -> tuple[bytes | None, str | None]:
    """Read one custom workbook data-store part within fixed scan budgets."""
    if budget.remaining_parts <= 0:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded custom data-store part count "
                "budget; affected persisted state was not compared."
            )
        return None, _private_external_data_signature(
            (("custom-data-store-part-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        if report_failure:
            warnings.add(
                "FormulaFence could not locate a custom data-store package part; "
                "affected persisted state was not compared."
            )
        return None, _private_external_data_signature(
            (("missing-custom-data-store-member", member),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _CUSTOM_DATA_STORE_MAX_PART_BYTES:
        if report_failure:
            warnings.add(
                "FormulaFence did not fully read an oversized custom data-store "
                "part; affected persisted state has a coverage gap."
            )
        return None, _private_external_data_signature(
            (("oversized-custom-data-store-part", metadata),)
        )
    if info.file_size > budget.remaining_bytes:
        if report_failure:
            warnings.add(
                "FormulaFence reached its bounded custom data-store read budget; "
                "affected persisted state was not compared."
            )
        return None, _private_external_data_signature(
            (("custom-data-store-read-budget-exhausted", metadata),)
        )
    if structural_xml:
        structure_fallback_signature = (
            _custom_data_store_xml_structure_budget_fallback_signature(
                archive,
                member,
                info,
                warnings,
                budget,
                report_failure=report_failure,
            )
        )
        if structure_fallback_signature is not None:
            return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, KeyError, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not read a custom data-store package part "
                f"({type(error).__name__}); affected persisted state was not compared."
            )
        return None, _private_external_data_signature(
            (("unreadable-custom-data-store-member", metadata),)
        )


def _custom_data_store_bounded_root(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _CustomDataStoreBudget,
    *,
    report_failure: bool = True,
) -> tuple[ElementTree.Element | None, str | None]:
    """Return one bounded custom-store XML root or a private failure signature."""
    payload, fallback_signature = _custom_data_store_bounded_payload(
        archive,
        member,
        warnings,
        budget,
        report_failure=report_failure,
        structural_xml=True,
    )
    if payload is None:
        return None, fallback_signature
    try:
        return _xml_root_from_payload(payload), None
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        if report_failure:
            warnings.add(
                "FormulaFence could not parse a custom data-store XML package "
                f"part ({type(error).__name__}); affected persisted state was not compared."
            )
        return None, _private_payload_signature(payload)


def _custom_data_store_part_relationships(
    archive: ZipFile,
    source_member: str,
    members: set[str],
    warnings: set[str],
    budget: _CustomDataStoreBudget,
    issues: list[tuple[str, str]],
    *,
    required: bool,
    context: str,
) -> tuple[_PackageRelationship, ...]:
    """Read a custom-store relationship part without following target endpoints."""
    relationship_member = _relationship_part_path(source_member)
    if relationship_member not in members:
        if required:
            _custom_data_store_issue(
                issues,
                f"missing-{context}-relationship-part",
                relationship_member,
            )
        return ()
    root, fallback_signature = _custom_data_store_bounded_root(
        archive,
        relationship_member,
        warnings,
        budget,
    )
    if root is None:
        _custom_data_store_issue(
            issues,
            f"unreadable-{context}-relationship-part",
            (relationship_member, fallback_signature),
        )
        return ()
    if (
        _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
        or _xml_local_name(root.tag) != "Relationships"
    ):
        _custom_data_store_issue(
            issues,
            f"unexpected-{context}-relationship-root",
            _xml_display_name(root.tag),
        )
        return ()
    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_PackageRelationship] = []
    identifiers: list[str] = []
    for child in root:
        if child.tag != relationship_tag:
            _custom_data_store_issue(
                issues,
                f"unexpected-{context}-relationship-child",
                _xml_fragment(child).sort_key(),
            )
            continue
        relationship_id = child.get("Id")
        if not relationship_id:
            _custom_data_store_issue(
                issues,
                f"missing-{context}-relationship-id",
                _xml_fragment(child).sort_key(),
            )
        else:
            identifiers.append(relationship_id)
        relationship_type = child.get("Type")
        raw_target = child.get("Target")
        target_mode = child.get("TargetMode", "Internal")
        if relationship_type is None or raw_target is None:
            _custom_data_store_issue(
                issues,
                f"malformed-{context}-relationship",
                _xml_fragment(child).sort_key(),
            )
        relationships.append(
            _PackageRelationship(
                relationship_id=relationship_id,
                relationship_type=relationship_type or "",
                target=(
                    _normalise_part_target(source_member, raw_target)
                    if raw_target is not None
                    and target_mode.casefold() == "internal"
                    else None
                ),
                target_mode=target_mode,
                raw_target=raw_target,
            )
        )
    if len(identifiers) != len(set(identifiers)):
        _custom_data_store_issue(
            issues,
            f"duplicate-{context}-relationship-id",
            tuple(sorted(identifiers)),
        )
    return tuple(relationships)


def _custom_data_store_relationship_semantic(
    relationship: _PackageRelationship,
    *,
    target_kind: str | None = None,
) -> tuple[str, str, str | None]:
    """Return private relationship semantics while ignoring writer-selected IDs."""
    target = target_kind
    if target is None:
        target = (
            relationship.target
            if relationship.target is not None
            else relationship.raw_target
        )
    return (
        relationship.relationship_type.casefold(),
        relationship.target_mode.casefold(),
        target,
    )


def _custom_data_store_xml_fragment(
    element: ElementTree.Element,
    *,
    omit_root_attribute_names: frozenset[str] = frozenset(),
) -> tuple[object, ...]:
    """Canonicalise private XML while optionally ignoring writer-assigned IDs."""

    def fragment(
        current: ElementTree.Element,
        *,
        is_root: bool,
    ) -> tuple[object, ...]:
        attributes = tuple(
            sorted(
                (
                    _xml_display_name(attribute),
                    value,
                )
                for attribute, value in current.attrib.items()
                if not (
                    is_root
                    and _xml_local_name(attribute).casefold()
                    in omit_root_attribute_names
                )
            )
        )
        children = tuple(fragment(child, is_root=False) for child in current)
        text = current.text
        if children and text is not None and not text.strip():
            text = None
        return (
            _xml_display_name(current.tag),
            attributes,
            text,
            children,
        )

    return fragment(element, is_root=True)


def _custom_xml_property_member_for_item(member: str) -> str | None:
    """Return the conventional item-properties part for one custom XML item."""
    match = re.fullmatch(r"customXml/item(\d*)\.xml", member, re.IGNORECASE)
    if match is None:
        return None
    return f"customXml/itemProps{match.group(1)}.xml"


def _custom_data_store_document_property_entries(
    root: ElementTree.Element,
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> tuple[tuple[str, ...], int, int]:
    """Fingerprint custom properties without exporting names or values."""
    if (
        _xml_namespace(root.tag) != _CUSTOM_DOCUMENT_PROPERTIES_NS
        or _xml_local_name(root.tag) != "Properties"
    ):
        _custom_data_store_issue(
            issues,
            f"unexpected-{context}-root",
            _xml_display_name(root.tag),
        )
    properties = [
        child
        for child in root
        if _xml_local_name(child.tag) == "property"
    ]
    if len(properties) != len(root):
        _custom_data_store_issue(
            issues,
            f"unexpected-{context}-child",
            len(root) - len(properties),
        )
    entries = tuple(
        sorted(
            repr(
                _custom_data_store_xml_fragment(
                    property_element,
                    omit_root_attribute_names=frozenset({"pid"}),
                )
            )
            for property_element in properties
        )
    )
    linked_count = sum(
        1
        for property_element in properties
        for child in property_element
        if _xml_local_name(child.tag) == "linkTarget"
    )
    return entries, len(properties), linked_count


def _custom_data_store_metadata(path: Path) -> _CustomDataStoreMetadata:
    """Inspect persisted add-in state without loading it into the workbook model.

    Generic custom XML, binary custom data, and custom document properties can
    carry workbook-specific state for add-ins while being absent from ordinary
    cells and openpyxl's public workbook model. This scanner compares that
    state only through bounded private fingerprints. It does not execute an
    add-in, resolve a property, follow a relationship, fetch a target, or emit
    XML, property names or values, storage IDs, binary payloads, URLs, or
    relationship IDs.
    """
    warnings: set[str] = set()
    issues: list[tuple[str, str]] = []
    custom_xml_entries: list[tuple[str, str]] = []
    custom_data_entries: list[tuple[str, str]] = []
    document_property_entries: list[tuple[str, str]] = []
    relationship_entries: list[tuple[str, str]] = []
    try:
        with ZipFile(path) as archive:
            raw_members = archive.namelist()
            members = set(raw_members)
            member_counts = Counter(raw_members)
            budget = _CustomDataStoreBudget()
            custom_xml_item_members = sorted(
                member
                for member in members
                if _CUSTOM_XML_ITEM_PATTERN.fullmatch(member)
            )
            custom_xml_property_members = {
                member
                for member in members
                if _CUSTOM_XML_ITEM_PROPERTIES_PATTERN.fullmatch(member)
            }
            custom_xml_relationship_members = {
                member
                for member in members
                if _CUSTOM_XML_RELATIONSHIP_PATTERN.fullmatch(member)
            }
            custom_data_members = {
                member
                for member in members
                if member.casefold().startswith("xl/customdata/")
                and "/_rels/" not in member.casefold()
                and not member.endswith("/")
            }

            root_probe_warnings: set[str] = set()
            root_probe_issues: list[tuple[str, str]] = []
            root_relationships = _custom_data_store_part_relationships(
                archive,
                "",
                members,
                root_probe_warnings,
                budget,
                root_probe_issues,
                required=False,
                context="package-root",
            )
            workbook_probe_warnings: set[str] = set()
            workbook_probe_issues: list[tuple[str, str]] = []
            workbook_relationships = _custom_data_store_part_relationships(
                archive,
                "xl/workbook.xml",
                members,
                workbook_probe_warnings,
                budget,
                workbook_probe_issues,
                required=False,
                context="workbook",
            )
            root_custom_xml_relationships = tuple(
                relationship
                for relationship in root_relationships
                if relationship.relationship_type.casefold().endswith("/customxml")
            )
            root_document_property_relationships = tuple(
                relationship
                for relationship in root_relationships
                if relationship.relationship_type.casefold().endswith(
                    "/custom-properties"
                )
            )
            workbook_custom_data_property_relationships = tuple(
                relationship
                for relationship in workbook_relationships
                if relationship.relationship_type.casefold().endswith(
                    "/customdataprops"
                )
            )
            candidate = bool(
                custom_xml_item_members
                or custom_xml_property_members
                or custom_xml_relationship_members
                or custom_data_members
                or _CUSTOM_DOCUMENT_PROPERTIES_MEMBER in members
                or root_custom_xml_relationships
                or root_document_property_relationships
                or workbook_custom_data_property_relationships
            )
            if not candidate:
                return _CustomDataStoreMetadata(CustomDataStoreSnapshot(), ())

            warnings.update(root_probe_warnings)
            warnings.update(workbook_probe_warnings)
            issues.extend(root_probe_issues)
            issues.extend(workbook_probe_issues)
            relevant_members = (
                set(custom_xml_item_members)
                | custom_xml_property_members
                | custom_xml_relationship_members
                | custom_data_members
            )
            for relationship_member in (
                _relationship_part_path(""),
                _relationship_part_path("xl/workbook.xml"),
            ):
                if relationship_member in members:
                    relevant_members.add(relationship_member)
            if _CUSTOM_DOCUMENT_PROPERTIES_MEMBER in members:
                relevant_members.add(_CUSTOM_DOCUMENT_PROPERTIES_MEMBER)
            for member in sorted(relevant_members):
                if member_counts[member] > 1:
                    _custom_data_store_issue(
                        issues,
                        "duplicate-custom-data-store-archive-member",
                        (member, member_counts[member]),
                    )

            power_query_item_members: set[str] = set()
            generic_custom_xml_item_members: set[str] = set()
            item_property_targets: dict[str, set[str]] = defaultdict(set)
            inspected_custom_xml_relationship_members: set[str] = set()
            custom_xml_relationship_count = 0
            external_custom_xml_relationship_count = 0
            for member in custom_xml_item_members:
                root, fallback_signature = _custom_data_store_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if root is None:
                    _custom_data_store_issue(
                        issues,
                        "unreadable-custom-xml-data-part",
                        (member, fallback_signature),
                    )
                    custom_xml_entries.append(
                        (
                            "unreadable-custom-xml-data-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                if _xml_namespace(root.tag) == _DATA_MASHUP_NS:
                    power_query_item_members.add(member)
                else:
                    generic_custom_xml_item_members.add(member)
                    custom_xml_entries.append(
                        (
                            "custom-xml-data",
                            repr(_xml_fragment(root).sort_key()),
                        )
                    )

                relationships = _custom_data_store_part_relationships(
                    archive,
                    member,
                    members,
                    warnings,
                    budget,
                    issues,
                    required=False,
                    context="custom-xml-item",
                )
                relationship_member = _relationship_part_path(member)
                if relationship_member in members:
                    inspected_custom_xml_relationship_members.add(relationship_member)
                property_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type.casefold().endswith(
                        "/customxmlprops"
                    )
                ]
                for relationship in property_relationships:
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        if member in generic_custom_xml_item_members:
                            _custom_data_store_issue(
                                issues,
                                "unsafe-custom-xml-properties-relationship",
                                _custom_data_store_relationship_semantic(
                                    relationship
                                ),
                            )
                        continue
                    item_property_targets[member].add(relationship.target)
                    if (
                        member in generic_custom_xml_item_members
                        and relationship.target not in members
                    ):
                        _custom_data_store_issue(
                            issues,
                            "missing-custom-xml-properties-part",
                            relationship.target,
                        )
                if member not in generic_custom_xml_item_members:
                    continue
                custom_xml_relationship_count += len(relationships)
                external_custom_xml_relationship_count += sum(
                    relationship.target_mode.casefold() == "external"
                    for relationship in relationships
                )
                relationship_entries.append(
                    (
                        "custom-xml-item-relationships",
                        repr(
                            tuple(
                                sorted(
                                    _custom_data_store_relationship_semantic(
                                        relationship,
                                        target_kind=(
                                            "custom-xml-properties"
                                            if relationship
                                            in property_relationships
                                            else None
                                        ),
                                    )
                                    for relationship in relationships
                                )
                            )
                        ),
                    )
                )
                for relationship in relationships:
                    if relationship not in property_relationships:
                        _custom_data_store_issue(
                            issues,
                            "unsupported-custom-xml-item-relationship",
                            _custom_data_store_relationship_semantic(relationship),
                        )

            power_query_property_members = {
                target
                for member, targets in item_property_targets.items()
                if member in power_query_item_members
                for target in targets
            }
            power_query_property_members.update(
                property_member
                for member in power_query_item_members
                if (property_member := _custom_xml_property_member_for_item(member))
                is not None
            )
            generic_property_targets = {
                target
                for member, targets in item_property_targets.items()
                if member in generic_custom_xml_item_members
                for target in targets
            }
            generic_custom_xml_property_members = (
                custom_xml_property_members | generic_property_targets
            ) - power_query_property_members
            actual_generic_custom_xml_property_members = {
                member
                for member in generic_custom_xml_property_members
                if member in members
            }
            custom_xml_schema_reference_count = 0
            for member in sorted(actual_generic_custom_xml_property_members):
                root, fallback_signature = _custom_data_store_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if root is None:
                    _custom_data_store_issue(
                        issues,
                        "unreadable-custom-xml-properties-part",
                        (member, fallback_signature),
                    )
                    custom_xml_entries.append(
                        (
                            "unreadable-custom-xml-properties-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                if _xml_local_name(root.tag) != "datastoreItem":
                    _custom_data_store_issue(
                        issues,
                        "unexpected-custom-xml-properties-root",
                        _xml_display_name(root.tag),
                    )
                custom_xml_schema_reference_count += sum(
                    _xml_local_name(element.tag) == "schemaRef"
                    for element in root.iter()
                )
                custom_xml_entries.append(
                    (
                        "custom-xml-properties",
                        repr(_custom_data_store_xml_fragment(root)),
                    )
                )
            for member in sorted(actual_generic_custom_xml_property_members):
                if member not in generic_property_targets:
                    _custom_data_store_issue(
                        issues,
                        "unbound-custom-xml-properties-part",
                        member,
                    )
            for member in sorted(custom_xml_relationship_members):
                if member not in inspected_custom_xml_relationship_members:
                    _custom_data_store_issue(
                        issues,
                        "unbound-custom-xml-relationship-part",
                        member,
                    )

            for relationship in root_custom_xml_relationships:
                if (
                    relationship.target_mode.casefold() == "internal"
                    and relationship.target in power_query_item_members
                ):
                    continue
                custom_xml_relationship_count += 1
                external_custom_xml_relationship_count += (
                    relationship.target_mode.casefold() == "external"
                )
                target_kind = (
                    "custom-xml-data"
                    if relationship.target in generic_custom_xml_item_members
                    else None
                )
                relationship_entries.append(
                    (
                        "package-root-custom-xml-relationship",
                        repr(
                            _custom_data_store_relationship_semantic(
                                relationship,
                                target_kind=target_kind,
                            )
                        ),
                    )
                )
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                    or relationship.target not in generic_custom_xml_item_members
                ):
                    _custom_data_store_issue(
                        issues,
                        "unsafe-or-unrecognized-package-root-custom-xml-relationship",
                        _custom_data_store_relationship_semantic(relationship),
                    )

            custom_data_property_targets: set[str] = set()
            for relationship in workbook_custom_data_property_relationships:
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                ):
                    _custom_data_store_issue(
                        issues,
                        "unsafe-custom-data-properties-workbook-relationship",
                        _custom_data_store_relationship_semantic(relationship),
                    )
                    relationship_entries.append(
                        (
                            "workbook-custom-data-properties-relationship",
                            repr(
                                _custom_data_store_relationship_semantic(
                                    relationship
                                )
                            ),
                        )
                    )
                    continue
                custom_data_property_targets.add(relationship.target)
                relationship_entries.append(
                    (
                        "workbook-custom-data-properties-relationship",
                        repr(
                            _custom_data_store_relationship_semantic(
                                relationship,
                                target_kind="custom-data-properties",
                            )
                        ),
                    )
                )
                if relationship.target not in members:
                    _custom_data_store_issue(
                        issues,
                        "missing-custom-data-properties-part",
                        relationship.target,
                    )
            discovered_custom_data_property_members = {
                member
                for member in custom_data_members
                if member.casefold().endswith(".xml")
            }
            custom_data_property_members = (
                custom_data_property_targets | discovered_custom_data_property_members
            )
            actual_custom_data_property_members = {
                member
                for member in custom_data_property_members
                if member in members
            }
            for member in sorted(actual_custom_data_property_members):
                if member not in custom_data_property_targets:
                    _custom_data_store_issue(
                        issues,
                        "unbound-custom-data-properties-part",
                        member,
                    )

            custom_data_payload_targets: set[str] = set()
            inspected_custom_data_relationship_members: set[str] = set()
            for member in sorted(actual_custom_data_property_members):
                root, fallback_signature = _custom_data_store_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if root is None:
                    _custom_data_store_issue(
                        issues,
                        "unreadable-custom-data-properties-part",
                        (member, fallback_signature),
                    )
                    custom_data_entries.append(
                        (
                            "unreadable-custom-data-properties-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                if (
                    _xml_namespace(root.tag) != _CUSTOM_DATA_PROPERTIES_NS
                    or _xml_local_name(root.tag) != "datastoreItem"
                ):
                    _custom_data_store_issue(
                        issues,
                        "unexpected-custom-data-properties-root",
                        _xml_display_name(root.tag),
                    )
                custom_data_entries.append(
                    (
                        "custom-data-properties",
                        repr(_custom_data_store_xml_fragment(root)),
                    )
                )
                relationships = _custom_data_store_part_relationships(
                    archive,
                    member,
                    members,
                    warnings,
                    budget,
                    issues,
                    required=True,
                    context="custom-data-properties",
                )
                relationship_member = _relationship_part_path(member)
                if relationship_member in members:
                    inspected_custom_data_relationship_members.add(relationship_member)
                data_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type.casefold().endswith(
                        "/customdata"
                    )
                ]
                if len(data_relationships) > 1:
                    _custom_data_store_issue(
                        issues,
                        "multiple-custom-data-payload-relationships",
                        len(data_relationships),
                    )
                for relationship in data_relationships:
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.target is None
                    ):
                        _custom_data_store_issue(
                            issues,
                            "unsafe-custom-data-payload-relationship",
                            _custom_data_store_relationship_semantic(relationship),
                        )
                        continue
                    custom_data_payload_targets.add(relationship.target)
                    if relationship.target not in members:
                        _custom_data_store_issue(
                            issues,
                            "missing-custom-data-payload-part",
                            relationship.target,
                        )
                relationship_entries.append(
                    (
                        "custom-data-properties-relationships",
                        repr(
                            tuple(
                                sorted(
                                    _custom_data_store_relationship_semantic(
                                        relationship,
                                        target_kind=(
                                            "custom-data-payload"
                                            if relationship
                                            in data_relationships
                                            else None
                                        ),
                                    )
                                    for relationship in relationships
                                )
                            )
                        ),
                    )
                )
                for relationship in relationships:
                    if relationship not in data_relationships:
                        _custom_data_store_issue(
                            issues,
                            "unsupported-custom-data-properties-relationship",
                            _custom_data_store_relationship_semantic(relationship),
                        )
            custom_data_relationship_members = {
                member
                for member in members
                if member.casefold().startswith("xl/customdata/_rels/")
                and member.casefold().endswith(".rels")
            }
            for member in sorted(custom_data_relationship_members):
                if member not in inspected_custom_data_relationship_members:
                    _custom_data_store_issue(
                        issues,
                        "unbound-custom-data-relationship-part",
                        member,
                    )

            discovered_custom_data_payload_members = (
                custom_data_members - actual_custom_data_property_members
            )
            custom_data_payload_members = (
                custom_data_payload_targets | discovered_custom_data_payload_members
            ) - actual_custom_data_property_members
            actual_custom_data_payload_members = {
                member
                for member in custom_data_payload_members
                if member in members
            }
            for member in sorted(discovered_custom_data_payload_members):
                if member not in custom_data_payload_targets:
                    _custom_data_store_issue(
                        issues,
                        "unbound-custom-data-payload-part",
                        member,
                    )
            for member in sorted(actual_custom_data_payload_members):
                payload, fallback_signature = _custom_data_store_bounded_payload(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if payload is None:
                    _custom_data_store_issue(
                        issues,
                        "unreadable-custom-data-payload-part",
                        (member, fallback_signature),
                    )
                    custom_data_entries.append(
                        (
                            "unreadable-custom-data-payload-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                custom_data_entries.append(
                    (
                        "custom-data-payload",
                        _private_payload_signature(payload),
                    )
                )

            document_property_targets: set[str] = set()
            for relationship in root_document_property_relationships:
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.target is None
                ):
                    _custom_data_store_issue(
                        issues,
                        "unsafe-custom-document-properties-relationship",
                        _custom_data_store_relationship_semantic(relationship),
                    )
                    relationship_entries.append(
                        (
                            "package-root-custom-document-properties-relationship",
                            repr(
                                _custom_data_store_relationship_semantic(
                                    relationship
                                )
                            ),
                        )
                    )
                    continue
                document_property_targets.add(relationship.target)
                relationship_entries.append(
                    (
                        "package-root-custom-document-properties-relationship",
                        repr(
                            _custom_data_store_relationship_semantic(
                                relationship,
                                target_kind="custom-document-properties",
                            )
                        ),
                    )
                )
                if relationship.target not in members:
                    _custom_data_store_issue(
                        issues,
                        "missing-custom-document-properties-part",
                        relationship.target,
                    )
            document_property_members = set(document_property_targets)
            if _CUSTOM_DOCUMENT_PROPERTIES_MEMBER in members:
                document_property_members.add(_CUSTOM_DOCUMENT_PROPERTIES_MEMBER)
            actual_document_property_members = {
                member
                for member in document_property_members
                if member in members
            }
            for member in sorted(actual_document_property_members):
                if member not in document_property_targets:
                    _custom_data_store_issue(
                        issues,
                        "unbound-custom-document-properties-part",
                        member,
                    )
            document_custom_property_count = 0
            linked_document_custom_property_count = 0
            for member in sorted(actual_document_property_members):
                root, fallback_signature = _custom_data_store_bounded_root(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                if root is None:
                    _custom_data_store_issue(
                        issues,
                        "unreadable-custom-document-properties-part",
                        (member, fallback_signature),
                    )
                    document_property_entries.append(
                        (
                            "unreadable-custom-document-properties-part",
                            fallback_signature or "",
                        )
                    )
                    continue
                entries, count, linked_count = (
                    _custom_data_store_document_property_entries(
                        root,
                        issues,
                        context="custom-document-properties",
                    )
                )
                document_custom_property_count += count
                linked_document_custom_property_count += linked_count
                document_property_entries.extend(
                    ("custom-document-property", entry)
                    for entry in entries
                )

            issue_entries = [
                ("custom-data-store-issue", repr(issue))
                for issue in sorted(issues)
            ]
            if issues:
                warnings.add(
                    "FormulaFence found malformed, unsupported, or incomplete "
                    "custom workbook data-store metadata; affected persisted "
                    "state has a coverage gap."
                )
            snapshot = CustomDataStoreSnapshot(
                custom_xml_part_count=len(generic_custom_xml_item_members),
                custom_xml_property_part_count=len(
                    actual_generic_custom_xml_property_members
                ),
                custom_xml_schema_reference_count=custom_xml_schema_reference_count,
                custom_xml_relationship_count=custom_xml_relationship_count,
                external_custom_xml_relationship_count=(
                    external_custom_xml_relationship_count
                ),
                custom_data_properties_part_count=len(
                    actual_custom_data_property_members
                ),
                custom_data_part_count=len(actual_custom_data_payload_members),
                document_custom_property_part_count=len(
                    actual_document_property_members
                ),
                document_custom_property_count=document_custom_property_count,
                linked_document_custom_property_count=(
                    linked_document_custom_property_count
                ),
                unrecognized_custom_data_store_count=len(issues),
                custom_xml_signature=_private_external_data_signature(
                    tuple(sorted(custom_xml_entries))
                ),
                custom_data_signature=_private_external_data_signature(
                    tuple(sorted(custom_data_entries))
                ),
                document_property_signature=_private_external_data_signature(
                    tuple(sorted(document_property_entries))
                ),
                relationship_signature=_private_external_data_signature(
                    tuple(sorted(relationship_entries + issue_entries))
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _CustomDataStoreMetadata(
            CustomDataStoreSnapshot(
                unrecognized_custom_data_store_count=1,
                relationship_signature=_private_external_data_signature(
                    (("custom-data-store-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect custom workbook data-store "
                f"OOXML ({type(error).__name__}); affected persisted state was not compared.",
            ),
        )
    return _CustomDataStoreMetadata(
        snapshot,
        tuple(sorted(warnings)),
        tuple(sorted(power_query_item_members, key=str.casefold)),
    )


@dataclass(frozen=True)
class _LegacyCommentRawRelationship:
    """One private package relationship used to locate legacy notes."""

    relationship_id: str | None
    relationship_type: str
    target: str | None
    target_mode: str
    safe_target: str | None

    def semantic_key(self) -> tuple[str, str, str]:
        """Return relationship semantics while ignoring writer-selected IDs."""
        target = self.target or ""
        if self.target_mode.casefold() == "internal" and self.safe_target is not None:
            target = self.safe_target
        return (
            self.relationship_type,
            self.target_mode.casefold(),
            target,
        )


@dataclass(frozen=True)
class _LegacyCommentPartInspection:
    """Private result of reading one legacy SpreadsheetML comments part."""

    member: str
    present: bool = False
    author_count: int = 0
    comment_count: int = 0
    comment_with_text_count: int = 0
    rich_text_comment_count: int = 0
    phonetic_comment_count: int = 0
    comment_property_count: int = 0
    threaded_placeholder_count: int = 0
    unrecognized_count: int = 0
    definition_signature: str | None = None


@dataclass(frozen=True)
class _LegacyNoteVmlInspection:
    """Private result of reading VML Note shapes for one worksheet."""

    member: str
    present: bool = False
    note_shape_count: int = 0
    visible_note_shape_count: int = 0
    anchored_note_shape_count: int = 0
    related_relationship_count: int = 0
    external_relationship_count: int = 0
    unrecognized_count: int = 0
    definition_signature: str | None = None
    relationship_signature: str | None = None


def _legacy_comment_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_LegacyCommentRawRelationship, ...] | None:
    """Read legacy-note package relationships without opening their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for legacy-note inspection "
            f"({type(error).__name__}); affected notes were not compared."
        )
        return None
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting legacy notes; affected "
            "notes were not compared."
        )
        return None

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_LegacyCommentRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _LegacyCommentRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting legacy "
            "notes; affected notes may be incomplete."
        )
        return None
    return tuple(relationships)


def _legacy_comment_relationship_signature(
    relationships: tuple[_LegacyCommentRawRelationship, ...],
) -> str | None:
    """Fingerprint note relationship semantics without exposing identifiers."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _legacy_comment_relationship_semantics(
    relationships: tuple[_LegacyCommentRawRelationship, ...],
    warnings: set[str],
    *,
    context: str,
) -> dict[str, tuple[str, str, str]]:
    """Resolve private relationship IDs to stable relationship semantics."""
    relationships_by_id: dict[str, list[_LegacyCommentRawRelationship]] = defaultdict(
        list
    )
    for relationship in relationships:
        if relationship.relationship_id:
            relationships_by_id[relationship.relationship_id].append(relationship)
        else:
            warnings.add(
                "FormulaFence found a legacy-note "
                f"{context} relationship without an id; affected notes have a coverage gap."
            )
    semantics: dict[str, tuple[str, str, str]] = {}
    for relationship_id, matches in relationships_by_id.items():
        values = sorted(match.semantic_key() for match in matches)
        if len(values) > 1:
            warnings.add(
                "FormulaFence found duplicate legacy-note "
                f"{context} relationship ids; affected notes have a coverage gap."
            )
        semantics[relationship_id] = values[0]
    return semantics


def _legacy_comment_content_type_member(value: str | None) -> str | None:
    """Return a safe archive member from one content-types PartName."""
    if not value or not value.startswith("/"):
        return None
    member = posixpath.normpath(value.lstrip("/"))
    if member in {".", ".."} or member.startswith("../"):
        return None
    return member


def _legacy_comment_package_members(
    archive: ZipFile,
    warnings: set[str],
) -> tuple[set[str], dict[str, tuple[str, ...]], list[tuple[str, str]]]:
    """Locate standard and declared legacy SpreadsheetML comment parts."""
    member_counts: dict[str, int] = defaultdict(int)
    members: set[str] = set()
    for entry in archive.infolist():
        if _LEGACY_COMMENT_PART_PATTERN.fullmatch(entry.filename):
            members.add(entry.filename)
            member_counts[entry.filename] += 1
    content_types: dict[str, list[str]] = defaultdict(list)
    issues: list[tuple[str, str]] = [
        ("duplicate-legacy-comment-package-member", repr((member, count)))
        for member, count in member_counts.items()
        if count > 1
    ]
    try:
        root = _xml_root(archive, "[Content_Types].xml")
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect OOXML content types for legacy notes "
            f"({type(error).__name__}); affected notes may be incomplete."
        )
        issues.append(("content-type-scan-failure", type(error).__name__))
        return members, {}, issues
    if (
        _xml_namespace(root.tag) != _CONTENT_TYPES_NS
        or _xml_local_name(root.tag) != "Types"
    ):
        warnings.add(
            "FormulaFence found an unexpected OOXML content-types root while inspecting "
            "legacy notes; affected notes may be incomplete."
        )
        issues.append(("unexpected-content-types-root", _xml_display_name(root.tag)))
        return members, {}, issues

    override_tag = f"{{{_CONTENT_TYPES_NS}}}Override"
    default_tag = f"{{{_CONTENT_TYPES_NS}}}Default"
    for child in root:
        if child.tag == default_tag:
            continue
        if child.tag != override_tag:
            issues.append(("unrecognised-content-types-child", _xml_display_name(child.tag)))
            continue
        member = _legacy_comment_content_type_member(child.get("PartName"))
        content_type = child.get("ContentType")
        if member is None or content_type is None:
            issues.append(("malformed-content-type-override", _xml_display_name(child.tag)))
            continue
        if (
            _LEGACY_COMMENT_PART_PATTERN.fullmatch(member)
            or content_type == _LEGACY_COMMENT_CONTENT_TYPE
        ):
            content_types[member].append(content_type)
        if content_type == _LEGACY_COMMENT_CONTENT_TYPE:
            members.add(member)
    issues.extend(
        ("duplicate-legacy-comment-content-type-override", repr((member, types)))
        for member, types in content_types.items()
        if len(types) > 1
    )
    return (
        members,
        {member: tuple(sorted(types)) for member, types in content_types.items()},
        issues,
    )


def _legacy_comment_content_type_status(
    member: str,
    content_types: Mapping[str, tuple[str, ...]],
) -> str:
    """Classify a legacy-note part declaration without exposing its path."""
    declared = content_types.get(member, ())
    if _LEGACY_COMMENT_CONTENT_TYPE in declared:
        return "declared"
    return "mismatched" if declared else "unlisted"


def _legacy_comment_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _LegacyCommentBudget,
) -> str | None:
    """Stream legacy Note XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _LEGACY_COMMENT_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read a legacy-note XML part whose XML structure "
        "exceeds the safety budget; affected notes have a coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _legacy_comment_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _LegacyCommentBudget,
    *,
    kind: str,
) -> tuple[bytes | None, str | None]:
    """Read one bounded legacy-note or VML XML part without resolving targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded legacy-note XML part count budget; "
            "affected notes have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a legacy-note "
            f"{kind} XML part; affected notes were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _LEGACY_COMMENT_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized legacy-note "
            f"{kind} XML part; affected notes have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded legacy-note XML read budget; affected "
            "notes have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = (
        _legacy_comment_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            warnings,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a legacy-note "
            f"{kind} XML package part ({type(error).__name__}); affected notes "
            "were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _legacy_comment_cell_reference(value: str | None) -> str | None:
    """Normalize one local A1 note reference without exposing invalid values."""
    if value is None or not (candidate := value.strip()):
        return None
    try:
        min_column, min_row, max_column, max_row = range_boundaries(candidate)
    except ValueError:
        return None
    if (
        min_column is None
        or min_row is None
        or max_column is None
        or max_row is None
        or min_column != max_column
        or min_row != max_row
        or min_column < 1
        or min_row < 1
        or min_column > MAX_EXCEL_COLUMN
        or min_row > MAX_EXCEL_ROW
    ):
        return None
    return f"{get_column_letter(min_column)}{min_row}"


def _legacy_comment_text_material(
    element: ElementTree.Element,
    *,
    context: str,
) -> tuple[tuple[object, ...], bool, bool, bool]:
    """Canonicalize one private comment text body and its rich presentation."""
    if (
        _xml_namespace(element.tag) != _SPREADSHEETML_NS
        or _xml_local_name(element.tag) != "text"
    ):
        return (
            (
                "unexpected-comment-text-root",
                _private_payload_signature(
                    ElementTree.tostring(element, encoding="utf-8")
                ),
            ),
            False,
            False,
            True,
        )
    rich_text = _rich_text_item(element, context=context)
    if rich_text is not None:
        material = (
            "rich",
            rich_text.text_signature,
            rich_text.style_sequence_signature,
            rich_text.style_layout_signature,
            rich_text.issue_signature,
        )
        return (
            material,
            rich_text.has_rich_runs,
            bool(
                rich_text.phonetic_run_count
                or rich_text.phonetic_property_count
            ),
            rich_text.unrecognized,
        )

    issues: list[tuple[str, str]] = []

    def note_issue(issue_context: str, detail: object) -> None:
        issues.append((issue_context, repr(detail)))

    text_tag = f"{{{_SPREADSHEETML_NS}}}t"
    direct_texts: list[ElementTree.Element] = []
    if element.attrib:
        note_issue(f"{context}:unsupported-attributes", tuple(sorted(element.attrib.items())))
    if element.text is not None and element.text.strip():
        note_issue(f"{context}:unexpected-text", element.text)
    for child_index, child in enumerate(element):
        if child.tag == text_tag:
            direct_texts.append(child)
        else:
            note_issue(f"{context}:child:{child_index}", child.tag)
    if len(direct_texts) != 1:
        note_issue(f"{context}:direct-text-count", len(direct_texts))
    value = ""
    preserve_space = False
    invalid = bool(issues)
    if direct_texts:
        value, preserve_space, text_invalid = _rich_text_text_value(
            direct_texts[0],
            context=f"{context}:direct-text",
            note_issue=note_issue,
        )
        invalid = invalid or text_invalid or bool(issues)
    material: tuple[object, ...] = (
        "plain",
        _rich_text_text_signature(value),
        preserve_space,
    )
    if invalid:
        material = (
            "unrecognized",
            _private_payload_signature(
                ElementTree.tostring(element, encoding="utf-8")
            ),
            _rich_text_private_digest(tuple(sorted(issues))),
        )
    return material, False, False, invalid


def _legacy_comment_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _LegacyCommentBudget,
) -> _LegacyCommentPartInspection:
    """Inspect one legacy comments part without rendering a note or its VML."""
    payload, fallback_signature = _legacy_comment_xml_payload(
        archive,
        member,
        warnings,
        budget,
        kind="comments",
    )
    if payload is None:
        return _LegacyCommentPartInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a legacy comments XML part "
            f"({type(error).__name__}); affected notes were not compared."
        )
        return _LegacyCommentPartInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(root.tag) != _SPREADSHEETML_NS
        or _xml_local_name(root.tag) != "comments"
    ):
        warnings.add(
            "FormulaFence found a legacy comments part with an unexpected root; "
            "affected notes were not compared."
        )
        return _LegacyCommentPartInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    authors_tag = f"{{{_SPREADSHEETML_NS}}}authors"
    author_tag = f"{{{_SPREADSHEETML_NS}}}author"
    comment_list_tag = f"{{{_SPREADSHEETML_NS}}}commentList"
    comment_tag = f"{{{_SPREADSHEETML_NS}}}comment"
    text_tag = f"{{{_SPREADSHEETML_NS}}}text"
    comment_properties_tag = f"{{{_SPREADSHEETML_NS}}}commentPr"
    issues: list[tuple[str, str]] = []
    root_fragments: list[tuple[object, ...]] = []
    author_nodes = [child for child in root if child.tag == authors_tag]
    comment_list_nodes = [child for child in root if child.tag == comment_list_tag]
    for child in root:
        if child.tag not in {authors_tag, comment_list_tag}:
            root_fragments.append(_xml_fragment(child).sort_key())
            issues.append(("unexpected-comments-root-child", _xml_display_name(child.tag)))
    if len(author_nodes) != 1:
        issues.append(("authors-container-count", str(len(author_nodes))))
    if len(comment_list_nodes) != 1:
        issues.append(("comment-list-container-count", str(len(comment_list_nodes))))

    authors: list[str] = []
    if author_nodes:
        authors_element = author_nodes[0]
        if authors_element.attrib or (
            authors_element.text is not None and authors_element.text.strip()
        ):
            issues.append(("malformed-authors-container", "present"))
        for child_index, author in enumerate(authors_element):
            if author.tag != author_tag:
                issues.append(
                    (
                        "unexpected-authors-child",
                        repr((child_index, _xml_display_name(author.tag))),
                    )
                )
                continue
            if author.attrib or any(author) or (
                author.tail is not None and author.tail.strip()
            ):
                issues.append(("malformed-author-record", str(child_index)))
            authors.append(author.text or "")
    if len(set(authors)) != len(authors):
        issues.append(("duplicate-comment-author", "present"))

    comment_fragments: list[tuple[object, ...]] = []
    comment_count = 0
    comment_with_text_count = 0
    rich_text_comment_count = 0
    phonetic_comment_count = 0
    comment_property_count = 0
    threaded_placeholder_count = 0
    references: set[str] = set()
    try:
        if comment_list_nodes:
            comment_list = comment_list_nodes[0]
            if comment_list.attrib or (
                comment_list.text is not None and comment_list.text.strip()
            ):
                issues.append(("malformed-comment-list-container", "present"))
            for child_index, comment in enumerate(comment_list):
                if comment.tag != comment_tag:
                    issues.append(
                        (
                            "unexpected-comment-list-child",
                            repr((child_index, _xml_display_name(comment.tag))),
                        )
                    )
                    continue
                comment_count += 1
                reference_raw = comment.get("ref")
                reference = _legacy_comment_cell_reference(reference_raw)
                if reference is None:
                    issues.append(("invalid-comment-reference", str(child_index)))
                    reference_signature = (
                        "invalid-reference",
                        reference_raw or "",
                    )
                else:
                    reference_signature = ("reference", reference)
                    if reference in references:
                        issues.append(("duplicate-comment-reference", reference))
                    references.add(reference)

                author_identifier = comment.get("authorId")
                author_value: str | None = None
                if (
                    author_identifier is not None
                    and author_identifier.isascii()
                    and author_identifier.isdecimal()
                    and int(author_identifier) < len(authors)
                ):
                    author_value = authors[int(author_identifier)]
                else:
                    issues.append(("invalid-comment-author-reference", str(child_index)))

                placeholder_match = (
                    _LEGACY_COMMENT_PLACEHOLDER_AUTHOR_PATTERN.search(author_value)
                    if author_value is not None
                    else None
                )
                is_placeholder = placeholder_match is not None
                if is_placeholder:
                    threaded_placeholder_count += 1
                    identifier = placeholder_match.group(1)
                    guid = comment.get("guid")
                    author_signature: object = (
                        "threaded-placeholder",
                        (
                            "guid-matches"
                            if guid is not None
                            and guid.casefold() == identifier.casefold()
                            else "guid-mismatch"
                        ),
                    )
                    if (
                        guid is None
                        or guid.casefold() != identifier.casefold()
                    ):
                        issues.append(("invalid-threaded-placeholder-guid", str(child_index)))
                elif author_value is not None:
                    author_signature = (
                        "author",
                        author_value,
                        "guid-present" if comment.get("guid") else "guid-absent",
                    )
                else:
                    author_signature = (
                        "invalid-author",
                        author_identifier or "",
                    )

                text_children = [child for child in comment if child.tag == text_tag]
                property_children = [
                    child for child in comment if child.tag == comment_properties_tag
                ]
                if text_children:
                    comment_with_text_count += 1
                if len(text_children) != 1:
                    issues.append(("comment-text-count", str(child_index)))
                    text_material: tuple[object, ...] = (
                        "unrecognized-text-count",
                        _private_payload_signature(
                            ElementTree.tostring(comment, encoding="utf-8")
                        ),
                    )
                    text_unrecognized = True
                    has_rich_text = False
                    has_phonetic = False
                else:
                    (
                        text_material,
                        has_rich_text,
                        has_phonetic,
                        text_unrecognized,
                    ) = _legacy_comment_text_material(
                        text_children[0],
                        context=f"legacy-comment:{member}:{child_index}",
                    )
                rich_text_comment_count += int(has_rich_text)
                phonetic_comment_count += int(has_phonetic)
                if text_unrecognized:
                    issues.append(("unsupported-comment-text", str(child_index)))
                if len(property_children) > 1:
                    issues.append(("multiple-comment-properties", str(child_index)))
                comment_property_count += len(property_children)
                property_fragments = tuple(
                    sorted(
                        (_xml_fragment(properties).sort_key() for properties in property_children),
                        key=repr,
                    )
                )
                unexpected_children = tuple(
                    _xml_fragment(child).sort_key()
                    for child in comment
                    if child.tag not in {text_tag, comment_properties_tag}
                )
                if unexpected_children:
                    issues.append(("unexpected-comment-child", str(child_index)))
                unknown_attributes = tuple(
                    sorted(
                        (_xml_display_name(attribute), value)
                        for attribute, value in comment.attrib.items()
                        if _xml_local_name(attribute)
                        not in {"ref", "authorId", "shapeId", "guid"}
                    )
                )
                if unknown_attributes:
                    issues.append(("unknown-comment-attribute", str(child_index)))
                comment_fragments.append(
                    (
                        reference_signature,
                        author_signature,
                        text_material,
                        property_fragments,
                        unknown_attributes,
                        unexpected_children,
                    )
                )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested legacy "
            "comment record; affected notes were not compared."
        )
        return _LegacyCommentPartInspection(
            member=member,
            present=True,
            author_count=len(authors),
            comment_count=comment_count,
            comment_with_text_count=comment_with_text_count,
            rich_text_comment_count=rich_text_comment_count,
            phonetic_comment_count=phonetic_comment_count,
            comment_property_count=comment_property_count,
            threaded_placeholder_count=threaded_placeholder_count,
            unrecognized_count=len(issues) + 1,
            definition_signature=_private_payload_signature(payload),
        )

    definition_entries = [
        (f"comment:{index}", repr(fragment))
        for index, fragment in enumerate(sorted(comment_fragments, key=repr))
    ]
    definition_entries.extend(
        (f"root-fragment:{index}", repr(fragment))
        for index, fragment in enumerate(sorted(root_fragments, key=repr))
    )
    definition_entries.extend(sorted(issues))
    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported legacy-comment metadata; "
            "affected notes have a coverage gap."
        )
    return _LegacyCommentPartInspection(
        member=member,
        present=True,
        author_count=len(authors),
        comment_count=comment_count,
        comment_with_text_count=comment_with_text_count,
        rich_text_comment_count=rich_text_comment_count,
        phonetic_comment_count=phonetic_comment_count,
        comment_property_count=comment_property_count,
        threaded_placeholder_count=threaded_placeholder_count,
        unrecognized_count=len(issues),
        definition_signature=_private_external_data_signature(tuple(definition_entries)),
    )


def _legacy_note_coordinate(
    client_data: ElementTree.Element,
) -> str | None:
    """Translate one VML Note row/column binding to a private A1 location."""
    row_tag = f"{{{_VML_EXCEL_NS}}}Row"
    column_tag = f"{{{_VML_EXCEL_NS}}}Column"
    rows = [child for child in client_data if child.tag == row_tag]
    columns = [child for child in client_data if child.tag == column_tag]
    if len(rows) != 1 or len(columns) != 1:
        return None
    row_value = (rows[0].text or "").strip()
    column_value = (columns[0].text or "").strip()
    if (
        not row_value.isascii()
        or not row_value.isdecimal()
        or not column_value.isascii()
        or not column_value.isdecimal()
    ):
        return None
    row = int(row_value)
    column = int(column_value)
    if (
        row < 0
        or column < 0
        or row >= MAX_EXCEL_ROW
        or column >= MAX_EXCEL_COLUMN
    ):
        return None
    return f"{get_column_letter(column + 1)}{row + 1}"


def _legacy_note_vml_style(
    value: str | None,
) -> tuple[tuple[tuple[str, str], ...], bool]:
    """Normalize a VML style declaration while retaining invalid material privately."""
    if value is None:
        return (), False
    properties: dict[str, str] = {}
    invalid = False
    for item in value.split(";"):
        candidate = item.strip()
        if not candidate:
            continue
        if ":" not in candidate:
            invalid = True
            continue
        name, setting = candidate.split(":", maxsplit=1)
        name = name.strip().casefold()
        setting = setting.strip()
        if not name or not setting or name in properties:
            invalid = True
            continue
        properties[name] = setting
    return tuple(sorted(properties.items())), invalid


def _legacy_note_vml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    shape_type_fragments: Mapping[str, tuple[object, ...]],
    *,
    relationship_attributes: frozenset[str],
) -> tuple[object, ...]:
    """Canonicalize one VML Note declaration without volatile VML IDs."""
    namespace = _xml_namespace(element.tag)
    local_name = _xml_local_name(element.tag)
    is_shape = namespace == _VML_NS and local_name == "shape"
    is_shape_type = namespace == _VML_NS and local_name == "shapetype"
    attributes: list[tuple[str, object]] = []
    for attribute, value in element.attrib.items():
        attribute_local_name = _xml_local_name(attribute)
        if (
            namespace == _VML_NS
            and attribute_local_name == "id"
            and (is_shape or is_shape_type)
        ):
            continue
        if (
            _xml_namespace(attribute) == _VML_OFFICE_NS
            and attribute_local_name == "spid"
        ):
            continue
        if attribute in relationship_attributes:
            relationship = relationship_semantics.get(value)
            resolved: object = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if is_shape and attribute_local_name == "type":
            type_identifier = value.lstrip("#")
            type_fragment = shape_type_fragments.get(type_identifier)
            attributes.append(
                (
                    _xml_display_name(attribute),
                    repr(
                        ("shape-type", type_fragment)
                        if type_fragment is not None
                        else ("missing-shape-type", type_identifier)
                    ),
                )
            )
            continue
        if attribute_local_name == "style":
            style, invalid_style = _legacy_note_vml_style(value)
            attributes.append(
                (
                    _xml_display_name(attribute),
                    repr(("invalid-style", value) if invalid_style else style),
                )
            )
            continue
        attributes.append((_xml_display_name(attribute), value))
    children = tuple(
        _legacy_note_vml_fragment(
            child,
            relationship_semantics,
            shape_type_fragments,
            relationship_attributes=relationship_attributes,
        )
        for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes, key=repr)),
        text,
        children,
    )


def _legacy_note_vml_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _LegacyCommentBudget,
) -> _LegacyNoteVmlInspection:
    """Inspect VML Note visibility and layout without rendering VML."""
    payload, fallback_signature = _legacy_comment_xml_payload(
        archive,
        member,
        warnings,
        budget,
        kind="VML note drawing",
    )
    if payload is None:
        return _LegacyNoteVmlInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a legacy VML note drawing "
            f"({type(error).__name__}); affected notes were not compared."
        )
        return _LegacyNoteVmlInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if _xml_local_name(root.tag) != "xml" or _xml_namespace(root.tag) not in {
        None,
        _VML_NS,
    }:
        warnings.add(
            "FormulaFence found a legacy VML note drawing with an unexpected root; "
            "affected notes were not compared."
        )
        return _LegacyNoteVmlInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    relationships = _legacy_comment_raw_relationships(
        archive,
        member,
        warnings,
        context="legacy VML note drawing",
    )
    if relationships is None:
        return _LegacyNoteVmlInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    relationship_semantics = _legacy_comment_relationship_semantics(
        relationships,
        warnings,
        context="legacy VML note drawing",
    )
    relationship_by_id = {
        relationship.relationship_id: relationship
        for relationship in relationships
        if relationship.relationship_id
    }
    relationship_attributes = frozenset(
        {
            f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id",
            f"{{{_VML_OFFICE_NS}}}relid",
        }
    )
    parent_by_child = {
        child: parent
        for parent in root.iter()
        for child in parent
    }
    client_data_tag = f"{{{_VML_EXCEL_NS}}}ClientData"
    shape_tag = f"{{{_VML_NS}}}shape"
    shape_type_tag = f"{{{_VML_NS}}}shapetype"
    raw_shape_type_fragments: dict[str, tuple[object, ...]] = {}
    for shape_type in root.iter(shape_type_tag):
        identifier = shape_type.get("id")
        if identifier:
            raw_shape_type_fragments[identifier] = _legacy_note_vml_fragment(
                shape_type,
                relationship_semantics,
                {},
                relationship_attributes=relationship_attributes,
            )

    note_records: list[tuple[ElementTree.Element, ElementTree.Element]] = []
    seen_shapes: set[int] = set()
    issues: list[tuple[str, str]] = []
    for client_data in root.iter(client_data_tag):
        if (client_data.get("ObjectType") or "").strip().casefold() != "note":
            continue
        container = parent_by_child.get(client_data)
        while container is not None and container.tag != shape_tag:
            container = parent_by_child.get(container)
        if container is None:
            issues.append(("note-without-vml-shape", "present"))
            continue
        if id(container) in seen_shapes:
            issues.append(("multiple-note-client-data-in-one-shape", "present"))
            continue
        seen_shapes.add(id(container))
        note_records.append((container, client_data))

    if not note_records:
        return _LegacyNoteVmlInspection(member=member)

    referenced_relationship_ids = {
        relationship_id
        for container, _client_data in note_records
        for element in container.iter()
        for relationship_attribute in relationship_attributes
        if (relationship_id := element.get(relationship_attribute)) is not None
    }
    selected_relationships: list[_LegacyCommentRawRelationship] = []
    for relationship_id in sorted(referenced_relationship_ids):
        relationship = relationship_by_id.get(relationship_id)
        if relationship is None:
            issues.append(("note-relationship-without-target", relationship_id))
            continue
        selected_relationships.append(relationship)
        if (
            relationship.target_mode.casefold() != "internal"
            or relationship.safe_target is None
        ):
            issues.append(("unsafe-note-relationship", repr(relationship.semantic_key())))

    note_fragments: list[tuple[str, tuple[object, ...]]] = []
    visible_note_shape_count = 0
    anchored_note_shape_count = 0
    for index, (container, client_data) in enumerate(note_records):
        coordinate = _legacy_note_coordinate(client_data)
        if coordinate is None:
            issues.append(("invalid-note-coordinate", str(index)))
            coordinate_key = f"invalid:{index}"
        else:
            coordinate_key = coordinate
        anchor_tag = f"{{{_VML_EXCEL_NS}}}Anchor"
        anchored_note_shape_count += int(
            any(child.tag == anchor_tag for child in client_data)
        )
        style, invalid_style = _legacy_note_vml_style(container.get("style"))
        if invalid_style:
            issues.append(("invalid-note-vml-style", str(index)))
        style_map = dict(style)
        visibility = style_map.get("visibility", "visible").casefold()
        if visibility not in {"visible", "hidden", "inherit"}:
            issues.append(("invalid-note-visibility", str(index)))
        if visibility != "hidden":
            visible_note_shape_count += 1
        shape_type_reference = (container.get("type") or "").lstrip("#")
        if shape_type_reference and shape_type_reference not in raw_shape_type_fragments:
            issues.append(("missing-note-shape-type", str(index)))
        note_fragments.append(
            (
                coordinate_key,
                _legacy_note_vml_fragment(
                    container,
                    relationship_semantics,
                    raw_shape_type_fragments,
                    relationship_attributes=relationship_attributes,
                ),
            )
        )

    definition_entries = [
        (f"note:{index}", repr(fragment))
        for index, fragment in enumerate(note_fragments)
    ]
    definition_entries.extend(sorted(issues))
    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported legacy VML note metadata; "
            "affected notes have a coverage gap."
        )
    return _LegacyNoteVmlInspection(
        member=member,
        present=True,
        note_shape_count=len(note_records),
        visible_note_shape_count=visible_note_shape_count,
        anchored_note_shape_count=anchored_note_shape_count,
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        unrecognized_count=len(issues),
        definition_signature=_private_external_data_signature(tuple(definition_entries)),
        relationship_signature=_legacy_comment_relationship_signature(
            tuple(selected_relationships)
        ),
    )


def _legacy_comment_metadata(path: Path) -> _LegacyCommentMetadata:
    """Inspect legacy notes and threaded-comment placeholders before reader loss.

    The scan follows only worksheet relationships that bind Comments and VML
    legacy drawings. It compares content, author associations, placeholder
    reconciliation fields, visibility, and layout through private signatures;
    it never renders VML, resolves a user, or exposes note text.
    """
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _LegacyCommentMetadata(
                    LegacyCommentSnapshot(
                        unrecognized_legacy_comment_count=1,
                        definition_signature=_private_external_data_signature(
                            (("sheet-part-scan-failure", type(error).__name__),)
                        ),
                    ),
                    (
                        "FormulaFence could not inspect worksheet OOXML relationships "
                        f"for legacy notes ({type(error).__name__}); affected notes "
                        "were not compared.",
                    ),
                )

            comment_members, content_types, package_issues = (
                _legacy_comment_package_members(archive, warnings)
            )
            coverage_entries: list[tuple[str, str]] = list(package_issues)
            declaration_entries: list[tuple[str, str]] = []
            relationship_entries: list[tuple[str, str]] = []
            comment_sources: dict[str, set[str]] = defaultdict(set)
            note_vml_sources: dict[str, set[str]] = defaultdict(set)
            selected_relationships: list[tuple[str, _LegacyCommentRawRelationship]] = []

            for sheet, (member, sheet_kind) in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                if sheet_kind != "worksheet":
                    continue
                relationships = _legacy_comment_raw_relationships(
                    archive,
                    member,
                    warnings,
                    context="worksheet",
                )
                if relationships is None:
                    coverage_entries.append(
                        ("unreadable-worksheet-legacy-note-relationships", member)
                    )
                    continue
                relationship_ids: dict[str, int] = defaultdict(int)
                for relationship in relationships:
                    if relationship.relationship_id:
                        relationship_ids[relationship.relationship_id] += 1
                for relationship_id, count in relationship_ids.items():
                    if count > 1:
                        coverage_entries.append(
                            (
                                "duplicate-worksheet-legacy-note-relationship-id",
                                relationship_id,
                            )
                        )
                comment_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type.casefold()
                    == _LEGACY_COMMENT_RELATIONSHIP.casefold()
                ]
                for relationship in comment_relationships:
                    selected_relationships.append(("comments", relationship))
                    if (
                        not relationship.relationship_id
                        or relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        coverage_entries.append(
                            (
                                "unsafe-legacy-comment-relationship",
                                repr(relationship.semantic_key()),
                            )
                        )
                        relationship_entries.append(
                            ("comments", repr(relationship.semantic_key()))
                        )
                        continue
                    comment_sources[relationship.safe_target].add(sheet)

                if not comment_relationships:
                    continue
                try:
                    worksheet = _xml_root(archive, member)
                except (
                    KeyError,
                    ElementTree.ParseError,
                    OSError,
                    RuntimeError,
                    ValueError,
                ) as error:
                    coverage_entries.append(
                        (
                            "unreadable-worksheet-legacy-drawing",
                            type(error).__name__,
                        )
                    )
                    continue
                if (
                    _xml_namespace(worksheet.tag) != _SPREADSHEETML_NS
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    coverage_entries.append(
                        ("unexpected-worksheet-root-for-legacy-notes", sheet)
                    )
                    continue
                relationship_attribute = f"{{{_DOCUMENT_RELATIONSHIP_NS}}}id"
                legacy_drawing_tag = f"{{{_SPREADSHEETML_NS}}}legacyDrawing"
                legacy_drawing_ids = {
                    relationship_id
                    for legacy_drawing in worksheet.iter(legacy_drawing_tag)
                    if (relationship_id := legacy_drawing.get(relationship_attribute))
                    is not None
                }
                vml_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type.casefold()
                    == _LEGACY_VML_RELATIONSHIP.casefold()
                ]
                vml_by_id = {
                    relationship.relationship_id: relationship
                    for relationship in vml_relationships
                    if relationship.relationship_id
                }
                for relationship_id in legacy_drawing_ids:
                    relationship = vml_by_id.get(relationship_id)
                    if relationship is None:
                        coverage_entries.append(
                            (
                                "legacy-drawing-without-vml-relationship",
                                relationship_id,
                            )
                        )
                        continue
                    selected_relationships.append(("note-vml", relationship))
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        coverage_entries.append(
                            (
                                "unsafe-legacy-note-vml-relationship",
                                repr(relationship.semantic_key()),
                            )
                        )
                        relationship_entries.append(
                            ("note-vml", repr(relationship.semantic_key()))
                        )
                        continue
                    note_vml_sources[relationship.safe_target].add(sheet)
                for relationship in vml_relationships:
                    if relationship.relationship_id not in legacy_drawing_ids:
                        coverage_entries.append(
                            (
                                "unbound-legacy-note-vml-relationship",
                                repr(relationship.semantic_key()),
                            )
                        )

            comment_members.update(comment_sources)
            for member in sorted(comment_members, key=str.casefold):
                if member not in comment_sources:
                    coverage_entries.append(("unbound-legacy-comment-part", member))
            budget = _LegacyCommentBudget()
            comment_inspections = [
                _legacy_comment_part_inspection(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                for member in sorted(comment_members, key=str.casefold)
            ]
            note_inspections = [
                _legacy_note_vml_inspection(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                for member in sorted(note_vml_sources, key=str.casefold)
            ]

            for inspection in comment_inspections:
                sources = tuple(
                    sorted(comment_sources.get(inspection.member, ()), key=str.casefold)
                )
                content_status = _legacy_comment_content_type_status(
                    inspection.member,
                    content_types,
                )
                declaration_entries.append(
                    (
                        "legacy-comment-binding",
                        repr((sources, content_status)),
                    )
                )
                if content_status != "declared":
                    coverage_entries.append(
                        ("invalid-legacy-comment-content-type", content_status)
                    )
            note_definition_entries: list[tuple[str, str]] = []
            for inspection in note_inspections:
                if not inspection.present:
                    continue
                sources = tuple(
                    sorted(
                        note_vml_sources.get(inspection.member, ()),
                        key=str.casefold,
                    )
                )
                declaration_entries.append(
                    ("legacy-note-vml-binding", repr(sources))
                )
                note_definition_entries.append(
                    (
                        "legacy-note-vml",
                        repr((sources, inspection.definition_signature)),
                    )
                )
                if inspection.relationship_signature is not None:
                    relationship_entries.append(
                        (
                            "legacy-note-vml-relationship",
                            inspection.relationship_signature,
                        )
                    )
            relationship_entries.extend(
                (
                    f"legacy-note-{label}-relationship",
                    repr(relationship.semantic_key()),
                )
                for label, relationship in selected_relationships
            )

            if coverage_entries:
                warnings.add(
                    "FormulaFence found malformed, unbound, or unsupported legacy-note "
                    "metadata; affected notes have a coverage gap."
                )
            comment_definition_entries = [
                (
                    "legacy-comment-part",
                    repr(
                        (
                            tuple(
                                sorted(
                                    comment_sources.get(inspection.member, ()),
                                    key=str.casefold,
                                )
                            ),
                            _legacy_comment_content_type_status(
                                inspection.member,
                                content_types,
                            ),
                            inspection.definition_signature,
                        )
                    ),
                )
                for inspection in comment_inspections
            ]
            comment_definition_entries.sort(key=lambda entry: entry[1])
            note_definition_entries.sort(key=lambda entry: entry[1])
            comment_sheets = {
                sheet
                for sources in comment_sources.values()
                for sheet in sources
            }
            note_sheets = {
                sheet
                for inspection in note_inspections
                if inspection.present
                for sheet in note_vml_sources.get(inspection.member, ())
            }
            snapshot = LegacyCommentSnapshot(
                worksheet_comment_sheet_count=len(comment_sheets),
                comment_part_count=len(comment_inspections),
                comment_author_count=sum(
                    inspection.author_count for inspection in comment_inspections
                ),
                comment_count=sum(
                    inspection.comment_count for inspection in comment_inspections
                ),
                comment_with_text_count=sum(
                    inspection.comment_with_text_count
                    for inspection in comment_inspections
                ),
                rich_text_comment_count=sum(
                    inspection.rich_text_comment_count
                    for inspection in comment_inspections
                ),
                phonetic_comment_count=sum(
                    inspection.phonetic_comment_count
                    for inspection in comment_inspections
                ),
                comment_property_count=sum(
                    inspection.comment_property_count
                    for inspection in comment_inspections
                ),
                threaded_placeholder_count=sum(
                    inspection.threaded_placeholder_count
                    for inspection in comment_inspections
                ),
                worksheet_note_drawing_sheet_count=len(note_sheets),
                note_vml_drawing_part_count=sum(
                    inspection.present for inspection in note_inspections
                ),
                note_shape_count=sum(
                    inspection.note_shape_count for inspection in note_inspections
                ),
                visible_note_shape_count=sum(
                    inspection.visible_note_shape_count
                    for inspection in note_inspections
                ),
                anchored_note_shape_count=sum(
                    inspection.anchored_note_shape_count
                    for inspection in note_inspections
                ),
                binding_relationship_count=(
                    len(selected_relationships)
                    + sum(
                        inspection.related_relationship_count
                        for inspection in note_inspections
                    )
                ),
                external_relationship_count=sum(
                    relationship.target_mode.casefold() != "internal"
                    for _label, relationship in selected_relationships
                )
                + sum(
                    inspection.external_relationship_count
                    for inspection in note_inspections
                ),
                unrecognized_legacy_comment_count=(
                    len(coverage_entries)
                    + sum(
                        inspection.unrecognized_count
                        for inspection in comment_inspections
                    )
                    + sum(
                        inspection.unrecognized_count
                        for inspection in note_inspections
                    )
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(sorted([*declaration_entries, *coverage_entries]))
                ),
                definition_signature=_private_external_data_signature(
                    tuple(comment_definition_entries)
                ),
                note_shape_signature=_private_external_data_signature(
                    tuple(note_definition_entries)
                ),
                relationship_signature=_private_external_data_signature(
                    tuple(sorted(relationship_entries))
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _LegacyCommentMetadata(
            LegacyCommentSnapshot(
                unrecognized_legacy_comment_count=1,
                definition_signature=_private_external_data_signature(
                    (("legacy-comment-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect legacy-note OOXML "
                f"({type(error).__name__}); affected notes were not compared.",
            ),
        )
    return _LegacyCommentMetadata(snapshot, tuple(sorted(warnings)))


@dataclass(frozen=True)
class _ThreadedCommentRawRelationship:
    """One private package relationship used to locate modern comments."""

    relationship_id: str | None
    relationship_type: str
    target: str | None
    target_mode: str
    safe_target: str | None


@dataclass(frozen=True)
class _ThreadedCommentPerson:
    """One private person record with its writer-generated identifier detached."""

    identifier: str | None
    fragment: tuple[object, ...]


@dataclass(frozen=True)
class _ThreadedCommentPersonInspection:
    """Private result of reading one modern-comment person part."""

    member: str
    present: bool = False
    person_count: int = 0
    people: tuple[_ThreadedCommentPerson, ...] = ()
    unrecognized_count: int = 0
    definition_signature: str | None = None


@dataclass(frozen=True)
class _ThreadedCommentRawEntry:
    """One private comment node prior to graph canonicalisation."""

    identifier: str | None
    parent_identifier: str | None
    fragment: tuple[object, ...]


@dataclass(frozen=True)
class _ThreadedCommentPartInspection:
    """Private result of reading one worksheet threaded-comment part."""

    member: str
    present: bool = False
    comment_thread_count: int = 0
    comment_count: int = 0
    reply_count: int = 0
    resolved_comment_count: int = 0
    comment_with_text_count: int = 0
    mention_count: int = 0
    referenced_person_ids: frozenset[str] = frozenset()
    mentioned_person_ids: frozenset[str] = frozenset()
    unrecognized_count: int = 0
    definition_signature: str | None = None


def _threaded_comment_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_ThreadedCommentRawRelationship, ...] | None:
    """Read modern-comment relationships without following their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for threaded-comment inspection "
            f"({type(error).__name__}); affected comments were not compared."
        )
        return None
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting threaded comments; "
            "affected comments were not compared."
        )
        return None

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_ThreadedCommentRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _ThreadedCommentRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting "
            "threaded comments; affected comments may be incomplete."
        )
        return None
    return tuple(relationships)


def _threaded_comment_content_type_member(value: str | None) -> str | None:
    """Return a safe archive member from one content-types ``PartName``."""
    if not value or not value.startswith("/"):
        return None
    member = posixpath.normpath(value.lstrip("/"))
    if member in {".", ".."} or member.startswith("../"):
        return None
    return member


def _threaded_comment_package_members(
    archive: ZipFile,
    warnings: set[str],
) -> tuple[
    set[str],
    set[str],
    dict[str, tuple[str, ...]],
    list[tuple[str, str]],
]:
    """Locate declared and conventionally named modern-comment package parts."""
    member_counts: dict[str, int] = defaultdict(int)
    threaded_members: set[str] = set()
    person_members: set[str] = set()
    for entry in archive.infolist():
        member = entry.filename
        if _THREADED_COMMENT_PART_PATTERN.fullmatch(member):
            threaded_members.add(member)
            member_counts[member] += 1
        elif _THREADED_COMMENT_PERSON_PART_PATTERN.fullmatch(member):
            person_members.add(member)
            member_counts[member] += 1
    content_types: dict[str, list[str]] = defaultdict(list)
    issues: list[tuple[str, str]] = [
        ("duplicate-threaded-comment-package-member", repr((member, count)))
        for member, count in member_counts.items()
        if count > 1
    ]
    try:
        root = _xml_root(archive, "[Content_Types].xml")
    except (KeyError, ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect OOXML content types for threaded comments "
            f"({type(error).__name__}); affected comments may be incomplete."
        )
        issues.append(("content-type-scan-failure", type(error).__name__))
        return threaded_members, person_members, {}, issues
    if (
        _xml_namespace(root.tag) != _CONTENT_TYPES_NS
        or _xml_local_name(root.tag) != "Types"
    ):
        warnings.add(
            "FormulaFence found an unexpected OOXML content-types root while inspecting "
            "threaded comments; affected comments may be incomplete."
        )
        issues.append(("unexpected-content-types-root", _xml_display_name(root.tag)))
        return threaded_members, person_members, {}, issues

    override_tag = f"{{{_CONTENT_TYPES_NS}}}Override"
    default_tag = f"{{{_CONTENT_TYPES_NS}}}Default"
    for child in root:
        if child.tag == default_tag:
            continue
        if child.tag != override_tag:
            issues.append(("unrecognised-content-types-child", _xml_display_name(child.tag)))
            continue
        member = _threaded_comment_content_type_member(child.get("PartName"))
        content_type = child.get("ContentType")
        if member is None or content_type is None:
            issues.append(("malformed-content-type-override", _xml_display_name(child.tag)))
            continue
        content_types[member].append(content_type)
        if content_type == _THREADED_COMMENT_CONTENT_TYPE:
            threaded_members.add(member)
        elif content_type == _THREADED_COMMENT_PERSON_CONTENT_TYPE:
            person_members.add(member)
    issues.extend(
        ("duplicate-threaded-comment-content-type-override", repr((member, types)))
        for member, types in content_types.items()
        if len(types) > 1
    )
    return (
        threaded_members,
        person_members,
        {member: tuple(sorted(types)) for member, types in content_types.items()},
        issues,
    )


def _threaded_comment_content_type_status(
    member: str,
    content_types: Mapping[str, tuple[str, ...]],
    expected_content_type: str,
) -> str:
    """Classify a part declaration without exposing its package path."""
    declared = content_types.get(member, ())
    if expected_content_type in declared:
        return "declared"
    return "mismatched" if declared else "unlisted"


def _threaded_comment_xml_structure_budget_fallback_signature(
    archive: ZipFile,
    member: str,
    info,
    warnings: set[str],
    budget: _ThreadedCommentBudget,
) -> str | None:
    """Stream comment XML before recursively canonicalizing its private tree."""
    try:
        element_count = _ooxml_xml_structure_element_count_within_budget(
            archive,
            member,
            maximum_element_count=min(
                _THREADED_COMMENT_MAX_XML_ELEMENT_COUNT,
                budget.remaining_xml_elements,
            ),
        )
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError):
        # Preserve the established full-parser diagnostic for malformed or
        # unreadable input. Only a successfully streamed over-budget part can
        # safely bypass the materializing XML root parser below.
        return None
    if element_count is not None:
        budget.remaining_xml_elements -= element_count
        return None
    warnings.add(
        "FormulaFence did not fully read a threaded-comment XML part whose XML "
        "structure exceeds the safety budget; affected comments have a coverage gap."
    )
    return _private_external_data_signature(
        (
            ("xml-structure-budget-exhausted", member),
            ("size", str(info.file_size)),
            ("compressed-size", str(info.compress_size)),
            ("crc", str(info.CRC)),
        )
    )


def _threaded_comment_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _ThreadedCommentBudget,
    *,
    kind: str,
) -> tuple[bytes | None, str | None]:
    """Read one bounded threaded-comment XML part without following targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded threaded-comment XML part count budget; "
            "affected comments have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a threaded-comment "
            f"{kind} XML part; affected comments were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _THREADED_COMMENT_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized threaded-comment "
            f"{kind} XML part; affected comments have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded threaded-comment XML read budget; "
            "affected comments have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    structure_fallback_signature = (
        _threaded_comment_xml_structure_budget_fallback_signature(
            archive,
            member,
            info,
            warnings,
            budget,
        )
    )
    if structure_fallback_signature is not None:
        return None, structure_fallback_signature
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a threaded-comment "
            f"{kind} XML package part ({type(error).__name__}); affected comments "
            "were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _threaded_comment_person_fragment(
    element: ElementTree.Element,
) -> tuple[object, ...]:
    """Canonicalise person XML while excluding its writer-generated identifier."""
    is_person = (
        _xml_namespace(element.tag) in _THREADED_COMMENT_PERSON_NAMESPACES
        and _xml_local_name(element.tag) == "person"
    )
    attributes = tuple(
        sorted(
            (_xml_display_name(attribute), value)
            for attribute, value in element.attrib.items()
            if not (is_person and _xml_local_name(attribute) == "id")
        )
    )
    children = tuple(_threaded_comment_person_fragment(child) for child in element)
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (_xml_display_name(element.tag), attributes, text, children)


def _threaded_comment_person_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _ThreadedCommentBudget,
) -> _ThreadedCommentPersonInspection:
    """Inspect one person list used by modern Excel comments."""
    payload, fallback_signature = _threaded_comment_xml_payload(
        archive,
        member,
        warnings,
        budget,
        kind="person",
    )
    if payload is None:
        return _ThreadedCommentPersonInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a threaded-comment person XML part "
            f"({type(error).__name__}); affected comments were not compared."
        )
        return _ThreadedCommentPersonInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(root.tag) not in _THREADED_COMMENT_PERSON_NAMESPACES
        or _xml_local_name(root.tag) != "personList"
    ):
        warnings.add(
            "FormulaFence found a threaded-comment person part with an unexpected root; "
            "affected comments were not compared."
        )
        return _ThreadedCommentPersonInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    people: list[_ThreadedCommentPerson] = []
    issue_entries: list[tuple[str, str]] = []
    extension_fragments: list[tuple[object, ...]] = []
    try:
        for child in root:
            if _xml_local_name(child.tag) == "extLst":
                extension_fragments.append(_threaded_comment_person_fragment(child))
                continue
            if (
                _xml_namespace(child.tag) not in _THREADED_COMMENT_PERSON_NAMESPACES
                or _xml_local_name(child.tag) != "person"
            ):
                issue_entries.append(
                    ("unexpected-person-list-child", repr(_threaded_comment_person_fragment(child)))
                )
                continue
            identifier = child.get("id")
            if not identifier:
                issue_entries.append(("person-without-identifier", "present"))
            if not child.get("displayName"):
                issue_entries.append(("person-without-display-name", "present"))
            people.append(
                _ThreadedCommentPerson(
                    identifier=identifier,
                    fragment=_threaded_comment_person_fragment(child),
                )
            )
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested threaded-comment "
            "person record; affected comments were not compared."
        )
        return _ThreadedCommentPersonInspection(
            member=member,
            present=True,
            person_count=len(people),
            unrecognized_count=len(issue_entries) + 1,
            definition_signature=_private_payload_signature(payload),
        )

    definition_entries = [
        (f"person:{index}", repr(fragment))
        for index, fragment in enumerate(sorted((person.fragment for person in people), key=repr))
    ]
    definition_entries.extend(sorted(issue_entries))
    definition_entries.extend(
        (f"person-list-extension:{index}", repr(fragment))
        for index, fragment in enumerate(sorted(extension_fragments, key=repr))
    )
    if issue_entries:
        warnings.add(
            "FormulaFence found malformed or unsupported threaded-comment person metadata; "
            "affected comments have a coverage gap."
        )
    return _ThreadedCommentPersonInspection(
        member=member,
        present=True,
        person_count=len(people),
        people=tuple(people),
        unrecognized_count=len(issue_entries),
        definition_signature=_private_external_data_signature(tuple(definition_entries)),
    )


def _threaded_comment_person_tokens(
    inspections: list[_ThreadedCommentPersonInspection],
    warnings: set[str],
) -> tuple[dict[str, str], int, str | None]:
    """Resolve person references by private identity material, not GUIDs."""
    people_by_identifier: dict[str, list[_ThreadedCommentPerson]] = defaultdict(list)
    fragments: list[tuple[object, ...]] = []
    for inspection in inspections:
        for person in inspection.people:
            fragments.append(person.fragment)
            if person.identifier:
                people_by_identifier[person.identifier].append(person)

    tokens: dict[str, str] = {}
    duplicate_identifier_count = 0
    for identifier, people in people_by_identifier.items():
        if len(people) != 1:
            duplicate_identifier_count += 1
            continue
        tokens[identifier] = repr(people[0].fragment)
    if duplicate_identifier_count:
        warnings.add(
            "FormulaFence found duplicate threaded-comment person identifiers; "
            "affected comments have a coverage gap."
        )
    signature_entries = tuple(
        (f"person:{index}", repr(fragment))
        for index, fragment in enumerate(sorted(fragments, key=repr))
    )
    return (
        tokens,
        duplicate_identifier_count,
        _private_external_data_signature(signature_entries),
    )


def _threaded_comment_boolean(value: str | None) -> tuple[bool, bool]:
    """Read one ``done`` flag while accepting the normal OOXML spellings."""
    if value is None:
        return False, True
    if value.casefold() in {"1", "true"}:
        return True, True
    if value.casefold() in {"0", "false"}:
        return False, True
    return False, False


def _threaded_comment_xml_fragment(
    element: ElementTree.Element,
    person_tokens: Mapping[str, str],
) -> tuple[object, ...]:
    """Canonicalise a comment node while replacing volatile linkage IDs."""
    namespace = _xml_namespace(element.tag)
    local_name = _xml_local_name(element.tag)
    is_comment = namespace == _THREADED_COMMENT_NS and local_name == "threadedComment"
    is_mention = namespace == _THREADED_COMMENT_NS and local_name == "mention"
    attributes: list[tuple[str, object]] = []
    for attribute, value in element.attrib.items():
        attribute_name = _xml_local_name(attribute)
        if is_comment and attribute_name in {"id", "parentId", "done"}:
            continue
        if is_mention and attribute_name == "mentionId":
            continue
        if is_comment and attribute_name == "personId":
            attributes.append(
                (
                    _xml_display_name(attribute),
                    ("person", person_tokens.get(value, "unresolved-person")),
                )
            )
            continue
        if is_mention and attribute_name == "mentionpersonId":
            attributes.append(
                (
                    _xml_display_name(attribute),
                    ("person", person_tokens.get(value, "unresolved-person")),
                )
            )
            continue
        attributes.append((_xml_display_name(attribute), value))
    if is_comment:
        done, _valid = _threaded_comment_boolean(element.get("done"))
        attributes.append(("done", "true" if done else "false"))
    children = tuple(
        _threaded_comment_xml_fragment(child, person_tokens) for child in element
    )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes, key=repr)),
        text,
        children,
    )


def _threaded_comment_forest(
    entries: list[_ThreadedCommentRawEntry],
) -> tuple[tuple[tuple[object, ...], ...], tuple[tuple[object, ...], ...], list[str]]:
    """Build an ID-independent discussion forest from one comment part."""
    entries_by_identifier: dict[str, list[_ThreadedCommentRawEntry]] = defaultdict(list)
    for entry in entries:
        if entry.identifier:
            entries_by_identifier[entry.identifier].append(entry)

    unique_entries = {
        identifier: candidates[0]
        for identifier, candidates in entries_by_identifier.items()
        if len(candidates) == 1
    }
    issues: list[str] = [
        "duplicate-comment-identifier"
        for candidates in entries_by_identifier.values()
        if len(candidates) > 1
    ]
    children: dict[str, list[str]] = defaultdict(list)
    roots: list[str] = []
    invalid_fragments: list[tuple[object, ...]] = []
    for entry in entries:
        if not entry.identifier or entry.identifier not in unique_entries:
            invalid_fragments.append(entry.fragment)
            if not entry.identifier:
                issues.append("comment-without-identifier")
            continue
        if entry.parent_identifier is None:
            roots.append(entry.identifier)
            continue
        if (
            entry.parent_identifier == entry.identifier
            or entry.parent_identifier not in unique_entries
        ):
            invalid_fragments.append(entry.fragment)
            issues.append("unresolved-comment-parent")
            continue
        children[entry.parent_identifier].append(entry.identifier)

    visited: set[str] = set()

    def node_fragment(identifier: str, active: set[str]) -> tuple[object, ...]:
        if identifier in active:
            raise ValueError("cyclic-comment-parent")
        active.add(identifier)
        child_fragments = [
            node_fragment(child, active)
            for child in children.get(identifier, ())
        ]
        active.remove(identifier)
        visited.add(identifier)
        return (
            unique_entries[identifier].fragment,
            tuple(sorted(child_fragments, key=repr)),
        )

    forest: list[tuple[object, ...]] = []
    for identifier in roots:
        try:
            forest.append(node_fragment(identifier, set()))
        except ValueError:
            issues.append("cyclic-comment-parent")
    for identifier, entry in unique_entries.items():
        if identifier not in visited:
            invalid_fragments.append(entry.fragment)
            issues.append("disconnected-comment-graph")
    return (
        tuple(sorted(forest, key=repr)),
        tuple(sorted(invalid_fragments, key=repr)),
        issues,
    )


def _threaded_comment_part_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _ThreadedCommentBudget,
    person_tokens: Mapping[str, str],
) -> _ThreadedCommentPartInspection:
    """Inspect one worksheet threaded-comment part without rendering its content."""
    payload, fallback_signature = _threaded_comment_xml_payload(
        archive,
        member,
        warnings,
        budget,
        kind="threaded-comment",
    )
    if payload is None:
        return _ThreadedCommentPartInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a threaded-comment XML part "
            f"({type(error).__name__}); affected comments were not compared."
        )
        return _ThreadedCommentPartInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(root.tag) != _THREADED_COMMENT_NS
        or _xml_local_name(root.tag) != "ThreadedComments"
    ):
        warnings.add(
            "FormulaFence found a threaded-comment part with an unexpected root; "
            "affected comments were not compared."
        )
        return _ThreadedCommentPartInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    comment_tag = f"{{{_THREADED_COMMENT_NS}}}threadedComment"
    text_tag = f"{{{_THREADED_COMMENT_NS}}}text"
    mentions_tag = f"{{{_THREADED_COMMENT_NS}}}mentions"
    mention_tag = f"{{{_THREADED_COMMENT_NS}}}mention"
    entries: list[_ThreadedCommentRawEntry] = []
    root_fragments: list[tuple[object, ...]] = []
    referenced_person_ids: set[str] = set()
    mentioned_person_ids: set[str] = set()
    issue_entries: list[str] = []
    resolved_comment_count = 0
    comment_with_text_count = 0
    mention_count = 0
    reply_count = 0
    try:
        for child in root:
            if _xml_local_name(child.tag) == "extLst":
                root_fragments.append(_threaded_comment_xml_fragment(child, person_tokens))
                continue
            if child.tag != comment_tag:
                root_fragments.append(_threaded_comment_xml_fragment(child, person_tokens))
                issue_entries.append("unexpected-threaded-comment-root-child")
                continue

            identifier = child.get("id")
            parent_identifier = child.get("parentId")
            if not identifier:
                issue_entries.append("comment-without-identifier")
            if "parentId" in child.attrib and not parent_identifier:
                issue_entries.append("comment-with-empty-parent")
            if parent_identifier is not None:
                reply_count += 1
            person_identifier = child.get("personId")
            if not person_identifier:
                issue_entries.append("comment-without-person")
            else:
                referenced_person_ids.add(person_identifier)
                if person_identifier not in person_tokens:
                    issue_entries.append("comment-with-unresolved-person")
            done, valid_done = _threaded_comment_boolean(child.get("done"))
            if done:
                resolved_comment_count += 1
            if not valid_done:
                issue_entries.append("comment-with-invalid-resolution-state")
            text_children = [element for element in child if element.tag == text_tag]
            if text_children:
                comment_with_text_count += 1
            if len(text_children) > 1:
                issue_entries.append("comment-with-multiple-text-nodes")
            for element in child:
                if element.tag == text_tag or _xml_local_name(element.tag) == "extLst":
                    continue
                if element.tag != mentions_tag:
                    issue_entries.append("unexpected-comment-child")
                    continue
                for mention in element:
                    if mention.tag != mention_tag:
                        issue_entries.append("unexpected-mentions-child")
                        continue
                    mention_count += 1
                    mentioned_identifier = mention.get("mentionpersonId")
                    if not mentioned_identifier:
                        issue_entries.append("mention-without-person")
                        continue
                    if not mention.get("mentionId"):
                        issue_entries.append("mention-without-identifier")
                    if not mention.get("startIndex") or not mention.get("length"):
                        issue_entries.append("mention-without-text-range")
                    referenced_person_ids.add(mentioned_identifier)
                    mentioned_person_ids.add(mentioned_identifier)
                    if mentioned_identifier not in person_tokens:
                        issue_entries.append("mention-with-unresolved-person")

            entries.append(
                _ThreadedCommentRawEntry(
                    identifier=identifier,
                    parent_identifier=parent_identifier,
                    fragment=_threaded_comment_xml_fragment(child, person_tokens),
                )
            )
        forest, malformed_fragments, graph_issues = _threaded_comment_forest(entries)
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested threaded-comment "
            "record; affected comments were not compared."
        )
        return _ThreadedCommentPartInspection(
            member=member,
            present=True,
            comment_count=len(entries),
            reply_count=reply_count,
            resolved_comment_count=resolved_comment_count,
            comment_with_text_count=comment_with_text_count,
            mention_count=mention_count,
            referenced_person_ids=frozenset(referenced_person_ids),
            mentioned_person_ids=frozenset(mentioned_person_ids),
            unrecognized_count=len(issue_entries) + 1,
            definition_signature=_private_payload_signature(payload),
        )

    issue_entries.extend(graph_issues)
    definition_entries = [
        (f"thread:{index}", repr(fragment))
        for index, fragment in enumerate(forest)
    ]
    definition_entries.extend(
        (f"malformed:{index}", repr(fragment))
        for index, fragment in enumerate(malformed_fragments)
    )
    definition_entries.extend(
        (f"root-extension:{index}", repr(fragment))
        for index, fragment in enumerate(sorted(root_fragments, key=repr))
    )
    definition_entries.extend(
        (f"issue:{index}", issue)
        for index, issue in enumerate(sorted(issue_entries))
    )
    if issue_entries:
        warnings.add(
            "FormulaFence found malformed or unsupported threaded-comment metadata; "
            "affected comments have a coverage gap."
        )
    return _ThreadedCommentPartInspection(
        member=member,
        present=True,
        comment_thread_count=len(forest),
        comment_count=len(entries),
        reply_count=reply_count,
        resolved_comment_count=resolved_comment_count,
        comment_with_text_count=comment_with_text_count,
        mention_count=mention_count,
        referenced_person_ids=frozenset(referenced_person_ids),
        mentioned_person_ids=frozenset(mentioned_person_ids),
        unrecognized_count=len(issue_entries),
        definition_signature=_private_external_data_signature(tuple(definition_entries)),
    )


def _threaded_comment_metadata(path: Path) -> _ThreadedCommentMetadata:
    """Inspect modern comments before the workbook reader can omit them.

    The scan follows only package-declared worksheet and workbook relationships,
    never renders comment UI, resolves accounts, or follows any external target.
    Text, locations, timestamps, identities, and raw linkage IDs remain in
    private signatures only.
    """
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _sheet_xml_parts(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _ThreadedCommentMetadata(
                    ThreadedCommentSnapshot(
                        unrecognized_threaded_comment_count=1,
                        definition_signature=_private_external_data_signature(
                            (("sheet-part-scan-failure", type(error).__name__),)
                        ),
                    ),
                    (
                        "FormulaFence could not inspect worksheet OOXML relationships "
                        f"for threaded comments ({type(error).__name__}); affected "
                        "comments were not compared.",
                    ),
                )

            (
                threaded_members,
                person_members,
                content_types,
                package_issues,
            ) = _threaded_comment_package_members(archive, warnings)
            declaration_entries: list[tuple[str, str]] = []
            coverage_entries: list[tuple[str, str]] = list(package_issues)
            threaded_sources: dict[str, set[str]] = defaultdict(set)
            person_sources: set[str] = set()
            selected_relationships: list[tuple[str, _ThreadedCommentRawRelationship]] = []
            relationship_entries: list[tuple[str, str]] = []

            def inspect_binding_relationships(
                relationships: tuple[_ThreadedCommentRawRelationship, ...],
                *,
                label: str,
            ) -> None:
                expected_type = (
                    _THREADED_COMMENT_RELATIONSHIP
                    if label == "worksheet-threaded-comment"
                    else _THREADED_COMMENT_PERSON_RELATIONSHIP
                )
                matching_relationships = [
                    relationship
                    for relationship in relationships
                    if relationship.relationship_type.casefold() == expected_type.casefold()
                ]
                if not matching_relationships:
                    return
                identifiers: dict[str, int] = defaultdict(int)
                for relationship in relationships:
                    if relationship.relationship_id:
                        identifiers[relationship.relationship_id] += 1
                coverage_entries.extend(
                    (f"duplicate-{label}-relationship-id", "present")
                    for count in identifiers.values()
                    if count > 1
                )
                for relationship in matching_relationships:
                    selected_relationships.append((label, relationship))
                    if not relationship.relationship_id:
                        coverage_entries.append(
                            (f"{label}-relationship-without-id", "present")
                        )
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        coverage_entries.append(
                            (
                                f"unsafe-{label}-relationship",
                                repr(
                                    (
                                        relationship.relationship_type,
                                        relationship.target_mode,
                                        relationship.target,
                                    )
                                ),
                            )
                        )
                        relationship_entries.append(
                            (
                                label,
                                repr(
                                    (
                                        relationship.relationship_type,
                                        relationship.target_mode,
                                        relationship.target,
                                    )
                                ),
                            )
                        )
                        continue
                    if label == "worksheet-threaded-comment":
                        # The caller adds the source worksheet after this helper.
                        continue
                    person_sources.add(relationship.safe_target)

            for sheet, (member, sheet_kind) in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                if sheet_kind != "worksheet":
                    continue
                relationships = _threaded_comment_raw_relationships(
                    archive,
                    member,
                    warnings,
                    context="worksheet",
                )
                if relationships is None:
                    coverage_entries.append(
                        ("unreadable-worksheet-threaded-comment-relationships", member)
                    )
                    continue
                before_count = len(selected_relationships)
                inspect_binding_relationships(
                    relationships,
                    label="worksheet-threaded-comment",
                )
                for _label, relationship in selected_relationships[before_count:]:
                    if (
                        relationship.target_mode.casefold() == "internal"
                        and relationship.safe_target is not None
                    ):
                        threaded_sources[relationship.safe_target].add(sheet)

            workbook_relationships = _threaded_comment_raw_relationships(
                archive,
                "xl/workbook.xml",
                warnings,
                context="workbook",
            )
            if workbook_relationships is None:
                coverage_entries.append(
                    ("unreadable-workbook-threaded-comment-relationships", "present")
                )
            else:
                inspect_binding_relationships(
                    workbook_relationships,
                    label="threaded-comment-person",
                )

            threaded_members.update(threaded_sources)
            person_members.update(person_sources)
            budget = _ThreadedCommentBudget()
            person_inspections = [
                _threaded_comment_person_inspection(
                    archive,
                    member,
                    warnings,
                    budget,
                )
                for member in sorted(person_members, key=str.casefold)
            ]
            person_tokens, duplicate_person_count, person_definition_signature = (
                _threaded_comment_person_tokens(person_inspections, warnings)
            )
            threaded_inspections = [
                _threaded_comment_part_inspection(
                    archive,
                    member,
                    warnings,
                    budget,
                    person_tokens,
                )
                for member in sorted(threaded_members, key=str.casefold)
            ]

            for inspection in threaded_inspections:
                sources = tuple(
                    sorted(
                        threaded_sources.get(inspection.member, ()),
                        key=str.casefold,
                    )
                )
                content_status = _threaded_comment_content_type_status(
                    inspection.member,
                    content_types,
                    _THREADED_COMMENT_CONTENT_TYPE,
                )
                declaration_entries.append(
                    (
                        "threaded-comment-binding",
                        repr((sources, content_status)),
                    )
                )
                if not sources:
                    coverage_entries.append(
                        ("unbound-threaded-comment-part", content_status)
                    )
                if content_status == "mismatched":
                    coverage_entries.append(
                        ("mismatched-threaded-comment-content-type", "present")
                    )

            for inspection in person_inspections:
                content_status = _threaded_comment_content_type_status(
                    inspection.member,
                    content_types,
                    _THREADED_COMMENT_PERSON_CONTENT_TYPE,
                )
                declaration_entries.append(
                    ("threaded-comment-person-binding", content_status)
                )
                if inspection.member not in person_sources:
                    coverage_entries.append(
                        ("unbound-threaded-comment-person-part", content_status)
                    )
                if content_status == "mismatched":
                    coverage_entries.append(
                        ("mismatched-threaded-comment-person-content-type", "present")
                    )

            referenced_person_ids = set().union(
                *(inspection.referenced_person_ids for inspection in threaded_inspections)
            ) if threaded_inspections else set()
            mentioned_person_ids = set().union(
                *(inspection.mentioned_person_ids for inspection in threaded_inspections)
            ) if threaded_inspections else set()
            all_people = [
                person
                for inspection in person_inspections
                for person in inspection.people
            ]
            orphan_person_count = sum(
                bool(person.identifier and person.identifier not in referenced_person_ids)
                for person in all_people
            )

            definition_entries = [
                (
                    "threaded-comment-part",
                    repr(
                        (
                            tuple(
                                sorted(
                                    threaded_sources.get(inspection.member, ()),
                                    key=str.casefold,
                                )
                            ),
                            _threaded_comment_content_type_status(
                                inspection.member,
                                content_types,
                                _THREADED_COMMENT_CONTENT_TYPE,
                            ),
                            inspection.definition_signature,
                        )
                    ),
                )
                for inspection in threaded_inspections
            ]
            definition_entries.sort(key=lambda entry: entry[1])
            person_entries = [
                (
                    "threaded-comment-person-part",
                    repr(
                        (
                            _threaded_comment_content_type_status(
                                inspection.member,
                                content_types,
                                _THREADED_COMMENT_PERSON_CONTENT_TYPE,
                            ),
                            inspection.definition_signature,
                        )
                    ),
                )
                for inspection in person_inspections
            ]
            person_entries.sort(key=lambda entry: entry[1])
            if person_definition_signature is not None:
                person_entries.append(
                    ("threaded-comment-person-definitions", person_definition_signature)
                )

            if duplicate_person_count:
                coverage_entries.extend(
                    ("duplicate-threaded-comment-person-identifier", "present")
                    for _ in range(duplicate_person_count)
                )
            if coverage_entries:
                warnings.add(
                    "FormulaFence found malformed, unbound, or unsupported threaded-comment "
                    "metadata; affected comments have a coverage gap."
                )

            worksheet_sheets = {
                sheet
                for sources in threaded_sources.values()
                for sheet in sources
            }
            snapshot = ThreadedCommentSnapshot(
                worksheet_threaded_comment_sheet_count=len(worksheet_sheets),
                threaded_comment_part_count=len(threaded_inspections),
                comment_thread_count=sum(
                    inspection.comment_thread_count for inspection in threaded_inspections
                ),
                comment_count=sum(
                    inspection.comment_count for inspection in threaded_inspections
                ),
                reply_count=sum(inspection.reply_count for inspection in threaded_inspections),
                resolved_comment_count=sum(
                    inspection.resolved_comment_count for inspection in threaded_inspections
                ),
                comment_with_text_count=sum(
                    inspection.comment_with_text_count for inspection in threaded_inspections
                ),
                mention_count=sum(inspection.mention_count for inspection in threaded_inspections),
                mentioned_person_count=len(mentioned_person_ids),
                person_part_count=len(person_inspections),
                person_count=sum(inspection.person_count for inspection in person_inspections),
                orphan_person_count=orphan_person_count,
                binding_relationship_count=len(selected_relationships),
                external_relationship_count=sum(
                    relationship.target_mode.casefold() != "internal"
                    for _label, relationship in selected_relationships
                ),
                unrecognized_threaded_comment_count=(
                    len(coverage_entries)
                    + sum(inspection.unrecognized_count for inspection in threaded_inspections)
                    + sum(inspection.unrecognized_count for inspection in person_inspections)
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(sorted([*declaration_entries, *coverage_entries]))
                ),
                definition_signature=_private_external_data_signature(
                    tuple(definition_entries)
                ),
                person_signature=_private_external_data_signature(tuple(person_entries)),
                relationship_signature=_private_external_data_signature(
                    tuple(sorted(relationship_entries))
                ),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _ThreadedCommentMetadata(
            ThreadedCommentSnapshot(
                unrecognized_threaded_comment_count=1,
                definition_signature=_private_external_data_signature(
                    (("threaded-comment-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect threaded-comment OOXML "
                f"({type(error).__name__}); affected comments were not compared.",
            ),
        )
    return _ThreadedCommentMetadata(snapshot, tuple(sorted(warnings)))


_WORKSHEET_DRAWING_SHAPE_ANCHORS = frozenset(
    {"twoCellAnchor", "oneCellAnchor", "absoluteAnchor"}
)
_WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES = frozenset(
    {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
)
_WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES = frozenset(
    {_DRAWINGML_MAIN_NS, _DRAWINGML_STRICT_MAIN_NS}
)
_WORKSHEET_DRAWING_SHAPE_ANCHOR_CHILDREN = frozenset(
    {
        "from",
        "to",
        "pos",
        "ext",
        "sp",
        "cxnSp",
        "graphicFrame",
        "grpSp",
        "clientData",
    }
)
_WORKSHEET_DRAWING_GROUP_CHILDREN = frozenset(
    {"nvGrpSpPr", "grpSpPr", "sp", "cxnSp", "graphicFrame", "grpSp"}
)
_WORKSHEET_DRAWING_SHAPE_CONTAINER_NAMES = frozenset(
    {"sp", "cxnSp", "graphicFrame", "grpSp"}
)
_WORKSHEET_DRAWING_CONNECTOR_ENDPOINT_NAMES = frozenset({"stCxn", "endCxn"})
_WORKSHEET_DRAWING_CONTAINER_NONVISUAL_NAMES = {
    "sp": "nvSpPr",
    "cxnSp": "nvCxnSpPr",
    "graphicFrame": "nvGraphicFramePr",
    "grpSp": "nvGrpSpPr",
}
_WORKSHEET_DRAWING_GRAPHIC_DATA_CHART_URIS = frozenset(
    {_DRAWINGML_CHART_NS, _DRAWINGML_STRICT_CHART_NS}
)
_WORKSHEET_DRAWING_GRAPHIC_DATA_CHART_EX_URIS = frozenset(
    {_DRAWINGML_CHART_EX_NS}
)
_WORKSHEET_DRAWING_GRAPHIC_DATA_DIAGRAM_URIS = frozenset(
    {_DRAWINGML_DIAGRAM_NS, _DRAWINGML_STRICT_DIAGRAM_NS}
)
_WORKSHEET_DRAWING_GRAPHIC_DATA_WEB_EXTENSION_URIS = frozenset({_WEB_EXTENSION_NS})
_WORKSHEET_DRAWING_DIAGRAM_COMPONENT_ROOTS = {
    "data": frozenset(
        (namespace, "dataModel")
        for namespace in _WORKSHEET_DRAWING_GRAPHIC_DATA_DIAGRAM_URIS
    ),
    "layout": frozenset(
        (namespace, "layoutDef")
        for namespace in _WORKSHEET_DRAWING_GRAPHIC_DATA_DIAGRAM_URIS
    ),
    "quick-style": frozenset(
        (namespace, "styleDef")
        for namespace in _WORKSHEET_DRAWING_GRAPHIC_DATA_DIAGRAM_URIS
    ),
    "colours": frozenset(
        (namespace, "colorsDef")
        for namespace in _WORKSHEET_DRAWING_GRAPHIC_DATA_DIAGRAM_URIS
    ),
    "drawing": frozenset({(_DRAWINGML_DIAGRAM_DRAWING_NS, "drawing")}),
}


def _worksheet_drawing_shape_graphic_frame_kind(
    frame: ElementTree.Element,
) -> str | None:
    """Classify one non-visual graphic frame without inspecting its payload."""
    if (
        _xml_namespace(frame.tag) not in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
        or _xml_local_name(frame.tag) != "graphicFrame"
    ):
        return None
    graphics = [
        child
        for child in frame
        if (
            _xml_namespace(child.tag) in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
            and _xml_local_name(child.tag) == "graphic"
        )
    ]
    if len(graphics) != 1:
        return None
    graphic_data = [
        child
        for child in graphics[0]
        if (
            _xml_namespace(child.tag) in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
            and _xml_local_name(child.tag) == "graphicData"
        )
    ]
    if len(graphic_data) != 1:
        return None
    uri = graphic_data[0].get("uri")
    if uri in _WORKSHEET_DRAWING_GRAPHIC_DATA_CHART_URIS:
        return "chart"
    if uri in _WORKSHEET_DRAWING_GRAPHIC_DATA_CHART_EX_URIS:
        return "chart-ex"
    if uri in _WORKSHEET_DRAWING_GRAPHIC_DATA_DIAGRAM_URIS:
        return "diagram"
    if uri in _WORKSHEET_DRAWING_GRAPHIC_DATA_WEB_EXTENSION_URIS:
        return "web-extension"
    return "other" if uri else None


def _worksheet_drawing_shape_supported_container(
    element: ElementTree.Element,
) -> bool:
    """Return whether a drawing object belongs to this non-chart boundary."""
    if _xml_namespace(element.tag) not in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES:
        return False
    local_name = _xml_local_name(element.tag)
    if local_name not in _WORKSHEET_DRAWING_SHAPE_CONTAINER_NAMES:
        return False
    return (
        local_name != "graphicFrame"
        or _worksheet_drawing_shape_graphic_frame_kind(element)
        not in {"chart", "chart-ex", "web-extension"}
    )


def _worksheet_drawing_shape_is_chart_ex_alternate_content(
    element: ElementTree.Element,
) -> bool:
    """Return whether a markup-compatibility branch hosts a recognized ChartEx frame.

    Excel writes modern charts inside ``mc:AlternateContent`` with a regular
    shape fallback for older clients.  The chart scanner follows the ChartEx
    branch directly; treating both branches as ordinary worksheet shapes would
    double count it and leave a healthy chart looking like an unanchored shape.
    """
    return (
        _xml_namespace(element.tag) == _MARKUP_COMPATIBILITY_NS
        and _xml_local_name(element.tag) == "AlternateContent"
        and any(
            _worksheet_drawing_shape_graphic_frame_kind(child) == "chart-ex"
            for child in element.iter()
        )
    )


def _worksheet_drawing_shape_is_in_content_web_extension_alternate_content(
    element: ElementTree.Element,
) -> bool:
    """Return whether a markup-compatibility branch hosts an add-in frame.

    In-content Office Web Add-ins use a DrawingML graphic frame in the active
    ``mc:Choice`` branch and commonly carry a native-picture fallback.  The
    Office Web Add-in scanner owns the active frame while the worksheet-image
    scanner owns that fallback; the ordinary shape scanner must not count
    either as a generic graphic-frame control.
    """
    return (
        _xml_namespace(element.tag) == _MARKUP_COMPATIBILITY_NS
        and _xml_local_name(element.tag) == "AlternateContent"
        and any(
            _worksheet_drawing_shape_graphic_frame_kind(descendant) == "web-extension"
            for child in element
            if not (
                _xml_namespace(child.tag) == _MARKUP_COMPATIBILITY_NS
                and _xml_local_name(child.tag) == "Fallback"
            )
            for descendant in child.iter()
        )
    )


def _worksheet_drawing_shape_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    *,
    context: str,
) -> tuple[_WorksheetDrawingShapeRawRelationship, ...] | None:
    """Read DrawingML shape relationships without following their targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        root = _xml_root(archive, relationship_member)
    except KeyError:
        return ()
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for Worksheet DrawingML shape inspection "
            f"({type(error).__name__}); affected shapes were not compared."
        )
        return None
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting Worksheet DrawingML shapes; "
            "affected shapes were not compared."
        )
        return None

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_WorksheetDrawingShapeRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _WorksheetDrawingShapeRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting Worksheet "
            "DrawingML shapes; affected shapes may be incomplete."
        )
        return None
    return tuple(relationships)


def _worksheet_drawing_shape_relationship_signature(
    relationships: tuple[_WorksheetDrawingShapeRawRelationship, ...],
) -> str | None:
    """Fingerprint selected relationship semantics without identifier churn."""
    material = sorted(relationship.semantic_key() for relationship in relationships)
    return _private_external_data_signature(
        tuple(
            (f"relationship:{index}", repr(relationship))
            for index, relationship in enumerate(material)
        )
    )


def _worksheet_drawing_shape_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetDrawingShapeBudget,
) -> tuple[bytes | None, str | None]:
    """Read one bounded worksheet DrawingML XML part without following targets."""
    if budget.remaining_parts == 0:
        warnings.add(
            "FormulaFence reached its bounded Worksheet DrawingML shape XML part count "
            "budget; affected shapes have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("part-count-budget-exhausted", member),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a Worksheet DrawingML shape XML part; "
            "affected shapes were not compared."
        )
        return None, _private_external_data_signature((("missing-member", member),))
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _WORKSHEET_DRAWING_SHAPE_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized Worksheet DrawingML shape "
            "XML part; affected shapes have a coverage gap."
        )
        return None, _private_external_data_signature((("oversized-part", metadata),))
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded Worksheet DrawingML shape XML read "
            "budget; affected shapes have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("read-budget-exhausted", metadata),)
        )
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a Worksheet DrawingML shape XML package part "
            f"({type(error).__name__}); affected shapes were not compared."
        )
        return None, _private_external_data_signature((("unreadable-part", metadata),))


def _worksheet_drawing_shape_related_payloads(
    archive: ZipFile,
    members: set[str],
    unresolved_entries: list[tuple[str, str]],
    warnings: set[str],
    budget: _WorksheetDrawingShapeRelatedPartBudget,
) -> _WorksheetDrawingShapeRelatedPartPayloadInspection:
    """Fingerprint direct SmartArt Diagram Data images without decoding them."""
    entries = list(unresolved_entries)
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts <= 0:
            warnings.add(
                "FormulaFence reached its bounded SmartArt Diagram Data image part "
                "count budget; affected diagram controls have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate a SmartArt Diagram Data image part; "
                "affected diagram controls were not compared."
            )
            entries.append(("missing-image-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _WORKSHEET_DRAWING_SHAPE_RELATED_PART_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized SmartArt Diagram Data "
                "image; affected diagram controls have a coverage gap."
            )
            entries.append(("oversized-image-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded SmartArt Diagram Data image read "
                "budget; affected diagram controls have a coverage gap."
            )
            entries.append(("image-read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as payload:
                while chunk := payload.read(
                    _WORKSHEET_DRAWING_SHAPE_RELATED_PART_HASH_CHUNK_BYTES
                ):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("payload exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("payload did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint a SmartArt Diagram Data image "
                f"({type(error).__name__}); affected diagram controls were not compared."
            )
            entries.append(("unreadable-image-part", metadata))
            uninspected_part_count += 1
            continue
        entries.append(("image-payload", repr((member, digest.hexdigest()))))
        fingerprinted_part_count += 1

    entries.sort()
    return _WorksheetDrawingShapeRelatedPartPayloadInspection(
        image_part_count=len(members) + len(unresolved_entries),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_signature=(
            _private_external_data_signature(tuple(entries)) if entries else None
        ),
    )


def _worksheet_drawing_shape_xml_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    connection_targets: Mapping[str, tuple[object, ...]],
) -> tuple[object, ...]:
    """Canonicalize private shape XML while resolving private object identifiers."""
    namespace = _xml_namespace(element.tag)
    local_name = _xml_local_name(element.tag)
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if (
            namespace in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
            and local_name == "cNvPr"
            and _xml_local_name(attribute) == "id"
        ):
            continue
        if attribute in (
            _WORKSHEET_DRAWING_SHAPE_RELATIONSHIP_ATTRIBUTES
            | _WORKSHEET_DRAWING_SHAPE_DIAGRAM_RELATIONSHIP_ATTRIBUTES
        ):
            relationship = relationship_semantics.get(value)
            resolved: object = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if (
            namespace in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
            and local_name in _WORKSHEET_DRAWING_CONNECTOR_ENDPOINT_NAMES
            and _xml_local_name(attribute) == "id"
        ):
            target = connection_targets.get(value)
            resolved = (
                ("connection-target", target)
                if target is not None
                else ("unresolved-connection-target",)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if (
            namespace in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
            and local_name == "srgbClr"
            and _xml_local_name(attribute) == "val"
        ):
            value = value.upper()
        attributes.append((_xml_display_name(attribute), value))

    if (
        namespace in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
        and local_name == "grpSp"
    ):
        children = tuple(
            _worksheet_drawing_shape_xml_fragment(
                child,
                relationship_semantics,
                connection_targets,
            )
            for child in element
            if (
                _xml_namespace(child.tag) in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
                and _xml_local_name(child.tag) in _WORKSHEET_DRAWING_GROUP_CHILDREN
                and (
                    _xml_local_name(child.tag) != "graphicFrame"
                    or _worksheet_drawing_shape_graphic_frame_kind(child)
                    not in {"chart", "chart-ex", "web-extension"}
                )
            )
        )
    else:
        children = tuple(
            _worksheet_drawing_shape_xml_fragment(
                child,
                relationship_semantics,
                connection_targets,
            )
            for child in element
        )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _worksheet_drawing_shape_anchor_fragment(
    anchor: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
    connection_targets: Mapping[str, tuple[object, ...]],
) -> tuple[object, ...]:
    """Retain anchors and supported drawing objects without charts or pictures."""
    attributes = tuple(
        sorted(
            (_xml_display_name(attribute), value)
            for attribute, value in anchor.attrib.items()
        )
    )
    children = tuple(
        _worksheet_drawing_shape_xml_fragment(
            child,
            relationship_semantics,
            connection_targets,
        )
        for child in anchor
        if (
            _xml_namespace(child.tag) in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
            and _xml_local_name(child.tag) in _WORKSHEET_DRAWING_SHAPE_ANCHOR_CHILDREN
            and (
                _xml_local_name(child.tag) != "graphicFrame"
                or _worksheet_drawing_shape_graphic_frame_kind(child)
                not in {"chart", "chart-ex", "web-extension"}
            )
        )
    )
    return (_xml_display_name(anchor.tag), attributes, children)


def _worksheet_drawing_shape_containers(
    anchor: ElementTree.Element,
) -> tuple[ElementTree.Element, ...]:
    """Return supported anchored containers without entering charts or pictures."""
    containers: list[ElementTree.Element] = []

    def visit(element: ElementTree.Element) -> None:
        if not _worksheet_drawing_shape_supported_container(element):
            return
        local_name = _xml_local_name(element.tag)
        containers.append(element)
        if local_name == "grpSp":
            for child in element:
                visit(child)

    for child in anchor:
        visit(child)
    return tuple(containers)


def _worksheet_drawing_shape_container_identifier(
    container: ElementTree.Element,
) -> str | None:
    """Return a supported drawing object's non-visual identifier, if usable."""
    namespace = _xml_namespace(container.tag)
    local_name = _xml_local_name(container.tag)
    nonvisual_name = _WORKSHEET_DRAWING_CONTAINER_NONVISUAL_NAMES.get(local_name)
    if (
        namespace not in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
        or nonvisual_name is None
    ):
        return None
    nonvisual = [
        child
        for child in container
        if (
            _xml_namespace(child.tag) == namespace
            and _xml_local_name(child.tag) == nonvisual_name
        )
    ]
    if len(nonvisual) != 1:
        return None
    nonvisual_properties = [
        child
        for child in nonvisual[0]
        if (
            _xml_namespace(child.tag) == namespace
            and _xml_local_name(child.tag) == "cNvPr"
        )
    ]
    if len(nonvisual_properties) != 1:
        return None
    identifier = nonvisual_properties[0].get("id")
    if not identifier or not identifier.isascii() or not identifier.isdecimal():
        return None
    return identifier


def _worksheet_drawing_shape_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetDrawingShapeBudget,
) -> _WorksheetDrawingShapeInspection:
    """Inspect non-chart shape controls in one worksheet DrawingML part."""
    payload, fallback_signature = _worksheet_drawing_shape_xml_payload(
        archive,
        member,
        warnings,
        budget,
    )
    if payload is None:
        return _WorksheetDrawingShapeInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a Worksheet DrawingML shape XML part "
            f"({type(error).__name__}); affected shapes were not compared."
        )
        return _WorksheetDrawingShapeInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(root.tag) not in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
        or _xml_local_name(root.tag) != "wsDr"
    ):
        warnings.add(
            "FormulaFence found a Worksheet DrawingML shape part with an unexpected "
            "root; affected shapes were not compared."
        )
        return _WorksheetDrawingShapeInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    anchors: list[tuple[ElementTree.Element, tuple[ElementTree.Element, ...]]] = []
    for child in root:
        if (
            _xml_namespace(child.tag)
            not in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
            or _xml_local_name(child.tag) not in _WORKSHEET_DRAWING_SHAPE_ANCHORS
        ):
            continue
        containers = _worksheet_drawing_shape_containers(child)
        if containers:
            anchors.append((child, containers))

    all_container_nodes: list[ElementTree.Element] = []

    def visit_container_nodes(element: ElementTree.Element) -> None:
        if (
            _worksheet_drawing_shape_is_chart_ex_alternate_content(element)
            or _worksheet_drawing_shape_is_in_content_web_extension_alternate_content(
                element
            )
        ):
            # Retain any unexpected control in the active Choice branch as an
            # unanchored coverage warning, but do not treat Excel's legacy
            # fallback shape as a second live worksheet control.
            for child in element:
                if (
                    _xml_namespace(child.tag) == _MARKUP_COMPATIBILITY_NS
                    and _xml_local_name(child.tag) == "Fallback"
                ):
                    continue
                visit_container_nodes(child)
            return
        if _worksheet_drawing_shape_supported_container(element):
            all_container_nodes.append(element)
        for child in element:
            visit_container_nodes(child)

    visit_container_nodes(root)
    selected_container_ids = {
        id(container)
        for _anchor, containers in anchors
        for container in containers
    }
    issue_entries: list[tuple[str, str]] = []
    unrecognized_count = 0
    unanchored_container_count = sum(
        id(container) not in selected_container_ids for container in all_container_nodes
    )
    if unanchored_container_count:
        warnings.add(
            "FormulaFence found Worksheet DrawingML objects outside supported anchors; "
            "affected shape and connector controls have a coverage gap."
        )
        unrecognized_count += unanchored_container_count
        issue_entries.append(
            ("unanchored-drawing-object-count", str(unanchored_container_count))
        )

    container_records = [
        (anchor_index, container_index, container)
        for anchor_index, (_anchor, containers) in enumerate(anchors)
        for container_index, container in enumerate(containers)
    ]
    shape_nodes = [
        container
        for _anchor_index, _container_index, container in container_records
        if _xml_local_name(container.tag) == "sp"
    ]
    connector_nodes = [
        container
        for _anchor_index, _container_index, container in container_records
        if _xml_local_name(container.tag) == "cxnSp"
    ]
    group_shape_count = sum(
        _xml_local_name(container.tag) == "grpSp"
        for _anchor_index, _container_index, container in container_records
    )
    graphic_frame_nodes = [
        container
        for _anchor_index, _container_index, container in container_records
        if _xml_local_name(container.tag) == "graphicFrame"
    ]
    diagram_graphic_frame_nodes = [
        frame
        for frame in graphic_frame_nodes
        if _worksheet_drawing_shape_graphic_frame_kind(frame) == "diagram"
    ]
    unrecognized_graphic_frame_count = sum(
        _worksheet_drawing_shape_graphic_frame_kind(frame) != "diagram"
        for frame in graphic_frame_nodes
    )
    if unrecognized_graphic_frame_count:
        warnings.add(
            "FormulaFence found unsupported non-chart Worksheet DrawingML graphic "
            "frames; affected graphic-frame controls have a coverage gap."
        )
        unrecognized_count += unrecognized_graphic_frame_count
        issue_entries.append(
            (
                "unsupported-graphic-frame-count",
                str(unrecognized_graphic_frame_count),
            )
        )

    connection_target_candidates: dict[str, list[tuple[object, ...]]] = defaultdict(
        list
    )
    for anchor_index, container_index, container in container_records:
        if identifier := _worksheet_drawing_shape_container_identifier(container):
            connection_target_candidates[identifier].append(
                (
                    "drawing-object",
                    anchor_index,
                    container_index,
                    _xml_local_name(container.tag),
                )
            )
    connection_targets = {
        identifier: candidates[0]
        for identifier, candidates in connection_target_candidates.items()
        if len(candidates) == 1
    }

    connector_attachment_count = 0
    for connector_index, connector in enumerate(connector_nodes):
        connector_namespace = _xml_namespace(connector.tag)
        connector_issue = False
        nonvisual = [
            child
            for child in connector
            if (
                _xml_namespace(child.tag) == connector_namespace
                and _xml_local_name(child.tag) == "nvCxnSpPr"
            )
        ]
        if len(nonvisual) != 1:
            connector_issue = True
            issue_entries.append(
                ("connector-nonvisual-properties", str(connector_index))
            )
            connection_properties: ElementTree.Element | None = None
        else:
            nonvisual_properties = [
                child
                for child in nonvisual[0]
                if (
                    _xml_namespace(child.tag) == connector_namespace
                    and _xml_local_name(child.tag) == "cNvPr"
                )
            ]
            if (
                len(nonvisual_properties) != 1
                or not _worksheet_drawing_shape_container_identifier(connector)
            ):
                connector_issue = True
                issue_entries.append(
                    ("connector-nonvisual-identifier", str(connector_index))
                )
            connection_properties_candidates = [
                child
                for child in nonvisual[0]
                if (
                    _xml_namespace(child.tag) == connector_namespace
                    and _xml_local_name(child.tag) == "cNvCxnSpPr"
                )
            ]
            if len(connection_properties_candidates) != 1:
                connector_issue = True
                issue_entries.append(
                    ("connector-connection-properties", str(connector_index))
                )
                connection_properties = None
            else:
                connection_properties = connection_properties_candidates[0]

        if connection_properties is not None:
            for endpoint_name in _WORKSHEET_DRAWING_CONNECTOR_ENDPOINT_NAMES:
                endpoints = [
                    child
                    for child in connection_properties
                    if _xml_local_name(child.tag) == endpoint_name
                ]
                if not endpoints:
                    continue
                if (
                    len(endpoints) != 1
                    or _xml_namespace(endpoints[0].tag)
                    not in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
                ):
                    connector_issue = True
                    issue_entries.append(
                        (
                            "connector-malformed-attachment",
                            repr((connector_index, endpoint_name)),
                        )
                    )
                    continue
                endpoint = endpoints[0]
                target_identifier = endpoint.get("id")
                connection_site = endpoint.get("idx")
                if (
                    not target_identifier
                    or not connection_site
                    or not target_identifier.isascii()
                    or not target_identifier.isdecimal()
                    or not connection_site.isascii()
                    or not connection_site.isdecimal()
                ):
                    connector_issue = True
                    issue_entries.append(
                        (
                            "connector-invalid-attachment",
                            repr((connector_index, endpoint_name)),
                        )
                    )
                    continue
                candidates = connection_target_candidates.get(target_identifier, [])
                if len(candidates) != 1:
                    connector_issue = True
                    issue_entries.append(
                        (
                            "connector-unresolved-attachment",
                            repr(
                                (
                                    connector_index,
                                    endpoint_name,
                                    target_identifier,
                                )
                            ),
                        )
                    )
                    continue
                connector_attachment_count += 1
        if connector_issue:
            unrecognized_count += 1

    relationship_ids: set[str] = set()
    hyperlink_count = 0
    text_shape_count = 0
    text_paragraph_count = 0
    text_run_count = 0
    for shape in shape_nodes:
        text_bodies = [
            element
            for element in shape.iter()
            if (
                _xml_namespace(element.tag)
                in _WORKSHEET_DRAWING_SHAPE_DRAWING_NAMESPACES
                and _xml_local_name(element.tag) == "txBody"
            )
        ]
        if text_bodies:
            text_shape_count += 1
        for text_body in text_bodies:
            text_paragraph_count += sum(
                _xml_namespace(child.tag) in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
                and _xml_local_name(child.tag) == "p"
                for child in text_body.iter()
            )
            text_run_count += sum(
                _xml_namespace(child.tag) in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
                and _xml_local_name(child.tag) in {"r", "fld"}
                for child in text_body.iter()
            )
    for drawing_object in [*shape_nodes, *connector_nodes, *graphic_frame_nodes]:
        for element in drawing_object.iter():
            if (
                _xml_namespace(element.tag) in _WORKSHEET_DRAWING_SHAPE_MAIN_NAMESPACES
                and _xml_local_name(element.tag) in {"hlinkClick", "hlinkHover"}
            ):
                hyperlink_count += 1
            for attribute, value in element.attrib.items():
                if (
                    attribute
                    in (
                        _WORKSHEET_DRAWING_SHAPE_RELATIONSHIP_ATTRIBUTES
                        | _WORKSHEET_DRAWING_SHAPE_DIAGRAM_RELATIONSHIP_ATTRIBUTES
                    )
                    and value
                ):
                    relationship_ids.add(value)

    relationship_semantics: dict[str, tuple[str, str, str]] = {}
    selected_relationships: list[_WorksheetDrawingShapeRawRelationship] = []
    relationships: tuple[_WorksheetDrawingShapeRawRelationship, ...] | None = ()
    relationships_by_id: dict[
        str,
        list[_WorksheetDrawingShapeRawRelationship],
    ] = defaultdict(list)
    if relationship_ids or diagram_graphic_frame_nodes:
        relationships = _worksheet_drawing_shape_raw_relationships(
            archive,
            member,
            warnings,
            context="Worksheet DrawingML",
        )
        if relationships is not None:
            for relationship in relationships:
                if relationship.relationship_id:
                    relationships_by_id[relationship.relationship_id].append(
                        relationship
                    )
        else:
            unrecognized_count += 1
            issue_entries.append(("unreadable-relationships", member))
        for relationship_id in sorted(relationship_ids):
            matches = relationships_by_id.get(relationship_id, [])
            if not matches:
                warnings.add(
                    "FormulaFence found a Worksheet DrawingML shape relationship "
                    "reference without a matching relationship; affected shape controls "
                    "have a coverage gap."
                )
                unrecognized_count += 1
                issue_entries.append(
                    ("missing-shape-relationship", relationship_id)
                )
                continue
            matches.sort(key=lambda relationship: relationship.semantic_key())
            if len(matches) > 1:
                warnings.add(
                    "FormulaFence found duplicate Worksheet DrawingML shape relationship "
                    "ids; affected shape controls have a coverage gap."
                )
                unrecognized_count += 1
                issue_entries.append(
                    (
                        "duplicate-shape-relationship",
                        repr(
                            (
                                relationship_id,
                                tuple(
                                    relationship.semantic_key()
                                    for relationship in matches
                                ),
                            )
                        ),
                    )
                )
            relationship = matches[0]
            relationship_semantics[relationship_id] = relationship.semantic_key()
            selected_relationships.append(relationship)

    diagram_members_by_kind: dict[str, set[str]] = defaultdict(set)
    diagram_signature_entries: list[tuple[str, str]] = []
    diagram_image_members: set[str] = set()
    unresolved_diagram_image_entries: list[tuple[str, str]] = []
    if diagram_graphic_frame_nodes:
        expected_component_kinds = {
            "dm": "data",
            "lo": "layout",
            "qs": "quick-style",
            "cs": "colours",
        }
        if relationships is None:
            warnings.add(
                "FormulaFence could not inspect Worksheet DrawingML diagram "
                "relationships; affected SmartArt controls were not compared."
            )
            unrecognized_count += 1
            issue_entries.append(("unreadable-diagram-relationships", member))
        else:
            for frame_index, frame in enumerate(diagram_graphic_frame_nodes):
                relationship_nodes = [
                    element
                    for element in frame.iter()
                    if (
                        _xml_namespace(element.tag)
                        in {_DRAWINGML_DIAGRAM_NS, _DRAWINGML_STRICT_DIAGRAM_NS}
                        and _xml_local_name(element.tag) == "relIds"
                    )
                ]
                if len(relationship_nodes) != 1:
                    warnings.add(
                        "FormulaFence found a Worksheet DrawingML SmartArt frame without "
                        "one diagram relationship declaration; affected diagram controls "
                        "have a coverage gap."
                    )
                    unrecognized_count += 1
                    issue_entries.append(
                        ("diagram-relationship-declaration", str(frame_index))
                    )
                    continue
                relationship_node = relationship_nodes[0]
                for attribute_name, expected_kind in expected_component_kinds.items():
                    relationship_ids_for_component = [
                        value
                        for attribute, value in relationship_node.attrib.items()
                        if (
                            _xml_namespace(attribute)
                            in {
                                _DOCUMENT_RELATIONSHIP_NS,
                                _STRICT_DOCUMENT_RELATIONSHIP_NS,
                            }
                            and _xml_local_name(attribute) == attribute_name
                        )
                    ]
                    if len(relationship_ids_for_component) != 1:
                        warnings.add(
                            "FormulaFence found a Worksheet DrawingML SmartArt frame with "
                            "an incomplete diagram relationship declaration; affected diagram "
                            "controls have a coverage gap."
                        )
                        unrecognized_count += 1
                        issue_entries.append(
                            (
                                "diagram-component-relationship",
                                repr((frame_index, attribute_name)),
                            )
                        )
                        continue
                    relationship_id = relationship_ids_for_component[0]
                    matches = relationships_by_id.get(relationship_id, [])
                    if len(matches) != 1:
                        warnings.add(
                            "FormulaFence found a Worksheet DrawingML SmartArt component "
                            "reference without one matching relationship; affected diagram "
                            "controls have a coverage gap."
                        )
                        unrecognized_count += 1
                        issue_entries.append(
                            (
                                "diagram-component-relationship-binding",
                                repr((frame_index, attribute_name)),
                            )
                        )
                        continue
                    relationship = matches[0]
                    actual_kind = _WORKSHEET_DRAWING_DIAGRAM_RELATIONSHIP_KINDS.get(
                        relationship.relationship_type.casefold()
                    )
                    if (
                        actual_kind != expected_kind
                        or relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        warnings.add(
                            "FormulaFence found a Worksheet DrawingML SmartArt component "
                            "with an unsafe or unexpected relationship; affected diagram "
                            "controls have a coverage gap."
                        )
                        unrecognized_count += 1
                        issue_entries.append(
                            (
                                "unsafe-or-unexpected-diagram-component",
                                repr((frame_index, attribute_name)),
                            )
                        )
                        continue
                    diagram_members_by_kind[expected_kind].add(relationship.safe_target)

            for relationship in relationships:
                if (
                    _WORKSHEET_DRAWING_DIAGRAM_RELATIONSHIP_KINDS.get(
                        relationship.relationship_type.casefold()
                    )
                    != "drawing"
                ):
                    continue
                if relationship not in selected_relationships:
                    selected_relationships.append(relationship)
                if (
                    relationship.target_mode.casefold() != "internal"
                    or relationship.safe_target is None
                ):
                    warnings.add(
                        "FormulaFence found a Worksheet DrawingML SmartArt rendering "
                        "relationship without a safe internal target; affected diagram "
                        "controls have a coverage gap."
                    )
                    unrecognized_count += 1
                    issue_entries.append(
                        ("unsafe-diagram-rendering-target", repr(relationship.semantic_key()))
                    )
                    continue
                diagram_members_by_kind["drawing"].add(relationship.safe_target)

        for component_kind in (
            "data",
            "layout",
            "quick-style",
            "colours",
            "drawing",
        ):
            for component_member in sorted(
                diagram_members_by_kind[component_kind], key=str.casefold
            ):
                component_payload, component_fallback = (
                    _worksheet_drawing_shape_xml_payload(
                        archive,
                        component_member,
                        warnings,
                        budget,
                    )
                )
                if component_payload is None:
                    unrecognized_count += 1
                    issue_entries.append(
                        (
                            "unreadable-diagram-component",
                            repr((component_kind, component_member)),
                        )
                    )
                    diagram_signature_entries.append(
                        (
                            f"diagram-{component_kind}",
                            component_fallback or "",
                        )
                    )
                    continue
                try:
                    component_root = _xml_root_from_payload(component_payload)
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                    warnings.add(
                        "FormulaFence could not inspect a Worksheet DrawingML SmartArt "
                        f"component ({type(error).__name__}); affected diagram controls were "
                        "not compared."
                    )
                    unrecognized_count += 1
                    issue_entries.append(
                        (
                            "malformed-diagram-component",
                            repr((component_kind, component_member)),
                        )
                    )
                    diagram_signature_entries.append(
                        (
                            f"diagram-{component_kind}",
                            _private_payload_signature(component_payload),
                        )
                    )
                    continue
                if (
                    _xml_namespace(component_root.tag),
                    _xml_local_name(component_root.tag),
                ) not in _WORKSHEET_DRAWING_DIAGRAM_COMPONENT_ROOTS[component_kind]:
                    warnings.add(
                        "FormulaFence found a Worksheet DrawingML SmartArt component "
                        "with an unexpected root; affected diagram controls have a "
                        "coverage gap."
                    )
                    unrecognized_count += 1
                    issue_entries.append(
                        (
                            "unexpected-diagram-component-root",
                            repr((component_kind, component_member)),
                        )
                    )
                    diagram_signature_entries.append(
                        (
                            f"diagram-{component_kind}",
                            _private_payload_signature(component_payload),
                        )
                    )
                    continue
                component_relationships = _worksheet_drawing_shape_raw_relationships(
                    archive,
                    component_member,
                    warnings,
                    context="Worksheet DrawingML SmartArt component",
                )
                component_relationship_semantics: dict[str, tuple[str, str, str]] = {}
                if component_relationships is None:
                    unrecognized_count += 1
                    issue_entries.append(
                        (
                            "unreadable-diagram-component-relationships",
                            repr((component_kind, component_member)),
                        )
                    )
                else:
                    component_relationships_by_id: dict[
                        str,
                        list[_WorksheetDrawingShapeRawRelationship],
                    ] = defaultdict(list)
                    for component_relationship in component_relationships:
                        if component_relationship.relationship_id:
                            component_relationships_by_id[
                                component_relationship.relationship_id
                            ].append(component_relationship)
                    for relationship_id, matches in component_relationships_by_id.items():
                        if len(matches) != 1:
                            warnings.add(
                                "FormulaFence found duplicate Worksheet DrawingML SmartArt "
                                "component relationship IDs; affected diagram controls have "
                                "a coverage gap."
                            )
                            unrecognized_count += 1
                            issue_entries.append(
                                (
                                    "duplicate-diagram-component-relationship",
                                    repr((component_kind, component_member, relationship_id)),
                                )
                            )
                        component_relationship_semantics[relationship_id] = sorted(
                            relationship.semantic_key() for relationship in matches
                        )[0]
                    supported_image_relationships = [
                        relationship
                        for relationship in component_relationships
                        if (
                            component_kind == "data"
                            and relationship.relationship_type.casefold()
                            in _WORKSHEET_IMAGE_RELATIONSHIPS
                        )
                    ]
                    unsupported_relationships = [
                        relationship
                        for relationship in component_relationships
                        if relationship not in supported_image_relationships
                    ]
                    if unsupported_relationships:
                        warnings.add(
                            "FormulaFence found relationships from a Worksheet DrawingML "
                            "SmartArt component that are outside the bounded Diagram Data "
                            "image scan; affected diagram controls have a coverage gap."
                        )
                        unrecognized_count += len(unsupported_relationships)
                        issue_entries.append(
                            (
                                "unfollowed-diagram-component-relationships",
                                repr(
                                    (
                                        component_kind,
                                        component_member,
                                        tuple(
                                            sorted(
                                                relationship.semantic_key()
                                                for relationship in unsupported_relationships
                                            )
                                        ),
                                    )
                                ),
                            )
                        )
                    for relationship in supported_image_relationships:
                        if relationship not in selected_relationships:
                            selected_relationships.append(relationship)
                        if not relationship.relationship_id:
                            warnings.add(
                                "FormulaFence found a SmartArt Diagram Data image "
                                "relationship without an id; affected diagram controls have "
                                "a coverage gap."
                            )
                            unrecognized_count += 1
                            unresolved_diagram_image_entries.append(
                                (
                                    "missing-diagram-image-relationship-id",
                                    repr(relationship.semantic_key()),
                                )
                            )
                            continue
                        if relationship.target_mode.casefold() != "internal":
                            warnings.add(
                                "FormulaFence found a SmartArt Diagram Data image "
                                "relationship without a safe internal target; affected diagram "
                                "controls were not compared."
                            )
                            unrecognized_count += 1
                            unresolved_diagram_image_entries.append(
                                (
                                    "external-diagram-image-relationship",
                                    repr(relationship.semantic_key()),
                                )
                            )
                            continue
                        if relationship.safe_target is None:
                            warnings.add(
                                "FormulaFence found a SmartArt Diagram Data image "
                                "relationship without a safe package target; affected diagram "
                                "controls were not compared."
                            )
                            unrecognized_count += 1
                            unresolved_diagram_image_entries.append(
                                (
                                    "unsafe-diagram-image-relationship",
                                    repr(relationship.semantic_key()),
                                )
                            )
                            continue
                        diagram_image_members.add(relationship.safe_target)
                try:
                    component_fragment = _worksheet_drawing_shape_xml_fragment(
                        component_root,
                        component_relationship_semantics,
                        {},
                    )
                except RecursionError:
                    warnings.add(
                        "FormulaFence could not fully traverse an excessively nested "
                        "Worksheet DrawingML SmartArt component; affected diagram controls "
                        "were not compared."
                    )
                    unrecognized_count += 1
                    issue_entries.append(
                        (
                            "nested-diagram-component",
                            repr((component_kind, component_member)),
                        )
                    )
                    component_fragment = _private_payload_signature(component_payload)
                diagram_signature_entries.append(
                    (
                        f"diagram-{component_kind}",
                        repr((component_member, component_fragment)),
                    )
                )

    try:
        definition_entries = [
            (
                f"shape-anchor:{index}",
                repr(
                    _worksheet_drawing_shape_anchor_fragment(
                        anchor,
                        relationship_semantics,
                        connection_targets,
                    )
                ),
            )
            for index, (anchor, _containers) in enumerate(anchors)
        ]
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested Worksheet "
            "DrawingML shape; affected shape controls were not compared."
        )
        return _WorksheetDrawingShapeInspection(
            member=member,
            present=True,
            shape_anchor_count=len(anchors),
            shape_count=len(shape_nodes),
            connector_shape_count=len(connector_nodes),
            connector_attachment_count=connector_attachment_count,
            group_shape_count=group_shape_count,
            graphic_frame_count=len(graphic_frame_nodes),
            diagram_graphic_frame_count=len(diagram_graphic_frame_nodes),
            diagram_data_part_count=len(diagram_members_by_kind["data"]),
            diagram_layout_part_count=len(diagram_members_by_kind["layout"]),
            diagram_quick_style_part_count=len(
                diagram_members_by_kind["quick-style"]
            ),
            diagram_colour_part_count=len(diagram_members_by_kind["colours"]),
            diagram_drawing_part_count=len(diagram_members_by_kind["drawing"]),
            diagram_image_members=tuple(
                sorted(diagram_image_members, key=str.casefold)
            ),
            unresolved_diagram_image_entries=tuple(unresolved_diagram_image_entries),
            unrecognized_graphic_frame_count=unrecognized_graphic_frame_count,
            unrecognized_count=unrecognized_count + 1,
            definition_signature=_private_payload_signature(payload),
            diagram_signature=_private_external_data_signature(
                tuple(sorted(diagram_signature_entries))
            ),
            relationship_signature=_worksheet_drawing_shape_relationship_signature(
                tuple(selected_relationships)
            ),
        )

    definition_entries.extend(sorted(issue_entries))
    if unrecognized_count:
        warnings.add(
            "FormulaFence found malformed or unsupported Worksheet DrawingML shape "
            "metadata; affected shape controls have a coverage gap."
        )
    return _WorksheetDrawingShapeInspection(
        member=member,
        present=bool(anchors or unrecognized_count),
        shape_anchor_count=len(anchors),
        shape_count=len(shape_nodes),
        connector_shape_count=len(connector_nodes),
        connector_attachment_count=connector_attachment_count,
        group_shape_count=group_shape_count,
        graphic_frame_count=len(graphic_frame_nodes),
        diagram_graphic_frame_count=len(diagram_graphic_frame_nodes),
        diagram_data_part_count=len(diagram_members_by_kind["data"]),
        diagram_layout_part_count=len(diagram_members_by_kind["layout"]),
        diagram_quick_style_part_count=len(diagram_members_by_kind["quick-style"]),
        diagram_colour_part_count=len(diagram_members_by_kind["colours"]),
        diagram_drawing_part_count=len(diagram_members_by_kind["drawing"]),
        diagram_image_members=tuple(sorted(diagram_image_members, key=str.casefold)),
        unresolved_diagram_image_entries=tuple(unresolved_diagram_image_entries),
        text_shape_count=text_shape_count,
        text_paragraph_count=text_paragraph_count,
        text_run_count=text_run_count,
        macro_assignment_count=sum(
            bool(container.get("macro"))
            for container in [*shape_nodes, *connector_nodes, *graphic_frame_nodes]
        ),
        text_link_count=sum(
            bool(shape.get("textlink")) for shape in shape_nodes
        ),
        hyperlink_count=hyperlink_count,
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        unrecognized_graphic_frame_count=unrecognized_graphic_frame_count,
        unrecognized_count=unrecognized_count,
        inspected=True,
        definition_signature=_private_external_data_signature(
            tuple(definition_entries)
        ),
        diagram_signature=_private_external_data_signature(
            tuple(sorted(diagram_signature_entries))
        ),
        relationship_signature=_worksheet_drawing_shape_relationship_signature(
            tuple(selected_relationships)
        ),
    )


def _worksheet_drawing_shape_metadata(path: Path) -> _WorksheetDrawingShapeMetadata:
    """Inspect worksheet shapes before the workbook reader can omit them.

    The scan follows worksheet drawing relationships and compares text-bearing
    shapes, connectors, their anchor/layout declarations, connector attachment
    semantics, and directly referenced relationship semantics. It also hashes
    bounded direct Diagram Data image payloads without decoding them. It does
    not render DrawingML, fetch external targets, or open arbitrary related media.
    """
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _visual_worksheet_xml_paths(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _WorksheetDrawingShapeMetadata(
                    WorksheetDrawingShapeSnapshot(
                        unrecognized_shape_count=1,
                        definition_signature=_private_external_data_signature(
                            (("sheet-part-scan-failure", type(error).__name__),)
                        ),
                    ),
                    (
                        "FormulaFence could not inspect worksheet OOXML relationships "
                        f"for DrawingML shapes ({type(error).__name__}); affected shape "
                        "controls were not compared.",
                    ),
                )

            drawing_sources: dict[str, set[tuple[str, str]]] = defaultdict(set)
            unresolved_declarations: list[tuple[str, str]] = []
            for sheet, member in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                relationships = _worksheet_drawing_shape_raw_relationships(
                    archive,
                    member,
                    warnings,
                    context="worksheet",
                )
                if relationships is None:
                    unresolved_declarations.append(
                        ("unreadable-worksheet-relationships", member)
                    )
                    continue
                for relationship in relationships:
                    if (
                        relationship.relationship_type.casefold()
                        not in _WORKSHEET_DRAWING_SHAPE_DRAWING_RELATIONSHIPS
                    ):
                        continue
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        warnings.add(
                            "FormulaFence found a worksheet DrawingML relationship "
                            "without a safe internal target; affected shape controls "
                            "were not compared."
                        )
                        unresolved_declarations.append(
                            (
                                "unsafe-worksheet-drawing-relationship",
                                repr(relationship.semantic_key()),
                            )
                        )
                        continue
                    drawing_sources[relationship.safe_target].add((sheet, member))

            budget = _WorksheetDrawingShapeBudget()
            inspections: list[_WorksheetDrawingShapeInspection] = []
            declaration_entries: list[tuple[str, str]] = list(unresolved_declarations)
            for drawing_member in sorted(drawing_sources, key=str.casefold):
                sources = tuple(
                    sorted(
                        drawing_sources[drawing_member],
                        key=lambda source: source[0].casefold(),
                    )
                )
                inspection = _worksheet_drawing_shape_inspection(
                    archive,
                    drawing_member,
                    warnings,
                    budget,
                )
                inspections.append(inspection)
                if inspection.present:
                    declaration_entries.append(
                        (
                            "worksheet-drawing-shape-part",
                            repr((drawing_member, sources)),
                        )
                    )

            def aggregate_signature(attribute: str) -> str | None:
                entries = sorted(
                    (inspection.member, value)
                    for inspection in inspections
                    if (value := getattr(inspection, attribute)) is not None
                )
                return _private_external_data_signature(tuple(entries))

            diagram_image_members: set[str] = set()
            unresolved_diagram_image_entries: list[tuple[str, str]] = []
            for inspection in inspections:
                diagram_image_members.update(inspection.diagram_image_members)
                unresolved_diagram_image_entries.extend(
                    inspection.unresolved_diagram_image_entries
                )
            diagram_image_payload_inspection = _worksheet_drawing_shape_related_payloads(
                archive,
                diagram_image_members,
                unresolved_diagram_image_entries,
                warnings,
                _WorksheetDrawingShapeRelatedPartBudget(),
            )
            component_diagram_signature = aggregate_signature("diagram_signature")
            diagram_signature_entries = tuple(
                entry
                for entry in (
                    ("diagram-components", component_diagram_signature),
                    (
                        "diagram-data-image-payloads",
                        diagram_image_payload_inspection.payload_signature,
                    ),
                )
                if entry[1] is not None
            )

            present_inspections = [
                inspection for inspection in inspections if inspection.present
            ]
            worksheet_sheets = {
                sheet
                for inspection in present_inspections
                for sheet, _member in drawing_sources.get(inspection.member, set())
            }
            snapshot = WorksheetDrawingShapeSnapshot(
                worksheet_drawing_sheet_count=len(worksheet_sheets),
                worksheet_drawing_part_count=len(present_inspections),
                shape_anchor_count=sum(
                    inspection.shape_anchor_count for inspection in inspections
                ),
                shape_count=sum(inspection.shape_count for inspection in inspections),
                connector_shape_count=sum(
                    inspection.connector_shape_count for inspection in inspections
                ),
                connector_attachment_count=sum(
                    inspection.connector_attachment_count for inspection in inspections
                ),
                group_shape_count=sum(
                    inspection.group_shape_count for inspection in inspections
                ),
                graphic_frame_count=sum(
                    inspection.graphic_frame_count for inspection in inspections
                ),
                diagram_graphic_frame_count=sum(
                    inspection.diagram_graphic_frame_count for inspection in inspections
                ),
                diagram_data_part_count=sum(
                    inspection.diagram_data_part_count for inspection in inspections
                ),
                diagram_layout_part_count=sum(
                    inspection.diagram_layout_part_count for inspection in inspections
                ),
                diagram_quick_style_part_count=sum(
                    inspection.diagram_quick_style_part_count
                    for inspection in inspections
                ),
                diagram_colour_part_count=sum(
                    inspection.diagram_colour_part_count for inspection in inspections
                ),
                diagram_drawing_part_count=sum(
                    inspection.diagram_drawing_part_count for inspection in inspections
                ),
                diagram_image_part_count=diagram_image_payload_inspection.image_part_count,
                fingerprinted_diagram_image_part_count=(
                    diagram_image_payload_inspection.fingerprinted_part_count
                ),
                uninspected_diagram_image_part_count=(
                    diagram_image_payload_inspection.uninspected_part_count
                ),
                text_shape_count=sum(
                    inspection.text_shape_count for inspection in inspections
                ),
                text_paragraph_count=sum(
                    inspection.text_paragraph_count for inspection in inspections
                ),
                text_run_count=sum(
                    inspection.text_run_count for inspection in inspections
                ),
                macro_assignment_count=sum(
                    inspection.macro_assignment_count for inspection in inspections
                ),
                text_link_count=sum(
                    inspection.text_link_count for inspection in inspections
                ),
                hyperlink_count=sum(
                    inspection.hyperlink_count for inspection in inspections
                ),
                related_relationship_count=sum(
                    inspection.related_relationship_count for inspection in inspections
                ),
                external_relationship_count=sum(
                    inspection.external_relationship_count for inspection in inspections
                ),
                unrecognized_graphic_frame_count=sum(
                    inspection.unrecognized_graphic_frame_count
                    for inspection in inspections
                ),
                unrecognized_shape_count=(
                    len(unresolved_declarations)
                    + sum(inspection.unrecognized_count for inspection in inspections)
                ),
                declaration_signature=_private_external_data_signature(
                    tuple(sorted(declaration_entries))
                ),
                definition_signature=aggregate_signature("definition_signature"),
                diagram_signature=_private_external_data_signature(
                    diagram_signature_entries
                ),
                relationship_signature=aggregate_signature("relationship_signature"),
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _WorksheetDrawingShapeMetadata(
            WorksheetDrawingShapeSnapshot(
                unrecognized_shape_count=1,
                definition_signature=_private_external_data_signature(
                    (("worksheet-drawing-shape-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect Worksheet DrawingML shape OOXML "
                f"({type(error).__name__}); affected shape controls were not compared.",
            ),
        )
    return _WorksheetDrawingShapeMetadata(snapshot, tuple(sorted(warnings)))


_WORKSHEET_IMAGE_DRAWING_NAMESPACES = frozenset(
    {_DRAWINGML_SPREADSHEET_NS, _DRAWINGML_STRICT_SPREADSHEET_NS}
)
_WORKSHEET_IMAGE_MAIN_NAMESPACES = frozenset(
    {_DRAWINGML_MAIN_NS, _DRAWINGML_STRICT_MAIN_NS}
)
_WORKSHEET_IMAGE_ANCHORS = frozenset(
    {"twoCellAnchor", "oneCellAnchor", "absoluteAnchor"}
)
_WORKSHEET_IMAGE_ANCHOR_CHILDREN = frozenset(
    {"from", "to", "pos", "ext", "pic", "grpSp", "clientData"}
)
_WORKSHEET_IMAGE_GROUP_CHILDREN = frozenset(
    {"nvGrpSpPr", "grpSpPr", "pic", "grpSp"}
)


def _worksheet_image_raw_relationships(
    archive: ZipFile,
    source_member: str,
    warnings: set[str],
    budget: _WorksheetImageXmlBudget,
    *,
    context: str,
) -> tuple[_WorksheetImageRawRelationship, ...] | None:
    """Read native worksheet-image relationships without following targets."""
    relationship_member = _relationship_part_path(source_member)
    try:
        archive.getinfo(relationship_member)
    except KeyError:
        return ()
    payload, _fallback_signature = _worksheet_image_xml_payload(
        archive,
        relationship_member,
        warnings,
        budget,
        kind=f"{context} relationship",
    )
    if payload is None:
        return None
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect "
            f"{context} relationships for native worksheet-image inspection "
            f"({type(error).__name__}); affected images were not compared."
        )
        return None
    if (
        _xml_local_name(root.tag) != "Relationships"
        or _xml_namespace(root.tag) != _PACKAGE_RELATIONSHIP_NS
    ):
        warnings.add(
            "FormulaFence found an unexpected "
            f"{context} relationship root while inspecting native worksheet images; "
            "affected images were not compared."
        )
        return None

    relationship_tag = f"{{{_PACKAGE_RELATIONSHIP_NS}}}Relationship"
    relationships: list[_WorksheetImageRawRelationship] = []
    for relationship in root.findall(relationship_tag):
        target = relationship.get("Target")
        target_mode = relationship.get("TargetMode", "Internal")
        safe_target = (
            _normalise_part_target(source_member, target)
            if target is not None and target_mode.casefold() == "internal"
            else None
        )
        relationships.append(
            _WorksheetImageRawRelationship(
                relationship_id=relationship.get("Id"),
                relationship_type=relationship.get("Type", ""),
                target=target,
                target_mode=target_mode,
                safe_target=safe_target,
            )
        )
    if len(relationships) != len(root):
        warnings.add(
            "FormulaFence found unmodelled relationship XML while inspecting native "
            "worksheet images; affected images may be incomplete."
        )
        return None
    return tuple(relationships)


def _worksheet_image_relationship_index(
    relationships: tuple[_WorksheetImageRawRelationship, ...],
) -> dict[str, list[_WorksheetImageRawRelationship]]:
    """Index raw image relationships without trusting an identifier as unique."""
    indexed: dict[str, list[_WorksheetImageRawRelationship]] = defaultdict(list)
    for relationship in relationships:
        if relationship.relationship_id:
            indexed[relationship.relationship_id].append(relationship)
    for matches in indexed.values():
        matches.sort(key=lambda relationship: relationship.semantic_key())
    return indexed


def _worksheet_image_resolve_relationships(
    relationship_ids: set[str],
    relationships_by_id: Mapping[str, list[_WorksheetImageRawRelationship]],
    warnings: set[str],
    issues: list[tuple[str, str]],
    *,
    context: str,
) -> tuple[_WorksheetImageRawRelationship, ...]:
    """Resolve referenced relationship IDs with duplicate/missing evidence."""
    selected: list[_WorksheetImageRawRelationship] = []
    for relationship_id in sorted(relationship_ids):
        matches = relationships_by_id.get(relationship_id, [])
        if not matches:
            warnings.add(
                "FormulaFence found a native worksheet-image relationship reference "
                f"without a matching relationship in {context}; affected images have "
                "a coverage gap."
            )
            issues.append(("missing-image-relationship", relationship_id))
            continue
        if len(matches) > 1:
            warnings.add(
                "FormulaFence found duplicate native worksheet-image relationship IDs; "
                "affected images have a coverage gap."
            )
            issues.append(
                (
                    "duplicate-image-relationship",
                    repr(
                        (
                            relationship_id,
                            tuple(
                                relationship.semantic_key() for relationship in matches
                            ),
                        )
                    ),
                )
            )
        selected.append(matches[0])
    return tuple(selected)


def _worksheet_image_relationship_id(element: ElementTree.Element) -> str | None:
    """Return one Office relationship identifier from an image declaration."""
    values = [
        value
        for attribute, value in element.attrib.items()
        if attribute in _WORKSHEET_IMAGE_RELATIONSHIP_ATTRIBUTES and value
    ]
    if len(values) == 1:
        return values[0]
    return None


def _worksheet_image_is_image_relationship(
    relationship: _WorksheetImageRawRelationship,
) -> bool:
    """Return whether a relationship is a native image payload binding."""
    return relationship.relationship_type.casefold() in _WORKSHEET_IMAGE_RELATIONSHIPS


def _worksheet_image_xml_payload(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetImageXmlBudget,
    *,
    kind: str,
) -> tuple[bytes | None, str | None]:
    """Read one bounded native worksheet-image XML member."""
    if budget.remaining_parts <= 0:
        warnings.add(
            "FormulaFence reached its bounded native worksheet-image XML part count "
            "budget; affected images have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("worksheet-image-part-budget-exhausted", repr((kind, member))),)
        )
    budget.remaining_parts -= 1
    try:
        info = archive.getinfo(member)
    except KeyError:
        warnings.add(
            "FormulaFence could not locate a native worksheet-image XML package part; "
            "affected images were not compared."
        )
        return None, _private_external_data_signature(
            (("missing-worksheet-image-member", repr((kind, member))),)
        )
    metadata = repr((member, info.file_size, info.compress_size, info.CRC))
    if info.file_size > _WORKSHEET_IMAGE_MAX_XML_PART_BYTES:
        warnings.add(
            "FormulaFence did not fully read an oversized native worksheet-image XML "
            "part; affected images have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("oversized-worksheet-image-member", repr((kind, metadata))),)
        )
    if info.file_size > budget.remaining_bytes:
        warnings.add(
            "FormulaFence reached its bounded native worksheet-image XML read budget; "
            "affected images have a coverage gap."
        )
        return None, _private_external_data_signature(
            (("worksheet-image-read-budget-exhausted", repr((kind, metadata))),)
        )
    budget.remaining_bytes -= info.file_size
    try:
        return archive.read(member), None
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not read a native worksheet-image XML package part "
            f"({type(error).__name__}); affected images were not compared."
        )
        return None, _private_external_data_signature(
            (("unreadable-worksheet-image-member", repr((kind, metadata))),)
        )


def _worksheet_image_payloads(
    archive: ZipFile,
    members: set[str],
    unresolved_entries: list[tuple[str, str]],
    warnings: set[str],
    budget: _WorksheetImageRelatedPartBudget,
) -> _WorksheetImagePayloadInspection:
    """Fingerprint bounded image bytes without decoding or exposing them."""
    entries = list(unresolved_entries)
    payload_by_member: list[tuple[str, str]] = []
    fingerprinted_part_count = 0
    uninspected_part_count = len(unresolved_entries)
    for member in sorted(members, key=str.casefold):
        if budget.remaining_parts <= 0:
            warnings.add(
                "FormulaFence reached its bounded native worksheet-image payload part "
                "count budget; affected images have a coverage gap."
            )
            entries.append(("part-count-budget-exhausted", member))
            uninspected_part_count += 1
            continue
        budget.remaining_parts -= 1
        try:
            info = archive.getinfo(member)
        except KeyError:
            warnings.add(
                "FormulaFence could not locate a native worksheet-image payload part; "
                "affected images were not compared."
            )
            entries.append(("missing-image-part", member))
            uninspected_part_count += 1
            continue
        metadata = repr((member, info.file_size, info.compress_size, info.CRC))
        if info.file_size > _WORKSHEET_IMAGE_RELATED_PART_MAX_BYTES:
            warnings.add(
                "FormulaFence did not fully read an oversized native worksheet-image "
                "payload; affected images have a coverage gap."
            )
            entries.append(("oversized-image-part", metadata))
            uninspected_part_count += 1
            continue
        if info.file_size > budget.remaining_bytes:
            warnings.add(
                "FormulaFence reached its bounded native worksheet-image payload read "
                "budget; affected images have a coverage gap."
            )
            entries.append(("image-read-budget-exhausted", metadata))
            uninspected_part_count += 1
            continue
        budget.remaining_bytes -= info.file_size
        digest = hashlib.sha256()
        bytes_read = 0
        try:
            with archive.open(info) as payload:
                while chunk := payload.read(_WORKSHEET_IMAGE_HASH_CHUNK_BYTES):
                    bytes_read += len(chunk)
                    if bytes_read > info.file_size:
                        raise ValueError("payload exceeded its declared size")
                    digest.update(chunk)
            if bytes_read != info.file_size:
                raise ValueError("payload did not match its declared size")
        except (BadZipFile, OSError, RuntimeError, ValueError) as error:
            warnings.add(
                "FormulaFence could not fingerprint a native worksheet-image payload "
                f"({type(error).__name__}); affected images were not compared."
            )
            entries.append(("unreadable-image-part", metadata))
            uninspected_part_count += 1
            continue
        digest_hex = digest.hexdigest()
        payload_by_member.append((member, digest_hex))
        entries.append(("image-payload", repr((member, digest_hex))))
        fingerprinted_part_count += 1

    entries.sort()
    return _WorksheetImagePayloadInspection(
        image_part_count=len(members) + len(unresolved_entries),
        fingerprinted_part_count=fingerprinted_part_count,
        uninspected_part_count=uninspected_part_count,
        payload_by_member=tuple(
            sorted(payload_by_member, key=lambda item: item[0].casefold())
        ),
        payload_signature=(
            _private_external_data_signature(tuple(entries)) if entries else None
        ),
    )


def _worksheet_image_drawing_fragment(
    element: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
) -> tuple[object, ...]:
    """Canonicalize private picture XML while resolving relationship IDs."""
    namespace = _xml_namespace(element.tag)
    local_name = _xml_local_name(element.tag)
    attributes: list[tuple[str, str]] = []
    for attribute, value in element.attrib.items():
        if (
            namespace in _WORKSHEET_IMAGE_DRAWING_NAMESPACES
            and local_name == "cNvPr"
            and _xml_local_name(attribute) == "id"
        ):
            continue
        if attribute in _WORKSHEET_IMAGE_RELATIONSHIP_ATTRIBUTES:
            relationship = relationship_semantics.get(value)
            resolved: object = (
                ("relationship", relationship)
                if relationship is not None
                else ("missing-relationship", value)
            )
            attributes.append((_xml_display_name(attribute), repr(resolved)))
            continue
        if (
            namespace in _WORKSHEET_IMAGE_MAIN_NAMESPACES
            and local_name == "srgbClr"
            and _xml_local_name(attribute) == "val"
        ):
            value = value.upper()
        attributes.append((_xml_display_name(attribute), value))

    if namespace in _WORKSHEET_IMAGE_DRAWING_NAMESPACES and local_name == "grpSp":
        children = tuple(
            _worksheet_image_drawing_fragment(child, relationship_semantics)
            for child in element
            if (
                _xml_namespace(child.tag) in _WORKSHEET_IMAGE_DRAWING_NAMESPACES
                and _xml_local_name(child.tag) in _WORKSHEET_IMAGE_GROUP_CHILDREN
            )
        )
    else:
        children = tuple(
            _worksheet_image_drawing_fragment(child, relationship_semantics)
            for child in element
        )
    text = element.text
    if children and text is not None and not text.strip():
        text = None
    return (
        _xml_display_name(element.tag),
        tuple(sorted(attributes)),
        text,
        children,
    )


def _worksheet_image_anchor_fragment(
    anchor: ElementTree.Element,
    relationship_semantics: Mapping[str, tuple[str, str, str]],
) -> tuple[object, ...]:
    """Retain an image anchor while excluding non-image drawing siblings."""
    attributes = tuple(
        sorted(
            (_xml_display_name(attribute), value)
            for attribute, value in anchor.attrib.items()
        )
    )
    children = tuple(
        _worksheet_image_drawing_fragment(child, relationship_semantics)
        for child in anchor
        if (
            _xml_namespace(child.tag) in _WORKSHEET_IMAGE_DRAWING_NAMESPACES
            and _xml_local_name(child.tag) in _WORKSHEET_IMAGE_ANCHOR_CHILDREN
        )
    )
    return (_xml_display_name(anchor.tag), attributes, children)


def _worksheet_image_picture_containers(
    anchor: ElementTree.Element,
) -> tuple[ElementTree.Element, ...]:
    """Return native picture elements in an anchor or nested drawing group."""
    pictures: list[ElementTree.Element] = []

    def visit(element: ElementTree.Element) -> None:
        if _worksheet_drawing_shape_is_in_content_web_extension_alternate_content(
            element
        ):
            # The active Choice branch is a web-extension frame, which is
            # inspected by the add-in scanner.  Its Fallback branch is a
            # native picture preview and remains a normal image control.
            for child in element:
                if (
                    _xml_namespace(child.tag) == _MARKUP_COMPATIBILITY_NS
                    and _xml_local_name(child.tag) == "Fallback"
                ):
                    for fallback_child in child:
                        visit(fallback_child)
            return
        if _xml_namespace(element.tag) not in _WORKSHEET_IMAGE_DRAWING_NAMESPACES:
            return
        local_name = _xml_local_name(element.tag)
        if local_name == "pic":
            pictures.append(element)
            return
        if local_name == "grpSp":
            for child in element:
                visit(child)

    for child in anchor:
        visit(child)
    return tuple(pictures)


def _worksheet_image_picture_relationship_ids(
    picture: ElementTree.Element,
) -> tuple[set[str], set[str]]:
    """Return all picture links and the image-payload subset of those links."""
    relationship_ids: set[str] = set()
    image_relationship_ids: set[str] = set()
    for element in picture.iter():
        is_blip = (
            _xml_namespace(element.tag) in _WORKSHEET_IMAGE_MAIN_NAMESPACES
            and _xml_local_name(element.tag) == "blip"
        )
        for attribute, value in element.attrib.items():
            if attribute not in _WORKSHEET_IMAGE_RELATIONSHIP_ATTRIBUTES or not value:
                continue
            relationship_ids.add(value)
            if is_blip and _xml_local_name(attribute) in {"embed", "link"}:
                image_relationship_ids.add(value)
    return relationship_ids, image_relationship_ids


def _worksheet_anchored_picture_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetImageXmlBudget,
) -> _WorksheetAnchoredPictureInspection:
    """Inspect native anchored pictures in one DrawingML worksheet part."""
    payload, fallback_signature = _worksheet_image_xml_payload(
        archive,
        member,
        warnings,
        budget,
        kind="Worksheet DrawingML picture",
    )
    if payload is None:
        return _WorksheetAnchoredPictureInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a Worksheet DrawingML picture XML part "
            f"({type(error).__name__}); affected pictures were not compared."
        )
        return _WorksheetAnchoredPictureInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if (
        _xml_namespace(root.tag) not in _WORKSHEET_IMAGE_DRAWING_NAMESPACES
        or _xml_local_name(root.tag) != "wsDr"
    ):
        warnings.add(
            "FormulaFence found a Worksheet DrawingML picture part with an unexpected "
            "root; affected pictures were not compared."
        )
        return _WorksheetAnchoredPictureInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    anchor_records: list[tuple[ElementTree.Element, tuple[ElementTree.Element, ...]]] = []
    for child in root:
        if (
            _xml_namespace(child.tag) not in _WORKSHEET_IMAGE_DRAWING_NAMESPACES
            or _xml_local_name(child.tag) not in _WORKSHEET_IMAGE_ANCHORS
        ):
            continue
        pictures = _worksheet_image_picture_containers(child)
        if pictures:
            anchor_records.append((child, pictures))

    all_picture_nodes = [
        element
        for element in root.iter()
        if (
            _xml_namespace(element.tag) in _WORKSHEET_IMAGE_DRAWING_NAMESPACES
            and _xml_local_name(element.tag) == "pic"
        )
    ]
    selected_picture_ids = {
        id(picture)
        for _anchor, pictures in anchor_records
        for picture in pictures
    }
    issues: list[tuple[str, str]] = []
    unrecognized_count = 0
    unanchored_picture_count = sum(
        id(picture) not in selected_picture_ids for picture in all_picture_nodes
    )
    if unanchored_picture_count:
        warnings.add(
            "FormulaFence found Worksheet DrawingML pictures outside supported anchors; "
            "affected picture controls have a coverage gap."
        )
        issues.append(("unanchored-picture-count", str(unanchored_picture_count)))
        unrecognized_count += unanchored_picture_count

    relationship_ids: set[str] = set()
    image_relationship_ids: set[str] = set()
    for _anchor, pictures in anchor_records:
        for picture in pictures:
            picture_relationship_ids, picture_image_relationship_ids = (
                _worksheet_image_picture_relationship_ids(picture)
            )
            relationship_ids.update(picture_relationship_ids)
            image_relationship_ids.update(picture_image_relationship_ids)
            if not picture_image_relationship_ids:
                issues.append(("picture-without-image-binding", str(id(picture))))
                unrecognized_count += 1

    selected_relationships: tuple[_WorksheetImageRawRelationship, ...] = ()
    relationship_semantics: dict[str, tuple[str, str, str]] = {}
    if relationship_ids:
        relationships = _worksheet_image_raw_relationships(
            archive,
            member,
            warnings,
            budget,
            context="Worksheet DrawingML picture",
        )
        if relationships is None:
            issues.append(("unreadable-picture-relationships", member))
            unrecognized_count += 1
        else:
            relationships_by_id = _worksheet_image_relationship_index(relationships)
            selected_relationships = _worksheet_image_resolve_relationships(
                relationship_ids,
                relationships_by_id,
                warnings,
                issues,
                context="Worksheet DrawingML picture",
            )
            relationship_semantics = {
                relationship.relationship_id: relationship.semantic_key()
                for relationship in selected_relationships
                if relationship.relationship_id
            }

    selected_by_id = {
        relationship.relationship_id: relationship
        for relationship in selected_relationships
        if relationship.relationship_id
    }
    image_members: set[str] = set()
    for relationship_id in sorted(image_relationship_ids):
        relationship = selected_by_id.get(relationship_id)
        if relationship is None:
            continue
        if not _worksheet_image_is_image_relationship(relationship):
            warnings.add(
                "FormulaFence found a DrawingML picture image binding with an "
                "unexpected relationship type; affected pictures have a coverage gap."
            )
            issues.append(
                ("unexpected-picture-image-relationship", repr(relationship.semantic_key()))
            )
            unrecognized_count += 1
            continue
        if relationship.target_mode.casefold() == "internal":
            if relationship.safe_target is None:
                warnings.add(
                    "FormulaFence found a DrawingML picture without a safe internal "
                    "image target; affected pictures have a coverage gap."
                )
                issues.append(
                    ("unsafe-picture-image-target", repr(relationship.semantic_key()))
                )
                unrecognized_count += 1
                continue
            image_members.add(relationship.safe_target)

    try:
        definition_entries = [
            (
                f"picture-anchor:{index}",
                repr(_worksheet_image_anchor_fragment(anchor, relationship_semantics)),
            )
            for index, (anchor, _pictures) in enumerate(anchor_records)
        ]
    except RecursionError:
        warnings.add(
            "FormulaFence could not fully traverse an excessively nested Worksheet "
            "DrawingML picture; affected pictures were not compared."
        )
        return _WorksheetAnchoredPictureInspection(
            member=member,
            present=True,
            picture_anchor_count=len(anchor_records),
            picture_count=sum(len(pictures) for _anchor, pictures in anchor_records),
            related_relationship_count=len(selected_relationships),
            external_relationship_count=sum(
                relationship.target_mode.casefold() != "internal"
                for relationship in selected_relationships
            ),
            image_members=tuple(sorted(image_members, key=str.casefold)),
            unrecognized_count=unrecognized_count + 1,
            definition_signature=_private_payload_signature(payload),
            relationship_entries=tuple(
                sorted(relationship.semantic_key() for relationship in selected_relationships)
            ),
        )

    definition_entries.extend(sorted(issues))
    if unrecognized_count:
        warnings.add(
            "FormulaFence found malformed or unsupported Worksheet DrawingML picture "
            "metadata; affected pictures have a coverage gap."
        )
    return _WorksheetAnchoredPictureInspection(
        member=member,
        present=bool(anchor_records or unrecognized_count),
        picture_anchor_count=len(anchor_records),
        picture_count=sum(len(pictures) for _anchor, pictures in anchor_records),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        image_members=tuple(sorted(image_members, key=str.casefold)),
        unrecognized_count=unrecognized_count,
        definition_signature=_private_external_data_signature(tuple(definition_entries)),
        relationship_entries=tuple(
            sorted(relationship.semantic_key() for relationship in selected_relationships)
        ),
    )


def _worksheet_image_vml_relationship_id(element: ElementTree.Element) -> str | None:
    """Return one image relationship ID from header/footer VML."""
    values = [
        value
        for attribute, value in element.attrib.items()
        if (
            attribute in _WORKSHEET_IMAGE_RELATIONSHIP_ATTRIBUTES
            or (
                _xml_namespace(attribute) == _VML_OFFICE_NS
                and _xml_local_name(attribute) == "relid"
            )
        )
        and value
    ]
    if len(values) == 1:
        return values[0]
    return None


def _worksheet_header_footer_image_inspection(
    archive: ZipFile,
    member: str,
    warnings: set[str],
    budget: _WorksheetImageXmlBudget,
) -> _WorksheetHeaderFooterImageInspection:
    """Inspect VML-backed header/footer watermark images without rendering VML."""
    payload, fallback_signature = _worksheet_image_xml_payload(
        archive,
        member,
        warnings,
        budget,
        kind="header/footer VML image",
    )
    if payload is None:
        return _WorksheetHeaderFooterImageInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=fallback_signature,
        )
    try:
        root = _xml_root_from_payload(payload)
    except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
        warnings.add(
            "FormulaFence could not inspect a header/footer VML image part "
            f"({type(error).__name__}); affected images were not compared."
        )
        return _WorksheetHeaderFooterImageInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )
    if _xml_local_name(root.tag) != "xml" or _xml_namespace(root.tag) not in {
        None,
        _VML_NS,
    }:
        warnings.add(
            "FormulaFence found a header/footer VML image part with an unexpected "
            "root; affected images were not compared."
        )
        return _WorksheetHeaderFooterImageInspection(
            member=member,
            present=True,
            unrecognized_count=1,
            definition_signature=_private_payload_signature(payload),
        )

    image_data_tag = f"{{{_VML_NS}}}imagedata"
    image_data_nodes = list(root.iter(image_data_tag))
    if not image_data_nodes:
        return _WorksheetHeaderFooterImageInspection(member=member)

    issues: list[tuple[str, str]] = []
    relationship_ids: set[str] = set()
    for image_data in image_data_nodes:
        relationship_id = _worksheet_image_vml_relationship_id(image_data)
        if relationship_id is None:
            issues.append(("header-footer-image-without-binding", str(id(image_data))))
            continue
        relationship_ids.add(relationship_id)

    selected_relationships: tuple[_WorksheetImageRawRelationship, ...] = ()
    relationship_semantics: dict[str, tuple[str, str, str]] = {}
    relationships = _worksheet_image_raw_relationships(
        archive,
        member,
        warnings,
        budget,
        context="header/footer VML image",
    )
    if relationships is None:
        issues.append(("unreadable-header-footer-image-relationships", member))
    else:
        selected_relationships = _worksheet_image_resolve_relationships(
            relationship_ids,
            _worksheet_image_relationship_index(relationships),
            warnings,
            issues,
            context="header/footer VML image",
        )
        relationship_semantics = {
            relationship.relationship_id: relationship.semantic_key()
            for relationship in selected_relationships
            if relationship.relationship_id
        }

    selected_by_id = {
        relationship.relationship_id: relationship
        for relationship in selected_relationships
        if relationship.relationship_id
    }
    image_members: set[str] = set()
    for relationship_id in sorted(relationship_ids):
        relationship = selected_by_id.get(relationship_id)
        if relationship is None:
            continue
        if not _worksheet_image_is_image_relationship(relationship):
            warnings.add(
                "FormulaFence found a header/footer VML image binding with an "
                "unexpected relationship type; affected images have a coverage gap."
            )
            issues.append(
                ("unexpected-header-footer-image-relationship", repr(relationship.semantic_key()))
            )
            continue
        if relationship.target_mode.casefold() == "internal":
            if relationship.safe_target is None:
                warnings.add(
                    "FormulaFence found a header/footer VML image without a safe "
                    "internal target; affected images have a coverage gap."
                )
                issues.append(
                    ("unsafe-header-footer-image-target", repr(relationship.semantic_key()))
                )
                continue
            image_members.add(relationship.safe_target)

    relationship_attributes = frozenset(
        {
            *_WORKSHEET_IMAGE_RELATIONSHIP_ATTRIBUTES,
            f"{{{_VML_OFFICE_NS}}}relid",
        }
    )
    shape_type_tag = f"{{{_VML_NS}}}shapetype"
    shape_tag = f"{{{_VML_NS}}}shape"
    shape_type_fragments: dict[str, tuple[object, ...]] = {}
    for shape_type in root.iter(shape_type_tag):
        identifier = shape_type.get("id")
        if identifier:
            shape_type_fragments[identifier] = _legacy_note_vml_fragment(
                shape_type,
                relationship_semantics,
                {},
                relationship_attributes=relationship_attributes,
            )
    parent_by_child = {
        child: parent
        for parent in root.iter()
        for child in parent
    }
    fragments: list[tuple[object, ...]] = []
    seen_shapes: set[int] = set()
    for image_data in image_data_nodes:
        container = parent_by_child.get(image_data)
        while container is not None and container.tag != shape_tag:
            container = parent_by_child.get(container)
        if container is None:
            issues.append(("header-footer-image-without-vml-shape", str(id(image_data))))
            fragments.append(
                _legacy_note_vml_fragment(
                    image_data,
                    relationship_semantics,
                    shape_type_fragments,
                    relationship_attributes=relationship_attributes,
                )
            )
            continue
        if id(container) in seen_shapes:
            continue
        seen_shapes.add(id(container))
        fragments.append(
            _legacy_note_vml_fragment(
                container,
                relationship_semantics,
                shape_type_fragments,
                relationship_attributes=relationship_attributes,
            )
        )

    if issues:
        warnings.add(
            "FormulaFence found malformed or unsupported header/footer VML image "
            "metadata; affected images have a coverage gap."
        )
    return _WorksheetHeaderFooterImageInspection(
        member=member,
        present=True,
        image_count=len(image_data_nodes),
        related_relationship_count=len(selected_relationships),
        external_relationship_count=sum(
            relationship.target_mode.casefold() != "internal"
            for relationship in selected_relationships
        ),
        image_members=tuple(sorted(image_members, key=str.casefold)),
        unrecognized_count=len(issues),
        definition_signature=_private_external_data_signature(
            tuple(
                (f"header-footer-image:{index}", repr(fragment))
                for index, fragment in enumerate(fragments)
            )
            + tuple(sorted(issues))
        ),
        relationship_entries=tuple(
            sorted(relationship.semantic_key() for relationship in selected_relationships)
        ),
    )


def _worksheet_image_metadata(path: Path) -> _WorksheetImageMetadata:
    """Inspect native worksheet image controls before ordinary reader loss.

    The scan compares floating pictures, display-only worksheet backgrounds, and
    VML-backed header/footer watermarks. It fingerprints safe direct image bytes
    under fixed budgets without decoding media or following external targets.
    Charts, rich-data images, Themes, ActiveX/OLE, and text shapes remain in
    their dedicated control boundaries.
    """
    warnings: set[str] = set()
    try:
        with ZipFile(path) as archive:
            try:
                sheet_parts = _visual_worksheet_xml_paths(archive)
            except (
                KeyError,
                ElementTree.ParseError,
                OSError,
                RuntimeError,
                ValueError,
            ) as error:
                return _WorksheetImageMetadata(
                    WorksheetImageSnapshot(
                        unrecognized_image_count=1,
                        definition_signature=_private_external_data_signature(
                            (("worksheet-image-sheet-part-scan-failure", type(error).__name__),)
                        ),
                    ),
                    (
                        "FormulaFence could not inspect worksheet OOXML for native "
                        f"image controls ({type(error).__name__}); affected images were "
                        "not compared.",
                    ),
                )

            xml_budget = _WorksheetImageXmlBudget()
            payload_budget = _WorksheetImageRelatedPartBudget()
            drawing_sources: dict[str, set[tuple[str, str]]] = defaultdict(set)
            drawing_source_relationships: dict[
                str, set[tuple[str, str, str]]
            ] = defaultdict(set)
            header_footer_sources: dict[str, set[tuple[str, str]]] = defaultdict(set)
            header_footer_source_relationships: dict[
                str, set[tuple[str, str, str]]
            ] = defaultdict(set)
            background_records: list[tuple[str, _WorksheetImageRawRelationship]] = []
            unresolved_declarations: list[tuple[str, str]] = []
            candidate_sheets: set[str] = set()

            for sheet, member in sorted(
                sheet_parts.items(),
                key=lambda item: item[0].casefold(),
            ):
                payload, fallback_signature = _worksheet_image_xml_payload(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                    kind="worksheet declaration",
                )
                if payload is None:
                    unresolved_declarations.append(
                        (
                            "unreadable-worksheet-image-declaration",
                            repr((sheet, fallback_signature)),
                        )
                    )
                    candidate_sheets.add(sheet)
                    continue
                try:
                    worksheet = _xml_root_from_payload(payload)
                except (ElementTree.ParseError, OSError, RuntimeError, ValueError) as error:
                    warnings.add(
                        "FormulaFence could not inspect worksheet XML for native image "
                        f"controls ({type(error).__name__}); affected images were not "
                        "compared."
                    )
                    unresolved_declarations.append(
                        ("invalid-worksheet-image-declaration", repr((sheet, type(error).__name__)))
                    )
                    candidate_sheets.add(sheet)
                    continue
                if (
                    _xml_namespace(worksheet.tag)
                    not in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                    or _xml_local_name(worksheet.tag) != "worksheet"
                ):
                    warnings.add(
                        "FormulaFence found an unexpected worksheet root while inspecting "
                        "native image controls; affected images were not compared."
                    )
                    unresolved_declarations.append(
                        ("unexpected-worksheet-image-root", sheet)
                    )
                    candidate_sheets.add(sheet)
                    continue

                image_declarations = [
                    element
                    for element in worksheet
                    if (
                        _xml_namespace(element.tag)
                        in {_SPREADSHEETML_NS, _STRICT_SPREADSHEETML_NS}
                        and _xml_local_name(element.tag)
                        in {"drawing", "picture", "legacyDrawingHF"}
                    )
                ]
                if not image_declarations:
                    continue
                relationships = _worksheet_image_raw_relationships(
                    archive,
                    member,
                    warnings,
                    xml_budget,
                    context="worksheet",
                )
                if relationships is None:
                    unresolved_declarations.append(
                        ("unreadable-worksheet-image-relationships", member)
                    )
                    candidate_sheets.add(sheet)
                    continue
                relationships_by_id = _worksheet_image_relationship_index(relationships)
                for element in image_declarations:
                    local_name = _xml_local_name(element.tag)
                    relationship_id = _worksheet_image_relationship_id(element)
                    if relationship_id is None:
                        warnings.add(
                            "FormulaFence found a native worksheet-image declaration "
                            "without one relationship ID; affected images have a coverage gap."
                        )
                        unresolved_declarations.append(
                            ("worksheet-image-declaration-without-relationship", sheet)
                        )
                        candidate_sheets.add(sheet)
                        continue
                    issues: list[tuple[str, str]] = []
                    selected = _worksheet_image_resolve_relationships(
                        {relationship_id},
                        relationships_by_id,
                        warnings,
                        issues,
                        context="worksheet",
                    )
                    if issues or not selected:
                        unresolved_declarations.extend(
                            (f"worksheet-{local_name}-{kind}", repr((sheet, detail)))
                            for kind, detail in issues
                        )
                        candidate_sheets.add(sheet)
                        continue
                    relationship = selected[0]
                    if local_name == "drawing":
                        if (
                            relationship.relationship_type.casefold()
                            not in _WORKSHEET_IMAGE_DRAWING_RELATIONSHIPS
                        ):
                            warnings.add(
                                "FormulaFence found a worksheet DrawingML declaration with "
                                "an unexpected relationship type; affected pictures have a "
                                "coverage gap."
                            )
                            unresolved_declarations.append(
                                (
                                    "unexpected-worksheet-drawing-relationship",
                                    repr(relationship.semantic_key()),
                                )
                            )
                            candidate_sheets.add(sheet)
                            continue
                        if (
                            relationship.target_mode.casefold() != "internal"
                            or relationship.safe_target is None
                        ):
                            warnings.add(
                                "FormulaFence found a worksheet DrawingML declaration without "
                                "a safe internal target; affected pictures have a coverage gap."
                            )
                            unresolved_declarations.append(
                                (
                                    "unsafe-worksheet-drawing-target",
                                    repr(relationship.semantic_key()),
                                )
                            )
                            candidate_sheets.add(sheet)
                            continue
                        drawing_sources[relationship.safe_target].add((sheet, member))
                        drawing_source_relationships[relationship.safe_target].add(
                            relationship.semantic_key()
                        )
                        continue
                    if local_name == "picture":
                        if not _worksheet_image_is_image_relationship(relationship):
                            warnings.add(
                                "FormulaFence found a worksheet background image declaration "
                                "with an unexpected relationship type; affected images have a "
                                "coverage gap."
                            )
                            unresolved_declarations.append(
                                (
                                    "unexpected-background-image-relationship",
                                    repr(relationship.semantic_key()),
                                )
                            )
                            candidate_sheets.add(sheet)
                            continue
                        background_records.append((sheet, relationship))
                        candidate_sheets.add(sheet)
                        continue
                    if (
                        relationship.relationship_type.casefold()
                        not in _WORKSHEET_IMAGE_VML_RELATIONSHIPS
                    ):
                        warnings.add(
                            "FormulaFence found a header/footer VML image declaration with "
                            "an unexpected relationship type; affected images have a coverage gap."
                        )
                        unresolved_declarations.append(
                            (
                                "unexpected-header-footer-vml-relationship",
                                repr(relationship.semantic_key()),
                            )
                        )
                        candidate_sheets.add(sheet)
                        continue
                    if (
                        relationship.target_mode.casefold() != "internal"
                        or relationship.safe_target is None
                    ):
                        warnings.add(
                            "FormulaFence found a header/footer VML image declaration without "
                            "a safe internal target; affected images have a coverage gap."
                        )
                        unresolved_declarations.append(
                            ("unsafe-header-footer-vml-target", repr(relationship.semantic_key()))
                        )
                        candidate_sheets.add(sheet)
                        continue
                    header_footer_sources[relationship.safe_target].add((sheet, member))
                    header_footer_source_relationships[relationship.safe_target].add(
                        relationship.semantic_key()
                    )

            drawing_inspections: list[_WorksheetAnchoredPictureInspection] = []
            for drawing_member in sorted(drawing_sources, key=str.casefold):
                drawing_inspections.append(
                    _worksheet_anchored_picture_inspection(
                        archive,
                        drawing_member,
                        warnings,
                        xml_budget,
                    )
                )
            header_footer_inspections: list[_WorksheetHeaderFooterImageInspection] = []
            for vml_member in sorted(header_footer_sources, key=str.casefold):
                header_footer_inspections.append(
                    _worksheet_header_footer_image_inspection(
                        archive,
                        vml_member,
                        warnings,
                        xml_budget,
                    )
                )

            image_members: set[str] = set()
            unresolved_payload_entries: list[tuple[str, str]] = []
            relationship_entries: list[tuple[str, str, str]] = []
            definition_entries: list[tuple[str, str]] = list(unresolved_declarations)
            declaration_entries: list[tuple[str, str]] = list(unresolved_declarations)
            image_sheets = set(candidate_sheets)

            for sheet, relationship in background_records:
                relationship_entries.append(relationship.semantic_key())
                declaration_entries.append(
                    ("worksheet-background-image", repr((sheet, relationship.semantic_key())))
                )
                definition_entries.append(
                    ("worksheet-background-image", repr((sheet, relationship.semantic_key())))
                )
                image_sheets.add(sheet)
                if relationship.target_mode.casefold() == "internal":
                    if relationship.safe_target is None:
                        unresolved_payload_entries.append(
                            ("unsafe-background-image-target", repr(relationship.semantic_key()))
                        )
                    else:
                        image_members.add(relationship.safe_target)

            for inspection in drawing_inspections:
                sources = tuple(
                    sorted(
                        drawing_sources.get(inspection.member, set()),
                        key=lambda source: source[0].casefold(),
                    )
                )
                source_relationships = tuple(
                    sorted(
                        drawing_source_relationships.get(inspection.member, set())
                    )
                )
                if inspection.present:
                    image_sheets.update(sheet for sheet, _member in sources)
                    declaration_entries.append(
                        (
                            "anchored-picture-source",
                            repr(
                                (
                                    sources,
                                    source_relationships,
                                    inspection.picture_anchor_count,
                                    inspection.picture_count,
                                )
                            ),
                        )
                    )
                    definition_entries.append(
                        (
                            "anchored-picture-definition",
                            repr(
                                (
                                    sources,
                                    source_relationships,
                                    inspection.definition_signature,
                                )
                            ),
                        )
                    )
                relationship_entries.extend(source_relationships)
                relationship_entries.extend(inspection.relationship_entries)
                image_members.update(inspection.image_members)

            for inspection in header_footer_inspections:
                sources = tuple(
                    sorted(
                        header_footer_sources.get(inspection.member, set()),
                        key=lambda source: source[0].casefold(),
                    )
                )
                source_relationships = tuple(
                    sorted(
                        header_footer_source_relationships.get(
                            inspection.member,
                            set(),
                        )
                    )
                )
                if inspection.present:
                    image_sheets.update(sheet for sheet, _member in sources)
                    declaration_entries.append(
                        (
                            "header-footer-image-source",
                            repr((sources, source_relationships, inspection.image_count)),
                        )
                    )
                    definition_entries.append(
                        (
                            "header-footer-image-definition",
                            repr(
                                (
                                    sources,
                                    source_relationships,
                                    inspection.definition_signature,
                                )
                            ),
                        )
                    )
                relationship_entries.extend(source_relationships)
                relationship_entries.extend(inspection.relationship_entries)
                image_members.update(inspection.image_members)

            payload_inspection = _worksheet_image_payloads(
                archive,
                image_members,
                unresolved_payload_entries,
                warnings,
                payload_budget,
            )
            all_relationship_entries = tuple(sorted(relationship_entries))
            snapshot = WorksheetImageSnapshot(
                worksheet_image_sheet_count=len(image_sheets),
                anchored_picture_count=sum(
                    inspection.picture_count for inspection in drawing_inspections
                ),
                anchored_picture_anchor_count=sum(
                    inspection.picture_anchor_count for inspection in drawing_inspections
                ),
                worksheet_background_image_count=len(background_records),
                header_footer_image_count=sum(
                    inspection.image_count for inspection in header_footer_inspections
                ),
                image_part_count=payload_inspection.image_part_count,
                fingerprinted_image_part_count=payload_inspection.fingerprinted_part_count,
                uninspected_image_part_count=payload_inspection.uninspected_part_count,
                related_relationship_count=len(all_relationship_entries),
                external_relationship_count=sum(
                    relationship[1].casefold() != "internal"
                    for relationship in all_relationship_entries
                ),
                unrecognized_image_count=(
                    len(unresolved_declarations)
                    + sum(inspection.unrecognized_count for inspection in drawing_inspections)
                    + sum(
                        inspection.unrecognized_count
                        for inspection in header_footer_inspections
                    )
                ),
                declaration_signature=(
                    _private_external_data_signature(
                        tuple(sorted(declaration_entries))
                    )
                    if declaration_entries
                    else None
                ),
                definition_signature=(
                    _private_external_data_signature(tuple(sorted(definition_entries)))
                    if definition_entries
                    else None
                ),
                relationship_signature=(
                    _private_external_data_signature(
                        tuple(
                            (f"image-relationship:{index}", repr(relationship))
                            for index, relationship in enumerate(all_relationship_entries)
                        )
                    )
                    if all_relationship_entries
                    else None
                ),
                image_payload_signature=payload_inspection.payload_signature,
            )
    except (BadZipFile, OSError, RuntimeError, ValueError) as error:
        return _WorksheetImageMetadata(
            WorksheetImageSnapshot(
                unrecognized_image_count=1,
                definition_signature=_private_external_data_signature(
                    (("worksheet-image-scan-failure", type(error).__name__),)
                ),
            ),
            (
                "FormulaFence could not inspect native worksheet-image OOXML "
                f"({type(error).__name__}); affected images were not compared.",
            ),
        )
    return _WorksheetImageMetadata(snapshot, tuple(sorted(warnings)))


def _array_formula_worksheet_metadata(
    archive: ZipFile,
    sheet: str,
    member: str,
    dynamic_indexes: frozenset[int],
) -> tuple[set[CellKey], set[CellKey]]:
    """Stream raw array-formula bindings without retaining a worksheet tree."""
    cell_tag = f"{{{_SPREADSHEETML_NS}}}c"
    formula_tag = f"{{{_SPREADSHEETML_NS}}}f"
    dynamic_cells: set[CellKey] = set()
    unclassified_cells: set[CellKey] = set()
    cell_scans: list[_ArrayFormulaCellScan] = []
    depth = 0
    with archive.open(member) as xml_stream:
        for event, element in _iterparse_ooxml_xml_with_character_data_budget(
            xml_stream
        ):
            if event == "start":
                depth += 1
                if element.tag == cell_tag:
                    cell_scans.append(
                        _ArrayFormulaCellScan(
                            depth=depth,
                            coordinate=element.get("r"),
                            metadata_index=element.get("cm"),
                        )
                    )
                elif (
                    cell_scans
                    and depth == cell_scans[-1].depth + 1
                    and element.tag == formula_tag
                    and not cell_scans[-1].formula_seen
                ):
                    cell_scans[-1].formula_seen = True
                    cell_scans[-1].is_array_formula = element.get("t") == "array"
                continue

            if (
                element.tag == cell_tag
                and cell_scans
                and depth == cell_scans[-1].depth
            ):
                cell = cell_scans.pop()
                if cell.is_array_formula and cell.coordinate:
                    try:
                        metadata_index = int(cell.metadata_index or "0")
                    except ValueError:
                        unclassified_cells.add((sheet, cell.coordinate))
                    else:
                        if metadata_index > 0:
                            if metadata_index in dynamic_indexes:
                                dynamic_cells.add((sheet, cell.coordinate))
                            else:
                                unclassified_cells.add((sheet, cell.coordinate))
            element.clear()
            depth -= 1
    return dynamic_cells, unclassified_cells


def _array_formula_metadata(path: Path) -> _ArrayFormulaMetadata:
    """Inspect raw markers that openpyxl intentionally does not expose."""
    dynamic_cells: set[CellKey] = set()
    unclassified_cells: set[CellKey] = set()
    scanned_sheets: set[str] = set()
    inspection = _DynamicArrayMetadataInspection(
        dynamic_indexes=frozenset(),
        complete=False,
        coverage_signature=None,
        warnings=(),
    )
    try:
        with ZipFile(path) as archive:
            inspection = _dynamic_metadata_indexes(archive)
            if not inspection.complete:
                return _ArrayFormulaMetadata(
                    dynamic_cells=set(),
                    unclassified_cells=set(),
                    scanned_sheets=set(),
                    complete=False,
                    coverage_signature=inspection.coverage_signature,
                    warnings=inspection.warnings,
                )
            for sheet, member in _worksheet_xml_paths(archive).items():
                sheet_dynamic_cells, sheet_unclassified_cells = (
                    _array_formula_worksheet_metadata(
                        archive,
                        sheet,
                        member,
                        inspection.dynamic_indexes,
                    )
                )
                dynamic_cells.update(sheet_dynamic_cells)
                unclassified_cells.update(sheet_unclassified_cells)
                scanned_sheets.add(sheet)
    except (
        BadZipFile,
        ElementTree.ParseError,
        KeyError,
        OSError,
        RuntimeError,
        ValueError,
    ) as error:
        return _ArrayFormulaMetadata(
            dynamic_cells=set(),
            unclassified_cells=set(),
            scanned_sheets=set(),
            complete=False,
            coverage_signature=inspection.coverage_signature,
            warnings=tuple(
                sorted(
                    {
                        *inspection.warnings,
                        "FormulaFence could not inspect array-formula OOXML metadata "
                        f"({type(error).__name__}); fixed CSE output aliases were not traced.",
                    }
                )
            ),
        )
    return _ArrayFormulaMetadata(
        dynamic_cells=dynamic_cells,
        unclassified_cells=unclassified_cells,
        scanned_sheets=scanned_sheets,
        complete=True,
        coverage_signature=None,
        warnings=inspection.warnings,
    )


def _array_formula_range(sheet: str, cell: object) -> ArrayFormulaRange | None:
    """Return one canonical local output range when an array anchor is valid."""
    value = getattr(cell, "value", None)
    ref = getattr(value, "ref", None)
    if not isinstance(ref, str) or not ref.strip():
        return None
    try:
        min_column, min_row, max_column, max_row = range_boundaries(ref)
    except ValueError:
        return None
    if None in {min_column, min_row, max_column, max_row}:
        return None
    anchor = f"{get_column_letter(min_column)}{min_row}"
    if getattr(cell, "coordinate", "").upper() != anchor:
        return None
    endpoint = f"{get_column_letter(max_column)}{max_row}"
    canonical_ref = anchor if anchor == endpoint else f"{anchor}:{endpoint}"
    return ArrayFormulaRange(
        sheet=sheet,
        anchor=anchor,
        ref=canonical_ref,
        min_column=min_column,
        min_row=min_row,
        max_column=max_column,
        max_row=max_row,
    )


def _is_array_formula(cell: object) -> bool:
    """Return whether openpyxl exposed the cell as an OOXML array formula."""
    value = getattr(cell, "value", None)
    return (
        getattr(cell, "data_type", None) == "f"
        and isinstance(getattr(value, "ref", None), str)
        and _formula_text(value) is not None
    )


def _classify_array_formulas(
    workbook: object, metadata: _ArrayFormulaMetadata
) -> _ArrayFormulaClassification:
    """Classify array formulas without treating dynamic extents as fixed."""
    kinds: dict[CellKey, str] = {}
    refs: dict[CellKey, str] = {}
    legacy_ranges: list[ArrayFormulaRange] = []
    dynamic_cells: set[CellKey] = set()
    dynamic_ranges: list[ArrayFormulaRange] = []
    unclassified_cells: set[CellKey] = set()
    warnings = set(metadata.warnings)
    for worksheet in getattr(workbook, "worksheets", ()):
        for cell in worksheet._cells.values():  # noqa: SLF001 - sparse workbook safety
            if not _is_array_formula(cell):
                continue
            location = (worksheet.title, cell.coordinate)
            if not metadata.complete or worksheet.title not in metadata.scanned_sheets:
                kinds[location] = "unclassified"
                unclassified_cells.add(location)
                continue
            if location in metadata.dynamic_cells:
                kinds[location] = "dynamic"
                dynamic_cells.add(location)
                array_range = _array_formula_range(worksheet.title, cell)
                if array_range is None:
                    warnings.add(
                        "FormulaFence could not read one or more observed dynamic-array "
                        "output ranges; non-anchor output aliases were not traced for "
                        "those anchors."
                    )
                    continue
                refs[location] = array_range.ref
                dynamic_ranges.append(array_range)
                continue
            if location in metadata.unclassified_cells:
                kinds[location] = "unclassified"
                unclassified_cells.add(location)
                continue
            array_range = _array_formula_range(worksheet.title, cell)
            if array_range is None:
                kinds[location] = "unclassified"
                unclassified_cells.add(location)
                continue
            kinds[location] = "legacy_cse"
            refs[location] = array_range.ref
            legacy_ranges.append(array_range)

    if unclassified_cells:
        warnings.add(
            "FormulaFence could not classify one or more OOXML array formulas; "
            "fixed CSE output aliases were not traced for those cells."
        )
    return _ArrayFormulaClassification(
        kinds=kinds,
        refs=refs,
        legacy_ranges=tuple(legacy_ranges),
        dynamic_cells=dynamic_cells,
        dynamic_ranges=tuple(dynamic_ranges),
        unclassified_cells=unclassified_cells,
        metadata_complete=metadata.complete,
        metadata_coverage_signature=metadata.coverage_signature,
        warnings=tuple(sorted(warnings)),
    )


def _array_formula_output_dependents(
    legacy_ranges: tuple[ArrayFormulaRange, ...],
    reverse_dependencies: Mapping[CellKey, set[CellKey]],
    range_dependencies: list[RangeDependency],
    dependency_edge_budget: DependencyEdgeBudget,
) -> dict[CellKey, set[CellKey]]:
    """Link a CSE anchor to formulas that read any fixed result member.

    The output range is never expanded into millions of virtual cells. Instead
    each anchor receives direct aliases only to the already-known formula cells
    whose static references intersect that compact range.
    """
    ranges_by_sheet: dict[str, list[ArrayFormulaRange]] = defaultdict(list)
    for array_range in legacy_ranges:
        if array_range.has_multiple_outputs:
            ranges_by_sheet[array_range.sheet].append(array_range)

    dependents: dict[CellKey, set[CellKey]] = defaultdict(set)
    for source, formula_cells in reverse_dependencies.items():
        for array_range in ranges_by_sheet.get(source[0], ()):
            if array_range.contains(source):
                array_dependents = dependents[array_range.location]
                for dependent in formula_cells:
                    if dependent not in array_dependents:
                        dependency_edge_budget.consume()
                        array_dependents.add(dependent)
    for dependency in range_dependencies:
        for array_range in ranges_by_sheet.get(dependency.source_sheet, ()):
            if dependency.intersects(array_range):
                array_dependents = dependents[array_range.location]
                if dependency.dependent not in array_dependents:
                    dependency_edge_budget.consume()
                    array_dependents.add(dependency.dependent)
    return {anchor: cells for anchor, cells in dependents.items() if cells}


def _dynamic_array_output_dependents(
    dynamic_ranges: tuple[ArrayFormulaRange, ...],
    reverse_dependencies: Mapping[CellKey, set[CellKey]],
    range_dependencies: list[RangeDependency],
    dependency_edge_budget: DependencyEdgeBudget,
) -> tuple[
    dict[CellKey, set[CellKey]],
    dict[CellKey, tuple[DynamicArrayOutputReference, ...]],
]:
    """Link observed dynamic spill members to their current formula consumers.

    Dynamic-array output ranges may resize during recalculation, so this is not
    a fixed-range assertion. It records only a formula that currently reads at
    least one non-anchor member, without materializing individual spill cells.
    """
    ranges_by_sheet: dict[str, list[ArrayFormulaRange]] = defaultdict(list)
    for array_range in dynamic_ranges:
        if array_range.has_multiple_outputs:
            ranges_by_sheet[array_range.sheet].append(array_range)

    dependents: dict[CellKey, set[CellKey]] = defaultdict(set)
    references: dict[CellKey, set[DynamicArrayOutputReference]] = defaultdict(set)

    def add_reference(array_range: ArrayFormulaRange, dependent: CellKey) -> None:
        if dependent == array_range.location:
            return
        array_dependents = dependents[array_range.location]
        if dependent not in array_dependents:
            dependency_edge_budget.consume()
            array_dependents.add(dependent)
        references[dependent].add(
            DynamicArrayOutputReference(
                anchor=array_range.location,
                observed_ref=array_range.ref,
            )
        )

    for source, formula_cells in reverse_dependencies.items():
        for array_range in ranges_by_sheet.get(source[0], ()):
            if source != array_range.location and array_range.contains(source):
                for dependent in formula_cells:
                    add_reference(array_range, dependent)
    for dependency in range_dependencies:
        for array_range in ranges_by_sheet.get(dependency.source_sheet, ()):
            if array_range.intersects_non_anchor(dependency):
                add_reference(array_range, dependency.dependent)

    return (
        {anchor: cells for anchor, cells in dependents.items() if cells},
        {
            dependent: tuple(
                sorted(
                    values,
                    key=lambda reference: (
                        reference.anchor[0].casefold(),
                        reference.anchor[1],
                        reference.observed_ref,
                    ),
                )
            )
            for dependent, values in references.items()
            if values
        },
    )


def _formula_text(value: object) -> str | None:
    if isinstance(value, str):
        return value
    # openpyxl represents array formulas as an object in recent versions.
    text = getattr(value, "text", None)
    return text if isinstance(text, str) else None


def _is_what_if_data_table_formula(cell: object) -> bool:
    """Return whether openpyxl exposed an OOXML What-If Data Table master."""
    value = getattr(cell, "value", None)
    formula_type = getattr(value, "t", None)
    return (
        getattr(cell, "data_type", None) == "f"
        and isinstance(formula_type, str)
        and formula_type.casefold() == _WHAT_IF_DATA_TABLE_FORMULA_TYPE.casefold()
    )


def _cell_snapshot(
    sheet: str,
    cell: object,
    *,
    array_formula_kind: str | None = None,
    array_formula_ref: str | None = None,
) -> CellSnapshot:
    coordinate = cell.coordinate
    value = cell.value
    data_type = cell.data_type
    if _is_what_if_data_table_formula(cell):
        # openpyxl stores this control as an object whose default repr embeds a
        # process-local address. The raw scanner carries the real semantics;
        # this stable placeholder preserves ordinary formula add/remove guards
        # without exposing the Data Table's sensitive input references.
        formula = "=TABLE()"
        return CellSnapshot(
            sheet=sheet,
            coordinate=coordinate,
            cell_type="formula",
            value=formula,
            value_type="what_if_data_table_formula",
            formula=formula,
            formula_fingerprint=formula_fingerprint(formula, coordinate),
        )
    formula = _formula_text(value) if data_type == "f" else None
    if formula is not None:
        return CellSnapshot(
            sheet=sheet,
            coordinate=coordinate,
            cell_type="formula",
            value=formula,
            value_type="formula",
            formula=formula,
            formula_fingerprint=formula_fingerprint(formula, coordinate),
            array_formula_kind=array_formula_kind,
            array_formula_ref=array_formula_ref,
        )
    cell_type = "error" if data_type == "e" else "value"
    return CellSnapshot(
        sheet=sheet,
        coordinate=coordinate,
        cell_type=cell_type,
        value=json_safe_value(value),
        value_type=type(value).__name__,
    )


def _calculation_settings(workbook: object) -> dict[str, object]:
    calculation = getattr(workbook, "calculation", None)
    if calculation is None:
        return {}
    return {
        field: value
        for field in _CALCULATION_FIELDS
        if (value := getattr(calculation, field, None)) is not None
    }


def _definition_text(definition: object) -> str:
    attr_text = getattr(definition, "attr_text", None)
    return str(attr_text if attr_text is not None else definition)


def _defined_names(workbook: object) -> dict[str, str]:
    """Inventory workbook and sheet-scoped names with unambiguous local keys."""
    names = getattr(workbook, "defined_names", {})
    result: dict[str, str] = {}
    try:
        items = names.items()
    except AttributeError:
        items = ()
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is None:
            result[str(name)] = _definition_text(definition)
    for worksheet in getattr(workbook, "worksheets", ()):
        worksheet_names = getattr(worksheet, "defined_names", {})
        try:
            worksheet_items = worksheet_names.items()
        except AttributeError:
            continue
        for name, definition in worksheet_items:
            result[f"{worksheet.title}!{name}"] = _definition_text(definition)
    return result


def _named_destination_reference(
    name: str, sheet: str, coordinate: str
) -> ParsedReference | None:
    """Convert one workbook-defined-name destination into a static range."""
    parsed = parse_reference_token(f"{sheet}!{coordinate}")
    if parsed is None:
        return None
    return ParsedReference(
        parsed.sheet,
        parsed.min_column,
        parsed.min_row,
        parsed.max_column,
        parsed.max_row,
        raw=name,
        is_external=parsed.is_external,
    )


def _definition_references(name: str, definition: object) -> tuple[ParsedReference, ...]:
    """Return only static destinations from an ordinary defined name."""
    try:
        destinations = list(definition.destinations)
    except Exception:  # pragma: no cover - malformed name syntax is workbook-specific
        return ()
    return tuple(
        reference
        for sheet, coordinate in destinations
        if (reference := _named_destination_reference(name, sheet, coordinate)) is not None
    )


@dataclass(frozen=True)
class _FormulaDefinedName:
    """A defined name whose OOXML text is an Excel formula expression."""

    key: str
    formula: str
    scope: str | None


_NameMapValue = TypeVar("_NameMapValue")
_NameDefinitionIdentity = tuple[str | None, str]
_FORMULA_DEFINED_NAME_MARKER_PREFIXES = (
    "FORMULAFENCE_EXTERNAL_ACTION_MARKER_",
    "FORMULAFENCE_FORMULA_DDE_LINK_MARKER_",
    "FORMULAFENCE_OFFICE_CUSTOM_MARKER_",
    "FORMULAFENCE_UNQUALIFIED_RUNTIME_FUNCTION_MARKER_",
    "FORMULAFENCE_CODE_RESOURCE_REGISTRATION_MARKER_",
    "FORMULAFENCE_FORMULA_DEFINED_XLM_REGISTRATION_MARKER_",
    "FORMULAFENCE_FORMULA_DEFINED_XLM_EVALUATION_MARKER_",
    "FORMULAFENCE_FORMULA_DEFINED_XLM_ACTION_MARKER_",
    "FORMULAFENCE_FORMULA_DEFINED_XLM_GET_CELL_MARKER_",
    "FORMULAFENCE_FORMULA_DEFINED_XLM_ENVIRONMENT_INFORMATION_MARKER_",
    "FORMULAFENCE_FORMULA_ENVIRONMENT_INFORMATION_MARKER_",
)
_FormulaDefinedNameLedger = tuple[tuple[str, ...], ...]
_EMPTY_FORMULA_DEFINED_NAME_LEDGER: _FormulaDefinedNameLedger = (
    (),
) * len(_FORMULA_DEFINED_NAME_MARKER_PREFIXES)


class _OverlayNameMapping(Mapping[str, _NameMapValue]):
    """A live, constant-time lookup overlay for scoped formula-name state.

    ``inspect_formula`` only needs membership and lookup.  Materializing every
    visible workbook/local name map for every formula-defined name turns the
    allowed catalog into quadratic work.  This overlay keeps a fixed small
    lookup chain over mutable resolution dictionaries instead.  Its explicit
    truthiness avoids ``Mapping.__len__`` work when ``inspect_formula`` uses a
    supplied map in a boolean context.
    """

    def __init__(self, *mappings: Mapping[str, _NameMapValue]) -> None:
        self._mappings = mappings

    def __bool__(self) -> bool:
        return any(bool(mapping) for mapping in self._mappings)

    def __contains__(self, key: object) -> bool:
        return any(key in mapping for mapping in self._mappings)

    def __getitem__(self, key: str) -> _NameMapValue:
        for mapping in self._mappings:
            if key in mapping:
                return mapping[key]
        raise KeyError(key)

    def get(self, key: str, default=None):
        for mapping in self._mappings:
            if key in mapping:
                return mapping[key]
        return default

    def __iter__(self):
        seen: set[str] = set()
        for mapping in self._mappings:
            for key in mapping:
                if key not in seen:
                    seen.add(key)
                    yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)


class _FilteredNameMapping(Mapping[str, _NameMapValue]):
    """Expose one live name map through its formula/LAMBDA kind boundary.

    The external-name resolver must keep ordinary formula names out of the
    named-LAMBDA path and vice versa.  Copying the growing resolved map for
    each definition turns that otherwise constant-time distinction into
    quadratic work, so this filter keeps the existing map live instead.
    """

    def __init__(
        self,
        mapping: Mapping[str, _NameMapValue],
        named_lambda_keys: frozenset[str],
        *,
        include_named_lambdas: bool,
    ) -> None:
        self._mapping = mapping
        self._named_lambda_keys = named_lambda_keys
        self._include_named_lambdas = include_named_lambdas

    def __bool__(self) -> bool:
        return bool(self._mapping)

    def _visible(self, key: object) -> bool:
        return isinstance(key, str) and (
            (key in self._named_lambda_keys) == self._include_named_lambdas
        )

    def __contains__(self, key: object) -> bool:
        return self._visible(key) and key in self._mapping

    def __getitem__(self, key: str) -> _NameMapValue:
        if key not in self:
            raise KeyError(key)
        return self._mapping[key]

    def get(self, key: str, default=None):
        if key not in self:
            return default
        return self._mapping[key]

    def __iter__(self):
        return (
            key
            for key in self._mapping
            if self._visible(key)
        )

    def __len__(self) -> int:
        return sum(1 for _ in self)


class _ExternalAliasNameMapping(Mapping[str, _NameMapValue]):
    """Resolve mutable external endpoint aliases without rebuilding a map.

    Formula-defined external endpoints become available one definition at a
    time.  ``inspect_formula`` only needs membership and ``get``; resolving a
    requested alias through the existing direct and newly resolved maps avoids
    copying all currently known endpoints for every definition.  An optional
    formula/LAMBDA filter preserves the separate invocation semantics used by
    the prior materialized maps.
    """

    _missing = object()

    def __init__(
        self,
        direct: Mapping[str, _NameMapValue],
        resolved: Mapping[str, _NameMapValue],
        aliases: Mapping[str, str],
        *,
        named_lambda_keys: frozenset[str] = frozenset(),
        include_named_lambdas: bool | None = None,
    ) -> None:
        self._direct = direct
        self._resolved = resolved
        self._aliases = aliases
        self._named_lambda_keys = named_lambda_keys
        self._include_named_lambdas = include_named_lambdas

    def __bool__(self) -> bool:
        return bool(self._direct) or bool(self._resolved)

    def _visible(self, key: object) -> bool:
        if not isinstance(key, str):
            return False
        if self._include_named_lambdas is None:
            return True
        return (
            (key in self._named_lambda_keys) == self._include_named_lambdas
        )

    def _value_for(self, key: str, default):
        if not self._visible(key):
            return default
        current = key
        visited: set[str] = set()
        while current not in visited:
            if current in self._resolved:
                return self._resolved[current]
            if current in self._direct:
                return self._direct[current]
            visited.add(current)
            target = self._aliases.get(current)
            if target is None:
                break
            current = target
        return default

    def __contains__(self, key: object) -> bool:
        return (
            isinstance(key, str)
            and self._value_for(key, self._missing) is not self._missing
        )

    def __getitem__(self, key: str) -> _NameMapValue:
        value = self._value_for(key, self._missing)
        if value is self._missing:
            raise KeyError(key)
        return value

    def get(self, key: str, default=None):
        return self._value_for(key, default)

    def __iter__(self):
        seen: set[str] = set()
        for mapping in (self._resolved, self._direct, self._aliases):
            for key in mapping:
                if key in seen:
                    continue
                seen.add(key)
                if self._value_for(key, self._missing) is not self._missing:
                    yield key

    def __len__(self) -> int:
        return sum(1 for _ in self)


class _NameMarkerMapping(Mapping[str, tuple[str, ...]]):
    """Generate one marker ledger through reusable name-to-identity overlays."""

    def __init__(
        self,
        identities: Mapping[str, _NameDefinitionIdentity],
        definition_indexes: Mapping[_NameDefinitionIdentity, int],
        marker_prefix: str,
    ) -> None:
        self._identities = identities
        self._definition_indexes = definition_indexes
        self._marker_prefix = marker_prefix

    def __bool__(self) -> bool:
        return bool(self._identities)

    def __contains__(self, key: object) -> bool:
        return key in self._identities

    def __getitem__(self, key: str) -> tuple[str, ...]:
        return (
            f"{self._marker_prefix}"
            f"{self._definition_indexes[self._identities[key]]}",
        )

    def get(self, key: str, default=None):
        if key not in self._identities:
            return default
        return self[key]

    def __iter__(self):
        return iter(self._identities)

    def __len__(self) -> int:
        return len(self._identities)


class _NameLedgerMapping(Mapping[str, tuple[str, ...]]):
    """Expose one nonempty propagated ledger through name-identity overlays.

    A formula inspector needs lookup only. Keeping a mapping entry for every
    formula-defined name whose ledger is empty both retains needless state and
    makes each worksheet's visible ledger map expensive to assemble. This view
    maps known names back to their component lazily and behaves as absent for
    an empty ledger, matching the caller's existing ``.get(..., ())`` contract.
    """

    def __init__(
        self,
        identities: Mapping[str, _NameDefinitionIdentity],
        component_by_definition: Mapping[_NameDefinitionIdentity, int],
        component_ledgers: Mapping[int, _FormulaDefinedNameLedger],
        ledger_index: int,
    ) -> None:
        self._identities = identities
        self._component_by_definition = component_by_definition
        self._component_ledgers = component_ledgers
        self._ledger_index = ledger_index

    def __bool__(self) -> bool:
        return bool(self._component_ledgers)

    def _values_for(self, key: str) -> tuple[str, ...]:
        identity = self._identities.get(key)
        if identity is None:
            return ()
        component = self._component_by_definition.get(identity)
        if component is None:
            return ()
        return self._component_ledgers.get(
            component, _EMPTY_FORMULA_DEFINED_NAME_LEDGER
        )[self._ledger_index]

    def __contains__(self, key: object) -> bool:
        return isinstance(key, str) and bool(self._values_for(key))

    def __getitem__(self, key: str) -> tuple[str, ...]:
        values = self._values_for(key)
        if not values:
            raise KeyError(key)
        return values

    def get(self, key: str, default=None):
        values = self._values_for(key)
        return values or default

    def __iter__(self):
        return (
            key for key in self._identities if self._values_for(key)
        )

    def __len__(self) -> int:
        return sum(1 for _ in self)


def _formula_defined_name(
    name: str, definition: object, scope: str | None
) -> _FormulaDefinedName | None:
    """Return a formula-valued defined name, excluding ordinary destinations.

    OOXML stores the text of a defined-name formula without its leading equals
    sign, while older writer output commonly retains one. ``DefinedName.type``
    lets us preserve ordinary A1 destinations and normalize either formula
    spelling before sending it through the formula tokenizer.
    """
    attr_text = getattr(definition, "attr_text", None)
    if not isinstance(attr_text, str):
        return None
    formula = attr_text.strip()
    if not formula:
        return None
    if not formula.startswith("="):
        try:
            definition_type = getattr(definition, "type", None)
        except Exception:  # pragma: no cover - malformed name text is workbook-specific
            definition_type = None
        if definition_type == "RANGE":
            return None
        formula = f"={formula}"
    return _FormulaDefinedName(reference_lookup_key(name), formula, scope)


def _qualified_name_key(sheet: str, name: str) -> str:
    """Build a lookup key for a sheet-local name without quote ambiguity."""
    escaped_sheet = sheet.replace("'", "''")
    return reference_lookup_key(f"'{escaped_sheet}'!{name}")


def _named_reference_maps(
    workbook: object,
    structured_tables: Mapping[str, StructuredTable],
    sheet_order: tuple[str, ...],
    formula_defined_name_state_budget: FormulaDefinedNameStateBudget,
) -> tuple[
    # References and named-LAMBDA references.
    dict[str, tuple[ParsedReference, ...]],
    dict[str, dict[str, tuple[ParsedReference, ...]]],
    dict[str, tuple[ParsedReference, ...] | None],
    dict[str, dict[str, tuple[ParsedReference, ...] | None]],
    # Formula external actions.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Direct DDE-style formula links.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Office custom-function candidates.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    # Worksheet REGISTER.ID calls.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Formula-defined XLM REGISTER calls.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Formula-defined XLM EVALUATE calls.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Formula-defined XLM selected actions.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Formula-defined XLM GET.CELL calls.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Formula-defined XLM environment-information calls.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
    # Native formula environment-information calls.
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    dict[str, tuple[str, ...]],
    dict[str, dict[str, tuple[str, ...]]],
    tuple[tuple[str, str], ...],
]:
    """Build dependency and sensitive-call maps for formula-defined names.

    Formula-valued names are expanded only when every dependency is statically
    visible and internal. Relative references, dynamic functions, unresolved
    tokens, recursive LAMBDAs, external links, and 3-D spans remain unresolved
    at a use site instead of producing a guessed graph edge. Formula external
    actions, direct DDE links, namespaced custom-function candidates, worksheet
    ``REGISTER.ID`` calls, XLM ``REGISTER`` / ``EVALUATE`` / selected action /
    ``GET.CELL`` calls, and native ``CELL`` / ``INFO`` calls stored in
    definitions are propagated separately through those definitions so a named
    LAMBDA cannot hide a stored boundary from the formula-cell ledgers.
    """
    workbook_names = getattr(workbook, "defined_names", {})
    global_references: dict[str, tuple[ParsedReference, ...]] = {}
    global_formulas: dict[str, _FormulaDefinedName] = {}
    global_lambdas: dict[str, _FormulaDefinedName] = {}
    try:
        workbook_items = workbook_names.items()
    except AttributeError:
        workbook_items = ()
    for name, definition in workbook_items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        formula_definition = _formula_defined_name(str(name), definition, None)
        if formula_definition is not None:
            target = (
                global_lambdas
                if lambda_parameter_count(formula_definition.formula) is not None
                else global_formulas
            )
            target[formula_definition.key] = formula_definition
            continue
        references = _definition_references(str(name), definition)
        if references:
            global_references[reference_lookup_key(str(name))] = references

    local_references: dict[str, dict[str, tuple[ParsedReference, ...]]] = {}
    local_formulas: dict[str, dict[str, _FormulaDefinedName]] = {}
    local_lambdas: dict[str, dict[str, _FormulaDefinedName]] = {}
    sheet_titles: dict[str, str] = {}
    for worksheet in getattr(workbook, "worksheets", ()):
        scope = worksheet.title.casefold()
        sheet_titles[scope] = worksheet.title
        worksheet_names = getattr(worksheet, "defined_names", {})
        try:
            worksheet_items = worksheet_names.items()
        except AttributeError:
            continue
        sheet_references: dict[str, tuple[ParsedReference, ...]] = {}
        for name, definition in worksheet_items:
            formula_definition = _formula_defined_name(str(name), definition, scope)
            if formula_definition is not None:
                target = (
                    local_lambdas
                    if lambda_parameter_count(formula_definition.formula) is not None
                    else local_formulas
                )
                target.setdefault(scope, {})[formula_definition.key] = formula_definition
                continue
            references = _definition_references(str(name), definition)
            if not references:
                continue
            sheet_references[reference_lookup_key(str(name))] = references
        if sheet_references:
            local_references[scope] = sheet_references

    qualified_formulas = {
        _qualified_name_key(sheet_titles[scope], key): definition
        for scope, definitions in local_formulas.items()
        for key, definition in definitions.items()
    }
    qualified_lambdas = {
        _qualified_name_key(sheet_titles[scope], key): definition
        for scope, definitions in local_lambdas.items()
        for key, definition in definitions.items()
    }

    def identity_for(definition: _FormulaDefinedName) -> tuple[str | None, str]:
        return definition.scope, definition.key

    formula_definition_identities = {
        identity_for(definition)
        for definition in global_formulas.values()
    } | {
        identity_for(definition)
        for definitions in local_formulas.values()
        for definition in definitions.values()
    }
    local_scopes = set(local_references) | set(local_formulas) | set(local_lambdas)

    # Keep static ordinary names and newly resolved formula names in live
    # overlays. Rebuilding this complete catalog at every resolver call made a
    # compact workbook with many formula-defined names quadratic to inspect.
    static_global_reference_values = dict(global_references)
    for local_scope, references in local_references.items():
        for key, values in references.items():
            static_global_reference_values[
                _qualified_name_key(sheet_titles[local_scope], key)
            ] = values
    resolved_reference_values: dict[str, tuple[ParsedReference, ...]] = {}
    resolved_local_reference_values = {
        scope: {} for scope in local_scopes
    }
    global_reference_view = _OverlayNameMapping(
        resolved_reference_values,
        static_global_reference_values,
    )
    scoped_reference_views = {
        scope: _OverlayNameMapping(
            resolved_local_reference_values[scope],
            local_references.get(scope, {}),
            global_reference_view,
        )
        for scope in local_scopes
    }

    # A known named LAMBDA must remain visible even before it is safely
    # resolvable: ``None`` is FormulaFence's explicit coverage-gap signal for
    # that callable. The values update in place as LAMBDAs resolve.
    global_function_values: dict[str, tuple[ParsedReference, ...] | None] = {
        key: None for key in global_lambdas
    }
    local_function_values: dict[
        str, dict[str, tuple[ParsedReference, ...] | None]
    ] = {scope: {} for scope in local_scopes}
    for local_scope, definitions in local_lambdas.items():
        for key in definitions:
            global_function_values[_qualified_name_key(sheet_titles[local_scope], key)] = (
                None
            )
            local_function_values[local_scope][key] = None
    global_function_view = _OverlayNameMapping(global_function_values)
    scoped_function_views = {
        scope: _OverlayNameMapping(
            local_function_values[scope],
            global_function_view,
        )
        for scope in local_scopes
    }

    resolved_definitions: dict[tuple[str | None, str], tuple[ParsedReference, ...]] = {}
    resolving: set[tuple[str | None, str]] = set()
    failed: set[tuple[str | None, str]] = set()

    def cached_references(
        definition: _FormulaDefinedName,
    ) -> tuple[ParsedReference, ...] | None:
        return resolved_definitions.get(identity_for(definition))

    def has_cached_references(definition: _FormulaDefinedName) -> bool:
        return identity_for(definition) in resolved_definitions

    def visible_references(
        scope: str | None,
    ) -> Mapping[str, tuple[ParsedReference, ...]]:
        return scoped_reference_views.get(scope, global_reference_view)

    def visible_named_functions(
        scope: str | None,
    ) -> Mapping[str, tuple[ParsedReference, ...] | None]:
        return scoped_function_views.get(scope, global_function_view)

    def record_resolved_definition(
        definition: _FormulaDefinedName,
        references: tuple[ParsedReference, ...],
    ) -> None:
        """Expose one completed definition through the reusable name views."""
        identity = identity_for(definition)
        if identity in formula_definition_identities:
            if definition.scope is None:
                resolved_reference_values[definition.key] = references
            else:
                resolved_reference_values[
                    _qualified_name_key(sheet_titles[definition.scope], definition.key)
                ] = references
                resolved_local_reference_values[definition.scope][definition.key] = references
            return
        if definition.scope is None:
            global_function_values[definition.key] = references
        else:
            global_function_values[
                _qualified_name_key(sheet_titles[definition.scope], definition.key)
            ] = references
            local_function_values[definition.scope][definition.key] = references

    def named_definition_for(
        token: str, scope: str | None
    ) -> _FormulaDefinedName | None:
        key = reference_lookup_key(token)
        if qualified := qualified_formulas.get(key):
            return qualified
        if qualified := qualified_lambdas.get(key):
            return qualified
        if "!" in key:
            return None
        if scope is not None and (local := local_formulas.get(scope, {}).get(key)):
            return local
        if scope is not None and (local := local_lambdas.get(scope, {}).get(key)):
            return local
        return global_formulas.get(key) or global_lambdas.get(key)

    def resolve_definition(
        definition: _FormulaDefinedName,
    ) -> tuple[ParsedReference, ...] | None:
        identity = identity_for(definition)
        if has_cached_references(definition):
            return cached_references(definition)
        if identity in failed or identity in resolving:
            return None

        resolving.add(identity)
        resolved_references: tuple[ParsedReference, ...] | None = None
        try:
            inspection = inspect_formula(
                definition.formula,
                named_references=visible_references(definition.scope),
                structured_tables=structured_tables,
                sheet_order=sheet_order,
                named_function_references=visible_named_functions(definition.scope),
            )
            can_expand = not (
                has_broken_reference(definition.formula)
                or inspection.tokenization_failed
                or inspection.dynamic_reference_functions
                or inspection.three_d_reference_tokens
                or inspection.spill_reference_tokens
                or inspection.implicit_intersection_tokens
            )
            if can_expand:
                for token in inspection.unresolved_range_tokens:
                    dependency = named_definition_for(token, definition.scope)
                    if dependency is None or resolve_definition(dependency) is None:
                        can_expand = False
                        break
            if can_expand:
                inspection = inspect_formula(
                    definition.formula,
                    named_references=visible_references(definition.scope),
                    structured_tables=structured_tables,
                    sheet_order=sheet_order,
                    named_function_references=visible_named_functions(definition.scope),
                )
                if (
                    inspection.unresolved_range_tokens
                    or inspection.tokenization_failed
                    or inspection.dynamic_reference_functions
                    or inspection.three_d_reference_tokens
                    or inspection.spill_reference_tokens
                    or inspection.implicit_intersection_tokens
                    or any(
                        reference.is_external or reference.sheet is None
                        for reference in inspection.references
                    )
                ):
                    can_expand = False
            if can_expand:
                resolved_references = tuple(dict.fromkeys(inspection.references))
        finally:
            resolving.remove(identity)

        if resolved_references is None:
            failed.add(identity)
            return None
        resolved_definitions[identity] = resolved_references
        record_resolved_definition(definition, resolved_references)
        return resolved_references

    for definition in global_formulas.values():
        resolve_definition(definition)
    for definition in global_lambdas.values():
        resolve_definition(definition)
    for definitions in local_formulas.values():
        for definition in definitions.values():
            resolve_definition(definition)
    for definitions in local_lambdas.values():
        for definition in definitions.values():
            resolve_definition(definition)

    all_formula_definitions = tuple(global_formulas.values()) + tuple(
        definition
        for definitions in local_formulas.values()
        for definition in definitions.values()
    )
    all_lambda_definitions = tuple(global_lambdas.values()) + tuple(
        definition
        for definitions in local_lambdas.values()
        for definition in definitions.values()
    )
    all_definitions = all_formula_definitions + all_lambda_definitions
    definition_identities = tuple(identity_for(definition) for definition in all_definitions)
    definition_indexes = {
        identity: index for index, identity in enumerate(definition_identities)
    }

    # Marker propagation has the same visibility rules as references and
    # named functions. Keep one identity-to-index catalog and generate each
    # marker only when formula inspection actually resolves a name. Retaining
    # eleven identity-to-marker maps plus one marker-to-identity dictionary
    # otherwise made a valid 100,000-name catalog disproportionately expensive.
    formula_name_identities: dict[str, _NameDefinitionIdentity] = {
        key: identity_for(definition)
        for key, definition in global_formulas.items()
    }
    local_formula_name_identities: dict[
        str, dict[str, _NameDefinitionIdentity]
    ] = {scope: {} for scope in local_scopes}
    for local_scope, definitions in local_formulas.items():
        for key, definition in definitions.items():
            identity = identity_for(definition)
            formula_name_identities[
                _qualified_name_key(sheet_titles[local_scope], key)
            ] = identity
            local_formula_name_identities[local_scope][key] = identity
    global_formula_identity_view = _OverlayNameMapping(formula_name_identities)
    scoped_formula_identity_views = {
        scope: _OverlayNameMapping(
            local_formula_name_identities[scope],
            global_formula_identity_view,
        )
        for scope in local_scopes
    }

    function_name_identities: dict[str, _NameDefinitionIdentity] = {
        key: identity_for(definition)
        for key, definition in global_lambdas.items()
    }
    local_function_name_identities: dict[
        str, dict[str, _NameDefinitionIdentity]
    ] = {scope: {} for scope in local_scopes}
    for local_scope, definitions in local_lambdas.items():
        for key, definition in definitions.items():
            identity = identity_for(definition)
            function_name_identities[
                _qualified_name_key(sheet_titles[local_scope], key)
            ] = identity
            local_function_name_identities[local_scope][key] = identity
    global_function_identity_view = _OverlayNameMapping(function_name_identities)
    scoped_function_identity_views = {
        scope: _OverlayNameMapping(
            local_function_name_identities[scope],
            global_function_identity_view,
        )
        for scope in local_scopes
    }

    def marker_visibility_maps(marker_prefix: str):
        """Expose one lazy marker kind through the shared visibility catalogs."""
        global_formula_view = _NameMarkerMapping(
            global_formula_identity_view,
            definition_indexes,
            marker_prefix,
        )
        scoped_formula_views = {
            scope: _NameMarkerMapping(
                scoped_formula_identity_views[scope],
                definition_indexes,
                marker_prefix,
            )
            for scope in local_scopes
        }
        global_function_marker_view = _NameMarkerMapping(
            global_function_identity_view,
            definition_indexes,
            marker_prefix,
        )
        scoped_function_marker_views = {
            scope: _NameMarkerMapping(
                scoped_function_identity_views[scope],
                definition_indexes,
                marker_prefix,
            )
            for scope in local_scopes
        }
        return (
            global_formula_view,
            scoped_formula_views,
            global_function_marker_view,
            scoped_function_marker_views,
        )

    def marker_visibility_for_scope(scope: str | None, visibility_maps):
        (
            global_formula_view,
            scoped_formula_views,
            global_function_marker_view,
            scoped_function_marker_views,
        ) = visibility_maps
        return (
            scoped_formula_views.get(scope, global_formula_view),
            scoped_function_marker_views.get(scope, global_function_marker_view),
        )

    marker_visibility_sets = tuple(
        marker_visibility_maps(marker_prefix)
        for marker_prefix in _FORMULA_DEFINED_NAME_MARKER_PREFIXES
    )

    marker_index_digit_limit = (
        len(str(len(definition_identities) - 1)) if definition_identities else 0
    )

    def identity_for_marker(marker: object) -> _NameDefinitionIdentity | None:
        """Recover one generated marker without retaining a reverse ledger."""
        if not isinstance(marker, str):
            return None
        for marker_prefix in _FORMULA_DEFINED_NAME_MARKER_PREFIXES:
            if not marker.startswith(marker_prefix):
                continue
            index_text = marker.removeprefix(marker_prefix)
            if (
                not index_text
                or len(index_text) > marker_index_digit_limit
                or not index_text.isascii()
                or not index_text.isdecimal()
            ):
                return None
            index = int(index_text)
            if str(index) != index_text or index >= len(definition_identities):
                return None
            return definition_identities[index]
        return None

    direct_ledgers: dict[_NameDefinitionIdentity, _FormulaDefinedNameLedger] = {}
    definition_dependencies: dict[
        tuple[str | None, str], tuple[tuple[str | None, str], ...]
    ] = {}
    for definition in all_definitions:
        (
            (
                external_action_formula_marker_view,
                external_action_function_marker_view,
            ),
            (dde_formula_marker_view, dde_function_marker_view),
            (custom_function_formula_marker_view, custom_function_function_marker_view),
            (
                unqualified_runtime_formula_marker_view,
                unqualified_runtime_function_marker_view,
            ),
            (
                code_resource_formula_marker_view,
                code_resource_function_marker_view,
            ),
            (xlm_registration_formula_marker_view, xlm_registration_function_marker_view),
            (xlm_evaluation_formula_marker_view, xlm_evaluation_function_marker_view),
            (xlm_action_formula_marker_view, xlm_action_function_marker_view),
            (xlm_get_cell_formula_marker_view, xlm_get_cell_function_marker_view),
            (xlm_environment_formula_marker_view, xlm_environment_function_marker_view),
            (
                native_environment_formula_marker_view,
                native_environment_function_marker_view,
            ),
        ) = tuple(
            marker_visibility_for_scope(definition.scope, visibility_maps)
            for visibility_maps in marker_visibility_sets
        )
        inspection = inspect_formula(
            definition.formula,
            named_references=visible_references(definition.scope),
            structured_tables=structured_tables,
            sheet_order=sheet_order,
            named_function_references=visible_named_functions(definition.scope),
            named_formula_external_action_functions=external_action_formula_marker_view,
            named_function_formula_external_action_functions=(
                external_action_function_marker_view
            ),
            named_formula_dde_link_markers=dde_formula_marker_view,
            named_function_formula_dde_link_markers=dde_function_marker_view,
            named_custom_function_candidates=custom_function_formula_marker_view,
            named_function_custom_function_candidates=custom_function_function_marker_view,
            named_unqualified_runtime_function_candidates=(
                unqualified_runtime_formula_marker_view
            ),
            named_function_unqualified_runtime_function_candidates=(
                unqualified_runtime_function_marker_view
            ),
            named_worksheet_code_resource_registration_functions=(
                code_resource_formula_marker_view
            ),
            named_function_worksheet_code_resource_registration_functions=(
                code_resource_function_marker_view
            ),
            named_formula_defined_xlm_registration_functions=(
                xlm_registration_formula_marker_view
            ),
            named_function_formula_defined_xlm_registration_functions=(
                xlm_registration_function_marker_view
            ),
            named_formula_defined_xlm_evaluation_functions=xlm_evaluation_formula_marker_view,
            named_function_formula_defined_xlm_evaluation_functions=(
                xlm_evaluation_function_marker_view
            ),
            named_formula_defined_xlm_action_functions=xlm_action_formula_marker_view,
            named_function_formula_defined_xlm_action_functions=(
                xlm_action_function_marker_view
            ),
            named_formula_defined_xlm_get_cell_functions=xlm_get_cell_formula_marker_view,
            named_function_formula_defined_xlm_get_cell_functions=(
                xlm_get_cell_function_marker_view
            ),
            named_formula_defined_xlm_environment_information_functions=(
                xlm_environment_formula_marker_view
            ),
            named_function_formula_defined_xlm_environment_information_functions=(
                xlm_environment_function_marker_view
            ),
            named_formula_environment_information_functions=(
                native_environment_formula_marker_view
            ),
            named_function_formula_environment_information_functions=(
                native_environment_function_marker_view
            ),
            inspect_formula_defined_xlm_registrations=True,
            inspect_formula_defined_xlm_evaluations=True,
            inspect_formula_defined_xlm_actions=True,
            inspect_formula_defined_xlm_get_cell_calls=True,
            inspect_formula_defined_xlm_environment_information_calls=True,
        )
        identity = identity_for(definition)
        direct_external_actions = tuple(
            function
            for function in inspection.external_action_functions
            if identity_for_marker(function) is None
        )
        direct_dde_links = tuple(
            marker
            for marker in inspection.formula_dde_link_markers
            if identity_for_marker(marker) is None
        )
        direct_custom_candidates = tuple(
            candidate
            for candidate in inspection.office_custom_function_candidates
            if identity_for_marker(candidate) is None
        )
        direct_unqualified_runtime_candidates = tuple(
            candidate
            for candidate in inspection.unqualified_runtime_function_candidates
            if identity_for_marker(candidate) is None
        )
        direct_code_resource_registrations = tuple(
            function
            for function in inspection.worksheet_code_resource_registration_functions
            if identity_for_marker(function) is None
        )
        direct_xlm_registrations = tuple(
            function
            for function in inspection.formula_defined_xlm_registration_functions
            if identity_for_marker(function) is None
        )
        direct_xlm_evaluations = tuple(
            function
            for function in inspection.formula_defined_xlm_evaluation_functions
            if identity_for_marker(function) is None
        )
        direct_xlm_actions = tuple(
            function
            for function in inspection.formula_defined_xlm_action_functions
            if identity_for_marker(function) is None
        )
        direct_xlm_get_cell_calls = tuple(
            function
            for function in inspection.formula_defined_xlm_get_cell_functions
            if identity_for_marker(function) is None
        )
        direct_xlm_environment_information_calls = tuple(
            function
            for function in inspection.formula_defined_xlm_environment_information_functions
            if identity_for_marker(function) is None
        )
        direct_environment_information_calls = tuple(
            signal
            for signal in inspection.formula_environment_information_signal_values
            if identity_for_marker(signal) is None
        )
        dependencies = tuple(
            dict.fromkeys(
                marker_identity
                for marker in (
                    inspection.external_action_functions
                    + inspection.formula_dde_link_markers
                    + inspection.office_custom_function_candidates
                    + inspection.unqualified_runtime_function_candidates
                    + inspection.worksheet_code_resource_registration_functions
                    + inspection.formula_defined_xlm_registration_functions
                    + inspection.formula_defined_xlm_evaluation_functions
                    + inspection.formula_defined_xlm_action_functions
                    + inspection.formula_defined_xlm_get_cell_functions
                    + inspection.formula_defined_xlm_environment_information_functions
                    + inspection.formula_environment_information_signal_values
                )
                if (marker_identity := identity_for_marker(marker)) is not None
            )
        )
        formula_defined_name_state_budget.consume(
            len(dependencies)
            + sum(
                len(values)
                for values in (
                    direct_external_actions,
                    direct_dde_links,
                    direct_custom_candidates,
                    direct_unqualified_runtime_candidates,
                    direct_code_resource_registrations,
                    direct_xlm_registrations,
                    direct_xlm_evaluations,
                    direct_xlm_actions,
                    direct_xlm_get_cell_calls,
                    direct_xlm_environment_information_calls,
                    direct_environment_information_calls,
                )
            )
        )
        direct_ledger: _FormulaDefinedNameLedger = (
            direct_external_actions,
            direct_dde_links,
            direct_custom_candidates,
            direct_unqualified_runtime_candidates,
            direct_code_resource_registrations,
            direct_xlm_registrations,
            direct_xlm_evaluations,
            direct_xlm_actions,
            direct_xlm_get_cell_calls,
            direct_xlm_environment_information_calls,
            direct_environment_information_calls,
        )
        if any(direct_ledger):
            direct_ledgers[identity] = direct_ledger
        if dependencies:
            definition_dependencies[identity] = dependencies

    # Collapse recursive definition groups before expanding their candidates.
    # That preserves repeated calls in ordinary acyclic definitions while a
    # recursive named LAMBDA contributes each stored callable once instead of
    # growing an unbounded synthetic inventory.
    has_direct_ledger = bool(direct_ledgers)
    reverse_dependencies: dict[
        tuple[str | None, str], list[tuple[str | None, str]]
    ] = (
        {identity: [] for identity in definition_identities}
        if has_direct_ledger
        else {}
    )
    if has_direct_ledger:
        for identity, dependencies in definition_dependencies.items():
            for dependency in dependencies:
                reverse_dependencies[dependency].append(identity)

    visited: set[tuple[str | None, str]] = set()
    finish_order: list[tuple[str | None, str]] = []
    for root in (definition_identities if has_direct_ledger else ()):
        if root in visited:
            continue
        visited.add(root)
        traversal: list[tuple[tuple[str | None, str], int]] = [(root, 0)]
        while traversal:
            identity, next_dependency = traversal[-1]
            dependencies = definition_dependencies.get(identity, ())
            if next_dependency < len(dependencies):
                dependency = dependencies[next_dependency]
                traversal[-1] = (identity, next_dependency + 1)
                if dependency not in visited:
                    visited.add(dependency)
                    traversal.append((dependency, 0))
                continue
            finish_order.append(identity)
            traversal.pop()

    components: list[tuple[tuple[str | None, str], ...]] = []
    component_by_definition: dict[tuple[str | None, str], int] = {}
    for root in reversed(finish_order):
        if root in component_by_definition:
            continue
        members: list[tuple[str | None, str]] = []
        traversal = [root]
        component_by_definition[root] = len(components)
        while traversal:
            identity = traversal.pop()
            members.append(identity)
            for dependency in reverse_dependencies[identity]:
                if dependency not in component_by_definition:
                    component_by_definition[dependency] = len(components)
                    traversal.append(dependency)
        components.append(tuple(sorted(members, key=definition_indexes.__getitem__)))

    component_dependencies: dict[int, tuple[int, ...]] = {}
    component_direct_ledgers: dict[int, _FormulaDefinedNameLedger] = {}
    for component, members in enumerate(components):
        if has_direct_ledger and any(
            identity in direct_ledgers for identity in members
        ):
            direct_ledger: _FormulaDefinedNameLedger = tuple(
                tuple(
                    entry
                    for identity in members
                    for entry in direct_ledgers.get(
                        identity, _EMPTY_FORMULA_DEFINED_NAME_LEDGER
                    )[ledger_index]
                )
                for ledger_index in range(len(_FORMULA_DEFINED_NAME_MARKER_PREFIXES))
            )
            component_direct_ledgers[component] = direct_ledger
        component_dependencies[component] = tuple(
            dependency_component
            for identity in members
            for dependency in definition_dependencies.get(identity, ())
            if (dependency_component := component_by_definition[dependency]) != component
        )

    component_dependents: dict[int, set[int]] = {
        component: set() for component in component_dependencies
    }
    remaining_component_dependencies = {
        component: set(dependencies)
        for component, dependencies in component_dependencies.items()
    }
    for component, dependencies in remaining_component_dependencies.items():
        for dependency in dependencies:
            component_dependents[dependency].add(component)
    ready_components = [
        component
        for component, dependencies in remaining_component_dependencies.items()
        if not dependencies
    ]
    heapq.heapify(ready_components)
    component_ledgers: dict[int, _FormulaDefinedNameLedger] = {}

    def propagated_component_entries(
        direct_entries: tuple[str, ...],
        dependencies: tuple[int, ...],
        ledger_index: int,
    ) -> tuple[str, ...]:
        """Retain one component's inherited sensitive-call ledger safely.

        Each entry remains distinct because separate formula-defined names can
        represent separate runtime calls.  Reserve the full derived tuple
        before constructing it, so a long acyclic chain fails closed rather
        than transiently materializing an unbounded sequence of prefixes.
        """
        entry_count = len(direct_entries) + sum(
            len(
                component_ledgers.get(
                    dependency, _EMPTY_FORMULA_DEFINED_NAME_LEDGER
                )[ledger_index]
            )
            for dependency in dependencies
        )
        formula_defined_name_state_budget.consume(entry_count)
        return direct_entries + tuple(
            entry
            for dependency in dependencies
            for entry in component_ledgers.get(
                dependency, _EMPTY_FORMULA_DEFINED_NAME_LEDGER
            )[ledger_index]
        )

    while ready_components:
        component = heapq.heappop(ready_components)
        dependencies = component_dependencies[component]
        direct_ledger = component_direct_ledgers.get(component)
        if direct_ledger is not None or any(
            dependency in component_ledgers for dependency in dependencies
        ):
            ledger: _FormulaDefinedNameLedger = tuple(
                propagated_component_entries(
                    (
                        direct_ledger[ledger_index]
                        if direct_ledger is not None
                        else ()
                    ),
                    dependencies,
                    ledger_index,
                )
                for ledger_index in range(len(_FORMULA_DEFINED_NAME_MARKER_PREFIXES))
            )
            if any(ledger):
                component_ledgers[component] = ledger
        for dependent in sorted(component_dependents[component]):
            remaining_component_dependencies[dependent].remove(component)
            if not remaining_component_dependencies[dependent]:
                heapq.heappush(ready_components, dependent)

    def ledger_entries(
        identity: _NameDefinitionIdentity, ledger_index: int
    ) -> tuple[str, ...]:
        component = component_by_definition.get(identity)
        if component is None:
            return ()
        return component_ledgers.get(
            component, _EMPTY_FORMULA_DEFINED_NAME_LEDGER
        )[ledger_index]

    global_result = dict(global_references)
    for key, definition in global_formulas.items():
        if cached := cached_references(definition):
            global_result[key] = cached
        elif has_cached_references(definition):
            global_result[key] = ()
    for scope, values in local_references.items():
        for key, references in values.items():
            global_result[_qualified_name_key(sheet_titles[scope], key)] = references
    for scope, definitions in local_formulas.items():
        for key, definition in definitions.items():
            if cached := cached_references(definition):
                global_result[_qualified_name_key(sheet_titles[scope], key)] = cached
            elif has_cached_references(definition):
                global_result[_qualified_name_key(sheet_titles[scope], key)] = ()

    local_result: dict[str, dict[str, tuple[ParsedReference, ...]]] = {}
    for scope in set(local_references) | set(local_formulas):
        references = dict(local_references.get(scope, {}))
        for key, definition in local_formulas.get(scope, {}).items():
            if cached := cached_references(definition):
                references[key] = cached
            elif has_cached_references(definition):
                references[key] = ()
        if references:
            local_result[scope] = references

    global_function_result: dict[str, tuple[ParsedReference, ...] | None] = {
        key: cached_references(definition)
        for key, definition in global_lambdas.items()
    }
    for scope, definitions in local_lambdas.items():
        for key, definition in definitions.items():
            global_function_result[_qualified_name_key(sheet_titles[scope], key)] = (
                cached_references(definition)
            )

    local_function_result: dict[
        str, dict[str, tuple[ParsedReference, ...] | None]
    ] = {}
    for scope, definitions in local_lambdas.items():
        functions = {
            key: cached_references(definition) for key, definition in definitions.items()
        }
        if functions:
            local_function_result[scope] = functions

    def ledger_visibility_maps(ledger_index: int):
        """Expose one sparse ledger kind through reusable name overlays."""
        global_formula_view = _NameLedgerMapping(
            global_formula_identity_view,
            component_by_definition,
            component_ledgers,
            ledger_index,
        )
        scoped_formula_views = {
            scope: _NameLedgerMapping(
                scoped_formula_identity_views[scope],
                component_by_definition,
                component_ledgers,
                ledger_index,
            )
            for scope in local_scopes
        }
        global_function_view = _NameLedgerMapping(
            global_function_identity_view,
            component_by_definition,
            component_ledgers,
            ledger_index,
        )
        scoped_function_views = {
            scope: _NameLedgerMapping(
                scoped_function_identity_views[scope],
                component_by_definition,
                component_ledgers,
                ledger_index,
            )
            for scope in local_scopes
        }
        return (
            global_formula_view,
            scoped_formula_views,
            global_function_view,
            scoped_function_views,
        )

    def ledger_definition_entries(ledger_index: int) -> tuple[tuple[str, str], ...]:
        if not component_ledgers:
            return ()
        return tuple(
            sorted(
                (
                    repr((definition.scope, definition.key)),
                    repr((entries, definition.formula)),
                )
                for definition in all_definitions
                if (
                    entries := ledger_entries(
                        identity_for(definition), ledger_index
                    )
                )
            )
        )

    (
        global_external_action_result,
        local_external_action_result,
        global_function_external_action_result,
        local_function_external_action_result,
    ) = ledger_visibility_maps(0)
    external_action_definition_entries = ledger_definition_entries(0)

    (
        global_formula_dde_link_result,
        local_formula_dde_link_result,
        global_function_formula_dde_link_result,
        local_function_formula_dde_link_result,
    ) = ledger_visibility_maps(1)
    formula_dde_link_definition_entries = ledger_definition_entries(1)

    (
        global_custom_result,
        local_custom_result,
        global_function_custom_result,
        local_function_custom_result,
    ) = ledger_visibility_maps(2)
    custom_function_definition_entries = ledger_definition_entries(2)

    (
        global_unqualified_runtime_function_result,
        local_unqualified_runtime_function_result,
        global_function_unqualified_runtime_function_result,
        local_function_unqualified_runtime_function_result,
    ) = ledger_visibility_maps(3)
    unqualified_runtime_function_definition_entries = ledger_definition_entries(3)

    (
        global_code_resource_registration_result,
        local_code_resource_registration_result,
        global_function_code_resource_registration_result,
        local_function_code_resource_registration_result,
    ) = ledger_visibility_maps(4)
    code_resource_registration_definition_entries = ledger_definition_entries(4)

    (
        global_formula_defined_xlm_registration_result,
        local_formula_defined_xlm_registration_result,
        global_function_formula_defined_xlm_registration_result,
        local_function_formula_defined_xlm_registration_result,
    ) = ledger_visibility_maps(5)
    formula_defined_xlm_registration_definition_entries = ledger_definition_entries(5)

    (
        global_formula_defined_xlm_evaluation_result,
        local_formula_defined_xlm_evaluation_result,
        global_function_formula_defined_xlm_evaluation_result,
        local_function_formula_defined_xlm_evaluation_result,
    ) = ledger_visibility_maps(6)
    formula_defined_xlm_evaluation_definition_entries = ledger_definition_entries(6)

    (
        global_formula_defined_xlm_action_result,
        local_formula_defined_xlm_action_result,
        global_function_formula_defined_xlm_action_result,
        local_function_formula_defined_xlm_action_result,
    ) = ledger_visibility_maps(7)
    formula_defined_xlm_action_definition_entries = ledger_definition_entries(7)

    (
        global_formula_defined_xlm_get_cell_result,
        local_formula_defined_xlm_get_cell_result,
        global_function_formula_defined_xlm_get_cell_result,
        local_function_formula_defined_xlm_get_cell_result,
    ) = ledger_visibility_maps(8)
    formula_defined_xlm_get_cell_definition_entries = ledger_definition_entries(8)

    (
        global_formula_defined_xlm_environment_information_result,
        local_formula_defined_xlm_environment_information_result,
        global_function_formula_defined_xlm_environment_information_result,
        local_function_formula_defined_xlm_environment_information_result,
    ) = ledger_visibility_maps(9)
    formula_defined_xlm_environment_information_definition_entries = (
        ledger_definition_entries(9)
    )

    (
        global_formula_environment_information_result,
        local_formula_environment_information_result,
        global_function_formula_environment_information_result,
        local_function_formula_environment_information_result,
    ) = ledger_visibility_maps(10)
    formula_environment_information_definition_entries = ledger_definition_entries(10)

    return (
        global_result,
        local_result,
        global_function_result,
        local_function_result,
        global_external_action_result,
        local_external_action_result,
        global_function_external_action_result,
        local_function_external_action_result,
        external_action_definition_entries,
        global_formula_dde_link_result,
        local_formula_dde_link_result,
        global_function_formula_dde_link_result,
        local_function_formula_dde_link_result,
        formula_dde_link_definition_entries,
        global_custom_result,
        local_custom_result,
        global_function_custom_result,
        local_function_custom_result,
        custom_function_definition_entries,
        global_unqualified_runtime_function_result,
        local_unqualified_runtime_function_result,
        global_function_unqualified_runtime_function_result,
        local_function_unqualified_runtime_function_result,
        unqualified_runtime_function_definition_entries,
        global_code_resource_registration_result,
        local_code_resource_registration_result,
        global_function_code_resource_registration_result,
        local_function_code_resource_registration_result,
        code_resource_registration_definition_entries,
        global_formula_defined_xlm_registration_result,
        local_formula_defined_xlm_registration_result,
        global_function_formula_defined_xlm_registration_result,
        local_function_formula_defined_xlm_registration_result,
        formula_defined_xlm_registration_definition_entries,
        global_formula_defined_xlm_evaluation_result,
        local_formula_defined_xlm_evaluation_result,
        global_function_formula_defined_xlm_evaluation_result,
        local_function_formula_defined_xlm_evaluation_result,
        formula_defined_xlm_evaluation_definition_entries,
        global_formula_defined_xlm_action_result,
        local_formula_defined_xlm_action_result,
        global_function_formula_defined_xlm_action_result,
        local_function_formula_defined_xlm_action_result,
        formula_defined_xlm_action_definition_entries,
        global_formula_defined_xlm_get_cell_result,
        local_formula_defined_xlm_get_cell_result,
        global_function_formula_defined_xlm_get_cell_result,
        local_function_formula_defined_xlm_get_cell_result,
        formula_defined_xlm_get_cell_definition_entries,
        global_formula_defined_xlm_environment_information_result,
        local_formula_defined_xlm_environment_information_result,
        global_function_formula_defined_xlm_environment_information_result,
        local_function_formula_defined_xlm_environment_information_result,
        formula_defined_xlm_environment_information_definition_entries,
        global_formula_environment_information_result,
        local_formula_environment_information_result,
        global_function_formula_environment_information_result,
        local_function_formula_environment_information_result,
        formula_environment_information_definition_entries,
    )


def _has_static_defined_name_destinations(
    references: tuple[ParsedReference, ...],
) -> bool:
    """Return whether every expanded destination is a fixed internal range."""
    return bool(references) and all(
        not reference.is_external
        and reference.sheet is not None
        and None
        not in {
            reference.min_column,
            reference.min_row,
            reference.max_column,
            reference.max_row,
        }
        for reference in references
    )


def _static_global_defined_name_references(
    named_references: Mapping[str, tuple[ParsedReference, ...]],
) -> dict[str, tuple[ParsedReference, ...]]:
    """Keep only safely expanded workbook-scoped name destinations private.

    The result is consumed solely by candidate portfolio analysis for direct
    external workbook names. A local name, unresolved formula/name, external
    target, relative reference, or malformed range is deliberately omitted;
    FormulaFence must not turn an uncertain name into an invented cross-file
    edge.
    """
    return {
        name_key: references
        for name_key, references in named_references.items()
        if "!" not in name_key and _has_static_defined_name_destinations(references)
    }


def _static_local_defined_name_references(
    named_references: Mapping[str, Mapping[str, tuple[ParsedReference, ...]]],
) -> dict[str, dict[str, tuple[ParsedReference, ...]]]:
    """Keep only static source-local names, indexed by their exact scope.

    An external ``[Book]Sheet!Name`` explicitly selects the local scope of the
    source sheet.  Do not fall back to a same-named global definition or a
    different sheet's local name, and do not retain a formula/name that did
    not resolve entirely to fixed internal destinations.
    """
    result: dict[str, dict[str, tuple[ParsedReference, ...]]] = {}
    for scope, definitions in named_references.items():
        static_definitions = {
            name_key: references
            for name_key, references in definitions.items()
            if "!" not in name_key
            and _has_static_defined_name_destinations(references)
        }
        if static_definitions:
            result[scope] = static_definitions
    return result


def _local_defined_name_keys(workbook: object) -> dict[str, frozenset[str]]:
    """Inventory local consumer keys so they shadow global external aliases.

    Excel resolves a sheet-local name before a workbook-scoped name with the
    same identity.  Keep even an unresolved local definition in this inventory:
    failing closed is preferable to incorrectly following a global external
    alias that the formula cannot actually select on that sheet.
    """
    result: dict[str, frozenset[str]] = {}
    for worksheet in getattr(workbook, "worksheets", ()):
        names = getattr(worksheet, "defined_names", {})
        try:
            items = names.items()
        except AttributeError:
            continue
        keys = frozenset(
            name_key
            for name, _definition in items
            if (name_key := reference_lookup_key(str(name)))
        )
        if keys:
            result[worksheet.title.casefold()] = keys
    return result


_ExternalAliasReference = TypeVar(
    "_ExternalAliasReference",
    ExternalWorkbookReference,
    ExternalWorkbookThreeDReference,
    ExternalWorkbookStructuredReference,
    ExternalWorkbookDefinedNameReference,
)


def _workbook_scoped_defined_name_aliases(workbook: object) -> dict[str, str]:
    """Return exact global name-to-name bridges without evaluating formulas.

    Workbook formula names routinely provide an extra semantic layer over an
    external link: ``RevenueInputs`` can be a direct external range while
    ``ForecastInputs`` is exactly ``=RevenueInputs``.  The latter is safe to
    retain only when it is a workbook-scoped, one-name bridge as parsed by the
    shared lexical helper.  Local names, formula wrappers, sheet-qualified
    syntax, dynamic functions, and malformed definitions never enter this
    map, so later portfolio resolution cannot infer an edge from workbook
    logic.
    """
    names = getattr(workbook, "defined_names", {})
    try:
        items = names.items()
    except AttributeError:
        return {}
    aliases: dict[str, str] = {}
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        name_key = reference_lookup_key(str(name))
        target_key = parse_workbook_defined_name_alias(_definition_text(definition))
        if name_key and target_key and name_key != target_key:
            aliases[name_key] = target_key
    return aliases


def _expand_workbook_scoped_external_aliases(
    direct_references: Mapping[str, tuple[_ExternalAliasReference, ...]],
    aliases: Mapping[str, str],
) -> dict[str, tuple[_ExternalAliasReference, ...]]:
    """Expand finite exact global alias chains to existing external endpoints.

    The endpoint map has already passed the direct-link and package-link
    validation appropriate to its reference kind.  This pass only follows
    name keys between those endpoints; it never resolves paths, formulas, or
    source definitions.  The iterative walk treats missing targets and every
    cycle as unresolved, avoiding invented dependencies without adding a
    recursive traversal to this portfolio bridge.
    """
    resolved = dict(direct_references)
    failed: set[str] = set()

    def resolve(name_key: str) -> tuple[_ExternalAliasReference, ...] | None:
        if name_key in resolved:
            return resolved[name_key]
        if name_key in failed:
            return None

        trail: list[str] = []
        seen: set[str] = set()
        current = name_key
        endpoint: tuple[_ExternalAliasReference, ...] | None = None
        while True:
            if current in resolved:
                endpoint = resolved[current]
                break
            if current in failed or current in seen:
                break
            target = aliases.get(current)
            if target is None:
                break
            seen.add(current)
            trail.append(current)
            current = target

        if endpoint is None:
            failed.update(trail)
            return None
        for alias_key in trail:
            resolved[alias_key] = endpoint
        return endpoint

    for name_key in aliases:
        resolve(name_key)
    return resolved


def _workbook_scoped_formula_defined_name_formulas(
    workbook: object,
) -> tuple[dict[str, str], frozenset[str]]:
    """Return global name formulas plus the keys that are named LAMBDAs.

    Excel permits a defined name to contain a complete formula around a
    workbook link, such as ``=SUM([Budget.xlsx]Annual!C10:C25)``. A global
    named LAMBDA can likewise retain a static input endpoint in its body. A
    local name is intentionally excluded because its scope is selected by the
    invoking worksheet.
    """
    names = getattr(workbook, "defined_names", {})
    try:
        items = names.items()
    except AttributeError:
        return {}, frozenset()
    result: dict[str, str] = {}
    lambda_keys: set[str] = set()
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        formula_definition = _formula_defined_name(str(name), definition, None)
        if formula_definition is None:
            continue
        result[formula_definition.key] = formula_definition.formula
        if lambda_parameter_count(formula_definition.formula) is not None:
            lambda_keys.add(formula_definition.key)
    return result, frozenset(lambda_keys)


def _formula_defined_name_external_references(
    workbook: object,
    *,
    named_references: Mapping[str, tuple[ParsedReference, ...]],
    named_functions: Mapping[str, tuple[ParsedReference, ...] | None],
    structured_tables: Mapping[str, StructuredTable],
    sheet_order: tuple[str, ...],
    indexed_external_workbook_paths: Mapping[int, str],
    direct_workbook_references: Mapping[
        str, tuple[ExternalWorkbookReference, ...]
    ],
    direct_three_d_references: Mapping[
        str, tuple[ExternalWorkbookThreeDReference, ...]
    ],
    direct_structured_references: Mapping[
        str, tuple[ExternalWorkbookStructuredReference, ...]
    ],
    direct_defined_name_references: Mapping[
        str, tuple[ExternalWorkbookDefinedNameReference, ...]
    ],
    aliases: Mapping[str, str],
) -> tuple[
    dict[str, tuple[ExternalWorkbookReference, ...]],
    dict[str, tuple[ExternalWorkbookThreeDReference, ...]],
    dict[str, tuple[ExternalWorkbookStructuredReference, ...]],
    dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]],
    dict[str, tuple[ParsedReference, ...]],
]:
    """Expand strictly static global name definitions to private endpoints.

    This is deliberately an input-edge bridge, not formula evaluation. It
    accepts a name formula only when every visible reference is static and any
    external token has already become one of the validated direct or
    package-indexed endpoint models. A named LAMBDA follows the same static
    rule for its body, and its endpoint is retained only at a call site. A
    dependency worklist lets one such name call another without repeatedly
    rescanning unrelated definitions, while cycles, unrecognized external syntax, dynamic
    functions, relative references, and scope-sensitive forms remain outside
    the candidate graph.
    """
    formulas, named_lambda_keys = _workbook_scoped_formula_defined_name_formulas(
        workbook
    )
    formula_workbook_references: dict[
        str, tuple[ExternalWorkbookReference, ...]
    ] = {}
    formula_three_d_references: dict[
        str, tuple[ExternalWorkbookThreeDReference, ...]
    ] = {}
    formula_structured_references: dict[
        str, tuple[ExternalWorkbookStructuredReference, ...]
    ] = {}
    formula_defined_name_references: dict[
        str, tuple[ExternalWorkbookDefinedNameReference, ...]
    ] = {}
    formula_static_references: dict[str, tuple[ParsedReference, ...]] = {}

    def expanded_endpoint_maps() -> tuple[
        dict[str, tuple[ExternalWorkbookReference, ...]],
        dict[str, tuple[ExternalWorkbookThreeDReference, ...]],
        dict[str, tuple[ExternalWorkbookStructuredReference, ...]],
        dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]],
    ]:
        return (
            _expand_workbook_scoped_external_aliases(
                {**direct_workbook_references, **formula_workbook_references},
                aliases,
            ),
            _expand_workbook_scoped_external_aliases(
                {**direct_three_d_references, **formula_three_d_references},
                aliases,
            ),
            _expand_workbook_scoped_external_aliases(
                {**direct_structured_references, **formula_structured_references},
                aliases,
            ),
            _expand_workbook_scoped_external_aliases(
                {
                    **direct_defined_name_references,
                    **formula_defined_name_references,
                },
                aliases,
            ),
        )

    alias_dependents: defaultdict[str, set[str]] = defaultdict(set)
    for alias_key, target_key in aliases.items():
        alias_dependents[target_key].add(alias_key)

    def changed_name_keys(name_key: str) -> set[str]:
        """Return one changed endpoint name plus aliases that now resolve it."""
        changed = {name_key}
        pending_aliases = [name_key]
        while pending_aliases:
            target_key = pending_aliases.pop()
            for alias_key in alias_dependents.get(target_key, ()):
                if alias_key not in changed:
                    changed.add(alias_key)
                    pending_aliases.append(alias_key)
        return changed

    def is_validated_external_token(
        token: str,
        endpoint_maps: tuple[
            Mapping[str, tuple[ExternalWorkbookReference, ...]],
            Mapping[str, tuple[ExternalWorkbookThreeDReference, ...]],
            Mapping[str, tuple[ExternalWorkbookStructuredReference, ...]],
            Mapping[str, tuple[ExternalWorkbookDefinedNameReference, ...]],
        ],
    ) -> bool:
        """Return whether one visible external token has a static endpoint.

        ``inspect_formula`` intentionally deduplicates endpoint models for
        snapshot stability.  Validate the original token instead of comparing
        that deduplicated collection with the number of references: a formula
        is still static when it uses the same endpoint twice.
        """
        name_key = reference_lookup_key(token)
        if any(name_key in endpoint_map for endpoint_map in endpoint_maps):
            return True
        if any(
            parser(token) is not None
            for parser in (
                parse_external_workbook_reference,
                parse_external_workbook_three_d_reference,
                parse_external_workbook_structured_reference,
                parse_external_workbook_defined_name_reference,
                parse_external_workbook_sheet_defined_name_reference,
            )
        ):
            return True
        indexed_reference = parse_external_link_indexed_workbook_reference(token)
        if (
            indexed_reference is not None
            and indexed_reference.index in indexed_external_workbook_paths
        ):
            return True
        indexed_three_d_reference = parse_external_link_indexed_workbook_three_d_reference(
            token
        )
        if (
            indexed_three_d_reference is not None
            and indexed_three_d_reference.index in indexed_external_workbook_paths
        ):
            return True
        indexed_structured_reference = (
            parse_external_link_indexed_workbook_structured_reference(token)
        )
        if (
            indexed_structured_reference is not None
            and indexed_structured_reference.index in indexed_external_workbook_paths
        ):
            return True
        indexed_defined_name_reference = parse_external_link_indexed_defined_name_reference(
            token
        )
        if (
            indexed_defined_name_reference is not None
            and indexed_defined_name_reference[0] in indexed_external_workbook_paths
        ):
            return True
        indexed_sheet_defined_name_reference = (
            parse_external_link_indexed_sheet_defined_name_reference(token)
        )
        return (
            indexed_sheet_defined_name_reference is not None
            and indexed_sheet_defined_name_reference[0]
            in indexed_external_workbook_paths
        )

    def endpoint_lookup_views(
        direct: Mapping[str, _NameMapValue],
        resolved: Mapping[str, _NameMapValue],
    ) -> tuple[
        _ExternalAliasNameMapping,
        _ExternalAliasNameMapping,
        _ExternalAliasNameMapping,
    ]:
        """Return all, ordinary-name, and named-LAMBDA views for one kind."""
        return (
            _ExternalAliasNameMapping(
                direct=direct,
                resolved=resolved,
                aliases=aliases,
            ),
            _ExternalAliasNameMapping(
                direct=direct,
                resolved=resolved,
                aliases=aliases,
                named_lambda_keys=named_lambda_keys,
                include_named_lambdas=False,
            ),
            _ExternalAliasNameMapping(
                direct=direct,
                resolved=resolved,
                aliases=aliases,
                named_lambda_keys=named_lambda_keys,
                include_named_lambdas=True,
            ),
        )

    (
        all_workbook_endpoint_view,
        named_workbook_endpoint_view,
        named_lambda_workbook_endpoint_view,
    ) = endpoint_lookup_views(
        direct_workbook_references,
        formula_workbook_references,
    )
    (
        all_three_d_endpoint_view,
        named_three_d_endpoint_view,
        named_lambda_three_d_endpoint_view,
    ) = endpoint_lookup_views(
        direct_three_d_references,
        formula_three_d_references,
    )
    (
        all_structured_endpoint_view,
        named_structured_endpoint_view,
        named_lambda_structured_endpoint_view,
    ) = endpoint_lookup_views(
        direct_structured_references,
        formula_structured_references,
    )
    (
        all_defined_name_endpoint_view,
        named_defined_name_endpoint_view,
        named_lambda_defined_name_endpoint_view,
    ) = endpoint_lookup_views(
        direct_defined_name_references,
        formula_defined_name_references,
    )
    all_endpoint_views = (
        all_workbook_endpoint_view,
        all_three_d_endpoint_view,
        all_structured_endpoint_view,
        all_defined_name_endpoint_view,
    )

    named_static_reference_view = _FilteredNameMapping(
        formula_static_references,
        named_lambda_keys,
        include_named_lambdas=False,
    )
    named_lambda_static_reference_view = _FilteredNameMapping(
        formula_static_references,
        named_lambda_keys,
        include_named_lambdas=True,
    )
    visible_named_references = _OverlayNameMapping(
        named_static_reference_view,
        named_references,
    )
    visible_named_functions = _OverlayNameMapping(
        named_lambda_static_reference_view,
        named_functions,
    )

    waiting_formula_names: defaultdict[str, set[str]] = defaultdict(set)
    for name_key, formula in formulas.items():
        unresolved = inspect_formula(
            formula,
            named_references=named_references,
            structured_tables=structured_tables,
            sheet_order=sheet_order,
            named_function_references=named_functions,
        ).unresolved_range_tokens
        for token in unresolved:
            waiting_formula_names[reference_lookup_key(token)].add(name_key)

    pending = list(sorted(formulas, reverse=True))
    pending_keys = set(formulas)
    while pending:
        name_key = pending.pop()
        pending_keys.discard(name_key)
        formula = formulas[name_key]
        inspection = inspect_formula(
            formula,
            named_references=visible_named_references,
            named_external_workbook_defined_name_references=(
                named_defined_name_endpoint_view
            ),
            indexed_external_workbook_paths=indexed_external_workbook_paths,
            named_external_workbook_references=named_workbook_endpoint_view,
            named_external_workbook_three_d_references=named_three_d_endpoint_view,
            named_external_workbook_structured_references=(
                named_structured_endpoint_view
            ),
            structured_tables=structured_tables,
            sheet_order=sheet_order,
            named_function_references=visible_named_functions,
            named_function_external_workbook_defined_name_references=(
                named_lambda_defined_name_endpoint_view
            ),
            named_function_external_workbook_references=(
                named_lambda_workbook_endpoint_view
            ),
            named_function_external_workbook_three_d_references=(
                named_lambda_three_d_endpoint_view
            ),
            named_function_external_workbook_structured_references=(
                named_lambda_structured_endpoint_view
            ),
        )
        workbook_references = tuple(
            dict.fromkeys(inspection.external_workbook_references)
        )
        three_d_references = tuple(
            dict.fromkeys(inspection.external_workbook_three_d_references)
        )
        structured_references = tuple(
            dict.fromkeys(inspection.external_workbook_structured_references)
        )
        defined_name_references = tuple(
            dict.fromkeys(inspection.external_workbook_defined_name_references)
        )
        endpoint_count = sum(
            len(references)
            for references in (
                workbook_references,
                three_d_references,
                structured_references,
                defined_name_references,
            )
        )
        external_references = tuple(
            reference for reference in inspection.references if reference.is_external
        )
        static_references = tuple(
            dict.fromkeys(
                reference
                for reference in inspection.references
                if not reference.is_external
            )
        )
        has_relative_internal_reference = any(
            not reference.is_external and reference.sheet is None
            for reference in inspection.references
        )
        if (
            not endpoint_count
            or not external_references
            or any(
                not is_validated_external_token(reference.raw, all_endpoint_views)
                for reference in external_references
            )
            or has_broken_reference(formula)
            or inspection.tokenization_failed
            or inspection.unresolved_range_tokens
            or inspection.dynamic_reference_functions
            or inspection.three_d_reference_tokens
            or inspection.spill_reference_tokens
            or inspection.implicit_intersection_tokens
            or has_relative_internal_reference
        ):
            continue

        changed = False
        for resolved, destination in (
            (workbook_references, formula_workbook_references),
            (three_d_references, formula_three_d_references),
            (structured_references, formula_structured_references),
            (defined_name_references, formula_defined_name_references),
        ):
            if resolved and destination.get(name_key) != resolved:
                destination[name_key] = resolved
                changed = True
        if formula_static_references.get(name_key) != static_references:
            formula_static_references[name_key] = static_references
            changed = True
        if not changed:
            continue

        for changed_name_key in sorted(changed_name_keys(name_key), reverse=True):
            for dependent_key in sorted(
                waiting_formula_names.get(changed_name_key, ()), reverse=True
            ):
                if dependent_key not in pending_keys:
                    pending.append(dependent_key)
                    pending_keys.add(dependent_key)

    endpoint_maps = expanded_endpoint_maps()
    return (*endpoint_maps, formula_static_references)


def _package_indexed_external_name_references(
    workbook: object,
    indexed_external_workbook_paths: Mapping[int, str],
) -> dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]]:
    """Resolve only direct workbook-scoped aliases for indexed external names.

    A formula such as ``=ExternalInput`` can be backed by a workbook-defined
    name whose OOXML text is ``[1]!InputRange``.  The integer is meaningful
    only after the raw package declaration validated it above.  Do not expand
    local names, formula aliases, relative names, cached ``externalLink``
    definitions, or any unresolved index: those forms could turn an ambiguous
    package detail into an invented cross-workbook edge.
    """
    if not indexed_external_workbook_paths:
        return {}
    names = getattr(workbook, "defined_names", {})
    try:
        items = names.items()
    except AttributeError:
        return {}
    result: dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]] = {}
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        indexed_reference = parse_external_link_indexed_defined_name_reference(
            _definition_text(definition)
        )
        if indexed_reference is None:
            continue
        index, source_name_key = indexed_reference
        source_path = indexed_external_workbook_paths.get(index)
        if source_path is None:
            continue
        name_key = reference_lookup_key(str(name))
        if name_key:
            result[name_key] = (
                ExternalWorkbookDefinedNameReference(source_path, source_name_key),
            )
    return result


def _package_indexed_external_sheet_defined_name_references(
    workbook: object,
    indexed_external_workbook_paths: Mapping[int, str],
) -> dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]]:
    """Resolve only direct workbook-scoped aliases for indexed local names.

    A consuming workbook-defined name can store ``[1]Data!LocalInput`` while
    an ordinary formula uses only the consumer alias.  The source sheet is a
    local-name scope, not a candidate A1 destination.  Require the same exact
    validated package target as every other indexed form, and leave local
    consumer aliases, formula aliases, invalid indexes, and ambiguous package
    metadata outside the graph.
    """
    if not indexed_external_workbook_paths:
        return {}
    names = getattr(workbook, "defined_names", {})
    try:
        items = names.items()
    except AttributeError:
        return {}
    result: dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]] = {}
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        indexed_reference = parse_external_link_indexed_sheet_defined_name_reference(
            _definition_text(definition)
        )
        if indexed_reference is None:
            continue
        index, scope_sheet, source_name_key = indexed_reference
        source_path = indexed_external_workbook_paths.get(index)
        if source_path is None:
            continue
        name_key = reference_lookup_key(str(name))
        if name_key:
            result[name_key] = (
                ExternalWorkbookDefinedNameReference(
                    source_path,
                    source_name_key,
                    scope_sheet,
                ),
            )
    return result


def _direct_external_sheet_defined_name_references(
    workbook: object,
) -> dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]]:
    """Keep direct workbook-scoped aliases for static source-local names.

    Direct textual paths can be resolved later only through the supplied
    portfolio root.  This loader performs no path lookup and deliberately
    ignores consumer-local and formula aliases so an explicit source scope is
    never inferred from workbook state.
    """
    names = getattr(workbook, "defined_names", {})
    try:
        items = names.items()
    except AttributeError:
        return {}
    result: dict[str, tuple[ExternalWorkbookDefinedNameReference, ...]] = {}
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        reference = parse_external_workbook_sheet_defined_name_reference(
            _definition_text(definition)
        )
        if reference is None:
            continue
        name_key = reference_lookup_key(str(name))
        if name_key:
            result[name_key] = (reference,)
    return result


