def _package_indexed_external_workbook_structured_references(
    workbook: object,
    indexed_external_workbook_paths: Mapping[int, str],
) -> dict[str, tuple[ExternalWorkbookStructuredReference, ...]]:
    """Resolve direct global aliases for indexed external tables only.

    A workbook name can store ``[1]!Sales[Amount]``. The index becomes useful
    only after raw package metadata establishes one exact target spelling;
    after that, the source table is still resolved only against a candidate
    snapshot. Formula-valued aliases, local names, row-relative selectors,
    and unresolved package indexes remain outside this graph.
    """
    if not indexed_external_workbook_paths:
        return {}
    names = getattr(workbook, "defined_names", {})
    try:
        items = names.items()
    except AttributeError:
        return {}
    result: dict[str, tuple[ExternalWorkbookStructuredReference, ...]] = {}
    for name, definition in items:
        if getattr(definition, "localSheetId", None) is not None:
            continue
        indexed_reference = parse_external_link_indexed_workbook_structured_reference(
            _definition_text(definition)
        )
        if indexed_reference is None:
            continue
        source_path = indexed_external_workbook_paths.get(indexed_reference.index)
        if source_path is None:
            continue
        name_key = reference_lookup_key(str(name))
        if name_key:
            result[name_key] = (
                ExternalWorkbookStructuredReference(
                    source_path=source_path,
                    table_name=indexed_reference.table_name,
                    table_reference=indexed_reference.table_reference,
                ),
            )
    return result


def _table_columns(
    worksheet: object,
    table: object,
    min_column: int,
    min_row: int,
    max_column: int,
    header_row_count: int,
) -> tuple[str, ...]:
    """Read table column labels, falling back to the inspectable header cells."""
    table_columns = tuple(getattr(table, "tableColumns", ()) or ())
    names = tuple(str(getattr(column, "name", "")) for column in table_columns)
    width = max_column - min_column + 1
    if len(names) == width and all(names):
        return names
    if header_row_count:
        return tuple(
            str(value) if (value := worksheet.cell(min_row, column).value) is not None else ""
            for column in range(min_column, max_column + 1)
        )
    return ()


def _table_snapshots(workbook: object) -> dict[str, TableSnapshot]:
    """Inventory Excel-table definitions that affect structured references."""
    result: dict[str, TableSnapshot] = {}
    for worksheet in getattr(workbook, "worksheets", ()):
        table_list = getattr(worksheet, "tables", {})
        try:
            table_values = table_list.values()
        except AttributeError:
            continue
        for table in table_values:
            name = str(
                getattr(table, "displayName", None)
                or getattr(table, "name", None)
                or ""
            )
            ref = getattr(table, "ref", None)
            if not name or not isinstance(ref, str):
                continue
            try:
                min_column, min_row, max_column, max_row = range_boundaries(ref)
            except ValueError:
                continue
            height = max_row - min_row + 1
            header_rows = min(max(int(getattr(table, "headerRowCount", 1) or 0), 0), height)
            totals_rows = min(
                max(int(getattr(table, "totalsRowCount", 0) or 0), 0), height - header_rows
            )
            result[name] = TableSnapshot(
                name=name,
                sheet=worksheet.title,
                ref=ref,
                columns=_table_columns(
                    worksheet,
                    table,
                    min_column,
                    min_row,
                    max_column,
                    header_rows,
                ),
                header_row_count=header_rows,
                totals_row_count=totals_rows,
            )
    return result


def _validation_formula(value: object) -> str | None:
    """Normalize the optional leading equals sign used by workbook writers."""
    if not isinstance(value, str):
        return None
    return value[1:] if value.startswith("=") else value


def _validation_ranges(validation: object) -> tuple[str, ...]:
    """Return a compact, writer-order-independent validation target inventory."""
    sqref = getattr(validation, "sqref", None)
    try:
        ranges = tuple(str(target_range) for target_range in sqref.ranges)
    except (AttributeError, TypeError):
        raw = str(sqref or "")
        ranges = tuple(raw.split())
    return tuple(sorted(set(ranges), key=str.casefold))


def _validation_bool(validation: object, attribute: str, default: bool) -> bool:
    """Read one OOXML boolean while applying its schema default."""
    value = getattr(validation, attribute, None)
    return default if value is None else bool(value)


def _data_validation_snapshots(workbook: object) -> tuple[DataValidationSnapshot, ...]:
    """Inventory data-entry controls without expanding their applied ranges.

    OOXML defaults are normalized because writers commonly omit values such as
    ``operator=between`` and ``errorStyle=stop`` while other writers serialize
    them explicitly. The control's formulas and messages remain available in a
    local diff but are omitted from profile output.
    """
    snapshots: list[DataValidationSnapshot] = []
    for worksheet in getattr(workbook, "worksheets", ()):
        validation_container = getattr(worksheet, "data_validations", None)
        validation_list = getattr(validation_container, "dataValidation", ())
        prompts_disabled = _validation_bool(validation_container, "disablePrompts", False)
        for validation in validation_list or ():
            ranges = _validation_ranges(validation)
            if not ranges:
                continue
            snapshots.append(
                DataValidationSnapshot(
                    sheet=worksheet.title,
                    ranges=ranges,
                    validation_type=str(getattr(validation, "type", None) or "none"),
                    operator=str(getattr(validation, "operator", None) or "between"),
                    formula1=_validation_formula(getattr(validation, "formula1", None)),
                    formula2=_validation_formula(getattr(validation, "formula2", None)),
                    allow_blank=_validation_bool(validation, "allowBlank", False),
                    dropdown_hidden=_validation_bool(validation, "showDropDown", False),
                    prompts_disabled=prompts_disabled,
                    show_input_message=_validation_bool(
                        validation, "showInputMessage", False
                    ),
                    show_error_message=_validation_bool(
                        validation, "showErrorMessage", False
                    ),
                    error_style=str(getattr(validation, "errorStyle", None) or "stop"),
                    error_title=getattr(validation, "errorTitle", None),
                    error=getattr(validation, "error", None),
                    prompt_title=getattr(validation, "promptTitle", None),
                    prompt=getattr(validation, "prompt", None),
                    ime_mode=str(getattr(validation, "imeMode", None) or "noControl"),
                )
            )
    # ``sqref`` is only a compact list of targets for a rule. Writers may keep
    # identical rules together or split them into separate ``dataValidation``
    # elements, with no change to what Excel applies to any target cell.
    # Canonicalize that grouping before comparing workbooks.
    grouped_ranges: dict[DataValidationSnapshot, set[str]] = defaultdict(set)
    for snapshot in snapshots:
        grouped_ranges[replace(snapshot, ranges=())].update(snapshot.ranges)
    return tuple(
        sorted(
            (
                replace(
                    snapshot,
                    ranges=tuple(sorted(ranges, key=str.casefold)),
                )
                for snapshot, ranges in grouped_ranges.items()
            ),
            key=DataValidationSnapshot.sort_key,
        )
    )


def _direct_external_workbook_reference_tokens(inspection: object) -> tuple[str, ...]:
    """Return only literal external endpoints, excluding expanded name aliases.

    ``inspect_formula`` also expands a workbook-defined name or named LAMBDA
    when a caller supplies those maps.  That is right for dependency impact,
    but this ledger must attribute a link to the surface that persists it. A
    direct A1/table/sheet-local endpoint retains Excel's ``!`` separator in
    its raw token; a direct workbook-scoped external name is the one exception
    (``[Source.xlsx]InputRange``).  A parsed direct external-name spelling is
    therefore included explicitly, while an expanded bare local name remains
    excluded.
    """
    references = getattr(inspection, "references", ())
    return tuple(
        sorted(
            {
                str(reference.raw).strip().casefold()
                for reference in references
                if getattr(reference, "is_external", False)
                and (
                    "!" in str(getattr(reference, "raw", ""))
                    or parse_external_workbook_defined_name_reference(
                        str(getattr(reference, "raw", ""))
                    )
                    is not None
                )
            }
        )
    )


def _external_workbook_formula_surface_tokens(formula: str | None) -> tuple[str, ...]:
    """Find literal workbook endpoints in any OOXML formula-bearing field.

    Defined-name, data-validation, and chart formula text commonly omit the
    leading equals sign expected by the worksheet-cell formula tokenizer. Add
    it solely for lexical inspection; no formula is evaluated or resolved.
    """
    if formula is None:
        return ()
    candidate = str(formula).strip()
    if not candidate:
        return ()
    if not candidate.startswith("="):
        candidate = f"={candidate}"
    return _direct_external_workbook_reference_tokens(inspect_formula(candidate))


def _external_workbook_link_surface_snapshot(
    cell_surfaces: list[tuple[CellKey, tuple[str, ...]]],
    defined_names: Mapping[str, str],
    data_validations: tuple[DataValidationSnapshot, ...],
    chart_definitions: ChartDefinitionSnapshot,
) -> ExternalWorkbookLinkSurfaceSnapshot:
    """Build a private, static ledger across persisted workbook-link surfaces.

    The ledger purposefully records endpoint material only inside a salted
    private signature.  It distinguishes a same-cell target swap from an
    ordinary formula edit, but exposes only surface and endpoint counts in
    JSON, Markdown, and SARIF.
    """
    entries: list[tuple[str, str]] = []
    cell_formula_surface_count = 0
    defined_name_surface_count = 0
    data_validation_surface_count = 0
    external_reference_count = 0

    for location, tokens in cell_surfaces:
        if not tokens:
            continue
        cell_formula_surface_count += 1
        external_reference_count += len(tokens)
        entries.append(
            (
                "cell-formula",
                repr(((location[0].casefold(), location[1].casefold()), tokens)),
            )
        )

    for name, definition in sorted(defined_names.items(), key=lambda item: item[0].casefold()):
        tokens = _external_workbook_formula_surface_tokens(definition)
        if not tokens:
            continue
        defined_name_surface_count += 1
        external_reference_count += len(tokens)
        entries.append(("defined-name", repr((name.casefold(), tokens))))

    for validation in data_validations:
        identity = (
            validation.sheet.casefold(),
            tuple(target.casefold() for target in validation.ranges),
            validation.validation_type.casefold(),
            validation.operator.casefold(),
        )
        for position, formula in enumerate((validation.formula1, validation.formula2), start=1):
            tokens = _external_workbook_formula_surface_tokens(formula)
            if not tokens:
                continue
            data_validation_surface_count += 1
            external_reference_count += len(tokens)
            entries.append(
                ("data-validation", repr((identity, position, tokens)))
            )

    chart_formula_surface_count = chart_definitions.external_workbook_formula_surface_count
    external_reference_count += (
        chart_definitions.external_workbook_formula_reference_count
    )
    if chart_formula_surface_count:
        entries.append(
            (
                "chart-formula",
                repr(
                    (
                        chart_formula_surface_count,
                        chart_definitions.external_workbook_formula_reference_count,
                        chart_definitions.external_workbook_formula_signature,
                    )
                ),
            )
        )

    opaque_chart_part_count = (
        chart_definitions.external_workbook_formula_opaque_part_count
    )
    if opaque_chart_part_count:
        # When a chart part cannot be safely inspected, a chart formula link
        # cannot be ruled out. Keep the affected chart definition private and
        # make the dedicated policy fail closed on a material change.
        entries.append(
            (
                "opaque-chart-part",
                repr(
                    (
                        opaque_chart_part_count,
                        chart_definitions.external_workbook_formula_opaque_signature,
                    )
                ),
            )
        )

    return ExternalWorkbookLinkSurfaceSnapshot(
        cell_formula_surface_count=cell_formula_surface_count,
        defined_name_surface_count=defined_name_surface_count,
        data_validation_surface_count=data_validation_surface_count,
        chart_formula_surface_count=chart_formula_surface_count,
        opaque_chart_part_count=opaque_chart_part_count,
        external_reference_count=external_reference_count,
        ledger_signature=(
            _private_external_data_signature(tuple(sorted(entries))) if entries else None
        ),
    )


def _structured_table_map(tables: dict[str, TableSnapshot]) -> dict[str, StructuredTable]:
    """Translate stable table inventory records into formula-resolution metadata."""
    return {
        name.casefold(): StructuredTable(
            name=table.name,
            sheet=table.sheet,
            ref=table.ref,
            columns=table.columns,
            header_row_count=table.header_row_count,
            totals_row_count=table.totals_row_count,
        )
        for name, table in tables.items()
    }


def _remove_stable_workbook_source(path: Path) -> None:
    """Best-effort cleanup for a private inspection copy."""
    try:
        path.unlink(missing_ok=True)
    except OSError:
        pass


@dataclass(frozen=True)
class WorkbookSourceIdentity:
    """Observed regular-file identity and state for a guarded workbook read."""

    device: int
    inode: int
    changed_at_ns: int
    size: int


def _materialize_stable_workbook_source(
    source: Path,
    *,
    expected_source_identity: WorkbookSourceIdentity | None = None,
) -> Path:
    """Copy one bounded regular file before any repeated workbook inspection."""
    temporary_path: Path | None = None
    completed = False
    try:
        descriptor, temporary_name = tempfile.mkstemp(
            prefix="formulafence-source-",
            suffix=source.suffix,
        )
        temporary_path = Path(temporary_name)
        input_flags = (
            os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NONBLOCK", 0)
        )
        if expected_source_identity is not None:
            input_flags |= getattr(os, "O_NOFOLLOW", 0)
        copied_bytes = 0
        remaining_bytes = _OOXML_ARCHIVE_MAX_SOURCE_BYTES + 1
        with os.fdopen(descriptor, "wb") as destination:
            try:
                source_descriptor = os.open(source, input_flags)
            except OSError as error:
                if expected_source_identity is not None and error.errno == errno.ELOOP:
                    raise WorkbookLoadError(
                        "Workbook source changed after portfolio inventory."
                    ) from error
                raise
            try:
                source_file = os.fdopen(source_descriptor, "rb")
            except BaseException:
                os.close(source_descriptor)
                raise
            with source_file:
                source_stat = os.fstat(source_file.fileno())
                if not stat.S_ISREG(source_stat.st_mode):
                    raise WorkbookLoadError("Workbook source is not a regular file.")
                # A just-unlinked inode can be reused. Pair its device/inode
                # with state that a normal writer cannot restore invisibly.
                if expected_source_identity is not None and (
                    source_stat.st_dev != expected_source_identity.device
                    or source_stat.st_ino != expected_source_identity.inode
                    or source_stat.st_ctime_ns != expected_source_identity.changed_at_ns
                    or source_stat.st_size != expected_source_identity.size
                ):
                    raise WorkbookLoadError(
                        "Workbook source changed after portfolio inventory."
                    )
                if source_stat.st_size > _OOXML_ARCHIVE_MAX_SOURCE_BYTES:
                    raise _archive_preflight_error(
                        "source size exceeds the supported safety limit."
                    )
                while remaining_bytes:
                    block = source_file.read(
                        min(_OOXML_SOURCE_SNAPSHOT_COPY_BLOCK_BYTES, remaining_bytes)
                    )
                    if not block:
                        break
                    if copied_bytes + len(block) > _OOXML_ARCHIVE_MAX_SOURCE_BYTES:
                        raise _archive_preflight_error(
                            "source size exceeds the supported safety limit."
                        )
                    destination.write(block)
                    copied_bytes += len(block)
                    remaining_bytes -= len(block)
        completed = True
        return temporary_path
    except OSError as error:
        raise WorkbookLoadError(
            "Could not create a stable private copy of the workbook source."
        ) from error
    finally:
        if not completed and temporary_path is not None:
            _remove_stable_workbook_source(temporary_path)


def load_snapshot(
    path: str | Path,
    *,
    expected_source_identity: WorkbookSourceIdentity | None = None,
    max_dependency_edges: int = DEFAULT_MAX_DEPENDENCY_EDGES,
    max_formula_defined_name_states: int = DEFAULT_MAX_FORMULA_DEFINED_NAME_STATES,
    _dependency_edge_budget: DependencyEdgeBudget | None = None,
    _formula_defined_name_state_budget: FormulaDefinedNameStateBudget | None = None,
) -> WorkbookSnapshot:
    """Load one immutable workbook snapshot without evaluating its contents.

    A caller that has already inventoried a portfolio can provide the regular
    file identity it observed. The final descriptor must still identify that
    same file state, preventing a later pathname replacement or in-place
    mutation from widening the portfolio's inspected scope.
    """
    if max_dependency_edges < 1:
        raise WorkbookLoadError("max_dependency_edges must be at least 1.")
    if max_formula_defined_name_states < 1:
        raise WorkbookLoadError(
            "max_formula_defined_name_states must be at least 1."
        )
    dependency_edge_budget = _dependency_edge_budget or DependencyEdgeBudget(
        max_edges=max_dependency_edges
    )
    formula_defined_name_state_budget = (
        _formula_defined_name_state_budget
        or FormulaDefinedNameStateBudget(max_states=max_formula_defined_name_states)
    )

    reported_source = Path(path)
    if not reported_source.exists() or not reported_source.is_file():
        raise WorkbookLoadError(
            f"Workbook does not exist or is not a file: {reported_source}"
        )
    if reported_source.suffix.lower() not in _SUPPORTED_SUFFIXES:
        supported = ", ".join(sorted(_SUPPORTED_SUFFIXES))
        raise WorkbookLoadError(
            "Unsupported workbook type "
            f"{reported_source.suffix!r}; supported types: {supported}"
        )

    if expected_source_identity is None:
        source = _materialize_stable_workbook_source(reported_source)
    else:
        source = _materialize_stable_workbook_source(
            reported_source,
            expected_source_identity=expected_source_identity,
        )
    try:
        return _load_snapshot_from_stable_source(
            source,
            reported_source,
            dependency_edge_budget=dependency_edge_budget,
            formula_defined_name_state_budget=formula_defined_name_state_budget,
        )
    finally:
        _remove_stable_workbook_source(source)


def _load_snapshot_from_stable_source(
    source: Path,
    reported_source: Path,
    *,
    dependency_edge_budget: DependencyEdgeBudget,
    formula_defined_name_state_budget: FormulaDefinedNameStateBudget,
) -> WorkbookSnapshot:
    """Inspect only the private source copy materialized for one snapshot."""

    archive_members = _validate_ooxml_archive(source)
    _validate_ooxml_semantic_reader_resources(source, archive_members)

    workbook_tab_order_metadata = _workbook_tab_order_metadata(source)
    xlm_macro_metadata = _xlm_macro_metadata(source)
    xlm_automatic_macro_binding_metadata = _xlm_automatic_macro_binding_metadata(
        source
    )
    ribbon_customization_metadata = _ribbon_customization_metadata(source)
    office_web_addin_metadata = _office_web_addin_metadata(source)
    pivot_table_metadata = _pivot_table_metadata(source)
    slicer_timeline_metadata = _slicer_timeline_metadata(
        source,
        dict(pivot_table_metadata.slicer_timeline_pivot_cache_members_by_id),
    )
    power_pivot_data_model_metadata = _power_pivot_data_model_metadata(source)
    what_if_data_table_metadata = _what_if_data_table_metadata(source)
    scenario_manager_metadata = _scenario_manager_metadata(source)
    filter_visibility_metadata = _filter_visibility_metadata(source)
    ignored_error_metadata = _ignored_error_metadata(source)
    named_sheet_view_metadata = _named_sheet_view_metadata(source)
    custom_workbook_view_metadata = _custom_workbook_view_metadata(source)
    table_style_controls_metadata = _table_style_controls_metadata(source)
    shared_workbook_revision_metadata = _shared_workbook_revision_metadata(source)
    number_format_metadata = _number_format_metadata(source)
    font_metadata = _font_metadata(source)
    fill_metadata = _fill_metadata(source)
    alignment_metadata = _alignment_metadata(source)
    border_metadata = _border_metadata(source)
    worksheet_dimension_metadata = _worksheet_dimension_metadata(source)
    worksheet_display_metadata = _worksheet_display_metadata(source)
    worksheet_print_layout_metadata = _worksheet_print_layout_metadata(source)
    workbook_theme_metadata = _workbook_theme_metadata(source)
    formula_cached_result_metadata = _formula_cached_result_metadata(source)
    rich_text_run_metadata = _rich_text_run_metadata(source)
    cell_hyperlink_metadata = _cell_hyperlink_metadata(source)
    worksheet_sparkline_metadata = _worksheet_sparkline_metadata(source)
    xml_mapping_metadata = _xml_mapping_metadata(source)
    digital_signature_metadata = _digital_signature_metadata(source)
    rich_data_metadata = _rich_data_metadata(source)
    custom_data_store_metadata = _custom_data_store_metadata(source)
    legacy_comment_metadata = _legacy_comment_metadata(source)
    threaded_comment_metadata = _threaded_comment_metadata(source)
    worksheet_drawing_shape_metadata = _worksheet_drawing_shape_metadata(source)
    worksheet_image_metadata = _worksheet_image_metadata(source)
    chart_definition_metadata = _chart_definition_metadata(source)
    worksheet_embedded_control_metadata = _worksheet_embedded_control_metadata(source)
    external_relationship_metadata = _external_relationship_metadata(source)
    python_in_excel_metadata = _python_in_excel_metadata(source)
    reader_source, temporary_reader_source, reader_source_warnings = _openpyxl_safe_source(
        source
    )
    try:
        with warnings.catch_warnings(record=True) as caught_warnings:
            warnings.simplefilter("always")
            workbook = load_workbook(
                reader_source,
                read_only=False,
                data_only=False,
                keep_vba=False,
                keep_links=False,
                rich_text=False,
            )
    except (
        BadZipFile,
        InvalidFileException,
        IndexError,
        KeyError,
        OSError,
        TypeError,
        ValueError,
    ) as error:
        raise WorkbookLoadError(
            f"Could not read workbook {reported_source}: {error}"
        ) from error
    finally:
        if temporary_reader_source is not None:
            try:
                temporary_reader_source.unlink(missing_ok=True)
            except OSError:
                pass
    parser_warnings = {str(warning.message) for warning in caught_warnings}
    parser_warnings.update(reader_source_warnings)
    parser_warnings.update(xlm_macro_metadata.warnings)
    parser_warnings.update(xlm_automatic_macro_binding_metadata.warnings)
    parser_warnings.update(ribbon_customization_metadata.warnings)
    parser_warnings.update(office_web_addin_metadata.warnings)
    parser_warnings.update(pivot_table_metadata.warnings)
    parser_warnings.update(slicer_timeline_metadata.warnings)
    parser_warnings.update(power_pivot_data_model_metadata.warnings)
    parser_warnings.update(what_if_data_table_metadata.warnings)
    parser_warnings.update(scenario_manager_metadata.warnings)
    parser_warnings.update(filter_visibility_metadata.warnings)
    parser_warnings.update(ignored_error_metadata.warnings)
    parser_warnings.update(named_sheet_view_metadata.warnings)
    parser_warnings.update(custom_workbook_view_metadata.warnings)
    parser_warnings.update(table_style_controls_metadata.warnings)
    parser_warnings.update(shared_workbook_revision_metadata.warnings)
    parser_warnings.update(number_format_metadata.warnings)
    parser_warnings.update(font_metadata.warnings)
    parser_warnings.update(fill_metadata.warnings)
    parser_warnings.update(alignment_metadata.warnings)
    parser_warnings.update(border_metadata.warnings)
    parser_warnings.update(worksheet_dimension_metadata.warnings)
    parser_warnings.update(worksheet_display_metadata.warnings)
    parser_warnings.update(worksheet_print_layout_metadata.warnings)
    parser_warnings.update(workbook_theme_metadata.warnings)
    parser_warnings.update(formula_cached_result_metadata.warnings)
    parser_warnings.update(rich_text_run_metadata.warnings)
    parser_warnings.update(cell_hyperlink_metadata.warnings)
    parser_warnings.update(worksheet_sparkline_metadata.warnings)
    parser_warnings.update(xml_mapping_metadata.warnings)
    parser_warnings.update(digital_signature_metadata.warnings)
    parser_warnings.update(rich_data_metadata.warnings)
    parser_warnings.update(custom_data_store_metadata.warnings)
    parser_warnings.update(legacy_comment_metadata.warnings)
    parser_warnings.update(threaded_comment_metadata.warnings)
    parser_warnings.update(worksheet_drawing_shape_metadata.warnings)
    parser_warnings.update(worksheet_image_metadata.warnings)
    parser_warnings.update(chart_definition_metadata.warnings)
    parser_warnings.update(worksheet_embedded_control_metadata.warnings)
    parser_warnings.update(external_relationship_metadata.warnings)
    parser_warnings.update(python_in_excel_metadata.warnings)
    parser_warnings.update(workbook_tab_order_metadata.warnings)
    has_array_formulas = any(
        _is_array_formula(cell)
        for worksheet in workbook.worksheets
        for cell in worksheet._cells.values()  # noqa: SLF001 - sparse workbook safety
    )
    if has_array_formulas:
        array_formula_classification = _classify_array_formulas(
            workbook, _array_formula_metadata(source)
        )
    else:
        array_formula_classification = _ArrayFormulaClassification(
            kinds={},
            refs={},
            legacy_ranges=(),
            dynamic_cells=set(),
            dynamic_ranges=(),
            unclassified_cells=set(),
            metadata_complete=True,
            metadata_coverage_signature=None,
            warnings=(),
        )
    parser_warnings.update(array_formula_classification.warnings)
    conditional_formatting_metadata = _conditional_formatting_metadata(source)
    parser_warnings.update(conditional_formatting_metadata.warnings)
    protection_metadata = _protection_metadata(source)
    parser_warnings.update(protection_metadata.warnings)
    external_data_metadata = _external_data_metadata(
        source,
        power_query_item_members=custom_data_store_metadata.power_query_item_members,
    )
    parser_warnings.update(external_data_metadata.warnings)

    sheets: dict[str, SheetSnapshot] = {}
    cells: dict[CellKey, CellSnapshot] = {}
